    fun getNickname(): String?
    fun isFavorite(peerID: String): Boolean
}

package com.bitchat.android.mesh

/**
 * Shared helpers for mesh packet handling.
 */
object MeshPacketUtils {
    /**
     * Convert hex string peer ID to binary data (8 bytes), matching iOS behavior.
     */
    fun hexStringToByteArray(hexString: String): ByteArray {
        val result = ByteArray(8) { 0 }
        var tempID = hexString
        var index = 0

        while (tempID.length >= 2 && index < 8) {
            val hexByte = tempID.substring(0, 2)
            val byte = hexByte.toIntOrNull(16)?.toByte()
            if (byte != null) {
                result[index] = byte
            }
            tempID = tempID.substring(2)
            index++
        }
        return result
    }

    /**
     * Hash payloads to a stable hex ID for transfer tracking.
     */
    fun sha256Hex(bytes: ByteArray): String = try {
        val md = java.security.MessageDigest.getInstance("SHA-256")
        md.update(bytes)
        md.digest().joinToString("") { "%02x".format(it) }
    } catch (_: Exception) {
        bytes.size.toString(16)
    }
}

package com.bitchat.android.mesh

import android.util.Log
import com.bitchat.android.favorites.FavoriteControlMessage
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.BitchatMessageType
import com.bitchat.android.model.AuthenticatedPeerState
import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.sync.PacketIdUtil
import com.bitchat.android.util.toHexString
import com.bitchat.android.features.voice.LiveVoiceManager
import com.bitchat.android.features.voice.LiveVoiceScope
import kotlinx.coroutines.*
import java.util.*

sealed class AnnounceHandlingResult {
    data class Accepted(val isFirst: Boolean) : AnnounceHandlingResult()
    object Rejected : AnnounceHandlingResult()
}

/**
 * Handles processing of different message types
 * Extracted from BluetoothMeshService for better separation of concerns
 */
class MessageHandler(private val myPeerID: String, private val appContext: android.content.Context) {

    companion object {
        private const val TAG = "MessageHandler"
        private const val ANNOUNCE_CLOCK_SKEW_TOLERANCE_MS = 10 * 60 * 1000L
        private const val MAX_CONSECUTIVE_DECRYPT_FAILURES = 3
    }

    // Delegate for callbacks
    var delegate: MessageHandlerDelegate? = null

    // Reference to PacketProcessor for recursive packet handling
    var packetProcessor: PacketProcessor? = null

    // Coroutines
    private val handlerScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    // Consecutive decrypt failures per peer; only signature-verified packets reach this path,
    // so repeated failures mean the established session is stale (peer re-handshaked elsewhere).
    private val consecutiveDecryptFailures = java.util.concurrent.ConcurrentHashMap<String, Int>()

    /**
     * Handle Noise encrypted transport message - SIMPLIFIED iOS-compatible version
     * Uses NoisePayloadType system exactly like iOS SimplifiedBluetoothService
     *
     * Returns false when the payload could not be decrypted, so callers can treat the
     * packet as not liveness-proving (no lastSeen refresh, no relay).
     */
    suspend fun handleNoiseEncrypted(routed: RoutedPacket): Boolean {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        // Skip our own messages
        if (peerID == myPeerID) return true

        // Check if this message is for us
        val recipientID = packet.recipientID?.toHexString()
        if (recipientID != myPeerID) {
            return true
        }

        try {
            // Decrypt the message using the Noise service
            val decryption = delegate?.decryptFromPeer(packet.payload, peerID)
            if (decryption == null) {
                Log.w(TAG, "Failed to decrypt Noise message from $peerID - may need handshake")
                registerDecryptFailure(peerID)
                return false
            }
            consecutiveDecryptFailures.remove(peerID)
            val decryptedData = decryption.plaintext

            if (decryptedData.isEmpty()) {
                Log.w(TAG, "Decrypted data is empty from $peerID")
                return true
            }

            val noisePayload = com.bitchat.android.model.NoisePayload.decode(decryptedData)
            if (noisePayload == null) {
                Log.w(TAG, "Failed to parse NoisePayload from $peerID")
                return true
            }

            when (noisePayload.type) {
                com.bitchat.android.model.NoisePayloadType.PRIVATE_MESSAGE -> {
                    // Decode TLV private message exactly like iOS
                    val privateMessage = com.bitchat.android.model.PrivateMessagePacket.decode(noisePayload.data)
                    if (privateMessage != null) {
                        // Handle favorite/unfavorite notifications embedded as PMs
                        val pmContent = privateMessage.content
                        if (FavoriteControlMessage.parse(pmContent) != null) {
                            handleFavoriteNotificationFromMesh(pmContent, peerID)
                            // Acknowledge delivery for UX parity
                            sendDeliveryAck(privateMessage.messageID, peerID)
                            return true
                        }

                        // Create BitchatMessage - preserve source packet timestamp
                        val message = BitchatMessage(
                            id = privateMessage.messageID,
                            sender = delegate?.getPeerNickname(peerID) ?: "Unknown",
                            content = privateMessage.content,
                            timestamp = java.util.Date(packet.timestamp.toLong()),
                            isRelay = false,
                            originalSender = null,
                            isPrivate = true,
                            recipientNickname = delegate?.getMyNickname(),
                            senderPeerID = peerID,
                            mentions = null
                        )

                        // Notify delegate
                        delegate?.onMessageReceived(message)

                        // Send delivery ACK exactly like iOS
                        sendDeliveryAck(privateMessage.messageID, peerID)
                    }
                }

                com.bitchat.android.model.NoisePayloadType.FILE_TRANSFER -> {
                    // Handle encrypted file transfer; generate unique message ID
                    val file = com.bitchat.android.model.BitchatFilePacket.decode(noisePayload.data)
                    if (file != null) {
                        Log.d(TAG, "Encrypted file from $peerID: ${file.fileSize} bytes")
                        val uniqueMsgId = java.util.UUID.randomUUID().toString().uppercase()
                        val savedPath = com.bitchat.android.features.file.FileUtils.saveIncomingFile(appContext, file)
                        val message = BitchatMessage(
                            id = uniqueMsgId,
                            sender = delegate?.getPeerNickname(peerID) ?: "Unknown",
                            content = savedPath,
                            type = com.bitchat.android.features.file.FileUtils.messageTypeForMime(file.mimeType),
                            timestamp = java.util.Date(packet.timestamp.toLong()),
                            isRelay = false,
                            isPrivate = true,
                            recipientNickname = delegate?.getMyNickname(),
                            senderPeerID = peerID
                        )

                        if (!LiveVoiceManager.getInstance(appContext).absorbFinalizedVoiceNote(message)) {
                            delegate?.onMessageReceived(message)
                        }

                        // Send delivery ACK with generated message ID
                        sendDeliveryAck(uniqueMsgId, peerID)
                    } else {
                        Log.w(TAG, "Failed to decode encrypted file transfer from $peerID")
                    }
                }

                com.bitchat.android.model.NoisePayloadType.VOICE_FRAME -> {
                    return LiveVoiceManager.getInstance(appContext).handleFrame(
                        peerID = peerID,
                        nickname = delegate?.getPeerNickname(peerID) ?: peerID,
                        scope = LiveVoiceScope.DIRECT_MESSAGE,
                        payload = noisePayload.data,
                        timestampMs = packet.timestamp.toLong()
                    )
                }

                com.bitchat.android.model.NoisePayloadType.PEER_STATE -> {
                    val authenticatedState = AuthenticatedPeerState.decode(noisePayload.data)
                    if (authenticatedState == null) {
                        Log.w(TAG, "Dropping malformed authenticated peer state from ${peerID.take(8)}")
                    } else {
                        delegate?.onAuthenticatedPeerStateReceived(
                            peerID,
                            authenticatedState,
                            decryption.authenticatedSession
                        )
                    }
                }

                com.bitchat.android.model.NoisePayloadType.DELIVERED -> {
                    // Handle delivery ACK exactly like iOS
                    val messageID = String(noisePayload.data, Charsets.UTF_8)
                    Log.d(TAG, "Delivery ACK from $peerID for $messageID")

                    // Simplified: Call delegate with messageID and peerID directly
                    delegate?.onDeliveryAckReceived(messageID, peerID)
                }

                com.bitchat.android.model.NoisePayloadType.READ_RECEIPT -> {
                    // Handle read receipt exactly like iOS
                    val messageID = String(noisePayload.data, Charsets.UTF_8)
                    Log.d(TAG, "Read receipt from $peerID for $messageID")

                    // Simplified: Call delegate with messageID and peerID directly
                    delegate?.onReadReceiptReceived(messageID, peerID)
                }
                com.bitchat.android.model.NoisePayloadType.VERIFY_CHALLENGE -> {
                    delegate?.onVerifyChallengeReceived(peerID, noisePayload.data, packet.timestamp.toLong())
                }
                com.bitchat.android.model.NoisePayloadType.VERIFY_RESPONSE -> {
                    delegate?.onVerifyResponseReceived(peerID, noisePayload.data, packet.timestamp.toLong())
                }
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error processing Noise encrypted message from $peerID: ${e.message}")
        }
        return true
    }

    /**
     * Count consecutive decrypt failures from a signature-verified peer that we still hold an
     * established session for. After repeated failures the session is stale (the peer completed
     * a new handshake elsewhere), so destroy it and start a fresh handshake; the peer's side
     * will finish via the responder-candidate path and evict its own stale session.
     */
    private fun registerDecryptFailure(peerID: String) {
        if (peerID == "unknown" || peerID == myPeerID) return
        if (delegate?.hasNoiseSession(peerID) != true) return
        val failures = (consecutiveDecryptFailures[peerID] ?: 0) + 1
        if (failures >= MAX_CONSECUTIVE_DECRYPT_FAILURES) {
            consecutiveDecryptFailures.remove(peerID)
            Log.w(TAG, "Noise session with $peerID stale after $failures decrypt failures; resetting and re-handshaking")
            try { delegate?.removeNoiseSession(peerID) } catch (e: Exception) {
                Log.w(TAG, "Failed to reset Noise session for $peerID: ${e.message}")
            }
            try { delegate?.initiateNoiseHandshake(peerID) } catch (e: Exception) {
                Log.w(TAG, "Failed to re-initiate handshake with $peerID: ${e.message}")
            }
        } else {
            consecutiveDecryptFailures[peerID] = failures
        }
    }

    /**
     * Send delivery ACK for a received private message - exactly like iOS
     */
    private suspend fun sendDeliveryAck(messageID: String, senderPeerID: String) {
        try {
            // Create ACK payload: [type byte] + [message ID] - exactly like iOS
            val ackPayload = com.bitchat.android.model.NoisePayload(
                type = com.bitchat.android.model.NoisePayloadType.DELIVERED,
                data = messageID.toByteArray(Charsets.UTF_8)
            )

            // Encrypt the payload
            val encryptedPayload = delegate?.encryptForPeer(ackPayload.encode(), senderPeerID)
            if (encryptedPayload == null) {
                Log.w(TAG, "Failed to encrypt delivery ACK for $senderPeerID")
                return
            }

            // Create NOISE_ENCRYPTED packet exactly like iOS
                val packet = BitchatPacket(
                    version = 1u,
                    type = MessageType.NOISE_ENCRYPTED.value,
                    senderID = hexStringToByteArray(myPeerID),
                    recipientID = hexStringToByteArray(senderPeerID),
                    timestamp = System.currentTimeMillis().toULong(),
                    payload = encryptedPayload,
                    signature = null,
                    ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS // Same TTL as iOS messageTTL
                )

            delegate?.sendPacket(packet)

        } catch (e: Exception) {
            Log.e(TAG, "Failed to send delivery ACK to $senderPeerID: ${e.message}")
        }
    }

    /**
     * Handle announce message with TLV decoding and signature verification - exactly like iOS
     */
    suspend fun handleAnnounce(routed: RoutedPacket): Boolean {
        return (handleAnnounceWithResult(routed) as? AnnounceHandlingResult.Accepted)?.isFirst ?: false
    }

    suspend fun handleAnnounceWithResult(routed: RoutedPacket): AnnounceHandlingResult {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        if (peerID == myPeerID) return AnnounceHandlingResult.Rejected

        // Peers use wall-clock packet timestamps; tolerate moderate device clock skew
        // during identity learning, or later signed messages cannot be verified.
        val now = System.currentTimeMillis()
        val clockSkewMs = kotlin.math.abs(now - packet.timestamp.toLong())
        if (clockSkewMs > ANNOUNCE_CLOCK_SKEW_TOLERANCE_MS) {
            Log.w(TAG, "Ignoring ANNOUNCE from ${peerID.take(8)} with excessive clock skew (${clockSkewMs}ms > ${ANNOUNCE_CLOCK_SKEW_TOLERANCE_MS}ms)")
            return AnnounceHandlingResult.Rejected
        }

        val announcement = AnnouncementIdentityValidator.verify(packet, peerID) { signature, data, key ->
            delegate?.verifyEd25519Signature(signature, data, key) ?: false
        }
        if (announcement == null) {
            Log.w(TAG, "Rejecting malformed, unbound, or invalidly signed ANNOUNCE from ${peerID.take(8)}")
            return AnnounceHandlingResult.Rejected
        }

        val persistedSigningKey = delegate?.getAuthenticatedSigningKey(announcement.noisePublicKey)
        if (persistedSigningKey != null &&
            !persistedSigningKey.contentEquals(announcement.signingPublicKey)
        ) {
            Log.w(TAG, "Rejecting ANNOUNCE Ed key that conflicts with authenticated peer state")
            return AnnounceHandlingResult.Rejected
        }

        var verified = true

        // Check for existing peer with different noise public key
        // If existing peer has a different noise public key, do not consider this verified
        val existingPeer = delegate?.getPeerInfo(peerID)

        if (existingPeer != null && existingPeer.noisePublicKey != null && !existingPeer.noisePublicKey!!.contentEquals(announcement.noisePublicKey)) {
            Log.w(TAG, "Announce key mismatch for ${peerID.take(8)} - keeping unverified")
            verified = false
        }

        if (
            existingPeer?.signingPublicKey != null &&
            !existingPeer.signingPublicKey!!.contentEquals(announcement.signingPublicKey)
        ) {
            Log.w(
                TAG,
                "Rejecting signing-key replacement for ${peerID.take(8)} without authenticated peer-state proof"
            )
            verified = false
        }

        // Require verified announce; ignore otherwise (no backward compatibility)
        if (!verified) {
            return AnnounceHandlingResult.Rejected
        }

        // Extract nickname and public keys from TLV data
        val nickname = announcement.nickname
        val noisePublicKey = announcement.noisePublicKey
        val signingPublicKey = announcement.signingPublicKey

        // Update peer info with verification status through new method
        val isFirstAnnounce = delegate?.updatePeerInfoFromVerifiedAnnouncement(
            peerID = peerID,
            nickname = nickname,
            noisePublicKey = noisePublicKey,
            signingPublicKey = signingPublicKey,
            isVerified = true,
            capabilities = announcement.capabilities
        ) ?: false

        // Update mesh graph from gossip neighbors (only if TLV present)
        try {
            val neighborsOrNull = com.bitchat.android.services.meshgraph.GossipTLV.decodeNeighborsFromAnnouncementPayload(packet.payload)
            com.bitchat.android.services.meshgraph.MeshGraphService.getInstance()
                .updateFromAnnouncement(peerID, nickname, neighborsOrNull, packet.timestamp)
        } catch (_: Exception) { }

        Log.d(TAG, "Verified announce from $peerID (${announcement.nickname})")
        return AnnounceHandlingResult.Accepted(isFirstAnnounce)
    }

    /**
     * Handle Noise handshake - SIMPLIFIED iOS-compatible version
     * Single handshake type (0x10) with response determined by payload analysis
     */
    suspend fun handleNoiseHandshake(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        // Skip our own handshake messages
        if (peerID == myPeerID) return

        // Check if handshake is addressed to us
        val recipientID = packet.recipientID?.toHexString()
        if (recipientID != myPeerID) {
            return
        }

        try {
            // Process handshake message through delegate (simplified approach)
            val response = delegate?.processNoiseHandshakeMessage(packet.payload, peerID)

            if (response != null) {
                // Send response using same packet type (simplified iOS approach)
                val responsePacket = BitchatPacket(
                    version = 1u,
                    type = MessageType.NOISE_HANDSHAKE.value,
                    senderID = hexStringToByteArray(myPeerID),
                    recipientID = hexStringToByteArray(peerID),
                    timestamp = System.currentTimeMillis().toULong(),
                    payload = response,
                    signature = null,
                    ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS // Same TTL as iOS
                )

                delegate?.sendPacket(responsePacket)
            }

        } catch (e: Exception) {
            Log.e(TAG, "Failed to process Noise handshake from $peerID: ${e.message}")
        }
    }

    /**
     * Handle broadcast or private message
     */
    suspend fun handleMessage(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"
        if (peerID == myPeerID) return
        val senderNickname = delegate?.getPeerNickname(peerID)
        if (senderNickname != null) {
            Log.d(TAG, "Received message from $senderNickname")
            delegate?.updatePeerNickname(peerID, senderNickname)
        }

        val recipientID = packet.recipientID?.takeIf { !it.contentEquals(delegate?.getBroadcastRecipient()) }

        if (recipientID == null) {
            // BROADCAST MESSAGE
            handleBroadcastMessage(routed)
        } else if (recipientID.toHexString() == myPeerID) {
            // PRIVATE MESSAGE FOR US
            handlePrivateMessage(packet, peerID)
        }
        // Message relay is now handled by centralized PacketRelayManager
    }

    /** Validate and ingest an ephemeral public push-to-talk frame. */
    fun handlePublicVoiceFrame(routed: RoutedPacket): Boolean {
        val packet = routed.packet
        val peerID = routed.peerID ?: return false
        if (peerID == myPeerID) return true
        val recipient = packet.recipientID
        if (recipient != null && !recipient.contentEquals(delegate?.getBroadcastRecipient())) return false
        if (packet.timestamp > Long.MAX_VALUE.toULong()) return false
        val ageMs = System.currentTimeMillis() - packet.timestamp.toLong()
        if (ageMs !in -30_000L..30_000L) return false
        val peerInfo = delegate?.getPeerInfo(peerID)
        if (peerInfo == null || !peerInfo.isVerifiedNickname) return false
        return LiveVoiceManager.getInstance(appContext).handleFrame(
            peerID = peerID,
            nickname = delegate?.getPeerNickname(peerID) ?: peerID,
            scope = LiveVoiceScope.PUBLIC_MESH,
            payload = packet.payload,
            timestampMs = packet.timestamp.toLong()
        )
    }

    /**
     * Handle broadcast message with verification enforcement
     */
    private suspend fun handleBroadcastMessage(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        // Enforce: only accept public messages from verified peers we know
        val peerInfo = delegate?.getPeerInfo(peerID)
        if (peerInfo == null || !peerInfo.isVerifiedNickname) {
            Log.w(TAG, "Dropping public message from unverified peer ${peerID.take(8)}")
            return
        }

        try {
            // Try file packet first (voice, image, etc.) and log outcome for FILE_TRANSFER
            val isFileTransfer = com.bitchat.android.protocol.MessageType.fromValue(packet.type) == com.bitchat.android.protocol.MessageType.FILE_TRANSFER
            val file = com.bitchat.android.model.BitchatFilePacket.decode(packet.payload)
            if (file != null) {

                val savedPath = com.bitchat.android.features.file.FileUtils.saveIncomingFile(appContext, file)
                val message = BitchatMessage(
                    id = PacketIdUtil.computeIdHex(packet).uppercase(),
                    sender = delegate?.getPeerNickname(peerID) ?: "unknown",
                    content = savedPath,
                    type = com.bitchat.android.features.file.FileUtils.messageTypeForMime(file.mimeType),
                    senderPeerID = peerID,
                    timestamp = Date(packet.timestamp.toLong())
                )
                if (!LiveVoiceManager.getInstance(appContext).absorbFinalizedVoiceNote(message)) {
                    delegate?.onMessageReceived(message)
                }
                return
            } else if (isFileTransfer) {
                Log.w(TAG, "FILE_TRANSFER decode failed (broadcast) from ${peerID.take(8)}")
            }

            // Fallback: plain text
            val message = BitchatMessage(
                id = PacketIdUtil.computeIdHex(packet).uppercase(),
                sender = delegate?.getPeerNickname(peerID) ?: "unknown",
                content = String(packet.payload, Charsets.UTF_8),
                senderPeerID = peerID,
                timestamp = Date(packet.timestamp.toLong())
            )
            delegate?.onMessageReceived(message)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to process broadcast message: ${e.message}")
        }
    }

    /**
     * Handle (decrypted) private message addressed to us
     */
    private suspend fun handlePrivateMessage(packet: BitchatPacket, peerID: String) {
        try {
            val isFileTransfer = com.bitchat.android.protocol.MessageType.fromValue(packet.type) ==
                com.bitchat.android.protocol.MessageType.FILE_TRANSFER
            val signatureIsValid = packet.signature != null &&
                delegate?.verifySignature(packet, peerID) == true

            // Migration fallback is visible to relays, so sender authenticity
            // is mandatory. Never accept an unsigned directed raw file.
            if (isFileTransfer && !signatureIsValid) {
                Log.w(TAG, "Unsigned or invalid signed private file from $peerID")
                return
            }

            // Preserve prior behavior for other directed packet types: verify
            // a signature whenever one is present.
            if (!isFileTransfer && packet.signature != null && !signatureIsValid) {
                Log.w(TAG, "Invalid signature for private message from $peerID")
                return
            }

            // Try file packet first (voice, image, etc.) and log outcome for FILE_TRANSFER
            val file = com.bitchat.android.model.BitchatFilePacket.decode(packet.payload)
            if (file != null) {

                val savedPath = com.bitchat.android.features.file.FileUtils.saveIncomingFile(appContext, file)
                val message = BitchatMessage(
                    id = java.util.UUID.randomUUID().toString().uppercase(),
                    sender = delegate?.getPeerNickname(peerID) ?: "unknown",
                    content = savedPath,
                    type = com.bitchat.android.features.file.FileUtils.messageTypeForMime(file.mimeType),
                    senderPeerID = peerID,
                    timestamp = Date(packet.timestamp.toLong()),
                    isPrivate = true,
                    recipientNickname = delegate?.getMyNickname()
                )
                Log.d(TAG, "📄 Saved incoming file to $savedPath")
                if (!LiveVoiceManager.getInstance(appContext).absorbFinalizedVoiceNote(message)) {
                    delegate?.onMessageReceived(message)
                }
                return
            } else if (isFileTransfer) {
                Log.w(TAG, "⚠️ FILE_TRANSFER decode failed (private) from ${peerID.take(8)} payloadSize=${packet.payload.size}")
            }

            // Fallback: plain text
            val message = BitchatMessage(
                sender = delegate?.getPeerNickname(peerID) ?: "unknown",
                content = String(packet.payload, Charsets.UTF_8),
                senderPeerID = peerID,
                timestamp = Date(packet.timestamp.toLong())
            )
            delegate?.onMessageReceived(message)

        } catch (e: Exception) {
            Log.e(TAG, "Failed to process private message from $peerID: ${e.message}")
        }
    }



    /**
     * Handle leave message
     */
    suspend fun handleLeave(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"
        val content = String(packet.payload, Charsets.UTF_8)

        if (content.startsWith("#")) {
            // Channel leave
            delegate?.onChannelLeave(content, peerID)
        } else {
            // Peer disconnect
            delegate?.removePeer(peerID)
        }

        // Leave message relay is now handled by centralized PacketRelayManager
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Message Handler Debug Info ===")
            appendLine("Handler Scope Active: ${handlerScope.isActive}")
            appendLine("My Peer ID: $myPeerID")
        }
    }

    /**
     * Convert hex string peer ID to binary data (8 bytes) - same as iOS implementation
     */
    private fun hexStringToByteArray(hexString: String): ByteArray {
        val result = ByteArray(8) { 0 } // Initialize with zeros, exactly 8 bytes
        var tempID = hexString
        var index = 0

        while (tempID.length >= 2 && index < 8) {
            val hexByte = tempID.substring(0, 2)
            val byte = hexByte.toIntOrNull(16)?.toByte()
            if (byte != null) {
                result[index] = byte
            }
            tempID = tempID.substring(2)
            index++
        }

        return result
    }

    /**
     * Shutdown the handler
     */
    fun shutdown() {
        handlerScope.cancel()
    }

    /**
     * Handle favorite/unfavorite notification received over mesh as a private message.
     * Content format: "[FAVORITED]:npub..." or "[UNFAVORITED]:npub..."
     */
    private fun handleFavoriteNotificationFromMesh(content: String, fromPeerID: String) {
        try {
            val control = FavoriteControlMessage.parse(content) ?: return

            val peerInfo = delegate?.getPeerInfo(fromPeerID)
            val noiseKey = peerInfo?.noisePublicKey
            if (noiseKey != null) {
                com.bitchat.android.favorites.FavoritesPersistenceService.shared.updatePeerFavoritedUs(noiseKey, control.isFavorite)
                if (control.npub != null) {
                    com.bitchat.android.favorites.FavoritesPersistenceService.shared.updateNostrPublicKey(noiseKey, control.npub)
                    com.bitchat.android.favorites.FavoritesPersistenceService.shared.updateNostrPublicKeyForPeerID(fromPeerID, control.npub)
                }

                val rel = com.bitchat.android.favorites.FavoritesPersistenceService.shared.getFavoriteStatus(noiseKey)
                val guidance = if (control.isFavorite) {
                    if (rel?.isFavorite == true) {
                        " — mutual! You can continue DMs via Nostr when out of mesh."
                    } else {
                        " — favorite back to continue DMs later."
                    }
                } else {
                    ". DMs over Nostr will pause unless you both favorite again."
                }

                val action = if (control.isFavorite) "favorited" else "unfavorited"
                val notice = "${peerInfo.nickname} $action you$guidance"
                val sys = com.bitchat.android.model.BitchatMessage(
                    sender = "system",
                    content = notice,
                    timestamp = java.util.Date(),
                    isRelay = false
                )
                delegate?.onMessageReceived(sys)

                // Mirror the notice into the private conversation so it's visible while chatting
                try {
                    val conversationID = com.bitchat.android.services.ContactDirectory
                        .canonicalConversationId(fromPeerID)
                    val sysPrivate = com.bitchat.android.model.BitchatMessage(
                        sender = "system",
                        content = notice,
                        timestamp = java.util.Date(),
                        isRelay = false,
                        isPrivate = true,
                        senderPeerID = conversationID
                    )
                    delegate?.onMessageReceived(sysPrivate)
                } catch (_: Exception) {
                    // Best-effort; public notice already delivered
                }
            }
        } catch (_: Exception) {
            // Best-effort; ignore errors
        }
    }
}

/**
 * Delegate interface for message handler callbacks
 */
interface MessageHandlerDelegate {
    // Peer management
    fun addOrUpdatePeer(peerID: String, nickname: String): Boolean
    fun removePeer(peerID: String)
    fun updatePeerNickname(peerID: String, nickname: String)
    fun getPeerNickname(peerID: String): String?
    fun getNetworkSize(): Int
    fun getMyNickname(): String?
    fun getPeerInfo(peerID: String): PeerInfo?
    fun updatePeerInfoFromVerifiedAnnouncement(
        peerID: String,
        nickname: String,
        noisePublicKey: ByteArray,
        signingPublicKey: ByteArray,
        isVerified: Boolean,
        capabilities: com.bitchat.android.model.PeerCapabilities? = null
    ): Boolean

    // Packet operations
    fun sendPacket(packet: BitchatPacket)
    fun relayPacket(routed: RoutedPacket)
    fun getBroadcastRecipient(): ByteArray

    // Cryptographic operations
    fun verifySignature(packet: BitchatPacket, peerID: String): Boolean
    fun encryptForPeer(data: ByteArray, recipientPeerID: String): ByteArray?
    fun decryptFromPeer(
        encryptedData: ByteArray,
        senderPeerID: String
    ): com.bitchat.android.noise.NoiseDecryptionResult?
    fun verifyEd25519Signature(signature: ByteArray, data: ByteArray, publicKey: ByteArray): Boolean
    fun getAuthenticatedSigningKey(noisePublicKey: ByteArray): ByteArray? = null

    // Noise protocol operations
    fun hasNoiseSession(peerID: String): Boolean
    fun initiateNoiseHandshake(peerID: String)
    fun removeNoiseSession(peerID: String) {}
    fun processNoiseHandshakeMessage(payload: ByteArray, peerID: String): ByteArray?
    fun onAuthenticatedPeerStateReceived(
        peerID: String,
        state: AuthenticatedPeerState,
        authenticatedSession: com.bitchat.android.noise.AuthenticatedNoiseSession
    ) {}

    // Message operations
    fun decryptChannelMessage(encryptedContent: ByteArray, channel: String): String?

    // Callbacks
    fun onMessageReceived(message: BitchatMessage)
    fun onChannelLeave(channel: String, fromPeer: String)
    fun onDeliveryAckReceived(messageID: String, peerID: String)
    fun onReadReceiptReceived(messageID: String, peerID: String)
    fun onVerifyChallengeReceived(peerID: String, payload: ByteArray, timestampMs: Long)
    fun onVerifyResponseReceived(peerID: String, payload: ByteArray, timestampMs: Long)
}

package com.bitchat.android.mesh

import android.util.Log
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.model.RoutedPacket
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.channels.actor

/**
 * Processes incoming packets and routes them to appropriate handlers
 * 
 * Per-peer packet serialization using Kotlin coroutine actors
 * Prevents race condition where multiple threads process packets
 * from the same peer simultaneously, causing session management conflicts.
 */
class PacketProcessor(private val myPeerID: String) {
    private val debugManager by lazy { try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance() } catch (e: Exception) { null } }

    companion object {
        private const val TAG = "PacketProcessor"
    }

    // Delegate for callbacks
    var delegate: PacketProcessorDelegate? = null

    // Helper function to format peer ID with nickname for logging
    private fun formatPeerForLog(peerID: String): String {
        val nickname = delegate?.getPeerNickname(peerID)
        return if (nickname != null) "$peerID ($nickname)" else peerID
    }

    // Packet relay manager for centralized relay decisions
    private val packetRelayManager = PacketRelayManager(myPeerID)

    // Coroutines
    private val processorScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    // Per-peer actors to serialize packet processing
    // Each peer gets its own actor that processes packets sequentially
    // This prevents race conditions in session management
    private val peerActors = mutableMapOf<String, CompletableDeferred<Unit>>()

    @OptIn(ObsoleteCoroutinesApi::class)
    private fun getOrCreateActorForPeer(peerID: String) = processorScope.actor<RoutedPacket>(
        capacity = Channel.UNLIMITED
    ) {
        for (packet in channel) {
            handleReceivedPacket(packet)
        }
    }

    // Cache actors to reuse them
    private val actors = mutableMapOf<String, kotlinx.coroutines.channels.SendChannel<RoutedPacket>>()

    init {
        // Set up the packet relay manager delegate immediately
        setupRelayManager()
    }

    /**
     * Process received packet - main entry point for all incoming packets
     * SURGICAL FIX: Route to per-peer actor for serialized processing
     */
    fun processPacket(routed: RoutedPacket) {
        val peerID = routed.peerID

        if (peerID == null) {
            Log.w(TAG, "Received packet with no peer ID, skipping")
            return
        }

        // Get or create actor for this peer
        val actor = actors.getOrPut(peerID) { getOrCreateActorForPeer(peerID) }

        // Send packet to peer's dedicated actor for serialized processing
        processorScope.launch {
            try {
                actor.send(routed)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to send packet to actor for ${formatPeerForLog(peerID)}: ${e.message}")
                // Fallback to direct processing if actor fails
                handleReceivedPacket(routed)
            }
        }
    }

    /**
     * Set up the packet relay manager with its delegate
     */
    fun setupRelayManager() {
        packetRelayManager.delegate = object : PacketRelayManagerDelegate {
            override fun getNetworkSize(): Int {
                return delegate?.getNetworkSize() ?: 1
            }

            override fun getBroadcastRecipient(): ByteArray {
                return delegate?.getBroadcastRecipient() ?: ByteArray(0)
            }

            override fun broadcastPacket(routed: RoutedPacket) {
                delegate?.relayPacket(routed)
            }
            override fun sendToPeer(peerID: String, routed: RoutedPacket): Boolean {
                return delegate?.sendToPeer(peerID, routed) ?: false
            }
        }
    }

    /**
     * Handle received packet - core protocol logic (exact same as iOS)
     */
    private suspend fun handleReceivedPacket(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        // Basic validation and security checks
        if (!delegate?.validatePacketSecurity(packet, peerID)!!) {
            return
        }

        var validPacket = true
        val messageType = MessageType.fromValue(packet.type)
        // Verbose logging to debug manager (and chat via ChatViewModel observer)
        try {
            val mt = messageType?.name ?: packet.type.toString()
            val routeDevice = routed.relayAddress
            val nick = delegate?.getPeerNickname(peerID)
            debugManager?.logIncomingPacket(peerID, nick, mt, routeDevice)
        } catch (_: Exception) { }


        // Handle public packet types (no address check needed)
        when (messageType) {
            MessageType.ANNOUNCE -> validPacket = handleAnnounce(routed)
            MessageType.MESSAGE -> handleMessage(routed)
            MessageType.FILE_TRANSFER -> handleMessage(routed) // treat same routing path; parsing happens in handler
            MessageType.VOICE_FRAME -> validPacket = delegate?.handleVoiceFrame(routed) ?: false
            MessageType.LEAVE -> handleLeave(routed)
            MessageType.FRAGMENT -> handleFragment(routed)
            MessageType.REQUEST_SYNC -> handleRequestSync(routed)
            else -> {
                // Handle private packet types (address check required)
                if (packetRelayManager.isPacketAddressedToMe(packet)) {
                    when (messageType) {
                        MessageType.NOISE_HANDSHAKE -> validPacket = handleNoiseHandshake(routed)
                        MessageType.NOISE_ENCRYPTED -> validPacket = handleNoiseEncrypted(routed)
                        MessageType.FILE_TRANSFER -> handleMessage(routed)
                        else -> {
                            validPacket = false
                            Log.w(TAG, "Unknown message type: ${packet.type}")
                        }
                    }
                } else {
                    // Not addressed to us; only relay handling below applies
                }
            }
        }

        // Update last seen timestamp
        if (validPacket) {
            delegate?.updatePeerLastSeen(peerID)

            // CENTRALIZED RELAY LOGIC: Handle relay decisions for all packets not addressed to us
            packetRelayManager.handlePacketRelay(routed)
        }
    }

    /**
     * Handle Noise handshake message - SIMPLIFIED iOS-compatible version
     */
    private suspend fun handleNoiseHandshake(routed: RoutedPacket): Boolean {
        return delegate?.handleNoiseHandshake(routed) ?: false
    }

    /**
     * Handle Noise encrypted transport message
     * Returns false when decryption fails so undecryptable packets do not prove liveness.
     */
    private suspend fun handleNoiseEncrypted(routed: RoutedPacket): Boolean {
        return delegate?.handleNoiseEncrypted(routed) ?: false
    }

    /**
     * Handle announce message
     */
    private suspend fun handleAnnounce(routed: RoutedPacket): Boolean {
        return delegate?.handleAnnounce(routed) ?: false
    }

    /**
     * Handle regular message
     */
    private suspend fun handleMessage(routed: RoutedPacket) {
        delegate?.handleMessage(routed)
    }

    /**
     * Handle leave message
     */
    private suspend fun handleLeave(routed: RoutedPacket) {
        delegate?.handleLeave(routed)
    }

    /**
     * Handle message fragments
     */
    private suspend fun handleFragment(routed: RoutedPacket) {
        val reassembledPacket = delegate?.handleFragment(routed.packet)
        if (reassembledPacket != null) {
            handleReceivedPacket(
                RoutedPacket(
                    packet = reassembledPacket,
                    peerID = routed.peerID,
                    relayAddress = routed.relayAddress,
                    ingressLinkID = routed.ingressLinkID
                )
            )
        }

        // Fragment relay is now handled by centralized PacketRelayManager
    }

    /**
     * Handle REQUEST_SYNC packets (public, TTL=1)
     */
    private suspend fun handleRequestSync(routed: RoutedPacket) {
        delegate?.handleRequestSync(routed)
    }

    /**
     * Handle delivery acknowledgment
     */
//    private suspend fun handleDeliveryAck(routed: RoutedPacket) {
//        val peerID = routed.peerID ?: "unknown"
//        Log.d(TAG, "Processing delivery ACK from ${formatPeerForLog(peerID)}")
//        delegate?.handleDeliveryAck(routed)
//    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Packet Processor Debug Info ===")
            appendLine("Processor Scope Active: ${processorScope.isActive}")
            appendLine("Active Peer Actors: ${actors.size}")
            appendLine("My Peer ID: $myPeerID")

            if (actors.isNotEmpty()) {
                appendLine("Peer Actors:")
                actors.keys.forEach { peerID ->
                    appendLine("  - $peerID")
                }
            }
        }
    }

    /**
     * Shutdown the processor and all peer actors
     */
    fun shutdown() {
        Log.d(TAG, "Shutting down PacketProcessor and ${actors.size} peer actors")

        // Close all peer actors gracefully
        actors.values.forEach { actor ->
            actor.close()
        }
        actors.clear()

        // Shutdown the relay manager
        packetRelayManager.shutdown()

        // Cancel the main scope
        processorScope.cancel()
    }
}

/**
 * Delegate interface for packet processor callbacks
 */
interface PacketProcessorDelegate {
    // Security validation
    fun validatePacketSecurity(packet: BitchatPacket, peerID: String): Boolean

    // Peer management
    fun updatePeerLastSeen(peerID: String)
    fun getPeerNickname(peerID: String): String?

    // Network information
    fun getNetworkSize(): Int
    fun getBroadcastRecipient(): ByteArray

    // Message type handlers
    fun handleNoiseHandshake(routed: RoutedPacket): Boolean
    fun handleNoiseEncrypted(routed: RoutedPacket): Boolean
    suspend fun handleAnnounce(routed: RoutedPacket): Boolean
    fun handleMessage(routed: RoutedPacket)
    fun handleVoiceFrame(routed: RoutedPacket): Boolean = false
    fun handleLeave(routed: RoutedPacket)
    fun handleFragment(packet: BitchatPacket): BitchatPacket?
    fun handleRequestSync(routed: RoutedPacket)

    // Communication
    fun sendAnnouncementToPeer(peerID: String)
    fun sendCachedMessages(peerID: String)
    fun relayPacket(routed: RoutedPacket)
    fun sendToPeer(peerID: String, routed: RoutedPacket): Boolean
}

package com.bitchat.android.mesh
import com.bitchat.android.protocol.MessageType

import android.util.Log
import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.util.toHexString
import kotlinx.coroutines.*
import kotlin.random.Random

/**
 * Centralized packet relay management
 * 
 * This class handles all relay decisions and logic for bitchat packets.
 * All packets that aren't specifically addressed to us get processed here.
 */
class PacketRelayManager(private val myPeerID: String) {
    private val debugManager by lazy { try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance() } catch (e: Exception) { null } }

    companion object {
        private const val TAG = "PacketRelayManager"
    }

    private fun isRelayEnabled(): Boolean = try {
        com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().packetRelayEnabled.value
    } catch (_: Exception) { true }

    // Logging moved to BluetoothPacketBroadcaster per actual transmission target

    // Delegate for callbacks
    var delegate: PacketRelayManagerDelegate? = null

    // Coroutines
    private val relayScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    /**
     * Main entry point for relay decisions
     * Only packets that aren't specifically addressed to us should be passed here
     */
    suspend fun handlePacketRelay(routed: RoutedPacket) {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        Log.d(TAG, "Evaluating relay for packet type ${packet.type} from ${peerID} (TTL: ${packet.ttl})")

        // Double-check this packet isn't addressed to us
        if (isPacketAddressedToMe(packet)) {
            Log.d(TAG, "Packet addressed to us, skipping relay")
            return
        }

        // Skip our own packets
        if (peerID == myPeerID) {
            Log.d(TAG, "Packet from ourselves, skipping relay")
            return
        }

        // Check TTL and decrement
        if (packet.ttl == 0u.toUByte()) {
            Log.d(TAG, "TTL expired, not relaying packet")
            return
        }

        // Decrement TTL by 1
        val networkSize = delegate?.getNetworkSize() ?: 1
        val decrementedTtl = (packet.ttl - 1u).toUByte()
        val voiceTtl = if (
            MessageType.fromValue(packet.type) == MessageType.VOICE_FRAME && networkSize > 6
        ) minOf(decrementedTtl, 5u.toUByte()) else decrementedTtl
        val relayPacket = packet.copy(ttl = voiceTtl)
        Log.d(TAG, "Decremented TTL from ${packet.ttl} to ${relayPacket.ttl}")
        if (MessageType.fromValue(packet.type) == MessageType.VOICE_FRAME) {
            delay(Random.nextLong(8L, 26L))
        }

        // Source-based routing: if route is set and includes us, try targeted next-hop forwarding
        val route = relayPacket.route
        if (!route.isNullOrEmpty()) {
            // Check for duplicate hops to prevent routing loops
            if (route.map { it.toHexString() }.toSet().size < route.size) {
                Log.w(TAG, "Packet with duplicate hops dropped")
                return
            }
            val myIdBytes = hexStringToPeerBytes(myPeerID)
            val index = route.indexOfFirst { it.contentEquals(myIdBytes) }
            if (index >= 0) {
                val nextHopIdHex: String? = run {
                    val nextIndex = index + 1
                    if (nextIndex < route.size) {
                        route[nextIndex].toHexString()
                    } else {
                        // We are the last intermediate; try final recipient as next hop
                        relayPacket.recipientID?.toHexString()
                    }
                }
                if (nextHopIdHex != null) {
                    val success = try { delegate?.sendToPeer(nextHopIdHex, RoutedPacket(relayPacket, peerID, routed.relayAddress)) } catch (_: Exception) { false } ?: false
                    if (success) {
                        Log.i(TAG, "📦 Source-route relay: ${peerID.take(8)} -> ${nextHopIdHex.take(8)} (type ${'$'}{packet.type}, TTL ${'$'}{relayPacket.ttl})")
                        return
                    } else {
                        Log.w(TAG, "Source-route next hop ${nextHopIdHex.take(8)} not directly connected; falling back to broadcast")
                    }
                }
            }
        }

        // Apply relay logic based on packet type and debug switch
        val shouldRelay = isRelayEnabled() && shouldRelayPacket(relayPacket, peerID)
        if (shouldRelay) {
            relayPacket(RoutedPacket(relayPacket, peerID, routed.relayAddress))
        } else {
            Log.d(TAG, "Relay decision: NOT relaying packet type ${packet.type}")
        }
    }

    /**
     * Check if a packet is specifically addressed to us
     */
    internal fun isPacketAddressedToMe(packet: BitchatPacket): Boolean {
        val recipientID = packet.recipientID

        // No recipient means broadcast (not addressed to us specifically)
        if (recipientID == null) {
            return false
        }

        // Check if it's a broadcast recipient
        val broadcastRecipient = delegate?.getBroadcastRecipient()
        if (broadcastRecipient != null && recipientID.contentEquals(broadcastRecipient)) {
            return false
        }

        // Check if recipient matches our peer ID
        val recipientIDString = recipientID.toHexString()
        return recipientIDString == myPeerID
    }

    /**
     * Determine if we should relay this packet based on type and network conditions
     */
    private fun shouldRelayPacket(packet: BitchatPacket, fromPeerID: String): Boolean {
        // Always relay if TTL is high enough (indicates important message)
        if (packet.ttl >= 4u) {
            Log.d(TAG, "High TTL (${packet.ttl}), relaying")
            return true
        }

        // Get network size for adaptive relay probability
        val networkSize = delegate?.getNetworkSize() ?: 1

        // Small networks always relay to ensure connectivity
        if (networkSize <= 3) {
            Log.d(TAG, "Small network (${networkSize} peers), relaying")
            return true
        }

        // Apply adaptive relay probability based on network size
        val relayProb = when {
            networkSize <= 10 -> 1.0    // Always relay in small networks
            networkSize <= 30 -> 0.85   // High probability for medium networks
            networkSize <= 50 -> 0.7    // Moderate probability
            networkSize <= 100 -> 0.55  // Lower probability for large networks
            else -> 0.4                 // Lowest probability for very large networks
        }

        val shouldRelay = Random.nextDouble() < relayProb
        Log.d(TAG, "Network size: ${networkSize}, Relay probability: ${relayProb}, Decision: ${shouldRelay}")

        return shouldRelay
    }

    /**
     * Actually broadcast the packet for relay
     */
    private fun relayPacket(routed: RoutedPacket) {
        Log.d(TAG, "🔄 Relaying packet type ${routed.packet.type} with TTL ${routed.packet.ttl}")
        delegate?.broadcastPacket(routed)
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Packet Relay Manager Debug Info ===")
            appendLine("Relay Scope Active: ${relayScope.isActive}")
            appendLine("My Peer ID: ${myPeerID}")
            appendLine("Network Size: ${delegate?.getNetworkSize() ?: "unknown"}")
        }
    }

    /**
     * Shutdown the relay manager
     */
    fun shutdown() {
        Log.d(TAG, "Shutting down PacketRelayManager")
        relayScope.cancel()
    }
}

/**
 * Delegate interface for packet relay manager callbacks
 */
interface PacketRelayManagerDelegate {
    // Network information
    fun getNetworkSize(): Int
    fun getBroadcastRecipient(): ByteArray

    // Packet operations
    fun broadcastPacket(routed: RoutedPacket)
    fun sendToPeer(peerID: String, routed: RoutedPacket): Boolean
}

private fun hexStringToPeerBytes(hex: String): ByteArray {
    val result = ByteArray(8)
    var idx = 0
    var out = 0
    while (idx + 1 < hex.length && out < 8) {
        val b = hex.substring(idx, idx + 2).toIntOrNull(16)?.toByte() ?: 0
        result[out++] = b
        idx += 2
    }
    return result
}

package com.bitchat.android.mesh

import android.util.Log
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

/**
 * Centralized peer fingerprint management singleton
 * 
 * This class manages all peer fingerprint storage and retrieval operations, 
 * providing a single source of truth for peer identity across the entire application.
 * 
 * Fingerprints are SHA-256 hashes of peer static public keys and are only stored 
 * after successful Noise handshake session establishment.
 * 
 * Key Design Principles:
 * - Thread-safe operations using ConcurrentHashMap
 * - Bidirectional mapping (peerID ↔ fingerprint) 
 * - Support for peer ID rotation while maintaining persistent identity
 * - Centralized logging for debugging identity management
 */
class PeerFingerprintManager private constructor() {

    companion object {
        private const val TAG = "PeerFingerprintManager"

        @Volatile
        private var INSTANCE: PeerFingerprintManager? = null

        /**
         * Get the singleton instance
         */
        fun getInstance(): PeerFingerprintManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: PeerFingerprintManager().also { INSTANCE = it }
            }
        }
    }

    // Bidirectional mapping for efficient lookups
    private val peerIDToFingerprint = ConcurrentHashMap<String, String>() // peerID -> fingerprint
    private val fingerprintToPeerID = ConcurrentHashMap<String, String>() // fingerprint -> current peerID

    // MARK: - Fingerprint Storage (Only called after successful Noise handshake)

    /**
     * Store fingerprint mapping after successful Noise handshake session establishment
     * This is the ONLY place where fingerprints should be stored
     * 
     * @param peerID The peer's current ID
     * @param publicKey The peer's static public key from Noise handshake
     */
    fun storeFingerprintForPeer(peerID: String, publicKey: ByteArray): String {
        // get existing fingerprint for this peer and compare
        val existingFingerprint = getFingerprintForPeer(peerID)
        val fingerprint = calculateFingerprint(publicKey)

        if (existingFingerprint != null && existingFingerprint != fingerprint) {
            Log.w(TAG, "Fingerprint mismatch for peer $peerID: $existingFingerprint != $fingerprint")
            throw IllegalStateException("Fingerprint mismatch for peer $peerID: $existingFingerprint != $fingerprint")
        }

        // Store bidirectional mapping
        peerIDToFingerprint[peerID] = fingerprint
        fingerprintToPeerID[fingerprint] = peerID

        Log.d(TAG, "Stored fingerprint for peer $peerID: ${fingerprint.take(16)}...")
        return fingerprint
    }

    /**
     * Update peer ID mapping while preserving fingerprint identity
     * Used for peer ID rotation - when a peer changes their ID but maintains the same static key
     * 
     * @param oldPeerID The previous peer ID (nullable if this is a fresh mapping)
     * @param newPeerID The new peer ID
     * @param fingerprint The persistent fingerprint (should match existing one)
     */
    fun updatePeerIDMapping(oldPeerID: String?, newPeerID: String, fingerprint: String) {
        if (newPeerID.isBlank()) {
            Log.w(TAG, "Attempted to update mapping with blank newPeerID")
            return
        }

        if (fingerprint.isBlank()) {
            Log.w(TAG, "Attempted to update mapping with blank fingerprint")
            return
        }

        // Remove old mapping if exists
        oldPeerID?.takeIf { it.isNotBlank() }?.let { oldID ->
            val removedFingerprint = peerIDToFingerprint.remove(oldID)
            if (removedFingerprint != null && removedFingerprint == fingerprint) {
                Log.d(TAG, "Removed old mapping: $oldID -> ${removedFingerprint.take(16)}...")
            }
        }

        // Add new mapping
        peerIDToFingerprint[newPeerID] = fingerprint
        fingerprintToPeerID[fingerprint] = newPeerID

        Log.d(TAG, "Updated peer ID mapping: $newPeerID (was: $oldPeerID), fingerprint: ${fingerprint.take(16)}...")
    }

    // MARK: - Fingerprint Retrieval

    /**
     * Get fingerprint for a specific peer ID
     * 
     * @param peerID The peer ID to look up
     * @return The fingerprint if found, null otherwise
     */
    fun getFingerprintForPeer(peerID: String): String? {
        if (peerID.isBlank()) return null
        return peerIDToFingerprint[peerID]
    }

    /**
     * Get current peer ID for a specific fingerprint
     * 
     * @param fingerprint The fingerprint to look up
     * @return The current peer ID if found, null otherwise
     */
    fun getPeerIDForFingerprint(fingerprint: String): String? {
        if (fingerprint.isBlank()) return null
        return fingerprintToPeerID[fingerprint]
    }

    /**
     * Check if we have a fingerprint for a specific peer
     * 
     * @param peerID The peer ID to check
     * @return True if we have a fingerprint for this peer, false otherwise
     */
    fun hasFingerprintForPeer(peerID: String): Boolean {
        return getFingerprintForPeer(peerID) != null
    }

    /**
     * Get all current peer ID to fingerprint mappings
     * 
     * @return Immutable copy of all mappings
     */
    fun getAllPeerFingerprints(): Map<String, String> {
        return peerIDToFingerprint.toMap()
    }

    /**
     * Get all current fingerprint to peer ID mappings
     * 
     * @return Immutable copy of all reverse mappings
     */
    fun getAllFingerprintMappings(): Map<String, String> {
        return fingerprintToPeerID.toMap()
    }

    // MARK: - Peer Management

    /**
     * Remove all mappings for a specific peer (called when peer disconnects)
     * 
     * @param peerID The peer ID to remove
     */
    fun removePeer(peerID: String) {
        if (peerID.isBlank()) return

        val fingerprint = peerIDToFingerprint.remove(peerID)
        if (fingerprint != null) {
            fingerprintToPeerID.remove(fingerprint)
            Log.d(TAG, "Removed peer mappings for $peerID: ${fingerprint.take(16)}...")
        }
    }

    /**
     * Remove all mappings for a specific fingerprint
     * 
     * @param fingerprint The fingerprint to remove
     */
    fun removeFingerprint(fingerprint: String) {
        if (fingerprint.isBlank()) return

        val peerID = fingerprintToPeerID.remove(fingerprint)
        if (peerID != null) {
            peerIDToFingerprint.remove(peerID)
            Log.d(TAG, "Removed fingerprint mappings for ${fingerprint.take(16)}...: $peerID")
        }
    }

    /**
     * Clear all fingerprint mappings (used for emergency clear/panic mode)
     */
    fun clearAllFingerprints() {
        val count = peerIDToFingerprint.size
        peerIDToFingerprint.clear()
        fingerprintToPeerID.clear()
    }

    // MARK: - Utility Functions

    /**
     * Calculate SHA-256 fingerprint from public key
     * 
     * @param publicKey The peer's static public key
     * @return The hex-encoded SHA-256 hash
     */
    private fun calculateFingerprint(publicKey: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(publicKey)
        return hash.joinToString("") { "%02x".format(it) }
    }

    /**
     * Get debug information about current fingerprint mappings
     * 
     * @return Debug string with mapping counts and summary
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== PeerFingerprintManager Debug Info ===")
            appendLine("Total mappings: ${peerIDToFingerprint.size}")

            if (peerIDToFingerprint.isNotEmpty()) {
                appendLine("Peer ID -> Fingerprint mappings:")
                peerIDToFingerprint.forEach { (peerID, fingerprint) ->
                    appendLine("  $peerID -> ${fingerprint.take(16)}...")
                }
            } else {
                appendLine("No fingerprint mappings stored")
            }

            // Verify bidirectional mapping consistency
            val inconsistentMappings = mutableListOf<String>()
            peerIDToFingerprint.forEach { (peerID, fingerprint) ->
                val reversePeerID = fingerprintToPeerID[fingerprint]
                if (reversePeerID != peerID) {
                    inconsistentMappings.add("$peerID -> $fingerprint -> $reversePeerID")
                }
            }

            if (inconsistentMappings.isNotEmpty()) {
                appendLine("⚠️ INCONSISTENT MAPPINGS DETECTED:")
                inconsistentMappings.forEach { appendLine("  $it") }
            }
        }
    }
}

package com.bitchat.android.mesh

import android.util.Log
import com.bitchat.android.model.AuthenticatedPeerState
import com.bitchat.android.model.PeerCapabilities
import kotlinx.coroutines.*
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CopyOnWriteArrayList

/**
 * Peer information structure with verification status
 * Compatible with iOS PeerInfo structure
 */
data class PeerInfo(
    val id: String,
    var nickname: String,
    var isConnected: Boolean,
    var isDirectConnection: Boolean,
    var noisePublicKey: ByteArray?,
    var signingPublicKey: ByteArray?,      // NEW: Ed25519 public key for verification
    var isVerifiedNickname: Boolean,       // NEW: Verification status flag
    var lastSeen: Long,  // Using Long instead of Date for simplicity
    var capabilities: PeerCapabilities? = null, // null means a signed old-client announce omitted TLV 0x05
    var hasVerifiedAnnouncement: Boolean = false,
    /** Noise key that the preserved capability state was actually signed alongside. */
    var verifiedAnnouncementNoisePublicKey: ByteArray? = null
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as PeerInfo

        if (id != other.id) return false
        if (nickname != other.nickname) return false
        if (isConnected != other.isConnected) return false
        if (isDirectConnection != other.isDirectConnection) return false
        if (noisePublicKey != null) {
            if (other.noisePublicKey == null) return false
            if (!noisePublicKey.contentEquals(other.noisePublicKey)) return false
        } else if (other.noisePublicKey != null) return false
        if (signingPublicKey != null) {
            if (other.signingPublicKey == null) return false
            if (!signingPublicKey.contentEquals(other.signingPublicKey)) return false
        } else if (other.signingPublicKey != null) return false
        if (isVerifiedNickname != other.isVerifiedNickname) return false
        if (lastSeen != other.lastSeen) return false
        if (capabilities != other.capabilities) return false
        if (hasVerifiedAnnouncement != other.hasVerifiedAnnouncement) return false
        val thisVerifiedAnnouncementKey = verifiedAnnouncementNoisePublicKey
        val otherVerifiedAnnouncementKey = other.verifiedAnnouncementNoisePublicKey
        if (thisVerifiedAnnouncementKey != null) {
            if (otherVerifiedAnnouncementKey == null) return false
            if (!thisVerifiedAnnouncementKey.contentEquals(otherVerifiedAnnouncementKey)) return false
        } else if (otherVerifiedAnnouncementKey != null) return false

        return true
    }

    override fun hashCode(): Int {
        var result = id.hashCode()
        result = 31 * result + nickname.hashCode()
        result = 31 * result + isConnected.hashCode()
        result = 31 * result + isDirectConnection.hashCode()
        result = 31 * result + (noisePublicKey?.contentHashCode() ?: 0)
        result = 31 * result + (signingPublicKey?.contentHashCode() ?: 0)
        result = 31 * result + isVerifiedNickname.hashCode()
        result = 31 * result + lastSeen.hashCode()
        result = 31 * result + (capabilities?.hashCode() ?: 0)
        result = 31 * result + hasVerifiedAnnouncement.hashCode()
        result = 31 * result + (verifiedAnnouncementNoisePublicKey?.contentHashCode() ?: 0)
        return result
    }
}

/**
 * Manages active peers, nicknames, RSSI tracking, and peer fingerprints
 * Extracted from BluetoothMeshService for better separation of concerns
 * 
 * Now includes centralized peer fingerprint management via PeerFingerprintManager singleton
 * and support for signed announcement verification
 */
class PeerManager {

    companion object {
        private const val TAG = "PeerManager"
    }

    // Centralized timeout from AppConstants
    private val stalePeerTimeoutMs: Long = com.bitchat.android.util.AppConstants.Mesh.STALE_PEER_TIMEOUT_MS

    // Peer tracking data - enhanced with verification status
    private val peers = ConcurrentHashMap<String, PeerInfo>() // peerID -> PeerInfo
    private val peerRSSI = ConcurrentHashMap<String, Int>()
    private val announcedPeers = CopyOnWriteArrayList<String>()
    private val announcedToPeers = CopyOnWriteArrayList<String>()

    // Legacy fields removed: use PeerInfo map exclusively

    // Centralized fingerprint management
    private val fingerprintManager = PeerFingerprintManager.getInstance()

    // Delegate for callbacks
    var delegate: PeerManagerDelegate? = null

    // Callback to check if a peer is directly connected (injected by BluetoothMeshService)
    var isPeerDirectlyConnected: ((String) -> Boolean)? = null

    // Coroutines
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    init {
        startPeriodicCleanup()
    }

    // MARK: - New PeerInfo-based methods

    /**
     * Update peer information with verification data
     * Similar to iOS updatePeer method
     */
    fun updatePeerInfo(
        peerID: String,
        nickname: String,
        noisePublicKey: ByteArray,
        signingPublicKey: ByteArray,
        isVerified: Boolean
    ): Boolean {
        val existing = peers[peerID]
        return updatePeerInfoInternal(
            peerID = peerID,
            nickname = nickname,
            noisePublicKey = noisePublicKey,
            signingPublicKey = signingPublicKey,
            isVerified = isVerified,
            capabilities = existing?.capabilities,
            hasVerifiedAnnouncement = existing?.hasVerifiedAnnouncement == true,
            verifiedAnnouncementNoisePublicKey = existing?.verifiedAnnouncementNoisePublicKey
        )
    }

    /**
     * Apply the exact capability state from a signature-verified announce.
     * A null value is meaningful: the peer signed an old-format announce that
     * omitted TLV 0x05. Normal peer refreshes use [updatePeerInfo] and retain
     * the last signed capability state instead of accidentally erasing it.
     */
    fun updatePeerInfoFromVerifiedAnnouncement(
        peerID: String,
        nickname: String,
        noisePublicKey: ByteArray,
        signingPublicKey: ByteArray,
        isVerified: Boolean,
        capabilities: PeerCapabilities?
    ): Boolean = updatePeerInfoInternal(
        peerID = peerID,
        nickname = nickname,
        noisePublicKey = noisePublicKey,
        signingPublicKey = signingPublicKey,
        isVerified = isVerified,
        capabilities = capabilities,
        hasVerifiedAnnouncement = true,
        verifiedAnnouncementNoisePublicKey = noisePublicKey.copyOf()
    )

    /** Replace capability/Ed identity from Noise 0x21 in one peer-map mutation. */
    @Synchronized
    fun applyAuthenticatedPeerState(
        peerID: String,
        authenticatedNoisePublicKey: ByteArray,
        state: AuthenticatedPeerState
    ) {
        val existing = peers[peerID]
        val announcementMatchesAuthenticatedState = existing?.hasVerifiedAnnouncement == true &&
            existing.verifiedAnnouncementNoisePublicKey?.contentEquals(authenticatedNoisePublicKey) == true &&
            existing.signingPublicKey?.contentEquals(state.signingPublicKey) == true
        val replacement = PeerInfo(
            id = peerID,
            // A copied-static preannouncement cannot retain its attacker-chosen display name once
            // authenticated peer state proves a different Ed key.
            nickname = existing?.nickname?.takeIf { announcementMatchesAuthenticatedState } ?: peerID,
            isConnected = true,
            isDirectConnection = existing?.isDirectConnection ?: false,
            noisePublicKey = authenticatedNoisePublicKey.copyOf(),
            signingPublicKey = state.signingPublicKey.copyOf(),
            isVerifiedNickname = existing?.isVerifiedNickname == true && announcementMatchesAuthenticatedState,
            lastSeen = System.currentTimeMillis(),
            capabilities = state.capabilities,
            hasVerifiedAnnouncement = announcementMatchesAuthenticatedState,
            verifiedAnnouncementNoisePublicKey = authenticatedNoisePublicKey.copyOf()
                .takeIf { announcementMatchesAuthenticatedState }
        )
        peers[peerID] = replacement
        if (existing == null || existing != replacement) notifyPeerListUpdate()
    }

    private fun updatePeerInfoInternal(
        peerID: String,
        nickname: String,
        noisePublicKey: ByteArray,
        signingPublicKey: ByteArray,
        isVerified: Boolean,
        capabilities: PeerCapabilities?,
        hasVerifiedAnnouncement: Boolean,
        verifiedAnnouncementNoisePublicKey: ByteArray?
    ): Boolean {
        if (peerID == "unknown") return false

        fun keysMatch(a: ByteArray?, b: ByteArray?): Boolean {
            if (a == null && b == null) return true
            if (a == null || b == null) return false
            return a.contentEquals(b)
        }

        val now = System.currentTimeMillis()
        val existingPeer = peers[peerID]
        val isNewPeer = existingPeer == null
        val wasVerified = existingPeer?.isVerifiedNickname == true
        val nicknameChanged = existingPeer != null && existingPeer.nickname != nickname
        val noiseKeyChanged = existingPeer != null && !keysMatch(existingPeer.noisePublicKey, noisePublicKey)
        val signingKeyChanged = existingPeer != null && !keysMatch(existingPeer.signingPublicKey, signingPublicKey)
        val connectedChanged = existingPeer != null && existingPeer.isConnected != true
        val capabilitiesChanged = existingPeer != null && existingPeer.capabilities != capabilities
        val announcementStateChanged = existingPeer != null &&
            existingPeer.hasVerifiedAnnouncement != hasVerifiedAnnouncement

        // Update or create peer info
        val peerInfo = PeerInfo(
            id = peerID,
            nickname = nickname,
            isConnected = true,
            isDirectConnection = existingPeer?.isDirectConnection ?: false,
            noisePublicKey = noisePublicKey,
            signingPublicKey = signingPublicKey,
            isVerifiedNickname = isVerified,
            lastSeen = now,
            capabilities = capabilities,
            hasVerifiedAnnouncement = hasVerifiedAnnouncement,
            verifiedAnnouncementNoisePublicKey = verifiedAnnouncementNoisePublicKey?.copyOf()
        )

        peers[peerID] = peerInfo

        // Update derived state only
        // No legacy maps; peers map is the single source of truth
        // Maintain announcedPeers for first-time announce semantics

        val shouldNotify = when {
            isNewPeer && isVerified -> true
            wasVerified != isVerified -> true
            nicknameChanged || noiseKeyChanged || signingKeyChanged || connectedChanged ||
                capabilitiesChanged || announcementStateChanged -> true
            else -> false
        }

        if (isNewPeer && isVerified) {
            announcedPeers.add(peerID)
            Log.d(TAG, "🆕 New verified peer: $nickname ($peerID)")
        } else if (isVerified) {
            Log.d(TAG, "🔄 Updated verified peer: $nickname ($peerID)")
        } else {
            Log.d(TAG, "⚠️ Unverified peer announcement from: $nickname ($peerID)")
        }

        if (shouldNotify) {
            notifyPeerListUpdate()
        }

        return isNewPeer && isVerified
    }

    /**
     * Get peer info with dynamic direct connection status
     */
    fun getPeerInfo(peerID: String): PeerInfo? {
        return peers[peerID]?.let { info ->
            // Dynamically check direct connection status from ConnectionManager
            val isDirect = isPeerDirectlyConnected?.invoke(peerID) ?: false
            if (info.isDirectConnection != isDirect) {
                info.copy(isDirectConnection = isDirect)
            } else {
                info
            }
        }
    }

    /**
     * Check if peer is verified
     */
    fun isPeerVerified(peerID: String): Boolean {
        return peers[peerID]?.isVerifiedNickname == true
    }

    /**
     * Get all verified peers with dynamic direct connection status
     */
    fun getVerifiedPeers(): Map<String, PeerInfo> {
        return peers.filterValues { it.isVerifiedNickname }.mapValues { (_, info) ->
            val isDirect = isPeerDirectlyConnected?.invoke(info.id) ?: false
            if (info.isDirectConnection != isDirect) info.copy(isDirectConnection = isDirect) else info
        }
    }

    // MARK: - Legacy Methods (maintained for compatibility)

    /**
     * Update peer last seen timestamp
     */
    fun updatePeerLastSeen(peerID: String) {
        if (peerID != "unknown") {
            peers[peerID]?.let { info ->
                peers[peerID] = info.copy(lastSeen = System.currentTimeMillis())
            }
        }
    }

    /**
     * Add or update peer with nickname
     * Maintained for compatibility. Uses peers map exclusively now.
     */
    fun addOrUpdatePeer(peerID: String, nickname: String): Boolean {
        if (peerID == "unknown") return false

        // Clean up stale peer IDs with the same nickname (exact same logic as iOS)
        val now = System.currentTimeMillis()
        val stalePeerIDs = mutableListOf<String>()
        peers.forEach { (existingPeerID, info) ->
            if (info.nickname == nickname && existingPeerID != peerID) {
                val wasRecentlySeen = (now - info.lastSeen) < 10000
                if (!wasRecentlySeen) {
                    stalePeerIDs.add(existingPeerID)
                }
            }
        }

        // Remove stale peer IDs
        stalePeerIDs.forEach { stalePeerID ->
            removePeer(stalePeerID, notifyPeerList = false)
        }

        // Check if this is a new peer announcement
        val isFirstAnnounce = !announcedPeers.contains(peerID)

        // Update peer data
        val existing = peers[peerID]
        if (existing != null) {
            peers[peerID] = existing.copy(nickname = nickname, lastSeen = now, isConnected = true)
        } else {
            peers[peerID] = PeerInfo(
                id = peerID,
                nickname = nickname,
                isConnected = true,
                isDirectConnection = false,
                noisePublicKey = null,
                signingPublicKey = null,
                isVerifiedNickname = false,
                lastSeen = now
            )
        }

        // Handle first announcement
        if (isFirstAnnounce) {
            announcedPeers.add(peerID)
            notifyPeerListUpdate()
            return true
        }
        Log.d(TAG, "Updated peer: $peerID ($nickname)")
        return false
    }

    /**
     * Remove peer
     */
    fun removePeer(peerID: String, notifyPeerList: Boolean = true) {
        val removed = peers.remove(peerID)
        peerRSSI.remove(peerID)
        announcedPeers.remove(peerID)
        announcedToPeers.remove(peerID)

        // Also remove fingerprint mappings
        fingerprintManager.removePeer(peerID)

        if (removed != null) {
            // Lifecycle cleanup must always run. Callers may suppress only the
            // intermediate peer-list update while atomically replacing a peer.
            try { delegate?.onPeerRemoved(peerID) } catch (_: Exception) {}
            if (notifyPeerList) {
                notifyPeerListUpdate()
            }
        }
    }

    /**
     * Update peer RSSI
     */
    fun updatePeerRSSI(peerID: String, rssi: Int) {
        if (peerID != "unknown") {
            peerRSSI[peerID] = rssi
        }
    }

    /**
     * Check if peer has been announced to
     */
    fun hasAnnouncedToPeer(peerID: String): Boolean {
        return announcedToPeers.contains(peerID)
    }

    /**
     * Mark peer as announced to
     */
    fun markPeerAsAnnouncedTo(peerID: String) {
        if (!announcedToPeers.contains(peerID)) {
            announcedToPeers.add(peerID)
        }
    }

    /**
     * Check if peer is active
     */
    fun isPeerActive(peerID: String): Boolean {
        val info = peers[peerID] ?: return false
        return info.isConnected
    }

    /**
     * Get peer nickname
     */
    fun getPeerNickname(peerID: String): String? {
        return peers[peerID]?.nickname
    }

    /**
     * Get all peer nicknames
     */
    fun getAllPeerNicknames(): Map<String, String> {
        return peers.mapValues { it.value.nickname }
    }

    /**
     * Get all peer RSSI values
     */
    fun getAllPeerRSSI(): Map<String, Int> {
        return peerRSSI.toMap()
    }

    /**
     * Get list of active peer IDs
     */
    fun getActivePeerIDs(): List<String> {
        return peers.filterValues { it.isConnected }
            .keys
            .toList()
            .sorted()
    }

    /**
     * Get active peer count
     */
    fun getActivePeerCount(): Int {
        return getActivePeerIDs().size
    }

    /**
     * Clear all peer data
     */
    fun clearAllPeers() {
        peers.clear()
        peerRSSI.clear()
        announcedPeers.clear()
        announcedToPeers.clear()

        // Also clear fingerprint mappings
        fingerprintManager.clearAllFingerprints()

        notifyPeerListUpdate()
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(addressPeerMap: Map<String, String>? = null): String {
        val now = System.currentTimeMillis()
        val activeIds = getActivePeerIDs().toSet()
        return buildString {
            appendLine("=== Peer Manager Debug Info ===")
            appendLine("Active Peers: ${activeIds.size}")
            peers.forEach { (peerID, storedInfo) ->
                // Use dynamic direct status for debug log accuracy
                val isDirect = isPeerDirectlyConnected?.invoke(peerID) ?: false
                val info = if (storedInfo.isDirectConnection != isDirect) storedInfo.copy(isDirectConnection = isDirect) else storedInfo

                val timeSince = (now - info.lastSeen) / 1000
                val rssi = peerRSSI[peerID]?.let { "${it} dBm" } ?: "No RSSI"
                val deviceAddress = addressPeerMap?.entries?.find { it.value == peerID }?.key
                val addressInfo = deviceAddress?.let { " [Device: $it]" } ?: " [Device: Unknown]"
                val status = if (activeIds.contains(peerID)) "ACTIVE" else "INACTIVE"
                val direct = if (info.isDirectConnection) "DIRECT" else "ROUTED"
                appendLine("  - $peerID (${info.nickname})$addressInfo - $status/$direct, last seen ${timeSince}s ago, RSSI: $rssi")
            }
            appendLine("Announced Peers: ${announcedPeers.size}")
            appendLine("Announced To Peers: ${announcedToPeers.size}")
        }
    }

    /**
     * Get debug information with device addresses
     */
    fun getDebugInfoWithDeviceAddresses(addressPeerMap: Map<String, String>): String {
        return buildString {
            appendLine("=== Device Address to Peer Mapping ===")
            if (addressPeerMap.isEmpty()) {
                appendLine("No device address mappings available")
            } else {
                addressPeerMap.forEach { (deviceAddress, peerID) ->
                    val nickname = peers[peerID]?.nickname ?: "Unknown"
                    val isActive = isPeerActive(peerID)
                    val status = if (isActive) "ACTIVE" else "INACTIVE"
                    appendLine("  Device: $deviceAddress -> Peer: $peerID ($nickname) [$status]")
                }
            }
            appendLine()
            appendLine(getDebugInfo(addressPeerMap))
        }
    }

    /**
     * Notify delegate of peer list updates
     */
    private fun notifyPeerListUpdate() {
        val peerList = getActivePeerIDs()
        delegate?.onPeerListUpdated(peerList)
    }

    fun refreshPeerList() {
        notifyPeerListUpdate()
    }

    /**
     * Start periodic cleanup of stale peers
     */
    private fun startPeriodicCleanup() {
        managerScope.launch {
            while (isActive) {
                delay(com.bitchat.android.util.AppConstants.Mesh.PEER_CLEANUP_INTERVAL_MS)
                cleanupStalePeers()
            }
        }
    }

    /**
     * Clean up stale peers (same 3-minute threshold as iOS)
     */
    private fun cleanupStalePeers() {
        val now = System.currentTimeMillis()

        val peersToRemove = peers.filterValues { (now - it.lastSeen) > stalePeerTimeoutMs }
            .keys
            .toList()

        peersToRemove.forEach { peerID ->
            Log.d(TAG, "Removing stale peer: $peerID")
            removePeer(peerID)
        }

        if (peersToRemove.isNotEmpty()) {
            Log.d(TAG, "Cleaned up ${peersToRemove.size} stale peers")
        }
    }

    // MARK: - Fingerprint Management (Centralized)

    /**
     * Store fingerprint for a peer after successful Noise handshake
     * This should only be called when a Noise session is established
     * 
     * @param peerID The peer's ID
     * @param publicKey The peer's static public key from Noise handshake
     */
    fun storeFingerprintForPeer(peerID: String, publicKey: ByteArray): String {
        return fingerprintManager.storeFingerprintForPeer(peerID, publicKey)
    }

    /**
     * Update peer ID mapping for peer ID rotation
     * 
     * @param oldPeerID The previous peer ID (nullable)
     * @param newPeerID The new peer ID
     * @param fingerprint The persistent fingerprint
     */
    fun updatePeerIDMapping(oldPeerID: String?, newPeerID: String, fingerprint: String) {
        fingerprintManager.updatePeerIDMapping(oldPeerID, newPeerID, fingerprint)
    }

    /**
     * Get fingerprint for a specific peer
     * 
     * @param peerID The peer ID to look up
     * @return The fingerprint if found, null otherwise
     */
    fun getFingerprintForPeer(peerID: String): String? {
        return fingerprintManager.getFingerprintForPeer(peerID)
    }

    /**
     * Get current peer ID for a specific fingerprint
     * 
     * @param fingerprint The fingerprint to look up
     * @return The current peer ID if found, null otherwise
     */
    fun getPeerIDForFingerprint(fingerprint: String): String? {
        return fingerprintManager.getPeerIDForFingerprint(fingerprint)
    }

    /**
     * Check if we have a fingerprint for a specific peer
     * 
     * @param peerID The peer ID to check
     * @return True if we have a fingerprint for this peer, false otherwise
     */
    fun hasFingerprintForPeer(peerID: String): Boolean {
        return fingerprintManager.hasFingerprintForPeer(peerID)
    }

    /**
     * Get all current peer ID to fingerprint mappings
     * 
     * @return Immutable copy of all mappings
     */
    fun getAllPeerFingerprints(): Map<String, String> {
        return fingerprintManager.getAllPeerFingerprints()
    }

    /**
     * Clear all fingerprint mappings (used for emergency clear)
     */
    fun clearAllFingerprints() {
        fingerprintManager.clearAllFingerprints()
    }

    /**
     * Get fingerprint manager debug info
     */
    fun getFingerprintDebugInfo(): String {
        return fingerprintManager.getDebugInfo()
    }

    /**
     * Shutdown the manager
     */
    fun shutdown() {
        managerScope.cancel()
        clearAllPeers()
    }
}

/**
 * Delegate interface for peer manager callbacks
 */
interface PeerManagerDelegate {
    fun onPeerListUpdated(peerIDs: List<String>)
    fun onPeerRemoved(peerID: String)
}

package com.bitchat.android.mesh

import android.bluetooth.le.AdvertiseSettings
import android.bluetooth.le.ScanSettings
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.BatteryManager
import android.os.Handler
import android.os.Looper
import android.util.Log
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleEventObserver
import androidx.lifecycle.LifecycleOwner
import androidx.lifecycle.ProcessLifecycleOwner
import com.bitchat.android.services.AppStateStore
import com.bitchat.android.util.AppConstants
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * Process-wide source of truth for background and battery-aware scheduling.
 *
 * The manager deliberately exposes policy only. Consumers retain ownership of their hardware and
 * network jobs, so changing profile never implies disconnecting a transport or suspending Tor.
 */
class PowerManager private constructor(context: Context) : LifecycleEventObserver {

    enum class PowerMode {
        PERFORMANCE,
        BALANCED,
        POWER_SAVER,
        ULTRA_LOW_POWER
    }

    enum class BatteryBand { NORMAL, LOW, CRITICAL }

    data class BleSchedule(
        val scanOnMs: Long,
        val scanOffMs: Long,
        val continuousScan: Boolean,
        val maxConnections: Int = 8
    )

    data class WifiAwareSchedule(
        val tcpKeepAliveMs: Long,
        val discoveryKeepAliveMs: Long,
        val connectionMaintenanceMs: Long,
        val discoveryIdleRefreshMs: Long,
        val discoverySessionRefreshMinMs: Long,
        val discoveryStaleMs: Long
    )

    data class NostrSchedule(
        val presenceHeartbeatMinMs: Long,
        val presenceHeartbeatMaxMs: Long,
        val subscriptionValidationMs: Long
    )

    data class RuntimePerformanceProfile(
        val mode: PowerMode,
        val batteryBand: BatteryBand,
        val isBackground: Boolean,
        val isCharging: Boolean,
        val hasDirectPeers: Boolean,
        val ble: BleSchedule,
        val meshAnnouncementIntervalMs: Long,
        val wifiAware: WifiAwareSchedule,
        val nostr: NostrSchedule
    )

    companion object {
        private const val TAG = "PowerManager"

        @Volatile
        private var INSTANCE: PowerManager? = null

        fun getInstance(context: Context): PowerManager =
            INSTANCE ?: synchronized(this) {
                INSTANCE ?: PowerManager(context.applicationContext).also { INSTANCE = it }
            }
    }

    private val appContext = context.applicationContext
    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())

    @Volatile private var batteryLevel = 100
    @Volatile private var isCharging = false
    @Volatile private var isAppInBackground = true
    @Volatile private var hasDirectPeers = false
    @Volatile private var shutdown = false

    private val _profile = MutableStateFlow(
        PowerProfileResolver.resolve(
            batteryLevel = batteryLevel,
            isCharging = isCharging,
            isBackground = isAppInBackground,
            hasDirectPeers = hasDirectPeers
        )
    )
    val profile: StateFlow<RuntimePerformanceProfile> = _profile.asStateFlow()

    private val batteryReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            when (intent?.action) {
                Intent.ACTION_BATTERY_CHANGED -> {
                    val level = intent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)
                    val scale = intent.getIntExtra(BatteryManager.EXTRA_SCALE, -1)
                    if (level >= 0 && scale > 0) batteryLevel = (level * 100) / scale

                    val status = intent.getIntExtra(BatteryManager.EXTRA_STATUS, -1)
                    isCharging = status == BatteryManager.BATTERY_STATUS_CHARGING ||
                        status == BatteryManager.BATTERY_STATUS_FULL
                    refreshProfile()
                }
                Intent.ACTION_POWER_CONNECTED -> {
                    isCharging = true
                    refreshProfile()
                }
                Intent.ACTION_POWER_DISCONNECTED -> {
                    isCharging = false
                    refreshProfile()
                }
            }
        }
    }

    init {
        registerBatteryReceiver()
        Handler(Looper.getMainLooper()).post {
            try {
                ProcessLifecycleOwner.get().lifecycle.addObserver(this)
                isAppInBackground = !ProcessLifecycleOwner.get().lifecycle.currentState
                    .isAtLeast(Lifecycle.State.STARTED)
                refreshProfile()
            } catch (e: Exception) {
                Log.e(TAG, "Failed to register process lifecycle observer: ${e.message}")
            }
        }
        scope.launch {
            AppStateStore.directPeers
                .collect { peers ->
                    hasDirectPeers = peers.isNotEmpty()
                    refreshProfile()
                }
        }
    }

    /** Kept for existing callers; initialization is eager and idempotent. */
    fun start() = Unit

    /**
     * Process-level teardown for explicit full application shutdown only.
     * Transport stop/restart paths must not call this.
     */
    fun shutdown() {
        if (shutdown) return
        shutdown = true
        scope.cancel()
        try { appContext.unregisterReceiver(batteryReceiver) } catch (_: Exception) { }
        Handler(Looper.getMainLooper()).post {
            try { ProcessLifecycleOwner.get().lifecycle.removeObserver(this) } catch (_: Exception) { }
        }
    }

    override fun onStateChanged(source: LifecycleOwner, event: Lifecycle.Event) {
        when (event) {
            Lifecycle.Event.ON_START -> {
                isAppInBackground = false
                refreshProfile()
            }
            Lifecycle.Event.ON_STOP -> {
                isAppInBackground = true
                refreshProfile()
            }
            else -> Unit
        }
    }

    fun getScanSettings(): ScanSettings {
        val current = profile.value
        val builder = ScanSettings.Builder()
            .setCallbackType(ScanSettings.CALLBACK_TYPE_ALL_MATCHES)

        when (current.mode) {
            PowerMode.PERFORMANCE -> builder
                .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
                .setMatchMode(ScanSettings.MATCH_MODE_AGGRESSIVE)
                .setNumOfMatches(ScanSettings.MATCH_NUM_MAX_ADVERTISEMENT)
            PowerMode.BALANCED -> builder
                .setScanMode(ScanSettings.SCAN_MODE_BALANCED)
                .setMatchMode(ScanSettings.MATCH_MODE_AGGRESSIVE)
                .setNumOfMatches(ScanSettings.MATCH_NUM_ONE_ADVERTISEMENT)
            PowerMode.POWER_SAVER,
            PowerMode.ULTRA_LOW_POWER -> builder
                .setScanMode(ScanSettings.SCAN_MODE_LOW_POWER)
                .setMatchMode(ScanSettings.MATCH_MODE_STICKY)
                .setNumOfMatches(ScanSettings.MATCH_NUM_ONE_ADVERTISEMENT)
        }
        return builder.setReportDelay(0).build()
    }

    fun getAdvertiseSettings(): AdvertiseSettings = when (profile.value.mode) {
        PowerMode.PERFORMANCE -> AdvertiseSettings.Builder()
            .setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY)
            .setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_HIGH)
            .setConnectable(true).setTimeout(0).build()
        PowerMode.BALANCED -> AdvertiseSettings.Builder()
            .setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_BALANCED)
            .setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_MEDIUM)
            .setConnectable(true).setTimeout(0).build()
        PowerMode.POWER_SAVER -> AdvertiseSettings.Builder()
            .setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_POWER)
            .setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_LOW)
            .setConnectable(true).setTimeout(0).build()
        PowerMode.ULTRA_LOW_POWER -> AdvertiseSettings.Builder()
            .setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_POWER)
            .setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_ULTRA_LOW)
            .setConnectable(true).setTimeout(0).build()
    }

    fun getMaxConnections(): Int = profile.value.ble.maxConnections

    fun getRSSIThreshold(): Int = when (profile.value.mode) {
        PowerMode.PERFORMANCE -> -95
        PowerMode.BALANCED -> -85
        PowerMode.POWER_SAVER -> -75
        PowerMode.ULTRA_LOW_POWER -> -65
    }

    fun shouldUseDutyCycle(): Boolean = !profile.value.ble.continuousScan

    fun getPowerInfo(): String = profile.value.let { current ->
        buildString {
            appendLine("=== Power Manager Status ===")
            appendLine("Current Mode: ${current.mode}")
            appendLine("Battery Band: ${current.batteryBand} ($batteryLevel%)")
            appendLine("Is Charging: ${current.isCharging}")
            appendLine("App In Background: ${current.isBackground}")
            appendLine("Has Direct Peers: ${current.hasDirectPeers}")
            appendLine("BLE Scan: ${current.ble.scanOnMs}ms ON / ${current.ble.scanOffMs}ms OFF")
            appendLine("Max Connections: ${current.ble.maxConnections}")
        }
    }

    private fun refreshProfile() {
        if (shutdown) return
        val next = PowerProfileResolver.resolve(
            batteryLevel = batteryLevel,
            isCharging = isCharging,
            isBackground = isAppInBackground,
            hasDirectPeers = hasDirectPeers
        )
        if (_profile.value != next) {
            Log.i(
                TAG,
                "Profile changed: mode=${next.mode}, battery=${next.batteryBand}, " +
                    "background=${next.isBackground}, directPeers=${next.hasDirectPeers}"
            )
            _profile.value = next
        }
    }

    private fun registerBatteryReceiver() {
        try {
            val filter = IntentFilter().apply {
                addAction(Intent.ACTION_BATTERY_CHANGED)
                addAction(Intent.ACTION_POWER_CONNECTED)
                addAction(Intent.ACTION_POWER_DISCONNECTED)
            }
            appContext.registerReceiver(batteryReceiver, filter)
        } catch (e: Exception) {
            Log.w(TAG, "Failed to register battery receiver: ${e.message}")
        }
    }
}

/**
 * Pure policy resolver so cadence and battery-boundary behavior can be tested without Android.
 */
internal object PowerProfileResolver {
    fun resolve(
        batteryLevel: Int,
        isCharging: Boolean,
        isBackground: Boolean,
        hasDirectPeers: Boolean
    ): PowerManager.RuntimePerformanceProfile {
        val batteryBand = when {
            batteryLevel <= AppConstants.Power.CRITICAL_BATTERY_PERCENT ->
                PowerManager.BatteryBand.CRITICAL
            batteryLevel <= AppConstants.Power.LOW_BATTERY_PERCENT ->
                PowerManager.BatteryBand.LOW
            else -> PowerManager.BatteryBand.NORMAL
        }

        val mode = when {
            isBackground && batteryBand == PowerManager.BatteryBand.CRITICAL ->
                PowerManager.PowerMode.ULTRA_LOW_POWER
            isBackground -> PowerManager.PowerMode.POWER_SAVER
            isCharging -> PowerManager.PowerMode.PERFORMANCE
            batteryBand == PowerManager.BatteryBand.CRITICAL ->
                PowerManager.PowerMode.ULTRA_LOW_POWER
            batteryBand == PowerManager.BatteryBand.LOW ->
                PowerManager.PowerMode.POWER_SAVER
            else -> PowerManager.PowerMode.BALANCED
        }

        val ble = when {
            isBackground && hasDirectPeers ->
                PowerManager.BleSchedule(
                    scanOnMs = 1_000L,
                    scanOffMs = 29_000L,
                    continuousScan = false
                )
            isBackground ->
                PowerManager.BleSchedule(
                    scanOnMs = 1_000L,
                    scanOffMs = 59_000L,
                    continuousScan = false
                )
            mode == PowerManager.PowerMode.PERFORMANCE ->
                PowerManager.BleSchedule(Long.MAX_VALUE, 0L, true)
            mode == PowerManager.PowerMode.BALANCED ->
                PowerManager.BleSchedule(8_000L, 2_000L, false)
            mode == PowerManager.PowerMode.POWER_SAVER ->
                PowerManager.BleSchedule(2_000L, 28_000L, false)
            else ->
                PowerManager.BleSchedule(1_000L, 29_000L, false)
        }

        val announcementInterval = when {
            isBackground && batteryBand == PowerManager.BatteryBand.NORMAL -> 60_000L
            isBackground && batteryBand == PowerManager.BatteryBand.LOW -> 120_000L
            isBackground -> 300_000L
            mode == PowerManager.PowerMode.POWER_SAVER -> 60_000L
            mode == PowerManager.PowerMode.ULTRA_LOW_POWER -> 120_000L
            else -> 30_000L
        }

        val wifi = when {
            isBackground && batteryBand == PowerManager.BatteryBand.NORMAL ->
                wifi(10, 60, 60, 5, 5, 10)
            isBackground && batteryBand == PowerManager.BatteryBand.LOW ->
                wifi(20, 120, 120, 10, 10, 15)
            isBackground ->
                wifi(30, 180, 180, 15, 15, 20)
            mode == PowerManager.PowerMode.PERFORMANCE ->
                PowerManager.WifiAwareSchedule(2_000L, 20_000L, 15_000L, 120_000L, 90_000L, 300_000L)
            mode == PowerManager.PowerMode.BALANCED ->
                PowerManager.WifiAwareSchedule(5_000L, 30_000L, 30_000L, 180_000L, 120_000L, 300_000L)
            mode == PowerManager.PowerMode.POWER_SAVER ->
                PowerManager.WifiAwareSchedule(10_000L, 60_000L, 60_000L, 300_000L, 180_000L, 600_000L)
            else ->
                PowerManager.WifiAwareSchedule(15_000L, 90_000L, 90_000L, 600_000L, 300_000L, 900_000L)
        }

        val nostr = when {
            isBackground && batteryBand == PowerManager.BatteryBand.NORMAL ->
                PowerManager.NostrSchedule(300_000L, 330_000L, 300_000L)
            isBackground && batteryBand == PowerManager.BatteryBand.LOW ->
                PowerManager.NostrSchedule(600_000L, 660_000L, 600_000L)
            isBackground ->
                PowerManager.NostrSchedule(900_000L, 990_000L, 900_000L)
            mode == PowerManager.PowerMode.POWER_SAVER ->
                PowerManager.NostrSchedule(120_000L, 132_000L, 60_000L)
            mode == PowerManager.PowerMode.ULTRA_LOW_POWER ->
                PowerManager.NostrSchedule(300_000L, 330_000L, 120_000L)
            else ->
                PowerManager.NostrSchedule(40_000L, 80_000L, 30_000L)
        }

        return PowerManager.RuntimePerformanceProfile(
            mode = mode,
            batteryBand = batteryBand,
            isBackground = isBackground,
            isCharging = isCharging,
            hasDirectPeers = hasDirectPeers,
            ble = ble,
            meshAnnouncementIntervalMs = announcementInterval,
            wifiAware = wifi,
            nostr = nostr
        )
    }

    private fun wifi(
        tcpSeconds: Long,
        discoverySeconds: Long,
        maintenanceSeconds: Long,
        idleMinutes: Long,
        minRefreshMinutes: Long,
        staleMinutes: Long
    ) = PowerManager.WifiAwareSchedule(
        tcpKeepAliveMs = tcpSeconds * 1_000L,
        discoveryKeepAliveMs = discoverySeconds * 1_000L,
        connectionMaintenanceMs = maintenanceSeconds * 1_000L,
        discoveryIdleRefreshMs = idleMinutes * 60_000L,
        discoverySessionRefreshMinMs = minRefreshMinutes * 60_000L,
        discoveryStaleMs = staleMinutes * 60_000L
    )
}

package com.bitchat.android.mesh

import com.bitchat.android.model.PeerCapabilities
import com.bitchat.android.noise.AuthenticatedNoiseSession

internal sealed interface PrivateMediaPolicyDecision {
    data class Encrypted(
        val authenticatedSession: AuthenticatedNoiseSession
    ) : PrivateMediaPolicyDecision
    data object RequiresLegacyConsent : PrivateMediaPolicyDecision
    data object NeedsHandshake : PrivateMediaPolicyDecision
    data object AwaitingPeerState : PrivateMediaPolicyDecision
    data class Blocked(val reason: String) : PrivateMediaPolicyDecision
}

/**
 * Binds an advertised private-media capability to a live Noise remote-static
 * key and persists an HSTS-style pin by that authenticated key's SHA-256
 * fingerprint. Announcements alone can never create a pin.
 */
internal class PrivateMediaSecurityController(
    private val authenticatedSessionProvider: (String) -> AuthenticatedNoiseSession?,
    private val peerStateStatusProvider: (
        String,
        AuthenticatedNoiseSession
    ) -> AuthenticatedPeerStateStatus,
    private val isPrivateMediaPinned: (String) -> Boolean
) {
    fun sendPolicy(peerID: String): PrivateMediaPolicyDecision {
        val authenticatedSession = authenticatedSessionProvider(peerID)
            ?.takeIf { it.remoteStaticKey.size == 32 && it.sessionToken.size == 32 }
            ?: return PrivateMediaPolicyDecision.NeedsHandshake

        return when (val status = peerStateStatusProvider(peerID, authenticatedSession)) {
            AuthenticatedPeerStateStatus.Awaiting -> PrivateMediaPolicyDecision.AwaitingPeerState
            is AuthenticatedPeerStateStatus.Proven -> {
                if (status.state.capabilities.contains(PeerCapabilities.PRIVATE_MEDIA)) {
                    PrivateMediaPolicyDecision.Encrypted(authenticatedSession)
                } else if (isPrivateMediaPinned(peerID)) {
                    PrivateMediaPolicyDecision.Blocked(
                        "Encrypted private media was previously pinned, but this session proved no support; send blocked"
                    )
                } else {
                    PrivateMediaPolicyDecision.RequiresLegacyConsent
                }
            }
            AuthenticatedPeerStateStatus.Missing ->
                // A live crypto session can become visible just before its authenticated callback
                // installs the coordinator generation. Never treat that gap as a watchdog timeout.
                PrivateMediaPolicyDecision.AwaitingPeerState
            AuthenticatedPeerStateStatus.TimedOut -> {
                if (isPrivateMediaPinned(peerID)) {
                    PrivateMediaPolicyDecision.Blocked(
                        "Encrypted private media was previously pinned, but this session did not provide authenticated peer state"
                    )
                } else {
                    // A Noise-capable old client that does not know 0x21 may use explicit one-shot
                    // legacy consent after the five-second generation watchdog.
                    PrivateMediaPolicyDecision.RequiresLegacyConsent
                }
            }
        }
    }
}

package com.bitchat.android.mesh

import com.bitchat.android.model.BitchatFilePacket
import com.bitchat.android.model.NoisePayload
import com.bitchat.android.model.NoisePayloadType
import com.bitchat.android.noise.AuthenticatedNoiseSession
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import java.util.concurrent.atomic.AtomicBoolean

enum class PrivateMediaWireMode {
    ENCRYPTED_NOISE_0X20,
    SIGNED_DIRECTED_RAW_0X22
}

class PreparedPrivateMediaTransfer internal constructor(
    val transferId: String,
    val wireMode: PrivateMediaWireMode,
    private val commitAction: () -> Boolean
) {
    private val committed = AtomicBoolean(false)

    /** A prepared transfer is single-use, including after a failed commit. */
    fun commit(): Boolean {
        if (!committed.compareAndSet(false, true)) return false
        return commitAction()
    }
}

sealed interface PrivateMediaPreparation {
    data class Ready(val transfer: PreparedPrivateMediaTransfer) : PrivateMediaPreparation
    data class RequiresLegacyConsent(val warning: String) : PrivateMediaPreparation
    data object NeedsHandshake : PrivateMediaPreparation
    data object AwaitingPeerState : PrivateMediaPreparation
    data class Rejected(val reason: String) : PrivateMediaPreparation
}

internal data class BuiltPrivateMediaTransfer(
    val packet: BitchatPacket,
    val fragments: List<BitchatPacket>,
    val wireMode: PrivateMediaWireMode
)

internal sealed interface PrivateMediaBuildOutcome {
    data class Ready(val built: BuiltPrivateMediaTransfer) : PrivateMediaBuildOutcome
    data class RequiresLegacyConsent(val warning: String) : PrivateMediaBuildOutcome
    data object NeedsHandshake : PrivateMediaBuildOutcome
    data object AwaitingPeerState : PrivateMediaBuildOutcome
    data class Rejected(val reason: String) : PrivateMediaBuildOutcome
}

internal sealed interface PrivateMediaEncryptionResult {
    data class Success(val ciphertext: ByteArray) : PrivateMediaEncryptionResult
    data object GenerationChanged : PrivateMediaEncryptionResult
    data object Failed : PrivateMediaEncryptionResult
}

/** Builds, routes, signs, and fragments exactly once before UI local echo. */
internal class PrivateMediaTransferPreparer(
    private val senderID: ByteArray,
    private val ttl: UByte,
    private val policyProvider: (String) -> PrivateMediaPolicyDecision,
    private val encrypt: (
        ByteArray,
        String,
        AuthenticatedNoiseSession
    ) -> PrivateMediaEncryptionResult,
    private val finalizeRoutedAndSigned: (BitchatPacket) -> BitchatPacket?,
    private val fragment: (BitchatPacket, Int) -> List<BitchatPacket>,
    private val now: () -> ULong = { System.currentTimeMillis().toULong() }
) {
    fun prepare(
        recipientPeerID: String,
        recipientID: ByteArray,
        file: BitchatFilePacket,
        allowLegacyFallback: Boolean
    ): PrivateMediaBuildOutcome = prepare(
        recipientPeerID,
        recipientID,
        file,
        allowLegacyFallback,
        generationRetriesRemaining = 1
    )

    private fun prepare(
        recipientPeerID: String,
        recipientID: ByteArray,
        file: BitchatFilePacket,
        allowLegacyFallback: Boolean,
        generationRetriesRemaining: Int
    ): PrivateMediaBuildOutcome {
        val maxPrivateFragments =
            com.bitchat.android.util.AppConstants.Fragmentation.MAX_FRAGMENTS_PER_ID
        val absolutePayloadUpperBound =
            maxPrivateFragments.toLong() *
                com.bitchat.android.util.AppConstants.Fragmentation.MAX_FRAGMENT_SIZE.toLong()
        // The file content alone cannot exceed the total bytes carried by every
        // possible fragment. Reject before TLV encoding, encryption, signing,
        // and packet serialization make additional full-size copies.
        if (file.content.size.toLong() > absolutePayloadUpperBound) {
            return PrivateMediaBuildOutcome.Rejected(
                "File exceeds the private-media v1 limit of 256 final mesh fragments"
            )
        }

        val policy = policyProvider(recipientPeerID)
        val mode = when (policy) {
            is PrivateMediaPolicyDecision.Encrypted -> PrivateMediaWireMode.ENCRYPTED_NOISE_0X20
            PrivateMediaPolicyDecision.RequiresLegacyConsent -> {
                if (!allowLegacyFallback) {
                    return PrivateMediaBuildOutcome.RequiresLegacyConsent(
                        "This older client cannot receive encrypted private media. " +
                            "Sending this one file will expose its contents to mesh relays, " +
                            "although the directed packet will still be signed."
                    )
                }
                PrivateMediaWireMode.SIGNED_DIRECTED_RAW_0X22
            }
            PrivateMediaPolicyDecision.NeedsHandshake ->
                return PrivateMediaBuildOutcome.NeedsHandshake
            PrivateMediaPolicyDecision.AwaitingPeerState ->
                return PrivateMediaBuildOutcome.AwaitingPeerState
            is PrivateMediaPolicyDecision.Blocked ->
                return PrivateMediaBuildOutcome.Rejected(policy.reason)
        }

        val filePayload = file.encode()
            ?: return PrivateMediaBuildOutcome.Rejected("Failed to encode private media")

        val packet = when (mode) {
            PrivateMediaWireMode.ENCRYPTED_NOISE_0X20 -> {
                val plaintext = NoisePayload(NoisePayloadType.FILE_TRANSFER, filePayload).encode()
                val encryption = try {
                    encrypt(
                        plaintext,
                        recipientPeerID,
                        (policy as PrivateMediaPolicyDecision.Encrypted).authenticatedSession
                    )
                } catch (_: Exception) {
                    PrivateMediaEncryptionResult.Failed
                }
                val ciphertext = when (encryption) {
                    is PrivateMediaEncryptionResult.Success -> encryption.ciphertext
                    PrivateMediaEncryptionResult.GenerationChanged -> {
                        if (generationRetriesRemaining > 0) {
                            return prepare(
                                recipientPeerID,
                                recipientID,
                                file,
                                allowLegacyFallback,
                                generationRetriesRemaining - 1
                            )
                        }
                        return PrivateMediaBuildOutcome.AwaitingPeerState
                    }
                    PrivateMediaEncryptionResult.Failed ->
                        return PrivateMediaBuildOutcome.Rejected(
                            "The authenticated Noise session could not encrypt this file"
                        )
                }
                BitchatPacket(
                    version = if (ciphertext.size > 0xFFFF) 2u else 1u,
                    type = MessageType.NOISE_ENCRYPTED.value,
                    senderID = senderID.copyOf(),
                    recipientID = recipientID.copyOf(),
                    timestamp = now(),
                    payload = ciphertext,
                    signature = null,
                    ttl = ttl
                )
            }

            PrivateMediaWireMode.SIGNED_DIRECTED_RAW_0X22 -> BitchatPacket(
                version = 2u,
                type = MessageType.FILE_TRANSFER.value,
                senderID = senderID.copyOf(),
                recipientID = recipientID.copyOf(),
                timestamp = now(),
                payload = filePayload,
                signature = null,
                ttl = ttl
            )
        }

        val finalized = finalizeRoutedAndSigned(packet)
            ?: return PrivateMediaBuildOutcome.Rejected(
                if (mode == PrivateMediaWireMode.SIGNED_DIRECTED_RAW_0X22) {
                    "Could not sign the legacy private-media packet; nothing was sent"
                } else {
                    "Could not sign the encrypted private-media packet; nothing was sent"
                }
            )
        if (finalized.signature?.size != 64) {
            return PrivateMediaBuildOutcome.Rejected(
                "Could not produce a valid Ed25519 private-media signature; nothing was sent"
            )
        }

        val fragments = fragment(finalized, maxPrivateFragments)
        if (fragments.isEmpty()) {
            return PrivateMediaBuildOutcome.Rejected(
                "File exceeds the private-media v1 limit of 256 final mesh fragments"
            )
        }
        if (fragments.size > maxPrivateFragments) {
            return PrivateMediaBuildOutcome.Rejected(
                "File exceeds the private-media v1 limit of 256 final mesh fragments"
            )
        }

        return PrivateMediaBuildOutcome.Ready(
            BuiltPrivateMediaTransfer(finalized, fragments, mode)
        )
    }
}

package com.bitchat.android.mesh

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

/**
 * Sends small idempotent control packets redundantly while serializing the attempts submitted
 * through this sender. Android BLE only reports that a GATT write/notification was accepted;
 * it does not prove that the remote application processed the packet. Reusing the exact encoded
 * packet makes retries safe: the receiver's packet/replay protection drops copies it already saw.
 */
internal class RetryingControlPacketSender(
    private val scope: CoroutineScope,
    private val maxAttempts: Int = 3,
    private val retryDelayMs: Long = 750L,
    private val interSendDelayMs: Long = 75L
) {
    private val sendMutex = Mutex()
    private val jobsLock = Any()
    private val activeJobs = mutableMapOf<String, Job>()

    init {
        require(maxAttempts > 0)
        require(retryDelayMs >= 0)
        require(interSendDelayMs >= 0)
    }

    /**
     * Coalesces concurrent requests for the same logical packet. Once the retry window finishes,
     * a later user action may enqueue the packet again; duplicate receipt processing is idempotent.
     */
    fun enqueue(
        key: String,
        sendAttempt: suspend (attempt: Int) -> Boolean,
        onComplete: (acceptedAtLeastOnce: Boolean) -> Unit = {}
    ) {
        val job = synchronized(jobsLock) {
            if (activeJobs[key]?.isActive == true) return

            scope.launch(start = CoroutineStart.LAZY) {
                var acceptedAtLeastOnce = false
                var completed = false
                try {
                    repeat(maxAttempts) { index ->
                        if (!isActive) return@launch
                        val attempt = index + 1
                        sendMutex.withLock {
                            try {
                                val accepted = try {
                                    sendAttempt(attempt)
                                } catch (_: Exception) {
                                    false
                                }
                                acceptedAtLeastOnce = accepted || acceptedAtLeastOnce
                            } finally {
                                if (interSendDelayMs > 0) delay(interSendDelayMs)
                            }
                        }
                        if (attempt < maxAttempts && retryDelayMs > 0) {
                            delay(retryDelayMs)
                        }
                    }
                    completed = true
                } finally {
                    synchronized(jobsLock) {
                        activeJobs.remove(key)
                    }
                    if (completed) {
                        try { onComplete(acceptedAtLeastOnce) } catch (_: Exception) { }
                    }
                }
            }.also { activeJobs[key] = it }
        }
        job.start()
    }
}

package com.bitchat.android.mesh

import android.util.Log
import com.bitchat.android.crypto.EncryptionService
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.noise.AuthenticatedNoiseSession
import com.bitchat.android.noise.NoiseDecryptionResult
import com.bitchat.android.util.toHexString
import kotlinx.coroutines.*
import java.util.*
import kotlin.collections.mutableSetOf

/**
 * Manages security aspects of the mesh network including duplicate detection,
 * replay attack protection, and key exchange handling
 * Extracted from BluetoothMeshService for better separation of concerns
 */
class SecurityManager(private val encryptionService: EncryptionService, private val myPeerID: String) {

    companion object {
        private const val TAG = "SecurityManager"
        private const val MESSAGE_TIMEOUT = com.bitchat.android.util.AppConstants.Security.MESSAGE_TIMEOUT_MS // 5 minutes (same as iOS)
        private const val CLEANUP_INTERVAL = com.bitchat.android.util.AppConstants.Security.CLEANUP_INTERVAL_MS // 5 minutes
        private const val MAX_PROCESSED_MESSAGES = com.bitchat.android.util.AppConstants.Security.MAX_PROCESSED_MESSAGES
        private const val MAX_PROCESSED_KEY_EXCHANGES = com.bitchat.android.util.AppConstants.Security.MAX_PROCESSED_KEY_EXCHANGES
        private const val KEY_EXCHANGE_DEDUP_TIMEOUT = com.bitchat.android.util.AppConstants.Security.KEY_EXCHANGE_DEDUP_TIMEOUT_MS
    }

    // Security tracking
    private val processedMessages = Collections.synchronizedSet(mutableSetOf<String>())
    private val processedKeyExchanges = Collections.synchronizedSet(mutableSetOf<String>())
    private val messageTimestamps = Collections.synchronizedMap(mutableMapOf<String, Long>())
    private val keyExchangeTimestamps = Collections.synchronizedMap(mutableMapOf<String, Long>())

    // Delegate for callbacks
    var delegate: SecurityManagerDelegate? = null

    // Coroutines
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    init {
        startPeriodicCleanup()
    }

    /**
     * Validate packet security (timestamp, replay attacks, duplicates, signatures)
     */
    fun validatePacket(packet: BitchatPacket, peerID: String): Boolean {
        // Skip validation for our own packets
        if (peerID == myPeerID) {
            return false
        }

        // Replay attack protection (same 5-minute window as iOS)
        val currentTime = System.currentTimeMillis()
        val messageType = MessageType.fromValue(packet.type)

        // LEAVE mutates presence immediately and cannot be safely replayed after the in-memory
        // duplicate cache expires (or after an app restart). Bound it to the same five-minute
        // security window used for duplicate retention while tolerating symmetric clock skew.
        if (messageType == MessageType.LEAVE) {
            val now = currentTime.coerceAtLeast(0).toULong()
            val clockSkew = if (packet.timestamp >= now) {
                packet.timestamp - now
            } else {
                now - packet.timestamp
            }
            if (clockSkew > MESSAGE_TIMEOUT.toULong()) {
                Log.w(TAG, "Dropping stale or future-dated LEAVE from $peerID")
                return false
            }
        }

        // Duplicate detection
        val messageID = generateMessageID(packet, peerID)

        if (processedMessages.contains(messageID)) {
            // Check for ANNOUNCE exception: allow if it looks like a direct neighbor (max TTL)
            // This ensures we observe the same peer on a new direct transport connection,
            // while still dropping looped/relayed duplicates.
            val isFreshAnnounce = messageType == MessageType.ANNOUNCE &&
                    packet.ttl >= com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS

            if (!isFreshAnnounce) {
                return false
            }
        }

        // Enforce mandatory signature verification
        if (!verifyPacketSignature(packet, peerID)) {
            return false
        }

        // Record only authenticated packets. Recording an attacker-controlled
        // invalid packet first would let it poison duplicate detection for a
        // later legitimate packet with the same timestamp and payload.
        processedMessages.add(messageID)
        messageTimestamps[messageID] = currentTime

        return true
    }

    /**
     * Handle Noise handshake packet - SIMPLIFIED iOS-compatible version
     * Single handshake type with automatic response handling
     */
    suspend fun handleNoiseHandshake(routed: RoutedPacket): Boolean {
        val packet = routed.packet
        val peerID = routed.peerID ?: "unknown"

        // Skip handshakes not addressed to us
        if (packet.recipientID?.toHexString() != myPeerID) {
            return false
        }

        // Skip our own handshake messages
        if (peerID == myPeerID) return false

        if (packet.payload.isEmpty()) {
            Log.d(TAG, "Noise handshake packet has empty payload")
            return false
        }

        // Prevent duplicate handshake processing
        val exchangeKey = "$peerID-${packet.payload.sliceArray(0 until minOf(16, packet.payload.size)).contentHashCode()}"

        if (processedKeyExchanges.contains(exchangeKey)) {
            return false
        }

        try {
            // The session manager preserves an existing transport in a separate responder-candidate
            // flow and reports whether this exact frame completed authentication. Never infer that
            // from ambient session state: a rejected replacement may leave the old session active.
            val result = encryptionService.processHandshakeMessageWithResult(packet.payload, peerID)
            processedKeyExchanges.add(exchangeKey)
            keyExchangeTimestamps[exchangeKey] = System.currentTimeMillis()

            if (result.response != null) {
                // Send handshake response through delegate
                delegate?.sendHandshakeResponse(peerID, result.response)
            }
            if (result.establishedNow) {
                val authenticatedRemoteStaticKey = result.authenticatedRemoteStaticKey
                if (authenticatedRemoteStaticKey == null) {
                    Log.e(TAG, "Bound Noise completion for $peerID omitted its authenticated static key")
                    return false
                }
                val authenticatedSessionToken = result.authenticatedSessionToken
                if (authenticatedSessionToken?.size != 32 ||
                    authenticatedSessionToken.all { it == 0.toByte() }
                ) {
                    Log.e(TAG, "Bound Noise completion for $peerID omitted its generation token")
                    return false
                }
                val isDirectIngress = packet.ttl == com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS
                Log.i(TAG, "Noise handshake completed with $peerID")
                delegate?.onKeyExchangeCompleted(
                    peerID = peerID,
                    authenticatedRemoteStaticKey = authenticatedRemoteStaticKey,
                    authenticatedSessionToken = authenticatedSessionToken,
                    directRelayAddress = routed.relayAddress.takeIf { isDirectIngress },
                    ingressLinkID = routed.ingressLinkID.takeIf { isDirectIngress }
                )
            }
            return true


        } catch (e: Exception) {
            Log.w(TAG, "Failed to process Noise handshake from $peerID: ${e.message}")
            return false
        }
    }

    /**
     * Verify a packet signature against the signing key learned from the
     * peer's verified announcement. Signatures cover the canonical packet,
     * not only its payload; otherwise routing and recipient fields could be
     * changed without invalidating the signature.
     */
    fun verifySignature(packet: BitchatPacket, peerID: String): Boolean {
        return verifyPacketSignature(packet, peerID)
    }

    /**
     * Sign packet payload
     */
    fun signPacket(payload: ByteArray): ByteArray? {
        return try {
            encryptionService.sign(payload)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to sign packet: ${e.message}")
            null
        }
    }

    /**
     * Encrypt payload for specific peer
     */
    fun encryptForPeer(data: ByteArray, recipientPeerID: String): ByteArray? {
        return try {
            encryptionService.encrypt(data, recipientPeerID)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encrypt for $recipientPeerID: ${e.message}")
            null
        }
    }

    fun encryptForPeer(
        data: ByteArray,
        recipientPeerID: String,
        expectedSession: AuthenticatedNoiseSession
    ): ByteArray? = try {
        encryptionService.encryptForSession(data, recipientPeerID, expectedSession)
    } catch (e: Exception) {
        Log.e(TAG, "Noise generation changed before encrypting for $recipientPeerID: ${e.message}")
        null
    }

    /**
     * Decrypt payload from specific peer
     */
    fun decryptFromPeer(encryptedData: ByteArray, senderPeerID: String): NoiseDecryptionResult? {
        return try {
            encryptionService.decryptWithSession(encryptedData, senderPeerID)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decrypt from $senderPeerID: ${e.message}")
            null
        }
    }

    /**
     * Get combined public key data for key exchange
     */
    fun getCombinedPublicKeyData(): ByteArray {
        return encryptionService.getCombinedPublicKeyData()
    }

    /**
     * Generate message ID for duplicate detection
     */
    private fun generateMessageID(packet: BitchatPacket, peerID: String): String {
        return when (MessageType.fromValue(packet.type)) {
            MessageType.FRAGMENT -> {
                // For fragments, include the payload hash to distinguish different fragments
                "${packet.timestamp}-$peerID-${packet.type}-${packet.payload.contentHashCode()}"
            }
            else -> {
                // For other messages, use a truncated payload hash
                val payloadHash = packet.payload.sliceArray(0 until minOf(64, packet.payload.size)).contentHashCode()
                "${packet.timestamp}-$peerID-$payloadHash"
            }
        }
    }

    /**
     * Verify packet signature using peer's signing public key
     * Returns true only if signature is present and valid
     */
    private fun verifyPacketSignature(packet: BitchatPacket, peerID: String): Boolean {
        try {
            // Public packets that mutate identity, presence, or user-visible state must prove the
            // signing key learned from a verified announcement. LEAVE is included so an attacker
            // cannot evict a claimed peer or amplify a forged departure through relay.
            if (MessageType.fromValue(packet.type) !in setOf(
                    MessageType.ANNOUNCE,
                    MessageType.MESSAGE,
                    MessageType.FILE_TRANSFER,
                    MessageType.VOICE_FRAME,
                    MessageType.LEAVE
                )) {
                return true
            }

            if (MessageType.fromValue(packet.type) == MessageType.ANNOUNCE) {
                val announcement = AnnouncementIdentityValidator.verify(packet, peerID) { signature, data, key ->
                    encryptionService.verifyEd25519Signature(signature, data, key)
                } ?: run {
                    Log.w(TAG, "Rejecting malformed, unbound, or invalidly signed ANNOUNCE from $peerID")
                    return false
                }

                val persistedSigningKey = delegate?.getAuthenticatedSigningKey(announcement.noisePublicKey)
                if (persistedSigningKey != null &&
                    !persistedSigningKey.contentEquals(announcement.signingPublicKey)
                ) {
                    Log.w(TAG, "Rejecting ANNOUNCE Ed key that conflicts with authenticated peer state for $peerID")
                    return false
                }

                val existingPeer = delegate?.getPeerInfo(peerID)
                if (
                    existingPeer?.noisePublicKey != null &&
                    !existingPeer.noisePublicKey!!.contentEquals(announcement.noisePublicKey)
                ) {
                    Log.w(TAG, "Rejecting ANNOUNCE Noise-key replacement for $peerID")
                    return false
                }
                if (
                    existingPeer?.signingPublicKey != null &&
                    !existingPeer.signingPublicKey!!.contentEquals(announcement.signingPublicKey)
                ) {
                    Log.w(TAG, "Rejecting ANNOUNCE signing-key replacement without authenticated peer state for $peerID")
                    return false
                }
                return true
            }

            // 1. Mandatory Signature Check
            if (packet.signature == null) {
                Log.w(TAG, "Signature check for $peerID: NO_SIGNATURE (packet type ${packet.type})")
                return false
            }

            // 2. Get Signing Public Key
            val peerInfo = delegate?.getPeerInfo(peerID)
            val signingPublicKey = peerInfo?.signingPublicKey

            if (signingPublicKey == null) {
                // If we don't have a key (and it's not an announce), we can't verify.
                // For security, we must reject packets from unknown peers unless it's an announce.
                Log.w(TAG, "Signature check for $peerID: NO_SIGNING_KEY_AVAILABLE (packet type ${packet.type})")
                return false
            }

            // 3. Get Canonical Data
            val packetDataForSigning = packet.toBinaryDataForSigning()
            if (packetDataForSigning == null) {
                Log.w(TAG, "Signature check for $peerID: ENCODING_ERROR (packet type ${packet.type})")
                return false
            }

            // 4. Verify Signature
            val signature = packet.signature!!
            val isSignatureValid = encryptionService.verifyEd25519Signature(
                signature,
                packetDataForSigning,
                signingPublicKey
            )

            if (isSignatureValid) {
                return true
            } else {
                Log.w(TAG, "Signature INVALID for $peerID (type ${packet.type})")
                return false
            }

        } catch (e: Exception) {
            Log.e(TAG, "Signature verification error for $peerID: ${e.message}")
            return false
        }
    }

    /**
     * Check if we have encryption keys for a peer
     */
    fun hasKeysForPeer(peerID: String): Boolean {
        return encryptionService.hasEstablishedSession(peerID)
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Security Manager Debug Info ===")
            appendLine("Processed Messages: ${processedMessages.size}")
            appendLine("Processed Key Exchanges: ${processedKeyExchanges.size}")
            appendLine("Message Timestamps: ${messageTimestamps.size}")

            if (processedKeyExchanges.isNotEmpty()) {
                appendLine("Key Exchange History:")
                processedKeyExchanges.take(10).forEach { exchange ->
                    appendLine("  - $exchange")
                }
                if (processedKeyExchanges.size > 10) {
                    appendLine("  ... and ${processedKeyExchanges.size - 10} more")
                }
            }
        }
    }

    /**
     * Start periodic cleanup
     */
    private fun startPeriodicCleanup() {
        managerScope.launch {
            while (isActive) {
                delay(CLEANUP_INTERVAL)
                cleanupOldData()
            }
        }
    }

    /**
     * Clean up old processed messages and timestamps
     */
    internal fun cleanupOldData(nowMs: Long = System.currentTimeMillis()) {
        val cutoffTime = nowMs - MESSAGE_TIMEOUT

        // Clean up old message timestamps and corresponding processed messages
        val messagesToRemove = messageTimestamps.entries.filter { (_, timestamp) ->
            timestamp < cutoffTime
        }.map { it.key }

        messagesToRemove.forEach { messageId ->
            messageTimestamps.remove(messageId)
            processedMessages.remove(messageId)
        }

        // Limit the size of processed messages set
        if (processedMessages.size > MAX_PROCESSED_MESSAGES) {
            val excess = processedMessages.size - MAX_PROCESSED_MESSAGES
            val toRemove = processedMessages.take(excess)
            processedMessages.removeAll(toRemove.toSet())
            removeFromMessageTimestamps(toRemove)
        }

        // Expire handshake dedup entries by time so a delayed same-ephemeral delivery
        // (e.g. a re-handshake retry after a failed attempt) is not blocked forever.
        val keyExchangeCutoff = nowMs - KEY_EXCHANGE_DEDUP_TIMEOUT
        val keyExchangesToRemove = keyExchangeTimestamps.entries.filter { (_, timestamp) ->
            timestamp < keyExchangeCutoff
        }.map { it.key }

        keyExchangesToRemove.forEach { exchangeKey ->
            keyExchangeTimestamps.remove(exchangeKey)
            processedKeyExchanges.remove(exchangeKey)
        }

        // Limit the size of processed key exchanges set
        if (processedKeyExchanges.size > MAX_PROCESSED_KEY_EXCHANGES) {
            val excess = processedKeyExchanges.size - MAX_PROCESSED_KEY_EXCHANGES
            val toRemove = processedKeyExchanges.take(excess)
            processedKeyExchanges.removeAll(toRemove.toSet())
            toRemove.forEach { keyExchangeTimestamps.remove(it) }
        }
    }

    /**
     * Helper to remove entries from messageTimestamps
     */
    private fun removeFromMessageTimestamps(messageIds: List<String>) {
        messageIds.forEach { messageId ->
            messageTimestamps.remove(messageId)
        }
    }

    /**
     * Clear all security data
     */
    fun clearAllData() {
        processedMessages.clear()
        processedKeyExchanges.clear()
        messageTimestamps.clear()
        keyExchangeTimestamps.clear()
    }

    /**
     * Shutdown the manager
     */
    fun shutdown() {
        managerScope.cancel()
        clearAllData()
    }
}

/**
 * Delegate interface for security manager callbacks
 */
interface SecurityManagerDelegate {
    fun onKeyExchangeCompleted(
        peerID: String,
        authenticatedRemoteStaticKey: ByteArray,
        authenticatedSessionToken: ByteArray,
        directRelayAddress: String?,
        ingressLinkID: String?
    )
    fun sendHandshakeResponse(peerID: String, response: ByteArray)
    fun getPeerInfo(peerID: String): PeerInfo? // NEW: For signature verification
    fun getAuthenticatedSigningKey(noisePublicKey: ByteArray): ByteArray? = null
}

package com.bitchat.android.mesh

import android.util.Log
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.protocol.SpecialRecipients
import kotlinx.coroutines.*
import java.util.*
import java.util.concurrent.ConcurrentHashMap

/**
 * Manages store-and-forward messaging for offline peers
 * Extracted from BluetoothMeshService for better separation of concerns
 */
class StoreForwardManager {

    companion object {
        private const val TAG = "StoreForwardManager"
        private const val MESSAGE_CACHE_TIMEOUT = com.bitchat.android.util.AppConstants.StoreForward.MESSAGE_CACHE_TIMEOUT_MS  // 12 hours for regular peers
        private const val MAX_CACHED_MESSAGES = com.bitchat.android.util.AppConstants.StoreForward.MAX_CACHED_MESSAGES  // For regular peers
        private const val MAX_CACHED_MESSAGES_FAVORITES = com.bitchat.android.util.AppConstants.StoreForward.MAX_CACHED_MESSAGES_FAVORITES  // For favorites
        private const val CLEANUP_INTERVAL = com.bitchat.android.util.AppConstants.StoreForward.CLEANUP_INTERVAL_MS // 10 minutes
    }

    /**
     * Data class for stored messages
     */
    private data class StoredMessage(
        val packet: BitchatPacket,
        val timestamp: Long,
        val messageID: String,
        val isForFavorite: Boolean
    )

    // Message storage
    private val messageCache = Collections.synchronizedList(mutableListOf<StoredMessage>())
    private val favoriteMessageQueue = ConcurrentHashMap<String, MutableList<StoredMessage>>()
    private val deliveredMessages = Collections.synchronizedSet(mutableSetOf<String>())
    private val cachedMessagesSentToPeer = Collections.synchronizedSet(mutableSetOf<String>())

    // Delegate for callbacks
    var delegate: StoreForwardManagerDelegate? = null

    // Coroutines
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    init {
        startPeriodicCleanup()
    }

    /**
     * Cache message for offline delivery
     */
    fun cacheMessage(packet: BitchatPacket, messageID: String) {
        // Skip certain message types (same as iOS)
        if (packet.type == MessageType.NOISE_HANDSHAKE.value ||
            packet.type == MessageType.NOISE_ENCRYPTED.value ||
            packet.type == MessageType.ANNOUNCE.value ||
            packet.type == MessageType.LEAVE.value) {
            Log.d(TAG, "Skipping cache for message type: ${packet.type}")
            return
        }

        // Don't cache broadcast messages
        if (packet.recipientID != null && packet.recipientID.contentEquals(SpecialRecipients.BROADCAST)) {
            Log.d(TAG, "Skipping cache for broadcast message")
            return
        }

        // Determine if this is for a favorite peer
        val recipientPeerID = packet.recipientID?.let { recipientID ->
            String(recipientID).replace("\u0000", "")
        }

        if (recipientPeerID.isNullOrEmpty()) {
            Log.w(TAG, "Cannot cache message without valid recipient")
            return
        }

        val isForFavorite = delegate?.isFavorite(recipientPeerID) ?: false

        val storedMessage = StoredMessage(
            packet = packet,
            timestamp = System.currentTimeMillis(),
            messageID = messageID,
            isForFavorite = isForFavorite
        )

        if (isForFavorite) {
            // Store in favorite queue
            if (!favoriteMessageQueue.containsKey(recipientPeerID)) {
                favoriteMessageQueue[recipientPeerID] = mutableListOf()
            }
            favoriteMessageQueue[recipientPeerID]?.add(storedMessage)

            // Limit favorite queue size
            if (favoriteMessageQueue[recipientPeerID]?.size ?: 0 > MAX_CACHED_MESSAGES_FAVORITES) {
                favoriteMessageQueue[recipientPeerID]?.removeAt(0)
            }

            Log.d(TAG, "Cached message for favorite peer $recipientPeerID (${favoriteMessageQueue[recipientPeerID]?.size} total)")

        } else {
            // Store in regular cache
            cleanupMessageCache()

            messageCache.add(storedMessage)

            // Limit cache size
            if (messageCache.size > MAX_CACHED_MESSAGES) {
                messageCache.removeAt(0)
            }

            Log.d(TAG, "Cached message for peer $recipientPeerID (${messageCache.size} total in cache)")
        }
    }

    /**
     * Send cached messages to peer when they come online
     */
    fun sendCachedMessages(peerID: String) {
        if (cachedMessagesSentToPeer.contains(peerID)) {
            Log.d(TAG, "Already sent cached messages to $peerID")
            return // Already sent cached messages to this peer
        }

        cachedMessagesSentToPeer.add(peerID)

        managerScope.launch {
            cleanupMessageCache()

            val messagesToSend = mutableListOf<StoredMessage>()

            // Check favorite queue
            favoriteMessageQueue[peerID]?.let { favoriteMessages ->
                val undeliveredFavorites = favoriteMessages.filter { !deliveredMessages.contains(it.messageID) }
                messagesToSend.addAll(undeliveredFavorites)
                favoriteMessageQueue.remove(peerID)
                Log.d(TAG, "Found ${undeliveredFavorites.size} cached favorite messages for $peerID")
            }

            // Filter regular cached messages for this recipient
            val recipientMessages = messageCache.filter { storedMessage ->
                !deliveredMessages.contains(storedMessage.messageID) &&
                storedMessage.packet.recipientID?.let { recipientID ->
                    String(recipientID).replace("\u0000", "") == peerID
                } == true
            }
            messagesToSend.addAll(recipientMessages)

            if (recipientMessages.isNotEmpty()) {
                Log.d(TAG, "Found ${recipientMessages.size} cached regular messages for $peerID")
            }

            // Sort by timestamp
            messagesToSend.sortBy { it.timestamp }

            if (messagesToSend.isNotEmpty()) {
                Log.i(TAG, "Sending ${messagesToSend.size} cached messages to $peerID")
            }

            // Mark as delivered
            val messageIDsToRemove = messagesToSend.map { it.messageID }
            deliveredMessages.addAll(messageIDsToRemove)

            // Send with delays to avoid overwhelming the connection
            messagesToSend.forEachIndexed { index, storedMessage ->
                delay(index * 10L) // 10ms between messages
                delegate?.sendPacket(storedMessage.packet)
            }

            // Remove sent messages from cache
            messageCache.removeAll { messageIDsToRemove.contains(it.messageID) }

            if (messagesToSend.isNotEmpty()) {
                Log.d(TAG, "Finished sending ${messagesToSend.size} cached messages to $peerID")
            }
        }
    }

    /**
     * Check if message should be cached for peer
     */
    fun shouldCacheForPeer(recipientPeerID: String): Boolean {
        // Check if recipient is offline and should cache for favorites
        val isOffline = !(delegate?.isPeerOnline(recipientPeerID) ?: false)
        val isRecipientFavorite = delegate?.isFavorite(recipientPeerID) ?: false

        return isOffline && isRecipientFavorite
    }

    /**
     * Mark message as delivered
     */
    fun markMessageAsDelivered(messageID: String) {
        deliveredMessages.add(messageID)
    }

    /**
     * Get cached message count for peer
     */
    fun getCachedMessageCount(peerID: String): Int {
        val favoriteCount = favoriteMessageQueue[peerID]?.size ?: 0
        val regularCount = messageCache.count { storedMessage ->
            storedMessage.packet.recipientID?.let { recipientID ->
                String(recipientID).replace("\u0000", "") == peerID
            } == true
        }
        return favoriteCount + regularCount
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Store-Forward Manager Debug Info ===")
            appendLine("Regular Cache: ${messageCache.size}/${MAX_CACHED_MESSAGES}")
            appendLine("Favorite Queues: ${favoriteMessageQueue.size}")

            favoriteMessageQueue.forEach { (peerID, messages) ->
                appendLine("  - $peerID: ${messages.size} messages")
            }

            appendLine("Delivered Messages: ${deliveredMessages.size}")
            appendLine("Peers Sent Cache: ${cachedMessagesSentToPeer.size}")

            // Cache age analysis
            val now = System.currentTimeMillis()
            val regularCacheAges = messageCache.map { (now - it.timestamp) / 1000 }
            if (regularCacheAges.isNotEmpty()) {
                val avgAge = regularCacheAges.average().toInt()
                val maxAge = regularCacheAges.maxOrNull() ?: 0
                appendLine("Regular Cache Age: avg ${avgAge}s, max ${maxAge}s")
            }
        }
    }

    /**
     * Start periodic cleanup
     */
    private fun startPeriodicCleanup() {
        managerScope.launch {
            while (isActive) {
                delay(CLEANUP_INTERVAL)
                cleanupMessageCache()
                cleanupDeliveredMessages()
            }
        }
    }

    /**
     * Clean up old cached messages (not for favorites)
     */
    private fun cleanupMessageCache() {
        val cutoffTime = System.currentTimeMillis() - MESSAGE_CACHE_TIMEOUT
        val sizeBefore = messageCache.size
        val removed = messageCache.removeAll { !it.isForFavorite && it.timestamp < cutoffTime }

        if (removed) {
            val removedCount = sizeBefore - messageCache.size
            Log.d(TAG, "Cleaned up $removedCount old cached messages")
        }
    }

    /**
     * Clean up delivered messages set (prevent memory leak)
     */
    private fun cleanupDeliveredMessages() {
        if (deliveredMessages.size > 1000) {
            Log.d(TAG, "Clearing delivered messages set (${deliveredMessages.size} entries)")
            deliveredMessages.clear()
        }

        if (cachedMessagesSentToPeer.size > 200) {
            Log.d(TAG, "Clearing cached messages sent tracking (${cachedMessagesSentToPeer.size} entries)")
            cachedMessagesSentToPeer.clear()
        }
    }

    /**
     * Clear all cached data
     */
    fun clearAllCache() {
        messageCache.clear()
        favoriteMessageQueue.clear()
        deliveredMessages.clear()
        cachedMessagesSentToPeer.clear()
        Log.d(TAG, "Cleared all cached message data")
    }

    /**
     * Force cleanup for testing
     */
    fun forceCleanup() {
        cleanupMessageCache()
        cleanupDeliveredMessages()
    }

    /**
     * Shutdown the manager
     */
    fun shutdown() {
        managerScope.cancel()
        clearAllCache()
    }
}

/**
 * Delegate interface for store-forward manager callbacks
 */
interface StoreForwardManagerDelegate {
    fun isFavorite(peerID: String): Boolean
    fun isPeerOnline(peerID: String): Boolean
    fun sendPacket(packet: BitchatPacket)
}

package com.bitchat.android.mesh

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.launch

data class TransferProgressEvent(
    val transferId: String,
    val sent: Int,
    val total: Int,
    val completed: Boolean,
    val failed: Boolean = false
)

object TransferProgressManager {
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private val _events = MutableSharedFlow<TransferProgressEvent>(replay = 0, extraBufferCapacity = 32)
    val events: SharedFlow<TransferProgressEvent> = _events

    fun start(id: String, total: Int) { emit(id, 0, total, false) }
    fun progress(id: String, sent: Int, total: Int) { emit(id, sent, total, sent >= total) }
    fun complete(id: String, total: Int) { emit(id, total, total, true) }
    fun fail(id: String) { emit(id, 0, 0, done = true, failed = true) }

    private fun emit(id: String, sent: Int, total: Int, done: Boolean, failed: Boolean = false) {
        scope.launch { _events.emit(TransferProgressEvent(id, sent, total, done, failed)) }
    }
}

package com.bitchat.android.mesh

import android.content.Context
import android.util.Log
import com.bitchat.android.favorites.FavoriteControlMessage
import com.bitchat.android.model.BitchatFilePacket
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.noise.NoiseSession
import com.bitchat.android.wifiaware.WifiAwareController
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

/**
 * Feature-facing mesh service that hides local transport selection from the rest of the app.
 *
 * BLE remains the canonical origin for broadcast packets when it is enabled so existing BLE mesh
 * behavior and bridge semantics stay intact. Addressed Noise traffic is routed over whichever
 * local transport already has the peer/session, falling back to a connected transport handshake.
 */
class UnifiedMeshService(
    private val context: Context,
    private val bluetooth: BluetoothMeshService
) : MeshService, BluetoothMeshDelegate {

    companion object {
        private const val TAG = "UnifiedMeshService"
    }

    private val serviceScope = CoroutineScope(Dispatchers.Default + SupervisorJob())
    private val powerManager = PowerManager.getInstance(context.applicationContext)
    private var announcementJob: Job? = null

    override val myPeerID: String
        get() = bluetooth.myPeerID

    override var delegate: MeshDelegate? = null
        set(value) {
            field = value
            refreshDelegates()
        }

    fun refreshDelegates() {
        try { bluetooth.delegate = if (delegate != null) this else null } catch (_: Exception) { }
        try { wifiService()?.delegate = if (delegate != null) this else null } catch (_: Exception) { }
    }

    override fun startServices() {
        if (isBleEnabled()) {
            try { bluetooth.startServices() } catch (e: Exception) {
                Log.w(TAG, "Failed to start BLE transport: ${e.message}")
            }
        } else {
            try { bluetooth.setBleTransportEnabled(false) } catch (_: Exception) { }
        }
        try { WifiAwareController.startIfPossible() } catch (e: Exception) {
            Log.w(TAG, "Failed to start Wi-Fi Aware transport: ${e.message}")
        }
        startAnnouncementScheduler()
        refreshDelegates()
    }

    override fun stopServices() {
        announcementJob?.cancel()
        announcementJob = null
        try { bluetooth.stopServices() } catch (_: Exception) { }
        try { WifiAwareController.stop() } catch (_: Exception) { }
    }

    private fun startAnnouncementScheduler() {
        if (announcementJob?.isActive == true) return
        announcementJob = serviceScope.launch {
            powerManager.profile
                .map { profile ->
                    profile.meshAnnouncementIntervalMs to profile.hasDirectPeers
                }
                .distinctUntilChanged()
                .collectLatest { (intervalMs, hasRecipients) ->
                    if (!hasRecipients) return@collectLatest
                    // Connection-specific paths already send an immediate announce. Begin the
                    // periodic cadence after the configured interval to avoid a transition burst.
                    while (isActive) {
                        delay(intervalMs)
                        if (powerManager.profile.value.hasDirectPeers) sendBroadcastAnnounce()
                    }
                }
            }
    }

    override fun sendMessage(content: String, mentions: List<String>, channel: String?) {
        when {
            isBleEnabled() -> bluetooth.sendMessage(content, mentions, channel)
            else -> wifiService()?.sendMessage(content, mentions, channel)
        }
    }

    override fun sendPrivateMessage(
        content: String,
        recipientPeerID: String,
        recipientNickname: String,
        messageID: String?
    ) {
        when {
            isBleReady(recipientPeerID) -> bluetooth.sendPrivateMessage(content, recipientPeerID, recipientNickname, messageID)
            isWifiReady(recipientPeerID) -> wifiService()?.sendPrivateMessage(content, recipientPeerID, recipientNickname, messageID)
            isBleConnected(recipientPeerID) || (isBleEnabled() && !isWifiConnected(recipientPeerID)) ->
                bluetooth.sendPrivateMessage(content, recipientPeerID, recipientNickname, messageID)
            else -> wifiService()?.sendPrivateMessage(content, recipientPeerID, recipientNickname, messageID)
        }
    }

    override fun sendReadReceipt(messageID: String, recipientPeerID: String, readerNickname: String) {
        when {
            isBleReady(recipientPeerID) -> bluetooth.sendReadReceipt(messageID, recipientPeerID, readerNickname)
            isWifiReady(recipientPeerID) -> wifiService()?.sendReadReceipt(messageID, recipientPeerID, readerNickname)
        }
    }

    override fun sendFavoriteNotification(peerID: String, isFavorite: Boolean) {
        val myNpub = try {
            com.bitchat.android.nostr.NostrIdentityBridge.getCurrentNostrIdentity(context)?.npub
        } catch (_: Exception) {
            null
        }
        val content = FavoriteControlMessage.encode(isFavorite, myNpub)
        val nickname = getPeerNicknames()[peerID] ?: peerID
        if (hasEstablishedSession(peerID)) {
            sendPrivateMessage(content, peerID, nickname, java.util.UUID.randomUUID().toString())
        }
    }

    override fun sendVerifyChallenge(peerID: String, noiseKeyHex: String, nonceA: ByteArray) {
        when {
            isBleReady(peerID) -> bluetooth.sendVerifyChallenge(peerID, noiseKeyHex, nonceA)
            isWifiReady(peerID) -> wifiService()?.sendVerifyChallenge(peerID, noiseKeyHex, nonceA)
        }
    }

    override fun sendVerifyResponse(peerID: String, noiseKeyHex: String, nonceA: ByteArray) {
        when {
            isBleReady(peerID) -> bluetooth.sendVerifyResponse(peerID, noiseKeyHex, nonceA)
            isWifiReady(peerID) -> wifiService()?.sendVerifyResponse(peerID, noiseKeyHex, nonceA)
        }
    }

    override fun sendFileBroadcast(file: BitchatFilePacket) {
        when {
            isBleEnabled() -> bluetooth.sendFileBroadcast(file)
            else -> wifiService()?.sendFileBroadcast(file)
        }
    }

    override fun sendFilePrivate(recipientPeerID: String, file: BitchatFilePacket) {
        when {
            isBleReady(recipientPeerID) -> bluetooth.sendFilePrivate(recipientPeerID, file)
            isWifiReady(recipientPeerID) -> wifiService()?.sendFilePrivate(recipientPeerID, file)
            isBleConnected(recipientPeerID) || (isBleEnabled() && !isWifiConnected(recipientPeerID)) ->
                bluetooth.sendFilePrivate(recipientPeerID, file)
            else -> wifiService()?.sendFilePrivate(recipientPeerID, file)
        }
    }

    override fun sendVoiceFrame(recipientPeerID: String?, payload: ByteArray) {
        if (recipientPeerID == null) {
            when {
                isBleEnabled() -> bluetooth.sendVoiceFrame(null, payload)
                else -> wifiService()?.sendVoiceFrame(null, payload)
            }
            return
        }
        when {
            isBleReady(recipientPeerID) -> bluetooth.sendVoiceFrame(recipientPeerID, payload)
            isWifiReady(recipientPeerID) -> wifiService()?.sendVoiceFrame(recipientPeerID, payload)
            isBleConnected(recipientPeerID) || (isBleEnabled() && !isWifiConnected(recipientPeerID)) ->
                bluetooth.sendVoiceFrame(recipientPeerID, payload)
            else -> wifiService()?.sendVoiceFrame(recipientPeerID, payload)
        }
    }

    override fun prepareFilePrivate(
        recipientPeerID: String,
        file: BitchatFilePacket,
        transferId: String,
        allowLegacyFallback: Boolean
    ): PrivateMediaPreparation {
        return when {
            isBleReady(recipientPeerID) -> bluetooth.prepareFilePrivate(
                recipientPeerID,
                file,
                transferId,
                allowLegacyFallback
            )
            isWifiReady(recipientPeerID) -> wifiService()?.prepareFilePrivate(
                recipientPeerID,
                file,
                transferId,
                allowLegacyFallback
            ) ?: PrivateMediaPreparation.Rejected("Wi-Fi Aware transport is unavailable")
            isBleConnected(recipientPeerID) || (isBleEnabled() && !isWifiConnected(recipientPeerID)) ->
                bluetooth.prepareFilePrivate(
                    recipientPeerID,
                    file,
                    transferId,
                    allowLegacyFallback
                )
            else -> wifiService()?.prepareFilePrivate(
                recipientPeerID,
                file,
                transferId,
                allowLegacyFallback
            ) ?: PrivateMediaPreparation.Rejected("No local transport is available for this peer")
        }
    }

    override fun cancelFileTransfer(transferId: String): Boolean {
        val bleCancelled = try { bluetooth.cancelFileTransfer(transferId) } catch (_: Exception) { false }
        val wifiCancelled = try { wifiService()?.cancelFileTransfer(transferId) == true } catch (_: Exception) { false }
        return bleCancelled || wifiCancelled
    }

    override fun sendBroadcastAnnounce() {
        if (isBleEnabled()) {
            try { bluetooth.sendBroadcastAnnounce() } catch (_: Exception) { }
        }
        try { wifiService()?.sendBroadcastAnnounce() } catch (_: Exception) { }
    }

    override fun sendAnnouncementToPeer(peerID: String) {
        when {
            isBleConnected(peerID) || (isBleEnabled() && !isWifiConnected(peerID)) -> bluetooth.sendAnnouncementToPeer(peerID)
            else -> wifiService()?.sendAnnouncementToPeer(peerID)
        }
    }

    override fun getPeerNicknames(): Map<String, String> {
        val merged = linkedMapOf<String, String>()
        try { merged.putAll(wifiService()?.getPeerNicknames().orEmpty()) } catch (_: Exception) { }
        try { merged.putAll(bluetooth.getPeerNicknames()) } catch (_: Exception) { }
        return merged
    }

    override fun getPeerRSSI(): Map<String, Int> {
        val merged = linkedMapOf<String, Int>()
        try { merged.putAll(wifiService()?.getPeerRSSI().orEmpty()) } catch (_: Exception) { }
        try { merged.putAll(bluetooth.getPeerRSSI()) } catch (_: Exception) { }
        return merged
    }

    override fun getActivePeerCount(): Int {
        return mergedPeerIDs().filter { it != myPeerID }.distinct().size
    }

    override fun hasEstablishedSession(peerID: String): Boolean {
        return isBleReady(peerID) || isWifiReady(peerID)
    }

    override fun getSessionState(peerID: String): NoiseSession.NoiseSessionState {
        val bleState = try { bluetooth.getSessionState(peerID) } catch (_: Exception) { NoiseSession.NoiseSessionState.Uninitialized }
        val wifiState = try { wifiService()?.getSessionState(peerID) } catch (_: Exception) { null }
        return when {
            bleState is NoiseSession.NoiseSessionState.Established -> bleState
            wifiState is NoiseSession.NoiseSessionState.Established -> wifiState
            bleState is NoiseSession.NoiseSessionState.Handshaking -> bleState
            wifiState is NoiseSession.NoiseSessionState.Handshaking -> wifiState
            bleState !is NoiseSession.NoiseSessionState.Uninitialized -> bleState
            wifiState != null -> wifiState
            else -> bleState
        }
    }

    override fun initiateNoiseHandshake(peerID: String) {
        when {
            isBleConnected(peerID) -> bluetooth.initiateNoiseHandshake(peerID)
            isWifiConnected(peerID) -> wifiService()?.initiateNoiseHandshake(peerID)
            isBleEnabled() -> bluetooth.initiateNoiseHandshake(peerID)
            else -> wifiService()?.initiateNoiseHandshake(peerID)
        }
    }

    override fun getPeerFingerprint(peerID: String): String? {
        return try { bluetooth.getPeerFingerprint(peerID) } catch (_: Exception) { null }
            ?: try { wifiService()?.getPeerFingerprint(peerID) } catch (_: Exception) { null }
    }

    override fun getPeerInfo(peerID: String): PeerInfo? {
        val ble = try { bluetooth.getPeerInfo(peerID) } catch (_: Exception) { null }
        val wifi = try { wifiService()?.getPeerInfo(peerID) } catch (_: Exception) { null }
        return when {
            ble?.isConnected == true && hasEstablishedSessionOnBluetooth(peerID) -> ble
            wifi?.isConnected == true && wifiService()?.hasEstablishedSession(peerID) == true -> wifi
            ble?.isConnected == true -> ble
            wifi?.isConnected == true -> wifi
            else -> ble ?: wifi
        }
    }

    override fun updatePeerInfo(
        peerID: String,
        nickname: String,
        noisePublicKey: ByteArray,
        signingPublicKey: ByteArray,
        isVerified: Boolean
    ): Boolean {
        val bleUpdated = try {
            bluetooth.updatePeerInfo(peerID, nickname, noisePublicKey, signingPublicKey, isVerified)
        } catch (_: Exception) {
            false
        }
        val wifiUpdated = try {
            wifiService()?.updatePeerInfo(peerID, nickname, noisePublicKey, signingPublicKey, isVerified) == true
        } catch (_: Exception) {
            false
        }
        return bleUpdated || wifiUpdated
    }

    override fun getIdentityFingerprint(): String = bluetooth.getIdentityFingerprint()

    override fun getStaticNoisePublicKey(): ByteArray? {
        return bluetooth.getStaticNoisePublicKey() ?: wifiService()?.getStaticNoisePublicKey()
    }

    override fun shouldShowEncryptionIcon(peerID: String): Boolean {
        return hasEstablishedSession(peerID)
    }

    override fun getEncryptedPeers(): List<String> {
        val encrypted = linkedSetOf<String>()
        try { encrypted.addAll(bluetooth.getEncryptedPeers()) } catch (_: Exception) { }
        try { encrypted.addAll(wifiService()?.getEncryptedPeers().orEmpty()) } catch (_: Exception) { }
        mergedPeerIDs().filterTo(encrypted) { hasEstablishedSession(it) }
        return encrypted.toList()
    }

    override fun getDeviceAddressForPeer(peerID: String): String? {
        return try { bluetooth.getDeviceAddressForPeer(peerID) } catch (_: Exception) { null }
            ?: try { wifiService()?.getDeviceAddressForPeer(peerID) } catch (_: Exception) { null }
    }

    override fun getDeviceAddressToPeerMapping(): Map<String, String> {
        val merged = linkedMapOf<String, String>()
        try { merged.putAll(wifiService()?.getDeviceAddressToPeerMapping().orEmpty()) } catch (_: Exception) { }
        try { merged.putAll(bluetooth.getDeviceAddressToPeerMapping()) } catch (_: Exception) { }
        return merged
    }

    override fun printDeviceAddressesForPeers(): String {
        return buildString {
            appendLine(bluetooth.printDeviceAddressesForPeers())
            wifiService()?.let {
                appendLine()
                appendLine(it.printDeviceAddressesForPeers())
            }
        }
    }

    override fun getDebugStatus(): String {
        return buildString {
            appendLine("=== Unified Mesh Service Debug Status ===")
            appendLine("My Peer ID: $myPeerID")
            appendLine("Merged Peers: ${mergedPeerIDs().joinToString(", ")}")
            appendLine()
            appendLine(bluetooth.getDebugStatus())
            wifiService()?.let {
                appendLine()
                appendLine(it.getDebugStatus())
            }
        }
    }

    override fun clearAllInternalData() {
        try { bluetooth.clearAllInternalData() } catch (_: Exception) { }
        try { wifiService()?.clearAllInternalData() } catch (_: Exception) { }
    }

    override fun clearAllEncryptionData() {
        try { bluetooth.clearAllEncryptionData() } catch (_: Exception) { }
        try { wifiService()?.clearAllEncryptionData() } catch (_: Exception) { }
    }

    override fun didReceiveMessage(message: BitchatMessage) {
        delegate?.didReceiveMessage(message)
    }

    override fun didUpdatePeerList(peers: List<String>) {
        delegate?.didUpdatePeerList(mergedPeerIDs().ifEmpty { peers.distinct() })
    }

    override fun didReceiveChannelLeave(channel: String, fromPeer: String) {
        delegate?.didReceiveChannelLeave(channel, fromPeer)
    }

    override fun didReceiveDeliveryAck(messageID: String, recipientPeerID: String) {
        delegate?.didReceiveDeliveryAck(messageID, recipientPeerID)
    }

    override fun didReceiveReadReceipt(messageID: String, recipientPeerID: String) {
        delegate?.didReceiveReadReceipt(messageID, recipientPeerID)
    }

    override fun didReceiveVerifyChallenge(peerID: String, payload: ByteArray, timestampMs: Long) {
        delegate?.didReceiveVerifyChallenge(peerID, payload, timestampMs)
    }

    override fun didReceiveVerifyResponse(peerID: String, payload: ByteArray, timestampMs: Long) {
        delegate?.didReceiveVerifyResponse(peerID, payload, timestampMs)
    }

    override fun didResolvePrivateMediaPolicy(peerID: String) {
        delegate?.didResolvePrivateMediaPolicy(peerID)
    }

    override fun decryptChannelMessage(encryptedContent: ByteArray, channel: String): String? {
        return delegate?.decryptChannelMessage(encryptedContent, channel)
    }

    override fun getNickname(): String? = delegate?.getNickname()

    override fun isFavorite(peerID: String): Boolean = delegate?.isFavorite(peerID) ?: false

    private fun mergedPeerIDs(): List<String> {
        val ids = linkedSetOf<String>()
        try { ids.addAll(com.bitchat.android.services.AppStateStore.peers.value) } catch (_: Exception) { }
        try { ids.addAll(bluetooth.getPeerNicknames().keys) } catch (_: Exception) { }
        try { ids.addAll(wifiService()?.getPeerNicknames()?.keys.orEmpty()) } catch (_: Exception) { }
        return ids.toList()
    }

    private fun wifiService(): MeshService? {
        return try {
            WifiAwareController.getService()?.also { service ->
                if (delegate != null && service.delegate !== this) {
                    service.delegate = this
                }
            }
        } catch (_: Exception) {
            null
        }
    }

    private fun isBleEnabled(): Boolean {
        return try {
            com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().bleEnabled.value
        } catch (_: Exception) {
            try { com.bitchat.android.ui.debug.DebugPreferenceManager.getBleEnabled(true) } catch (_: Exception) { true }
        }
    }

    private fun isBleConnected(peerID: String): Boolean {
        return try { bluetooth.getPeerInfo(peerID)?.isConnected == true } catch (_: Exception) { false }
    }

    private fun isWifiConnected(peerID: String): Boolean {
        return try { wifiService()?.getPeerInfo(peerID)?.isConnected == true } catch (_: Exception) { false }
    }

    private fun isBleReady(peerID: String): Boolean {
        return isBleConnected(peerID) && hasEstablishedSessionOnBluetooth(peerID)
    }

    private fun isWifiReady(peerID: String): Boolean {
        return try {
            val wifi = wifiService()
            wifi?.getPeerInfo(peerID)?.isConnected == true && wifi.hasEstablishedSession(peerID)
        } catch (_: Exception) {
            false
        }
    }

    private fun hasEstablishedSessionOnBluetooth(peerID: String): Boolean {
        return try { bluetooth.hasEstablishedSession(peerID) } catch (_: Exception) { false }
    }
}

package com.bitchat.android.model

/**
 * Canonical payload carried inside Noise payload type 0x21.
 *
 * Wire format:
 * `[version=0x01][type=0x01][len=1...8][minimal LE capabilities]`
 * `[type=0x02][len=32][Ed25519 public key]`
 *
 * Unknown TLVs are skipped. Both known fields must occur exactly once.
 */
data class AuthenticatedPeerState(
    val capabilities: PeerCapabilities,
    val signingPublicKey: ByteArray
) {
    init {
        require(signingPublicKey.size == SIGNING_PUBLIC_KEY_SIZE) {
            "Ed25519 public key must be 32 bytes"
        }
    }

    fun encode(): ByteArray {
        val capabilityBytes = capabilities.encoded()
        return buildList<Byte>(1 + 2 + capabilityBytes.size + 2 + signingPublicKey.size) {
            add(VERSION.toByte())
            add(CAPABILITIES_TLV.toByte())
            add(capabilityBytes.size.toByte())
            addAll(capabilityBytes.toList())
            add(SIGNING_PUBLIC_KEY_TLV.toByte())
            add(SIGNING_PUBLIC_KEY_SIZE.toByte())
            addAll(signingPublicKey.toList())
        }.toByteArray()
    }

    companion object {
        const val VERSION = 0x01
        private const val CAPABILITIES_TLV = 0x01
        private const val SIGNING_PUBLIC_KEY_TLV = 0x02
        private const val SIGNING_PUBLIC_KEY_SIZE = 32

        fun decode(data: ByteArray): AuthenticatedPeerState? {
            if (data.firstOrNull()?.toInt()?.and(0xFF) != VERSION) return null
            var offset = 1
            var capabilities: PeerCapabilities? = null
            var signingPublicKey: ByteArray? = null

            while (offset < data.size) {
                if (offset + 2 > data.size) return null
                val type = data[offset].toInt() and 0xFF
                val length = data[offset + 1].toInt() and 0xFF
                offset += 2
                if (offset + length > data.size) return null
                val value = data.copyOfRange(offset, offset + length)
                offset += length

                when (type) {
                    CAPABILITIES_TLV -> {
                        if (capabilities != null || length !in 1..8) return null
                        val decoded = PeerCapabilities.decode(value)
                        if (!decoded.encoded().contentEquals(value)) return null
                        capabilities = decoded
                    }

                    SIGNING_PUBLIC_KEY_TLV -> {
                        if (signingPublicKey != null || length != SIGNING_PUBLIC_KEY_SIZE) return null
                        signingPublicKey = value
                    }

                    else -> Unit
                }
            }

            val decodedCapabilities = capabilities ?: return null
            val decodedSigningKey = signingPublicKey ?: return null
            return AuthenticatedPeerState(decodedCapabilities, decodedSigningKey)
        }
    }

    override fun equals(other: Any?): Boolean =
        this === other ||
            (other is AuthenticatedPeerState &&
                capabilities == other.capabilities &&
                signingPublicKey.contentEquals(other.signingPublicKey))

    override fun hashCode(): Int = 31 * capabilities.hashCode() + signingPublicKey.contentHashCode()
}

package com.bitchat.android.model

import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * BitchatFilePacket: TLV-encoded file transfer payload for BLE mesh.
 * TLVs:
 *  - 0x01: filename (UTF-8)
 *  - 0x02: file size (8 bytes, UInt64)
 *  - 0x03: mime type (UTF-8)
 *  - 0x04: content (bytes) — may appear multiple times for large files
 *
 * Length field for TLV is 2 bytes (UInt16, big-endian) for all TLVs.
 * For large files, CONTENT is chunked into multiple TLVs of up to 65535 bytes each.
 *
 * Unknown TLV types are SKIPPED, not rejected: the tag list above is a floor,
 * not a ceiling, and a decoder that bails on the first tag it does not know
 * makes the format unextendable — the whole file is lost over a field that,
 * by construction, the sender considered optional. The iOS client has always
 * done this (`case nil: continue` in its own decoder), so rejecting here also
 * meant the two implementations disagreed about what a valid packet is.
 *
 * Note: The outer BitchatPacket uses version 2 (4-byte payload length), so this
 * TLV payload can exceed 64 KiB even though each TLV value is limited to 65535 bytes.
 * Transport-level fragmentation then splits the final packet for BLE MTU.
 */
data class BitchatFilePacket(
    val fileName: String,
    val fileSize: Long,
    val mimeType: String,
    val content: ByteArray
) {
    private enum class TLVType(val v: UByte) {
        FILE_NAME(0x01u), FILE_SIZE(0x02u), MIME_TYPE(0x03u), CONTENT(0x04u);
        companion object {
            fun from(value: UByte): TLVType? = when (value) {
                FILE_NAME.v -> FILE_NAME
                FILE_SIZE.v -> FILE_SIZE
                MIME_TYPE.v -> MIME_TYPE
                CONTENT.v -> CONTENT
                else -> null
            }
        }
    }

    fun encode(): ByteArray? {
        try {
            android.util.Log.d("BitchatFilePacket", "🔄 Encoding: name=$fileName, size=$fileSize, mime=$mimeType")
        val nameBytes = fileName.toByteArray(Charsets.UTF_8)
        val mimeBytes = mimeType.toByteArray(Charsets.UTF_8)
        // Validate bounds for 2-byte TLV lengths (per-TLV). CONTENT may exceed 65535 and will be chunked.
        if (nameBytes.size > 0xFFFF || mimeBytes.size > 0xFFFF) {
                android.util.Log.e("BitchatFilePacket", "❌ TLV field too large: name=${nameBytes.size}, mime=${mimeBytes.size} (max: 65535)")
                return null
            }
            if (content.size > 0xFFFF) {
                android.util.Log.d("BitchatFilePacket", "📦 Content exceeds 65535 bytes (${content.size}); will be split into multiple CONTENT TLVs")
            } else {
                android.util.Log.d("BitchatFilePacket", "📏 TLV sizes OK: name=${nameBytes.size}, mime=${mimeBytes.size}, content=${content.size}")
            }
        val sizeFieldLen = 4 // UInt32 for FILE_SIZE (changed from 8 bytes)
        val contentLenFieldLen = 4 // UInt32 for CONTENT TLV as requested

        // Compute capacity: header TLVs + single CONTENT TLV with 4-byte length
        val contentTLVBytes = 1 + contentLenFieldLen + content.size
        val capacity = (1 + 2 + nameBytes.size) + (1 + 2 + sizeFieldLen) + (1 + 2 + mimeBytes.size) + contentTLVBytes
        val buf = ByteBuffer.allocate(capacity).order(ByteOrder.BIG_ENDIAN)

        // FILE_NAME
        buf.put(TLVType.FILE_NAME.v.toByte())
        buf.putShort(nameBytes.size.toShort())
        buf.put(nameBytes)

        // FILE_SIZE (4 bytes)
        buf.put(TLVType.FILE_SIZE.v.toByte())
        buf.putShort(sizeFieldLen.toShort())
        buf.putInt(fileSize.toInt())

        // MIME_TYPE
        buf.put(TLVType.MIME_TYPE.v.toByte())
        buf.putShort(mimeBytes.size.toShort())
        buf.put(mimeBytes)

        // CONTENT (single TLV with 4-byte length)
        buf.put(TLVType.CONTENT.v.toByte())
        buf.putInt(content.size)
        buf.put(content)

        val result = buf.array()
            android.util.Log.d("BitchatFilePacket", "✅ Encoded successfully: ${result.size} bytes total")
            return result
        } catch (e: Exception) {
            android.util.Log.e("BitchatFilePacket", "❌ Encoding failed: ${e.message}", e)
            return null
        }
    }

    companion object {
        fun decode(data: ByteArray): BitchatFilePacket? {
            android.util.Log.d("BitchatFilePacket", "🔄 Decoding ${data.size} bytes")
            try {
                var off = 0
                var name: String? = null
                var size: Long? = null
                var mime: String? = null
                var contentBytes: ByteArray? = null
                var skippedUnknownTLVs = 0
                while (off < data.size) {
                    // Every TLV needs at least a type and a 2-byte length.
                    // Reject a truncated trailing header instead of silently
                    // accepting it, matching the iOS decoder.
                    if (data.size - off < 3) return null
                    // A null `t` is an unknown tag: read its length like any
                    // other 2-byte TLV and skip its value, matching iOS.
                    val t = TLVType.from(data[off].toUByte())
                    off += 1
                    // CONTENT uses 4-byte length; others use 2-byte length
                    val len: Int
                    if (t == TLVType.CONTENT) {
                        if (off + 4 > data.size) return null
                        len = ((data[off].toInt() and 0xFF) shl 24) or ((data[off + 1].toInt() and 0xFF) shl 16) or ((data[off + 2].toInt() and 0xFF) shl 8) or (data[off + 3].toInt() and 0xFF)
                        off += 4
                    } else {
                        if (off + 2 > data.size) return null
                        len = ((data[off].toInt() and 0xFF) shl 8) or (data[off + 1].toInt() and 0xFF)
                        off += 2
                    }
                    if (len < 0 || off + len > data.size) return null
                    if (t == null) {
                        // Unknown tag: advance past the value without copying it
                        // and without logging. A peer can pad a packet with
                        // zero-length unknown TLVs — 3 bytes each — so anything
                        // per-TLV here is attacker-scaled: at the payload
                        // ceiling that is millions of copies and formatted log
                        // lines monopolising the mesh handler. Counted and
                        // reported once after the loop instead.
                        off += len
                        skippedUnknownTLVs += 1
                        continue
                    }
                    val value = data.copyOfRange(off, off + len)
                    off += len
                    when (t) {
                        TLVType.FILE_NAME -> name = String(value, Charsets.UTF_8)
                        TLVType.FILE_SIZE -> {
                            if (len != 4) return null
                            val bb = ByteBuffer.wrap(value).order(ByteOrder.BIG_ENDIAN)
                            size = bb.int.toLong()
                        }
                        TLVType.MIME_TYPE -> mime = String(value, Charsets.UTF_8)
                        TLVType.CONTENT -> {
                            // Expect a single CONTENT TLV
                            if (contentBytes == null) contentBytes = value else {
                                // If multiple CONTENT TLVs appear, concatenate for tolerance
                                contentBytes = (contentBytes!! + value)
                            }
                        }
                    }
                }
                if (skippedUnknownTLVs > 0) {
                    android.util.Log.d("BitchatFilePacket", "⏭️ Skipped $skippedUnknownTLVs unknown TLV(s)")
                }
                val n = name ?: return null
                val c = contentBytes ?: return null
                val s = size ?: c.size.toLong()
                val m = mime ?: "application/octet-stream"
                val result = BitchatFilePacket(n, s, m, c)
                android.util.Log.d("BitchatFilePacket", "✅ Decoded: name=$n, size=$s, mime=$m, content=${c.size} bytes")
                return result
            } catch (e: Exception) {
                android.util.Log.e("BitchatFilePacket", "❌ Decoding failed: ${e.message}", e)
                return null
            }
        }
    }
}

package com.bitchat.android.model

import android.os.Parcelable
import com.google.gson.GsonBuilder
import kotlinx.parcelize.Parcelize
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.*

@Parcelize
enum class BitchatMessageType : Parcelable {
    Message,
    Audio,
    Image,
    File
}

/**
 * Delivery status for messages - exact same as iOS version
 */
sealed class DeliveryStatus : Parcelable {
    @Parcelize
    object Sending : DeliveryStatus()

    @Parcelize
    object Sent : DeliveryStatus()

    @Parcelize
    data class Delivered(val to: String, val at: Date) : DeliveryStatus()

    @Parcelize
    data class Read(val by: String, val at: Date) : DeliveryStatus()

    @Parcelize
    data class Failed(val reason: String) : DeliveryStatus()

    @Parcelize
    data class PartiallyDelivered(val reached: Int, val total: Int) : DeliveryStatus()

    fun getDisplayText(): String {
        return when (this) {
            is Sending -> "Sending..."
            is Sent -> "Sent"
            is Delivered -> "Delivered to ${this.to}"
            is Read -> "Read by ${this.by}"
            is Failed -> "Failed: ${this.reason}"
            is PartiallyDelivered -> "Delivered to ${this.reached}/${this.total}"
        }
    }
}

/**
 * BitchatMessage - 100% compatible with iOS version
 */
@Parcelize
data class BitchatMessage(
    val id: String = UUID.randomUUID().toString().uppercase(),
    val sender: String,
    val content: String,
    val type: BitchatMessageType = BitchatMessageType.Message,
    val timestamp: Date,
    val isRelay: Boolean = false,
    val originalSender: String? = null,
    val isPrivate: Boolean = false,
    val recipientNickname: String? = null,
    val senderPeerID: String? = null,
    val mentions: List<String>? = null,
    val channel: String? = null,
    val encryptedContent: ByteArray? = null,
    val isEncrypted: Boolean = false,
    val deliveryStatus: DeliveryStatus? = null,
    val powDifficulty: Int? = null,
    /**
     * Full canonical Nostr public key supplied by the local Nostr bridge.
     *
     * This is local identity metadata, not part of the Bitchat binary wire format. It lets UI
     * surfaces color the sender by the same stable key while [senderPeerID] remains available for
     * mesh IDs and private-chat routing aliases.
     */
    val senderNostrPubkey: String? = null
) : Parcelable {

    /**
     * Convert message to binary payload format - exactly same as iOS version
     */
    fun toBinaryPayload(): ByteArray? {
        try {
            val buffer = ByteBuffer.allocate(4096).apply { order(ByteOrder.BIG_ENDIAN) }

            // Message format:
            // - Flags: 1 byte (bit flags for optional fields)
            // - Timestamp: 8 bytes (milliseconds since epoch, big-endian)
            // - ID length: 1 byte + ID data
            // - Sender length: 1 byte + sender data
            // - Content length: 2 bytes + content data (or encrypted content)
            // Optional fields based on flags...

            var flags: UByte = 0u
            if (isRelay) flags = flags or 0x01u
            if (isPrivate) flags = flags or 0x02u
            if (originalSender != null) flags = flags or 0x04u
            if (recipientNickname != null) flags = flags or 0x08u
            if (senderPeerID != null) flags = flags or 0x10u
            if (mentions != null && mentions.isNotEmpty()) flags = flags or 0x20u
            if (channel != null) flags = flags or 0x40u
            if (isEncrypted) flags = flags or 0x80u

            buffer.put(flags.toByte())

            // Timestamp (in milliseconds, 8 bytes big-endian)
            val timestampMillis = timestamp.time
            buffer.putLong(timestampMillis)

            // ID
            val idBytes = id.toByteArray(Charsets.UTF_8)
            buffer.put(minOf(idBytes.size, 255).toByte())
            buffer.put(idBytes.take(255).toByteArray())

            // Sender
            val senderBytes = sender.toByteArray(Charsets.UTF_8)
            buffer.put(minOf(senderBytes.size, 255).toByte())
            buffer.put(senderBytes.take(255).toByteArray())

            // Content or encrypted content
            if (isEncrypted && encryptedContent != null) {
                val length = minOf(encryptedContent.size, 65535)
                buffer.putShort(length.toShort())
                buffer.put(encryptedContent.take(length).toByteArray())
            } else {
                val contentBytes = content.toByteArray(Charsets.UTF_8)
                val length = minOf(contentBytes.size, 65535)
                buffer.putShort(length.toShort())
                buffer.put(contentBytes.take(length).toByteArray())
            }

            // Optional fields
            originalSender?.let { origSender ->
                val origBytes = origSender.toByteArray(Charsets.UTF_8)
                buffer.put(minOf(origBytes.size, 255).toByte())
                buffer.put(origBytes.take(255).toByteArray())
            }

            recipientNickname?.let { recipient ->
                val recipBytes = recipient.toByteArray(Charsets.UTF_8)
                buffer.put(minOf(recipBytes.size, 255).toByte())
                buffer.put(recipBytes.take(255).toByteArray())
            }

            senderPeerID?.let { peerID ->
                val peerBytes = peerID.toByteArray(Charsets.UTF_8)
                buffer.put(minOf(peerBytes.size, 255).toByte())
                buffer.put(peerBytes.take(255).toByteArray())
            }

            // Mentions array
            mentions?.let { mentionList ->
                buffer.put(minOf(mentionList.size, 255).toByte())
                mentionList.take(255).forEach { mention ->
                    val mentionBytes = mention.toByteArray(Charsets.UTF_8)
                    buffer.put(minOf(mentionBytes.size, 255).toByte())
                    buffer.put(mentionBytes.take(255).toByteArray())
                }
            }

            // Channel hashtag
            channel?.let { channelName ->
                val channelBytes = channelName.toByteArray(Charsets.UTF_8)
                buffer.put(minOf(channelBytes.size, 255).toByte())
                buffer.put(channelBytes.take(255).toByteArray())
            }

            val result = ByteArray(buffer.position())
            buffer.rewind()
            buffer.get(result)
            return result

        } catch (e: Exception) {
            return null
        }
    }

    companion object {
        /**
         * Parse message from binary payload - exactly same logic as iOS version
         */
        fun fromBinaryPayload(data: ByteArray): BitchatMessage? {
            try {
                if (data.size < 13) return null

                val buffer = ByteBuffer.wrap(data).apply { order(ByteOrder.BIG_ENDIAN) }

                // Flags
                val flags = buffer.get().toUByte()
                val isRelay = (flags and 0x01u) != 0u.toUByte()
                val isPrivate = (flags and 0x02u) != 0u.toUByte()
                val hasOriginalSender = (flags and 0x04u) != 0u.toUByte()
                val hasRecipientNickname = (flags and 0x08u) != 0u.toUByte()
                val hasSenderPeerID = (flags and 0x10u) != 0u.toUByte()
                val hasMentions = (flags and 0x20u) != 0u.toUByte()
                val hasChannel = (flags and 0x40u) != 0u.toUByte()
                val isEncrypted = (flags and 0x80u) != 0u.toUByte()

                // Timestamp
                val timestampMillis = buffer.getLong()
                val timestamp = Date(timestampMillis)

                // ID
                val idLength = buffer.get().toInt() and 0xFF
                if (buffer.remaining() < idLength) return null
                val idBytes = ByteArray(idLength)
                buffer.get(idBytes)
                val id = String(idBytes, Charsets.UTF_8)

                // Sender
                val senderLength = buffer.get().toInt() and 0xFF
                if (buffer.remaining() < senderLength) return null
                val senderBytes = ByteArray(senderLength)
                buffer.get(senderBytes)
                val sender = String(senderBytes, Charsets.UTF_8)

                // Content
                val contentLength = buffer.getShort().toInt() and 0xFFFF
                if (buffer.remaining() < contentLength) return null

                val content: String
                val encryptedContent: ByteArray?

                if (isEncrypted) {
                    val encryptedBytes = ByteArray(contentLength)
                    buffer.get(encryptedBytes)
                    encryptedContent = encryptedBytes
                    content = "" // Empty placeholder
                } else {
                    val contentBytes = ByteArray(contentLength)
                    buffer.get(contentBytes)
                    content = String(contentBytes, Charsets.UTF_8)
                    encryptedContent = null
                }

                // Optional fields
                val originalSender = if (hasOriginalSender && buffer.hasRemaining()) {
                    val length = buffer.get().toInt() and 0xFF
                    if (buffer.remaining() >= length) {
                        val bytes = ByteArray(length)
                        buffer.get(bytes)
                        String(bytes, Charsets.UTF_8)
                    } else null
                } else null

                val recipientNickname = if (hasRecipientNickname && buffer.hasRemaining()) {
                    val length = buffer.get().toInt() and 0xFF
                    if (buffer.remaining() >= length) {
                        val bytes = ByteArray(length)
                        buffer.get(bytes)
                        String(bytes, Charsets.UTF_8)
                    } else null
                } else null

                val senderPeerID = if (hasSenderPeerID && buffer.hasRemaining()) {
                    val length = buffer.get().toInt() and 0xFF
                    if (buffer.remaining() >= length) {
                        val bytes = ByteArray(length)
                        buffer.get(bytes)
                        String(bytes, Charsets.UTF_8)
                    } else null
                } else null

                // Mentions array
                val mentions = if (hasMentions && buffer.hasRemaining()) {
                    val mentionCount = buffer.get().toInt() and 0xFF
                    val mentionList = mutableListOf<String>()
                    repeat(mentionCount) {
                        if (buffer.hasRemaining()) {
                            val length = buffer.get().toInt() and 0xFF
                            if (buffer.remaining() >= length) {
                                val bytes = ByteArray(length)
                                buffer.get(bytes)
                                mentionList.add(String(bytes, Charsets.UTF_8))
                            }
                        }
                    }
                    if (mentionList.isNotEmpty()) mentionList else null
                } else null

                // Channel
                val channel = if (hasChannel && buffer.hasRemaining()) {
                    val length = buffer.get().toInt() and 0xFF
                    if (buffer.remaining() >= length) {
                        val bytes = ByteArray(length)
                        buffer.get(bytes)
                        String(bytes, Charsets.UTF_8)
                    } else null
                } else null

                return BitchatMessage(
                    id = id,
                    sender = sender,
                    content = content,
                    type = BitchatMessageType.Message,
                    timestamp = timestamp,
                    isRelay = isRelay,
                    originalSender = originalSender,
                    isPrivate = isPrivate,
                    recipientNickname = recipientNickname,
                    senderPeerID = senderPeerID,
                    mentions = mentions,
                    channel = channel,
                    encryptedContent = encryptedContent,
                    isEncrypted = isEncrypted
                )

            } catch (e: Exception) {
                return null
            }
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as BitchatMessage

        if (id != other.id) return false
        if (sender != other.sender) return false
        if (content != other.content) return false
        if (type != other.type) return false
        if (timestamp != other.timestamp) return false
        if (isRelay != other.isRelay) return false
        if (originalSender != other.originalSender) return false
        if (isPrivate != other.isPrivate) return false
        if (recipientNickname != other.recipientNickname) return false
        if (senderPeerID != other.senderPeerID) return false
        if (mentions != other.mentions) return false
        if (channel != other.channel) return false
        if (encryptedContent != null) {
            if (other.encryptedContent == null) return false
            if (!encryptedContent.contentEquals(other.encryptedContent)) return false
        } else if (other.encryptedContent != null) return false
        if (isEncrypted != other.isEncrypted) return false
        if (deliveryStatus != other.deliveryStatus) return false

        return true
    }

    override fun hashCode(): Int {
        var result = id.hashCode()
        result = 31 * result + sender.hashCode()
        result = 31 * result + content.hashCode()
        result = 31 * result + type.hashCode()
        result = 31 * result + timestamp.hashCode()
        result = 31 * result + isRelay.hashCode()
        result = 31 * result + (originalSender?.hashCode() ?: 0)
        result = 31 * result + isPrivate.hashCode()
        result = 31 * result + (recipientNickname?.hashCode() ?: 0)
        result = 31 * result + (senderPeerID?.hashCode() ?: 0)
        result = 31 * result + (mentions?.hashCode() ?: 0)
        result = 31 * result + (channel?.hashCode() ?: 0)
        result = 31 * result + (encryptedContent?.contentHashCode() ?: 0)
        result = 31 * result + isEncrypted.hashCode()
        result = 31 * result + (deliveryStatus?.hashCode() ?: 0)
        return result
    }
}

package com.bitchat.android.model

import android.content.Context
import android.net.Uri
import android.util.Log
import com.bitchat.android.features.file.FileUtils
import java.io.File

/**
 * Business logic for file sharing operations
 */
object FileSharingManager {

    private const val TAG = "FileSharingManager"

    /**
     * Create a file packet from URI for sending
     */
    fun createFilePacketFromUri(
        context: Context,
        uri: Uri,
        originalName: String? = null
    ): BitchatFilePacket? {
        return try {
            // Get file name from URI or use original name
            val fileName = originalName ?: getFileNameFromUri(context, uri) ?: "unknown_file"

            // Copy file to our temp storage for sending
            val localPath = FileUtils.copyFileForSending(context, uri) ?: return null

            // Determine MIME type
            val mimeType = FileUtils.getMimeTypeFromExtension(fileName)

            // Read file content
            val file = File(localPath)
            val content = file.readBytes()
            val fileSize = file.length()

            // Clean up temp file
            file.delete()

            val packet = BitchatFilePacket(
                fileName = fileName,
                fileSize = fileSize,
                mimeType = mimeType,
                content = content
            )

            Log.d(TAG, "Created file packet: name=$fileName, size=${FileUtils.formatFileSize(fileSize)}, mime=$mimeType")
            packet

        } catch (e: Exception) {
            Log.e(TAG, "Failed to create file packet from URI", e)
            null
        }
    }

    /**
     * Extract filename from URI
     */
    private fun getFileNameFromUri(context: Context, uri: Uri): String? {
        return try {
            context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                val nameIndex = cursor.getColumnIndex(android.provider.MediaStore.MediaColumns.DISPLAY_NAME)
                cursor.moveToFirst()
                cursor.getString(nameIndex)
            } ?: uri.lastPathSegment
        } catch (e: Exception) {
            Log.w(TAG, "Failed to get filename from URI", e)
            uri.lastPathSegment
        }
    }

    /**
     * Process a received file packet and return file info
     */
    data class ReceivedFileInfo(
        val fileName: String,
        val fileSize: Long,
        val mimeType: String,
        val content: ByteArray
    )

    fun processReceivedFile(packet: BitchatFilePacket): ReceivedFileInfo {
        return ReceivedFileInfo(
            fileName = packet.fileName,
            fileSize = packet.fileSize,
            mimeType = packet.mimeType,
            content = packet.content
        )
    }
}

package com.bitchat.android.model

import com.bitchat.android.protocol.MessageType

/**
 * FragmentPayload - 100% iOS-compatible fragment payload structure
 * 
 * This class handles the encoding and decoding of fragment payloads exactly
 * as implemented in iOS bitchat SimplifiedBluetoothService.
 * 
 * Fragment payload structure (matching iOS):
 * - 8 bytes: Fragment ID (random bytes)
 * - 2 bytes: Index (big-endian) 
 * - 2 bytes: Total count (big-endian)
 * - 1 byte: Original message type
 * - Variable: Fragment data
 * 
 * Total header size: 13 bytes
 */
data class FragmentPayload(
    val fragmentID: ByteArray,      // 8 bytes - random fragment identifier
    val index: Int,                 // Fragment index (0-based)
    val total: Int,                 // Total number of fragments
    val originalType: UByte,        // Original message type before fragmentation
    val data: ByteArray             // Fragment data
) {

    companion object {
        const val HEADER_SIZE = 13
        const val FRAGMENT_ID_SIZE = 8

        /**
         * Decode fragment payload from binary data
         * Matches iOS implementation exactly
         */
        fun decode(payloadData: ByteArray): FragmentPayload? {
            if (payloadData.size < HEADER_SIZE) {
                return null
            }

            try {
                // Extract fragment ID (8 bytes)
                val fragmentID = payloadData.sliceArray(0..<FRAGMENT_ID_SIZE)

                // Extract index (2 bytes, big-endian) - matching iOS
                val index = ((payloadData[8].toInt() and 0xFF) shl 8) or 
                           (payloadData[9].toInt() and 0xFF)

                // Extract total (2 bytes, big-endian) - matching iOS  
                val total = ((payloadData[10].toInt() and 0xFF) shl 8) or
                           (payloadData[11].toInt() and 0xFF)

                // Extract original type (1 byte)
                val originalType = payloadData[12].toUByte()

                // Extract fragment data (remaining bytes)
                val data = if (payloadData.size > HEADER_SIZE) {
                    payloadData.sliceArray(HEADER_SIZE..<payloadData.size)
                } else {
                    ByteArray(0)
                }

                return FragmentPayload(fragmentID, index, total, originalType, data)

            } catch (e: Exception) {
                return null
            }
        }

        /**
         * Generate random fragment ID (8 bytes)
         * Matches iOS implementation: Data((0..<8).map { _ in UInt8.random(in: 0...255) })
         */
        fun generateFragmentID(): ByteArray {
            val fragmentID = ByteArray(FRAGMENT_ID_SIZE)
            kotlin.random.Random.nextBytes(fragmentID)
            return fragmentID
        }
    }

    /**
     * Encode fragment payload to binary data
     * Matches iOS implementation exactly
     */
    fun encode(): ByteArray {
        require(index in 0..0xFFFF) { "Fragment index would truncate UInt16: $index" }
        require(total in 1..0xFFFF) { "Fragment total would truncate UInt16: $total" }
        require(index < total) { "Fragment index $index must be below total $total" }
        val payload = ByteArray(HEADER_SIZE + data.size)

        // Fragment ID (8 bytes)
        System.arraycopy(fragmentID, 0, payload, 0, FRAGMENT_ID_SIZE)

        // Index (2 bytes, big-endian) - matching iOS withUnsafeBytes(of: UInt16(index).bigEndian)
        payload[8] = ((index shr 8) and 0xFF).toByte()
        payload[9] = (index and 0xFF).toByte()

        // Total (2 bytes, big-endian) - matching iOS withUnsafeBytes(of: UInt16(fragments.count).bigEndian)
        payload[10] = ((total shr 8) and 0xFF).toByte()
        payload[11] = (total and 0xFF).toByte()

        // Original type (1 byte)
        payload[12] = originalType.toByte()

        // Fragment data
        if (data.isNotEmpty()) {
            System.arraycopy(data, 0, payload, HEADER_SIZE, data.size)
        }

        return payload
    }

    /**
     * Get fragment ID as hex string for logging/debugging
     */
    fun getFragmentIDString(): String {
        return fragmentID.joinToString("") { "%02x".format(it) }
    }

    /**
     * Validate fragment payload constraints
     */
    fun isValid(): Boolean {
        return fragmentID.size == FRAGMENT_ID_SIZE &&
               index >= 0 &&
               total > 0 &&
               index < total &&
               data.isNotEmpty()
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as FragmentPayload

        if (!fragmentID.contentEquals(other.fragmentID)) return false
        if (index != other.index) return false
        if (total != other.total) return false
        if (originalType != other.originalType) return false
        if (!data.contentEquals(other.data)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = fragmentID.contentHashCode()
        result = 31 * result + index
        result = 31 * result + total
        result = 31 * result + originalType.hashCode()
        result = 31 * result + data.contentHashCode()
        return result
    }

    override fun toString(): String {
        return "FragmentPayload(fragmentID=${getFragmentIDString()}, index=$index, total=$total, originalType=$originalType, dataSize=${data.size})"
    }
}

package com.bitchat.android.model

import android.os.Parcelable
import kotlinx.parcelize.Parcelize

/**
 * Identity announcement structure with TLV encoding
 * Compatible with iOS AnnouncementPacket TLV format
 */
@Parcelize
data class IdentityAnnouncement(
    val nickname: String,
    val noisePublicKey: ByteArray,    // Noise static public key (Curve25519.KeyAgreement)
    val signingPublicKey: ByteArray,  // Ed25519 public key for signing
    val capabilities: PeerCapabilities? = null,
    val unknownTLVs: List<UnknownAnnouncementTLV> = emptyList()
) : Parcelable {

    /**
     * TLV types matching iOS implementation
     */
    private enum class TLVType(val value: UByte) {
        NICKNAME(0x01u),
        NOISE_PUBLIC_KEY(0x02u),
        SIGNING_PUBLIC_KEY(0x03u),  // NEW: Ed25519 signing public key
        CAPABILITIES(0x05u);

        companion object {
            fun fromValue(value: UByte): TLVType? {
                return values().find { it.value == value }
            }
        }
    }

    /**
     * Encode to TLV binary data matching iOS implementation
     */
    fun encode(): ByteArray? {
        val nicknameData = nickname.toByteArray(Charsets.UTF_8)

        // Check size limits
        if (nicknameData.size > 255 || noisePublicKey.size > 255 || signingPublicKey.size > 255 ||
            unknownTLVs.any { it.value.size > 255 }) {
            return null
        }

        val result = mutableListOf<Byte>()

        // TLV for nickname
        result.add(TLVType.NICKNAME.value.toByte())
        result.add(nicknameData.size.toByte())
        result.addAll(nicknameData.toList())

        // TLV for noise public key
        result.add(TLVType.NOISE_PUBLIC_KEY.value.toByte())
        result.add(noisePublicKey.size.toByte())
        result.addAll(noisePublicKey.toList())

        // TLV for signing public key
        result.add(TLVType.SIGNING_PUBLIC_KEY.value.toByte())
        result.add(signingPublicKey.size.toByte())
        result.addAll(signingPublicKey.toList())

        // Optional little-endian feature bitfield. Old clients skip this TLV.
        capabilities?.encoded()?.let { capabilityBytes ->
            result.add(TLVType.CAPABILITIES.value.toByte())
            result.add(capabilityBytes.size.toByte())
            result.addAll(capabilityBytes.toList())
        }

        // Preserve extensions this build does not understand. This includes
        // gossip TLV 0x04 when an announcement is decoded through this model.
        unknownTLVs.forEach { tlv ->
            result.add(tlv.type.toByte())
            result.add(tlv.value.size.toByte())
            result.addAll(tlv.value.toList())
        }

        return result.toByteArray()
    }

    companion object {
        /**
         * Decode from TLV binary data matching iOS implementation
         */
        fun decode(data: ByteArray): IdentityAnnouncement? {
            // Create defensive copy
            val dataCopy = data.copyOf()

            var offset = 0
            var nickname: String? = null
            var noisePublicKey: ByteArray? = null
            var signingPublicKey: ByteArray? = null
            var capabilities: PeerCapabilities? = null
            val unknownTLVs = mutableListOf<UnknownAnnouncementTLV>()

            while (offset + 2 <= dataCopy.size) {
                // Read TLV type
                val typeValue = dataCopy[offset].toUByte()
                val type = TLVType.fromValue(typeValue)
                offset += 1

                // Read TLV length
                val length = dataCopy[offset].toUByte().toInt()
                offset += 1

                // Check bounds
                if (offset + length > dataCopy.size) return null

                // Read TLV value
                val value = dataCopy.sliceArray(offset until offset + length)
                offset += length

                // Process known TLV types, skip unknown ones for forward compatibility
                when (type) {
                    TLVType.NICKNAME -> {
                        nickname = String(value, Charsets.UTF_8)
                    }
                    TLVType.NOISE_PUBLIC_KEY -> {
                        noisePublicKey = value
                    }
                    TLVType.SIGNING_PUBLIC_KEY -> {
                        signingPublicKey = value
                    }
                    TLVType.CAPABILITIES -> {
                        capabilities = PeerCapabilities.decode(value)
                    }
                    null -> {
                        // Retain unknown extensions so callers can forward or
                        // re-encode the announcement without erasing them.
                        unknownTLVs += UnknownAnnouncementTLV(typeValue.toInt(), value)
                    }
                }
            }

            // All three fields are required
            return if (nickname != null && noisePublicKey != null && signingPublicKey != null) {
                IdentityAnnouncement(nickname, noisePublicKey, signingPublicKey, capabilities, unknownTLVs)
            } else {
                null
            }
        }

        /** Construct the announcement emitted by this Android build. */
        fun forLocalPeer(
            nickname: String,
            noisePublicKey: ByteArray,
            signingPublicKey: ByteArray
        ): IdentityAnnouncement = IdentityAnnouncement(
            nickname = nickname,
            noisePublicKey = noisePublicKey,
            signingPublicKey = signingPublicKey,
            capabilities = PeerCapabilities.LOCAL_SUPPORTED
        )
    }

    // Override equals and hashCode since we use ByteArray
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as IdentityAnnouncement

        if (nickname != other.nickname) return false
        if (!noisePublicKey.contentEquals(other.noisePublicKey)) return false
        if (!signingPublicKey.contentEquals(other.signingPublicKey)) return false
        if (capabilities != other.capabilities) return false
        if (unknownTLVs != other.unknownTLVs) return false

        return true
    }

    override fun hashCode(): Int {
        var result = nickname.hashCode()
        result = 31 * result + noisePublicKey.contentHashCode()
        result = 31 * result + signingPublicKey.contentHashCode()
        result = 31 * result + (capabilities?.hashCode() ?: 0)
        result = 31 * result + unknownTLVs.hashCode()
        return result
    }

    override fun toString(): String {
        return "IdentityAnnouncement(nickname='$nickname', noisePublicKey=${noisePublicKey.joinToString("") { "%02x".format(it) }.take(16)}..., signingPublicKey=${signingPublicKey.joinToString("") { "%02x".format(it) }.take(16)}..., capabilities=${capabilities?.rawValue})"
    }
}

package com.bitchat.android.model

import android.os.Parcelable
import kotlinx.parcelize.Parcelize

/**
 * Noise encrypted payload types and handling - 100% compatible with iOS SimplifiedBluetoothService
 * 
 * This handles all encrypted content that goes through noiseEncrypted packets:
 * - Private messages with TLV encoding
 * - Delivery acknowledgments
 * - Read receipts
 * - Future encrypted payload types
 */

/**
 * Types of payloads embedded within noiseEncrypted messages
 * Matches iOS NoisePayloadType exactly
 */
enum class NoisePayloadType(val value: UByte) {
    PRIVATE_MESSAGE(0x01u),     // Private chat message with TLV encoding
    READ_RECEIPT(0x02u),        // Message was read
    DELIVERED(0x03u),           // Message was delivered
    VOICE_FRAME(0x08u),         // Ephemeral live push-to-talk frame
    VERIFY_CHALLENGE(0x10u),    // Verification challenge
    VERIFY_RESPONSE(0x11u),     // Verification response
    FILE_TRANSFER(0x20u),
    /** Authenticated capabilities + Ed25519 binding for the current Noise generation. */
    PEER_STATE(0x21u);


    companion object {
        // #1434 prerelease iOS builds briefly emitted private files as 0x09. Keep this
        // decode-only: every NoisePayload constructed by Android still encodes FILE_TRANSFER as
        // its canonical 0x20 value, so the compatibility alias cannot leak into new traffic.
        private val PRERELEASE_FILE_TRANSFER_RAW_VALUE = 0x09u.toUByte()

        fun fromValue(value: UByte): NoisePayloadType? {
            return if (value == PRERELEASE_FILE_TRANSFER_RAW_VALUE) {
                FILE_TRANSFER
            } else {
                values().find { it.value == value }
            }
        }
    }
}

/**
 * Helper class for creating and parsing Noise payloads
 * Matches iOS NoisePayload helper exactly
 */
@Parcelize
data class NoisePayload(
    val type: NoisePayloadType,
    val data: ByteArray
) : Parcelable {

    /**
     * Encode payload with type prefix - exactly like iOS
     * Format: [type_byte][payload_data]
     */
    fun encode(): ByteArray {
        val result = ByteArray(1 + data.size)
        result[0] = type.value.toByte()
        data.copyInto(result, destinationOffset = 1)
        return result
    }

    companion object {
        /**
         * Decode payload from data - exactly like iOS
         * Expects: [type_byte][payload_data]
         */
        fun decode(data: ByteArray): NoisePayload? {
            if (data.isEmpty()) return null

            val typeValue = data[0].toUByte()
            val type = NoisePayloadType.fromValue(typeValue) ?: return null

            // Extract payload data (remaining bytes after type byte)
            val payloadData = if (data.size > 1) {
                data.copyOfRange(1, data.size)
            } else {
                ByteArray(0)
            }

            return NoisePayload(type, payloadData)
        }
    }

    // Override equals and hashCode since we use ByteArray
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as NoisePayload

        if (type != other.type) return false
        if (!data.contentEquals(other.data)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = type.hashCode()
        result = 31 * result + data.contentHashCode()
        return result
    }
}

/**
 * Private message packet with TLV encoding - matches iOS PrivateMessagePacket exactly
 */
@Parcelize
data class PrivateMessagePacket(
    val messageID: String,
    val content: String
) : Parcelable {

    /**
     * TLV types matching iOS implementation exactly
     */
    private enum class TLVType(val value: UByte) {
        MESSAGE_ID(0x00u),
        CONTENT(0x01u);

        companion object {
            fun fromValue(value: UByte): TLVType? {
                return values().find { it.value == value }
            }
        }
    }

    /**
     * Encode to TLV binary data - exactly like iOS
     * Format: [type][length][value] for each field
     */
    fun encode(): ByteArray? {
        val messageIDData = messageID.toByteArray(Charsets.UTF_8)
        val contentData = content.toByteArray(Charsets.UTF_8)

        // Check size limits (TLV length field is 1 byte = max 255)
        if (messageIDData.size > 255 || contentData.size > 255) {
            return null
        }

        val result = mutableListOf<Byte>()

        // TLV for messageID
        result.add(TLVType.MESSAGE_ID.value.toByte())
        result.add(messageIDData.size.toByte())
        result.addAll(messageIDData.toList())

        // TLV for content
        result.add(TLVType.CONTENT.value.toByte())
        result.add(contentData.size.toByte())
        result.addAll(contentData.toList())

        return result.toByteArray()
    }

    companion object {
        /**
         * Decode from TLV binary data - exactly like iOS
         */
        fun decode(data: ByteArray): PrivateMessagePacket? {
            var offset = 0
            var messageID: String? = null
            var content: String? = null

            while (offset + 2 <= data.size) {
                // Read TLV type
                val typeValue = data[offset].toUByte()
                val type = TLVType.fromValue(typeValue) ?: return null
                offset += 1

                // Read TLV length
                val length = data[offset].toUByte().toInt()
                offset += 1

                // Check bounds
                if (offset + length > data.size) return null

                // Read TLV value
                val value = data.copyOfRange(offset, offset + length)
                offset += length

                when (type) {
                    TLVType.MESSAGE_ID -> {
                        messageID = String(value, Charsets.UTF_8)
                    }
                    TLVType.CONTENT -> {
                        content = String(value, Charsets.UTF_8)
                    }
                }
            }

            return if (messageID != null && content != null) {
                PrivateMessagePacket(messageID, content)
            } else {
                null
            }
        }
    }

    override fun toString(): String {
        return "PrivateMessagePacket(messageID='$messageID', content='${content.take(50)}${if (content.length > 50) "..." else ""}')"
    }
}

/**
 * Read receipt data class for transport compatibility
 */
@Parcelize
data class ReadReceipt(
    val originalMessageID: String,
    val readerPeerID: String? = null
) : Parcelable

package com.bitchat.android.model

import android.os.Parcelable
import kotlinx.parcelize.Parcelize

/**
 * Feature bits advertised in IdentityAnnouncement TLV 0x05.
 *
 * The wire representation matches iOS: a minimal little-endian bitfield that
 * always contains at least one byte. Unknown bits in the low 64 bits are kept
 * so a decode/re-encode cycle does not erase capabilities added by newer
 * clients.
 */
@Parcelize
data class PeerCapabilities(val rawValue: Long) : Parcelable {
    fun contains(capability: PeerCapabilities): Boolean =
        (rawValue and capability.rawValue) == capability.rawValue

    fun encoded(): ByteArray {
        var remaining = rawValue
        val bytes = mutableListOf<Byte>()
        do {
            bytes += remaining.toByte()
            remaining = remaining ushr 8
        } while (remaining != 0L)
        return bytes.toByteArray()
    }

    companion object {
        val NONE = PeerCapabilities(0)

        /** Noise-encrypted private BitchatFilePacket using payload type 0x20. */
        val PRIVATE_MEDIA = PeerCapabilities(1L shl 8)

        /** Capabilities implemented by this Android build. */
        val LOCAL_SUPPORTED = PRIVATE_MEDIA

        /**
         * Decode the low 64 bits and ignore any future extension bytes, which
         * is the same forward-compatible behavior used by iOS.
         */
        fun decode(data: ByteArray): PeerCapabilities {
            var rawValue = 0L
            data.take(8).forEachIndexed { index, byte ->
                rawValue = rawValue or ((byte.toLong() and 0xFF) shl (8 * index))
            }
            return PeerCapabilities(rawValue)
        }
    }
}

/** An announcement TLV not understood by this build, retained verbatim. */
@Parcelize
class UnknownAnnouncementTLV(
    val type: Int,
    val value: ByteArray
) : Parcelable {
    init {
        require(type in 0..0xFF) { "TLV type must fit in one byte" }
    }

    override fun equals(other: Any?): Boolean =
        this === other ||
            (other is UnknownAnnouncementTLV && type == other.type && value.contentEquals(other.value))

    override fun hashCode(): Int = 31 * type + value.contentHashCode()
}

package com.bitchat.android.model

import com.bitchat.android.sync.SyncDefaults

/**
 * REQUEST_SYNC payload using GCS (Golomb-Coded Set) parameters.
 * TLV (type, length16, value), types:
 *  - 0x01: P (uint8) — Golomb-Rice parameter
 *  - 0x02: M (uint32, big-endian) — hash range (N * 2^P)
 *  - 0x03: data (opaque) — GR bitstream bytes
 */
data class RequestSyncPacket(
    val p: Int,
    val m: Long,
    val data: ByteArray
) {
    fun encode(): ByteArray {
        val out = ArrayList<Byte>()
        fun putTLV(t: Int, v: ByteArray) {
            out.add(t.toByte())
            val len = v.size
            out.add(((len ushr 8) and 0xFF).toByte())
            out.add((len and 0xFF).toByte())
            out.addAll(v.toList())
        }
        // P
        putTLV(0x01, byteArrayOf(p.toByte()))
        // M (uint32)
        val m32 = m.coerceAtMost(0xffff_ffffL)
        putTLV(
            0x02,
            byteArrayOf(
                ((m32 ushr 24) and 0xFF).toByte(),
                ((m32 ushr 16) and 0xFF).toByte(),
                ((m32 ushr 8) and 0xFF).toByte(),
                (m32 and 0xFF).toByte()
            )
        )
        // data
        putTLV(0x03, data)
        return out.toByteArray()
    }

    companion object {
        // Receiver-side safety limit (configurable constant)
        const val MAX_ACCEPT_FILTER_BYTES: Int = SyncDefaults.MAX_ACCEPT_FILTER_BYTES

        fun decode(data: ByteArray): RequestSyncPacket? {
            var off = 0
            var p: Int? = null
            var m: Long? = null
            var payload: ByteArray? = null

            while (off + 3 <= data.size) {
                val t = (data[off].toInt() and 0xFF); off += 1
                val len = ((data[off].toInt() and 0xFF) shl 8) or (data[off+1].toInt() and 0xFF); off += 2
                if (off + len > data.size) return null
                val v = data.copyOfRange(off, off + len); off += len
                when (t) {
                    0x01 -> if (len == 1) p = (v[0].toInt() and 0xFF)
                    0x02 -> if (len == 4) {
                        val mm = ((v[0].toLong() and 0xFF) shl 24) or
                                 ((v[1].toLong() and 0xFF) shl 16) or
                                 ((v[2].toLong() and 0xFF) shl 8) or
                                 (v[3].toLong() and 0xFF)
                        m = mm
                    }
                    0x03 -> {
                        if (v.size > MAX_ACCEPT_FILTER_BYTES) return null
                        payload = v
                    }
                }
            }

            val pp = p ?: return null
            val mm = m ?: return null
            val dd = payload ?: return null
            if (pp < 1 || mm <= 0L) return null
            return RequestSyncPacket(pp, mm, dd)
        }
    }
}

package com.bitchat.android.net

import android.app.Application
import android.util.Log
import com.bitchat.android.util.AppConstants
import info.guardianproject.arti.ArtiLogListener
import info.guardianproject.arti.ArtiProxy
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.launch
import kotlinx.coroutines.delay
import kotlinx.coroutines.Job
import kotlinx.coroutines.withTimeoutOrNull
import kotlinx.coroutines.CompletableDeferred

import java.net.InetSocketAddress
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.atomic.AtomicLong

/**
 * Tor provider implementation using custom-built Arti (Tor-in-Rust).
 *
 * This singleton provides Tor anonymity features using a custom Arti build
 * compiled with 16KB page size support for Google Play compliance.
 *
 * Based on the original TorManager implementation.
 */
class ArtiTorManager private constructor() {
    enum class TorState {
        OFF,
        STARTING,
        BOOTSTRAPPING,
        RUNNING,
        STOPPING,
        ERROR
    }

    data class TorStatus(
        val mode: TorMode = TorMode.OFF,
        val running: Boolean = false,
        val bootstrapPercent: Int = 0,
        val lastLogLine: String = "",
        val state: TorState = TorState.OFF
    )

    companion object {
        private const val TAG = "ArtiTorManager"
        private const val DEFAULT_SOCKS_PORT = AppConstants.Tor.DEFAULT_SOCKS_PORT
        private const val RESTART_DELAY_MS = AppConstants.Tor.RESTART_DELAY_MS
        private const val INACTIVITY_TIMEOUT_MS = AppConstants.Tor.INACTIVITY_TIMEOUT_MS
        private const val MAX_RETRY_ATTEMPTS = AppConstants.Tor.MAX_RETRY_ATTEMPTS
        private const val STOP_TIMEOUT_MS = AppConstants.Tor.STOP_TIMEOUT_MS

        @Volatile
        private var INSTANCE: ArtiTorManager? = null

        fun getInstance(): ArtiTorManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ArtiTorManager().also { INSTANCE = it }
            }
        }
    }

    private val appScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    @Volatile
    private var initialized = false
    @Volatile
    private var socksAddr: InetSocketAddress? = null
    @Volatile
    private var artiProxy: ArtiProxy? = null
    @Volatile
    private var lastMode: TorMode = TorMode.OFF
    private val applyMutex = Mutex()
    @Volatile
    private var desiredMode: TorMode = TorMode.OFF
    @Volatile
    private var currentSocksPort: Int = DEFAULT_SOCKS_PORT
    @Volatile
    private var lastLogTime = AtomicLong(0L)
    @Volatile
    private var retryAttempts = 0
    @Volatile
    private var bindRetryAttempts = 0
    private var inactivityJob: Job? = null
    private var retryJob: Job? = null
    private var currentApplication: Application? = null

    private enum class LifecycleState { STOPPED, STARTING, RUNNING, STOPPING }

    @Volatile
    private var lifecycleState: LifecycleState = LifecycleState.STOPPED

    private val _statusFlow = MutableStateFlow(
        TorStatus(
            mode = TorMode.OFF,
            running = false,
            bootstrapPercent = 0,
            lastLogLine = "",
            state = TorState.OFF
        )
    )

    val statusFlow: StateFlow<TorStatus> = _statusFlow.asStateFlow()

    private val stateChangeDeferred = AtomicReference<CompletableDeferred<TorState>?>(null)

    fun isProxyEnabled(): Boolean {
        val s = _statusFlow.value
        return s.mode != TorMode.OFF && s.running && s.bootstrapPercent >= 100 &&
                socksAddr != null && s.state == TorState.RUNNING
    }

    fun init(application: Application) {
        if (initialized) return
        synchronized(this) {
            if (initialized) return
            initialized = true
            currentApplication = application
            TorPreferenceManager.init(application)

            val logListener = ArtiLogListener { logLine ->
                val text = logLine ?: return@ArtiLogListener
                val s = text
                lastLogTime.set(System.currentTimeMillis())
                _statusFlow.update { it.copy(lastLogLine = s) }
                handleArtiLogLine(s)
                if (_statusFlow.value.bootstrapPercent < 100) {
                    armBootstrapInactivityWatchdog()
                }
            }

            artiProxy = ArtiProxy.Builder(application)
                .setSocksPort(currentSocksPort)
                .setDnsPort(currentSocksPort + 1)
                .setLogListener(logListener)
                .build()

            val savedMode = TorPreferenceManager.get(application)
            if (savedMode == TorMode.ON) {
                if (currentSocksPort < DEFAULT_SOCKS_PORT) {
                    currentSocksPort = DEFAULT_SOCKS_PORT
                }
                desiredMode = savedMode
                socksAddr = InetSocketAddress("127.0.0.1", currentSocksPort)
                try {
                    OkHttpProvider.reset()
                } catch (_: Throwable) {
                }  // Only reset OkHttp during init
            }
            appScope.launch {
                applyMode(application, savedMode)
            }

            appScope.launch {
                TorPreferenceManager.modeFlow.collect { mode ->
                    applyMode(application, mode)
                }
            }
        }
    }

    fun currentSocksAddress(): InetSocketAddress? = socksAddr

    /**
     * Wait until the currently selected HTTP route can be used.
     *
     * When Tor mode is enabled, [socksAddr] is intentionally published before
     * bootstrap completes so clients fail closed instead of leaking traffic
     * directly. Callers that initiate one-shot HTTP work should wait here rather
     * than repeatedly connecting to a SOCKS port that is not listening yet.
     */
    suspend fun awaitSelectedRoute(timeoutMs: Long): Boolean {
        if (currentSocksAddress() == null || isProxyEnabled()) {
            return true
        }

        return withTimeoutOrNull(timeoutMs) {
            statusFlow.first {
                currentSocksAddress() == null || isProxyEnabled()
            }
            true
        } ?: false
    }

    suspend fun applyMode(application: Application, mode: TorMode) {
        applyMutex.withLock {
            try {
                desiredMode = mode
                lastMode = mode
                val s = _statusFlow.value
                if (mode == s.mode && mode != TorMode.OFF &&
                    (lifecycleState == LifecycleState.STARTING || lifecycleState == LifecycleState.RUNNING)
                ) {
                    return
                }
                when (mode) {
                    TorMode.OFF -> {
                        Log.i(TAG, "applyMode: OFF -> stopping tor")
                        lifecycleState = LifecycleState.STOPPING
                        _statusFlow.value = _statusFlow.value.copy(
                            mode = TorMode.OFF,
                            running = false,
                            bootstrapPercent = 0,
                            state = TorState.STOPPING
                        )
                        stopArti()
                        waitForStateTransition(target = TorState.OFF, timeoutMs = STOP_TIMEOUT_MS)
                        socksAddr = null
                        _statusFlow.value = _statusFlow.value.copy(
                            mode = TorMode.OFF,
                            running = false,
                            bootstrapPercent = 0,
                            state = TorState.OFF
                        )
                        currentSocksPort = DEFAULT_SOCKS_PORT
                        bindRetryAttempts = 0
                        lifecycleState = LifecycleState.STOPPED
                        resetNetworkConnections()
                    }

                    TorMode.ON -> {
                        Log.i(TAG, "applyMode: ON -> starting arti")
                        if (currentSocksPort < DEFAULT_SOCKS_PORT) {
                            currentSocksPort = DEFAULT_SOCKS_PORT
                        }
                        bindRetryAttempts = 0
                        lifecycleState = LifecycleState.STARTING
                        _statusFlow.value = _statusFlow.value.copy(
                            mode = TorMode.ON,
                            running = false,
                            bootstrapPercent = 0,
                            state = TorState.STARTING
                        )
                        socksAddr = InetSocketAddress("127.0.0.1", currentSocksPort)
                        resetNetworkConnections()
                        startArti(application, useDelay = false)
                        appScope.launch {
                            waitUntilBootstrapped()
                            if (_statusFlow.value.running && desiredMode == TorMode.ON) {
                                socksAddr = InetSocketAddress("127.0.0.1", currentSocksPort)
                                Log.i(TAG, "Tor ON: proxy set to ${socksAddr}")
                                resetNetworkConnections()
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to apply Arti mode: ${e.message}")
            }
        }
    }

    private suspend fun startArti(application: Application, useDelay: Boolean = false) {
        try {
            stopArtiAndWait()
            if (useDelay) {
                delay(RESTART_DELAY_MS)
            }

            val proxy = artiProxy ?: run {
                Log.e(TAG, "ArtiProxy not initialized! This should not happen.")
                _statusFlow.update { it.copy(state = TorState.ERROR) }
                return
            }

            proxy.start()
            lastLogTime.set(System.currentTimeMillis())

            _statusFlow.update {
                it.copy(
                    running = true,
                    bootstrapPercent = 0,
                    state = TorState.STARTING
                )
            }
            lifecycleState = LifecycleState.RUNNING
            startInactivityMonitoring()

        } catch (e: Exception) {
            Log.e(TAG, "Error starting Arti on port $currentSocksPort: ${e.message}")
            _statusFlow.update { it.copy(state = TorState.ERROR) }

            val isBindError = isBindError(e)
            if (isBindError && bindRetryAttempts < MAX_RETRY_ATTEMPTS) {
                bindRetryAttempts++
                currentSocksPort++
                Log.w(TAG, "Port bind failed (attempt $bindRetryAttempts/$MAX_RETRY_ATTEMPTS), retrying with port $currentSocksPort")
                socksAddr = InetSocketAddress("127.0.0.1", currentSocksPort)
                resetNetworkConnections()
                startArti(application, useDelay = false)
            } else if (isBindError) {
                Log.e(TAG, "Max bind retry attempts reached ($MAX_RETRY_ATTEMPTS), giving up")
                lifecycleState = LifecycleState.STOPPED
                _statusFlow.update {
                    it.copy(
                        running = false,
                        bootstrapPercent = 0,
                        state = TorState.ERROR
                    )
                }
            } else {
                scheduleRetry(application)
            }
        }
    }

    private fun isBindError(exception: Exception): Boolean {
        val message = exception.message?.lowercase() ?: ""
        return message.contains("bind") ||
                message.contains("address already in use") ||
                message.contains("port") && message.contains("use") ||
                message.contains("permission denied") && message.contains("port") ||
                message.contains("could not bind")
    }

    /**
     * Reset network connections after Tor state changes.
     * Rebuilds OkHttp clients and reconnects Nostr relays.
     */
    private fun resetNetworkConnections() {
        try {
            OkHttpProvider.reset()
        } catch (_: Throwable) {
        }
        try {
            com.bitchat.android.nostr.NostrRelayManager.shared.resetAllConnections()
        } catch (_: Throwable) {
        }
    }

    private fun stopArtiInternal() {
        try {
            val proxy = artiProxy
            if (proxy != null) {
                try {
                    proxy.stop()
                } catch (_: Throwable) {
                }
            }
            stopInactivityMonitoring()
            stopRetryMonitoring()
        } catch (e: Exception) {
            Log.w(TAG, "Error stopping Arti: ${e.message}")
        }
    }

    private fun stopArti() {
        stopArtiInternal()
        socksAddr = null
        _statusFlow.value = _statusFlow.value.copy(
            running = false,
            bootstrapPercent = 0,
            state = TorState.STOPPING
        )
    }

    private suspend fun stopArtiAndWait(timeoutMs: Long = STOP_TIMEOUT_MS) {
        stopArtiInternal()
        waitForStateTransition(target = TorState.OFF, timeoutMs = timeoutMs)
        delay(200)
    }

    private suspend fun restartArti(application: Application) {
        Log.i(TAG, "Restarting Arti (keeping SOCKS proxy enabled)...")
        stopArtiAndWait()
        delay(RESTART_DELAY_MS)
        startArti(application, useDelay = false)
    }

    private fun startInactivityMonitoring() {
        armBootstrapInactivityWatchdog()
    }

    /**
     * One-shot startup watchdog. Arti log activity re-arms it and successful bootstrap cancels it,
     * so a healthy background Tor process has no permanent five-second polling coroutine.
     */
    private fun armBootstrapInactivityWatchdog() {
        inactivityJob?.cancel()
        if (lifecycleState != LifecycleState.RUNNING || _statusFlow.value.bootstrapPercent >= 100) {
            inactivityJob = null
            return
        }
        inactivityJob = appScope.launch {
            delay(INACTIVITY_TIMEOUT_MS)
            val timeSinceLastActivity = System.currentTimeMillis() - lastLogTime.get()
            if (
                timeSinceLastActivity >= INACTIVITY_TIMEOUT_MS &&
                _statusFlow.value.mode == TorMode.ON &&
                _statusFlow.value.bootstrapPercent < 100 &&
                lifecycleState == LifecycleState.RUNNING
            ) {
                Log.w(TAG, "Bootstrap inactivity detected (${timeSinceLastActivity}ms), restarting Arti")
                currentApplication?.let { restartArti(it) }
            }
        }
    }

    private fun stopInactivityMonitoring() {
        inactivityJob?.cancel()
        inactivityJob = null
    }

    private fun scheduleRetry(application: Application) {
        retryJob?.cancel()
        if (retryAttempts < MAX_RETRY_ATTEMPTS) {
            retryAttempts++
            val delayMs = (1000L * (1 shl retryAttempts)).coerceAtMost(30000L)
            Log.w(TAG, "Scheduling Arti retry attempt $retryAttempts in ${delayMs}ms")
            retryJob = appScope.launch {
                delay(delayMs)
                val currentMode = _statusFlow.value.mode
                if (currentMode == TorMode.ON) {
                    restartArti(application)
                }
            }
        } else {
            Log.e(TAG, "Max retry attempts reached, giving up on Arti connection")
        }
    }

    private fun stopRetryMonitoring() {
        retryJob?.cancel()
        retryJob = null
    }

    private suspend fun waitUntilBootstrapped() {
        val current = _statusFlow.value
        if (!current.running) return
        if (current.bootstrapPercent >= 100 && current.state == TorState.RUNNING) return
        while (true) {
            val s = statusFlow.first {
                (it.bootstrapPercent >= 100 && it.state == TorState.RUNNING) ||
                        !it.running ||
                        it.state == TorState.ERROR
            }
            if (!s.running || s.state == TorState.ERROR) return
            if (s.bootstrapPercent >= 100 && s.state == TorState.RUNNING) return
        }
    }

    private fun handleArtiLogLine(s: String) {
        val currentState = _statusFlow.value.state
        val currentLifecycle = lifecycleState

        when {
            s.contains("AMEx: state changed to Initialized", ignoreCase = true) -> {
                if (currentLifecycle != LifecycleState.STARTING && currentLifecycle != LifecycleState.RUNNING) {
                    return
                }
                _statusFlow.update { it.copy(state = TorState.STARTING) }
                completeWaitersIf(TorState.STARTING)
            }

            s.contains("AMEx: state changed to Starting", ignoreCase = true) -> {
                if (currentLifecycle != LifecycleState.STARTING && currentLifecycle != LifecycleState.RUNNING) {
                    return
                }
                _statusFlow.update { it.copy(state = TorState.STARTING) }
                completeWaitersIf(TorState.STARTING)
            }

            s.contains(
                "Sufficiently bootstrapped; system SOCKS now functional",
                ignoreCase = true
            ) -> {
                if (currentLifecycle != LifecycleState.RUNNING) {
                    return
                }
                _statusFlow.update {
                    it.copy(
                        bootstrapPercent = 75,
                        state = TorState.BOOTSTRAPPING
                    )
                }
                retryAttempts = 0
                bindRetryAttempts = 0
                startInactivityMonitoring()
            }

            s.contains("We have found that guard [scrubbed] is usable.", ignoreCase = true) -> {
                if (currentLifecycle != LifecycleState.RUNNING) {
                    return
                }
                _statusFlow.update {
                    it.copy(
                        state = TorState.RUNNING,
                        bootstrapPercent = 100,
                        running = true
                    )
                }
                stopInactivityMonitoring()
                completeWaitersIf(TorState.RUNNING)
            }

            s.contains("AMEx: state changed to Stopping", ignoreCase = true) -> {
                if (currentLifecycle != LifecycleState.STOPPING) {
                    return
                }
                _statusFlow.update {
                    it.copy(
                        state = TorState.STOPPING,
                        running = false
                    )
                }
            }

            s.contains("AMEx: state changed to Stopped", ignoreCase = true) -> {
                if (currentLifecycle != LifecycleState.STOPPING && currentLifecycle != LifecycleState.STOPPED) {
                    return
                }
                _statusFlow.update {
                    it.copy(
                        state = TorState.OFF,
                        running = false,
                        bootstrapPercent = 0
                    )
                }
                completeWaitersIf(TorState.OFF)
            }

            s.contains("Another process has the lock on our state files", ignoreCase = true) -> {
                _statusFlow.update { it.copy(state = TorState.ERROR) }
            }
        }
    }

    private fun completeWaitersIf(state: TorState) {
        stateChangeDeferred.getAndSet(null)?.let { def ->
            def.complete(state)
        }
    }

    private suspend fun waitForStateTransition(target: TorState, timeoutMs: Long): TorState? {
        val def = CompletableDeferred<TorState>()
        stateChangeDeferred.getAndSet(def)?.cancel()
        return withTimeoutOrNull(timeoutMs) {
            val cur = _statusFlow.value.state
            if (cur == target) return@withTimeoutOrNull cur
            def.await()
        }
    }

    fun isTorAvailable(): Boolean = true
}

package com.bitchat.android.net

import okhttp3.OkHttpClient
import java.net.InetSocketAddress
import java.net.Proxy
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicReference

/**
 * Centralized OkHttp provider to ensure all network traffic honors Tor settings.
 */
object OkHttpProvider {
    private val httpClientRef = AtomicReference<OkHttpClient?>(null)
    private val wsClientRef = AtomicReference<OkHttpClient?>(null)

    fun reset() {
        httpClientRef.set(null)
        wsClientRef.set(null)
    }

    fun httpClient(): OkHttpClient {
        httpClientRef.get()?.let { return it }
        val client = baseBuilderForCurrentProxy()
            .callTimeout(15, TimeUnit.SECONDS)
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(15, TimeUnit.SECONDS)
            .build()
        httpClientRef.set(client)
        return client
    }

    fun webSocketClient(): OkHttpClient {
        wsClientRef.get()?.let { return it }
        val client = baseBuilderForCurrentProxy()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(0, TimeUnit.SECONDS)
            .writeTimeout(10, TimeUnit.SECONDS)
            .build()
        wsClientRef.set(client)
        return client
    }

    private fun baseBuilderForCurrentProxy(): OkHttpClient.Builder {
        val builder = OkHttpClient.Builder()
        val torProvider = ArtiTorManager.getInstance()
        val socks: InetSocketAddress? = torProvider.currentSocksAddress()
        // If a SOCKS address is defined, always use it. TorProvider sets this as soon as Tor mode is ON,
        // even before bootstrap, to prevent any direct connections from occurring.
        if (socks != null) {
            val proxy = Proxy(Proxy.Type.SOCKS, socks)
            builder.proxy(proxy)
        }
        return builder
    }
}

package com.bitchat.android.net

enum class TorMode {
    OFF,
    ON
}

package com.bitchat.android.net

import android.content.Context
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

object TorPreferenceManager {
    private const val PREFS_NAME = "bitchat_settings"
    private const val KEY_TOR_MODE = "tor_mode"

    private val _modeFlow = MutableStateFlow(TorMode.ON)
    val modeFlow: StateFlow<TorMode> = _modeFlow

    fun init(context: Context) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val saved = prefs.getString(KEY_TOR_MODE, TorMode.ON.name)
        val mode = runCatching { TorMode.valueOf(saved ?: TorMode.ON.name) }.getOrDefault(TorMode.ON)
        _modeFlow.value = mode
    }

    fun set(context: Context, mode: TorMode) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putString(KEY_TOR_MODE, mode.name).apply()
        _modeFlow.value = mode
    }

    fun get(context: Context): TorMode {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val saved = prefs.getString(KEY_TOR_MODE, TorMode.ON.name)
        return runCatching { TorMode.valueOf(saved ?: TorMode.ON.name) }.getOrDefault(TorMode.ON)
    }
}

package com.bitchat.android.noise

import android.util.Log
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.SecretKeyFactory
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.PBEKeySpec
import javax.crypto.spec.SecretKeySpec

/**
 * Channel encryption for password-protected channels - 100% compatible with iOS implementation
 * 
 * Uses PBKDF2 key derivation with channel name as salt and AES-256-GCM for encryption.
 * This is separate from Noise sessions and used for group channels with shared passwords.
 */
class NoiseChannelEncryption {

    companion object {
        private const val TAG = "NoiseChannelEncryption"

        // PBKDF2 parameters (same as iOS)
        private const val PBKDF2_ITERATIONS = 100000
        private const val KEY_LENGTH = 256 // 256-bit AES key
    }

    // Channel keys storage (channelName -> AES key)
    private val channelKeys = ConcurrentHashMap<String, SecretKeySpec>()

    // Channel passwords (for rekey operations)
    private val channelPasswords = ConcurrentHashMap<String, String>()

    // MARK: - Channel Password Management

    /**
     * Set password for a channel and derive encryption key
     */
    fun setChannelPassword(password: String, channel: String) {
        try {
            if (password.isEmpty()) {
                Log.w(TAG, "Empty password provided for channel $channel")
                return
            }

            // Derive key from password using PBKDF2 (same as iOS)
            val key = deriveChannelKey(password, channel)

            // Store key and password
            channelKeys[channel] = key
            channelPasswords[channel] = password

            Log.d(TAG, "Set password for channel $channel")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to set password for channel $channel: ${e.message}")
        }
    }

    /**
     * Remove password for a channel
     */
    fun removeChannelPassword(channel: String) {
        channelKeys.remove(channel)
        channelPasswords.remove(channel)
        Log.d(TAG, "Removed password for channel $channel")
    }

    /**
     * Check if we have a key for a channel
     */
    fun hasChannelKey(channel: String): Boolean {
        return channelKeys.containsKey(channel)
    }

    /**
     * Get channel password (if available)
     */
    fun getChannelPassword(channel: String): String? {
        return channelPasswords[channel]
    }

    // MARK: - Encryption/Decryption

    /**
     * Encrypt a message for a channel
     * Returns encrypted data including IV
     */
    fun encryptChannelMessage(message: String, channel: String): ByteArray {
        val key = channelKeys[channel]
            ?: throw IllegalStateException("No key available for channel $channel")

        val messageBytes = message.toByteArray(Charsets.UTF_8)

        return try {
            val cipher = Cipher.getInstance("AES/GCM/NoPadding")
            cipher.init(Cipher.ENCRYPT_MODE, key)

            val iv = cipher.iv
            val encryptedData = cipher.doFinal(messageBytes)

            // Combine IV and encrypted data (same format as iOS)
            val result = ByteArray(iv.size + encryptedData.size)
            System.arraycopy(iv, 0, result, 0, iv.size)
            System.arraycopy(encryptedData, 0, result, iv.size, encryptedData.size)

            result
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encrypt channel message: ${e.message}")
            throw e
        }
    }

    /**
     * Decrypt a message for a channel
     * Expects data format: IV + encrypted_data + auth_tag
     */
    fun decryptChannelMessage(encryptedData: ByteArray, channel: String): String {
        val key = channelKeys[channel]
            ?: throw IllegalStateException("No key available for channel $channel")

        if (encryptedData.size < 16) { // 12 bytes IV + minimum ciphertext
            throw IllegalArgumentException("Encrypted data too short")
        }

        return try {
            val cipher = Cipher.getInstance("AES/GCM/NoPadding")

            // Extract IV (first 12 bytes for GCM) and ciphertext
            val iv = encryptedData.sliceArray(0..11)
            val ciphertext = encryptedData.sliceArray(12 until encryptedData.size)

            val gcmSpec = GCMParameterSpec(128, iv) // 128-bit authentication tag
            cipher.init(Cipher.DECRYPT_MODE, key, gcmSpec)

            val decryptedBytes = cipher.doFinal(ciphertext)
            String(decryptedBytes, Charsets.UTF_8)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decrypt channel message: ${e.message}")
            throw e
        }
    }

    // MARK: - Key Derivation

    /**
     * Derive AES key from password using PBKDF2 (same parameters as iOS)
     */
    private fun deriveChannelKey(password: String, channel: String): SecretKeySpec {
        try {
            val factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")

            // Use channel name as salt (UTF-8 bytes)
            val salt = channel.toByteArray(Charsets.UTF_8)

            val spec = PBEKeySpec(
                password.toCharArray(),
                salt,
                PBKDF2_ITERATIONS,
                KEY_LENGTH
            )

            val secretKey = factory.generateSecret(spec)
            return SecretKeySpec(secretKey.encoded, "AES")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to derive channel key: ${e.message}")
            throw e
        }
    }

    // MARK: - Key Verification

    /**
     * Calculate key commitment (SHA-256 hash) for verification
     * This allows peers to verify they have the same key without revealing it
     */
    fun calculateKeyCommitment(channel: String): String? {
        val key = channelKeys[channel] ?: return null

        return try {
            val digest = MessageDigest.getInstance("SHA-256")
            val hash = digest.digest(key.encoded)
            hash.joinToString("") { "%02x".format(it) }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to calculate key commitment: ${e.message}")
            null
        }
    }

    /**
     * Verify key commitment matches our derived key
     */
    fun verifyKeyCommitment(channel: String, commitment: String): Boolean {
        val ourCommitment = calculateKeyCommitment(channel)
        return ourCommitment?.lowercase() == commitment.lowercase()
    }

    // MARK: - Channel Key Sharing

    /**
     * Create channel key packet for sharing via Noise session
     * Returns encrypted packet that can be sent to other peers
     */
    fun createChannelKeyPacket(password: String, channel: String): ByteArray? {
        return try {
            // Create key packet with channel and password
            val packet = mapOf(
                "channel" to channel,
                "password" to password,
                "timestamp" to System.currentTimeMillis()
            )

            // Simple JSON encoding for now (could be replaced with more efficient format)
            val json = com.google.gson.Gson().toJson(packet)
            json.toByteArray(Charsets.UTF_8)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to create channel key packet: ${e.message}")
            null
        }
    }

    /**
     * Process received channel key packet
     * Returns (channel, password) if successful
     */
    fun processChannelKeyPacket(data: ByteArray): Pair<String, String>? {
        return try {
            val json = String(data, Charsets.UTF_8)
            val packet = com.google.gson.Gson().fromJson(json, Map::class.java) as Map<String, Any>

            val channel = packet["channel"] as? String
            val password = packet["password"] as? String

            if (channel != null && password != null) {
                Pair(channel, password)
            } else {
                Log.w(TAG, "Invalid channel key packet format")
                null
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to process channel key packet: ${e.message}")
            null
        }
    }

    // MARK: - Debug and Management

    /**
     * Get debug information
     */
    fun getDebugInfo(): String = buildString {
        appendLine("=== Channel Encryption Debug ===")
        appendLine("Active channels: ${channelKeys.size}")

        channelKeys.keys.forEach { channel ->
            val hasPassword = channelPasswords.containsKey(channel)
            val commitment = calculateKeyCommitment(channel)?.take(16)
            appendLine("  $channel: hasPassword=$hasPassword, commitment=${commitment}...")
        }
    }

    /**
     * Get list of channels with keys
     */
    fun getActiveChannels(): Set<String> {
        return channelKeys.keys.toSet()
    }

    /**
     * Clear all channel data
     */
    fun clear() {
        channelKeys.clear()
        channelPasswords.clear()
        Log.d(TAG, "Cleared all channel encryption data")
    }
}

package com.bitchat.android.noise

import android.content.Context
import android.util.Log
import com.bitchat.android.identity.SecureIdentityStateManager
import com.bitchat.android.mesh.PeerFingerprintManager
import com.bitchat.android.noise.southernstorm.protocol.Noise
import java.security.MessageDigest
import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap

/**
 * Main Noise encryption service - 100% compatible with iOS implementation
 * 
 * This service manages:
 * - Static identity keys (persistent across sessions)
 * - Noise session management for each peer
 * - Channel encryption using password-derived keys
 * - Peer fingerprint mapping and identity persistence
 */
class NoiseEncryptionService(private val context: Context) {

    companion object {
        private const val TAG = "NoiseEncryptionService"

        // Session limits for performance and security
        private const val REKEY_TIME_LIMIT = com.bitchat.android.util.AppConstants.Noise.REKEY_TIME_LIMIT_MS // 1 hour (same as iOS)
        private const val REKEY_MESSAGE_LIMIT = com.bitchat.android.util.AppConstants.Noise.REKEY_MESSAGE_LIMIT_ENCRYPTION // 1k messages (matches iOS) (same as iOS)
    }

    // Static identity key (persistent across app restarts) - loaded from secure storage
    private var staticIdentityPrivateKey: ByteArray
    private var staticIdentityPublicKey: ByteArray

    // Ed25519 signing key (persistent across app restarts) - loaded from secure storage
    private var signingPrivateKey: ByteArray
    private var signingPublicKey: ByteArray

    // Session management
    private lateinit var sessionManager: NoiseSessionManager

    // Channel encryption for password-protected channels
    private val channelEncryption = NoiseChannelEncryption()

    // Identity management for peer ID rotation support
    private val identityStateManager: SecureIdentityStateManager

    // Centralized fingerprint management - NO LOCAL STORAGE
    private val fingerprintManager = PeerFingerprintManager.getInstance()

    // Callbacks
    var onPeerAuthenticated: ((String, String) -> Unit)? = null // (peerID, fingerprint)
    var onHandshakeRequired: ((String) -> Unit)? = null // peerID needs handshake

    init {
        // Initialize identity state manager for persistent storage
        identityStateManager = SecureIdentityStateManager(context)

        // Load or create keys - temporary placeholders
        staticIdentityPrivateKey = ByteArray(32)
        staticIdentityPublicKey = ByteArray(32)
        signingPrivateKey = ByteArray(32)
        signingPublicKey = ByteArray(32)

        loadOrGenerateKeys()

        // Initialize session manager
        initializeSessionManager()
    }

    private fun initializeSessionManager() {
        // Create new session manager with current keys
        val localPeerID = calculateFingerprint(staticIdentityPublicKey).take(16)
        sessionManager = NoiseSessionManager(staticIdentityPrivateKey, staticIdentityPublicKey, localPeerID)

        // Set up session callbacks
        sessionManager.onSessionEstablished = { peerID, remoteStaticKey ->
            handleSessionEstablished(peerID, remoteStaticKey)
        }

        // Ensure any other callbacks are wired if needed
        // sessionManager.onSessionFailed could be wired if we exposed it
    }

    private fun loadOrGenerateKeys() {
        // Load or create static identity key (persistent across sessions)
        val loadedKeyPair = identityStateManager.loadStaticKey()
        if (loadedKeyPair != null) {
            staticIdentityPrivateKey = loadedKeyPair.first
            staticIdentityPublicKey = loadedKeyPair.second
            Log.d(TAG, "Identity loaded: ${calculateFingerprint(staticIdentityPublicKey).take(16)}")
        } else {
            // Generate new identity key pair
            val keyPair = generateKeyPair()
            staticIdentityPrivateKey = keyPair.first
            staticIdentityPublicKey = keyPair.second

            // Save to secure storage
            identityStateManager.saveStaticKey(staticIdentityPrivateKey, staticIdentityPublicKey)
        }

        // Load or create Ed25519 signing key (persistent across sessions)
        val loadedSigningKeyPair = identityStateManager.loadSigningKey()
        if (loadedSigningKeyPair != null) {
            signingPrivateKey = loadedSigningKeyPair.first
            signingPublicKey = loadedSigningKeyPair.second
        } else {
            // Generate new Ed25519 signing key pair
            val signingKeyPair = generateEd25519KeyPair()
            signingPrivateKey = signingKeyPair.first
            signingPublicKey = signingKeyPair.second

            // Save to secure storage
            identityStateManager.saveSigningKey(signingPrivateKey, signingPublicKey)
        }
    }

    // MARK: - Public Interface

    /**
     * Get our static public key data for sharing (32 bytes)
     */
    fun getStaticPublicKeyData(): ByteArray {
        return staticIdentityPublicKey.clone()
    }

    /**
     * Get our signing public key data for sharing (32 bytes)
     */
    fun getSigningPublicKeyData(): ByteArray {
        return signingPublicKey.clone()
    }

    /**
     * Get our identity fingerprint (SHA-256 hash of static public key)
     */
    fun getIdentityFingerprint(): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(staticIdentityPublicKey)
        return hash.joinToString("") { "%02x".format(it) }
    }

    /**
     * Get peer's public key data (if we have a session)
     */
    fun getPeerPublicKeyData(peerID: String): ByteArray? {
        return sessionManager.getRemoteStaticKey(peerID)
    }

    fun getAuthenticatedSession(peerID: String): AuthenticatedNoiseSession? =
        sessionManager.getAuthenticatedSession(peerID)

    fun withAuthenticatedSession(
        peerID: String,
        expectedSession: AuthenticatedNoiseSession,
        action: () -> Boolean
    ): Boolean = sessionManager.withAuthenticatedSession(peerID, expectedSession, action)

    /**
     * Clear persistent identity (for panic mode)
     */
    fun clearPersistentIdentity() {
        Log.w(TAG, "Panic: clearing persistent identity and rotating in-memory keys")

        // 1. Clear storage
        identityStateManager.clearIdentityData()

        // 2. Clear all sessions immediately
        if (::sessionManager.isInitialized) {
            sessionManager.shutdown()
        }

        // 3. Regenerate keys immediately (in-memory rotation)
        loadOrGenerateKeys()

        // 4. Re-initialize SessionManager with new keys
        initializeSessionManager()

    }

    // MARK: - Handshake Management

    /**
     * Initiate a Noise handshake with a peer
     * Returns the first handshake message to send
     */
    fun initiateHandshake(peerID: String, replaceEstablished: Boolean = false): ByteArray? {
        return try {
            sessionManager.initiateHandshake(peerID, replaceEstablished)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initiate handshake with $peerID: ${e.message}")
            null
        }
    }

    /**
     * Process an incoming handshake message
     * Returns response message if needed, null if handshake complete or failed
     */
    fun processHandshakeMessage(data: ByteArray, peerID: String): ByteArray? {
        return try {
            processHandshakeMessageWithResult(data, peerID).response
        } catch (e: Exception) {
            Log.e(TAG, "Failed to process handshake from $peerID: ${e.message}")
            null
        }
    }

    /**
     * Typed handshake result for security-sensitive callers that must distinguish a null response
     * from a newly authenticated session or a rejected handshake. Identity mismatch exceptions are
     * intentionally propagated to the caller.
     */
    @Throws(Exception::class)
    fun processHandshakeMessageWithResult(
        data: ByteArray,
        peerID: String
    ): NoiseHandshakeProcessingResult {
        return sessionManager.processHandshakeMessageWithResult(peerID, data)
    }

    /**
     * Check if we have an established session with a peer
     */
    fun hasEstablishedSession(peerID: String): Boolean {
        return sessionManager.hasEstablishedSession(peerID)
    }

    /**
     * Get session state for a peer (for UI state display)
     */
    fun getSessionState(peerID: String): NoiseSession.NoiseSessionState {
        return sessionManager.getSessionState(peerID)
    }

    // MARK: - Encryption/Decryption

    /**
     * Encrypt data for a specific peer using established Noise session
     */
    fun encrypt(data: ByteArray, peerID: String): ByteArray? {
        if (!hasEstablishedSession(peerID)) {
            Log.w(TAG, "No established session with $peerID, handshake required. TODO: IMPLEMENT HANDSHAKE INIT")
            onHandshakeRequired?.invoke(peerID)
            return null
        }

        return try {
            sessionManager.encrypt(data, peerID)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encrypt for $peerID: ${e.message}")
            null
        }
    }

    @Throws(Exception::class)
    fun encryptForSession(
        data: ByteArray,
        peerID: String,
        expectedSession: AuthenticatedNoiseSession
    ): ByteArray = sessionManager.encryptForSession(data, peerID, expectedSession)

    /**
     * Decrypt data from a specific peer using established Noise session
     */
    fun decrypt(encryptedData: ByteArray, peerID: String): ByteArray? {
        if (!hasEstablishedSession(peerID)) {
            Log.w(TAG, "No established session with $peerID")
            return null
        }

        return try {
            sessionManager.decrypt(encryptedData, peerID)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decrypt from $peerID: ${e.message}")
            null
        }
    }

    fun decryptWithSession(encryptedData: ByteArray, peerID: String): NoiseDecryptionResult? =
        try {
            sessionManager.decryptWithSession(encryptedData, peerID)
        } catch (e: Exception) {
            Log.e(TAG, "Failed generation-bound decryption from $peerID: ${e.message}")
            null
        }

    // MARK: - Peer Management

    /**
     * Get fingerprint for a peer (returns null if peer unknown)
     */
    fun getPeerFingerprint(peerID: String): String? {
        return fingerprintManager.getFingerprintForPeer(peerID)
    }

    /**
     * Get current peer ID for a fingerprint (returns null if not currently online)
     */
    fun getPeerID(fingerprint: String): String? {
        return fingerprintManager.getPeerIDForFingerprint(fingerprint)
    }

    /**
     * Remove a peer session (called when peer disconnects)
     */
    fun removePeer(peerID: String) {
        sessionManager.removeSession(peerID)

        // Clean up fingerprint mappings via centralized manager
        fingerprintManager.removePeer(peerID)
    }

    /**
     * Update peer ID mapping (for peer ID rotation)
     * This allows favorites/blocking to persist across peer ID changes
     */
    fun updatePeerIDMapping(oldPeerID: String?, newPeerID: String, fingerprint: String) {
        // Use centralized fingerprint manager for peer ID rotation
        fingerprintManager.updatePeerIDMapping(oldPeerID, newPeerID, fingerprint)
    }

    // MARK: - Channel Encryption

    /**
     * Set password for a channel (derives encryption key)
     */
    fun setChannelPassword(password: String, channel: String) {
        channelEncryption.setChannelPassword(password, channel)
    }

    /**
     * Encrypt message for a password-protected channel
     */
    fun encryptChannelMessage(message: String, channel: String): ByteArray? {
        return try {
            channelEncryption.encryptChannelMessage(message, channel)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encrypt channel message for $channel: ${e.message}")
            null
        }
    }

    /**
     * Decrypt channel message
     */
    fun decryptChannelMessage(encryptedData: ByteArray, channel: String): String? {
        return try {
            channelEncryption.decryptChannelMessage(encryptedData, channel)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decrypt channel message for $channel: ${e.message}")
            null
        }
    }

    /**
     * Remove channel password (when leaving channel)
     */
    fun removeChannelPassword(channel: String) {
        channelEncryption.removeChannelPassword(channel)
    }

    // MARK: - Session Maintenance

    /**
     * Get sessions that need rekey based on time or message count
     */
    fun getSessionsNeedingRekey(): List<String> {
        return sessionManager.getSessionsNeedingRekey()
    }

    /**
     * Initiate rekey for a session (replaces old session with new handshake)
     */
    fun initiateRekey(peerID: String): ByteArray? {
        Log.d(TAG, "Rekeying session with $peerID")

        // Remove old session
        sessionManager.removeSession(peerID)

        // Start new handshake
        return initiateHandshake(peerID)
    }

    // MARK: - Private Helpers

    /**
     * Generate a new Curve25519 key pair using the real Noise library
     * Returns (privateKey, publicKey) as 32-byte arrays
     */
    private fun generateKeyPair(): Pair<ByteArray, ByteArray> {
        try {
            val dhState = com.bitchat.android.noise.southernstorm.protocol.Noise.createDH("25519")
            dhState.generateKeyPair()

            val privateKey = ByteArray(32)
            val publicKey = ByteArray(32)

            dhState.getPrivateKey(privateKey, 0)
            dhState.getPublicKey(publicKey, 0)

            dhState.destroy()

            return Pair(privateKey, publicKey)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to generate key pair: ${e.message}")
            throw e
        }
    }

    /**
     * Handle session establishment (called when Noise handshake completes)
     */
    private fun handleSessionEstablished(peerID: String, remoteStaticKey: ByteArray) {
        // Store fingerprint mapping via centralized manager
        // This is the ONLY place where fingerprints are stored - after successful Noise handshake
        fingerprintManager.storeFingerprintForPeer(peerID, remoteStaticKey)

        // Preserve the canonical peerID -> npub index, but only after Noise proves possession of
        // the static key. Announcement-time indexing was unsafe because a peer can copy another
        // party's public Noise key without possessing its private key.
        try {
            com.bitchat.android.favorites.FavoritesPersistenceService.shared
                .findNostrPubkey(remoteStaticKey)
                ?.let { npub ->
                    com.bitchat.android.favorites.FavoritesPersistenceService.shared
                        .updateNostrPublicKeyForPeerID(peerID, npub)
                }
        } catch (_: Exception) {
            // Favorites may not be initialized in isolated/background crypto tests.
        }

        // Calculate fingerprint for logging and callback
        val fingerprint = calculateFingerprint(remoteStaticKey)


        // Notify about authentication
        onPeerAuthenticated?.invoke(peerID, fingerprint)
    }

    /**
     * Calculate fingerprint from public key (SHA-256 hash)
     */
    private fun calculateFingerprint(publicKey: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(publicKey)
        return hash.joinToString("") { "%02x".format(it) }
    }

    // MARK: - Packet Signing/Verification

    /**
     * Sign a BitchatPacket using our Ed25519 signing key
     */
    fun signPacket(packet: com.bitchat.android.protocol.BitchatPacket): com.bitchat.android.protocol.BitchatPacket? {
        // Create canonical packet bytes for signing
        val packetData = packet.toBinaryDataForSigning() ?: return null

        // Sign with our Ed25519 signing private key
        val signature = signData(packetData) ?: return null

        // Return new packet with signature
        return packet.copy(signature = signature)
    }

    /**
     * Verify a BitchatPacket signature using the provided public key
     */
    fun verifyPacketSignature(packet: com.bitchat.android.protocol.BitchatPacket, publicKey: ByteArray): Boolean {
        val signature = packet.signature ?: return false

        // Create canonical packet bytes for verification (without signature)
        val packetData = packet.toBinaryDataForSigning() ?: return false

        // Verify signature using the provided Ed25519 public key
        return verifySignature(signature, packetData, publicKey)
    }

    /**
     * Sign data with our Ed25519 signing key
     */
    fun signData(data: ByteArray): ByteArray? {
        return try {
            // For simplicity, we'll implement this using BouncyCastle which should be available
            // In a production system, you might want to use the Android Keystore
            signWithEd25519(data, signingPrivateKey)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to sign data: ${e.message}")
            null
        }
    }

    /**
     * Verify signature with a public key
     */
    fun verifySignature(signature: ByteArray, data: ByteArray, publicKey: ByteArray): Boolean {
        return try {
            verifyWithEd25519(signature, data, publicKey)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to verify signature: ${e.message}")
            false
        }
    }

    /**
     * Generate a new Ed25519 key pair for signing using BouncyCastle
     * Returns (privateKey, publicKey) as 32-byte arrays
     */
    private fun generateEd25519KeyPair(): Pair<ByteArray, ByteArray> {
        try {
            // Use BouncyCastle for proper Ed25519 key generation
            val keyGen = org.bouncycastle.crypto.generators.Ed25519KeyPairGenerator()
            keyGen.init(org.bouncycastle.crypto.params.Ed25519KeyGenerationParameters(SecureRandom()))
            val keyPair = keyGen.generateKeyPair()

            val privateKey = (keyPair.private as org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters).encoded
            val publicKey = (keyPair.public as org.bouncycastle.crypto.params.Ed25519PublicKeyParameters).encoded

            return Pair(privateKey, publicKey)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to generate Ed25519 key pair: ${e.message}")
            throw e
        }
    }

    /**
     * Sign data with Ed25519 private key using BouncyCastle
     */
    private fun signWithEd25519(data: ByteArray, privateKey: ByteArray): ByteArray {
        try {
            val privateKeyParams = org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters(privateKey, 0)
            val signer = org.bouncycastle.crypto.signers.Ed25519Signer()
            signer.init(true, privateKeyParams)
            signer.update(data, 0, data.size)
            return signer.generateSignature()
        } catch (e: Exception) {
            Log.e(TAG, "Failed to sign data with Ed25519: ${e.message}")
            throw e
        }
    }

    /**
     * Verify Ed25519 signature using BouncyCastle
     */
    private fun verifyWithEd25519(signature: ByteArray, data: ByteArray, publicKey: ByteArray): Boolean {
        try {
            val publicKeyParams = org.bouncycastle.crypto.params.Ed25519PublicKeyParameters(publicKey, 0)
            val verifier = org.bouncycastle.crypto.signers.Ed25519Signer()
            verifier.init(false, publicKeyParams)
            verifier.update(data, 0, data.size)
            return verifier.verifySignature(signature)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to verify Ed25519 signature: ${e.message}")
            return false
        }
    }

    /**
     * Clean shutdown
     */
    fun shutdown() {
        if (::sessionManager.isInitialized) {
            sessionManager.shutdown()
        }
        channelEncryption.clear()
        // No need to clear fingerprints here - they are managed centrally
    }
}

/**
 * Noise-specific errors
 */
sealed class NoiseEncryptionError(message: String) : Exception(message) {
    object HandshakeRequired : NoiseEncryptionError("Handshake required before encryption")
    object SessionNotEstablished : NoiseEncryptionError("No established Noise session")
    object InvalidMessage : NoiseEncryptionError("Invalid message format")
    class HandshakeFailed(cause: Throwable) : NoiseEncryptionError("Handshake failed: ${cause.message}")
}

package com.bitchat.android.noise

import java.security.MessageDigest

/**
 * Canonical binding between an authenticated Noise static key and its mesh wire identity.
 *
 * Mesh peer IDs are the first eight bytes of SHA-256(staticPublicKey), encoded as 16 lowercase
 * hexadecimal characters. A self-signed announcement or completed Noise XX handshake is not
 * sufficient on its own: the claimed wire ID must also match this derivation.
 */
object NoisePeerIdentity {
    const val STATIC_PUBLIC_KEY_SIZE = 32
    const val WIRE_PEER_ID_LENGTH = 16

    private val wirePeerIDPattern = Regex("^[0-9a-f]{$WIRE_PEER_ID_LENGTH}$")

    fun derivePeerID(staticPublicKey: ByteArray): String? {
        if (staticPublicKey.size != STATIC_PUBLIC_KEY_SIZE) return null
        return MessageDigest.getInstance("SHA-256")
            .digest(staticPublicKey)
            .take(8)
            .joinToString("") { "%02x".format(it) }
    }

    fun matchesClaimedPeerID(claimedPeerID: String, staticPublicKey: ByteArray): Boolean {
        if (!wirePeerIDPattern.matches(claimedPeerID)) return false
        return derivePeerID(staticPublicKey) == claimedPeerID
    }
}

package com.bitchat.android.noise

import android.util.Log
import com.bitchat.android.noise.southernstorm.protocol.*
import java.security.SecureRandom


/**
 * Individual Noise session for a specific peer - REAL IMPLEMENTATION with noise-java
 * 100% compatible with iOS bitchat Noise Protocol
 */
class NoiseSession(
    private val peerID: String,
    private val isInitiator: Boolean,
    private val localStaticPrivateKey: ByteArray,
    private val localStaticPublicKey: ByteArray
) {

    companion object {
        private const val TAG = "NoiseSession"
        private const val NOISE_XX_PATTERN_LENGTH = 3

        // Noise Protocol Configuration (exactly matching iOS)
        private const val PROTOCOL_NAME = "Noise_XX_25519_ChaChaPoly_SHA256"

        // Rekey thresholds (same as iOS)
        private const val REKEY_TIME_LIMIT = com.bitchat.android.util.AppConstants.Noise.REKEY_TIME_LIMIT_MS // 1 hour
        private const val REKEY_MESSAGE_LIMIT = com.bitchat.android.util.AppConstants.Noise.REKEY_MESSAGE_LIMIT_SESSION // 10k messages

        // XX Pattern Message Sizes (exactly matching iOS implementation)
        private const val XX_MESSAGE_1_SIZE = 32      // -> e (ephemeral key only)
        private const val XX_MESSAGE_2_SIZE = 96      // <- e, ee, s, es (32 + 48) + 16 (MAC)
        private const val XX_MESSAGE_3_SIZE = 48      // -> s, se (encrypted static key)

        // Maximum payload size for safety
        private const val MAX_PAYLOAD_SIZE = com.bitchat.android.util.AppConstants.Noise.MAX_PAYLOAD_SIZE_BYTES

        // Constants for replay protection (matching iOS implementation)
        private const val NONCE_SIZE_BYTES = 4
        private const val REPLAY_WINDOW_SIZE = 1024
        private const val REPLAY_WINDOW_BYTES = REPLAY_WINDOW_SIZE / 8 // 128 bytes
        private const val HIGH_NONCE_WARNING_THRESHOLD = com.bitchat.android.util.AppConstants.Noise.HIGH_NONCE_WARNING_THRESHOLD

        // MARK: - Sliding Window Replay Protection

        /**
         * Check if nonce is valid for replay protection (matching iOS implementation)
         */
        private fun isValidNonce(receivedNonce: Long, highestReceivedNonce: Long, replayWindow: ByteArray): Boolean {
            if (receivedNonce + REPLAY_WINDOW_SIZE <= highestReceivedNonce) {
                return false  // Too old, outside window
            }

            if (receivedNonce > highestReceivedNonce) {
                return true  // Always accept newer nonces
            }

            val offset = (highestReceivedNonce - receivedNonce).toInt()
            val byteIndex = offset / 8
            val bitIndex = offset % 8

            return (replayWindow[byteIndex].toInt() and (1 shl bitIndex)) == 0  // Not yet seen
        }

        /**
         * Mark nonce as seen in replay window (matching iOS implementation)
         */
        private fun markNonceAsSeen(receivedNonce: Long, highestReceivedNonce: Long, replayWindow: ByteArray): Pair<Long, ByteArray> {
            var newHighestReceivedNonce = highestReceivedNonce
            val newReplayWindow = replayWindow.copyOf()

            if (receivedNonce > highestReceivedNonce) {
                val shift = (receivedNonce - highestReceivedNonce).toInt()

                if (shift >= REPLAY_WINDOW_SIZE) {
                    // Clear entire window - shift is too large
                    newReplayWindow.fill(0)
                } else {
                    // Shift window right by `shift` bits
                    for (i in (REPLAY_WINDOW_BYTES - 1) downTo 0) {
                        val sourceByteIndex = i - shift / 8
                        var newByte = 0

                        if (sourceByteIndex >= 0) {
                            newByte = (newReplayWindow[sourceByteIndex].toInt() and 0xFF) ushr (shift % 8)
                            if (sourceByteIndex > 0 && shift % 8 != 0) {
                                newByte = newByte or ((newReplayWindow[sourceByteIndex - 1].toInt() and 0xFF) shl (8 - shift % 8))
                            }
                        }

                        newReplayWindow[i] = (newByte and 0xFF).toByte()
                    }
                }

                newHighestReceivedNonce = receivedNonce
                newReplayWindow[0] = (newReplayWindow[0].toInt() or 1).toByte()  // Mark most recent bit as seen
            } else {
                val offset = (highestReceivedNonce - receivedNonce).toInt()
                val byteIndex = offset / 8
                val bitIndex = offset % 8
                newReplayWindow[byteIndex] = (newReplayWindow[byteIndex].toInt() or (1 shl bitIndex)).toByte()
            }

            return Pair(newHighestReceivedNonce, newReplayWindow)
        }

        /**
         * Extract nonce from combined payload <nonce><ciphertext> (matching iOS implementation)
         * Returns Pair of (nonce, ciphertext) or null if invalid
         */
        private fun extractNonceFromCiphertextPayload(combinedPayload: ByteArray): Pair<Long, ByteArray>? {
            if (combinedPayload.size < NONCE_SIZE_BYTES) {
                Log.w(TAG, "Combined payload too small: ${combinedPayload.size} < $NONCE_SIZE_BYTES")
                throw Exception("Combined payload too small: ${combinedPayload.size} < $NONCE_SIZE_BYTES")
            }

            try {
                // Extract 4-byte nonce (big-endian)
                var extractedNonce = 0L
                for (i in 0 until NONCE_SIZE_BYTES) {
                    extractedNonce = (extractedNonce shl 8) or (combinedPayload[i].toLong() and 0xFF)
                }
                // Extract ciphertext (remaining bytes)
                val ciphertext = combinedPayload.copyOfRange(NONCE_SIZE_BYTES, combinedPayload.size)
                return Pair(extractedNonce, ciphertext)

            } catch (e: Exception) {
                throw Exception("Failed to extract nonce from payload: ${e.message}")
            }
        }

        /**
         * Convert nonce to 4-byte array (big-endian) (matching iOS implementation)
         */
        private fun nonceToBytes(nonce: Long): ByteArray {
            val bytes = ByteArray(NONCE_SIZE_BYTES)
            var value = nonce
            for (i in (NONCE_SIZE_BYTES - 1) downTo 0) {
                bytes[i] = (value and 0xFF).toByte()
                value = value ushr 8
            }
            return bytes
        }
    }

    // Noise Protocol objects
    private var handshakeState: HandshakeState? = null
    private var sendCipher: CipherState? = null
    private var receiveCipher: CipherState? = null

    // Session state
    private var state: NoiseSessionState = NoiseSessionState.Uninitialized
    private val creationTime = System.currentTimeMillis()
    private var handshakeStartMs: Long? = null
    private var lastHandshakeActivityMs: Long? = null
    private var handshakeMessage1: ByteArray? = null

    // Session counters
    private var currentPattern = 0;
    private var messagesSent = 0L
    private var messagesReceived = 0L

    // Sliding window replay protection (used during transport encryption/decryption)
    private var highestReceivedNonce = 0L
    private var replayWindow = ByteArray(REPLAY_WINDOW_BYTES)

    // CRITICAL FIX: Enhanced thread safety for cipher operations
    // The noise-java CipherState objects are NOT thread-safe. Multiple concurrent
    // decrypt/encrypt operations can corrupt the internal nonce state.
    private val cipherLock = Any() // Dedicated lock for cipher operations

    // Remote peer information  
    private var remoteStaticPublicKey: ByteArray? = null
    private var handshakeHash: ByteArray? = null

    // MARK: - Session State

    /**
     * Session states matching iOS implementation
     */
    sealed class NoiseSessionState {
        object Uninitialized : NoiseSessionState()
        object Handshaking : NoiseSessionState()
        object Established : NoiseSessionState()
        data class Failed(val error: Throwable) : NoiseSessionState()

        override fun toString(): String = when (this) {
            is Uninitialized -> "uninitialized"
            is Handshaking -> "handshaking"
            is Established -> "established"
            is Failed -> "failed: ${error.message}"
        }
    }

    fun getState(): NoiseSessionState = state
    fun isEstablished(): Boolean = state is NoiseSessionState.Established
    fun isHandshaking(): Boolean = state is NoiseSessionState.Handshaking
    fun getCreationTime(): Long = creationTime
    fun isInitiatorRole(): Boolean = isInitiator
    fun getHandshakeStartMs(): Long? = handshakeStartMs
    fun getLastHandshakeActivityMs(): Long? = lastHandshakeActivityMs

    internal fun getHandshakeMessage1(): ByteArray? = handshakeMessage1?.clone()

    internal fun setLastHandshakeActivityForTest(timestampMs: Long) {
        lastHandshakeActivityMs = timestampMs
    }

    init {
        try {
            validateStaticKeys()
        } catch (e: Exception) {
            state = NoiseSessionState.Failed(e)
            Log.e(TAG, "Failed to initialize Noise session: ${e.message}")
        }
    }

    /**
     * Validate static keys before using them
     */
    private fun validateStaticKeys() {
        if (localStaticPrivateKey.size != 32) {
            throw IllegalArgumentException("Local static private key must be 32 bytes, got ${localStaticPrivateKey.size}")
        }
        if (localStaticPublicKey.size != 32) {
            throw IllegalArgumentException("Local static public key must be 32 bytes, got ${localStaticPublicKey.size}")
        }

        // Check for all-zero keys (invalid)
        if (localStaticPrivateKey.all { it == 0.toByte() }) {
            throw IllegalArgumentException("Local static private key cannot be all zeros")
        }
        if (localStaticPublicKey.all { it == 0.toByte() }) {
            throw IllegalArgumentException("Local static public key cannot be all zeros")
        }
    }

    /**
     * Initialize the Noise handshake - NOW USES PERSISTENT KEYS with our local fork
     * Our local fork properly supports setting pre-existing keys, enabling persistent identity
     */
    private fun initializeNoiseHandshake(role: Int) {
        try {
            handshakeState = HandshakeState(PROTOCOL_NAME, role)

            if (handshakeState?.needsLocalKeyPair() == true) {
                val localKeyPair = handshakeState?.getLocalKeyPair()
                if (localKeyPair != null) {
                    localKeyPair.setPrivateKey(localStaticPrivateKey, 0)

                    if (!localKeyPair.hasPrivateKey() || !localKeyPair.hasPublicKey()) {
                        throw IllegalStateException("Failed to set static identity keys - local fork issue")
                    }
                } else {
                    throw IllegalStateException("HandshakeState returned null for local key pair")
                }
            }
            handshakeState?.start()

        } catch (e: Exception) {
            Log.e(TAG, "Handshake init failed for $peerID: ${e.message}", e)
            throw e
        }
    }



    // MARK: - Real Handshake Implementation

    /**
     * Start handshake as INITIATOR
     * Returns e, the first handshake message for XX pattern (32 bytes)
     */
    @Synchronized
    fun startHandshake(): ByteArray {
        if (!isInitiator) {
            throw IllegalStateException("Only initiator can start handshake")
        }

        if (state != NoiseSessionState.Uninitialized) {
            throw IllegalStateException("Handshake already started")
        }

        try {
            // Initialize handshake as initiator 
            initializeNoiseHandshake(HandshakeState.INITIATOR)
            state = NoiseSessionState.Handshaking
            if (handshakeStartMs == null) {
                handshakeStartMs = System.currentTimeMillis()
            }
            lastHandshakeActivityMs = System.currentTimeMillis()

            val messageBuffer = ByteArray(XX_MESSAGE_1_SIZE)
            val handshakeStateLocal = handshakeState ?: throw IllegalStateException("Handshake state is null")
            val messageLength = handshakeStateLocal.writeMessage(messageBuffer, 0, null, 0, 0)
            currentPattern++
            val firstMessage = messageBuffer.copyOf(messageLength)
            handshakeMessage1 = firstMessage

            // Validate message size matches XX pattern expectations
            if (firstMessage.size != XX_MESSAGE_1_SIZE) {
                Log.w(TAG, "XX message 1 size ${firstMessage.size} != expected $XX_MESSAGE_1_SIZE")
            }

            return firstMessage
        } catch (e: Exception) {
            state = NoiseSessionState.Failed(e)
            Log.e(TAG, "Failed to start handshake with $peerID: ${e.message}")
            throw e
        }
    }

    /**
     * Process incoming handshake as RESPONDER
     * Returns e, ee
     */
    @Synchronized
    fun processHandshakeMessage(message: ByteArray): ByteArray? {
        try {
            // Initialize as responder if receiving first message
            if (state == NoiseSessionState.Uninitialized && !isInitiator) {
                initializeNoiseHandshake(HandshakeState.RESPONDER)
                state = NoiseSessionState.Handshaking
                if (handshakeStartMs == null) {
                    handshakeStartMs = System.currentTimeMillis()
                }
            }

            if (state != NoiseSessionState.Handshaking) {
                throw IllegalStateException("Invalid state for handshake: $state")
            }
            lastHandshakeActivityMs = System.currentTimeMillis()

            val handshakeStateLocal = handshakeState ?: throw IllegalStateException("Handshake state is null")

            // Let the Noise library validate message sizes and handle the flow
            val payloadBuffer = ByteArray(XX_MESSAGE_2_SIZE + MAX_PAYLOAD_SIZE)  // Buffer for any payload data

            // Read the incoming message - the Noise library will handle validation
            val payloadLength = handshakeStateLocal.readMessage(message, 0, message.size, payloadBuffer, 0)
            currentPattern++

            // Check what action the handshake state wants us to take next
            val action = handshakeStateLocal.getAction()

            return when (action) {
                HandshakeState.WRITE_MESSAGE -> {
                    // Noise library says we need to send a response
                    val responseBuffer = ByteArray(XX_MESSAGE_2_SIZE + MAX_PAYLOAD_SIZE) // Large buffer for any response
                    val responseLength = handshakeStateLocal.writeMessage(responseBuffer, 0, null, 0, 0)
                    currentPattern++
                    val response = responseBuffer.copyOf(responseLength)

                    completeHandshake()
                    response
                }

                HandshakeState.SPLIT -> {
                    // Handshake complete, split into transport keys
                    completeHandshake()
                    null
                }

                HandshakeState.FAILED -> {
                    throw Exception("Handshake failed - Noise library reported FAILED state")
                }

                else -> null
            }

        } catch (e: Exception) {
            state = NoiseSessionState.Failed(e)
            Log.e(TAG, "Handshake failed with $peerID: ${e.message}", e)
            throw e
        }
    }

    /**
     * Complete handshake and derive transport keys
     */
    @Synchronized
    private fun completeHandshake() {
        if (currentPattern < NOISE_XX_PATTERN_LENGTH) {
            return
        }

        try {
            val activeHandshake = handshakeState ?: throw NoiseSessionError.HandshakeFailed

            // Authenticate the remote static key's claimed mesh identity before split creates
            // transport ciphers or the session can become observable as Established.
            if (!activeHandshake.hasRemotePublicKey()) throw NoiseSessionError.HandshakeFailed
            val remoteDH = activeHandshake.getRemotePublicKey()
                ?: throw NoiseSessionError.HandshakeFailed
            val authenticatedRemoteKey = ByteArray(NoisePeerIdentity.STATIC_PUBLIC_KEY_SIZE)
            remoteDH.getPublicKey(authenticatedRemoteKey, 0)
            val derivedPeerID = NoisePeerIdentity.derivePeerID(authenticatedRemoteKey)
            if (!NoisePeerIdentity.matchesClaimedPeerID(peerID, authenticatedRemoteKey)) {
                authenticatedRemoteKey.fill(0)
                throw NoiseSessionError.PeerIdentityMismatch(peerID, derivedPeerID)
            }
            remoteStaticPublicKey = authenticatedRemoteKey

            // Only a bound remote identity may derive transport ciphers.
            val cipherPair = activeHandshake.split()
            sendCipher = cipherPair.getSender()
            receiveCipher = cipherPair.getReceiver()

            // Extract handshake hash for channel binding
            // getHandshakeHash() exposes the handshake state's backing array. Clone it before
            // destroy() zeroizes that state, or every completed session appears to have the same
            // all-zero channel-binding token.
            handshakeHash = activeHandshake.getHandshakeHash().clone()

            // Clean up handshake state
            activeHandshake.destroy()
            handshakeState = null

            messagesSent = 0
            messagesReceived = 0
            currentPattern = 0

            // Reset sliding window replay protection for new transport phase
            highestReceivedNonce = 0L
            replayWindow = ByteArray(REPLAY_WINDOW_BYTES)

            state = NoiseSessionState.Established
            Log.i(TAG, "Handshake established with $peerID (${if (isInitiator) "initiator" else "responder"})")
        } catch (e: Exception) {
            state = NoiseSessionState.Failed(e)
            Log.e(TAG, "Failed to complete handshake: ${e.message}")
            throw e
        }
    }

    // MARK: - Transport Encryption

    /**
     * Encrypt data in transport mode using real ChaCha20-Poly1305 with nonce synchronization
     * Returns: <nonce><ciphertext> where nonce is 4 bytes (matching iOS implementation)
     */
    fun encrypt(data: ByteArray): ByteArray {
        // Pre-check state without holding cipher lock
        if (!isEstablished()) {
            throw IllegalStateException("Session not established")
        }

        // Critical section: Use dedicated cipher lock to protect CipherState nonce corruption
        synchronized(cipherLock) {
            // Double-check state inside lock
            if (!isEstablished()) {
                throw IllegalStateException("Session not established during cipher operation")
            }

            if (sendCipher == null) {
                throw IllegalStateException("Send cipher not available")
            }

            // Check if nonce exceeds 4-byte limit (UInt32 max value)
            if (messagesSent > UInt.MAX_VALUE.toLong() - 1) {
                throw SessionError.NonceExceeded("Nonce value $messagesSent exceeds 4-byte limit")
            }

            try {
                // assert that sendCipher!!.macLength is 16:
                if (sendCipher!!.macLength != 16) {
                    throw IllegalStateException("Send cipher MAC length is not 16")
                }

                // Encrypt the data first
                val ciphertext = ByteArray(data.size + sendCipher!!.macLength) // Add space for MAC tag
                sendCipher!!.setNonce(messagesSent)
                val ciphertextLength = sendCipher!!.encryptWithAd(null, data, 0, ciphertext, 0, data.size)

                // Get the current nonce before incrementing
                val currentNonce = messagesSent
                messagesSent++

                // Create combined payload: <nonce><ciphertext> (4 bytes for nonce)
                val nonceBytes = nonceToBytes(currentNonce)
                val combinedPayload = ByteArray(NONCE_SIZE_BYTES + ciphertextLength)

                // Copy nonce (first 4 bytes)
                System.arraycopy(nonceBytes, 0, combinedPayload, 0, NONCE_SIZE_BYTES)

                // Copy ciphertext (remaining bytes)
                System.arraycopy(ciphertext, 0, combinedPayload, NONCE_SIZE_BYTES, ciphertextLength)

                // Log high nonce values that might indicate issues
                if (currentNonce > HIGH_NONCE_WARNING_THRESHOLD) {
                    Log.w(TAG, "High send nonce $currentNonce for $peerID - rekey recommended")
                }

                return combinedPayload

            } catch (e: Exception) {
                Log.e(TAG, "Encryption failed for $peerID: ${e.message}")
                throw SessionError.EncryptionFailed
            }
        }
    }

    /**
     * Decrypt data in transport mode using real ChaCha20-Poly1305 with sliding window replay protection
     * Expects: <nonce><ciphertext> where nonce is 4 bytes (matching iOS implementation)
     */
    fun decrypt(combinedPayload: ByteArray): ByteArray {
        // Pre-check state without holding cipher lock
        if (!isEstablished()) {
            throw IllegalStateException("Session not established")
        }

        // Critical section: Use dedicated cipher lock to protect CipherState nonce corruption
        synchronized(cipherLock) {
            // Double-check state inside lock
            if (!isEstablished()) {
                throw IllegalStateException("Session not established during cipher operation")
            }

            if (receiveCipher == null) {
                throw IllegalStateException("Receive cipher not available")
            }

            try {
                // Extract nonce and ciphertext from combined payload
                val nonceAndCiphertext = extractNonceFromCiphertextPayload(combinedPayload)
                if (nonceAndCiphertext == null) {
                    Log.e(TAG, "Failed to extract nonce from payload for $peerID")
                    throw SessionError.DecryptionFailed
                }

                val (extractedNonce, ciphertext) = nonceAndCiphertext

                if (ciphertext.size < receiveCipher!!.macLength) {
                    Log.w(TAG, "Ciphertext too short: ${ciphertext.size} < ${receiveCipher!!.macLength}")
                    throw SessionError.DecryptionFailed
                }

                // Validate nonce with sliding window replay protection
                if (!isValidNonce(extractedNonce, highestReceivedNonce, replayWindow)) {
                    Log.w(TAG, "Replay attack detected: nonce $extractedNonce rejected for $peerID")
                    throw SessionError.DecryptionFailed
                }

                // Use the extracted nonce for decryption
                val plaintext = ByteArray(ciphertext.size) 

                 receiveCipher!!.setNonce(extractedNonce)
                val plaintextLength = receiveCipher!!.decryptWithAd(null, ciphertext, 0, plaintext, 0, ciphertext.size)

                // Mark nonce as seen after successful decryption
                val (newHighestReceivedNonce, newReplayWindow) = markNonceAsSeen(extractedNonce, highestReceivedNonce, replayWindow)
                highestReceivedNonce = newHighestReceivedNonce
                replayWindow = newReplayWindow

                // Log high nonce values that might indicate issues
                if (extractedNonce > HIGH_NONCE_WARNING_THRESHOLD) {
                    Log.w(TAG, "High receive nonce $extractedNonce for $peerID - rekey recommended")
                }

                return plaintext.copyOf(plaintextLength)

            } catch (e: Exception) {
                Log.w(TAG, "Decrypt failed for $peerID: ${e.message} (state=$state, highestNonce=$highestReceivedNonce)")
                throw SessionError.DecryptionFailed
            }
        }
    }

    // MARK: - Session Information

    /**
     * Get remote static public key (available after handshake completion)
     */
    fun getRemoteStaticPublicKey(): ByteArray? {
        return remoteStaticPublicKey?.clone()
    }

    /**
     * Get handshake hash for channel binding
     */
    fun getHandshakeHash(): ByteArray? {
        return handshakeHash?.clone()
    }

    /**
     * Check if session needs rekeying
     */
    fun needsRekey(): Boolean {
        if (!isEstablished()) return false

        val timeLimit = System.currentTimeMillis() - creationTime > REKEY_TIME_LIMIT
        val messageLimit = (messagesSent + messagesReceived) > REKEY_MESSAGE_LIMIT

        return timeLimit || messageLimit
    }

    /**
     * Get session statistics
     */
    fun getSessionStats(): String = buildString {
        appendLine("NoiseSession with $peerID:")
        appendLine("  State: $state")
        appendLine("  Role: ${if (isInitiator) "initiator" else "responder"}")
        appendLine("  Messages sent: $messagesSent")
        appendLine("  Messages received: $messagesReceived")
        appendLine("  Session age: ${(System.currentTimeMillis() - creationTime) / 1000}s")
        appendLine("  Needs rekey: ${needsRekey()}")
        appendLine("  Has remote key: ${remoteStaticPublicKey != null}")
        appendLine("  Has send cipher: ${sendCipher != null}")
        appendLine("  Has receive cipher: ${receiveCipher != null}")
    }

    /**
     * Reset session state
     */
    @Synchronized
    fun reset() {
        try {
            // Destroy existing state
            destroy()

            // Reset to uninitialized state (handshake will be initialized when needed)
            state = NoiseSessionState.Uninitialized
            messagesSent = 0
            messagesReceived = 0

            // Reset sliding window replay protection
            highestReceivedNonce = 0L
            replayWindow = ByteArray(REPLAY_WINDOW_BYTES)

            remoteStaticPublicKey = null
            handshakeHash = null
        } catch (e: Exception) {
            state = NoiseSessionState.Failed(e)
            Log.e(TAG, "Failed to reset session: ${e.message}")
        }
    }

    /**
     * Clean up session resources securely
     */
    @Synchronized
    fun destroy() {
        try {
            // Destroy Noise objects
            sendCipher?.destroy()
            receiveCipher?.destroy()
            handshakeState?.destroy()

            // Clear sensitive data
            remoteStaticPublicKey?.fill(0)
            handshakeHash?.fill(0)

            // Null out references
            sendCipher = null
            receiveCipher = null
            handshakeState = null
            remoteStaticPublicKey = null
            handshakeHash = null

            if (state !is NoiseSessionState.Failed) {
                state = NoiseSessionState.Failed(Exception("Session destroyed"))
            }

        } catch (e: Exception) {
            Log.w(TAG, "Error during session cleanup: ${e.message}")
        }
    }
}

/**
 * Session-specific errors
 */
sealed class SessionError(message: String, cause: Throwable? = null) : Exception(message, cause) {
    object InvalidState : SessionError("Session in invalid state")
    object NotEstablished : SessionError("Session not established")
    object HandshakeFailed : SessionError("Handshake failed")
    object EncryptionFailed : SessionError("Encryption failed")
    object DecryptionFailed : SessionError("Decryption failed")
    class HandshakeInitializationFailed(message: String) : SessionError("Handshake initialization failed: $message")
    class NonceExceeded(message: String) : SessionError(message)
}

package com.bitchat.android.noise

import android.util.Log
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

data class NoiseHandshakeProcessingResult(
    val response: ByteArray?,
    val establishedNow: Boolean,
    /** The bound remote static key only when this exact call completed authentication. */
    val authenticatedRemoteStaticKey: ByteArray? = null,
    /** Handshake hash identifying that exact authenticated Noise generation. */
    val authenticatedSessionToken: ByteArray? = null
)

/** Atomic snapshot of the live authenticated Noise generation. */
class AuthenticatedNoiseSession(
    remoteStaticKey: ByteArray,
    sessionToken: ByteArray
) {
    private val remoteStaticKeyBytes = remoteStaticKey.copyOf()
    private val sessionTokenBytes = sessionToken.copyOf()

    val remoteStaticKey: ByteArray get() = remoteStaticKeyBytes.copyOf()
    val sessionToken: ByteArray get() = sessionTokenBytes.copyOf()

    override fun equals(other: Any?): Boolean =
        this === other ||
            (other is AuthenticatedNoiseSession &&
                remoteStaticKeyBytes.contentEquals(other.remoteStaticKeyBytes) &&
                sessionTokenBytes.contentEquals(other.sessionTokenBytes))

    override fun hashCode(): Int =
        31 * remoteStaticKeyBytes.contentHashCode() + sessionTokenBytes.contentHashCode()
}

/** Plaintext and generation binding captured atomically from the session that decrypted it. */
data class NoiseDecryptionResult(
    val plaintext: ByteArray,
    val authenticatedSession: AuthenticatedNoiseSession
)

/**
 * SIMPLIFIED Noise session manager - focuses on core functionality only
 */
class NoiseSessionManager(
    private val localStaticPrivateKey: ByteArray,
    private val localStaticPublicKey: ByteArray,
    private val localPeerID: String
) {

    companion object {
        private const val TAG = "NoiseSessionManager"
        private const val HANDSHAKE_TIMEOUT_MS = 10_000L
        private const val HANDSHAKE_SWEEP_INTERVAL_MS = 2_000L
        private const val HANDSHAKE_MESSAGE_1_SIZE = 32
        private const val SESSION_TOKEN_SIZE = 32
    }

    private val sessions = ConcurrentHashMap<String, NoiseSession>()
    // An inbound replacement handshake must prove its authenticated static-key binding before it
    // can evict a working transport session. Keep responder candidates outside the active map.
    private val responderCandidates = ConcurrentHashMap<String, NoiseSession>()

    private val sweepScheduler = Executors.newSingleThreadScheduledExecutor { runnable ->
        Thread(runnable, "NoiseHandshakeSweeper").apply { isDaemon = true }
    }

    init {
        sweepScheduler.scheduleWithFixedDelay({
            try {
                cleanupStaleHandshakes(System.currentTimeMillis())
            } catch (e: Exception) {
                Log.w(TAG, "Handshake sweep failed: ${e.message}")
            }
        }, HANDSHAKE_SWEEP_INTERVAL_MS, HANDSHAKE_SWEEP_INTERVAL_MS, TimeUnit.MILLISECONDS)
    }

    // Callbacks
    var onSessionEstablished: ((String, ByteArray) -> Unit)? = null
    var onSessionFailed: ((String, Throwable) -> Unit)? = null

    // MARK: - Simple Session Management

    /**
     * Add new session for a peer
     */
    @Synchronized
    fun addSession(peerID: String, session: NoiseSession) {
        val previous = sessions.put(peerID, session)
        if (previous != null && previous !== session) previous.destroy()
    }

    /**
     * Get existing session for a peer
     */
    fun getSession(peerID: String): NoiseSession? {
        val session = sessions[peerID]
        return session
    }

    /**
     * Remove session for a peer
     */
    @Synchronized
    fun removeSession(peerID: String) {
        sessions.remove(peerID)?.destroy()
        responderCandidates.remove(peerID)?.destroy()
    }

    /**
     * SIMPLIFIED: Initiate handshake - no tie breaker, just start
     */
    @Synchronized
    fun initiateHandshake(peerID: String, replaceEstablished: Boolean = false): ByteArray? {
        val now = System.currentTimeMillis()
        val existing = getSession(peerID)
        if (existing != null) {
            when {
                existing.isEstablished() -> {
                    if (!replaceEstablished) {
                        return null
                    }
                    val candidate = createSession(peerID, isInitiator = true)
                    responderCandidates.remove(peerID)?.destroy()
                    responderCandidates[peerID] = candidate
                    return try {
                        candidate.startHandshake()
                    } catch (e: Exception) {
                        responderCandidates.remove(peerID, candidate)
                        candidate.destroy()
                        throw e
                    }
                }
                existing.isHandshaking() -> {
                    if (!isHandshakeStale(existing, now)) {
                        return null
                    }
                    Log.d(TAG, "Restarting stale handshake with $peerID")
                    removeSession(peerID)
                }
                else -> {
                    removeSession(peerID)
                }
            }
        }

        // Create new session as initiator
        val session = NoiseSession(
            peerID = peerID,
            isInitiator = true,
            localStaticPrivateKey = localStaticPrivateKey,
            localStaticPublicKey = localStaticPublicKey
        )
        addSession(peerID, session)

        try {
            return session.startHandshake()
        } catch (e: Exception) {
            if (sessions.remove(peerID, session)) session.destroy()
            throw e
        }
    }

    /**
     * Handle incoming handshake message
     */
    fun processHandshakeMessage(peerID: String, message: ByteArray): ByteArray? {
        return processHandshakeMessageWithResult(peerID, message).response
    }

    @Synchronized
    fun processHandshakeMessageWithResult(
        peerID: String,
        message: ByteArray
    ): NoiseHandshakeProcessingResult {
        var activeSession: NoiseSession? = null
        var isReplacementCandidate = false
        var establishedRemoteKey: ByteArray? = null
        var establishedSessionToken: ByteArray? = null
        var response: ByteArray? = null

        try {
            val existingCandidate = responderCandidates[peerID]
            if (existingCandidate != null) {
                activeSession = if (message.size == HANDSHAKE_MESSAGE_1_SIZE) {
                    if (existingCandidate.isInitiatorRole()) {
                        val shouldYield = localPeerID > peerID
                        if (!shouldYield) {
                            return NoiseHandshakeProcessingResult(
                                response = null,
                                establishedNow = false
                            )
                        }
                        Log.d(TAG, "Replacement collision with $peerID; yielding to responder")
                    }
                    responderCandidates.remove(peerID, existingCandidate)
                    existingCandidate.destroy()
                    createSession(peerID, isInitiator = false).also {
                        responderCandidates[peerID] = it
                    }
                } else {
                    existingCandidate
                }
                isReplacementCandidate = true
            } else {
                var session = getSession(peerID)

                // Collision handling: both sides initiated and we received message 1.
                if (session != null &&
                    session.isHandshaking() &&
                    session.isInitiatorRole() &&
                    message.size == HANDSHAKE_MESSAGE_1_SIZE
                ) {
                    val shouldYield = localPeerID > peerID
                    if (shouldYield) {
                        Log.d(TAG, "Handshake collision with $peerID; yielding to responder")
                        if (sessions.remove(peerID, session)) session.destroy()
                        session = null
                    } else {
                        return NoiseHandshakeProcessingResult(response = null, establishedNow = false)
                    }
                }

                activeSession = when {
                    session == null -> {
                        createSession(peerID, isInitiator = false).also { sessions[peerID] = it }
                    }
                    session.isEstablished() -> {
                        isReplacementCandidate = true
                        createSession(peerID, isInitiator = false).also {
                            responderCandidates[peerID] = it
                        }
                    }
                    session.isHandshaking() &&
                        !session.isInitiatorRole() &&
                        message.size == HANDSHAKE_MESSAGE_1_SIZE -> {
                        // A restarted responder handshake can replace an incomplete session because
                        // there is no working transport state to preserve.
                        if (sessions.remove(peerID, session)) session.destroy()
                        createSession(peerID, isInitiator = false).also { sessions[peerID] = it }
                    }
                    else -> session
                }
            }

            val session = activeSession ?: throw NoiseSessionError.InvalidState

            response = session.processHandshakeMessage(message)

            if (session.isEstablished()) {
                val remoteStaticKey = session.getRemoteStaticPublicKey()
                    ?: throw NoiseSessionError.HandshakeFailed
                val derivedPeerID = NoisePeerIdentity.derivePeerID(remoteStaticKey)
                if (!NoisePeerIdentity.matchesClaimedPeerID(peerID, remoteStaticKey)) {
                    throw NoiseSessionError.PeerIdentityMismatch(peerID, derivedPeerID)
                }

                val sessionToken = session.getHandshakeHash()
                    ?.takeIf { it.size == SESSION_TOKEN_SIZE && it.any { byte -> byte != 0.toByte() } }
                    ?: throw NoiseSessionError.HandshakeFailed

                if (isReplacementCandidate) {
                    responderCandidates.remove(peerID, session)
                    val previous = sessions.put(peerID, session)
                    if (previous != null && previous !== session) previous.destroy()
                }

                establishedRemoteKey = remoteStaticKey
                establishedSessionToken = sessionToken
            }
        } catch (e: Exception) {
            val session = activeSession
            if (session != null) {
                if (isReplacementCandidate) {
                    responderCandidates.remove(peerID, session)
                } else {
                    sessions.remove(peerID, session)
                }
                session.destroy()
            }
            Log.e(TAG, "Handshake failed with $peerID: ${e.message}")
            runCatching { onSessionFailed?.invoke(peerID, e) }
            throw e
        }

        establishedRemoteKey?.let { onSessionEstablished?.invoke(peerID, it) }
        return NoiseHandshakeProcessingResult(
            response = response,
            establishedNow = establishedRemoteKey != null,
            authenticatedRemoteStaticKey = establishedRemoteKey?.clone(),
            authenticatedSessionToken = establishedSessionToken?.clone()
        )
    }

    private fun createSession(peerID: String, isInitiator: Boolean): NoiseSession = NoiseSession(
        peerID = peerID,
        isInitiator = isInitiator,
        localStaticPrivateKey = localStaticPrivateKey,
        localStaticPublicKey = localStaticPublicKey
    )

    private fun isHandshakeStale(session: NoiseSession, nowMs: Long): Boolean {
        val lastActivity = session.getLastHandshakeActivityMs() ?: session.getHandshakeStartMs()
        if (lastActivity == null) return false
        return (nowMs - lastActivity) > HANDSHAKE_TIMEOUT_MS
    }

    /**
     * Actively expire handshakes that stopped progressing (lost response, abandoned
     * responder candidates). Established sessions are never touched here.
     */
    @Synchronized
    fun cleanupStaleHandshakes(nowMs: Long) {
        sessions.entries.toList().forEach { (peerID, session) ->
            if (session.isHandshaking() && isHandshakeStale(session, nowMs)) {
                Log.d(TAG, "Expiring stale handshake with $peerID")
                if (sessions.remove(peerID, session)) {
                    session.destroy()
                    runCatching { onSessionFailed?.invoke(peerID, NoiseSessionError.HandshakeTimeout) }
                }
            }
        }
        responderCandidates.entries.toList().forEach { (peerID, session) ->
            if (session.isHandshaking() && isHandshakeStale(session, nowMs)) {
                Log.d(TAG, "Expiring stale responder candidate for $peerID")
                if (responderCandidates.remove(peerID, session)) {
                    session.destroy()
                }
            }
        }
    }

    /**
     * SIMPLIFIED: Encrypt data
     */
    @Synchronized
    fun encrypt(data: ByteArray, peerID: String): ByteArray {
        val session = getSession(peerID) ?: throw IllegalStateException("No session found for $peerID")
        if (!session.isEstablished()) {
            throw IllegalStateException("Session not established with $peerID")
        }
        return session.encrypt(data)
    }

    /** Encrypt only if the exact generation that authorized the operation is still active. */
    @Synchronized
    fun encryptForSession(
        data: ByteArray,
        peerID: String,
        expectedSession: AuthenticatedNoiseSession
    ): ByteArray {
        val session = getSession(peerID) ?: throw NoiseSessionError.SessionNotFound
        if (!session.isEstablished()) throw NoiseSessionError.SessionNotEstablished
        val current = authenticatedSession(session) ?: throw NoiseSessionError.SessionNotEstablished
        if (current != expectedSession) throw NoiseSessionError.SessionGenerationChanged
        return session.encrypt(data)
    }

    /**
     * SIMPLIFIED: Decrypt data
     */
    fun decrypt(encryptedData: ByteArray, peerID: String): ByteArray =
        decryptWithSession(encryptedData, peerID).plaintext

    @Synchronized
    fun decryptWithSession(encryptedData: ByteArray, peerID: String): NoiseDecryptionResult {
        val session = getSession(peerID)
        if (session == null) {
            Log.e(TAG, "No session found for $peerID when trying to decrypt")
            throw IllegalStateException("No session found for $peerID")
        }
        if (!session.isEstablished()) {
            Log.e(TAG, "Session not established with $peerID when trying to decrypt")
            throw IllegalStateException("Session not established with $peerID")
        }
        val plaintext = session.decrypt(encryptedData)
        val authenticatedSession = authenticatedSession(session)
            ?: throw IllegalStateException("Established session for $peerID has no channel binding")
        return NoiseDecryptionResult(plaintext, authenticatedSession)
    }

    /**
     * Check if session is established with peer
     */
    fun hasEstablishedSession(peerID: String): Boolean {
        return getSession(peerID)?.isEstablished() ?: false
    }

    /**
     * Get session state for a peer (for UI state display)
     */
    fun getSessionState(peerID: String): NoiseSession.NoiseSessionState {
        return getSession(peerID)?.getState() ?: NoiseSession.NoiseSessionState.Uninitialized
    }

    /**
     * Get remote static public key for a peer (if session established)
     */
    fun getRemoteStaticKey(peerID: String): ByteArray? =
        getAuthenticatedSession(peerID)?.remoteStaticKey

    @Synchronized
    fun getAuthenticatedSession(peerID: String): AuthenticatedNoiseSession? {
        val session = getSession(peerID) ?: return null
        if (!session.isEstablished()) return null
        return authenticatedSession(session)
    }

    /** Execute a state transition while preventing replacement/removal of the expected session. */
    @Synchronized
    fun withAuthenticatedSession(
        peerID: String,
        expectedSession: AuthenticatedNoiseSession,
        action: () -> Boolean
    ): Boolean {
        val session = getSession(peerID) ?: return false
        if (!session.isEstablished()) return false
        if (authenticatedSession(session) != expectedSession) return false
        return action()
    }

    /**
     * Get handshake hash for channel binding (if session established)
     */
    fun getHandshakeHash(peerID: String): ByteArray? {
        return getAuthenticatedSession(peerID)?.sessionToken
    }

    private fun authenticatedSession(session: NoiseSession): AuthenticatedNoiseSession? {
        val remoteStaticKey = session.getRemoteStaticPublicKey()?.takeIf { it.size == 32 } ?: return null
        val sessionToken = session.getHandshakeHash()?.takeIf {
            it.size == SESSION_TOKEN_SIZE && it.any { byte -> byte != 0.toByte() }
        } ?: return null
        return AuthenticatedNoiseSession(remoteStaticKey, sessionToken)
    }

    /**
     * Get sessions that need rekeying based on time or message count
     */
    fun getSessionsNeedingRekey(): List<String> {
        return sessions.entries
            .filter { (_, session) -> 
                session.isEstablished() && session.needsRekey()
            }
            .map { it.key }
    }

    /**
     * Get debug information
     */
    fun getDebugInfo(): String = buildString {
        appendLine("=== Noise Session Manager Debug ===")
        appendLine("Active sessions: ${sessions.size}")
        appendLine("Responder candidates: ${responderCandidates.size}")
        appendLine("")

        if (sessions.isNotEmpty()) {
            appendLine("Sessions:")
            sessions.forEach { (peerID, session) ->
                appendLine("  $peerID: ${session.getState()}")
            }
        }
    }

    /**
     * Shutdown manager and clean up all sessions
     */
    @Synchronized
    fun shutdown() {
        sweepScheduler.shutdownNow()
        sessions.values.forEach { it.destroy() }
        responderCandidates.values.forEach { it.destroy() }
        sessions.clear()
        responderCandidates.clear()
        Log.d(TAG, "Noise session manager shut down")
    }
}

/**
 * Session-related errors
 */
sealed class NoiseSessionError(message: String, cause: Throwable? = null) : Exception(message, cause) {
    object SessionNotFound : NoiseSessionError("Session not found")
    object SessionNotEstablished : NoiseSessionError("Session not established")
    object InvalidState : NoiseSessionError("Session in invalid state")
    object HandshakeFailed : NoiseSessionError("Handshake failed")
    object HandshakeTimeout : NoiseSessionError("Handshake timed out")
    object AlreadyEstablished : NoiseSessionError("Session already established")
    object SessionGenerationChanged : NoiseSessionError("Noise session generation changed")
    class PeerIdentityMismatch(claimedPeerID: String, derivedPeerID: String?) : NoiseSessionError(
        "Authenticated Noise key derives to ${derivedPeerID ?: "invalid"}, not claimed peer $claimedPeerID"
    )
}

