         * map byte array block to cipher state
         * and add initial round key:
         */
	    s0 = GETU32(ct, ctoffset     ) ^ rk[0];
	    s1 = GETU32(ct, ctoffset +  4) ^ rk[1];
	    s2 = GETU32(ct, ctoffset +  8) ^ rk[2];
	    s3 = GETU32(ct, ctoffset + 12) ^ rk[3];

