	     * Nr - 1 full rounds:
	     */
	    r = Nr >> 1;
	    rkoffset = 0;
	    for (;;) {
	        t0 =
	            Td0[(s0 >> 24) & 0xff] ^
	            Td1[(s3 >> 16) & 0xff] ^
	            Td2[(s2 >>  8) & 0xff] ^
	            Td3[(s1      ) & 0xff] ^
	            rk[rkoffset + 4];
