	        s0 =
	                Td0[(t0 >> 24) & 0xff] ^
	                Td1[(t3 >> 16) & 0xff] ^
	                Td2[(t2 >>  8) & 0xff] ^
	                Td3[(t1      ) & 0xff] ^
	                rk[rkoffset];
	            s1 =
	                Td0[(t1 >> 24) & 0xff] ^
	                Td1[(t0 >> 16) & 0xff] ^
	                Td2[(t3 >>  8) & 0xff] ^
	                Td3[(t2      ) & 0xff] ^
