                rk[rkoffset + 2];
        PUTU32(pt, ptoffset +  8, s2);
        s3 =
                (Td4[(t3 >> 24) & 0xff] & 0xff000000) ^
                (Td4[(t2 >> 16) & 0xff] & 0x00ff0000) ^
                (Td4[(t1 >>  8) & 0xff] & 0x0000ff00) ^
