/**
 * Fallback implementation of SHA256.
 */
public class SHA256MessageDigest extends MessageDigest implements Destroyable {

	private int[] h;
	private byte[] block;
	private int[] w;
	private long length;
	private int posn;

	/**
	 * Constructs a new SHA256 message digest object.
	 */
	public SHA256MessageDigest() {
		super("SHA-256");
		h = new int [8];
		block = new byte [64];
		w = new int [64];
		engineReset();
	}

	@Override
	public void destroy() {
		Arrays.fill(h, (int)0);
		Arrays.fill(block, (byte)0);
		Arrays.fill(w, (int)0);
	}

	private static void writeBE32(byte[] buf, int offset, int value)
	{
		buf[offset] = (byte)(value >> 24);
		buf[offset + 1] = (byte)(value >> 16);
		buf[offset + 2] = (byte)(value >> 8);
		buf[offset + 3] = (byte)value;
	}

	@Override
	protected byte[] engineDigest() {
		byte[] digest = new byte [32];
		try {
			engineDigest(digest, 0, 32);
		} catch (DigestException e) {
			// Shouldn't happen, but just in case.
			Arrays.fill(digest, (byte)0);
		}
		return digest;
	}

	@Override
	protected int engineDigest(byte[] buf, int offset, int len) throws DigestException
	{
		if (len < 32)
			throw new DigestException("Invalid digest length for SHA256");
		if (posn <= (64 - 9)) {
			block[posn] = (byte)0x80;
			Arrays.fill(block, posn + 1, 64 - 8, (byte)0);
		} else {
			block[posn] = (byte)0x80;
			Arrays.fill(block, posn + 1, 64, (byte)0);
			transform(block, 0);
			Arrays.fill(block, 0, 64 - 8, (byte)0);
		}
		writeBE32(block, 64 - 8, (int)(length >> 32));
		writeBE32(block, 64 - 4, (int)length);
		transform(block, 0);
		posn = 0;
		for (int index = 0; index < 8; ++index)
			writeBE32(buf, offset + index * 4, h[index]);
		return 32;
	}

	@Override
	protected int engineGetDigestLength() {
		return 32;
	}

	@Override
	protected void engineReset() {
		h[0] = 0x6A09E667;
		h[1] = 0xBB67AE85;
		h[2] = 0x3C6EF372;
		h[3] = 0xA54FF53A;
		h[4] = 0x510E527F;
		h[5] = 0x9B05688C;
		h[6] = 0x1F83D9AB;
		h[7] = 0x5BE0CD19;
		length = 0;
		posn = 0;
	}

	@Override
	protected void engineUpdate(byte input) {
		block[posn++] = input;
		length += 8;
		if (posn >= 64) {
			transform(block, 0);
			posn = 0;
		}
	}

	@Override
	protected void engineUpdate(byte[] input, int offset, int len) {
		while (len > 0) {
			if (posn == 0 && len >= 64) {
				transform(input, offset);
				offset += 64;
				len -= 64;
				length += 64 * 8;
			} else {
				int temp = 64 - posn;
				if (temp > len)
					temp = len;
				System.arraycopy(input, offset, block, posn, temp);
				posn += temp;
				length += temp * 8;
				if (posn >= 64) {
					transform(block, 0);
					posn = 0;
				}
				offset += temp;
				len -= temp;
			}
		}
	}

