package com.bitchat.android.nostr

import android.app.Application
import android.util.Log
import com.bitchat.android.model.BitchatMessage
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.launch
import java.util.Date

/**
 * GeohashMessageHandler
 * - Processes kind=20000 Nostr events for geohash channels
 * - Updates repository for participants + nicknames
 * - Emits messages to MessageManager
 */
class GeohashMessageHandler(
    private val application: Application,
    private val repo: GeohashRepository,
    private val scope: CoroutineScope,
    private val dataManager: com.bitchat.android.ui.DataManager,
    private val addChannelMessage: (String, BitchatMessage) -> Unit
) {
    companion object { private const val TAG = "GeohashMessageHandler" }

    // Simple event deduplication
    private val processedIds = ArrayDeque<String>()
    private val seen = HashSet<String>()
    private val max = 2000

    private fun dedupe(id: String): Boolean {
        if (seen.contains(id)) return true
        seen.add(id)
        processedIds.addLast(id)
        if (processedIds.size > max) {
            val old = processedIds.removeFirst()
            seen.remove(old)
        }
        return false
    }

    fun onEvent(event: NostrEvent, subscribedGeohash: String) {
        scope.launch {
            try {
                if (event.kind != NostrKind.EPHEMERAL_EVENT && event.kind != NostrKind.GEOHASH_PRESENCE) return@launch
                val tagGeo = event.tags.firstOrNull { it.size >= 2 && it[0] == "g" }?.getOrNull(1)
                if (tagGeo == null || !tagGeo.equals(subscribedGeohash, true)) return@launch
                if (dedupe(event.id)) return@launch

                // PoW validation (if enabled) - apply to chat messages primarily
                if (event.kind == NostrKind.EPHEMERAL_EVENT) {
                    val pow = PoWPreferenceManager.getCurrentSettings()
                    if (pow.enabled && pow.difficulty > 0) {
                        if (!NostrProofOfWork.validateDifficulty(event, pow.difficulty)) return@launch
                    }
                }

                // Normalize pubkey to lowercase for consistent blocking and storage
                val pubkey = event.pubkey.lowercase()

                // Blocked users check (use injected DataManager which has loaded state)
                if (dataManager.isGeohashUserBlocked(pubkey)) return@launch

                // Update participant count (last seen) on BOTH Presence (20001) and Chat (20000) events
                if (event.kind == NostrKind.GEOHASH_PRESENCE || event.kind == NostrKind.EPHEMERAL_EVENT) {
                    repo.updateParticipant(subscribedGeohash, pubkey, Date(event.createdAt * 1000L))
                }

                event.tags.find { it.size >= 2 && it[0] == "n" }?.let { repo.cacheNickname(pubkey, it[1]) }
                event.tags.find { it.size >= 2 && it[0] == "t" && it[1] == "teleport" }?.let { repo.markTeleported(pubkey) }
                // Register a geohash DM alias for this participant so MessageRouter can route DMs via Nostr
                try {
                    com.bitchat.android.nostr.GeohashAliasRegistry.put("nostr_${pubkey.take(16)}", pubkey)
                } catch (_: Exception) { }

                // Stop here for presence events - they don't produce chat messages
                if (event.kind == NostrKind.GEOHASH_PRESENCE) return@launch

                // Skip our own events for message emission
                val my = NostrIdentityBridge.deriveIdentity(subscribedGeohash, application)
                if (my.publicKeyHex.equals(pubkey, true)) return@launch

                val isTeleportPresence = event.tags.any { it.size >= 2 && it[0] == "t" && it[1] == "teleport" } &&
                                         event.content.trim().isEmpty()
                if (isTeleportPresence) return@launch

                val senderName = repo.displayNameForNostrPubkeyUI(pubkey)
                val hasNonce = try { NostrProofOfWork.hasNonce(event) } catch (_: Exception) { false }
                val msg = BitchatMessage(
                    id = event.id,
                    sender = senderName,
                    content = event.content,
                    timestamp = Date(event.createdAt * 1000L),
                    isRelay = false,
                    originalSender = repo.displayNameForNostrPubkey(pubkey),
                    senderPeerID = "nostr:${pubkey.take(8)}",
                    senderNostrPubkey = pubkey,
                    mentions = null,
                    channel = "#$subscribedGeohash",
                    powDifficulty = try {
                        if (hasNonce) NostrProofOfWork.calculateDifficulty(event.id).takeIf { it > 0 } else null
                    } catch (_: Exception) { null }
                )
                addChannelMessage("geo:$subscribedGeohash", msg)
            } catch (e: Exception) {
                Log.e(TAG, "onEvent error: ${e.message}")
            }
        }
    }
}

package com.bitchat.android.nostr

import android.app.Application
import android.util.Log
import com.bitchat.android.ui.ChatState
import com.bitchat.android.ui.GeoPerson
import java.util.Date

/**
 * GeohashRepository
 * - Owns geohash participant tracking and nickname caching
 * - Maintains lightweight state for geohash-related UI
 */
class GeohashRepository(
    private val application: Application,
    private val state: ChatState,
    private val dataManager: com.bitchat.android.ui.DataManager
) {
    companion object { private const val TAG = "GeohashRepository" }

    // geohash -> (participant pubkeyHex -> lastSeen)
    private val geohashParticipants: MutableMap<String, MutableMap<String, Date>> = mutableMapOf()


    // pubkeyHex(lowercase) -> nickname (without #hash)
    private val geoNicknames: MutableMap<String, String> = mutableMapOf()

    // conversation key (e.g., "nostr_<pub16>") -> source geohash it belongs to
    private val conversationGeohash: MutableMap<String, String> = mutableMapOf()

    @Synchronized
    fun setConversationGeohash(convKey: String, geohash: String) {
        if (geohash.isNotEmpty()) {
            conversationGeohash[convKey] = geohash
        }
    }

    @Synchronized
    fun getConversationGeohash(convKey: String): String? = conversationGeohash[convKey]

    @Synchronized
    fun findPubkeyByNickname(targetNickname: String): String? {
        return geoNicknames.entries.firstOrNull { (_, nickname) ->
            val base = nickname.split("#").firstOrNull() ?: nickname
            base == targetNickname
        }?.key
    }

    @Synchronized
    fun findPubkeyByShortId(shortId: String): String? {
        // First check cached nicknames (fastest)
        var found = geoNicknames.keys.firstOrNull { it.startsWith(shortId, ignoreCase = true) }
        if (found != null) return found

        // If not found in nicknames (e.g. anon user), check all known participants across all geohashes
        for (participants in geohashParticipants.values) {
            found = participants.keys.firstOrNull { it.startsWith(shortId, ignoreCase = true) }
            if (found != null) return found
        }

        return null
    }

    // peerID alias -> nostr pubkey mapping for geohash DMs and temp aliases
    private val nostrKeyMapping: MutableMap<String, String> = mutableMapOf()

    // Current geohash in view
    private var currentGeohash: String? = null

    fun setCurrentGeohash(geo: String?) { currentGeohash = geo }
    fun getCurrentGeohash(): String? = currentGeohash

    @Synchronized
    fun clearAll() {
        geohashParticipants.clear()
        geoNicknames.clear()
        nostrKeyMapping.clear()
        state.setGeohashPeople(emptyList())
        state.setTeleportedGeo(emptySet())
        state.setGeohashParticipantCounts(emptyMap())
        currentGeohash = null
    }

    @Synchronized
    fun cacheNickname(pubkeyHex: String, nickname: String) {
        val lower = pubkeyHex.lowercase()
        val previous = geoNicknames[lower]
        geoNicknames[lower] = nickname
        if (previous != nickname && currentGeohash != null) {
            refreshGeohashPeople()
        }
    }

    @Synchronized
    fun getCachedNickname(pubkeyHex: String): String? = geoNicknames[pubkeyHex.lowercase()]

    @Synchronized
    fun markTeleported(pubkeyHex: String) {
        val set = state.getTeleportedGeoValue().toMutableSet()
        val key = pubkeyHex.lowercase()
        if (!set.contains(key)) {
            set.add(key)
            // Background safe update
            state.postTeleportedGeo(set)
        }
    }

    @Synchronized
    fun isPersonTeleported(pubkeyHex: String): Boolean {
        return state.getTeleportedGeoValue().contains(pubkeyHex.lowercase())
    }

    @Synchronized
    fun updateParticipant(geohash: String, participantId: String, lastSeen: Date) {
        val participants = geohashParticipants.getOrPut(geohash) { mutableMapOf() }
        // Cap to now: prevents future-timestamped events (clock skew / malicious created_at)
        // from pinning lastSeen and blocking subsequent normal heartbeats.
        // Also keeps max: relays send events newest-first, so subsequent older events for
        // the same user must not overwrite a fresher lastSeen.
        val now = Date()
        val effective = if (lastSeen.after(now)) now else lastSeen
        val existing = participants[participantId]
        if (existing == null || effective.after(existing)) {
            participants[participantId] = effective
        }
        if (currentGeohash == geohash) refreshGeohashPeople()
        updateReactiveParticipantCounts()
    }

    @Synchronized
    fun geohashParticipantCount(geohash: String): Int {
        val cutoff = Date(System.currentTimeMillis() - 5 * 60 * 1000)
        val participants = geohashParticipants[geohash] ?: return 0
        // prune expired
        val it = participants.iterator()
        while (it.hasNext()) {
            val e = it.next()
            if (e.value.before(cutoff)) it.remove()
        }
        // exclude blocked users
        return participants.keys.count { !dataManager.isGeohashUserBlocked(it) }
    }

    @Synchronized
    fun refreshGeohashPeople() {
        val geohash = currentGeohash
        if (geohash == null) {
            // Use postValue for thread safety - this can be called from background threads
            state.setGeohashPeople(emptyList())
            return
        }
        val cutoff = Date(System.currentTimeMillis() - 5 * 60 * 1000)
        val participants = geohashParticipants[geohash] ?: mutableMapOf()
        // prune expired
        val it = participants.iterator()
        while (it.hasNext()) {
            val e = it.next()
            if (e.value.before(cutoff)) it.remove()
        }
        geohashParticipants[geohash] = participants
        // exclude blocked users from people list
        val people = participants.filterKeys { !dataManager.isGeohashUserBlocked(it) }
            .map { (pubkeyHex, lastSeen) ->
            // Use our actual nickname for self; otherwise use cached nickname or anon
            val base = try {
                val myHex = currentGeohash?.let { NostrIdentityBridge.deriveIdentity(it, application).publicKeyHex }
                if (myHex != null && myHex.equals(pubkeyHex, true)) {
                    state.getNicknameValue() ?: "anon"
                } else {
                    getCachedNickname(pubkeyHex) ?: "anon"
                }
            } catch (_: Exception) { getCachedNickname(pubkeyHex) ?: "anon" }
            GeoPerson(
                id = pubkeyHex.lowercase(),
                displayName = base, // UI can add #hash if necessary
                lastSeen = lastSeen
            )
        }.sortedByDescending { it.lastSeen }
        // Use postValue for thread safety - this can be called from background threads
        state.setGeohashPeople(people)
    }

    @Synchronized
    fun updateReactiveParticipantCounts() {
        val cutoff = Date(System.currentTimeMillis() - 5 * 60 * 1000)
        val counts = mutableMapOf<String, Int>()
        for ((gh, participants) in geohashParticipants) {
            val active = participants.filterKeys { !dataManager.isGeohashUserBlocked(it) }
                .values.count { !it.before(cutoff) }
            counts[gh] = active
        }
        // Use postValue for thread safety - this can be called from background threads  
        state.setGeohashParticipantCounts(counts)
    }

    @Synchronized
    fun putNostrKeyMapping(tempKeyOrPeer: String, pubkeyHex: String) {
        nostrKeyMapping[tempKeyOrPeer] = pubkeyHex
    }

    @Synchronized
    fun getNostrKeyMapping(): Map<String, String> = nostrKeyMapping.toMap()

    @Synchronized
    fun displayNameForNostrPubkey(pubkeyHex: String): String {
        val suffix = pubkeyHex.takeLast(4)
        val lower = pubkeyHex.lowercase()
        // Self nickname if matches current identity of current geohash
        val current = currentGeohash
        if (current != null) {
            try {
                val my = NostrIdentityBridge.deriveIdentity(current, application)
                if (my.publicKeyHex.equals(lower, true)) {
                    return "${state.getNicknameValue()}#$suffix"
                }
            } catch (_: Exception) {}
        }
        val nick = geoNicknames[lower] ?: "anon"
        return "$nick#$suffix"
    }

    @Synchronized
    fun displayNameForNostrPubkeyUI(pubkeyHex: String): String {
        val lower = pubkeyHex.lowercase()
        val suffix = pubkeyHex.takeLast(4)
        val current = currentGeohash
        val base: String = try {
            if (current != null) {
                val my = NostrIdentityBridge.deriveIdentity(current, application)
                if (my.publicKeyHex.equals(lower, true)) {
                    state.getNicknameValue() ?: "anon"
                } else geoNicknames[lower] ?: "anon"
            } else geoNicknames[lower] ?: "anon"
        } catch (_: Exception) { geoNicknames[lower] ?: "anon" }
        if (current == null) return base
        return try {
            val cutoff = Date(System.currentTimeMillis() - 5 * 60 * 1000)
            val participants = geohashParticipants[current] ?: emptyMap()
            var count = 0
            for ((k, t) in participants) {
                if (dataManager.isGeohashUserBlocked(k)) continue
                if (t.before(cutoff)) continue
                val name = if (k.equals(lower, true)) base else (geoNicknames[k.lowercase()] ?: "anon")
                if (name.equals(base, true)) { count++; if (count > 1) break }
            }
            if (!participants.containsKey(lower)) count += 1
            if (count > 1) "$base#$suffix" else base
        } catch (_: Exception) { base }
    }

    /**
     * Get display name for any geohash (not just current one) for header titles
     */
    @Synchronized
    fun displayNameForGeohashConversation(pubkeyHex: String, sourceGeohash: String): String {
        val lower = pubkeyHex.lowercase()
        val suffix = pubkeyHex.takeLast(4)
        val base = geoNicknames[lower] ?: "anon"
        return try {
            val cutoff = Date(System.currentTimeMillis() - 5 * 60 * 1000)
            val participants = geohashParticipants[sourceGeohash] ?: emptyMap()
            var count = 0
            for ((k, t) in participants) {
                if (dataManager.isGeohashUserBlocked(k)) continue
                if (t.before(cutoff)) continue
                val name = if (k.equals(lower, true)) base else (geoNicknames[k.lowercase()] ?: "anon")
                if (name.equals(base, true)) { count++; if (count > 1) break }
            }
            if (!participants.containsKey(lower)) count += 1
            if (count > 1) "$base#$suffix" else base
        } catch (_: Exception) { base }
    }
}

package com.bitchat.android.nostr

import android.content.Context
import android.util.Log

/**
 * Initializer for LocationNotesManager with all dependencies
 * Extracts initialization logic from MainActivity for better separation of concerns
 */
object LocationNotesInitializer {

    private const val TAG = "LocationNotesInitializer"

    /**
     * Initialize LocationNotesManager with all required dependencies
     * 
     * @param context Application context
     * @return true if initialization succeeded, false otherwise
     */
    fun initialize(context: Context): Boolean {
        return try {
            LocationNotesManager.getInstance().initialize(
                relayManager = { NostrRelayManager.getInstance(context) },
                subscribe = { filter, id, handler ->
                    // CRITICAL FIX: Extract geohash properly from filter using getGeohash() method
                    val geohashFromFilter = filter.getGeohash() ?: run {
                        Log.e(TAG, "❌ Cannot extract geohash from filter for location notes")
                        return@initialize id // Return subscription ID even on error
                    }

                    val token = com.bitchat.android.geohash.LiveLocationPrivacyGate
                        .captureToken() ?: return@initialize id
                    NostrRelayManager.getInstance(context).subscribeForGeohash(
                        geohash = geohashFromFilter,
                        filter = filter,
                        id = id,
                        handler = handler,
                        includeDefaults = true,
                        nRelays = 5,
                        liveLocationToken = token
                    )
                },
                unsubscribe = { id ->
                    NostrRelayManager.getInstance(context).unsubscribe(id)
                },
                sendEvent = { event, relayUrls, token ->
                    if (relayUrls != null) {
                        NostrRelayManager.getInstance(context).sendEvent(
                            event,
                            relayUrls,
                            liveLocationToken = token
                        )
                    } else {
                        NostrRelayManager.getInstance(context).sendEvent(
                            event,
                            liveLocationToken = token
                        )
                    }
                },
                deriveIdentity = { geohash ->
                    NostrIdentityBridge.deriveIdentity(geohash, context)
                }
            )
            Log.d(TAG, "✅ Location Notes Manager initialized")
            true
        } catch (e: Exception) {
            Log.e(TAG, "❌ Failed to initialize Location Notes Manager: ${e.message}", e)
            false
        }
    }
}

package com.bitchat.android.nostr

import android.util.Log
import androidx.annotation.MainThread
import com.bitchat.android.geohash.LiveLocationPrivacyGate
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

/**
 * Manages location notes (kind=1 text notes with geohash tags)
 * iOS-compatible implementation with StateFlow for Android UI binding
 */
@MainThread
class LocationNotesManager private constructor() {

    companion object {
        private const val TAG = "LocationNotesManager"
        private const val MAX_NOTES_IN_MEMORY = 500

        @Volatile
        private var INSTANCE: LocationNotesManager? = null

        fun getInstance(): LocationNotesManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: LocationNotesManager().also { INSTANCE = it }
            }
        }
    }

    /**
     * Note data class matching iOS implementation
     */
    data class Note(
        val id: String,
        val pubkey: String,
        val content: String,
        val createdAt: Int,
        val nickname: String?
    ) {
        /**
         * Display name for the note - matches iOS exactly
         * Format: "nickname#abcd" or "anon#abcd" where abcd is last 4 chars of pubkey
         */
        val displayName: String
            get() {
                val suffix = pubkey.takeLast(4)
                val nick = nickname?.trim()
                return if (!nick.isNullOrEmpty()) {
                    "$nick#$suffix"
                } else {
                    "anon#$suffix"
                }
            }
    }

    /**
     * Manager state enum
     */
    enum class State {
        IDLE,
        LOADING,
        READY,
        NO_RELAYS
    }

    // Published state (StateFlow for Android)
    private val _notes = MutableStateFlow<List<Note>>(emptyList())
    val notes: StateFlow<List<Note>> = _notes.asStateFlow()

    private val _geohash = MutableStateFlow<String?>(null)
    val geohash: StateFlow<String?> = _geohash.asStateFlow()

    private val _initialLoadComplete = MutableStateFlow(false)
    val initialLoadComplete: StateFlow<Boolean> = _initialLoadComplete.asStateFlow()

    private val _state = MutableStateFlow(State.IDLE)
    val state: StateFlow<State> = _state.asStateFlow()

    private val _errorMessage = MutableStateFlow<String?>(null)
    val errorMessage: StateFlow<String?> = _errorMessage.asStateFlow()

    // Private state
    private var subscriptionIDs: MutableMap<String, String> = mutableMapOf()
    private val noteIDs = mutableSetOf<String>() // For deduplication
    private var subscribedGeohashes: Set<String> = emptySet()

    // Dependencies (injected via setters for flexibility)
    private var relayLookup: (() -> NostrRelayManager)? = null
    private var subscribeFunc: ((NostrFilter, String, (NostrEvent) -> Unit) -> String)? = null
    private var unsubscribeFunc: ((String) -> Unit)? = null
    private var sendEventFunc: ((NostrEvent, List<String>?, Long) -> Unit)? = null
    private var deriveIdentityFunc: ((String) -> NostrIdentity)? = null

    // Coroutine scope for background operations
    private val scope = CoroutineScope(Dispatchers.Main + SupervisorJob())
    private var liveLocationToken: Long? = null
    private var subscribeRetryJob: Job? = null
    private var initialLoadJob: Job? = null

    init {
        LiveLocationPrivacyGate.addRevocationListener(::stop)
    }

    /**
     * Initialize dependencies
     */
    fun initialize(
        relayManager: () -> NostrRelayManager,
        subscribe: (NostrFilter, String, (NostrEvent) -> Unit) -> String,
        unsubscribe: (String) -> Unit,
        sendEvent: (NostrEvent, List<String>?, Long) -> Unit,
        deriveIdentity: (String) -> NostrIdentity
    ) {
        this.relayLookup = relayManager
        this.subscribeFunc = subscribe
        this.unsubscribeFunc = unsubscribe
        this.sendEventFunc = sendEvent
        this.deriveIdentityFunc = deriveIdentity
    }

    /**
     * Set geohash and start subscription
     * iOS: Validates building-level precision (8 characters)
     */
    fun setGeohash(newGeohash: String) {
        val token = LiveLocationPrivacyGate.captureToken() ?: run {
            stop()
            return
        }
        val normalized = newGeohash.lowercase()

        if (_geohash.value == normalized &&
            liveLocationToken?.let(LiveLocationPrivacyGate::accepts) == true
        ) {
            return
        }

        // Validate geohash (building-level precision: 8 chars) - matches iOS
        if (!isValidBuildingGeohash(normalized)) {
            Log.w(TAG, "LocationNotesManager rejected an invalid building geohash")
            return
        }

        // Cancel existing subscription
        cancel()
        if (!LiveLocationPrivacyGate.accepts(token)) return
        liveLocationToken = token

        // Set loading state before clearing to prevent empty state flicker (iOS pattern)
        _state.value = State.LOADING
        _initialLoadComplete.value = false
        _errorMessage.value = null

        // Clear notes
        _notes.value = emptyList()
        noteIDs.clear()
        _geohash.value = normalized

        // Compute target geohashes: center + neighbors (±1)
        val neighbors = try {
            com.bitchat.android.geohash.Geohash.neighborsSamePrecision(normalized)
        } catch (_: Exception) { emptySet() }
        subscribedGeohashes = (neighbors + normalized).toSet()

        // Start new subscriptions for all cells
        subscribeAll(token)
    }

    /**
     * Validate building-level geohash (precision 8) - matches iOS Geohash.isValidBuildingGeohash
     */
    private fun isValidBuildingGeohash(geohash: String): Boolean {
        if (geohash.length != 8) return false
        val base32Chars = "0123456789bcdefghjkmnpqrstuvwxyz"
        return geohash.all { it in base32Chars }
    }

    /**
     * Refresh notes for current geohash
     */
    fun refresh() {
        val token = LiveLocationPrivacyGate.captureToken() ?: run {
            stop()
            return
        }
        val currentGeohash = _geohash.value
        if (currentGeohash == null) {
            Log.w(TAG, "Cannot refresh - no geohash set")
            return
        }

        // Cancel and restart subscriptions for current ±1 set
        cancel()
        if (!LiveLocationPrivacyGate.accepts(token)) return
        liveLocationToken = token
        _notes.value = emptyList()
        noteIDs.clear()
        _initialLoadComplete.value = false
        // Rebuild subscribedGeohashes and resubscribe
        val neighbors = try {
            com.bitchat.android.geohash.Geohash.neighborsSamePrecision(currentGeohash)
        } catch (_: Exception) { emptySet() }
        subscribedGeohashes = (neighbors + currentGeohash).toSet()
        subscribeAll(token)
    }

    /**
     * Send a new location note
     */
    fun send(content: String, nickname: String?) {
        val token = LiveLocationPrivacyGate.captureToken() ?: run {
            stop()
            return
        }
        val currentGeohash = _geohash.value
        if (currentGeohash == null) {
            Log.w(TAG, "Cannot send note - no geohash set")
            _errorMessage.value = "No location set"
            return
        }

        val trimmed = content.trim()
        if (trimmed.isEmpty()) {
            return
        }

        // CRITICAL FIX: Get geo-specific relays for sending (matching iOS pattern)
        // iOS: let relays = dependencies.relayLookup(geohash, TransportConfig.nostrGeoRelayCount)
        var relays: List<String> = emptyList()
        try {
            LiveLocationPrivacyGate.runIfAllowed(token) {
                relays = RelayDirectory.closestRelaysForGeohash(currentGeohash, 5)
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to look up location-note relays")
        }
        if (!LiveLocationPrivacyGate.accepts(token)) {
            stop()
            return
        }

        // Check if we have relays (iOS pattern: guard !relays.isEmpty())
        if (relays.isEmpty()) {
            Log.w(TAG, "Location-note send blocked because no relays are available")
            _state.value = State.NO_RELAYS
            _errorMessage.value = "No relays available"
            return
        }

        val deriveIdentity = deriveIdentityFunc
        if (deriveIdentity == null) {
            Log.e(TAG, "Cannot send note - deriveIdentity not initialized")
            _errorMessage.value = "Not initialized"
            return
        }

        scope.launch {
            try {
                var identity: NostrIdentity? = null
                val identityPrepared = withContext(Dispatchers.IO) {
                    LiveLocationPrivacyGate.runIfAllowed(token) {
                        identity = deriveIdentity(currentGeohash)
                    }
                }
                val preparedIdentity = identity
                if (!identityPrepared || preparedIdentity == null ||
                    !LiveLocationPrivacyGate.accepts(token)
                ) return@launch

                val preparedEvent = withContext(Dispatchers.IO) {
                    NostrProtocol.createGeohashTextNote(
                            content = trimmed,
                            geohash = currentGeohash,
                            senderIdentity = preparedIdentity,
                            nickname = nickname
                        )
                }
                if (!LiveLocationPrivacyGate.accepts(token)) return@launch

                // Optimistic local echo - add note immediately to UI
                val localNote = Note(
                    id = preparedEvent.id,
                    pubkey = preparedEvent.pubkey,
                    content = trimmed,
                    createdAt = preparedEvent.createdAt,
                    nickname = nickname
                )

                if (!noteIDs.contains(preparedEvent.id)) {
                    noteIDs.add(preparedEvent.id)
                    val currentNotes = _notes.value ?: emptyList()
                    _notes.value = (currentNotes + localNote).sortedByDescending { it.createdAt }

                    // Trim if exceeds max
                    if (noteIDs.size > MAX_NOTES_IN_MEMORY) {
                        trimOldestNotes()
                    }
                }

                // CRITICAL FIX: Send to geo-specific relays (matching iOS pattern)
                // iOS: dependencies.sendEvent(event, relays)
                val sent = withContext(Dispatchers.IO) {
                    LiveLocationPrivacyGate.runIfAllowed(token) {
                        sendEventFunc?.invoke(preparedEvent, relays, token)
                    }
                }
                if (!sent) return@launch

                // Clear any error messages on successful send
                _errorMessage.value = null
                _state.value = State.READY

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send note: ${e.message}")
                _errorMessage.value = "Failed to send: ${e.message}"
            }
        }
    }

    /**
     * Subscribe to location notes for current geohash
     */
    private fun subscribeAll(token: Long) {
        subscribeRetryJob?.cancel()
        subscribeRetryJob = null
        initialLoadJob?.cancel()
        initialLoadJob = null

        if (!LiveLocationPrivacyGate.accepts(token)) {
            stop()
            return
        }
        val currentGeohash = _geohash.value
        if (currentGeohash == null) {
            Log.w(TAG, "Cannot subscribe - no geohash set")
            _state.value = State.IDLE
            return
        }

        val subscribe = subscribeFunc
        if (subscribe == null) {
            Log.e(TAG, "Cannot subscribe - subscribe function not initialized; will retry shortly")
            _state.value = State.LOADING
            // Retry a few times in case initialization is racing the sheet open
            subscribeRetryJob = scope.launch {
                var attempts = 0
                while (attempts < 10 &&
                    subscribeFunc == null &&
                    LiveLocationPrivacyGate.accepts(token)
                ) {
                    delay(300)
                    attempts++
                }
                val subNow = subscribeFunc
                if (subNow != null && LiveLocationPrivacyGate.accepts(token)) {
                    // Try again now that dependencies are ready
                    subscribeAll(token)
                } else {
                    // Give UI a chance to show empty state rather than spinner forever
                    if (!_initialLoadComplete.value) {
                        _initialLoadComplete.value = true
                        _state.value = State.READY
                    }
                }
            }
            return
        }

        _state.value = State.LOADING

        // Subscribe for each geohash in the ±1 set
        subscribedGeohashes.forEach { gh ->
            if (!LiveLocationPrivacyGate.accepts(token)) return
            val filter = NostrFilter.geohashNotes(
                geohash = gh,
                since = null,
                limit = 200
            )
            val subId = "location-notes-${UUID.randomUUID()}"
            try {
                var id: String? = null
                LiveLocationPrivacyGate.runIfAllowed(token) {
                    id = subscribe(filter, subId) { event -> handleEvent(event) }
                }
                id?.let { subscriptionIDs[gh] = it }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to subscribe to location notes")
            }
        }

        // Mark initial load complete after brief delay to allow relay responses
        initialLoadJob = scope.launch {
            delay(2000) // Wait 2 seconds for initial batch
            if (_geohash.value == currentGeohash &&
                LiveLocationPrivacyGate.accepts(token) &&
                !_initialLoadComplete.value
            ) {
                _initialLoadComplete.value = true
                _state.value = State.READY
            }
        }
    }

    /**
     * Handle incoming event from subscription
     */
    private fun handleEvent(event: NostrEvent) {
        val token = liveLocationToken
        if (token == null || !LiveLocationPrivacyGate.accepts(token)) return

        // Validate event
        if (event.kind != NostrKind.TEXT_NOTE) {
            Log.v(TAG, "Ignoring non-text-note event: kind=${event.kind}")
            return
        }

        // Check for geohash tag
        val geohashTag = event.tags.firstOrNull { it.size >= 2 && it[0] == "g" }
        if (geohashTag == null) {
            Log.v(TAG, "Ignoring event without geohash tag: ${event.id.take(16)}...")
            return
        }

        // Check if matches current geohash
        val eventGeohash = geohashTag[1]
        if (!subscribedGeohashes.contains(eventGeohash)) {
            return
        }

        // Deduplicate
        if (noteIDs.contains(event.id)) {
            return
        }

        // Extract nickname from tags
        val nicknameTag = event.tags.firstOrNull { it.size >= 2 && it[0] == "n" }
        val nickname = nicknameTag?.get(1)

        // Create note
        val note = Note(
            id = event.id,
            pubkey = event.pubkey,
            content = event.content,
            createdAt = event.createdAt,
            nickname = nickname
        )

        // Add to collection
        noteIDs.add(event.id)
        val currentNotes = _notes.value ?: emptyList()
        _notes.value = (currentNotes + note).sortedByDescending { it.createdAt }

        // Trim if exceeds max
        if (noteIDs.size > MAX_NOTES_IN_MEMORY) {
            trimOldestNotes()
        }

        // Update state
        if (!_initialLoadComplete.value!!) {
            _initialLoadComplete.value = true
        }
        _state.value = State.READY
    }

    /**
     * Trim oldest notes to stay within memory limit
     */
    private fun trimOldestNotes() {
        val currentNotes = _notes.value ?: return
        if (currentNotes.size <= MAX_NOTES_IN_MEMORY) return

        val trimmed = currentNotes.sortedByDescending { it.createdAt }.take(MAX_NOTES_IN_MEMORY)
        _notes.value = trimmed

        // Update note IDs set
        noteIDs.clear()
        noteIDs.addAll(trimmed.map { it.id })

        Log.d(TAG, "Trimmed notes to $MAX_NOTES_IN_MEMORY (removed ${currentNotes.size - trimmed.size})")
    }

    /**
     * Clear error message - matches iOS clearError()
     */
    fun clearError() {
        _errorMessage.value = null
    }

    /**
     * Cancel subscription and clear state
     */
    fun cancel() {
        subscribeRetryJob?.cancel()
        subscribeRetryJob = null
        initialLoadJob?.cancel()
        initialLoadJob = null

        if (subscriptionIDs.isNotEmpty()) {
            subscriptionIDs.values.forEach { subId ->
                try {
                    unsubscribeFunc?.invoke(subId)
                } catch (_: Exception) { }
            }
            subscriptionIDs.clear()
        }
        subscribedGeohashes = emptySet()
        _state.value = State.IDLE
    }

    /**
     * End the nearby-notes session and discard location-correlated UI state.
     * Unlike [cancel], this also clears the target so a later activation can
     * safely subscribe to the same building geohash again.
     */
    fun stop() {
        cancel()
        liveLocationToken = null
        _geohash.value = null
        _notes.value = emptyList()
        noteIDs.clear()
        _initialLoadComplete.value = false
        _errorMessage.value = null
    }

    /**
     * Cleanup resources
     */
    fun cleanup() {
        stop()
        scope.cancel()
    }
}

package com.bitchat.android.nostr

import androidx.annotation.MainThread
import com.bitchat.android.geohash.GeohashChannel
import com.bitchat.android.geohash.GeohashChannelLevel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Session-scoped consent gate for nearby location notes.
 *
 * Merely rendering the mesh timeline must not open a building-precision Nostr
 * subscription. A subscription is eligible only after an explicit reveal and
 * while the app is foregrounded and at least one nearby-notes surface is active.
 */
@MainThread
class NearbyNotesController internal constructor(
    private val subscribe: (String) -> Unit,
    private val unsubscribe: () -> Unit,
) {
    private val _revealed = MutableStateFlow(false)
    val revealed: StateFlow<Boolean> = _revealed.asStateFlow()

    private var activeHolders = 0
    private var locationEnabled = false
    private var locationAuthorized = false
    private var appForeground = false
    private var buildingGeohash: String? = null
    private var subscribedGeohash: String? = null

    /**
     * Unlocks nearby notes for this process session. Deactivation deliberately
     * does not reset consent, matching the iOS privacy model.
     */
    fun reveal() {
        if (_revealed.value) return
        _revealed.value = true
        reconcileSubscription()
    }

    /** Holds the subscription while a nearby-notes surface is visible. */
    fun activate() {
        activeHolders += 1
        reconcileSubscription()
    }

    /** Releases a matching [activate] hold and unsubscribes after the last one. */
    fun deactivate() {
        activeHolders = (activeHolders - 1).coerceAtLeast(0)
        reconcileSubscription()
    }

    /** Closes the live subscription whenever the process leaves the foreground. */
    fun updateAppForeground(isForeground: Boolean) {
        appForeground = isForeground
        reconcileSubscription()
    }

    /**
     * Updates the privacy-sensitive inputs independently of view activation.
     * Permission revocation, location disable, or loss of the building cell
     * immediately closes any live subscription.
     */
    fun updateAvailability(
        locationEnabled: Boolean,
        locationAuthorized: Boolean,
        buildingGeohash: String?,
    ) {
        this.locationEnabled = locationEnabled
        this.locationAuthorized = locationAuthorized
        this.buildingGeohash = buildingGeohash
            ?.trim()
            ?.lowercase()
            ?.takeIf { it.isNotEmpty() }
        reconcileSubscription()
    }

    fun offersRevealHint(): Boolean =
        !_revealed.value &&
            locationEnabled &&
            locationAuthorized &&
            buildingGeohash != null

    private fun reconcileSubscription() {
        val target = buildingGeohash.takeIf {
            activeHolders > 0 &&
                appForeground &&
                _revealed.value &&
                locationEnabled &&
                locationAuthorized
        }

        if (subscribedGeohash != null && subscribedGeohash != target) {
            unsubscribe()
            subscribedGeohash = null
        }

        if (target != null && subscribedGeohash == null) {
            subscribe(target)
            subscribedGeohash = target
        }
    }

    companion object {
        val shared: NearbyNotesController by lazy {
            val manager = LocationNotesManager.getInstance()
            NearbyNotesController(
                subscribe = manager::setGeohash,
                unsubscribe = manager::stop,
            )
        }
    }
}

/**
 * Building precision is location-notes precision and remains private before a
 * reveal. Explicit bookmarks remain eligible because saving one is itself an
 * intentional location act.
 */
internal fun geohashesForSampling(
    availableChannels: List<GeohashChannel>,
    bookmarks: Collection<String>,
    notesRevealed: Boolean,
): List<String> = buildSet {
    availableChannels
        .filter { notesRevealed || it.level != GeohashChannelLevel.BUILDING }
        .mapTo(this) { it.geohash }
    addAll(bookmarks)
}.toList()

package com.bitchat.android.nostr

import android.app.Application
import com.bitchat.android.model.DeliveryStatus
import com.bitchat.android.services.AppStateStore
import com.bitchat.android.ui.ChatState
import com.bitchat.android.ui.DataManager
import com.bitchat.android.ui.MessageManager
import com.bitchat.android.ui.NoiseSessionDelegate
import com.bitchat.android.ui.PrivateChatManager
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

/**
 * Process-owned Nostr event processing.
 *
 * Relay subscriptions must remain useful when no Activity exists, so their handlers cannot be
 * borrowed from a ViewModel. This processor owns only application-scoped collaborators and writes
 * messages to [AppStateStore], which the next UI instance hydrates from.
 */
internal class NostrBackgroundEventProcessor(
    application: Application,
    parentScope: CoroutineScope
) {
    private val scope = CoroutineScope(
        parentScope.coroutineContext + Dispatchers.IO.limitedParallelism(1)
    )
    private val state = ChatState(scope)
    private val dataManager = DataManager(application.applicationContext).apply {
        state.setNickname(loadNickname())
        loadBlockedUsers()
        loadGeohashBlockedUsers()
    }
    private val messageManager = MessageManager(state)
    private val geohashRepository = GeohashRepository(application, state, dataManager)
    private val privateChatManager = PrivateChatManager(
        state = state,
        messageManager = messageManager,
        dataManager = dataManager,
        noiseSessionDelegate = object : NoiseSessionDelegate {
            override fun hasEstablishedSession(peerID: String): Boolean = false
            override fun initiateHandshake(peerID: String) = Unit
            override fun getMyPeerID(): String = ""
        },
        trackUnreadMessages = false
    )
    private val geohashMessageHandler = GeohashMessageHandler(
        application = application,
        repo = geohashRepository,
        scope = scope,
        dataManager = dataManager,
        addChannelMessage = AppStateStore::addChannelMessage
    )
    private val directMessageHandler = NostrDirectMessageHandler(
        application = application,
        state = state,
        privateChatManager = privateChatManager,
        updateDeliveryStatus = ::updateDeliveryStatus,
        scope = scope,
        repo = geohashRepository,
        dataManager = dataManager
    )

    init {
        // Keep the headless state aligned with messages sent or received through other transports.
        // This preserves duplicate detection and focused-conversation behavior without retaining UI.
        scope.launch {
            AppStateStore.privateMessages.collect(state::setPrivateChats)
        }
        scope.launch {
            AppStateStore.nickname.collect(state::setNickname)
        }
        scope.launch {
            AppStateStore.selectedPrivateChatPeer.collect(state::setSelectedPrivateChatPeer)
        }
    }

    fun onAccountDm(event: NostrEvent, identity: NostrIdentity) {
        refreshBlockLists()
        directMessageHandler.onGiftWrap(event, "", identity)
    }

    fun onGeohashMessage(event: NostrEvent, geohash: String) {
        refreshBlockLists()
        geohashMessageHandler.onEvent(event, geohash)
    }

    fun onGeohashDm(event: NostrEvent, geohash: String, identity: NostrIdentity) {
        refreshBlockLists()
        directMessageHandler.onGiftWrap(event, geohash, identity)
    }

    fun conversationGeohash(conversationKey: String): String? =
        geohashRepository.getConversationGeohash(conversationKey)
            ?: GeohashConversationRegistry.get(conversationKey)

    fun displayNameForNostrPubkey(pubkeyHex: String): String =
        geohashRepository.displayNameForNostrPubkeyUI(pubkeyHex)

    fun displayNameForGeohashConversation(pubkeyHex: String, sourceGeohash: String): String =
        geohashRepository.displayNameForGeohashConversation(pubkeyHex, sourceGeohash)

    private fun updateDeliveryStatus(messageId: String, status: DeliveryStatus) {
        messageManager.updateMessageDeliveryStatus(messageId, status)
        // The headless state may not yet contain a just-sent UI message. Update the process store
        // unconditionally so a delivery/read receipt can never be lost during Activity handoff.
        AppStateStore.updatePrivateMessageStatus(messageId, status)
    }

    private fun refreshBlockLists() {
        dataManager.loadBlockedUsers()
        dataManager.loadGeohashBlockedUsers()
    }
}

package com.bitchat.android.nostr

import android.app.Application
import android.util.Log
import com.bitchat.android.geohash.ChannelID
import com.bitchat.android.geohash.GeohashNostrPrivacyPolicy
import com.bitchat.android.geohash.LiveLocationPrivacyGate
import com.bitchat.android.geohash.LocationChannelManager
import com.bitchat.android.mesh.PowerManager
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch
import java.security.SecureRandom
import kotlin.random.asKotlinRandom

/**
 * Process-owned Nostr connectivity and low-volume background subscriptions.
 *
 * Stable subscriptions dispatch directly to a process-owned event processor. The UI hydrates from
 * the process state store, so relay events remain useful without retaining a cleared ViewModel.
 */
object NostrBackgroundRuntime {
    private const val TAG = "NostrBackground"

    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private val random = SecureRandom().asKotlinRandom()
    private val lock = Any()

    @Volatile private var initialized = false
    @Volatile private var activeGeohash: String? = null
    @Volatile private var activeGeohashLiveToken: Long? = null
    @Volatile private var conversationGeohash: String? = null
    private lateinit var application: Application
    private lateinit var subscriptions: NostrSubscriptionManager
    private lateinit var locationChannels: LocationChannelManager
    private lateinit var eventProcessor: NostrBackgroundEventProcessor

    fun initialize(app: Application) {
        synchronized(lock) {
            if (initialized) return
            application = app
            locationChannels = LocationChannelManager.getInstance(app)
            eventProcessor = NostrBackgroundEventProcessor(app, scope)
            subscriptions = NostrSubscriptionManager(
                app,
                owner = NostrRelayManager.OWNER_BACKGROUND
            )
            // Publish readiness only after every process-owned dependency is available.
            initialized = true
        }

        subscriptions.connect()
        subscribeAccountDm()
        observeSelectedChannel()
        startPresenceScheduler()
    }

    fun resetSubscriptions() {
        if (!initialized) return
        subscriptions.unsubscribeAllOwned()
        scope.launch {
            // Let CLOSE frames be queued before replacing the deterministic IDs.
            delay(100)
            subscribeAccountDm()
            activeGeohash?.let { geohash ->
                subscribeSelectedGeohash(geohash, activeGeohashLiveToken)
            }
        }
    }

    fun ensureConversationDm(geohash: String) {
        if (!initialized || geohash == conversationGeohash) return
        val selectedLiveToken = activeGeohashLiveToken
        val selectedChannelSubscriptionIsUsable =
            geohash == activeGeohash &&
                (selectedLiveToken == null ||
                    LiveLocationPrivacyGate.accepts(selectedLiveToken))
        if (selectedChannelSubscriptionIsUsable) return
        conversationGeohash?.let { subscriptions.unsubscribe("geo-dm-conversation-$it") }
        conversationGeohash = geohash
        subscribeGeohashDm(
            geohash = geohash,
            subscriptionId = "geo-dm-conversation-$geohash",
            liveLocationToken = null
        )
    }

    private fun subscribeAccountDm() {
        val identity = NostrIdentityBridge.getCurrentNostrIdentity(application) ?: return
        subscriptions.subscribeGiftWraps(
            pubkey = identity.publicKeyHex,
            sinceMs = System.currentTimeMillis() - 172_800_000L,
            id = "chat-messages",
            handler = { event ->
                eventProcessor.onAccountDm(event, identity)
            }
        )
    }

    private fun observeSelectedChannel() {
        scope.launch {
            locationChannels.selectedChannel.collectLatest { channel ->
                val locationChannel = channel as? ChannelID.Location
                val next = locationChannel?.channel?.geohash
                val nextToken = locationChannel?.let {
                    locationChannels.liveLocationTokenForSelectedChannel(it.channel)
                }
                val previous = activeGeohash
                if (previous == next && activeGeohashLiveToken == nextToken) {
                    return@collectLatest
                }

                previous?.let {
                    subscriptions.unsubscribe("geohash-$it")
                    subscriptions.unsubscribe("geo-dm-$it")
                }
                activeGeohash = next
                activeGeohashLiveToken = nextToken
                if (conversationGeohash == next) {
                    subscriptions.unsubscribe("geo-dm-conversation-$next")
                    conversationGeohash = null
                }
                next?.let { geohash ->
                    val isLiveDerived =
                        locationChannels.isSelectedChannelLiveDerived(locationChannel.channel)
                    if (!isLiveDerived || nextToken != null) {
                        subscribeSelectedGeohash(geohash, nextToken)
                    }
                }
            }
        }
    }

    private fun subscribeSelectedGeohash(
        geohash: String,
        liveLocationToken: Long?
    ) {
        subscriptions.subscribeGeohashMessages(
            geohash = geohash,
            sinceMs = System.currentTimeMillis() - 3_600_000L,
            limit = 200,
            id = "geohash-$geohash",
            handler = { event -> eventProcessor.onGeohashMessage(event, geohash) },
            liveLocationToken = liveLocationToken
        )
        subscribeGeohashDm(geohash, "geo-dm-$geohash", liveLocationToken)
    }

    private fun subscribeGeohashDm(
        geohash: String,
        subscriptionId: String,
        liveLocationToken: Long?
    ) {
        scope.launch {
            val subscribe = {
                val identity = NostrIdentityBridge.deriveIdentity(geohash, application)
                subscriptions.subscribeGiftWraps(
                    pubkey = identity.publicKeyHex,
                    sinceMs = System.currentTimeMillis() - 172_800_000L,
                    id = subscriptionId,
                    handler = { event ->
                        eventProcessor.onGeohashDm(event, geohash, identity)
                    },
                    liveLocationToken = liveLocationToken
                )
                GeohashAliasRegistry.put(
                    "nostr_${identity.publicKeyHex.take(16)}",
                    identity.publicKeyHex
                )
            }

            if (liveLocationToken == null) {
                subscribe()
            } else {
                LiveLocationPrivacyGate.runIfAllowed(liveLocationToken, subscribe)
            }
        }
    }

    private fun startPresenceScheduler() {
        val powerManager = PowerManager.getInstance(application)
        scope.launch {
            val nostrSchedule = powerManager.profile
                .map { it.nostr }
                .distinctUntilChanged()
            combine(
                locationChannels.availableChannels,
                LiveLocationPrivacyGate.enabled,
                nostrSchedule
            ) { channels, liveLocationEnabled, schedule ->
                val targets = GeohashNostrPrivacyPolicy.livePresenceTargets(
                    availableChannels = channels,
                    liveLocationEnabled = liveLocationEnabled
                )
                targets to schedule
            }.collectLatest { (targets, schedule) ->
                if (targets.isEmpty()) return@collectLatest
                while (true) {
                    val waitMs = if (schedule.presenceHeartbeatMaxMs > schedule.presenceHeartbeatMinMs) {
                        random.nextLong(
                            schedule.presenceHeartbeatMinMs,
                            schedule.presenceHeartbeatMaxMs + 1
                        )
                    } else {
                        schedule.presenceHeartbeatMinMs
                    }
                    delay(waitMs)

                    // Send every target in one wake window; do not spread the batch over seconds.
                    targets.forEach { geohash ->
                        try {
                            val token = LiveLocationPrivacyGate.captureToken()
                                ?: return@forEach
                            if (geohash !in GeohashNostrPrivacyPolicy.livePresenceTargets(
                                    availableChannels = locationChannels.availableChannels.value,
                                    liveLocationEnabled = true
                                )
                            ) return@forEach

                            var identity: NostrIdentity? = null
                            LiveLocationPrivacyGate.runIfAllowed(token) {
                                identity = NostrIdentityBridge.deriveIdentity(geohash, application)
                            }
                            val preparedIdentity = identity ?: return@forEach
                            if (!LiveLocationPrivacyGate.accepts(token)) return@forEach
                            val event = NostrProtocol.createGeohashPresenceEvent(
                                geohash,
                                preparedIdentity
                            )
                            LiveLocationPrivacyGate.runIfAllowed(token) {
                                NostrRelayManager.getInstance(application).sendEventToGeohash(
                                    event = event,
                                    geohash = geohash,
                                    includeDefaults = false,
                                    nRelays = 5,
                                    liveLocationToken = token
                                )
                            }
                        } catch (e: CancellationException) {
                            throw e
                        } catch (e: Exception) {
                            Log.w(TAG, "Presence heartbeat failed for $geohash: ${e.message}")
                        }
                    }
                }
            }
        }
    }

    fun conversationGeohash(conversationKey: String): String? =
        if (initialized) eventProcessor.conversationGeohash(conversationKey)
        else GeohashConversationRegistry.get(conversationKey)

    fun displayNameForNostrPubkey(pubkeyHex: String): String? =
        if (initialized) eventProcessor.displayNameForNostrPubkey(pubkeyHex) else null

    fun displayNameForGeohashConversation(
        pubkeyHex: String,
        sourceGeohash: String
    ): String? = if (initialized) {
        eventProcessor.displayNameForGeohashConversation(pubkeyHex, sourceGeohash)
    } else {
        null
    }
}

package com.bitchat.android.nostr

import android.content.Context
import android.util.Log
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * High-level Nostr client that manages identity, connections, and messaging
 * Provides a simple API for the rest of the application
 */
class NostrClient private constructor(private val context: Context) {

    companion object {
        private const val TAG = "NostrClient"

        @Volatile
        private var INSTANCE: NostrClient? = null

        fun getInstance(context: Context): NostrClient {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: NostrClient(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    // Core components
    private val relayManager = NostrRelayManager.shared
    private var currentIdentity: NostrIdentity? = null

    // Client state
    private val _isInitialized = MutableStateFlow(false)
    val isInitialized: StateFlow<Boolean> = _isInitialized.asStateFlow()

    private val _currentNpub = MutableStateFlow<String?>(null)
    val currentNpub: StateFlow<String?> = _currentNpub.asStateFlow()

    // Message processing
    private val scope = CoroutineScope(Dispatchers.Main + SupervisorJob())

    init {
        Log.d(TAG, "Initializing Nostr client")
    }

    /**
     * Initialize the Nostr client with identity and relay connections
     */
    fun initialize() {
        scope.launch {
            try {
                // Load or create identity
                currentIdentity = NostrIdentityBridge.getCurrentNostrIdentity(context)

                if (currentIdentity != null) {
                    _currentNpub.value = currentIdentity!!.npub
                    Log.i(TAG, "✅ Nostr identity loaded: ${currentIdentity!!.getShortNpub()}")

                    // Connect to relays
                    relayManager.connect()

                    _isInitialized.value = true
                    Log.i(TAG, "✅ Nostr client initialized successfully")
                } else {
                    Log.e(TAG, "❌ Failed to load/create Nostr identity")
                    _isInitialized.value = false
                }
            } catch (e: Exception) {
                Log.e(TAG, "❌ Failed to initialize Nostr client: ${e.message}")
                _isInitialized.value = false
            }
        }
    }

    /**
     * Shutdown the client and disconnect from relays
     */
    fun shutdown() {
        Log.d(TAG, "Shutting down Nostr client")
        relayManager.disconnect()
        _isInitialized.value = false
    }

    /**
     * Send a private message using NIP-17
     */
    fun sendPrivateMessage(
        content: String,
        recipientNpub: String,
        onSuccess: (() -> Unit)? = null,
        onError: ((String) -> Unit)? = null
    ) {
        val identity = currentIdentity
        if (identity == null) {
            onError?.invoke("Nostr client not initialized")
            return
        }

        scope.launch {
            try {
                // Decode recipient npub to hex pubkey
                val (hrp, pubkeyBytes) = Bech32.decode(recipientNpub)
                if (hrp != "npub") {
                    onError?.invoke("Invalid npub format")
                    return@launch
                }

                val recipientPubkeyHex = pubkeyBytes.toHexString()

                // Create and send gift wraps (receiver and sender copies)
                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = content,
                    recipientPubkey = recipientPubkeyHex,
                    senderIdentity = identity
                )

                // Track and send all gift wraps
                giftWraps.forEach { wrap ->
                    NostrRelayManager.registerPendingGiftWrap(wrap.id)
                    relayManager.sendEvent(wrap)
                }

                Log.i(TAG, "📤 Sent private message to ${recipientNpub.take(16)}...")
                onSuccess?.invoke()

            } catch (e: Exception) {
                Log.e(TAG, "❌ Failed to send private message: ${e.message}")
                onError?.invoke("Failed to send message: ${e.message}")
            }
        }
    }

    /**
     * Subscribe to private messages for current identity
     */
    fun subscribeToPrivateMessages(handler: (content: String, senderNpub: String, timestamp: Int) -> Unit) {
        val identity = currentIdentity
        if (identity == null) {
            Log.e(TAG, "Cannot subscribe to private messages: client not initialized")
            return
        }

        val filter = NostrFilter.giftWrapsFor(
            pubkey = identity.publicKeyHex,
            since = System.currentTimeMillis() - 172800000L // Last 48 hours (align with NIP-17 randomization)
        )

        relayManager.subscribe(filter, "private-messages", { giftWrap ->
            scope.launch {
                handlePrivateMessage(giftWrap, handler)
            }
        })

        Log.i(TAG, "🔑 Subscribed to private messages for: ${identity.getShortNpub()}")
    }

    /**
     * Send a public message to a geohash channel
     */
    fun sendGeohashMessage(
        content: String,
        geohash: String,
        nickname: String? = null,
        onSuccess: (() -> Unit)? = null,
        onError: ((String) -> Unit)? = null
    ) {
        scope.launch {
            try {
                // Derive geohash-specific identity
                val geohashIdentity = NostrIdentityBridge.deriveIdentity(geohash, context)

                // Create ephemeral event (with PoW if enabled)
                val event = NostrProtocol.createEphemeralGeohashEvent(
                    content = content,
                    geohash = geohash,
                    senderIdentity = geohashIdentity,
                    nickname = nickname
                )

                relayManager.sendEvent(event)

                Log.i(TAG, "📤 Sent geohash message")
                onSuccess?.invoke()

            } catch (e: Exception) {
                Log.e(TAG, "❌ Failed to send geohash message: ${e.message}")
                onError?.invoke("Failed to send message: ${e.message}")
            }
        }
    }

    /**
     * Subscribe to public messages in a geohash channel
     */
    fun subscribeToGeohash(
        geohash: String,
        handler: (content: String, senderPubkey: String, nickname: String?, timestamp: Int) -> Unit
    ) {
        val filter = NostrFilter.geohashEphemeral(
            geohash = geohash,
            since = System.currentTimeMillis() - 3600000L, // Last hour
            limit = 200
        )

        relayManager.subscribe(filter, "geohash-$geohash", { event ->
            scope.launch {
                handleGeohashMessage(event, handler)
            }
        })

        Log.i(TAG, "🌍 Subscribed to geohash channel")
    }

    /**
     * Unsubscribe from a geohash channel
     */
    fun unsubscribeFromGeohash(geohash: String) {
        relayManager.unsubscribe("geohash-$geohash")
        Log.i(TAG, "Unsubscribed from geohash channel")
    }

    /**
     * Get current identity information
     */
    fun getCurrentIdentity(): NostrIdentity? = currentIdentity

    /**
     * Get relay connection status
     */
    val relayConnectionStatus: StateFlow<Boolean> = relayManager.isConnected

    /**
     * Get relay information
     */
    val relayInfo: StateFlow<List<NostrRelayManager.Relay>> = relayManager.relays

    // MARK: - Private Methods

    private suspend fun handlePrivateMessage(
        giftWrap: NostrEvent,
        handler: (content: String, senderNpub: String, timestamp: Int) -> Unit
    ) {
        // Age filtering (24h + 15min buffer for randomized timestamps)
        val messageAge = System.currentTimeMillis() / 1000 - giftWrap.createdAt
        if (messageAge > 173700) { // 48 hours + 15 minutes
            Log.v(TAG, "Ignoring old private message")
            return
        }

        val identity = currentIdentity ?: return

        try {
            val decryptResult = NostrProtocol.decryptPrivateMessage(giftWrap, identity)
            if (decryptResult != null) {
                val (content, senderPubkey, timestamp) = decryptResult

                // Convert sender pubkey to npub
                val senderNpub = try {
                    Bech32.encode("npub", senderPubkey.hexToByteArray())
                } catch (e: Exception) {
                    Log.w(TAG, "Failed to encode sender npub: ${e.message}")
                    "npub_decode_error"
                }

                Log.d(TAG, "📥 Received private message from ${senderNpub.take(16)}...")

                // Dispatch to main thread for handler
                withContext(Dispatchers.Main) {
                    handler(content, senderNpub, timestamp)
                }
            } else {
                Log.w(TAG, "Failed to decrypt private message")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error handling private message: ${e.message}")
        }
    }

    private suspend fun handleGeohashMessage(
        event: NostrEvent,
        handler: (content: String, senderPubkey: String, nickname: String?, timestamp: Int) -> Unit
    ) {
        try {
            // Check Proof of Work validation for incoming geohash events
            val powSettings = PoWPreferenceManager.getCurrentSettings()
            if (powSettings.enabled && powSettings.difficulty > 0) {
                if (!NostrProofOfWork.validateDifficulty(event, powSettings.difficulty)) {
                    Log.w(TAG, "🚫 Rejecting geohash event ${event.id.take(8)}... due to insufficient PoW (required: ${powSettings.difficulty})")
                    return
                }
                Log.v(TAG, "✅ PoW validation passed for geohash event ${event.id.take(8)}...")
            }

            // Extract nickname from tags
            val nickname = event.tags.find { it.size >= 2 && it[0] == "n" }?.get(1)

            Log.v(TAG, "📥 Received geohash message from ${event.pubkey.take(16)}...")

            // Dispatch to main thread for handler
            withContext(Dispatchers.Main) {
                handler(event.content, event.pubkey, nickname, event.createdAt)
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error handling geohash message: ${e.message}")
        }
    }
}

package com.bitchat.android.nostr

import org.bouncycastle.crypto.ec.CustomNamedCurves
import org.bouncycastle.crypto.params.ECDomainParameters
import org.bouncycastle.crypto.params.ECPrivateKeyParameters
import org.bouncycastle.crypto.params.ECPublicKeyParameters
import org.bouncycastle.math.ec.ECPoint
import org.bouncycastle.crypto.generators.ECKeyPairGenerator
import org.bouncycastle.crypto.params.ECKeyGenerationParameters
import org.bouncycastle.crypto.agreement.ECDHBasicAgreement
import org.bouncycastle.crypto.digests.SHA256Digest
import org.bouncycastle.crypto.macs.HMac
import org.bouncycastle.crypto.params.KeyParameter
import com.google.crypto.tink.subtle.XChaCha20Poly1305
import java.security.SecureRandom
import java.security.MessageDigest
import java.math.BigInteger

/**
 * Cryptographic utilities for Nostr protocol
 * Includes secp256k1 operations, ECDH, and NIP-44 encryption
 */
object NostrCrypto {

    private val secureRandom = SecureRandom()
    // NIP-44 v2 only

    // secp256k1 curve parameters
    val secp256k1Curve = CustomNamedCurves.getByName("secp256k1")
    val secp256k1Params = ECDomainParameters(
        secp256k1Curve.curve,
        secp256k1Curve.g,
        secp256k1Curve.n,
        secp256k1Curve.h
    )

    /**
     * Generate secp256k1 key pair
     * Returns (privateKeyHex, publicKeyHex)
     */
    fun generateKeyPair(): Pair<String, String> {
        val generator = ECKeyPairGenerator()
        val keyGenParams = ECKeyGenerationParameters(secp256k1Params, secureRandom)
        generator.init(keyGenParams)

        val keyPair = generator.generateKeyPair()
        val privateKey = keyPair.private as ECPrivateKeyParameters
        val publicKey = keyPair.public as ECPublicKeyParameters

        // Get private key as 32-byte hex - ensure proper padding
        val privateKeyBigInt = privateKey.d
        val privateKeyBytes = privateKeyBigInt.toByteArray()

        val privateKeyPadded = ByteArray(32)
        if (privateKeyBytes.size <= 32) {
            val srcStart = maxOf(0, privateKeyBytes.size - 32)
            val destStart = maxOf(0, 32 - privateKeyBytes.size)
            val length = minOf(privateKeyBytes.size, 32)
            System.arraycopy(privateKeyBytes, srcStart, privateKeyPadded, destStart, length)
        } else {
            // If BigInteger added a sign byte, skip it
            System.arraycopy(privateKeyBytes, privateKeyBytes.size - 32, privateKeyPadded, 0, 32)
        }

        // Get x-only public key (32 bytes)
        val publicKeyPoint = publicKey.q.normalize()
        val xCoord = publicKeyPoint.xCoord.encoded

        return Pair(
            privateKeyPadded.toHexString(),
            xCoord.toHexString()
        )
    }

    /**
     * Derive public key from private key
     * Returns x-only public key (32 bytes hex)
     */
    fun derivePublicKey(privateKeyHex: String): String {
        val privateKeyBytes = privateKeyHex.hexToByteArray()
        val privateKeyBigInt = BigInteger(1, privateKeyBytes)

        val publicKeyPoint = secp256k1Params.g.multiply(privateKeyBigInt).normalize()
        val xCoord = publicKeyPoint.xCoord.encoded

        return xCoord.toHexString()
    }

    /**
     * Perform ECDH key agreement
     * Returns shared secret
     */
    fun performECDH(privateKeyHex: String, publicKeyHex: String): ByteArray {
        val privateKeyBytes = privateKeyHex.hexToByteArray()
        val publicKeyBytes = publicKeyHex.hexToByteArray()

        val privateKeyBigInt = BigInteger(1, privateKeyBytes)
        val privateKeyParams = ECPrivateKeyParameters(privateKeyBigInt, secp256k1Params)

        // Recover full public key point from x-only coordinate (prefer even y per BIP-340)
        val publicKeyPoint = recoverPublicKeyPoint(publicKeyBytes)
        val publicKeyParams = ECPublicKeyParameters(publicKeyPoint, secp256k1Params)

        val agreement = ECDHBasicAgreement()
        agreement.init(privateKeyParams)

        val sharedSecret = agreement.calculateAgreement(publicKeyParams)
        val sharedSecretBytes = sharedSecret.toByteArray()

        // Ensure 32 bytes
        val result = ByteArray(32)
        if (sharedSecretBytes.size <= 32) {
            System.arraycopy(
                sharedSecretBytes,
                maxOf(0, sharedSecretBytes.size - 32),
                result,
                maxOf(0, 32 - sharedSecretBytes.size),
                minOf(sharedSecretBytes.size, 32)
            )
        } else {
            // If BigInteger added a leading sign byte, keep the last 32 bytes
            System.arraycopy(sharedSecretBytes, sharedSecretBytes.size - 32, result, 0, 32)
        }

        return result
    }

    /**
     * Perform ECDH with explicit parity choice for the x-only public key
     * If preferOddY is true, use the odd-y lift; otherwise even-y lift.
     */
    private fun performECDHWithParity(privateKeyHex: String, publicKeyHex: String, preferOddY: Boolean): ByteArray {
        val privateKeyBytes = privateKeyHex.hexToByteArray()
        val publicKeyBytes = publicKeyHex.hexToByteArray()
        val privateKeyBigInt = BigInteger(1, privateKeyBytes)
        val privateKeyParams = ECPrivateKeyParameters(privateKeyBigInt, secp256k1Params)
        val point = recoverPublicKeyPointWithParity(publicKeyBytes, preferOddY)
        val publicKeyParams = ECPublicKeyParameters(point, secp256k1Params)
        val agreement = ECDHBasicAgreement()
        agreement.init(privateKeyParams)
        val sharedSecret = agreement.calculateAgreement(publicKeyParams)
        val sharedSecretBytes = sharedSecret.toByteArray()
        val result = ByteArray(32)
        if (sharedSecretBytes.size <= 32) {
            System.arraycopy(sharedSecretBytes, maxOf(0, sharedSecretBytes.size - 32), result, maxOf(0, 32 - sharedSecretBytes.size), minOf(sharedSecretBytes.size, 32))
        } else {
            // If BigInteger added a leading sign byte, keep the last 32 bytes
            System.arraycopy(sharedSecretBytes, sharedSecretBytes.size - 32, result, 0, 32)
        }
        return result
    }

    /**
     * Recover full EC point from x-only coordinate
     * Tries both possible y coordinates
     */
    private fun recoverPublicKeyPoint(xOnlyBytes: ByteArray): ECPoint {
        require(xOnlyBytes.size == 32) { "X-only public key must be 32 bytes" }

        val x = BigInteger(1, xOnlyBytes)

        // Try even y first (0x02 prefix)
        try {
            val compressedBytes = ByteArray(33)
            compressedBytes[0] = 0x02
            System.arraycopy(xOnlyBytes, 0, compressedBytes, 1, 32)
            return secp256k1Curve.curve.decodePoint(compressedBytes)
        } catch (e: Exception) {
            // Try odd y (0x03 prefix)
            val compressedBytes = ByteArray(33)
            compressedBytes[0] = 0x03
            System.arraycopy(xOnlyBytes, 0, compressedBytes, 1, 32)
            return secp256k1Curve.curve.decodePoint(compressedBytes)
        }
    }

    private fun recoverPublicKeyPointWithParity(xOnlyBytes: ByteArray, preferOddY: Boolean): ECPoint {
        require(xOnlyBytes.size == 32) { "X-only public key must be 32 bytes" }
        val prefix: Byte = if (preferOddY) 0x03 else 0x02
        val compressedBytes = ByteArray(33)
        compressedBytes[0] = prefix
        System.arraycopy(xOnlyBytes, 0, compressedBytes, 1, 32)
        return secp256k1Curve.curve.decodePoint(compressedBytes)
    }

    /**
     * Compute the ECDH shared point (uncompressed) with an explicit parity choice for the x-only public key
     */
    private fun computeSharedPointWithParity(privateKeyHex: String, publicKeyHex: String, preferOddY: Boolean): ECPoint {
        val privateKeyBytes = privateKeyHex.hexToByteArray()
        val publicKeyBytes = publicKeyHex.hexToByteArray()
        val privateKeyBigInt = BigInteger(1, privateKeyBytes)
        val point = recoverPublicKeyPointWithParity(publicKeyBytes, preferOddY)
        return point.multiply(privateKeyBigInt).normalize()
    }

    private fun compressedPoint(point: ECPoint): ByteArray {
        val normalized = point.normalize()
        val x = normalized.xCoord.encoded
        val prefix: Byte = if (hasEvenY(normalized)) 0x02 else 0x03
        val out = ByteArray(33)
        out[0] = prefix
        System.arraycopy(x, 0, out, 1, 32)
        return out
    }

    /**
     * NIP-44 v2 key derivation using HKDF-SHA256
     * salt = empty, info = "nip44-v2", length = 32 bytes
     */
    fun deriveNIP44Key(sharedSecret: ByteArray): ByteArray {
        val zeroSalt = ByteArray(0)
        val prk = hkdfExtract(zeroSalt, sharedSecret)
        return hkdfExpand(prk, info = "nip44-v2".toByteArray(Charsets.UTF_8), length = 32)
    }

    private fun hkdfExtract(salt: ByteArray, ikm: ByteArray): ByteArray {
        val hmac = HMac(SHA256Digest())
        hmac.init(KeyParameter(salt))
        hmac.update(ikm, 0, ikm.size)
        val prk = ByteArray(hmac.macSize)
        hmac.doFinal(prk, 0)
        return prk
    }

    private fun hkdfExpand(prk: ByteArray, info: ByteArray?, length: Int): ByteArray {
        val hmac = HMac(SHA256Digest())
        hmac.init(KeyParameter(prk))
        if (info != null && info.isNotEmpty()) {
            hmac.update(info, 0, info.size)
        }
        hmac.update(byteArrayOf(0x01), 0, 1)
        val t = ByteArray(hmac.macSize)
        hmac.doFinal(t, 0)
        return t.copyOf(length)
    }

    /**
     * NIP-44 v2 encryption using XChaCha20-Poly1305
     * Output format: "v2:" + base64url(nonce24 || ciphertext || tag)
     */
    fun encryptNIP44(
        plaintext: String,
        recipientPublicKeyHex: String,
        senderPrivateKeyHex: String
    ): String {
        try {
            // Match iOS: derive HKDF input from the compressed shared point (33 bytes)
            val sharedPoint = computeSharedPointWithParity(senderPrivateKeyHex, recipientPublicKeyHex, preferOddY = false)
            val secretMaterial = compressedPoint(sharedPoint)
            val encryptionKey = deriveNIP44Key(secretMaterial)
            val aead = XChaCha20Poly1305(encryptionKey)
            val combined = aead.encrypt(plaintext.toByteArray(Charsets.UTF_8), null) // nonce||ct||tag
            val b64 = base64UrlNoPad(combined)
            android.util.Log.d("NostrCrypto", "NIP44 v2 encrypt: len=${b64.length}")
            return "v2:$b64"
        } catch (e: Exception) {
            throw RuntimeException("NIP-44 v2 encryption failed: ${e.message}", e)
        }
    }

    /**
     * NIP-44 v2 decryption using XChaCha20-Poly1305
     * Only accepts the exact "v2:" base64url format.
     * Tries both even/odd Y parities for x-only pubkeys.
     */
    fun decryptNIP44(ciphertext: String, senderPublicKeyHex: String, recipientPrivateKeyHex: String): String {
        try {
            require(ciphertext.startsWith("v2:")) { "Invalid NIP-44 version prefix" }
            val encoded = ciphertext.substring(3)
            val encryptedData = base64UrlDecode(encoded)
                ?: throw IllegalArgumentException("Invalid base64url payload")

            var lastError: Exception? = null
            // Try even-Y first, then odd-Y
            for (preferOdd in listOf(false, true)) {
                try {
                    // Match iOS: derive HKDF input from the compressed shared point (33 bytes)
                    val point = computeSharedPointWithParity(recipientPrivateKeyHex, senderPublicKeyHex, preferOddY = preferOdd)
                    val secretMaterial = compressedPoint(point)
                    val key = deriveNIP44Key(secretMaterial)
                    val aead = XChaCha20Poly1305(key)
                    val pt = aead.decrypt(encryptedData, null) // expects nonce||ct||tag
                    return String(pt, Charsets.UTF_8)
                } catch (e: Exception) {
                    lastError = e
                }
            }
            throw lastError ?: RuntimeException("NIP-44 v2 decryption failed")
        } catch (e: Exception) {
            throw RuntimeException("NIP-44 v2 decryption failed: ${e.message}", e)
        }
    }

    private fun base64UrlNoPad(data: ByteArray): String {
        val b64 = android.util.Base64.encodeToString(data, android.util.Base64.NO_WRAP)
        return b64.replace('+', '-').replace('/', '_').replace("=", "")
    }

    private fun base64UrlDecode(s: String): ByteArray? {
        var str = s.replace('-', '+').replace('_', '/')
        val pad = (4 - (str.length % 4)) % 4
        if (pad > 0) str += "=".repeat(pad)
        return try {
            android.util.Base64.decode(str, android.util.Base64.NO_WRAP)
        } catch (_: IllegalArgumentException) {
            null
        }
    }

    /**
     * Generate random timestamp offset for privacy (±15 minutes)
     */
    fun randomizeTimestamp(baseTimestamp: Long = System.currentTimeMillis() / 1000): Int {
        val offset = secureRandom.nextInt(1800) - 900 // ±15 minutes in seconds
        return (baseTimestamp + offset).toInt()
    }

    /**
     * Random timestamp up to maxPastSeconds in the past (default 2 days)
     */
    fun randomizeTimestampUpToPast(maxPastSeconds: Int = 172800): Int {
        val now = (System.currentTimeMillis() / 1000).toInt()
        val offset = if (maxPastSeconds > 0) secureRandom.nextInt(maxPastSeconds + 1) else 0
        return now - offset
    }

    /**
     * Validate secp256k1 private key
     */
    fun isValidPrivateKey(privateKeyHex: String): Boolean {
        return try {
            val privateKeyBytes = privateKeyHex.hexToByteArray()
            if (privateKeyBytes.size != 32) return false

            val privateKeyBigInt = BigInteger(1, privateKeyBytes)

            // Must be less than curve order and greater than 0
            privateKeyBigInt > BigInteger.ZERO && privateKeyBigInt < secp256k1Params.n
        } catch (e: Exception) {
            false
        }
    }

    /**
     * Validate x-only public key
     */
    fun isValidPublicKey(publicKeyHex: String): Boolean {
        return try {
            val publicKeyBytes = publicKeyHex.hexToByteArray()
            if (publicKeyBytes.size != 32) return false

            // Try to recover point
            recoverPublicKeyPoint(publicKeyBytes)
            true
        } catch (e: Exception) {
            false
        }
    }

    // ==============================================================================
    // BIP-340 Schnorr Signatures Implementation
    // ==============================================================================

    /**
     * Tagged hash function for BIP-340
     */
    private fun taggedHash(tag: String, data: ByteArray): ByteArray {
        val tagBytes = tag.toByteArray(Charsets.UTF_8)
        val tagHash = MessageDigest.getInstance("SHA-256").digest(tagBytes)

        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(tagHash)
        digest.update(tagHash)
        digest.update(data)
        return digest.digest()
    }

    /**
     * Check if y coordinate is even
     */
    private fun hasEvenY(point: ECPoint): Boolean {
        val yCoord = point.normalize().yCoord.encoded
        return (yCoord[yCoord.size - 1].toInt() and 1) == 0
    }

    /**
     * Lift x coordinate to point with even y
     */
    private fun liftX(xBytes: ByteArray): ECPoint? {
        return try {
            val point = recoverPublicKeyPoint(xBytes)
            val normalizedPoint = point.normalize()

            if (hasEvenY(normalizedPoint)) {
                normalizedPoint
            } else {
                normalizedPoint.negate()
            }
        } catch (e: Exception) {
            null
        }
    }

    /**
     * BIP-340 Schnorr signature creation
     * Returns 64-byte signature (r || s) as hex string
     */
    fun schnorrSign(messageHash: ByteArray, privateKeyHex: String): String {
        require(messageHash.size == 32) { "Message hash must be 32 bytes" }

        val privateKeyBytes = privateKeyHex.hexToByteArray()
        require(privateKeyBytes.size == 32) { "Private key must be 32 bytes" }

        val d = BigInteger(1, privateKeyBytes)
        require(d > BigInteger.ZERO && d < secp256k1Params.n) { "Invalid private key" }

        // Compute public key point P = d * G
        val P = secp256k1Params.g.multiply(d).normalize()

        // Ensure P has even y coordinate, adjust d if necessary
        val (adjustedD, publicKeyBytes) = if (hasEvenY(P)) {
            Pair(d, P.xCoord.encoded)
        } else {
            Pair(secp256k1Params.n.subtract(d), P.xCoord.encoded)
        }

        // Generate nonce
        val k = generateNonce(adjustedD, messageHash, publicKeyBytes)

        // Compute R = k * G
        val R = secp256k1Params.g.multiply(k).normalize()

        // Ensure R has even y coordinate
        val adjustedK = if (hasEvenY(R)) k else secp256k1Params.n.subtract(k)
        val r = R.xCoord.encoded

        // Compute challenge e = H(r || P || m)
        val challengeData = ByteArray(96) // 32 + 32 + 32
        System.arraycopy(r, 0, challengeData, 0, 32)
        System.arraycopy(publicKeyBytes, 0, challengeData, 32, 32)
        System.arraycopy(messageHash, 0, challengeData, 64, 32)

        val eBytes = taggedHash("BIP0340/challenge", challengeData)
        val e = BigInteger(1, eBytes).mod(secp256k1Params.n)

        // Compute s = (k + e * d) mod n
        val s = adjustedK.add(e.multiply(adjustedD)).mod(secp256k1Params.n)

        // Return signature as r || s (64 bytes hex)
        val rPadded = ByteArray(32)
        val sPadded = ByteArray(32)

        val rBytes = r
        val sBytes = s.toByteArray()

        // Pad r to 32 bytes (should already be 32)
        System.arraycopy(rBytes, 0, rPadded, 0, minOf(32, rBytes.size))

        // Pad s to 32 bytes - handle BigInteger padding correctly
        if (sBytes.size <= 32) {
            val srcStart = maxOf(0, sBytes.size - 32)
            val destStart = maxOf(0, 32 - sBytes.size)
            val length = minOf(sBytes.size, 32)
            System.arraycopy(sBytes, srcStart, sPadded, destStart, length)
        } else {
            // If BigInteger added a sign byte, skip it
            System.arraycopy(sBytes, sBytes.size - 32, sPadded, 0, 32)
        }

        return (rPadded + sPadded).toHexString()
    }

    /**
     * BIP-340 Schnorr signature verification
     */
    fun schnorrVerify(messageHash: ByteArray, signatureHex: String, publicKeyHex: String): Boolean {
        return try {
            require(messageHash.size == 32) { "Message hash must be 32 bytes" }

            val signatureBytes = signatureHex.hexToByteArray()
            require(signatureBytes.size == 64) { "Signature must be 64 bytes" }

            val publicKeyBytes = publicKeyHex.hexToByteArray()
            require(publicKeyBytes.size == 32) { "Public key must be 32 bytes" }

            // Parse signature
            val r = signatureBytes.copyOfRange(0, 32)
            val sBytes = signatureBytes.copyOfRange(32, 64)
            val s = BigInteger(1, sBytes)

            // Validate r and s
            val rBigInt = BigInteger(1, r)
            if (rBigInt >= secp256k1Params.curve.field.characteristic) return false
            if (s >= secp256k1Params.n) return false

            // Lift public key
            val P = liftX(publicKeyBytes) ?: return false

            // Compute challenge e = H(r || P || m)
            val challengeData = ByteArray(96)
            System.arraycopy(r, 0, challengeData, 0, 32)
            System.arraycopy(publicKeyBytes, 0, challengeData, 32, 32)
            System.arraycopy(messageHash, 0, challengeData, 64, 32)

            val eBytes = taggedHash("BIP0340/challenge", challengeData)
            val e = BigInteger(1, eBytes).mod(secp256k1Params.n)

            // Compute R = s * G - e * P
            val sG = secp256k1Params.g.multiply(s)
            val eP = P.multiply(e)
            val R = sG.subtract(eP).normalize()

            // Check if R has even y and x coordinate matches r
            if (!hasEvenY(R)) return false

            val computedR = R.xCoord.encoded
            return r.contentEquals(computedR)

        } catch (e: Exception) {
            false
        }
    }

    /**
     * Generate deterministic nonce for Schnorr signature (RFC 6979 style)
     */
    private fun generateNonce(privateKey: BigInteger, messageHash: ByteArray, publicKeyBytes: ByteArray): BigInteger {
        // Simple nonce generation - in production, use RFC 6979
        // For now, use SHA256(private_key || message || public_key || random)
        val random = ByteArray(32)
        secureRandom.nextBytes(random)

        val privateKeyBytes = privateKey.toByteArray()
        val nonceInput = ByteArray(privateKeyBytes.size + messageHash.size + publicKeyBytes.size + random.size)
        var offset = 0

        System.arraycopy(privateKeyBytes, 0, nonceInput, offset, privateKeyBytes.size)
        offset += privateKeyBytes.size

        System.arraycopy(messageHash, 0, nonceInput, offset, messageHash.size)
        offset += messageHash.size

        System.arraycopy(publicKeyBytes, 0, nonceInput, offset, publicKeyBytes.size)
        offset += publicKeyBytes.size

        System.arraycopy(random, 0, nonceInput, offset, random.size)

        val nonceHash = MessageDigest.getInstance("SHA-256").digest(nonceInput)
        val nonce = BigInteger(1, nonceHash)

        // Ensure nonce is in valid range
        return if (nonce >= secp256k1Params.n) {
            nonce.mod(secp256k1Params.n)
        } else {
            nonce
        }
    }
}

package com.bitchat.android.nostr

import android.app.Application
import android.util.Log
import com.bitchat.android.favorites.FavoriteControlMessage
import com.bitchat.android.favorites.FavoritesPersistenceService
import com.bitchat.android.model.BitchatFilePacket
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.DeliveryStatus
import com.bitchat.android.model.NoisePayload
import com.bitchat.android.model.NoisePayloadType
import com.bitchat.android.model.PrivateMessagePacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.services.ContactDirectory
import com.bitchat.android.services.ContactIdentityResolver
import com.bitchat.android.services.SeenMessageStore
import com.bitchat.android.ui.ChatState
import com.bitchat.android.ui.PrivateChatManager
import com.bitchat.android.ui.PrivateMessageOrigin
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.util.Date

class NostrDirectMessageHandler(
    private val application: Application,
    private val state: ChatState,
    private val privateChatManager: PrivateChatManager,
    private val updateDeliveryStatus: (String, DeliveryStatus) -> Unit,
    private val scope: CoroutineScope,
    private val repo: GeohashRepository,
    private val dataManager: com.bitchat.android.ui.DataManager,
    private val seenStoreProvider: () -> SeenMessageStore = {
        SeenMessageStore.getInstance(application)
    }
) {
    companion object { private const val TAG = "NostrDirectMessageHandler" }

    private val seenStore by lazy(seenStoreProvider)

    // Simple event deduplication
    private val processedIds = ArrayDeque<String>()
    private val seen = HashSet<String>()
    private val max = 2000

    private fun dedupe(id: String): Boolean {
        if (seen.contains(id)) return true
        seen.add(id)
        processedIds.addLast(id)
        if (processedIds.size > max) {
            val old = processedIds.removeFirst()
            seen.remove(old)
        }
        return false
    }

    fun onGiftWrap(giftWrap: NostrEvent, geohash: String, identity: NostrIdentity) {
        scope.launch {
            try {
                if (dedupe(giftWrap.id)) return@launch

                val messageAge = System.currentTimeMillis() / 1000 - giftWrap.createdAt
                if (messageAge > 173700) return@launch // 48 hours + 15 mins

                val decryptResult = NostrProtocol.decryptPrivateMessage(giftWrap, identity)
                if (decryptResult == null) {
                    Log.w(TAG, "Failed to decrypt Nostr message")
                    return@launch
                }

                val (content, rawSenderPubkey, rumorTimestamp) = decryptResult
                val senderPubkey = rawSenderPubkey.lowercase()

                // If sender is blocked for geohash contexts, drop any events from this pubkey
                // Applies to both geohash DMs (geohash != "") and account DMs (geohash == "")
                if (dataManager.isGeohashUserBlocked(senderPubkey)) return@launch
                if (!content.startsWith("bitchat1:")) return@launch

                val base64Content = content.removePrefix("bitchat1:")
                val packetData = base64URLDecode(base64Content) ?: return@launch
                val packet = BitchatPacket.fromBinaryData(packetData) ?: return@launch

                if (packet.type != com.bitchat.android.protocol.MessageType.NOISE_ENCRYPTED.value) return@launch

                val noisePayload = NoisePayload.decode(packet.payload) ?: return@launch
                val messageTimestamp = Date(rumorTimestamp * 1000L)
                val convKey = "nostr_${senderPubkey.take(16)}"
                repo.putNostrKeyMapping(convKey, senderPubkey)
                com.bitchat.android.nostr.GeohashAliasRegistry.put(convKey, senderPubkey)
                if (geohash.isNotEmpty()) {
                    // Remember which geohash this conversation belongs to so we can subscribe on-demand
                    repo.setConversationGeohash(convKey, geohash)
                    GeohashConversationRegistry.set(convKey, geohash)
                }

                // Ensure sender appears in geohash people list even if they haven't posted publicly yet
                if (geohash.isNotEmpty()) {
                    // Cache a best-effort nickname and mark as participant
                    val cached = repo.getCachedNickname(senderPubkey)
                    if (cached == null) {
                        val base = repo.displayNameForNostrPubkeyUI(senderPubkey).substringBefore("#")
                        repo.cacheNickname(senderPubkey, base)
                    }
                    repo.updateParticipant(geohash, senderPubkey, messageTimestamp)
                }

                val senderNickname = repo.displayNameForNostrPubkeyUI(senderPubkey)
                val conversationID = ContactDirectory.canonicalConversationId(convKey)

                processNoisePayload(noisePayload, conversationID, senderNickname, messageTimestamp, senderPubkey, identity)

            } catch (e: Exception) {
                Log.e(TAG, "onGiftWrap error: ${e.message}")
            }
        }
    }

    private suspend fun processNoisePayload(
        payload: NoisePayload,
        conversationID: String,
        senderNickname: String,
        timestamp: Date,
        senderPubkey: String,
        recipientIdentity: NostrIdentity
    ) {
        when (payload.type) {
            NoisePayloadType.PRIVATE_MESSAGE -> {
                val pm = PrivateMessagePacket.decode(payload.data) ?: return
                val existingMessages = state.getPrivateChatsValue()[conversationID] ?: emptyList()
                if (existingMessages.any { it.id == pm.messageID }) return

                val favoriteControl = FavoriteControlMessage.parse(pm.content)
                if (favoriteControl != null) {
                    val admitted = handleFavoriteControl(
                        favoriteControl,
                        conversationID,
                        senderNickname,
                        timestamp,
                        senderPubkey
                    )
                    if (!admitted) return
                    if (!seenStore.hasDelivered(pm.messageID)) {
                        val nostrTransport = NostrTransport.getInstance(application)
                        nostrTransport.sendDeliveryAckGeohash(pm.messageID, senderPubkey, recipientIdentity)
                        seenStore.markDelivered(pm.messageID)
                    }
                    return
                }

                val message = BitchatMessage(
                    id = pm.messageID,
                    sender = senderNickname,
                    content = pm.content,
                    timestamp = timestamp,
                    isRelay = false,
                    isPrivate = true,
                    recipientNickname = state.getNicknameValue(),
                    senderPeerID = conversationID,
                    senderNostrPubkey = senderPubkey,
                    deliveryStatus = DeliveryStatus.Delivered(to = state.getNicknameValue() ?: "Unknown", at = Date())
                )

                val isViewing = state.getSelectedPrivateChatPeerValue() == conversationID
                val suppressUnread = seenStore.hasBeenReadLocally(pm.messageID)

                val admitted = withContext(Dispatchers.Main) {
                    privateChatManager.handleIncomingPrivateMessageDurably(
                        message = message,
                        suppressUnread = suppressUnread,
                        origin = PrivateMessageOrigin.NOSTR
                    )
                }
                if (!admitted) return

                if (!seenStore.hasDelivered(pm.messageID)) {
                    val nostrTransport = NostrTransport.getInstance(application)
                    nostrTransport.sendDeliveryAckGeohash(pm.messageID, senderPubkey, recipientIdentity)
                    seenStore.markDelivered(pm.messageID)
                }

                if (isViewing && !suppressUnread) {
                    val nostrTransport = NostrTransport.getInstance(application)
                    nostrTransport.sendReadReceiptGeohash(pm.messageID, senderPubkey, recipientIdentity)
                    seenStore.markReadLocally(pm.messageID)
                    seenStore.markReadReceiptSent(pm.messageID)
                }
            }
            NoisePayloadType.DELIVERED -> {
                val messageId = String(payload.data, Charsets.UTF_8)
                withContext(Dispatchers.Main) {
                    updateDeliveryStatus(
                        messageId,
                        DeliveryStatus.Delivered(conversationID, Date())
                    )
                }
            }
            NoisePayloadType.READ_RECEIPT -> {
                val messageId = String(payload.data, Charsets.UTF_8)
                withContext(Dispatchers.Main) {
                    updateDeliveryStatus(
                        messageId,
                        DeliveryStatus.Read(conversationID, Date())
                    )
                }
            }
            NoisePayloadType.FILE_TRANSFER -> {
                // Properly handle encrypted file transfer
                val file = BitchatFilePacket.decode(payload.data)
                if (file != null) {
                    val uniqueMsgId = java.util.UUID.randomUUID().toString().uppercase()
                    val savedPath = com.bitchat.android.features.file.FileUtils.saveIncomingFile(application, file)
                    val message = BitchatMessage(
                        id = uniqueMsgId,
                        sender = senderNickname,
                        content = savedPath,
                        type = com.bitchat.android.features.file.FileUtils.messageTypeForMime(file.mimeType),
                        timestamp = timestamp,
                        isRelay = false,
                        isPrivate = true,
                        recipientNickname = state.getNicknameValue(),
                        senderPeerID = conversationID,
                        senderNostrPubkey = senderPubkey
                    )
                    Log.d(TAG, "📄 Saved Nostr encrypted incoming file to $savedPath (msgId=$uniqueMsgId)")
                    val admitted = withContext(Dispatchers.Main) {
                        privateChatManager.handleIncomingPrivateMessageDurably(
                            message = message,
                            suppressUnread = false,
                            origin = PrivateMessageOrigin.NOSTR
                        )
                    }
                    if (!admitted) {
                        com.bitchat.android.features.file.FileUtils.deleteStoredMediaPaths(
                            application,
                            listOf(savedPath)
                        )
                    }
                } else {
                    Log.w(TAG, "Failed to decode Nostr file transfer from $conversationID")
                }
            }
            NoisePayloadType.VERIFY_CHALLENGE,
            NoisePayloadType.VERIFY_RESPONSE,
            NoisePayloadType.VOICE_FRAME,
            NoisePayloadType.PEER_STATE -> Unit // Peer state is bound to a live mesh Noise generation.
        }
    }

    private suspend fun handleFavoriteControl(
        control: FavoriteControlMessage,
        conversationID: String,
        senderNickname: String,
        timestamp: Date,
        senderPubkey: String
    ): Boolean {
        return try {
            val senderNpub = control.npub ?: ContactIdentityResolver.npubFromHex(senderPubkey)
            val noiseKey = senderNpub?.let { FavoritesPersistenceService.shared.findNoiseKey(it) }
                ?: FavoritesPersistenceService.shared.findNoiseKey(senderPubkey)

            if (noiseKey == null) {
                Log.w(TAG, "Favorite notification from Nostr sender without known Noise key: ${senderPubkey.take(16)}...")
                return false
            }

            FavoritesPersistenceService.shared.updatePeerFavoritedUs(noiseKey, control.isFavorite)
            senderNpub?.let { FavoritesPersistenceService.shared.updateNostrPublicKey(noiseKey, it) }
            val targetConversationID = ContactDirectory.canonicalConversationId(conversationID)

            val relationship = FavoritesPersistenceService.shared.getFavoriteStatus(noiseKey)
            val displayName = relationship
                ?.peerNickname
                ?.takeUnless { it.equals("Unknown", ignoreCase = true) }
                ?: senderNickname
            val guidance = if (control.isFavorite) {
                if (relationship?.isFavorite == true) {
                    " - mutual! You can continue DMs via Nostr when out of mesh."
                } else {
                    " - favorite back to continue DMs later."
                }
            } else {
                ". DMs over Nostr will pause unless you both favorite again."
            }
            val action = if (control.isFavorite) "favorited" else "unfavorited"
            val systemMessage = BitchatMessage(
                sender = "system",
                content = "$displayName $action you$guidance",
                timestamp = timestamp,
                isRelay = false,
                isPrivate = true,
                senderPeerID = targetConversationID
            )

            withContext(Dispatchers.Main) {
                privateChatManager.handleIncomingPrivateMessageDurably(
                    message = systemMessage,
                    suppressUnread = true,
                    origin = PrivateMessageOrigin.NOSTR
                )
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to handle Nostr favorite notification: ${e.message}")
            false
        }
    }

    private fun base64URLDecode(input: String): ByteArray? {
        return try {
            val padded = input.replace("-", "+")
                .replace("_", "/")
                .let { str ->
                    val padding = (4 - str.length % 4) % 4
                    str + "=".repeat(padding)
                }
            android.util.Base64.decode(padded, android.util.Base64.DEFAULT)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decode base64url: ${e.message}")
            null
        }
    }
}

package com.bitchat.android.nostr

import android.util.Base64
import android.util.Log
import com.bitchat.android.mesh.MeshPacketUtils
import com.bitchat.android.model.PrivateMessagePacket
import com.bitchat.android.model.NoisePayloadType
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.services.ContactIdentityResolver
import java.util.*

/**
 * BitChat-over-Nostr Adapter
 */
object NostrEmbeddedBitChat {

    private const val TAG = "NostrEmbeddedBitChat"

    /**
     * Build a `bitchat1:` base64url-encoded BitChat packet carrying a private message for Nostr DMs.
     */
    fun encodePMForNostr(
        content: String,
        messageID: String,
        recipientPeerID: String,
        senderPeerID: String
    ): String? {
        try {
            // TLV-encode the private message
            val pm = PrivateMessagePacket(messageID = messageID, content = content)
            val tlv = pm.encode() ?: return null

            // Prefix with NoisePayloadType
            val payload = ByteArray(1 + tlv.size)
            payload[0] = NoisePayloadType.PRIVATE_MESSAGE.value.toByte()
            System.arraycopy(tlv, 0, payload, 1, tlv.size)

            // Determine 8-byte recipient ID to embed
            val recipientIDHex = normalizeRecipientPeerID(recipientPeerID)

            val packet = BitchatPacket(
                version = 1u,
                type = MessageType.NOISE_ENCRYPTED.value,
                senderID = hexStringToByteArray(senderPeerID),
                recipientID = hexStringToByteArray(recipientIDHex),
                timestamp = System.currentTimeMillis().toULong(),
                payload = payload,
                signature = null,
                ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS
            )

            val data = packet.toBinaryData() ?: return null
            return "bitchat1:" + base64URLEncode(data)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encode PM for Nostr: ${e.message}")
            return null
        }
    }

    /**
     * Build a `bitchat1:` base64url-encoded BitChat packet carrying a delivery/read ack for Nostr DMs.
     */
    fun encodeAckForNostr(
        type: NoisePayloadType,
        messageID: String,
        recipientPeerID: String,
        senderPeerID: String
    ): String? {
        if (type != NoisePayloadType.DELIVERED && type != NoisePayloadType.READ_RECEIPT) {
            return null
        }

        try {
            val payload = ByteArray(1 + messageID.toByteArray(Charsets.UTF_8).size)
            payload[0] = type.value.toByte()
            val messageIDBytes = messageID.toByteArray(Charsets.UTF_8)
            System.arraycopy(messageIDBytes, 0, payload, 1, messageIDBytes.size)

            val recipientIDHex = normalizeRecipientPeerID(recipientPeerID)

            val packet = BitchatPacket(
                version = 1u,
                type = MessageType.NOISE_ENCRYPTED.value,
                senderID = hexStringToByteArray(senderPeerID),
                recipientID = hexStringToByteArray(recipientIDHex),
                timestamp = System.currentTimeMillis().toULong(),
                payload = payload,
                signature = null,
                ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS
            )

            val data = packet.toBinaryData() ?: return null
            return "bitchat1:" + base64URLEncode(data)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encode ACK for Nostr: ${e.message}")
            return null
        }
    }

    /**
     * Build a `bitchat1:` ACK (delivered/read) without an embedded recipient peer ID (geohash DMs).
     */
    fun encodeAckForNostrNoRecipient(
        type: NoisePayloadType,
        messageID: String,
        senderPeerID: String
    ): String? {
        if (type != NoisePayloadType.DELIVERED && type != NoisePayloadType.READ_RECEIPT) {
            return null
        }

        try {
            val payload = ByteArray(1 + messageID.toByteArray(Charsets.UTF_8).size)
            payload[0] = type.value.toByte()
            val messageIDBytes = messageID.toByteArray(Charsets.UTF_8)
            System.arraycopy(messageIDBytes, 0, payload, 1, messageIDBytes.size)

            val packet = BitchatPacket(
                version = 1u,
                type = MessageType.NOISE_ENCRYPTED.value,
                senderID = hexStringToByteArray(senderPeerID),
                recipientID = null, // No recipient for geohash DMs
                timestamp = System.currentTimeMillis().toULong(),
                payload = payload,
                signature = null,
                ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS
            )

            val data = packet.toBinaryData() ?: return null
            return "bitchat1:" + base64URLEncode(data)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encode ACK for Nostr (no recipient): ${e.message}")
            return null
        }
    }

    /**
     * Build a `bitchat1:` payload without an embedded recipient peer ID (used for geohash DMs).
     */
    fun encodePMForNostrNoRecipient(
        content: String,
        messageID: String,
        senderPeerID: String
    ): String? {
        try {
            val pm = PrivateMessagePacket(messageID = messageID, content = content)
            val tlv = pm.encode() ?: return null

            val payload = ByteArray(1 + tlv.size)
            payload[0] = NoisePayloadType.PRIVATE_MESSAGE.value.toByte()
            System.arraycopy(tlv, 0, payload, 1, tlv.size)

            val packet = BitchatPacket(
                version = 1u,
                type = MessageType.NOISE_ENCRYPTED.value,
                senderID = hexStringToByteArray(senderPeerID),
                recipientID = null, // No recipient for geohash DMs
                timestamp = System.currentTimeMillis().toULong(),
                payload = payload,
                signature = null,
                ttl = com.bitchat.android.util.AppConstants.MESSAGE_TTL_HOPS
            )

            val data = packet.toBinaryData() ?: return null
            return "bitchat1:" + base64URLEncode(data)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to encode PM for Nostr (no recipient): ${e.message}")
            return null
        }
    }

    /**
     * Normalize recipient peer ID (matches iOS implementation)
     */
    private fun normalizeRecipientPeerID(recipientPeerID: String): String {
        val clean = recipientPeerID.trim().lowercase()
        return when {
            ContactIdentityResolver.isNoiseKeyHex(clean) ->
                ContactIdentityResolver.peerIdForNoiseKeyHex(clean) ?: clean
            ContactIdentityResolver.isMeshPeerId(clean) -> clean
            else -> recipientPeerID
        }
    }

    /**
     * Base64url encode without padding (matches iOS implementation)
     */
    private fun base64URLEncode(data: ByteArray): String {
        val b64 = Base64.encodeToString(data, Base64.NO_WRAP)
        return b64
            .replace("+", "-")
            .replace("/", "_")
            .replace("=", "")
    }

    /**
     * Convert hex string to byte array
     */
    private fun hexStringToByteArray(hexString: String): ByteArray =
        MeshPacketUtils.hexStringToByteArray(hexString)
}

package com.bitchat.android.nostr

import com.google.gson.Gson
import com.google.gson.GsonBuilder
import com.google.gson.annotations.SerializedName
import java.security.MessageDigest

/**
 * Nostr Event structure following NIP-01
 * Compatible with iOS implementation
 */
data class NostrEvent(
    var id: String = "",
    val pubkey: String,
    @SerializedName("created_at") val createdAt: Int,
    val kind: Int,
    val tags: List<List<String>>,
    val content: String,
    var sig: String? = null
) {

    companion object {
        /**
         * Create from JSON dictionary
         */
        fun fromJson(json: Map<String, Any>): NostrEvent? {
            return try {
                NostrEvent(
                    id = json["id"] as? String ?: "",
                    pubkey = json["pubkey"] as? String ?: return null,
                    createdAt = (json["created_at"] as? Number)?.toInt() ?: return null,
                    kind = (json["kind"] as? Number)?.toInt() ?: return null,
                    tags = (json["tags"] as? List<List<String>>) ?: return null,
                    content = json["content"] as? String ?: return null,
                    sig = json["sig"] as? String?
                )
            } catch (e: Exception) {
                null
            }
        }

        /**
         * Create from JSON string
         */
        fun fromJsonString(jsonString: String): NostrEvent? {
            return try {
                val gson = Gson()
                gson.fromJson(jsonString, NostrEvent::class.java)
            } catch (e: Exception) {
                null
            }
        }

        /**
         * Create a new text note event
         */
        fun createTextNote(
            content: String,
            publicKeyHex: String,
            privateKeyHex: String,
            tags: List<List<String>> = emptyList(),
            createdAt: Int = (System.currentTimeMillis() / 1000).toInt()
        ): NostrEvent {
            val event = NostrEvent(
                pubkey = publicKeyHex,
                createdAt = createdAt,
                kind = NostrKind.TEXT_NOTE,
                tags = tags,
                content = content
            )
            return event.sign(privateKeyHex)
        }

        /**
         * Create a new metadata event (kind 0)
         */
        fun createMetadata(
            metadata: String,
            publicKeyHex: String,
            privateKeyHex: String,
            createdAt: Int = (System.currentTimeMillis() / 1000).toInt()
        ): NostrEvent {
            val event = NostrEvent(
                pubkey = publicKeyHex,
                createdAt = createdAt,
                kind = NostrKind.METADATA,
                tags = emptyList(),
                content = metadata
            )
            return event.sign(privateKeyHex)
        }
    }

    /**
     * Sign event with secp256k1 private key
     * Returns signed event with id and signature set
     */
    fun sign(privateKeyHex: String): NostrEvent {
        val (eventId, eventIdHash) = calculateEventId()

        // Create signature using secp256k1
        val signature = signHash(eventIdHash, privateKeyHex)

        return this.copy(
            id = eventId,
            sig = signature
        )
    }

    /**
     * Compute event ID (NIP-01) without signing
     */
    fun computeEventIdHex(): String {
        val (eventId, _) = calculateEventId()
        return eventId
    }

    /**
     * Calculate event ID according to NIP-01
     * Returns (hex_id, hash_bytes)
     */
    private fun calculateEventId(): Pair<String, ByteArray> {
        // Create serialized array for hashing according to NIP-01
        val serialized = listOf(
            0,
            pubkey,
            createdAt,
            kind,
            tags,
            content
        )

        // Convert to JSON without escaping slashes (compact format)
        val gson = GsonBuilder().disableHtmlEscaping().create()
        val jsonString = gson.toJson(serialized)

        // SHA256 hash of the JSON string
        val digest = MessageDigest.getInstance("SHA-256")
        val jsonBytes = jsonString.toByteArray(Charsets.UTF_8)
        val hash = digest.digest(jsonBytes)

        // Convert to hex
        val hexId = hash.joinToString("") { "%02x".format(it) }

        return Pair(hexId, hash)
    }

    /**
     * Sign hash using BIP-340 Schnorr signatures
     */
    private fun signHash(hash: ByteArray, privateKeyHex: String): String {
        return try {
            // Use the real BIP-340 Schnorr signature from NostrCrypto
            NostrCrypto.schnorrSign(hash, privateKeyHex)
        } catch (e: Exception) {
            throw RuntimeException("Failed to sign event: ${e.message}", e)
        }
    }

    /**
     * Convert to JSON string
     */
    fun toJsonString(): String {
        val gson = Gson()
        return gson.toJson(this)
    }

    /**
     * Validate event signature using BIP-340 Schnorr verification
     */
    fun isValidSignature(): Boolean {
        return try {
            val signatureHex = sig ?: return false
            if (id.isEmpty() || pubkey.isEmpty()) return false

            // Recalculate the event ID hash for verification
            val (calculatedId, messageHash) = calculateEventId()

            // Check if the calculated ID matches the stored ID
            if (calculatedId != id) return false

            // Verify the Schnorr signature
            NostrCrypto.schnorrVerify(messageHash, signatureHex, pubkey)
        } catch (e: Exception) {
            false
        }
    }

    /**
     * Validate event structure and signature
     */
    fun isValid(): Boolean {
        return try {
            // Basic field validation
            if (pubkey.isEmpty() || content.isEmpty()) return false
            if (createdAt <= 0 || kind < 0) return false
            if (!NostrCrypto.isValidPublicKey(pubkey)) return false

            // Signature validation
            isValidSignature()
        } catch (e: Exception) {
            false
        }
    }
}

/**
 * Nostr event kinds
 */
object NostrKind {
    const val METADATA = 0
    const val TEXT_NOTE = 1
    const val DIRECT_MESSAGE = 14     // NIP-17 direct message (unsigned)
    const val FILE_MESSAGE = 15       // NIP-17 file message (unsigned)
    const val SEAL = 13              // NIP-17 sealed event
    const val GIFT_WRAP = 1059       // NIP-17 gift wrap
    const val EPHEMERAL_EVENT = 20000 // For geohash channels
    const val GEOHASH_PRESENCE = 20001 // For geohash presence heartbeat
}

/**
 * Extension functions for hex encoding/decoding
 */
fun String.hexToByteArray(): ByteArray {
    check(length % 2 == 0) { "Must have an even length" }
    return chunked(2)
        .map { it.toInt(16).toByte() }
        .toByteArray()
}

fun ByteArray.toHexString(): String = joinToString("") { "%02x".format(it) }

package com.bitchat.android.nostr

import android.util.Log
import java.util.concurrent.ConcurrentHashMap

/**
 * Efficient LRU-based Nostr event deduplication system
 * 
 * This class provides thread-safe deduplication of Nostr events based on their event IDs.
 * It maintains an LRU cache of up to 10,000 event IDs to prevent memory bloat while ensuring
 * duplicate events (which commonly arrive via different relays) are processed only once.
 * 
 * Features:
 * - Thread-safe concurrent access
 * - LRU eviction when capacity is exceeded
 * - Configurable capacity (default 10,000)
 * - Efficient O(1) lookup and insertion
 * - Memory-bounded to prevent unbounded growth
 */
class NostrEventDeduplicator(
    private val maxCapacity: Int = DEFAULT_CAPACITY
) {
    companion object {
        private const val TAG = "NostrDeduplicator"
        private const val DEFAULT_CAPACITY = com.bitchat.android.util.AppConstants.Nostr.DEFAULT_DEDUP_CAPACITY

        @Volatile
        private var INSTANCE: NostrEventDeduplicator? = null

        /**
         * Get the singleton instance of the deduplicator
         */
        fun getInstance(): NostrEventDeduplicator {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: NostrEventDeduplicator().also { INSTANCE = it }
            }
        }
    }

    /**
     * Node for the doubly-linked list used in LRU implementation
     */
    private data class LRUNode(
        val eventId: String,
        var prev: LRUNode? = null,
        var next: LRUNode? = null
    )

    // Hash map for O(1) lookup - maps event ID to node
    private val nodeMap = ConcurrentHashMap<String, LRUNode>()

    // Doubly-linked list for LRU ordering
    private val head = LRUNode("HEAD") // Dummy head node
    private val tail = LRUNode("TAIL") // Dummy tail node

    // Lock for thread-safe LRU operations
    private val lruLock = Any()

    // Statistics
    @Volatile
    private var totalChecks = 0L
    @Volatile
    private var duplicateCount = 0L
    @Volatile
    private var evictionCount = 0L

    init {
        // Initialize the doubly-linked list
        head.next = tail
        tail.prev = head

        Log.d(TAG, "Initialized NostrEventDeduplicator with capacity: $maxCapacity")
    }

    /**
     * Check if an event has been seen before and mark it as seen
     * 
     * @param eventId The Nostr event ID to check
     * @return true if the event is a duplicate (already seen), false if it's new
     */
    fun isDuplicate(eventId: String): Boolean {
        totalChecks++

        synchronized(lruLock) {
            val existingNode = nodeMap[eventId]

            if (existingNode != null) {
                // Event is a duplicate - move to front (most recently used)
                moveToFront(existingNode)
                duplicateCount++

                if (duplicateCount % 100 == 0L) {
                    Log.v(TAG, "Duplicate event detected: $eventId (${duplicateCount} total duplicates)")
                }

                return true
            } else {
                // New event - add to front
                addToFront(eventId)

                // Check if we need to evict oldest entries
                if (nodeMap.size > maxCapacity) {
                    evictOldest()
                }

                return false
            }
        }
    }

    /**
     * Process a Nostr event with deduplication
     * 
     * @param event The Nostr event to process
     * @param processor Function to call if the event is not a duplicate
     * @return true if the event was processed (not a duplicate), false if it was deduplicated
     */
    fun processEvent(event: NostrEvent, processor: (NostrEvent) -> Unit): Boolean {
        return if (!isDuplicate(event.id)) {
            processor(event)
            true
        } else {
            false
        }
    }

    /**
     * Get current statistics about the deduplicator
     */
    fun getStats(): DeduplicationStats {
        synchronized(lruLock) {
            return DeduplicationStats(
                capacity = maxCapacity,
                currentSize = nodeMap.size,
                totalChecks = totalChecks,
                duplicateCount = duplicateCount,
                evictionCount = evictionCount,
                hitRate = if (totalChecks > 0) (duplicateCount.toDouble() / totalChecks.toDouble()) else 0.0
            )
        }
    }

    /**
     * Clear all cached event IDs (useful for testing or resetting state)
     */
    fun clear() {
        synchronized(lruLock) {
            nodeMap.clear()
            head.next = tail
            tail.prev = head

            // Reset statistics
            totalChecks = 0L
            duplicateCount = 0L
            evictionCount = 0L

            Log.d(TAG, "Cleared all cached event IDs")
        }
    }

    /**
     * Check if the deduplicator contains a specific event ID
     */
    fun contains(eventId: String): Boolean {
        return nodeMap.containsKey(eventId)
    }

    /**
     * Get the current size of the cache
     */
    fun size(): Int = nodeMap.size

    // MARK: - Private LRU Implementation Methods

    /**
     * Add a new event ID to the front of the LRU list
     */
    private fun addToFront(eventId: String) {
        val newNode = LRUNode(eventId)
        nodeMap[eventId] = newNode

        // Insert after head
        newNode.next = head.next
        newNode.prev = head
        head.next?.prev = newNode
        head.next = newNode
    }

    /**
     * Move an existing node to the front (most recently used position)
     */
    private fun moveToFront(node: LRUNode) {
        // Remove from current position
        node.prev?.next = node.next
        node.next?.prev = node.prev

        // Insert at front
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    /**
     * Remove and return the least recently used node (at the tail)
     */
    private fun removeTail(): LRUNode? {
        val lastNode = tail.prev
        if (lastNode == head) {
            return null // Empty list
        }

        // Remove from linked list
        lastNode?.prev?.next = tail
        tail.prev = lastNode?.prev

        // Remove from hash map
        if (lastNode != null) {
            nodeMap.remove(lastNode.eventId)
        }

        return lastNode
    }

    /**
     * Evict the oldest (least recently used) entries when capacity is exceeded
     */
    private fun evictOldest() {
        while (nodeMap.size > maxCapacity) {
            val evictedNode = removeTail()
            if (evictedNode != null) {
                evictionCount++

                if (evictionCount % 500 == 0L) {
                    Log.v(TAG, "Evicted event ID: ${evictedNode.eventId} (${evictionCount} total evictions)")
                }
            } else {
                break // Should not happen, but safety check
            }
        }
    }
}

/**
 * Statistics about the deduplication system
 */
data class DeduplicationStats(
    val capacity: Int,
    val currentSize: Int,
    val totalChecks: Long,
    val duplicateCount: Long,
    val evictionCount: Long,
    val hitRate: Double
) {
    override fun toString(): String {
        return "DeduplicationStats(capacity=$capacity, size=$currentSize, " +
               "checks=$totalChecks, duplicates=$duplicateCount, evictions=$evictionCount, " +
               "hitRate=${"%.2f".format(hitRate * 100)}%)"
    }
}

package com.bitchat.android.nostr

import com.google.gson.*
import com.google.gson.annotations.SerializedName
import java.lang.reflect.Type

/**
 * Nostr event filter for subscriptions
 * Compatible with iOS implementation
 */
data class NostrFilter(
    val ids: List<String>? = null,
    val authors: List<String>? = null,
    val kinds: List<Int>? = null,
    val since: Int? = null,
    val until: Int? = null,
    val limit: Int? = null,
    private val tagFilters: Map<String, List<String>>? = null
) {

    companion object {
        /**
         * Create filter for NIP-17 gift wraps
         */
        fun giftWrapsFor(pubkey: String, since: Long? = null): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.GIFT_WRAP),
                since = since?.let { (it / 1000).toInt() },
                tagFilters = mapOf("p" to listOf(pubkey)),
                limit = 100
            )
        }

        /**
         * Create filter for geohash-scoped ephemeral events (kind 20000 and 20001)
         */
        fun geohashEphemeral(geohash: String, since: Long? = null, limit: Int = 1000): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.EPHEMERAL_EVENT, NostrKind.GEOHASH_PRESENCE),
                since = since?.let { (it / 1000).toInt() },
                tagFilters = mapOf("g" to listOf(geohash)),
                limit = limit
            )
        }

        /**
         * Create filter for geohash-scoped chat messages only (kind 20000).
         * Low-volume; kept subscribed in the background so messages keep arriving.
         */
        fun geohashMessages(geohash: String, since: Long? = null, limit: Int = 1000): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.EPHEMERAL_EVENT),
                since = since?.let { (it / 1000).toInt() },
                tagFilters = mapOf("g" to listOf(geohash)),
                limit = limit
            )
        }

        /**
         * Create filter for geohash-scoped presence heartbeats only (kind 20001).
         * High-volume firehose (every participant rebroadcasts ~every 60s); only used
         * to refresh the participant list, so it is paused while backgrounded.
         */
        fun geohashPresence(geohash: String, since: Long? = null, limit: Int = 1000): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.GEOHASH_PRESENCE),
                since = since?.let { (it / 1000).toInt() },
                tagFilters = mapOf("g" to listOf(geohash)),
                limit = limit
            )
        }

        /**
         * Create filter for text notes from specific authors
         */
        fun textNotesFrom(authors: List<String>, since: Long? = null, limit: Int = 50): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.TEXT_NOTE),
                authors = authors,
                since = since?.let { (it / 1000).toInt() },
                limit = limit
            )
        }

        /**
         * Create filter for geohash-scoped text notes (kind=1 with g tag)
         */
        fun geohashNotes(geohash: String, since: Long? = null, limit: Int = 200): NostrFilter {
            return NostrFilter(
                kinds = listOf(NostrKind.TEXT_NOTE),
                since = since?.let { (it / 1000).toInt() },
                tagFilters = mapOf("g" to listOf(geohash)),
                limit = limit
            )
        }

        /**
         * Create filter for specific event IDs
         */
        fun forEvents(ids: List<String>): NostrFilter {
            return NostrFilter(ids = ids)
        }
    }

    /**
     * Custom JSON serializer to handle tag filters properly
     */
    class FilterSerializer : JsonSerializer<NostrFilter> {
        override fun serialize(src: NostrFilter, typeOfSrc: Type, context: JsonSerializationContext): JsonElement {
            val jsonObject = JsonObject()

            // Standard fields
            src.ids?.let { jsonObject.add("ids", context.serialize(it)) }
            src.authors?.let { jsonObject.add("authors", context.serialize(it)) }
            src.kinds?.let { jsonObject.add("kinds", context.serialize(it)) }
            src.since?.let { jsonObject.addProperty("since", it) }
            src.until?.let { jsonObject.addProperty("until", it) }
            src.limit?.let { jsonObject.addProperty("limit", it) }

            // Tag filters with # prefix
            src.tagFilters?.forEach { (tag, values) ->
                jsonObject.add("#$tag", context.serialize(values))
            }

            return jsonObject
        }
    }

    /**
     * Create builder for complex filters
     */
    class Builder {
        private var ids: List<String>? = null
        private var authors: List<String>? = null
        private var kinds: List<Int>? = null
        private var since: Int? = null
        private var until: Int? = null
        private var limit: Int? = null
        private val tagFilters = mutableMapOf<String, List<String>>()

        fun ids(vararg ids: String) = apply { this.ids = ids.toList() }
        fun authors(vararg authors: String) = apply { this.authors = authors.toList() }
        fun kinds(vararg kinds: Int) = apply { this.kinds = kinds.toList() }
        fun since(timestamp: Long) = apply { this.since = (timestamp / 1000).toInt() }
        fun until(timestamp: Long) = apply { this.until = (timestamp / 1000).toInt() }
        fun limit(count: Int) = apply { this.limit = count }

        fun tagP(vararg pubkeys: String) = apply { tagFilters["p"] = pubkeys.toList() }
        fun tagE(vararg eventIds: String) = apply { tagFilters["e"] = eventIds.toList() }
        fun tagG(vararg geohashes: String) = apply { tagFilters["g"] = geohashes.toList() }
        fun tag(name: String, vararg values: String) = apply { tagFilters[name] = values.toList() }

        fun build(): NostrFilter {
            return NostrFilter(
                ids = ids,
                authors = authors,
                kinds = kinds,
                since = since,
                until = until,
                limit = limit,
                tagFilters = tagFilters.toMap()
            )
        }
    }

    /**
     * Check if this filter matches an event
     */
    fun matches(event: NostrEvent): Boolean {
        // Check IDs
        if (ids != null && !ids.contains(event.id)) {
            return false
        }

        // Check authors
        if (authors != null && !authors.contains(event.pubkey)) {
            return false
        }

        // Check kinds
        if (kinds != null && !kinds.contains(event.kind)) {
            return false
        }

        // Check time bounds
        if (since != null && event.createdAt < since) {
            return false
        }

        if (until != null && event.createdAt > until) {
            return false
        }

        // Check tag filters
        if (tagFilters != null) {
            for ((tagName, requiredValues) in tagFilters) {
                val eventTags = event.tags.filter { it.isNotEmpty() && it[0] == tagName }
                val eventValues = eventTags.mapNotNull { tag ->
                    if (tag.size > 1) tag[1] else null
                }

                val hasMatch = requiredValues.any { requiredValue ->
                    eventValues.contains(requiredValue)
                }

                if (!hasMatch) {
                    return false
                }
            }
        }

        return true
    }

    /**
     * Get debug description
     */
    fun getDebugDescription(): String {
        val parts = mutableListOf<String>()

        ids?.let { parts.add("ids=${it.size}") }
        authors?.let { parts.add("authors=${it.size}") }
        kinds?.let { parts.add("kinds=$it") }
        since?.let { parts.add("since=$it") }
        until?.let { parts.add("until=$it") }
        limit?.let { parts.add("limit=$it") }
        tagFilters?.let { filters ->
            filters.forEach { (tag, values) ->
                parts.add("#$tag=${values.size}")
            }
        }

        return "NostrFilter(${parts.joinToString(", ")})"
    }

    /**
     * Get geohash value from g tag filter (if present)
     * Returns the first geohash in the filter or null if none
     */
    fun getGeohash(): String? {
        return tagFilters?.get("g")?.firstOrNull()
    }
}

package com.bitchat.android.nostr

import android.content.Context
import android.util.Log
import com.bitchat.android.favorites.FavoritesPersistenceService
import com.bitchat.android.identity.SecureIdentityStateManager
import java.security.MessageDigest
import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap

/**
 * Manages Nostr identity (secp256k1 keypair) for NIP-17 private messaging
 * Compatible with iOS implementation
 */
data class NostrIdentity(
    val privateKeyHex: String,
    val publicKeyHex: String,
    val npub: String,
    val createdAt: Long
) {

    companion object {
        private const val TAG = "NostrIdentity"

        /**
         * Generate a new Nostr identity
         */
        fun generate(): NostrIdentity {
            val (privateKeyHex, publicKeyHex) = NostrCrypto.generateKeyPair()
            val npub = Bech32.encode("npub", publicKeyHex.hexToByteArrayLocal())

            Log.d(TAG, "Generated new Nostr identity: npub=$npub")

            return NostrIdentity(
                privateKeyHex = privateKeyHex,
                publicKeyHex = publicKeyHex,
                npub = npub,
                createdAt = System.currentTimeMillis()
            )
        }

        /**
         * Create from existing private key
         */
        fun fromPrivateKey(privateKeyHex: String): NostrIdentity {
            require(NostrCrypto.isValidPrivateKey(privateKeyHex)) { 
                "Invalid private key" 
            }

            val publicKeyHex = NostrCrypto.derivePublicKey(privateKeyHex)
            val npub = Bech32.encode("npub", publicKeyHex.hexToByteArrayLocal())

            return NostrIdentity(
                privateKeyHex = privateKeyHex,
                publicKeyHex = publicKeyHex,
                npub = npub,
                createdAt = System.currentTimeMillis()
            )
        }

        /**
         * Create from a deterministic seed (for demo purposes)
         */
        fun fromSeed(seed: String): NostrIdentity {
            // Hash the seed to create a private key
            val digest = MessageDigest.getInstance("SHA-256")
            val seedBytes = seed.toByteArray(Charsets.UTF_8)
            val privateKeyBytes = digest.digest(seedBytes)
            val privateKeyHex = privateKeyBytes.joinToString("") { "%02x".format(it) }

            return fromPrivateKey(privateKeyHex)
        }
    }

    /**
     * Sign a Nostr event
     */
    fun signEvent(event: NostrEvent): NostrEvent {
        return event.sign(privateKeyHex)
    }

    /**
     * Get short display format
     */
    fun getShortNpub(): String {
        return if (npub.length > 16) {
            "${npub.take(8)}...${npub.takeLast(8)}"
        } else {
            npub
        }
    }
}

/**
 * Bridge between Noise and Nostr identities
 * Manages persistent storage and per-geohash identity derivation
 */
object NostrIdentityBridge {
    private const val TAG = "NostrIdentityBridge"
    private const val NOSTR_PRIVATE_KEY = "nostr_private_key"
    private const val DEVICE_SEED_KEY = "nostr_device_seed"

    // Cache for derived geohash identities to avoid repeated crypto operations
    private val geohashIdentityCache = ConcurrentHashMap<String, NostrIdentity>()

    /**
     * Get or create the current Nostr identity
     */
    fun getCurrentNostrIdentity(context: Context): NostrIdentity? {
        val stateManager = SecureIdentityStateManager(context)

        // Try to load existing Nostr private key
        val existingKey = loadNostrPrivateKey(stateManager)
        if (existingKey != null) {
            return try {
                NostrIdentity.fromPrivateKey(existingKey)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to create identity from stored key: ${e.message}")
                null
            }
        }

        // Generate new identity
        val newIdentity = NostrIdentity.generate()
        saveNostrPrivateKey(stateManager, newIdentity.privateKeyHex)

        Log.i(TAG, "Created new Nostr identity: ${newIdentity.getShortNpub()}")
        return newIdentity
    }

    /**
     * Derive a deterministic, unlinkable Nostr identity for a given geohash
     * Uses HMAC-SHA256(deviceSeed, geohash) as private key material with fallback rehashing
     * if the candidate is not a valid secp256k1 private key.
     * 
     * Cached for UI responsiveness.
     */
    fun deriveIdentity(forGeohash: String, context: Context): NostrIdentity {
        // Check cache first for immediate response
        geohashIdentityCache[forGeohash]?.let { cachedIdentity ->
            //Log.v(TAG, "Using cached geohash identity for $forGeohash")
            return cachedIdentity
        }

        val stateManager = SecureIdentityStateManager(context)
        val seed = getOrCreateDeviceSeed(stateManager)

        val geohashBytes = forGeohash.toByteArray(Charsets.UTF_8)

        // Try a few iterations to ensure a valid key can be formed (exactly like iOS)
        for (i in 0 until 10) {
            val candidateKey = candidateKey(seed, geohashBytes, i.toUInt())
            val candidateKeyHex = candidateKey.toHexStringLocal()

            if (NostrCrypto.isValidPrivateKey(candidateKeyHex)) {
                val identity = NostrIdentity.fromPrivateKey(candidateKeyHex)

                // Cache the result for future UI responsiveness
                geohashIdentityCache[forGeohash] = identity

                Log.d(TAG, "Derived geohash identity")
                return identity
            }
        }

        // As a final fallback, hash the seed+msg and try again (exactly like iOS)
        val combined = seed + geohashBytes
        val digest = MessageDigest.getInstance("SHA-256")
        val fallbackKey = digest.digest(combined)

        val fallbackIdentity = NostrIdentity.fromPrivateKey(fallbackKey.toHexStringLocal())

        // Cache the fallback result too
        geohashIdentityCache[forGeohash] = fallbackIdentity

        Log.d(TAG, "Used fallback geohash identity derivation")
        return fallbackIdentity
    }

    /**
     * Generate candidate key for a specific iteration (matches iOS implementation)
     */
    private fun candidateKey(seed: ByteArray, message: ByteArray, iteration: UInt): ByteArray {
        val input = message + iteration.toLittleEndianBytes()
        return hmacSha256(seed, input)
    }

    /**
     * Associate a Nostr identity with a Noise public key (for favorites)
     */
    fun associateNostrIdentity(nostrPubkey: String, noisePublicKey: ByteArray, context: Context) {
        FavoritesPersistenceService.initialize(context)
        FavoritesPersistenceService.shared.updateNostrPublicKey(noisePublicKey, nostrPubkey)
        Log.d(TAG, "Associated Nostr pubkey ${nostrPubkey.take(16)}... with Noise key")
    }

    /**
     * Get Nostr public key associated with a Noise public key
     */
    fun getNostrPublicKey(noisePublicKey: ByteArray, context: Context): String? {
        FavoritesPersistenceService.initialize(context)
        return FavoritesPersistenceService.shared.findNostrPubkey(noisePublicKey)
    }

    /**
     * Clear all Nostr identity data
     */
    fun clearAllAssociations(context: Context) {
        val stateManager = SecureIdentityStateManager(context)

        // Clear cache first
        geohashIdentityCache.clear()

        // Clear Nostr private key using public methods instead of reflection
        try {
            stateManager.clearSecureValues(NOSTR_PRIVATE_KEY, DEVICE_SEED_KEY)

            Log.i(TAG, "Cleared all Nostr identity data and cache")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to clear Nostr data: ${e.message}")
        }
    }

    fun clearGeohashIdentityCache(geohashes: Collection<String>) {
        geohashes.forEach(geohashIdentityCache::remove)
    }

    // MARK: - Private Methods

    private fun loadNostrPrivateKey(stateManager: SecureIdentityStateManager): String? {
        return try {
            // Use public methods instead of reflection to access the encrypted preferences
            stateManager.getSecureValue(NOSTR_PRIVATE_KEY)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to load Nostr private key: ${e.message}")
            null
        }
    }

    private fun saveNostrPrivateKey(stateManager: SecureIdentityStateManager, privateKeyHex: String) {
        try {
            // Use public methods instead of reflection to access the encrypted preferences
            stateManager.storeSecureValue(NOSTR_PRIVATE_KEY, privateKeyHex)

            Log.d(TAG, "Saved Nostr private key to secure storage")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to save Nostr private key: ${e.message}")
            throw e
        }
    }

    private fun getOrCreateDeviceSeed(stateManager: SecureIdentityStateManager): ByteArray {
        try {
            // Use public methods instead of reflection to access the encrypted preferences
            val existingSeed = stateManager.getSecureValue(DEVICE_SEED_KEY)
            if (existingSeed != null) {
                return android.util.Base64.decode(existingSeed, android.util.Base64.DEFAULT)
            }

            // Generate new seed
            val seed = ByteArray(32)
            SecureRandom().nextBytes(seed)

            val seedBase64 = android.util.Base64.encodeToString(seed, android.util.Base64.DEFAULT)
            stateManager.storeSecureValue(DEVICE_SEED_KEY, seedBase64)

            Log.d(TAG, "Generated new device seed for geohash identity derivation")
            return seed
        } catch (e: Exception) {
            Log.e(TAG, "Failed to get/create device seed: ${e.message}")
            throw e
        }
    }

    private fun hmacSha256(key: ByteArray, message: ByteArray): ByteArray {
        val mac = javax.crypto.Mac.getInstance("HmacSHA256")
        val secretKeySpec = javax.crypto.spec.SecretKeySpec(key, "HmacSHA256")
        mac.init(secretKeySpec)
        return mac.doFinal(message)
    }
}

// Extension functions for data conversion
private fun String.hexToByteArrayLocal(): ByteArray {
    return chunked(2).map { it.toInt(16).toByte() }.toByteArray()
}

private fun ByteArray.toHexStringLocal(): String {
    return joinToString("") { "%02x".format(it) }
}

private fun UInt.toLittleEndianBytes(): ByteArray {
    val bytes = ByteArray(4)
    bytes[0] = (this and 0xFFu).toByte()
    bytes[1] = ((this shr 8) and 0xFFu).toByte()
    bytes[2] = ((this shr 16) and 0xFFu).toByte()
    bytes[3] = ((this shr 24) and 0xFFu).toByte()
    return bytes
}

package com.bitchat.android.nostr

internal object NostrLiveSubscriptionPrivacy {
    fun closeTargets(
        liveSubscriptionIds: Set<String>,
        subscriptionsByRelay: Map<String, Set<String>>,
    ): Map<String, Set<String>> = buildMap {
        subscriptionsByRelay.forEach { (relayUrl, relaySubscriptionIds) ->
            val matchingIds = relaySubscriptionIds.intersect(liveSubscriptionIds)
            if (matchingIds.isNotEmpty()) put(relayUrl, matchingIds)
        }
    }
}

package com.bitchat.android.nostr

/**
 * Thread-safe bounded queue of relay deliveries awaiting a usable WebSocket.
 *
 * Queue entries have a local ID rather than using the Nostr event ID: the same signed event may be
 * intentionally published more than once with different relay sets or privacy provenance.
 */
internal class NostrPendingEventQueue(
    private val capacity: Int
) {
    init {
        require(capacity > 0)
    }

    data class Delivery(
        val queueId: Long,
        val event: NostrEvent,
        val liveLocationToken: Long?
    )

    private data class Entry(
        val queueId: Long,
        val event: NostrEvent,
        val pendingRelayUrls: MutableSet<String>,
        val liveLocationToken: Long?
    )

    private val lock = Any()
    private val entries = ArrayDeque<Entry>()
    private var nextQueueId = 1L

    fun enqueue(
        event: NostrEvent,
        relayUrls: Collection<String>,
        liveLocationToken: Long?
    ): Long? {
        val pendingRelays = relayUrls.filterTo(linkedSetOf()) { it.isNotBlank() }
        if (pendingRelays.isEmpty()) return null

        return synchronized(lock) {
            if (entries.size >= capacity) entries.removeFirst()
            val queueId = nextQueueId++
            entries.addLast(
                Entry(
                    queueId = queueId,
                    event = event,
                    pendingRelayUrls = pendingRelays,
                    liveLocationToken = liveLocationToken
                )
            )
            queueId
        }
    }

    fun pendingForRelay(relayUrl: String): List<Delivery> = synchronized(lock) {
        entries
            .asSequence()
            .filter { relayUrl in it.pendingRelayUrls }
            .map { Delivery(it.queueId, it.event, it.liveLocationToken) }
            .toList()
    }

    fun markDelivered(queueId: Long, relayUrl: String) {
        synchronized(lock) {
            val iterator = entries.iterator()
            while (iterator.hasNext()) {
                val entry = iterator.next()
                if (entry.queueId != queueId) continue
                entry.pendingRelayUrls.remove(relayUrl)
                if (entry.pendingRelayUrls.isEmpty()) iterator.remove()
                return
            }
        }
    }

    fun removeLiveLocationEvents() {
        synchronized(lock) {
            entries.removeAll { it.liveLocationToken != null }
        }
    }

    fun clear() {
        synchronized(lock) {
            entries.clear()
        }
    }

    internal fun size(): Int = synchronized(lock) { entries.size }
}

package com.bitchat.android.nostr

import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.security.MessageDigest
import kotlin.random.Random

/**
 * Nostr Proof of Work (PoW) implementation following NIP-13
 * 
 * This implements the Proof of Work system for Nostr events to provide spam deterrence.
 * The difficulty is defined as the number of leading zero bits in the event ID.
 * 
 * Reference: https://github.com/nostr-protocol/nips/blob/master/13.md
 */
object NostrProofOfWork {

    private const val TAG = "NostrProofOfWork"

    /**
     * Calculate the difficulty (number of leading zero bits) of an event ID
     * @param eventIdHex The hexadecimal event ID
     * @return The number of leading zero bits
     */
    fun calculateDifficulty(eventIdHex: String): Int {
        var count = 0

        for (i in eventIdHex.indices) {
            val nibble = eventIdHex[i].toString().toInt(16)
            if (nibble == 0) {
                count += 4
            } else {
                // Count leading zeros in the nibble
                count += when (nibble) {
                    1 -> 3  // 0001
                    2, 3 -> 2  // 001x
                    4, 5, 6, 7 -> 1  // 01xx
                    else -> 0  // 1xxx
                }
                break
            }
        }

        return count
    }

    /**
     * Validate that an event meets the minimum difficulty requirement
     * @param event The Nostr event to validate
     * @param minimumDifficulty The minimum required difficulty
     * @return true if the event meets the difficulty requirement
     */
    fun validateDifficulty(event: NostrEvent, minimumDifficulty: Int): Boolean {
        if (minimumDifficulty <= 0) return true

        // Require explicit nonce tag to recognize PoW per NIP-13 intent
        if (!hasNonce(event)) {
            Log.w(TAG, "Event ${event.id.take(16)}... missing nonce tag; treating as no PoW")
            return false
        }

        val actualDifficulty = calculateDifficulty(event.id)
        val committedDifficulty = getCommittedDifficulty(event)

        Log.d(TAG, "Validating PoW: actual=$actualDifficulty, required=$minimumDifficulty, committed=$committedDifficulty")

        // Check if actual difficulty meets requirement
        if (actualDifficulty < minimumDifficulty) {
            Log.w(TAG, "Event ${event.id.take(16)}... has insufficient difficulty: $actualDifficulty < $minimumDifficulty")
            return false
        }

        // If there's a committed difficulty, it should match or exceed the minimum
        if (committedDifficulty != null && committedDifficulty < minimumDifficulty) {
            Log.w(TAG, "Event ${event.id.take(16)}... has committed difficulty $committedDifficulty but achieved $actualDifficulty (possible spam)")
            return false
        }

        return true
    }

    /**
     * Mine a Nostr event to achieve the target difficulty
     * @param event The event to mine (will be modified with nonce tag)
     * @param targetDifficulty The target difficulty to achieve
     * @param maxIterations Maximum number of iterations before giving up (default: 1,000,000)
     * @return The mined event with nonce tag, or null if mining failed
     */
    suspend fun mineEvent(
        event: NostrEvent,
        targetDifficulty: Int,
        maxIterations: Int = 1_000_000
    ): NostrEvent? = withContext(Dispatchers.Default) {
        if (targetDifficulty <= 0) return@withContext event

        Log.d(TAG, "Starting PoW mining for difficulty $targetDifficulty...")
        val startTime = System.currentTimeMillis()

        var nonce = Random.nextLong(0, 1_000_000).toString()
        var iterations = 0

        while (iterations < maxIterations) {
            // Create a copy of the event with the nonce tag
            val eventWithNonce = addNonceTag(event, nonce, targetDifficulty)

            // Calculate the event ID
            val eventId = eventWithNonce.computeEventIdHex()
            val actualDifficulty = calculateDifficulty(eventId)

            if (actualDifficulty >= targetDifficulty) {
                val timeElapsed = System.currentTimeMillis() - startTime
                Log.i(TAG, "✅ PoW mining successful! Difficulty: $actualDifficulty, iterations: $iterations, time: ${timeElapsed}ms")

                // Return the event with the computed ID
                return@withContext eventWithNonce.copy(id = eventId)
            }

            // Increment nonce and try again
            nonce = (nonce.toLongOrNull()?.plus(1) ?: Random.nextLong()).toString()
            iterations++

            // Log progress every 100,000 iterations
            if (iterations % 100_000 == 0) {
                val timeElapsed = System.currentTimeMillis() - startTime
                Log.d(TAG, "PoW mining progress: $iterations iterations, ${timeElapsed}ms elapsed")
            }
        }

        val timeElapsed = System.currentTimeMillis() - startTime
        Log.w(TAG, "❌ PoW mining failed after $maxIterations iterations (${timeElapsed}ms)")
        return@withContext null
    }

    /**
     * Add or update the nonce tag in an event
     * @param event The original event
     * @param nonce The nonce value
     * @param targetDifficulty The target difficulty being attempted
     * @return A new event with the nonce tag added/updated
     */
    private fun addNonceTag(event: NostrEvent, nonce: String, targetDifficulty: Int): NostrEvent {
        val newTags = event.tags.toMutableList()

        // Remove existing nonce tag if present
        newTags.removeAll { tag -> tag.isNotEmpty() && tag[0] == "nonce" }

        // Add new nonce tag with format: ["nonce", nonce_value, target_difficulty]
        newTags.add(listOf("nonce", nonce, targetDifficulty.toString()))

        // Update created_at as recommended by NIP-13
        val updatedCreatedAt = (System.currentTimeMillis() / 1000).toInt()

        return event.copy(
            tags = newTags,
            createdAt = updatedCreatedAt
        )
    }

    /**
     * Get the committed difficulty from an event's nonce tag
     * @param event The event to check
     * @return The committed difficulty, or null if not present
     */
    private fun getCommittedDifficulty(event: NostrEvent): Int? {
        val nonceTag = event.tags.find { tag -> 
            tag.isNotEmpty() && tag[0] == "nonce" && tag.size >= 3 
        }

        return nonceTag?.get(2)?.toIntOrNull()
    }

    /**
     * Check if an event has a nonce tag (indicating it was mined)
     * @param event The event to check
     * @return true if the event has a nonce tag
     */
    fun hasNonce(event: NostrEvent): Boolean {
        return event.tags.any { tag -> tag.isNotEmpty() && tag[0] == "nonce" }
    }

    /**
     * Get the nonce value from an event
     * @param event The event to check
     * @return The nonce value, or null if not present
     */
    fun getNonce(event: NostrEvent): String? {
        val nonceTag = event.tags.find { tag -> 
            tag.isNotEmpty() && tag[0] == "nonce" && tag.size >= 2 
        }

        return nonceTag?.get(1)
    }

    /**
     * Estimate the computational work required for a given difficulty
     * @param difficulty The target difficulty
     * @return Estimated number of hash operations required
     */
    fun estimateWork(difficulty: Int): Long {
        return if (difficulty <= 0) 1L else 1L shl difficulty
    }

    /**
     * Get a human-readable description of the estimated mining time
     * @param difficulty The target difficulty
     * @param hashesPerSecond Estimated hashes per second (default: 100,000)
     * @return Human-readable time estimate
     */
    fun estimateMiningTime(difficulty: Int, hashesPerSecond: Int = 100_000): String {
        val estimatedHashes = estimateWork(difficulty)
        val estimatedSeconds = estimatedHashes / hashesPerSecond

        return when {
            estimatedSeconds < 1 -> "< 1 second"
            estimatedSeconds < 60 -> "${estimatedSeconds}s"
            estimatedSeconds < 3600 -> "${estimatedSeconds / 60}m ${estimatedSeconds % 60}s"
            estimatedSeconds < 86400 -> "${estimatedSeconds / 3600}h ${(estimatedSeconds % 3600) / 60}m"
            else -> "${estimatedSeconds / 86400}d ${(estimatedSeconds % 86400) / 3600}h"
        }
    }
}

package com.bitchat.android.nostr

import android.util.Log
import com.google.gson.Gson
import com.google.gson.JsonParser
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * NIP-17 Protocol Implementation for Private Direct Messages
 * Compatible with iOS implementation
 */
object NostrProtocol {

    private const val TAG = "NostrProtocol"
    private val gson = Gson()

    /**
     * Create NIP-17 private message gift-wrap (receiver copy only per iOS)
     * Returns a single gift-wrapped event ready for relay broadcast
     */
    fun createPrivateMessage(
        content: String,
        recipientPubkey: String,
        senderIdentity: NostrIdentity
    ): List<NostrEvent> {
        Log.d(TAG, "Creating private message for recipient: ${recipientPubkey.take(16)}...")

        // 1. Create the rumor (unsigned kind 14) with p-tag
        val rumorBase = NostrEvent(
            pubkey = senderIdentity.publicKeyHex,
            createdAt = (System.currentTimeMillis() / 1000).toInt(),
            kind = NostrKind.DIRECT_MESSAGE,
            tags = listOf(listOf("p", recipientPubkey)),
            content = content
        )
        val rumorId = rumorBase.computeEventIdHex()
        val rumor = rumorBase.copy(id = rumorId)

        // 2. Seal the rumor (kind 13) signed by sender, timestamp randomized up to 2 days
        val sealedEvent = createSeal(
            rumor = rumor,
            recipientPubkey = recipientPubkey,
            senderPrivateKey = senderIdentity.privateKeyHex,
            senderPublicKey = senderIdentity.publicKeyHex
        )

        // 3. Gift wrap to recipient (kind 1059)
        val giftWrapToRecipient = createGiftWrap(
            seal = sealedEvent,
            recipientPubkey = recipientPubkey
        )
        Log.d(TAG, "Created gift wrap: toRecipient=${giftWrapToRecipient.id.take(16)}...")
        return listOf(giftWrapToRecipient)
    }

    /**
     * Decrypt a received NIP-17 message
     * Returns (content, senderPubkey, timestamp) or null if decryption fails
     */
    fun decryptPrivateMessage(
        giftWrap: NostrEvent,
        recipientIdentity: NostrIdentity
    ): Triple<String, String, Int>? {
        Log.v(TAG, "Starting decryption of gift wrap: ${giftWrap.id.take(16)}...")

        return try {
            // 1. Unwrap the gift wrap
            val seal = unwrapGiftWrap(giftWrap, recipientIdentity.privateKeyHex)
                ?: run {
                    Log.w(TAG, "❌ Failed to unwrap gift wrap")
                    return null
                }

            Log.v(TAG, "Successfully unwrapped gift wrap from: ${seal.pubkey.take(16)}...")

            if (seal.kind != NostrKind.SEAL || !seal.isValidSignature()) {
                Log.w(TAG, "❌ Invalid NIP-17 seal signature")
                return null
            }

            // 2. Open the seal
            val rumor = openSeal(seal, recipientIdentity.privateKeyHex)
                ?: run {
                    Log.w(TAG, "❌ Failed to open seal")
                    return null
                }

            if (seal.pubkey != rumor.pubkey) {
                Log.w(TAG, "❌ NIP-17 seal pubkey does not match rumor pubkey")
                return null
            }

            Log.v(TAG, "Successfully opened seal")

            Triple(rumor.content, rumor.pubkey, rumor.createdAt)
        } catch (e: Exception) {
            Log.w(TAG, "Failed to decrypt private message: ${e.message}")
            null
        }
    }

    /**
     * Create a geohash-scoped text note (kind 1) with optional nickname
     * This creates a persistent text note that can be retrieved later
     */
    suspend fun createGeohashTextNote(
        content: String,
        geohash: String,
        senderIdentity: NostrIdentity,
        nickname: String? = null
    ): NostrEvent = withContext(Dispatchers.Default) {
        val tags = mutableListOf<List<String>>()
        tags.add(listOf("g", geohash))

        if (!nickname.isNullOrEmpty()) {
            tags.add(listOf("n", nickname))
        }

        val event = NostrEvent(
            pubkey = senderIdentity.publicKeyHex,
            createdAt = (System.currentTimeMillis() / 1000).toInt(),
            kind = NostrKind.TEXT_NOTE,
            tags = tags,
            content = content
        )

        return@withContext senderIdentity.signEvent(event)
    }

    /**
     * Create a geohash-scoped presence event (kind 20001)
     * Has no content and no nickname, used for participant counting
     */
    suspend fun createGeohashPresenceEvent(
        geohash: String,
        senderIdentity: NostrIdentity
    ): NostrEvent = withContext(Dispatchers.Default) {
        val tags = mutableListOf<List<String>>()
        tags.add(listOf("g", geohash))

        val event = NostrEvent(
            pubkey = senderIdentity.publicKeyHex,
            createdAt = (System.currentTimeMillis() / 1000).toInt(),
            kind = NostrKind.GEOHASH_PRESENCE,
            tags = tags,
            content = ""
        )

        return@withContext senderIdentity.signEvent(event)
    }

    /**
     * Create a geohash-scoped ephemeral public message (kind 20000)
     * Includes Proof of Work mining if enabled in settings
     */
    suspend fun createEphemeralGeohashEvent(
        content: String,
        geohash: String,
        senderIdentity: NostrIdentity,
        nickname: String? = null,
        teleported: Boolean = false
    ): NostrEvent = withContext(Dispatchers.Default) {
        val tags = mutableListOf<List<String>>()
        tags.add(listOf("g", geohash))

        if (!nickname.isNullOrEmpty()) {
            tags.add(listOf("n", nickname))
        }

        if (teleported) {
            // Use tag consistent with event handlers ("t","teleport")
            tags.add(listOf("t", "teleport"))
        }

        var event = NostrEvent(
            pubkey = senderIdentity.publicKeyHex,
            createdAt = (System.currentTimeMillis() / 1000).toInt(),
            kind = NostrKind.EPHEMERAL_EVENT,
            tags = tags,
            content = content
        )

        // Check if Proof of Work is enabled
        val powSettings = PoWPreferenceManager.getCurrentSettings()
        if (powSettings.enabled && powSettings.difficulty > 0) {
            Log.d(TAG, "PoW enabled for geohash event: difficulty=${powSettings.difficulty}")

            try {
                // Start mining state for animated indicators
                PoWPreferenceManager.startMining()

                // Mine the event before signing
                val minedEvent = NostrProofOfWork.mineEvent(
                    event = event,
                    targetDifficulty = powSettings.difficulty,
                    maxIterations = 2_000_000 // Allow up to 2M iterations for reasonable mining time
                )

                if (minedEvent != null) {
                    event = minedEvent
                    val actualDifficulty = NostrProofOfWork.calculateDifficulty(event.id)
                    Log.d(TAG, "✅ PoW mining successful: target=${powSettings.difficulty}, actual=$actualDifficulty, nonce=${NostrProofOfWork.getNonce(event)}")
                } else {
                    Log.w(TAG, "❌ PoW mining failed, proceeding without PoW")
                }
            } finally {
                // Always stop mining state when done (success or failure)
                PoWPreferenceManager.stopMining()
            }
        }

        return@withContext senderIdentity.signEvent(event)
    }

    // MARK: - Private Methods

    private fun createSeal(
        rumor: NostrEvent,
        recipientPubkey: String,
        senderPrivateKey: String,
        senderPublicKey: String
    ): NostrEvent {
        val rumorJSON = gson.toJson(rumor)

        val encrypted = NostrCrypto.encryptNIP44(
            plaintext = rumorJSON,
            recipientPublicKeyHex = recipientPubkey,
            senderPrivateKeyHex = senderPrivateKey
        )

        val seal = NostrEvent(
            pubkey = senderPublicKey,
            createdAt = NostrCrypto.randomizeTimestampUpToPast(),
            kind = NostrKind.SEAL,
            tags = emptyList(),
            content = encrypted
        )

        // NIP-17 requires the seal to be signed by the sender identity key.
        return seal.sign(senderPrivateKey)
    }

    private fun createGiftWrap(
        seal: NostrEvent,
        recipientPubkey: String
    ): NostrEvent {
        val sealJSON = gson.toJson(seal)

        // Create new ephemeral key for gift wrap
        val (wrapPrivateKey, wrapPublicKey) = NostrCrypto.generateKeyPair()
        Log.v(TAG, "Creating gift wrap with ephemeral key")

        // Encrypt the seal with the new ephemeral key
        val encrypted = NostrCrypto.encryptNIP44(
            plaintext = sealJSON,
            recipientPublicKeyHex = recipientPubkey,
            senderPrivateKeyHex = wrapPrivateKey
        )

        val giftWrap = NostrEvent(
            pubkey = wrapPublicKey,
            createdAt = NostrCrypto.randomizeTimestampUpToPast(),
            kind = NostrKind.GIFT_WRAP,
            tags = listOf(listOf("p", recipientPubkey)), // Tag recipient
            content = encrypted
        )

        // Sign with the gift wrap ephemeral key
        return giftWrap.sign(wrapPrivateKey)
    }

    private fun unwrapGiftWrap(
        giftWrap: NostrEvent,
        recipientPrivateKey: String
    ): NostrEvent? {
        return try {
            val decrypted = NostrCrypto.decryptNIP44(
                ciphertext = giftWrap.content,
                senderPublicKeyHex = giftWrap.pubkey,
                recipientPrivateKeyHex = recipientPrivateKey
            )

            val jsonElement = JsonParser.parseString(decrypted)
            if (!jsonElement.isJsonObject) {
                Log.w(TAG, "Decrypted gift wrap is not a JSON object")
                return null
            }

            val jsonObject = jsonElement.asJsonObject
            val seal = NostrEvent(
                id = jsonObject.get("id")?.asString ?: "",
                pubkey = jsonObject.get("pubkey")?.asString ?: "",
                createdAt = jsonObject.get("created_at")?.asInt ?: 0,
                kind = jsonObject.get("kind")?.asInt ?: 0,
                tags = parseTagsFromJson(jsonObject.get("tags")?.asJsonArray) ?: emptyList(),
                content = jsonObject.get("content")?.asString ?: "",
                sig = jsonObject.get("sig")?.asString
            )

            Log.v(TAG, "Unwrapped seal with kind: ${seal.kind}")
            seal
        } catch (e: Exception) {
            Log.w(TAG, "Failed to unwrap gift wrap: ${e.message}")
            null
        }
    }

    private fun openSeal(
        seal: NostrEvent,
        recipientPrivateKey: String
    ): NostrEvent? {
        return try {
            val decrypted = NostrCrypto.decryptNIP44(
                ciphertext = seal.content,
                senderPublicKeyHex = seal.pubkey,
                recipientPrivateKeyHex = recipientPrivateKey
            )

            val jsonElement = JsonParser.parseString(decrypted)
            if (!jsonElement.isJsonObject) {
                Log.w(TAG, "Decrypted seal is not a JSON object")
                return null
            }

            val jsonObject = jsonElement.asJsonObject
            NostrEvent(
                id = jsonObject.get("id")?.asString ?: "",
                pubkey = jsonObject.get("pubkey")?.asString ?: "",
                createdAt = jsonObject.get("created_at")?.asInt ?: 0,
                kind = jsonObject.get("kind")?.asInt ?: 0,
                tags = parseTagsFromJson(jsonObject.get("tags")?.asJsonArray) ?: emptyList(),
                content = jsonObject.get("content")?.asString ?: "",
                sig = jsonObject.get("sig")?.asString
            )
        } catch (e: Exception) {
            Log.w(TAG, "Failed to open seal: ${e.message}")
            null
        }
    }

    private fun parseTagsFromJson(tagsArray: com.google.gson.JsonArray?): List<List<String>>? {
        if (tagsArray == null) return emptyList()

        return try {
            tagsArray.map { tagElement ->
                if (tagElement.isJsonArray) {
                    val tagArray = tagElement.asJsonArray
                    tagArray.map { it.asString }
                } else {
                    emptyList()
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse tags: ${e.message}")
            null
        }
    }
}

package com.bitchat.android.nostr

import android.util.Log
import com.bitchat.android.geohash.LiveLocationPrivacyGate
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.map
import com.google.gson.JsonParser
import kotlinx.coroutines.*
import okhttp3.*
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import kotlin.math.min
import kotlin.math.pow

/**
 * Manages WebSocket connections to Nostr relays
 * Compatible with iOS implementation with Android-specific optimizations
 */
class NostrRelayManager private constructor() {

    companion object {
        @JvmStatic
        val shared = NostrRelayManager()

        private const val TAG = "NostrRelayManager"
        private const val MAX_QUEUED_EVENTS = 500
        const val OWNER_LEGACY = "legacy"
        const val OWNER_BACKGROUND = "background"

        /**
         * Get instance for Android compatibility (context-aware calls)
         */
        fun getInstance(context: android.content.Context): NostrRelayManager {
            shared.appContext = context.applicationContext
            return shared
        }

        // Default relay list (same as iOS)
        private val DEFAULT_RELAYS = listOf(
            "wss://relay.damus.io",
            "wss://relay.primal.net",
            "wss://offchain.pub",
            "wss://nostr21.com"
        )

        // Exponential backoff configuration (same as iOS)
        private const val INITIAL_BACKOFF_INTERVAL = com.bitchat.android.util.AppConstants.Nostr.INITIAL_BACKOFF_INTERVAL_MS  // 1 second
        private const val MAX_BACKOFF_INTERVAL = com.bitchat.android.util.AppConstants.Nostr.MAX_BACKOFF_INTERVAL_MS    // 5 minutes
        private const val BACKOFF_MULTIPLIER = com.bitchat.android.util.AppConstants.Nostr.BACKOFF_MULTIPLIER
        private const val MAX_RECONNECT_ATTEMPTS = com.bitchat.android.util.AppConstants.Nostr.MAX_RECONNECT_ATTEMPTS

        // Track gift-wraps we initiated for logging
        private val pendingGiftWrapIDs = ConcurrentHashMap.newKeySet<String>()

        fun registerPendingGiftWrap(id: String) {
            pendingGiftWrapIDs.add(id)
        }

        fun defaultRelays(): List<String> = DEFAULT_RELAYS
    }

    /**
     * Relay status information
     */
    data class Relay(
        val url: String,
        var isConnected: Boolean = false,
        var lastError: Throwable? = null,
        var lastConnectedAt: Long? = null,
        var messagesSent: Int = 0,
        var messagesReceived: Int = 0,
        var reconnectAttempts: Int = 0,
        var lastDisconnectedAt: Long? = null,
        var nextReconnectTime: Long? = null
    )

    // Published state
    private val _relays = MutableStateFlow<List<Relay>>(emptyList())
    val relays: StateFlow<List<Relay>> = _relays.asStateFlow()

    private val _isConnected = MutableStateFlow<Boolean>(false)
    val isConnected: StateFlow<Boolean> = _isConnected.asStateFlow()

    // Internal state
    private val relaysList = mutableListOf<Relay>()
    private val connections = ConcurrentHashMap<String, WebSocket>()
    private val reconnectJobs = ConcurrentHashMap<String, Job>()
    private val desiredConnected = AtomicBoolean(false)
    private val subscriptions = ConcurrentHashMap<String, Set<String>>() // relay URL -> subscription IDs
    private val messageHandlers = ConcurrentHashMap<String, (NostrEvent) -> Unit>()

    // Persistent subscription tracking for robust reconnection
    private val activeSubscriptions = ConcurrentHashMap<String, SubscriptionInfo>() // subscription ID -> info

    /**
     * Information about an active subscription that needs to be maintained across reconnections
     */
    data class SubscriptionInfo(
        val id: String,
        val filter: NostrFilter,
        val handler: (NostrEvent) -> Unit,
        val targetRelayUrls: Set<String>? = null, // null means all relays
        val createdAt: Long = System.currentTimeMillis(),
        val originGeohash: String? = null,
        val owner: String = OWNER_LEGACY,
        val liveLocationToken: Long? = null
    )

    // Event deduplication system
    private val eventDeduplicator = NostrEventDeduplicator.getInstance()

    // Bounded per-relay delivery queue for reconnect reliability.
    private val messageQueue = NostrPendingEventQueue(MAX_QUEUED_EVENTS)

    // Coroutine scope for background operations
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    // Subscription validation timer
    private var subscriptionValidationJob: Job? = null
    private val powerManager: com.bitchat.android.mesh.PowerManager?
        get() = appContext?.let { com.bitchat.android.mesh.PowerManager.getInstance(it) }
    @Volatile private var appContext: android.content.Context? = null

    // OkHttp client for WebSocket connections (via provider to honor Tor)
    private val httpClient: OkHttpClient
        get() = com.bitchat.android.net.OkHttpProvider.webSocketClient()

    private val gson by lazy { NostrRequest.createGson() }

    // Per-geohash relay selection
    private val geohashToRelays = ConcurrentHashMap<String, Set<String>>() // geohash -> relay URLs
    private val liveGeohashTokens = ConcurrentHashMap<String, Long>()
    private val liveLocationRelayTokens = ConcurrentHashMap<String, Long>()
    private val nonLiveRelayUrls = ConcurrentHashMap.newKeySet<String>()
    private val liveLocationConnectionJobs = ConcurrentHashMap.newKeySet<Job>()

    // --- Public API for geohash-specific operation ---

    /**
     * Compute and connect to relays for a given geohash (nearest + optional defaults), cache the mapping.
     */
    fun ensureGeohashRelaysConnected(
        geohash: String,
        nRelays: Int = 5,
        includeDefaults: Boolean = false,
        liveLocationToken: Long? = null
    ) {
        if (!isNetworkActionAllowed(liveLocationToken)) return
        try {
            val nearest = RelayDirectory.closestRelaysForGeohash(geohash, nRelays)
            val selected = if (includeDefaults) {
                (nearest + Companion.defaultRelays()).toSet()
            } else nearest.toSet()
            if (selected.isEmpty()) {
                Log.w(TAG, "No relays selected for a geohash")
                return
            }
            runNetworkAction(liveLocationToken) {
                geohashToRelays[geohash] = selected
                if (liveLocationToken == null) {
                    liveGeohashTokens.remove(geohash)
                    nonLiveRelayUrls.addAll(selected)
                } else {
                    liveGeohashTokens[geohash] = liveLocationToken
                    selected.forEach { relayUrl ->
                        if (relayUrl !in nonLiveRelayUrls) {
                            liveLocationRelayTokens[relayUrl] = liveLocationToken
                        }
                    }
                }
                ensureConnectionsFor(selected, liveLocationToken)
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to ensure geohash relays")
        }
    }

    /**
     * Get relays mapped to a geohash (empty list if none configured).
     */
    fun getRelaysForGeohash(geohash: String): List<String> {
        return geohashToRelays[geohash]?.toList() ?: emptyList()
    }

    /**
     * Subscribe with explicit geohash routing; ensures connections exist, then targets only those relays.
     */
    fun subscribeForGeohash(
        geohash: String,
        filter: NostrFilter,
        id: String = generateSubscriptionId(),
        handler: (NostrEvent) -> Unit,
        includeDefaults: Boolean = false,
        nRelays: Int = 5,
        owner: String = OWNER_LEGACY,
        liveLocationToken: Long? = null
    ): String {
        if (!isNetworkActionAllowed(liveLocationToken)) return id
        ensureGeohashRelaysConnected(
            geohash,
            nRelays,
            includeDefaults,
            liveLocationToken
        )
        if (!isNetworkActionAllowed(liveLocationToken)) return id
        val relayUrls = getRelaysForGeohash(geohash)
        return subscribe(
            filter = filter,
            id = id,
            handler = handler,
            targetRelayUrls = relayUrls,
            owner = owner,
            liveLocationToken = liveLocationToken
        ).also { subscriptionId ->
            activeSubscriptions[subscriptionId]?.let { subscription ->
                activeSubscriptions[subscriptionId] =
                    subscription.copy(originGeohash = geohash)
            }
        }
    }

    /**
     * Send an event specifically to a geohash's relays (+ optional defaults).
     */
    fun sendEventToGeohash(
        event: NostrEvent,
        geohash: String,
        includeDefaults: Boolean = false,
        nRelays: Int = 5,
        liveLocationToken: Long? = null
    ) {
        if (!isNetworkActionAllowed(liveLocationToken)) return
        ensureGeohashRelaysConnected(
            geohash,
            nRelays,
            includeDefaults,
            liveLocationToken
        )
        if (!isNetworkActionAllowed(liveLocationToken)) return
        val relayUrls = getRelaysForGeohash(geohash)
        if (relayUrls.isEmpty()) {
            Log.w(TAG, "No target relays for geohash event; falling back to defaults")
            sendEvent(event, Companion.defaultRelays(), liveLocationToken)
            return
        }
        sendEvent(event, relayUrls, liveLocationToken)
    }

    // --- Internal helpers ---

    private fun isNetworkActionAllowed(liveLocationToken: Long?): Boolean =
        liveLocationToken == null || LiveLocationPrivacyGate.accepts(liveLocationToken)

    private fun runNetworkAction(
        liveLocationToken: Long?,
        action: () -> Unit
    ): Boolean = if (liveLocationToken == null) {
        action()
        true
    } else {
        LiveLocationPrivacyGate.runIfAllowed(liveLocationToken, action)
    }

    /**
     * Privacy teardown is allowed to bypass an already-revoked token solely to stop
     * server-side delivery. Live subscription IDs are opaque, so CLOSE carries no
     * geohash. If a CLOSE cannot be queued, fail closed by dropping that socket.
     */
    private fun closeSubscriptionsOnConnectedRelays(subscriptionIds: Set<String>) {
        if (subscriptionIds.isEmpty()) return

        val closeTargets = NostrLiveSubscriptionPrivacy.closeTargets(
            liveSubscriptionIds = subscriptionIds,
            subscriptionsByRelay = subscriptions,
        )
        closeTargets.forEach { (relayUrl, relaySubscriptionIds) ->
            val webSocket = connections[relayUrl] ?: return@forEach
            for (subscriptionId in relaySubscriptionIds) {
                val request = NostrRequest.Close(subscriptionId)
                val message = gson.toJson(request, NostrRequest::class.java)
                val closeQueued = runCatching { webSocket.send(message) }
                    .getOrDefault(false)
                if (!closeQueued) {
                    connections.remove(relayUrl, webSocket)
                    subscriptions.remove(relayUrl)
                    webSocket.cancel()
                    updateRelayStatus(
                        relayUrl,
                        isConnected = false,
                        error = IllegalStateException("Failed to close revoked subscription")
                    )
                    if (desiredConnected.get() && relayUrl in nonLiveRelayUrls) {
                        scope.launch { connectToRelay(relayUrl, liveLocationToken = null) }
                    }
                    break
                }
            }
        }
    }

    private fun revokeLiveLocationAccess() {
        liveLocationConnectionJobs.forEach(Job::cancel)
        liveLocationConnectionJobs.clear()

        val liveSubscriptionIds = activeSubscriptions.values
            .filter { it.liveLocationToken != null }
            .mapTo(mutableSetOf()) { it.id }
        closeSubscriptionsOnConnectedRelays(liveSubscriptionIds)
        liveSubscriptionIds.forEach { id ->
            activeSubscriptions.remove(id)
            messageHandlers.remove(id)
        }
        subscriptions.replaceAll { _, ids -> ids - liveSubscriptionIds }

        messageQueue.removeLiveLocationEvents()

        liveGeohashTokens.keys.forEach(geohashToRelays::remove)
        liveGeohashTokens.clear()

        val liveOnlyRelayUrls = liveLocationRelayTokens.keys
            .filterNotTo(mutableSetOf()) { it in nonLiveRelayUrls }
        liveOnlyRelayUrls.forEach { relayUrl ->
            connections.remove(relayUrl)?.cancel()
            subscriptions.remove(relayUrl)
            reconnectJobs.remove(relayUrl)?.cancel()
        }
        synchronized(relaysList) {
            relaysList.removeAll { it.url in liveOnlyRelayUrls }
        }
        liveLocationRelayTokens.clear()
        updateRelaysList()
        updateConnectionStatus()
    }

    private fun ensureConnectionsFor(
        relayUrls: Set<String>,
        liveLocationToken: Long? = null
    ) {
        if (!isNetworkActionAllowed(liveLocationToken)) return
        // Ensure relays are tracked for UI/status
        relayUrls.forEach { url ->
            if (relaysList.none { it.url == url }) {
                relaysList.add(Relay(url))
            }
        }
        updateRelaysList()

        if (!desiredConnected.get()) return
        val job = scope.launch {
            if (!desiredConnected.get() ||
                !isNetworkActionAllowed(liveLocationToken)
            ) return@launch
            relayUrls.forEach { relayUrl ->
                launch {
                    if (desiredConnected.get() &&
                        !connections.containsKey(relayUrl) &&
                        isNetworkActionAllowed(liveLocationToken)
                    ) {
                        connectToRelay(relayUrl, liveLocationToken)
                    }
                }
            }
        }
        if (liveLocationToken != null) {
            liveLocationConnectionJobs.add(job)
            job.invokeOnCompletion { liveLocationConnectionJobs.remove(job) }
        }
    }

    init {
        // Initialize with default relays - avoid static initialization order issues
        try {
            val defaultRelayUrls = listOf(
                "wss://relay.damus.io",
                "wss://relay.primal.net",
                "wss://offchain.pub",
                "wss://nostr21.com"
            )
            relaysList.addAll(defaultRelayUrls.map { Relay(it) })
            nonLiveRelayUrls.addAll(defaultRelayUrls)
            _relays.value = relaysList.toList()
            updateConnectionStatus()
            LiveLocationPrivacyGate.addRevocationListener(::revokeLiveLocationAccess)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initialize NostrRelayManager: ${e.message}", e)
            // Initialize with empty list as fallback
            _relays.value = emptyList()
            _isConnected.value = false
        }
    }

    /**
     * Connect to all configured relays
     */
    fun connect() {
        desiredConnected.set(true)
        Log.i(TAG, "Connecting to ${relaysList.size} Nostr relays")
        scope.launch {
            relaysList.forEach { relay ->
                launch {
                    val liveToken = liveLocationRelayTokens[relay.url]
                        ?.takeIf { relay.url !in nonLiveRelayUrls }
                    if (liveToken == null || LiveLocationPrivacyGate.accepts(liveToken)) {
                        connectToRelay(relay.url, liveToken)
                    }
                }
            }
        }

        // Start periodic subscription validation
        startSubscriptionValidation()
    }

    /**
     * Disconnect from all relays
     */
    fun disconnect() {
        Log.i(TAG, "Disconnecting from all Nostr relays")
        desiredConnected.set(false)

        // Stop subscription validation
        stopSubscriptionValidation()
        reconnectJobs.values.forEach(Job::cancel)
        reconnectJobs.clear()
        liveLocationConnectionJobs.forEach(Job::cancel)
        liveLocationConnectionJobs.clear()

        val sockets = connections.values.toList()
        connections.clear()
        sockets.forEach { webSocket ->
            webSocket.close(1000, "Manual disconnect")
        }

        // Preserve logical subscriptions for controlled resets, but forget per-socket state.
        subscriptions.clear()
        relaysList.forEach {
            it.isConnected = false
            it.nextReconnectTime = null
        }
        updateRelaysList()
        updateConnectionStatus()
    }

    /**
     * Send an event to specified relays (or all if none specified)
     */
    fun sendEvent(
        event: NostrEvent,
        relayUrls: List<String>? = null,
        liveLocationToken: Long? = null
    ) {
        val targetRelays = (relayUrls ?: relaysList.map { it.url })
            .filter { it.isNotBlank() }
            .distinct()
        if (targetRelays.isEmpty()) return

        val queued = runNetworkAction(liveLocationToken) {
            val queueId = messageQueue.enqueue(
                event = event,
                relayUrls = targetRelays,
                liveLocationToken = liveLocationToken
            ) ?: return@runNetworkAction
            scope.launch {
                if (!isNetworkActionAllowed(liveLocationToken)) return@launch
                targetRelays.forEach { relayUrl ->
                    val webSocket = connections[relayUrl]
                    if (webSocket != null) {
                        if (sendToRelay(event, webSocket, relayUrl, liveLocationToken)) {
                            messageQueue.markDelivered(queueId, relayUrl)
                        }
                    }
                }
            }
        }
        if (!queued) return
    }

    /**
     * Subscribe to events matching a filter
     * The subscription will be automatically re-established on reconnection
     */
    fun subscribe(
        filter: NostrFilter,
        id: String = generateSubscriptionId(),
        handler: (NostrEvent) -> Unit,
        targetRelayUrls: List<String>? = null,
        owner: String = OWNER_LEGACY,
        liveLocationToken: Long? = null
    ): String {
        val subscriptionInfo = SubscriptionInfo(
            id = id,
            filter = filter,
            handler = handler,
            targetRelayUrls = targetRelayUrls?.toSet(),
            owner = owner,
            liveLocationToken = liveLocationToken
        )

        runNetworkAction(liveLocationToken) {
            activeSubscriptions[id] = subscriptionInfo
            messageHandlers[id] = handler
            sendSubscriptionToRelays(subscriptionInfo)
        }

        return id
    }

    /**
     * Send a subscription to the appropriate relays
     */
    private fun sendSubscriptionToRelays(subscriptionInfo: SubscriptionInfo) {
        if (!isNetworkActionAllowed(subscriptionInfo.liveLocationToken)) return
        val request = NostrRequest.Subscribe(subscriptionInfo.id, listOf(subscriptionInfo.filter))
        val message = gson.toJson(request, NostrRequest::class.java)

        scope.launch {
            if (!isNetworkActionAllowed(subscriptionInfo.liveLocationToken)) return@launch
            val targetRelays = subscriptionInfo.targetRelayUrls?.toList() ?: connections.keys.toList()

            targetRelays.forEach { relayUrl ->
                val webSocket = connections[relayUrl]
                if (webSocket != null) {
                    try {
                        var success = false
                        runNetworkAction(subscriptionInfo.liveLocationToken) {
                            success = webSocket.send(message)
                            if (success) {
                                val currentSubs = subscriptions[relayUrl] ?: emptySet()
                                subscriptions[relayUrl] =
                                    currentSubs + subscriptionInfo.id
                            }
                        }
                        if (!success) {
                            Log.w(TAG, "Failed to send subscription: WebSocket send failed")
                        }
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to send subscription")
                    }
                }
            }

            if (connections.isEmpty()) {
                Log.w(TAG, "⚠️ No relay connections available for subscription, will retry on reconnection")
            }
        }
    }

    /**
     * Unsubscribe from a subscription
     */
    fun unsubscribe(id: String) {
        // Remove from persistent tracking
        val subscriptionInfo = activeSubscriptions.remove(id)
        messageHandlers.remove(id)

        if (subscriptionInfo == null) {
            return
        }

        if (subscriptionInfo.liveLocationToken != null &&
            !isNetworkActionAllowed(subscriptionInfo.liveLocationToken)
        ) {
            closeSubscriptionsOnConnectedRelays(setOf(id))
            subscriptions.replaceAll { _, ids -> ids - id }
            return
        }

        val request = NostrRequest.Close(id)
        val message = gson.toJson(request, NostrRequest::class.java)

        scope.launch {
            if (!isNetworkActionAllowed(subscriptionInfo.liveLocationToken)) {
                closeSubscriptionsOnConnectedRelays(setOf(id))
                subscriptions.replaceAll { _, ids -> ids - id }
                return@launch
            }
            connections.forEach { (relayUrl, webSocket) ->
                val currentSubs = subscriptions[relayUrl]
                if (currentSubs?.contains(id) == true) {
                    try {
                        runNetworkAction(subscriptionInfo.liveLocationToken) {
                            webSocket.send(message)
                        }
                        subscriptions[relayUrl] = currentSubs - id
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to unsubscribe from relay")
                    }
                }
            }
        }
    }

    fun unsubscribeOwner(owner: String) {
        activeSubscriptions.values
            .filter { it.owner == owner }
            .map { it.id }
            .forEach(::unsubscribe)
    }

    /**
     * Manually retry connection to a specific relay
     */
    fun retryConnection(relayUrl: String) {
        val relay = relaysList.find { it.url == relayUrl } ?: return
        desiredConnected.set(true)
        val liveToken = liveLocationRelayTokens[relayUrl]
            ?.takeIf { relayUrl !in nonLiveRelayUrls }
        if (!isNetworkActionAllowed(liveToken)) return

        // Reset reconnection attempts
        relay.reconnectAttempts = 0
        relay.nextReconnectTime = null

        // Disconnect if connected
        reconnectJobs.remove(relayUrl)?.cancel()
        connections.remove(relayUrl)?.close(1000, "Manual retry")

        // Attempt immediate reconnection
        scope.launch {
            connectToRelay(relayUrl, liveToken)
        }
    }

    /**
     * Reset all relay connections
     * This will automatically restore all subscriptions when reconnected
     */
    fun resetAllConnections() {
        val shouldReconnect = desiredConnected.get()
        disconnect()

        // Reset all relay states
        relaysList.forEach { relay ->
            relay.reconnectAttempts = 0
            relay.nextReconnectTime = null
            relay.lastError = null
        }

        // Reconnect only when connectivity was desired before the controlled reset.
        if (shouldReconnect) connect()
    }

    /**
     * Force re-establishment of all subscriptions on currently connected relays
     * Useful for ensuring subscription consistency after network issues
     */
    fun reestablishAllSubscriptions() {
        scope.launch {
            connections.forEach { (relayUrl, webSocket) ->
                restoreSubscriptionsForRelay(relayUrl, webSocket)
            }
        }
    }

    /**
     * Clear all subscription tracking, message handlers, routing caches, and queued messages.
     * Intended for panic/reset flows prior to reconnecting and re-subscribing from scratch.
     */
    fun clearAllSubscriptions() {
        try {
            // Clear persistent subscription tracking
            activeSubscriptions.clear()
            messageHandlers.clear()
            subscriptions.clear()

            // Clear routing caches (per-geohash relay selections)
            geohashToRelays.clear()

            // Clear any queued messages waiting to be sent
            messageQueue.clear()

            Log.i(TAG, "Cleared all Nostr subscriptions and routing caches")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to clear subscriptions: ${e.message}")
        }
    }

    /**
     * Clear all subscription tracking, deduplication cache, message queue, and connections for panic mode.
     */
    fun clearAllOnPanic() {
        try {
            val wasConnected = desiredConnected.get()
            clearAllSubscriptions()
            clearDeduplicationCache()
            disconnect()
            if (wasConnected) {
                desiredConnected.set(true)
            }
            Log.w(TAG, "🚨 Cleared NostrRelayManager subscriptions, cache, and connections for panic mode")
        } catch (e: Exception) {
            Log.e(TAG, "Failed to clear NostrRelayManager on panic: ${e.message}")
        }
    }

    /**
     * Get detailed status for all relays
     */
    fun getRelayStatuses(): List<Relay> {
        return relaysList.toList()
    }

    /**
     * Get event deduplication statistics
     */
    fun getDeduplicationStats(): DeduplicationStats {
        return eventDeduplicator.getStats()
    }

    /**
     * Clear the event deduplication cache (useful for testing or debugging)
     */
    fun clearDeduplicationCache() {
        eventDeduplicator.clear()
    }

    /**
     * Get the count of active subscriptions
     */
    fun getActiveSubscriptionCount(): Int {
        return activeSubscriptions.size
    }

    /**
     * Get information about all active subscriptions (for debugging)
     */
    fun getActiveSubscriptions(): Map<String, SubscriptionInfo> {
        return activeSubscriptions.toMap()
    }

    /**
     * Validate subscription consistency across all relays
     * Returns a report of any inconsistencies found
     */
    fun validateSubscriptionConsistency(): SubscriptionConsistencyReport {
        val expectedSubs = activeSubscriptions.keys
        val actualSubsByRelay = subscriptions.toMap()
        val inconsistencies = mutableListOf<String>()

        connections.keys.forEach { relayUrl ->
            val actualSubs = actualSubsByRelay[relayUrl] ?: emptySet()
            val expectedForRelay = expectedSubs.filter { subId ->
                val subInfo = activeSubscriptions[subId]
                subInfo?.targetRelayUrls == null || subInfo.targetRelayUrls.contains(relayUrl)
            }.toSet()

            val missing = expectedForRelay - actualSubs
            val extra = actualSubs - expectedForRelay

            if (missing.isNotEmpty()) {
                inconsistencies.add("Relay $relayUrl missing subscriptions: $missing")
            }
            if (extra.isNotEmpty()) {
                inconsistencies.add("Relay $relayUrl has extra subscriptions: $extra")
            }
        }

        return SubscriptionConsistencyReport(
            isConsistent = inconsistencies.isEmpty(),
            inconsistencies = inconsistencies,
            totalActiveSubscriptions = activeSubscriptions.size,
            connectedRelayCount = connections.size
        )
    }

    data class SubscriptionConsistencyReport(
        val isConsistent: Boolean,
        val inconsistencies: List<String>,
        val totalActiveSubscriptions: Int,
        val connectedRelayCount: Int
    )

    /**
     * Start periodic subscription validation to ensure robustness
     */
    private fun startSubscriptionValidation() {
        stopSubscriptionValidation() // Stop any existing validation

        subscriptionValidationJob = scope.launch {
            val manager = powerManager
            if (manager == null) {
                runSubscriptionValidationLoop(
                    com.bitchat.android.util.AppConstants.Nostr
                        .SUBSCRIPTION_VALIDATION_INTERVAL_MS
                )
                return@launch
            }

            manager.profile
                .map { it.nostr.subscriptionValidationMs }
                .distinctUntilChanged()
                .collectLatest(::runSubscriptionValidationLoop)
        }
    }

    private suspend fun runSubscriptionValidationLoop(intervalMs: Long) {
        while (currentCoroutineContext().isActive && desiredConnected.get()) {
            delay(intervalMs)
            if (!desiredConnected.get()) break
            validateAndRepairSubscriptions()
        }
    }

    private fun validateAndRepairSubscriptions() {
        try {
            val report = validateSubscriptionConsistency()
            if (report.isConsistent || report.connectedRelayCount == 0) return

            Log.w(TAG, "Nostr subscription inconsistencies detected")
            connections.forEach { (relayUrl, webSocket) ->
                val currentSubs = subscriptions[relayUrl] ?: emptySet()
                val expectedSubs = activeSubscriptions.keys.filter { subId ->
                    val subInfo = activeSubscriptions[subId]
                    subInfo?.targetRelayUrls == null ||
                        subInfo.targetRelayUrls.contains(relayUrl)
                }.toSet()

                if ((expectedSubs - currentSubs).isNotEmpty()) {
                    Log.i(TAG, "Auto-repairing missing subscriptions")
                    restoreSubscriptionsForRelay(relayUrl, webSocket)
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error during subscription validation: ${e.message}")
        }
    }

    /**
     * Stop periodic subscription validation
     */
    private fun stopSubscriptionValidation() {
        subscriptionValidationJob?.cancel()
        subscriptionValidationJob = null
    }

    // MARK: - Private Methods

    private suspend fun connectToRelay(
        urlString: String,
        liveLocationToken: Long? = null
    ) {
        if (!desiredConnected.get()) return
        val connectionToken = liveLocationToken
            ?.takeIf { urlString !in nonLiveRelayUrls }
        if (!isNetworkActionAllowed(connectionToken)) return
        // Skip if we already have a connection
        if (connections.containsKey(urlString)) {
            return
        }

        try {
            val request = Request.Builder()
                .url(urlString)
                .build()

            val started = runNetworkAction(connectionToken) {
                val webSocket = httpClient.newWebSocket(
                    request,
                    RelayWebSocketListener(urlString, connectionToken)
                )
                val existing = connections.putIfAbsent(urlString, webSocket)
                when {
                    existing != null -> webSocket.close(1000, "Duplicate connection")
                    !desiredConnected.get() -> {
                        connections.remove(urlString, webSocket)
                        webSocket.close(1000, "Connection no longer desired")
                    }
                }
            }
            if (!started) return

        } catch (e: Exception) {
            Log.e(TAG, "Failed to create WebSocket connection")
            handleConnectionCreationFailure(urlString, e, connectionToken)
        }
    }

    private fun sendToRelay(
        event: NostrEvent,
        webSocket: WebSocket,
        relayUrl: String,
        liveLocationToken: Long? = null
    ): Boolean {
        if (!isNetworkActionAllowed(liveLocationToken)) return false
        return try {
            val request = NostrRequest.Event(event)
            val message = gson.toJson(request, NostrRequest::class.java)

            var success = false
            runNetworkAction(liveLocationToken) {
                success = webSocket.send(message)
            }
            if (success) {
                // Update relay stats
                relaysList.find { it.url == relayUrl }?.let { relay ->
                    relay.messagesSent += 1
                }
                updateRelaysList()
                true
            } else {
                Log.e(TAG, "Failed to send event: WebSocket send failed")
                false
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to send event")
            false
        }
    }

    private fun handleMessage(message: String, relayUrl: String) {
        try {
            val jsonElement = JsonParser.parseString(message)
            if (!jsonElement.isJsonArray) {
                Log.w(TAG, "Received non-array message from relay")
                return
            }

            val response = NostrResponse.fromJsonArray(jsonElement.asJsonArray)

            when (response) {
                is NostrResponse.Event -> {
                    // Update relay stats
                    relaysList.find { it.url == relayUrl }?.let { relay ->
                        relay.messagesReceived += 1
                    }
                    updateRelaysList()

                    // CLIENT-SIDE FILTER ENFORCEMENT: Ensure this event matches the subscription's filter
                    val subscriptionInfo = activeSubscriptions[response.subscriptionId]
                        ?: return
                    if (!isNetworkActionAllowed(subscriptionInfo.liveLocationToken)) return
                    subscriptionInfo.let { subInfo ->
                        val matches = try { subInfo.filter.matches(response.event) } catch (e: Exception) { true }
                        if (!matches) {
                            // Do NOT call deduplicator here to allow the correct subscription to process it later
                            return
                        }
                    }

                    // DEDUPLICATION: Check if we've already processed this event
                    eventDeduplicator.processEvent(response.event) { event ->
                        // Call handler for new events only
                        val handler = messageHandlers[response.subscriptionId]
                        if (handler != null) {
                            scope.launch(Dispatchers.Main) {
                                if (isNetworkActionAllowed(subscriptionInfo.liveLocationToken)) {
                                    handler(event)
                                }
                            }
                        } else {
                            Log.w(TAG, "⚠️ No handler for Nostr subscription")
                        }
                    }

                }

                is NostrResponse.EndOfStoredEvents -> {
                    // No action needed
                }

                is NostrResponse.Ok -> {
                    val wasGiftWrap = pendingGiftWrapIDs.remove(response.eventId)
                    if (!response.accepted) {
                        val level = if (wasGiftWrap) Log.WARN else Log.ERROR
                        Log.println(level, TAG, "Event rejected by relay: ${response.message ?: "no reason"}")
                    }
                }

                is NostrResponse.Notice -> {
                    // No action needed
                }

                is NostrResponse.Unknown -> {
                    // No action needed
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to parse relay message")
        }
    }

    private fun handleDisconnection(
        relayUrl: String,
        webSocket: WebSocket,
        error: Throwable,
        liveLocationToken: Long? = null
    ) {
        // Ignore callbacks from intentionally closed or replaced sockets. They must not remove a
        // newer socket or schedule a reconnect after a controlled disconnect/privacy revocation.
        if (!connections.remove(relayUrl, webSocket)) return
        subscriptions.remove(relayUrl)
        handleCurrentDisconnection(relayUrl, error, liveLocationToken)
    }

    private fun handleConnectionCreationFailure(
        relayUrl: String,
        error: Throwable,
        liveLocationToken: Long?
    ) {
        if (!desiredConnected.get()) return
        handleCurrentDisconnection(relayUrl, error, liveLocationToken)
    }

    private fun handleCurrentDisconnection(
        relayUrl: String,
        error: Throwable,
        liveLocationToken: Long?
    ) {
        val connectionToken = liveLocationToken
            ?.takeIf { relayUrl !in nonLiveRelayUrls }

        updateRelayStatus(relayUrl, false, error)
        if (!desiredConnected.get() ||
            !isNetworkActionAllowed(connectionToken)
        ) return

        // Check if this is a DNS error
        val errorMessage = error.message?.lowercase() ?: ""
        if (errorMessage.contains("hostname could not be found") || 
            errorMessage.contains("dns") ||
            errorMessage.contains("unable to resolve host")) {

            val relay = relaysList.find { it.url == relayUrl }
            if (relay?.lastError == null) {
                Log.w(TAG, "Nostr relay DNS failure; not retrying")
            }
            return
        }

        // Implement exponential backoff for non-DNS errors
        val relay = relaysList.find { it.url == relayUrl } ?: return
        relay.reconnectAttempts++

        // Stop attempting after max attempts
        if (relay.reconnectAttempts >= MAX_RECONNECT_ATTEMPTS) {
            Log.w(TAG, "Max Nostr relay reconnection attempts reached")
            return
        }

        // Calculate backoff interval
        val backoffInterval = min(
            INITIAL_BACKOFF_INTERVAL * BACKOFF_MULTIPLIER.pow(relay.reconnectAttempts - 1.0),
            MAX_BACKOFF_INTERVAL.toDouble()
        ).toLong()

        relay.nextReconnectTime = System.currentTimeMillis() + backoffInterval

        Log.d(TAG, "Scheduling Nostr relay reconnection")

        reconnectJobs.remove(relayUrl)?.cancel()
        val reconnectJob = scope.launch {
            delay(backoffInterval)
            if (desiredConnected.get() &&
                isNetworkActionAllowed(connectionToken)
            ) {
                connectToRelay(relayUrl, connectionToken)
            }
        }
        reconnectJobs[relayUrl] = reconnectJob
        reconnectJob.invokeOnCompletion {
            reconnectJobs.remove(relayUrl, reconnectJob)
        }
    }

    private fun updateRelayStatus(url: String, isConnected: Boolean, error: Throwable? = null) {
        val relay = relaysList.find { it.url == url } ?: return

        relay.isConnected = isConnected
        relay.lastError = error

        if (isConnected) {
            relay.lastConnectedAt = System.currentTimeMillis()
            relay.reconnectAttempts = 0
            relay.nextReconnectTime = null
        } else {
            relay.lastDisconnectedAt = System.currentTimeMillis()
        }

        updateRelaysList()
        updateConnectionStatus()
    }

    private fun updateRelaysList() {
        _relays.value = relaysList.toList()
    }

    private fun updateConnectionStatus() {
        val connected = relaysList.any { it.isConnected }
        _isConnected.value = connected
    }

    private fun generateSubscriptionId(): String {
        return "sub-${UUID.randomUUID()}"
    }

    /**
     * Restore all active subscriptions for a specific relay that just reconnected
     */
    private fun restoreSubscriptionsForRelay(relayUrl: String, webSocket: WebSocket) {
        val subscriptionsToRestore = activeSubscriptions.values.filter { subscriptionInfo ->
            // Include subscription if it targets all relays or specifically targets this relay
            isNetworkActionAllowed(subscriptionInfo.liveLocationToken) &&
                (subscriptionInfo.targetRelayUrls == null ||
                    subscriptionInfo.targetRelayUrls.contains(relayUrl))
        }

        if (subscriptionsToRestore.isEmpty()) {
            return
        }

        subscriptionsToRestore.forEach { subscriptionInfo ->
            try {
                val request = NostrRequest.Subscribe(subscriptionInfo.id, listOf(subscriptionInfo.filter))
                val message = gson.toJson(request, NostrRequest::class.java)

                var success = false
                runNetworkAction(subscriptionInfo.liveLocationToken) {
                    success = webSocket.send(message)
                    if (success) {
                        val currentSubs = subscriptions[relayUrl] ?: emptySet()
                        subscriptions[relayUrl] =
                            currentSubs + subscriptionInfo.id
                    }
                }
                if (!success) {
                    Log.w(TAG, "Failed to restore subscription: WebSocket send failed")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to restore subscription")
            }
        }
    }

    /**
     * WebSocket listener for relay connections
     */
    private inner class RelayWebSocketListener(
        private val relayUrl: String,
        private val liveLocationToken: Long?
    ) : WebSocketListener() {

        override fun onOpen(webSocket: WebSocket, response: Response) {
            if (!desiredConnected.get() ||
                connections[relayUrl] !== webSocket ||
                !isNetworkActionAllowed(liveLocationToken)
            ) {
                connections.remove(relayUrl, webSocket)
                webSocket.close(1000, "Stale connection")
                return
            }
            reconnectJobs.remove(relayUrl)?.cancel()
            updateRelayStatus(relayUrl, true)

            // Restore all active subscriptions for this relay
            restoreSubscriptionsForRelay(relayUrl, webSocket)

            // Process only events still pending for this relay, outside the queue lock.
            val queuedForRelay = messageQueue.pendingForRelay(relayUrl)
                .filter { isNetworkActionAllowed(it.liveLocationToken) }
            queuedForRelay.forEach { delivery ->
                if (sendToRelay(
                        delivery.event,
                        webSocket,
                        relayUrl,
                        delivery.liveLocationToken
                    )
                ) {
                    messageQueue.markDelivered(delivery.queueId, relayUrl)
                }
            }
        }

        override fun onMessage(webSocket: WebSocket, text: String) {
            if (connections[relayUrl] !== webSocket) return
            handleMessage(text, relayUrl)
        }

        override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
            // Server-initiated close; onClosed will follow
        }

        override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
            val error = Exception("WebSocket closed: $code $reason")
            handleDisconnection(relayUrl, webSocket, error, liveLocationToken)
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            Log.e(TAG, "Nostr WebSocket failure")
            handleDisconnection(relayUrl, webSocket, t, liveLocationToken)
        }
    }
}

package com.bitchat.android.nostr

import com.google.gson.*
import java.lang.reflect.Type

/**
 * Nostr protocol request messages
 * Supports EVENT, REQ, and CLOSE message types
 */
sealed class NostrRequest {

    /**
     * EVENT message - publish an event
     */
    data class Event(val event: NostrEvent) : NostrRequest()

    /**
     * REQ message - subscribe to events
     */
    data class Subscribe(
        val subscriptionId: String,
        val filters: List<NostrFilter>
    ) : NostrRequest()

    /**
     * CLOSE message - close a subscription
     */
    data class Close(val subscriptionId: String) : NostrRequest()

    /**
     * Custom JSON serializer for NostrRequest
     */
    class RequestSerializer : JsonSerializer<NostrRequest> {
        override fun serialize(src: NostrRequest, typeOfSrc: Type, context: JsonSerializationContext): JsonElement {
            val array = JsonArray()

            when (src) {
                is Event -> {
                    array.add("EVENT")
                    array.add(context.serialize(src.event))
                }

                is Subscribe -> {
                    array.add("REQ")
                    array.add(src.subscriptionId)
                    src.filters.forEach { filter ->
                        array.add(context.serialize(filter, NostrFilter::class.java))
                    }
                }

                is Close -> {
                    array.add("CLOSE")
                    array.add(src.subscriptionId)
                }
            }

            return array
        }
    }

    companion object {
        /**
         * Create Gson instance with proper serializers
         */
        fun createGson(): Gson {
            return GsonBuilder()
                .registerTypeAdapter(NostrRequest::class.java, RequestSerializer())
                .registerTypeAdapter(NostrFilter::class.java, NostrFilter.FilterSerializer())
                .disableHtmlEscaping()
                .create()
        }

        /**
         * Serialize request to JSON string
         */
        fun toJson(request: NostrRequest): String {
            return createGson().toJson(request)
        }
    }
}

/**
 * Nostr protocol response messages
 * Handles EVENT, EOSE, OK, and NOTICE responses
 */
sealed class NostrResponse {

    /**
     * EVENT response - received event from subscription
     */
    data class Event(
        val subscriptionId: String,
        val event: NostrEvent
    ) : NostrResponse()

    /**
     * EOSE response - end of stored events
     */
    data class EndOfStoredEvents(
        val subscriptionId: String
    ) : NostrResponse()

    /**
     * OK response - event publication result
     */
    data class Ok(
        val eventId: String,
        val accepted: Boolean,
        val message: String?
    ) : NostrResponse()

    /**
     * NOTICE response - relay notice
     */
    data class Notice(
        val message: String
    ) : NostrResponse()

    /**
     * Unknown response type
     */
    data class Unknown(
        val raw: String
    ) : NostrResponse()

    companion object {
        /**
         * Parse JSON array response
         */
        fun fromJsonArray(jsonArray: JsonArray): NostrResponse {
            return try {
                when (val type = jsonArray[0].asString) {
                    "EVENT" -> {
                        if (jsonArray.size() >= 3) {
                            val subscriptionId = jsonArray[1].asString
                            val eventJson = jsonArray[2].asJsonObject
                            val event = parseEventFromJson(eventJson)
                            Event(subscriptionId, event)
                        } else {
                            Unknown(jsonArray.toString())
                        }
                    }

                    "EOSE" -> {
                        if (jsonArray.size() >= 2) {
                            val subscriptionId = jsonArray[1].asString
                            EndOfStoredEvents(subscriptionId)
                        } else {
                            Unknown(jsonArray.toString())
                        }
                    }

                    "OK" -> {
                        if (jsonArray.size() >= 3) {
                            val eventId = jsonArray[1].asString
                            val accepted = jsonArray[2].asBoolean
                            val message = if (jsonArray.size() >= 4) {
                                jsonArray[3].asString
                            } else null
                            Ok(eventId, accepted, message)
                        } else {
                            Unknown(jsonArray.toString())
                        }
                    }

                    "NOTICE" -> {
                        if (jsonArray.size() >= 2) {
                            val message = jsonArray[1].asString
                            Notice(message)
                        } else {
                            Unknown(jsonArray.toString())
                        }
                    }

                    else -> Unknown(jsonArray.toString())
                }
            } catch (e: Exception) {
                Unknown(jsonArray.toString())
            }
        }

        private fun parseEventFromJson(jsonObject: JsonObject): NostrEvent {
            return NostrEvent(
                id = jsonObject.get("id")?.asString ?: "",
                pubkey = jsonObject.get("pubkey")?.asString ?: "",
                createdAt = jsonObject.get("created_at")?.asInt ?: 0,
                kind = jsonObject.get("kind")?.asInt ?: 0,
                tags = parseTagsFromJson(jsonObject.get("tags")?.asJsonArray),
                content = jsonObject.get("content")?.asString ?: "",
                sig = jsonObject.get("sig")?.asString
            )
        }

        private fun parseTagsFromJson(tagsArray: JsonArray?): List<List<String>> {
            if (tagsArray == null) return emptyList()

            return try {
                tagsArray.map { tagElement ->
                    if (tagElement.isJsonArray) {
                        val tagArray = tagElement.asJsonArray
                        tagArray.map { it.asString }
                    } else {
                        emptyList()
                    }
                }
            } catch (e: Exception) {
                emptyList()
            }
        }
    }
}

package com.bitchat.android.nostr

import android.app.Application
import android.util.Log
import com.bitchat.android.geohash.LiveLocationPrivacyGate

/**
 * NostrSubscriptionManager
 * - Encapsulates ordered subscription lifecycle with NostrRelayManager.
 *
 * Relay-manager operations are already non-blocking and schedule network I/O on their own scope.
 * Keeping this facade synchronous prevents lifecycle cancellation from dropping unsubscribe work
 * and guarantees that a channel switch closes the old subscription before opening the new one.
 */
class NostrSubscriptionManager(
    private val application: Application,
    private val owner: String = NostrRelayManager.OWNER_LEGACY
) {
    companion object { private const val TAG = "NostrSubscriptionManager" }

    private val relayManager get() = NostrRelayManager.getInstance(application)

    fun connect() {
        runCatching { relayManager.connect() }
            .onFailure { Log.e(TAG, "connect failed: ${it.message}") }
    }

    fun disconnect() {
        runCatching { relayManager.disconnect() }
            .onFailure { Log.e(TAG, "disconnect failed: ${it.message}") }
    }

    fun subscribeGiftWraps(
        pubkey: String,
        sinceMs: Long,
        id: String,
        handler: (NostrEvent) -> Unit,
        liveLocationToken: Long? = null
    ) {
        if (!isAllowed(liveLocationToken)) return
        val filter = NostrFilter.giftWrapsFor(pubkey, sinceMs)
        relayManager.subscribe(
            filter = filter,
            id = id,
            handler = handler,
            owner = owner,
            liveLocationToken = liveLocationToken
        )
    }

    /** Subscribe to geohash chat messages only (kind 20000) — low-volume, kept alive in background. */
    fun subscribeGeohashMessages(
        geohash: String,
        sinceMs: Long,
        limit: Int,
        id: String,
        handler: (NostrEvent) -> Unit,
        liveLocationToken: Long? = null
    ) {
        if (!isAllowed(liveLocationToken)) return
        val filter = NostrFilter.geohashMessages(geohash, sinceMs, limit)
        relayManager.subscribeForGeohash(
            geohash,
            filter,
            id,
            handler,
            includeDefaults = false,
            nRelays = 5,
            owner = owner,
            liveLocationToken = liveLocationToken
        )
    }

    /** Subscribe to geohash presence heartbeats only (kind 20001) — high-volume, paused in background. */
    fun subscribeGeohashPresence(
        geohash: String,
        sinceMs: Long,
        limit: Int,
        id: String,
        handler: (NostrEvent) -> Unit,
        liveLocationToken: Long? = null
    ) {
        if (!isAllowed(liveLocationToken)) return
        val filter = NostrFilter.geohashPresence(geohash, sinceMs, limit)
        relayManager.subscribeForGeohash(
            geohash,
            filter,
            id,
            handler,
            includeDefaults = false,
            nRelays = 5,
            owner = owner,
            liveLocationToken = liveLocationToken
        )
    }

    fun unsubscribe(id: String) {
        runCatching { relayManager.unsubscribe(id) }
    }

    fun unsubscribeAllOwned() {
        runCatching { relayManager.unsubscribeOwner(owner) }
    }

    private fun isAllowed(liveLocationToken: Long?): Boolean =
        liveLocationToken == null || LiveLocationPrivacyGate.accepts(liveLocationToken)
}

package com.bitchat.android.nostr

import android.content.Context
import android.util.Log
import kotlinx.coroutines.*

/**
 * Test manager for Nostr functionality
 * Use this to verify the Nostr client works correctly
 */
class NostrTestManager(private val context: Context) {

    companion object {
        private const val TAG = "NostrTestManager"
    }

    private val testScope = CoroutineScope(Dispatchers.Main + SupervisorJob())
    private lateinit var nostrClient: NostrClient

    /**
     * Run comprehensive Nostr tests
     */
    fun runTests() {
        Log.i(TAG, "🧪 Starting Nostr functionality tests...")

        testScope.launch {
            try {
                // Test 1: Initialize client
                testClientInitialization()

                // Test 2: Test identity generation and storage
                testIdentityManagement()

                // Test 3: Test relay connections
                testRelayConnections()

                // Test 4: Test cryptography
                testCryptography()

                // Test 5: Test Bech32 encoding
                testBech32()

                // Test 6: Test message subscription (without sending)
                testMessageSubscription()

                Log.i(TAG, "✅ All Nostr tests completed successfully!")

            } catch (e: Exception) {
                Log.e(TAG, "❌ Nostr tests failed: ${e.message}", e)
            }
        }
    }

    private suspend fun testClientInitialization() {
        Log.d(TAG, "Testing client initialization...")

        nostrClient = NostrClient.getInstance(context)
        nostrClient.initialize()

        // Wait for initialization
        delay(2000)

        val isInitialized = nostrClient.isInitialized.value ?: false
        require(isInitialized) { "Client failed to initialize" }

        Log.d(TAG, "✅ Client initialization successful")
    }

    private suspend fun testIdentityManagement() {
        Log.d(TAG, "Testing identity management...")

        // Test current identity
        val identity = nostrClient.getCurrentIdentity()
        requireNotNull(identity) { "No current identity" }

        Log.d(TAG, "Current identity npub: ${identity.getShortNpub()}")
        require(identity.npub.startsWith("npub1")) { "Invalid npub format" }
        require(identity.publicKeyHex.length == 64) { "Invalid public key length" }
        require(identity.privateKeyHex.length == 64) { "Invalid private key length" }

        // Test geohash identity derivation
        val geohashIdentity = NostrIdentityBridge.deriveIdentity("u4pruydq", context)
        require(geohashIdentity.npub.startsWith("npub1")) { "Invalid geohash identity npub" }
        require(geohashIdentity.publicKeyHex != identity.publicKeyHex) { "Geohash identity should be different" }

        Log.d(TAG, "Geohash identity npub: ${geohashIdentity.getShortNpub()}")
        Log.d(TAG, "✅ Identity management test successful")
    }

    private suspend fun testRelayConnections() {
        Log.d(TAG, "Testing relay connections...")

        // Wait for potential relay connections
        delay(3000)

        val relayInfo = nostrClient.relayInfo.value ?: emptyList()
        require(relayInfo.isNotEmpty()) { "No relays configured" }

        Log.d(TAG, "Configured relays: ${relayInfo.size}")
        relayInfo.forEach { relay ->
            Log.d(TAG, "Relay: ${relay.url} - Connected: ${relay.isConnected}")
        }

        Log.d(TAG, "✅ Relay configuration test successful")
    }

    private suspend fun testCryptography() {
        Log.d(TAG, "Testing cryptography functions...")

        // Test key generation
        val (privateKey, publicKey) = NostrCrypto.generateKeyPair()
        require(privateKey.length == 64) { "Invalid private key length" }
        require(publicKey.length == 64) { "Invalid public key length" }
        require(NostrCrypto.isValidPrivateKey(privateKey)) { "Generated private key is invalid" }
        require(NostrCrypto.isValidPublicKey(publicKey)) { "Generated public key is invalid" }

        // Test key derivation
        val derivedPublic = NostrCrypto.derivePublicKey(privateKey)
        require(derivedPublic == publicKey) { "Key derivation mismatch" }

        // Test encryption/decryption
        val (recipientPrivate, recipientPublic) = NostrCrypto.generateKeyPair()
        val plaintext = "Hello, Nostr world! This is a test message."

        val encrypted = NostrCrypto.encryptNIP44(
            plaintext,
            recipientPublic,
            privateKey
        )
        require(encrypted.isNotEmpty()) { "Encryption failed" }

        val decrypted = NostrCrypto.decryptNIP44(encrypted, publicKey, recipientPrivate)
        require(decrypted == plaintext) { "Decryption failed: expected '$plaintext', got '$decrypted'" }

        Log.d(TAG, "✅ Cryptography test successful")
    }

    private suspend fun testBech32() {
        Log.d(TAG, "Testing Bech32 encoding...")

        val testData = "hello world test data for bech32".toByteArray()
        val encoded = Bech32.encode("test", testData)
        require(encoded.startsWith("test1")) { "Invalid bech32 encoding" }

        val (hrp, decoded) = Bech32.decode(encoded)
        require(hrp == "test") { "HRP mismatch" }
        require(decoded.contentEquals(testData)) { "Data mismatch after decode" }

        // Test with actual public key
        val (_, publicKey) = NostrCrypto.generateKeyPair()
        val npub = Bech32.encode("npub", publicKey.hexToByteArray())
        require(npub.startsWith("npub1")) { "Invalid npub encoding" }

        val (npubHrp, npubData) = Bech32.decode(npub)
        require(npubHrp == "npub") { "npub HRP mismatch" }
        require(npubData.toHexString() == publicKey) { "npub data mismatch" }

        Log.d(TAG, "✅ Bech32 test successful")
    }

    private suspend fun testMessageSubscription() {
        Log.d(TAG, "Testing message subscription...")

        var messageReceived = false

        // Subscribe to private messages (won't receive any in test, but tests the subscription mechanism)
        nostrClient.subscribeToPrivateMessages { content, senderNpub, timestamp ->
            Log.d(TAG, "Received test private message (${content.length} chars)")
            messageReceived = true
        }

        // Subscribe to a test geohash
        nostrClient.subscribeToGeohash("u4pru") { content, senderPubkey, nickname, timestamp ->
            Log.d(TAG, "📥 Received test geohash message from ${senderPubkey.take(16)}...: $content")
            messageReceived = true
        }

        // Wait a bit to see if any messages come through
        delay(2000)

        Log.d(TAG, "✅ Message subscription test successful (no messages expected in test)")
    }

    /**
     * Test sending a message to yourself (loopback test)
     */
    fun testLoopbackMessage() {
        testScope.launch {
            try {
                val identity = nostrClient.getCurrentIdentity()
                requireNotNull(identity) { "No identity available for loopback test" }

                Log.i(TAG, "🔄 Testing loopback private message...")

                // Send message to ourselves
                nostrClient.sendPrivateMessage(
                    content = "Test loopback message at ${System.currentTimeMillis()}",
                    recipientNpub = identity.npub,
                    onSuccess = {
                        Log.i(TAG, "✅ Loopback message sent successfully")
                    },
                    onError = { error ->
                        Log.e(TAG, "❌ Loopback message failed: $error")
                    }
                )

            } catch (e: Exception) {
                Log.e(TAG, "❌ Loopback test failed: ${e.message}", e)
            }
        }
    }

    /**
     * Test sending a geohash message
     */
    fun testGeohashMessage() {
        testScope.launch {
            try {
                Log.i(TAG, "🌍 Testing geohash message...")

                nostrClient.sendGeohashMessage(
                    content = "Test geohash message from Android at ${System.currentTimeMillis()}",
                    geohash = "u4pru",
                    nickname = "android-test",
                    onSuccess = {
                        Log.i(TAG, "✅ Geohash message sent successfully")
                    },
                    onError = { error ->
                        Log.e(TAG, "❌ Geohash message failed: $error")
                    }
                )

            } catch (e: Exception) {
                Log.e(TAG, "❌ Geohash test failed: ${e.message}", e)
            }
        }
    }

    /**
     * Get debug information about the Nostr client
     */
    fun getDebugInfo(): String {
        return buildString {
            appendLine("=== Nostr Client Debug Info ===")

            val identity = nostrClient.getCurrentIdentity()
            if (identity != null) {
                appendLine("Identity: ${identity.getShortNpub()}")
                appendLine("Public Key: ${identity.publicKeyHex.take(16)}...")
                appendLine("Created: ${java.util.Date(identity.createdAt)}")
            } else {
                appendLine("No identity loaded")
            }

            val isInitialized = nostrClient.isInitialized.value ?: false
            appendLine("Initialized: $isInitialized")

            val isConnected = nostrClient.relayConnectionStatus.value ?: false
            appendLine("Relay Connected: $isConnected")

            val relays = nostrClient.relayInfo.value ?: emptyList()
            appendLine("Relays (${relays.size}):")
            relays.forEach { relay ->
                appendLine("  ${relay.url}: ${if (relay.isConnected) "✅" else "❌"} (sent: ${relay.messagesSent}, received: ${relay.messagesReceived})")
            }
        }
    }

    /**
     * Shutdown test manager
     */
    fun shutdown() {
        testScope.cancel()
        nostrClient.shutdown()
    }
}

package com.bitchat.android.nostr

import android.content.Context
import android.util.Log
import com.bitchat.android.favorites.FavoriteControlMessage
import com.bitchat.android.model.ReadReceipt
import com.bitchat.android.model.NoisePayloadType
import com.bitchat.android.services.ContactDirectory
import com.bitchat.android.services.ContactIdentityResolver
import kotlinx.coroutines.*
import java.util.*
import java.util.concurrent.ConcurrentLinkedQueue

/**
 * Nostr transport for offline private messages and receipts.
 */
class NostrTransport(
    private val context: Context,
    var senderPeerID: String = ""
) {

    companion object {
        private const val TAG = "NostrTransport"
        private const val READ_ACK_INTERVAL = com.bitchat.android.util.AppConstants.Nostr.READ_ACK_INTERVAL_MS // ~3 per second (0.35s interval like iOS)

        @Volatile
        private var INSTANCE: NostrTransport? = null

        fun getInstance(context: Context): NostrTransport {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: NostrTransport(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    // Throttle READ receipts to avoid relay rate limits (like iOS)
    private data class QueuedRead(
        val receipt: ReadReceipt,
        val peerID: String
    )

    private val readQueue = ConcurrentLinkedQueue<QueuedRead>()
    private var isSendingReadAcks = false
    private val transportScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    // MARK: - Transport Interface Methods

    val myPeerID: String get() = senderPeerID

    fun sendPrivateMessage(
        content: String,
        to: String,
        recipientNickname: String,
        messageID: String
    ) {
        transportScope.launch {
            try {
                val recipientNostrPubkey = resolveNostrPublicKey(to)

                if (recipientNostrPubkey == null) {
                    Log.w(TAG, "No Nostr public key found for peerID: $to")
                    return@launch
                }

                val senderIdentity = NostrIdentityBridge.getCurrentNostrIdentity(context)
                if (senderIdentity == null) {
                    Log.e(TAG, "No Nostr identity available")
                    return@launch
                }

                val recipientHex = ContactIdentityResolver.nostrPubkeyHex(recipientNostrPubkey)
                if (recipientHex == null) {
                    Log.e(TAG, "NostrTransport: recipient key is not a valid Nostr pubkey")
                    return@launch
                }

                val recipientPeerIDForEmbed = try {
                    com.bitchat.android.favorites.FavoritesPersistenceService.shared
                        .findPeerIDForNostrPubkey(recipientNostrPubkey)
                } catch (_: Exception) { null }
                if (recipientPeerIDForEmbed.isNullOrBlank()) {
                    Log.e(TAG, "NostrTransport: no peerID stored for recipient npub; cannot embed PM")
                    return@launch
                }
                val embedded = NostrEmbeddedBitChat.encodePMForNostr(
                    content = content,
                    messageID = messageID,
                    recipientPeerID = recipientPeerIDForEmbed,
                    senderPeerID = senderPeerID
                )


                if (embedded == null) {
                    Log.e(TAG, "NostrTransport: failed to embed PM packet")
                    return@launch
                }

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = embedded,
                    recipientPubkey = recipientHex,
                    senderIdentity = senderIdentity
                )

                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send private message via Nostr: ${e.message}")
            }
        }
    }

    fun sendReadReceipt(receipt: ReadReceipt, to: String) {
        // Enqueue and process with throttling to avoid relay rate limits
        readQueue.offer(QueuedRead(receipt, to))
        processReadQueueIfNeeded()
    }

    private fun processReadQueueIfNeeded() {
        if (isSendingReadAcks) return
        if (readQueue.isEmpty()) return

        isSendingReadAcks = true
        sendNextReadAck()
    }

    private fun sendNextReadAck() {
        val item = readQueue.poll()
        if (item == null) {
            isSendingReadAcks = false
            return
        }

        transportScope.launch {
            try {
                val recipientNostrPubkey = resolveNostrPublicKey(item.peerID)

                if (recipientNostrPubkey == null) {
                    Log.w(TAG, "No Nostr public key found for read receipt to: ${item.peerID}")
                    scheduleNextReadAck()
                    return@launch
                }

                val senderIdentity = NostrIdentityBridge.getCurrentNostrIdentity(context)
                if (senderIdentity == null) {
                    Log.e(TAG, "No Nostr identity available for read receipt")
                    scheduleNextReadAck()
                    return@launch
                }

                val recipientHex = ContactIdentityResolver.nostrPubkeyHex(recipientNostrPubkey)
                if (recipientHex == null) {
                    scheduleNextReadAck()
                    return@launch
                }

                val ack = NostrEmbeddedBitChat.encodeAckForNostr(
                    type = NoisePayloadType.READ_RECEIPT,
                    messageID = item.receipt.originalMessageID,
                    recipientPeerID = item.peerID,
                    senderPeerID = senderPeerID
                )

                if (ack == null) {
                    Log.e(TAG, "NostrTransport: failed to embed READ ack")
                    scheduleNextReadAck()
                    return@launch
                }

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = ack,
                    recipientPubkey = recipientHex,
                    senderIdentity = senderIdentity
                )

                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

                scheduleNextReadAck()

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send read receipt via Nostr: ${e.message}")
                scheduleNextReadAck()
            }
        }
    }

    private fun scheduleNextReadAck() {
        transportScope.launch {
            delay(READ_ACK_INTERVAL)
            isSendingReadAcks = false
            processReadQueueIfNeeded()
        }
    }

    fun sendFavoriteNotification(to: String, isFavorite: Boolean) {
        transportScope.launch {
            try {
                val recipientNostrPubkey = resolveNostrPublicKey(to)

                if (recipientNostrPubkey == null) {
                    Log.w(TAG, "No Nostr public key found for favorite notification to: $to")
                    return@launch
                }

                val senderIdentity = NostrIdentityBridge.getCurrentNostrIdentity(context)
                if (senderIdentity == null) {
                    Log.e(TAG, "No Nostr identity available for favorite notification")
                    return@launch
                }

                val content = FavoriteControlMessage.encode(isFavorite, senderIdentity.npub)

                val recipientHex = ContactIdentityResolver.nostrPubkeyHex(recipientNostrPubkey)
                if (recipientHex == null) {
                    return@launch
                }

                val embedded = NostrEmbeddedBitChat.encodePMForNostr(
                    content = content,
                    messageID = UUID.randomUUID().toString(),
                    recipientPeerID = to,
                    senderPeerID = senderPeerID
                )

                if (embedded == null) {
                    Log.e(TAG, "NostrTransport: failed to embed favorite notification")
                    return@launch
                }

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = embedded,
                    recipientPubkey = recipientHex,
                    senderIdentity = senderIdentity
                )

                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send favorite notification via Nostr: ${e.message}")
            }
        }
    }

    fun sendDeliveryAck(messageID: String, to: String) {
        transportScope.launch {
            try {
                val recipientNostrPubkey = resolveNostrPublicKey(to)

                if (recipientNostrPubkey == null) {
                    Log.w(TAG, "No Nostr public key found for delivery ack to: $to")
                    return@launch
                }

                val senderIdentity = NostrIdentityBridge.getCurrentNostrIdentity(context)
                if (senderIdentity == null) {
                    Log.e(TAG, "No Nostr identity available for delivery ack")
                    return@launch
                }

                val recipientHex = ContactIdentityResolver.nostrPubkeyHex(recipientNostrPubkey)
                if (recipientHex == null) {
                    return@launch
                }

                val ack = NostrEmbeddedBitChat.encodeAckForNostr(
                    type = NoisePayloadType.DELIVERED,
                    messageID = messageID,
                    recipientPeerID = to,
                    senderPeerID = senderPeerID
                )

                if (ack == null) {
                    Log.e(TAG, "NostrTransport: failed to embed DELIVERED ack")
                    return@launch
                }

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = ack,
                    recipientPubkey = recipientHex,
                    senderIdentity = senderIdentity
                )

                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send delivery ack via Nostr: ${e.message}")
            }
        }
    }

    // MARK: - Geohash ACK helpers (for per-geohash identity DMs)

    fun sendDeliveryAckGeohash(
        messageID: String,
        toRecipientHex: String,
        fromIdentity: NostrIdentity
    ) {
        transportScope.launch {
            try {
                val embedded = NostrEmbeddedBitChat.encodeAckForNostrNoRecipient(
                    type = NoisePayloadType.DELIVERED,
                    messageID = messageID,
                    senderPeerID = senderPeerID
                )

                if (embedded == null) return@launch

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = embedded,
                    recipientPubkey = toRecipientHex,
                    senderIdentity = fromIdentity
                )

                // Register pending gift wrap for deduplication and send all
                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send geohash delivery ack: ${e.message}")
            }
        }
    }

    fun sendReadReceiptGeohash(
        messageID: String,
        toRecipientHex: String,
        fromIdentity: NostrIdentity
    ) {
        transportScope.launch {
            try {
                val embedded = NostrEmbeddedBitChat.encodeAckForNostrNoRecipient(
                    type = NoisePayloadType.READ_RECEIPT,
                    messageID = messageID,
                    senderPeerID = senderPeerID
                )

                if (embedded == null) return@launch

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = embedded,
                    recipientPubkey = toRecipientHex,
                    senderIdentity = fromIdentity
                )

                // Register pending gift wrap for deduplication and send all
                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Failed to send geohash read receipt: ${e.message}")
            }
        }
    }

    // MARK: - Geohash DMs (per-geohash identity)

    fun sendPrivateMessageGeohash(
        content: String,
        toRecipientHex: String,
        messageID: String,
        sourceGeohash: String? = null
    ) {
        // Use provided geohash or derive from current location
        val geohash = sourceGeohash ?: run {
            val selected = try {
                com.bitchat.android.geohash.LocationChannelManager.getInstance(context).selectedChannel.value
            } catch (_: Exception) { null }
            if (selected !is com.bitchat.android.geohash.ChannelID.Location) {
                Log.w(TAG, "NostrTransport: cannot send geohash PM - not in a location channel and no geohash provided")
                return
            }
            selected.channel.geohash
        }

        val fromIdentity = try {
            NostrIdentityBridge.deriveIdentity(geohash, context)
        } catch (e: Exception) {
            Log.e(TAG, "NostrTransport: cannot derive geohash identity for $geohash: ${e.message}")
            return
        }

        transportScope.launch {
            try {
                if (toRecipientHex.isEmpty()) return@launch

                // Build embedded BitChat packet without recipient peer ID
                val embedded = NostrEmbeddedBitChat.encodePMForNostrNoRecipient(
                    content = content,
                    messageID = messageID,
                    senderPeerID = senderPeerID
                ) ?: run {
                    Log.e(TAG, "NostrTransport: failed to embed geohash PM packet")
                    return@launch
                }

                val giftWraps = NostrProtocol.createPrivateMessage(
                    content = embedded,
                    recipientPubkey = toRecipientHex,
                    senderIdentity = fromIdentity
                )

                giftWraps.forEach { event ->
                    NostrRelayManager.registerPendingGiftWrap(event.id)
                    NostrRelayManager.getInstance(context).sendEvent(event)
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to send geohash private message: ${e.message}")
            }
        }
    }

    // MARK: - Helper Methods

    /**
     * Resolve Nostr public key for a peer ID
     */
    private fun resolveNostrPublicKey(peerID: String): String? {
        try {
            ContactDirectory.resolve(peerID).nostrPubkey?.let { return it }

            com.bitchat.android.favorites.FavoritesPersistenceService.shared.findNostrPubkeyForPeerID(peerID)?.let { return it }

            if (ContactIdentityResolver.isNoiseKeyHex(peerID)) {
                val noiseKey = ContactIdentityResolver.bytesFromHex(peerID) ?: return null
                val favoriteStatus = com.bitchat.android.favorites.FavoritesPersistenceService.shared.getFavoriteStatus(noiseKey)
                if (favoriteStatus?.peerNostrPublicKey != null) return favoriteStatus.peerNostrPublicKey
            }

            if (ContactIdentityResolver.isMeshPeerId(peerID)) {
                val fallbackStatus = com.bitchat.android.favorites.FavoritesPersistenceService.shared.getFavoriteStatus(peerID)
                return fallbackStatus?.peerNostrPublicKey
            }

            return null
        } catch (e: Exception) {
            Log.e(TAG, "Failed to resolve Nostr public key for $peerID: ${e.message}")
            return null
        }
    }

    fun cleanup() {
        transportScope.cancel()
    }
}

package com.bitchat.android.nostr

import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Manages Proof of Work preferences for Nostr events
 */
object PoWPreferenceManager {

    private const val PREFS_NAME = "pow_preferences"
    private const val KEY_POW_ENABLED = "pow_enabled"
    private const val KEY_POW_DIFFICULTY = "pow_difficulty"

    // Default values
    private const val DEFAULT_POW_ENABLED = false
    private const val DEFAULT_POW_DIFFICULTY = 12 // Reasonable default for geohash spam prevention

    // State flows for reactive UI
    private val _powEnabled = MutableStateFlow(DEFAULT_POW_ENABLED)
    val powEnabled: StateFlow<Boolean> = _powEnabled.asStateFlow()

    private val _powDifficulty = MutableStateFlow(DEFAULT_POW_DIFFICULTY)
    val powDifficulty: StateFlow<Int> = _powDifficulty.asStateFlow()

    // Mining state for animated indicators
    private val _isMining = MutableStateFlow(false)
    val isMining: StateFlow<Boolean> = _isMining.asStateFlow()

    private lateinit var sharedPrefs: SharedPreferences
    private var isInitialized = false

    /**
     * Initialize the preference manager with application context
     * Should be called once during app startup
     */
    fun init(context: Context) {
        if (isInitialized) return

        sharedPrefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)

        // Load current values
        _powEnabled.value = sharedPrefs.getBoolean(KEY_POW_ENABLED, DEFAULT_POW_ENABLED)
        _powDifficulty.value = sharedPrefs.getInt(KEY_POW_DIFFICULTY, DEFAULT_POW_DIFFICULTY)

        isInitialized = true
    }

    /**
     * Get current PoW enabled state
     */
    fun isPowEnabled(): Boolean {
        return _powEnabled.value
    }

    /**
     * Set PoW enabled state
     */
    fun setPowEnabled(enabled: Boolean) {
        _powEnabled.value = enabled
        if (::sharedPrefs.isInitialized) {
            sharedPrefs.edit().putBoolean(KEY_POW_ENABLED, enabled).apply()
        }
    }

    /**
     * Get current PoW difficulty setting
     */
    fun getPowDifficulty(): Int {
        return _powDifficulty.value
    }

    /**
     * Set PoW difficulty (clamped between 0 and 32)
     */
    fun setPowDifficulty(difficulty: Int) {
        val clampedDifficulty = difficulty.coerceIn(0, 32)
        _powDifficulty.value = clampedDifficulty
        if (::sharedPrefs.isInitialized) {
            sharedPrefs.edit().putInt(KEY_POW_DIFFICULTY, clampedDifficulty).apply()
        }
    }

    /**
     * Get current settings as a data class
     */
    data class PoWSettings(
        val enabled: Boolean,
        val difficulty: Int
    )

    /**
     * Get current settings
     */
    fun getCurrentSettings(): PoWSettings {
        return PoWSettings(
            enabled = _powEnabled.value,
            difficulty = _powDifficulty.value
        )
    }

    /**
     * Reset to default settings
     */
    fun resetToDefaults() {
        setPowEnabled(DEFAULT_POW_ENABLED)
        setPowDifficulty(DEFAULT_POW_DIFFICULTY)
    }

    /**
     * Get difficulty levels with descriptions for UI
     */
    fun getDifficultyLevels(): List<Pair<Int, String>> {
        return listOf(
            0 to "Disabled (no PoW)",
            8 to "Very Low (instant)",
            12 to "Low (~0.1s)",
            16 to "Medium (~2s)",
            20 to "High (~30s)",
            24 to "Very High (~8m)",
            28 to "Extreme (~2h)",
            32 to "Maximum (~8h)"
        )
    }

    /**
     * Get current mining state
     */
    fun isMining(): Boolean {
        return _isMining.value
    }

    /**
     * Start mining state - triggers animated indicators
     */
    fun startMining() {
        _isMining.value = true
    }

    /**
     * Stop mining state - stops animated indicators
     */
    fun stopMining() {
        _isMining.value = false
    }
}

package com.bitchat.android.nostr

import android.app.Application
import android.content.SharedPreferences
import android.util.Log
import java.io.BufferedReader
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.InputStream
import java.io.InputStreamReader
import java.security.MessageDigest
import java.util.concurrent.TimeUnit
import kotlin.math.*
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import okhttp3.OkHttpClient
import okhttp3.Request

/**
 * Loads relay coordinates from assets and provides nearest-relay lookup by geohash.
 */
object RelayDirectory {

    private const val TAG = "RelayDirectory"
    private const val ASSET_FILE_URL = "https://raw.githubusercontent.com/permissionlesstech/georelays/refs/heads/main/nostr_relays.csv"
    private const val ASSET_FILE = "nostr_relays.csv"
    private const val DOWNLOADED_FILE = "nostr_relays_latest.csv"
    private const val PREFS_NAME = "relay_directory_prefs"
    private const val KEY_LAST_UPDATE_MS = "last_update_ms"
    private val ONE_DAY_MS = TimeUnit.DAYS.toMillis(1)

    private val ioScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private val httpClient: OkHttpClient
        get() = com.bitchat.android.net.OkHttpProvider.httpClient()

    data class RelayInfo(
        val url: String,
        val latitude: Double,
        val longitude: Double
    )

    @Volatile
    private var initialized: Boolean = false

    private val relays: MutableList<RelayInfo> = mutableListOf()
    private val relaysLock = Any()

    fun initialize(application: Application) {
        if (initialized) return
        synchronized(this) {
            if (initialized) return
            try {
                val downloaded = getDownloadedFile(application)
                val loadedFromDownloaded = if (downloaded.exists() && downloaded.canRead()) {
                    loadFromFile(downloaded, sourceLabel = "downloaded")
                } else {
                    false
                }

                if (!loadedFromDownloaded) {
                    loadFromAssets(application)
                }

                initialized = true

                // Trigger an immediate fetch if the data is stale (older than 24h)
                ioScope.launch {
                    if (isStale(application)) {
                        fetchAndMaybeSwap(application)
                    }
                }

                // Start periodic staleness check every minute
                startPeriodicRefresh(application)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to initialize RelayDirectory: ${e.message}")
            }
        }
    }

    /**
     * Return up to nRelays closest relay URLs to the geohash center.
     */
    fun closestRelaysForGeohash(geohash: String, nRelays: Int): List<String> {
        val snapshot = synchronized(relaysLock) { relays.toList() }
        if (snapshot.isEmpty()) return emptyList()
        val center = try {
            val c = com.bitchat.android.geohash.Geohash.decodeToCenter(geohash)
            c
        } catch (e: Exception) {
            Log.e(TAG, "Failed to decode geohash")
            return emptyList()
        }

        val (lat, lon) = center
        return snapshot
            .asSequence()
            .sortedBy { haversineMeters(lat, lon, it.latitude, it.longitude) }
            .take(nRelays.coerceAtLeast(0))
            .map { it.url }
            .toList()
    }

    private fun haversineMeters(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
        val R = 6371000.0 // meters
        val dLat = Math.toRadians(lat2 - lat1)
        val dLon = Math.toRadians(lon2 - lon1)
        val a = sin(dLat / 2).pow(2.0) + cos(Math.toRadians(lat1)) * cos(Math.toRadians(lat2)) * sin(dLon / 2).pow(2.0)
        val c = 2 * atan2(sqrt(a), sqrt(1 - a))
        return R * c
    }

    private fun normalizeRelayUrl(raw: String): String {
        val trimmed = raw.trim()
        if (trimmed.isEmpty()) return trimmed
        return if ("://" in trimmed) trimmed else "wss://$trimmed"
    }

    // ===== Implementation details =====

    private fun getPrefs(application: Application): SharedPreferences =
        application.getSharedPreferences(PREFS_NAME, Application.MODE_PRIVATE)

    private fun getDownloadedFile(application: Application): File =
        File(application.filesDir, DOWNLOADED_FILE)

    private fun isStale(application: Application): Boolean {
        val last = getPrefs(application).getLong(KEY_LAST_UPDATE_MS, 0L)
        val now = System.currentTimeMillis()
        return now - last >= ONE_DAY_MS
    }

    private fun startPeriodicRefresh(application: Application) {
        ioScope.launch {
            while (true) {
                try {
                    if (isStale(application)) {
                        fetchAndMaybeSwap(application)
                    }
                } catch (e: Exception) {
                    Log.w(TAG, "Periodic refresh encountered an error: ${e.message}")
                }
                delay(TimeUnit.MINUTES.toMillis(1))
            }
        }
    }

    private fun fetchAndMaybeSwap(application: Application) {
        try {
            val tmpFile = File.createTempFile("relays_", ".csv", application.cacheDir)
            val ok = downloadToFile(ASSET_FILE_URL, tmpFile)
            if (!ok) {
                Log.w(TAG, "Failed to fetch latest relays; keeping current list (will fallback to bundled if none)")
                tmpFile.delete()
                return
            }

            val parsed = parseCsv(FileInputStream(tmpFile))
            if (parsed.isEmpty()) {
                Log.w(TAG, "Downloaded relay CSV parsed to 0 entries; ignoring")
                tmpFile.delete()
                return
            }

            val dest = getDownloadedFile(application)
            tmpFile.inputStream().use { input ->
                FileOutputStream(dest, false).use { output ->
                    input.copyTo(output)
                }
            }
            tmpFile.delete()

            val hash = fileSha256Hex(dest)
            val entries = parsed.size

            synchronized(relaysLock) {
                relays.clear()
                relays.addAll(parsed)
            }

            getPrefs(application).edit().putLong(KEY_LAST_UPDATE_MS, System.currentTimeMillis()).apply()

            Log.i(TAG, "✅ Using downloaded relay list (${dest.absolutePath}), entries=$entries, sha256=$hash, updatedAtMs=${getPrefs(application).getLong(KEY_LAST_UPDATE_MS, 0L)}")
        } catch (e: Exception) {
            Log.w(TAG, "Failed to fetch and swap relay list: ${e.message}")
        }
    }

    private fun downloadToFile(url: String, dest: File): Boolean {
        return try {
            val req = Request.Builder().url(url).get().build()
            httpClient.newCall(req).execute().use { resp ->
                if (!resp.isSuccessful) {
                    Log.w(TAG, "HTTP ${'$'}{resp.code} when fetching $url")
                    return false
                }
                val body = resp.body ?: return false
                FileOutputStream(dest).use { out ->
                    body.byteStream().use { input ->
                        input.copyTo(out)
                    }
                }
                true
            }
        } catch (e: Exception) {
            Log.w(TAG, "Download error: ${e.message}")
            false
        }
    }

    private fun loadFromFile(file: File, sourceLabel: String): Boolean {
        return try {
            val list = parseCsv(FileInputStream(file))
            if (list.isEmpty()) {
                Log.w(TAG, "${sourceLabel} relay CSV has 0 entries; ignoring")
                false
            } else {
                synchronized(relaysLock) {
                    relays.clear()
                    relays.addAll(list)
                }
                val hash = fileSha256Hex(file)
                Log.i(TAG, "📄 Loaded ${list.size} relay entries from ${sourceLabel} file (${file.absolutePath}), sha256=$hash")
                true
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed loading ${sourceLabel} relay file: ${e.message}")
            false
        }
    }

    private fun loadFromAssets(application: Application) {
        val list = try {
            parseCsv(application.assets.open(ASSET_FILE))
        } catch (e: Exception) {
            Log.e(TAG, "Failed to open asset $ASSET_FILE: ${e.message}")
            emptyList()
        }
        synchronized(relaysLock) {
            relays.clear()
            relays.addAll(list)
        }
        // Compute asset hash for logging
        val hash = try {
            application.assets.open(ASSET_FILE).use { input ->
                streamSha256Hex(input)
            }
        } catch (e: Exception) {
            "error:${'$'}{e.message}"
        }
        Log.i(TAG, "📦 Loaded ${list.size} relay entries from assets/$ASSET_FILE, sha256=$hash")
    }

    private fun parseCsv(input: InputStream): List<RelayInfo> {
        val result = mutableListOf<RelayInfo>()
        BufferedReader(InputStreamReader(input)).use { reader ->
            var line: String?
            while (true) {
                line = reader.readLine()
                if (line == null) break
                val trimmed = line!!.trim()
                if (trimmed.isEmpty()) continue
                if (trimmed.lowercase().startsWith("relay url")) continue
                val parts = trimmed.split(",")
                if (parts.size < 3) continue
                val url = normalizeRelayUrl(parts[0].trim())
                val lat = parts[1].trim().toDoubleOrNull()
                val lon = parts[2].trim().toDoubleOrNull()
                if (url.isEmpty() || lat == null || lon == null) continue
                result.add(RelayInfo(url = url, latitude = lat, longitude = lon))
            }
        }
        return result
    }

    private fun fileSha256Hex(file: File): String = try {
        FileInputStream(file).use { input ->
            streamSha256Hex(input)
        }
    } catch (_: Exception) { "error" }

    private fun streamSha256Hex(input: InputStream): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val buf = ByteArray(8192)
        var read: Int
        while (true) {
            read = input.read(buf)
            if (read <= 0) break
            digest.update(buf, 0, read)
        }
        val bytes = digest.digest()
        return bytes.joinToString("") { b ->
            val v = b.toInt() and 0xff
            val s = Integer.toHexString(v)
            if (s.length == 1) "0$s" else s
        }
    }
}

