package com.bitchat.android.onboarding

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import android.os.PowerManager
import android.util.Log
import androidx.core.content.ContextCompat
import com.bitchat.android.R

/**
 * Centralized permission management for bitchat app
 * Handles all Bluetooth and notification permissions required for the app to function
 */
class PermissionManager(private val context: Context) {

    companion object {
        private const val TAG = "PermissionManager"
        private const val PREFS_NAME = "bitchat_permissions"
        private const val KEY_FIRST_TIME_COMPLETE = "first_time_onboarding_complete"
        private const val KEY_OPTIONAL_PERMISSION_REQUESTED_PREFIX =
            "optional_permission_requested_"
    }

    private val sharedPrefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)

    private fun shouldRequireWifiAwarePermission(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return false
        val enabled = try {
            com.bitchat.android.ui.debug.DebugPreferenceManager.getWifiAwareEnabled(false)
        } catch (_: Exception) {
            false
        }
        if (!enabled) return false

        return try {
            com.bitchat.android.wifiaware.WifiAwareSupport.isSupported(context)
        } catch (_: Exception) {
            false
        }
    }

    /**
     * Runtime permissions for the Wi‑Fi Aware transport, version-gated because neither exists
     * at minSdk 26 — requesting an unknown permission comes back permanently denied.
     *
     * ACCESS_LOCAL_NETWORK is defensive: Android 17 gates local network access, and the
     * transport reaches peers over link-local IPv6 sockets. It is granted separately from
     * NEARBY_WIFI_DEVICES but shares its permission group, so the two prompt only once.
     */
    fun wifiAwarePermissions(): List<String> {
        val permissions = mutableListOf<String>()
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            permissions.add(Manifest.permission.NEARBY_WIFI_DEVICES)
        }
        // API 37 == Android 17; no named VERSION_CODES constant is available yet.
        if (Build.VERSION.SDK_INT >= 37) {
            permissions.add(Manifest.permission.ACCESS_LOCAL_NETWORK)
        }
        return permissions
    }

    /**
     * Check if this is the first time the user is launching the app
     */
    fun isFirstTimeLaunch(): Boolean {
        return !sharedPrefs.getBoolean(KEY_FIRST_TIME_COMPLETE, false)
    }

    /**
     * Mark the first-time onboarding as complete
     */
    fun markOnboardingComplete() {
        sharedPrefs.edit()
            .putBoolean(KEY_FIRST_TIME_COMPLETE, true)
            .apply()
        Log.d(TAG, "First-time onboarding marked as complete")
    }

    /**
     * Get required permissions that can be requested together.
     * Background location is handled separately to ensure correct request order.
     * Note: Notification permission is optional and not included here,
     * so the app works without notification access.
     */
    fun getRequiredPermissions(): List<String> {
        val permissions = mutableListOf<String>()

        // Bluetooth permissions (API level dependent)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            permissions.addAll(listOf(
                Manifest.permission.BLUETOOTH_ADVERTISE,
                Manifest.permission.BLUETOOTH_CONNECT,
                Manifest.permission.BLUETOOTH_SCAN
            ))
        } else {
            permissions.addAll(listOf(
                Manifest.permission.BLUETOOTH,
                Manifest.permission.BLUETOOTH_ADMIN
            ))
        }

        // Location permissions (required for Bluetooth LE scanning)
        permissions.addAll(listOf(
            Manifest.permission.ACCESS_COARSE_LOCATION,
            Manifest.permission.ACCESS_FINE_LOCATION
        ))

        // Wi‑Fi Aware: Android 13+ requires NEARBY_WIFI_DEVICES runtime permission
        if (shouldRequireWifiAwarePermission()) {
            permissions.addAll(wifiAwarePermissions())
        }

        // Notification permission intentionally excluded to keep it optional

        return permissions
    }

    /**
     * Background location permission is required on Android 10+ for background BLE scanning.
     * Must be requested after foreground location permissions are granted.
     */
    fun needsBackgroundLocationPermission(): Boolean {
        return Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q
    }

    fun getBackgroundLocationPermission(): String? {
        return if (needsBackgroundLocationPermission()) {
            Manifest.permission.ACCESS_BACKGROUND_LOCATION
        } else {
            null
        }
    }

    fun isBackgroundLocationGranted(): Boolean {
        val permission = getBackgroundLocationPermission() ?: return true
        return isPermissionGranted(permission)
    }

    /**
     * Get optional permissions that improve the experience but aren't required.
     * Currently includes POST_NOTIFICATIONS on Android 13+.
     */
    fun getOptionalPermissions(): List<String> {
        val optional = mutableListOf<String>()
        // Notifications on Android 13+
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            optional.add(Manifest.permission.POST_NOTIFICATIONS)
        }
        return optional
    }

    /**
     * Optional permissions are prompted once. A denial must not trap returning users in
     * onboarding, while users upgrading to a notification-permission Android version
     * should still receive one contextual request.
     */
    fun getUnrequestedOptionalPermissions(): List<String> {
        return getOptionalPermissions().filter { permission ->
            !isPermissionGranted(permission) &&
                !sharedPrefs.getBoolean(optionalPermissionRequestKey(permission), false)
        }
    }

    fun markOptionalPermissionsRequested(permissions: Collection<String>) {
        if (permissions.isEmpty()) return

        sharedPrefs.edit().apply {
            permissions.forEach { permission ->
                putBoolean(optionalPermissionRequestKey(permission), true)
            }
        }.apply()
    }

    private fun optionalPermissionRequestKey(permission: String): String {
        return KEY_OPTIONAL_PERMISSION_REQUESTED_PREFIX + permission
    }

    /**
     * Check if a specific permission is granted
     */
    fun isPermissionGranted(permission: String): Boolean {
        return ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED
    }

    /**
     * Check if all required permissions are granted (background location is optional).
     */
    fun areAllPermissionsGranted(): Boolean {
        return areRequiredPermissionsGranted()
    }

    fun areRequiredPermissionsGranted(): Boolean {
        return getRequiredPermissions().all { isPermissionGranted(it) }
    }

    /**
     * Check if battery optimization is disabled for this app
     */
    fun isBatteryOptimizationDisabled(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            try {
                val powerManager = context.getSystemService(Context.POWER_SERVICE) as PowerManager
                powerManager.isIgnoringBatteryOptimizations(context.packageName)
            } catch (e: Exception) {
                Log.e(TAG, "Error checking battery optimization status", e)
                false
            }
        } else {
            // Battery optimization doesn't exist on Android < 6.0
            true
        }
    }

    /**
     * Check if battery optimization is supported on this device
     */
    fun isBatteryOptimizationSupported(): Boolean {
        return Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
    }

    /**
     * Get the list of permissions that are missing
     */
    fun getMissingPermissions(): List<String> {
        return getRequiredPermissions().filter { !isPermissionGranted(it) }
    }

    fun getMissingBackgroundLocationPermission(): List<String> {
        val permission = getBackgroundLocationPermission() ?: return emptyList()
        return if (isPermissionGranted(permission)) emptyList() else listOf(permission)
    }

    /**
     * Get categorized permission information for display
     */
    fun getCategorizedPermissions(): List<PermissionCategory> {
        val categories = mutableListOf<PermissionCategory>()

        // Bluetooth/Nearby Devices category
        val bluetoothPermissions = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            listOf(
                Manifest.permission.BLUETOOTH_ADVERTISE,
                Manifest.permission.BLUETOOTH_CONNECT,
                Manifest.permission.BLUETOOTH_SCAN
            )
        } else {
            listOf(
                Manifest.permission.BLUETOOTH,
                Manifest.permission.BLUETOOTH_ADMIN
            )
        }

        categories.add(
            PermissionCategory(
                type = PermissionType.NEARBY_DEVICES,
                description = "Required to discover bitchat users via Bluetooth",
                permissions = bluetoothPermissions,
                isGranted = bluetoothPermissions.all { isPermissionGranted(it) },
                systemDescription = "Allow bitchat to connect to nearby devices"
            )
        )

        // Location category
        val locationPermissions = listOf(
            Manifest.permission.ACCESS_COARSE_LOCATION,
            Manifest.permission.ACCESS_FINE_LOCATION
        )

        categories.add(
            PermissionCategory(
                type = PermissionType.PRECISE_LOCATION,
                description = "Required by Android to discover nearby bitchat users via Bluetooth",
                permissions = locationPermissions,
                isGranted = locationPermissions.all { isPermissionGranted(it) },
                systemDescription = "bitchat needs this to scan for nearby devices"
            )
        )

        // Wi‑Fi Aware category (Android 13+)
        if (shouldRequireWifiAwarePermission()) {
            val wifiAwarePermissions = wifiAwarePermissions()
            categories.add(
                PermissionCategory(
                    type = PermissionType.WIFI_AWARE,
                    description = "Enable Wi‑Fi Aware to discover and connect to nearby bitchat users over Wi‑Fi.",
                    permissions = wifiAwarePermissions,
                    isGranted = wifiAwarePermissions.all { isPermissionGranted(it) },
                    systemDescription = "Allow bitchat to discover nearby Wi‑Fi devices"
                )
            )
        }

        if (needsBackgroundLocationPermission()) {
            val backgroundPermission = listOf(Manifest.permission.ACCESS_BACKGROUND_LOCATION)
            categories.add(
                PermissionCategory(
                    type = PermissionType.BACKGROUND_LOCATION,
                    description = context.getString(R.string.perm_background_location_desc),
                    permissions = backgroundPermission,
                    isGranted = backgroundPermission.all { isPermissionGranted(it) },
                    systemDescription = context.getString(R.string.perm_background_location_system)
                )
            )
        }

        // Notifications category (if applicable)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            categories.add(
                PermissionCategory(
                    type = PermissionType.NOTIFICATIONS,
                    description = "Receive notifications when you receive private messages",
                    permissions = listOf(Manifest.permission.POST_NOTIFICATIONS),
                    isGranted = isPermissionGranted(Manifest.permission.POST_NOTIFICATIONS),
                    systemDescription = "Allow bitchat to send you notifications"
                )
            )
        }

        // Microphone category removed from onboarding

        // Battery optimization category (if applicable)
        if (isBatteryOptimizationSupported()) {
            categories.add(
                PermissionCategory(
                    type = PermissionType.BATTERY_OPTIMIZATION,
                    description = "Disable battery optimization to ensure bitchat runs reliably in the background and maintains mesh network connections",
                    permissions = listOf("BATTERY_OPTIMIZATION"), // Custom identifier
                    isGranted = isBatteryOptimizationDisabled(),
                    systemDescription = "Allow bitchat to run without battery restrictions"
                )
            )
        }

        return categories
    }

    /**
     * Get detailed diagnostic information about permission status
     */
    fun getPermissionDiagnostics(): String {
        return buildString {
            appendLine("Permission Diagnostics:")
            appendLine("Android SDK: ${Build.VERSION.SDK_INT}")
            appendLine("First time launch: ${isFirstTimeLaunch()}")
            appendLine("Required permissions granted: ${areAllPermissionsGranted()}")
            appendLine()

            getCategorizedPermissions().forEach { category ->
                appendLine("${category.type.nameValue}: ${if (category.isGranted) "✅ GRANTED" else "❌ MISSING"}")
                category.permissions.forEach { permission ->
                    val granted = isPermissionGranted(permission)
                    appendLine("  - ${permission.substringAfterLast(".")}: ${if (granted) "✅" else "❌"}")
                }
                appendLine()
            }

            val missing = getMissingPermissions() + getMissingBackgroundLocationPermission()
            if (missing.isNotEmpty()) {
                appendLine("Missing permissions:")
                missing.forEach { permission ->
                    appendLine("- $permission")
                }
            }
        }
    }

    /**
     * Log permission status for debugging
     */
    fun logPermissionStatus() {
        Log.d(TAG, getPermissionDiagnostics())
    }
}

/**
 * Data class representing a category of related permissions
 */
data class PermissionCategory(
    val type: PermissionType,
    val description: String,
    val permissions: List<String>,
    val isGranted: Boolean,
    val systemDescription: String
)

enum class PermissionType(val nameValue: String) {
    NEARBY_DEVICES("Nearby Devices"),
    PRECISE_LOCATION("Precise Location"),
    BACKGROUND_LOCATION("Background Location"),
    MICROPHONE("Microphone"),
    NOTIFICATIONS("Notifications"),
    WIFI_AWARE("Wi‑Fi Aware"),
    BATTERY_OPTIMIZATION("Battery Optimization"),
    OTHER("Other")
}

package com.bitchat.android.protocol

import android.os.Parcelable
import kotlinx.parcelize.Parcelize
import java.nio.ByteBuffer
import java.nio.ByteOrder
import android.util.Log

/**
 * Message types - exact same as iOS version with Noise Protocol support
 */
enum class MessageType(val value: UByte) {
    ANNOUNCE(0x01u),
    MESSAGE(0x02u),  // All user messages (private and broadcast)
    LEAVE(0x03u),
    NOISE_HANDSHAKE(0x10u),  // Noise handshake
    NOISE_ENCRYPTED(0x11u),  // Noise encrypted transport message
    FRAGMENT(0x20u), // Fragmentation for large packets
    REQUEST_SYNC(0x21u), // GCS-based sync request
    FILE_TRANSFER(0x22u), // New: File transfer packet (BLE voice notes, etc.)
    VOICE_FRAME(0x29u); // Ephemeral live push-to-talk frame; never added to gossip sync

    companion object {
        fun fromValue(value: UByte): MessageType? {
            return values().find { it.value == value }
        }
    }
}

/**
 * Special recipient IDs - exact same as iOS version
 */
object SpecialRecipients {
    val BROADCAST = ByteArray(8) { 0xFF.toByte() }  // All 0xFF = broadcast
}

/**
 * Binary packet format - 100% backward compatible with iOS version
 *
 * Header (14 bytes for v1, 16 bytes for v2):
 * - Version: 1 byte
 * - Type: 1 byte
 * - TTL: 1 byte
 * - Timestamp: 8 bytes (UInt64, big-endian)
 * - Flags: 1 byte (bit 0: hasRecipient, bit 1: hasSignature, bit 2: isCompressed)
 * - PayloadLength: 2 bytes (v1) / 4 bytes (v2) (big-endian)
 *
 * Variable sections:
 * - SenderID: 8 bytes (fixed)
 * - RecipientID: 8 bytes (if hasRecipient flag set)
 * - Payload: Variable length (includes original size if compressed)
 * - Signature: 64 bytes (if hasSignature flag set)
 */
@Parcelize
data class BitchatPacket(
    val version: UByte = 1u,
    val type: UByte,
    val senderID: ByteArray,
    val recipientID: ByteArray? = null,
    val timestamp: ULong,
    val payload: ByteArray,
    var signature: ByteArray? = null,  // Changed from val to var for packet signing
    var ttl: UByte,
    var route: List<ByteArray>? = null // Optional source route: ordered list of peerIDs (8 bytes each), not including sender and final recipient
) : Parcelable {

    constructor(
        type: UByte,
        ttl: UByte,
        senderID: String,
        payload: ByteArray
    ) : this(
        version = 1u,
        type = type,
        senderID = hexStringToByteArray(senderID),
        recipientID = null,
        timestamp = (System.currentTimeMillis()).toULong(),
        payload = payload,
        signature = null,
        ttl = ttl
    )

    fun toBinaryData(padding: Boolean = true): ByteArray? {
        return BinaryProtocol.encode(this, padding = padding)
    }

    /**
     * Create binary representation for signing (without signature and TTL fields)
     * TTL is excluded because it changes during packet relay operations
     */
    fun toBinaryDataForSigning(): ByteArray? {
        // Create a copy without signature and with fixed TTL for signing
        // TTL must be excluded because it changes during relay
        val unsignedPacket = BitchatPacket(
            version = version,
            type = type,
            senderID = senderID,
            recipientID = recipientID,
            timestamp = timestamp,
            payload = payload,
            signature = null, // Remove signature for signing
            route = route,
            ttl = com.bitchat.android.util.AppConstants.SYNC_TTL_HOPS // Use fixed TTL=0 for signing to ensure relay compatibility
        )
        return BinaryProtocol.encode(unsignedPacket)
    }

    companion object {
        fun fromBinaryData(data: ByteArray): BitchatPacket? {
            return BinaryProtocol.decode(data)
        }

        /**
         * Convert hex string peer ID to binary data (8 bytes) - exactly same as iOS
         */
        private fun hexStringToByteArray(hexString: String): ByteArray {
            val result = ByteArray(8) { 0 } // Initialize with zeros, exactly 8 bytes
            var tempID = hexString
            var index = 0

            while (tempID.length >= 2 && index < 8) {
                val hexByte = tempID.substring(0, 2)
                val byte = hexByte.toIntOrNull(16)?.toByte()
                if (byte != null) {
                    result[index] = byte
                }
                tempID = tempID.substring(2)
                index++
            }

            return result
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as BitchatPacket

        if (version != other.version) return false
        if (type != other.type) return false
        if (!senderID.contentEquals(other.senderID)) return false
        if (recipientID != null) {
            if (other.recipientID == null) return false
            if (!recipientID.contentEquals(other.recipientID)) return false
        } else if (other.recipientID != null) return false
        if (timestamp != other.timestamp) return false
        if (!payload.contentEquals(other.payload)) return false
        if (signature != null) {
            if (other.signature == null) return false
            if (!signature.contentEquals(other.signature)) return false
        } else if (other.signature != null) return false
        if (ttl != other.ttl) return false
        if (route != null || other.route != null) {
            val a = route?.map { it.toList() } ?: emptyList()
            val b = other.route?.map { it.toList() } ?: emptyList()
            if (a != b) return false
        }

        return true
    }

    override fun hashCode(): Int {
        var result = version.hashCode()
        result = 31 * result + type.hashCode()
        result = 31 * result + senderID.contentHashCode()
        result = 31 * result + (recipientID?.contentHashCode() ?: 0)
        result = 31 * result + timestamp.hashCode()
        result = 31 * result + payload.contentHashCode()
        result = 31 * result + (signature?.contentHashCode() ?: 0)
        result = 31 * result + ttl.hashCode()
        result = 31 * result + (route?.fold(1) { acc, bytes -> 31 * acc + bytes.contentHashCode() } ?: 0)
        return result
    }
}

/**
 * Binary Protocol implementation - supports v1 and v2, backward compatible
 */
object BinaryProtocol {
    private const val HEADER_SIZE_V1 = 14
    private const val HEADER_SIZE_V2 = 16
    private const val SENDER_ID_SIZE = 8
    private const val RECIPIENT_ID_SIZE = 8
    private const val SIGNATURE_SIZE = 64
    object Flags {
        const val HAS_RECIPIENT: UByte = 0x01u
        const val HAS_SIGNATURE: UByte = 0x02u
        const val IS_COMPRESSED: UByte = 0x04u
        const val HAS_ROUTE: UByte = 0x08u
    }

    private fun getHeaderSize(version: UByte): Int {
        return when (version) {
            1u.toUByte() -> HEADER_SIZE_V1
            else -> HEADER_SIZE_V2  // v2+ will use 4-byte payload length
        }
    }

    fun encode(packet: BitchatPacket, padding: Boolean = true): ByteArray? {
        try {
            val maxPayloadLength = com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH
            if (packet.payload.size > maxPayloadLength) {
                Log.w(
                    "BinaryProtocol",
                    "Cannot encode payload ${packet.payload.size} above receiver limit $maxPayloadLength"
                )
                return null
            }

            // Try to compress payload if beneficial
            var payload = packet.payload
            var originalPayloadSize: Int? = null
            var isCompressed = false

            if (CompressionUtil.shouldCompress(payload)) {
                CompressionUtil.compress(payload)?.let { compressedPayload ->
                    originalPayloadSize = payload.size
                    payload = compressedPayload
                    isCompressed = true
                }
            }

            // Compute a safe capacity for the unpadded frame
            val headerSize = getHeaderSize(packet.version)
            val recipientBytes = if (packet.recipientID != null) RECIPIENT_ID_SIZE else 0
            val signatureBytes = if (packet.signature != null) SIGNATURE_SIZE else 0
            val sizeFieldBytes = if (isCompressed) (if (packet.version >= 2u.toUByte()) 4 else 2) else 0
            val payloadBytes = payload.size + sizeFieldBytes
            val routeBytes = if (!packet.route.isNullOrEmpty() && packet.version >= 2u.toUByte()) {
                1 + (packet.route!!.size.coerceAtMost(255) * SENDER_ID_SIZE)
            } else 0
            val capacity = headerSize + SENDER_ID_SIZE + recipientBytes + payloadBytes + signatureBytes + routeBytes + 16 // small slack
            val buffer = ByteBuffer.allocate(capacity.coerceAtLeast(512)).apply { order(ByteOrder.BIG_ENDIAN) }

            // Header
            buffer.put(packet.version.toByte())
            buffer.put(packet.type.toByte())
            buffer.put(packet.ttl.toByte())

            // Timestamp (8 bytes, big-endian)
            buffer.putLong(packet.timestamp.toLong())

            // Flags
            var flags: UByte = 0u
            if (packet.recipientID != null) {
                flags = flags or Flags.HAS_RECIPIENT
            }
            if (packet.signature != null) {
                flags = flags or Flags.HAS_SIGNATURE
            }
            if (isCompressed) {
                flags = flags or Flags.IS_COMPRESSED
            }
            // HAS_ROUTE is only supported for v2+ packets
            if (!packet.route.isNullOrEmpty() && packet.version >= 2u.toUByte()) {
                flags = flags or Flags.HAS_ROUTE
            }
            buffer.put(flags.toByte())

            // Payload length (2 or 4 bytes, big-endian) - includes original size if compressed
            val payloadDataSize = payload.size + sizeFieldBytes
            if (packet.version >= 2u.toUByte()) {
                buffer.putInt(payloadDataSize)  // 4 bytes for v2+
            } else {
                if (payloadDataSize > 0xFFFF || (originalPayloadSize ?: 0) > 0xFFFF) {
                    Log.w("BinaryProtocol", "Cannot encode oversized v1 packet payload: $payloadDataSize bytes")
                    return null
                }
                buffer.putShort(payloadDataSize.toShort())  // 2 bytes for v1
            }

            // SenderID (exactly 8 bytes)
            val senderBytes = packet.senderID.take(SENDER_ID_SIZE).toByteArray()
            buffer.put(senderBytes)
            if (senderBytes.size < SENDER_ID_SIZE) {
                buffer.put(ByteArray(SENDER_ID_SIZE - senderBytes.size))
            }

            // RecipientID (if present)
            packet.recipientID?.let { recipientID ->
                val recipientBytes = recipientID.take(RECIPIENT_ID_SIZE).toByteArray()
                buffer.put(recipientBytes)
                if (recipientBytes.size < RECIPIENT_ID_SIZE) {
                    buffer.put(ByteArray(RECIPIENT_ID_SIZE - recipientBytes.size))
                }
            }

            // Route (optional, v2+ only): 1 byte count + N*8 bytes
            if (packet.version >= 2u.toUByte() && !packet.route.isNullOrEmpty()) {
                packet.route?.let { routeList ->
                    val cleaned = routeList.map { bytes -> bytes.take(SENDER_ID_SIZE).toByteArray().let { if (it.size < SENDER_ID_SIZE) it + ByteArray(SENDER_ID_SIZE - it.size) else it } }
                    val count = cleaned.size.coerceAtMost(255)
                    buffer.put(count.toByte())
                    cleaned.take(count).forEach { hop -> buffer.put(hop) }
                }
            }

            // Payload (with original size prepended if compressed)
            if (isCompressed) {
                val originalSize = originalPayloadSize
                if (originalSize != null) {
                    if (packet.version >= 2u.toUByte()) {
                        buffer.putInt(originalSize.toInt())
                    } else {
                        buffer.putShort(originalSize.toShort())
                    }
                }
            }
            buffer.put(payload)

            // Signature (if present)
            packet.signature?.let { signature ->
                buffer.put(signature.take(SIGNATURE_SIZE).toByteArray())
            }

            val result = ByteArray(buffer.position())
            buffer.rewind()
            buffer.get(result)

            // Apply padding if requested (iOS-compatible: selective padding for privacy)
            if (padding) {
                val optimalSize = MessagePadding.optimalBlockSize(result.size)
                return MessagePadding.pad(result, optimalSize)
            }

            return result

        } catch (e: Exception) {
            Log.e("BinaryProtocol", "Error encoding packet type ${packet.type}: ${e.message}")
            return null
        }
    }

    fun decode(data: ByteArray): BitchatPacket? =
        decode(data, CompressionUtil::decompressWithResourcesReserved)

    /** Test seam used to prove rejected expansion sizes never reach inflation. */
    internal fun decodeForTesting(
        data: ByteArray,
        decompress: (ByteArray, Int) -> ByteArray?
    ): BitchatPacket? = decode(data, decompress)

    private fun decode(
        data: ByteArray,
        decompress: (ByteArray, Int) -> ByteArray?
    ): BitchatPacket? {
        // Try decode as-is first (robust when padding wasn't applied) - iOS fix
        decodeCore(data, decompress)?.let { return it }

        // If that fails, try after removing padding
        val unpadded = MessagePadding.unpad(data)
        if (unpadded.contentEquals(data)) return null // No padding was removed, already failed

        return decodeCore(unpadded, decompress)
    }

    /**
     * Core decoding implementation used by decode() with and without padding removal - iOS fix
     */
    private fun decodeCore(
        raw: ByteArray,
        decompress: (ByteArray, Int) -> ByteArray?
    ): BitchatPacket? {
        try {
            if (raw.size < HEADER_SIZE_V1 + SENDER_ID_SIZE) return null

            val buffer = ByteBuffer.wrap(raw).apply { order(ByteOrder.BIG_ENDIAN) }

            // Header
            val version = buffer.get().toUByte()
            if (version.toUInt() != 1u && version.toUInt() != 2u) return null  // Support v1 and v2

            val headerSize = getHeaderSize(version)

            val type = buffer.get().toUByte()
            val ttl = buffer.get().toUByte()

            // Timestamp
            val timestamp = buffer.getLong().toULong()

            // Flags
            val flags = buffer.get().toUByte()
            val hasRecipient = (flags and Flags.HAS_RECIPIENT) != 0u.toUByte()
            val hasSignature = (flags and Flags.HAS_SIGNATURE) != 0u.toUByte()
            val isCompressed = (flags and Flags.IS_COMPRESSED) != 0u.toUByte()
            // HAS_ROUTE is only valid for v2+ packets; ignore the flag for v1
            val hasRoute = (version >= 2u.toUByte()) && (flags and Flags.HAS_ROUTE) != 0u.toUByte()

            // Payload length - version-dependent (2 or 4 bytes)
            val payloadLength = if (version >= 2u.toUByte()) {
                buffer.getInt().toUInt()  // 4 bytes for v2+
            } else {
                buffer.getShort().toUShort().toUInt()  // 2 bytes for v1, convert to UInt
            }

            if (payloadLength > com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH.toUInt()) {
                Log.w("BinaryProtocol", "Payload length ${payloadLength} exceeds maximum allowed (${com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH})")
                return null
            }

            var expectedSize = headerSize + SENDER_ID_SIZE + payloadLength.toInt()
            if (hasRecipient) expectedSize += RECIPIENT_ID_SIZE
            var routeCount = 0
            if (hasRoute) {
                // Peek count (1 byte) without consuming buffer for now
                // The buffer is currently positioned at the start of SenderID (after fixed header)
                // We must skip SenderID and RecipientID (if present) to find the route count
                val currentPos = buffer.position()
                var routeOffset = currentPos + SENDER_ID_SIZE
                if (hasRecipient) {
                    routeOffset += RECIPIENT_ID_SIZE
                }

                if (raw.size >= routeOffset + 1) {
                    routeCount = raw[routeOffset].toUByte().toInt()
                }
                expectedSize += 1 + (routeCount * SENDER_ID_SIZE)
            }
            if (hasSignature) expectedSize += SIGNATURE_SIZE

            if (raw.size < expectedSize) return null

            // SenderID
            val senderID = ByteArray(SENDER_ID_SIZE)
            buffer.get(senderID)

            // RecipientID
            val recipientID = if (hasRecipient) {
                val recipientBytes = ByteArray(RECIPIENT_ID_SIZE)
                buffer.get(recipientBytes)
                recipientBytes
            } else null

            // Route (optional)
            val route: List<ByteArray>? = if (hasRoute) {
                val count = buffer.get().toUByte().toInt()
                if (count == 0) {
                    null // Treat empty route list as null to enforce canonical representation
                } else {
                    val hops = mutableListOf<ByteArray>()
                    repeat(count) {
                        val hop = ByteArray(SENDER_ID_SIZE)
                        buffer.get(hop)
                        hops.add(hop)
                    }
                    hops
                }
            } else null

            // Payload
            val payload = if (isCompressed) {
                val lengthFieldBytes = if (version >= 2u.toUByte()) 4 else 2
                if (payloadLength.toInt() < lengthFieldBytes) return null

                val originalSize = if (version >= 2u.toUByte()) {
                    buffer.getInt()
                } else {
                    buffer.getShort().toUShort().toInt()
                }

                val maxExpandedSize = com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH
                if (originalSize <= 0 || originalSize > maxExpandedSize) {
                    Log.w(
                        "BinaryProtocol",
                        "Expanded payload size $originalSize is outside the allowed range 1..$maxExpandedSize"
                    )
                    return null
                }

                // Compressed payload
                val compressedSize = payloadLength.toInt() - lengthFieldBytes
                if (compressedSize == 0) {
                    Log.w("BinaryProtocol", "Compressed payload has no deflate bytes")
                    return null
                }
                // Security check: Compression bomb protection
                val ratio = originalSize.toDouble() / compressedSize.toDouble()
                if (ratio > 50_000.0) {
                    Log.w("BinaryProtocol", "🚫 Suspicious compression ratio: ${ratio}:1")
                    return null
                }

                // Reserve the compressed copy plus expanded output before either allocation.
                // Small packets share the memory pool; packets wait only while its budget is full.
                val resourceBytes = compressedSize.toLong() + originalSize.toLong()
                val expandedPayload = CompressionUtil.withDecompressionResources(resourceBytes) {
                    val compressedPayload = ByteArray(compressedSize)
                    buffer.get(compressedPayload)
                    decompress(compressedPayload, originalSize)
                } ?: return null
                if (expandedPayload.size != originalSize) {
                    Log.w(
                        "BinaryProtocol",
                        "Expanded payload size ${expandedPayload.size} did not match declared size $originalSize"
                    )
                    return null
                }
                expandedPayload
            } else {
                val payloadBytes = ByteArray(payloadLength.toInt())
                buffer.get(payloadBytes)
                payloadBytes
            }

            // Signature
            val signature = if (hasSignature) {
                val signatureBytes = ByteArray(SIGNATURE_SIZE)
                buffer.get(signatureBytes)
                signatureBytes
            } else null

            return BitchatPacket(
                version = version,
                type = type,
                senderID = senderID,
                recipientID = recipientID,
                timestamp = timestamp,
                payload = payload,
                signature = signature,
                ttl = ttl,
                route = route
            )

        } catch (e: Exception) {
            Log.e("BinaryProtocol", "Error decoding packet: ${e.message}")
            return null
        }
    }
}

package com.bitchat.android.protocol

import android.util.Log
import java.io.ByteArrayOutputStream
import java.util.zip.DataFormatException
import java.util.zip.Deflater
import java.util.zip.Inflater

/**
 * Compression utilities - 100% iOS-compatible zlib implementation
 * Uses the same zlib algorithm as iOS CompressionUtil.swift
 */
object CompressionUtil {
    private const val COMPRESSION_THRESHOLD = com.bitchat.android.util.AppConstants.Protocol.COMPRESSION_THRESHOLD_BYTES  // bytes - same as iOS

    private val decompressionPool = DecompressionResourcePool.forRuntime()

    /**
     * Helper to check if compression is worth it - exact same logic as iOS
     */
    fun shouldCompress(data: ByteArray): Boolean {
        // Don't compress if:
        // 1. Data is too small
        // 2. Data appears to be already compressed (high entropy)
        if (data.size < COMPRESSION_THRESHOLD) return false

        // Simple entropy check - count unique bytes (exact same as iOS)
        val byteFrequency = mutableMapOf<Byte, Int>()
        for (byte in data) {
            byteFrequency[byte] = (byteFrequency[byte] ?: 0) + 1
        }

        // If we have very high byte diversity, data is likely already compressed
        val uniqueByteRatio = byteFrequency.size.toDouble() / minOf(data.size, 256).toDouble()
        return uniqueByteRatio < 0.9 // Compress if less than 90% unique bytes
    }

    /**
     * Compress data using deflate algorithm - exact same as iOS
     * iOS COMPRESSION_ZLIB actually produces raw deflate data (no zlib headers)
     */
    fun compress(data: ByteArray): ByteArray? {
        // Skip compression for small data
        if (data.size < COMPRESSION_THRESHOLD) return null

        try {
            // Use raw deflate format (no headers) to match iOS COMPRESSION_ZLIB behavior
            val deflater = Deflater(Deflater.DEFAULT_COMPRESSION, true) // true = raw deflate, no headers
            deflater.setInput(data)
            deflater.finish()

            val outputStream = ByteArrayOutputStream(data.size)
            val buffer = ByteArray(1024)

            while (!deflater.finished()) {
                val count = deflater.deflate(buffer)
                outputStream.write(buffer, 0, count)
            }
            deflater.end()

            val compressedData = outputStream.toByteArray()

            // Only return if compression was beneficial (same logic as iOS)
            return if (compressedData.size > 0 && compressedData.size < data.size) {
                compressedData
            } else {
                null
            }
        } catch (e: Exception) {
            return null
        }
    }

    /**
     * Decompress deflate compressed data - exact same as iOS
     * iOS COMPRESSION_ZLIB produces raw deflate data (no headers)
     */
    fun decompress(compressedData: ByteArray, originalSize: Int): ByteArray? {
        if (!isValidRequest(compressedData, originalSize)) return null
        return withDecompressionResources(originalSize.toLong()) {
            decompressWithResourcesReserved(compressedData, originalSize)
        }
    }

    internal fun <T> withDecompressionResources(bytes: Long, block: () -> T): T? =
        decompressionPool.withReservation(bytes, block)

    /**
     * Inflate after the caller has reserved all packet-specific allocations.
     * This avoids nested acquisition when BinaryProtocol reserves both its input copy and output.
     */
    internal fun decompressWithResourcesReserved(
        compressedData: ByteArray,
        originalSize: Int
    ): ByteArray? {
        if (!isValidRequest(compressedData, originalSize)) return null
        return decompressExact(compressedData, originalSize)
    }

    private fun isValidRequest(compressedData: ByteArray, originalSize: Int): Boolean {
        val maxExpandedSize = com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH
        if (compressedData.isEmpty()) {
            Log.w("CompressionUtil", "Refusing an empty compressed payload")
            return false
        }
        if (originalSize <= 0 || originalSize > maxExpandedSize) {
            Log.w(
                "CompressionUtil",
                "Refusing expanded payload size $originalSize outside 1..$maxExpandedSize"
            )
            return false
        }
        return true
    }

    private fun decompressExact(compressedData: ByteArray, originalSize: Int): ByteArray? {
        return if (looksLikeZlib(compressedData)) {
            // A raw stream can coincidentally begin with a valid-looking zlib header. The
            // header therefore only determines which format to try first; any non-exact zlib
            // result must still fall back to raw under the same size/completion bounds.
            val zlibResult = try {
                inflateExact(compressedData, originalSize, nowrap = false)
            } catch (zlibException: DataFormatException) {
                null
            }
            if (zlibResult != null) {
                zlibResult
            } else {
                try {
                    inflateExact(compressedData, originalSize, nowrap = true)
                } catch (rawException: DataFormatException) {
                    Log.d("CompressionUtil", "Invalid zlib/raw deflate stream")
                    null
                }
            }
        } else {
            try {
                inflateExact(compressedData, originalSize, nowrap = true)
            } catch (rawException: DataFormatException) {
                Log.d("CompressionUtil", "Invalid raw deflate stream")
                null
            }
        }
    }

    /** RFC 1950 header check used to avoid speculative double inflation. */
    private fun looksLikeZlib(data: ByteArray): Boolean {
        if (data.size < 2) return false
        val cmf = data[0].toInt() and 0xFF
        val flg = data[1].toInt() and 0xFF
        return (cmf and 0x0F) == 8 &&
            (cmf ushr 4) <= 7 &&
            ((cmf shl 8) or flg) % 31 == 0
    }

    /**
     * Inflate one complete stream into exactly [originalSize] bytes.
     *
     * A full output buffer alone is not success: an attacker can under-declare a larger stream so
     * the first inflate call fills the buffer while [Inflater.finished] remains false. Conversely,
     * a truncated or over-declared stream can produce a non-empty prefix. Both forms are rejected,
     * as are trailing bytes after the compressed stream.
     *
     * [DataFormatException] is deliberately allowed to escape so the caller can try the legacy
     * zlib-wrapped format. Size/completion mismatches return null; the fallback must then prove the
     * same bytes are a complete, exact-sized zlib stream before they can be accepted.
     */
    @Throws(DataFormatException::class)
    private fun inflateExact(
        compressedData: ByteArray,
        originalSize: Int,
        nowrap: Boolean
    ): ByteArray? {
        val inflater = Inflater(nowrap)
        return try {
            inflater.setInput(compressedData)
            val output = ByteArray(originalSize)
            var written = 0

            while (written < originalSize) {
                val count = inflater.inflate(output, written, originalSize - written)
                if (count == 0) break
                written += count
            }

            if (written != originalSize) return null

            // Give Inflater one byte of room to consume the end marker. Any produced byte proves
            // the declared size was smaller than the actual expansion.
            val overflowProbe = ByteArray(1)
            if (inflater.inflate(overflowProbe) != 0) return null

            if (!inflater.finished() || inflater.remaining != 0) return null
            output
        } finally {
            inflater.end()
        }
    }

    /**
     * Test function to verify deflate compression works correctly
     * This can be called during app initialization to ensure compatibility
     */
    fun testCompression(): Boolean {
        try {
            // Create test data that should compress well (repeating pattern like iOS would use)
            val testMessage = "This is a test message that should compress well. ".repeat(10)
            val originalData = testMessage.toByteArray()

            Log.d("CompressionUtil", "Testing deflate compression with ${originalData.size} bytes")

            // Test shouldCompress
            val shouldCompress = shouldCompress(originalData)
            Log.d("CompressionUtil", "shouldCompress() returned: $shouldCompress")

            if (!shouldCompress) {
                Log.e("CompressionUtil", "shouldCompress failed for test data")
                return false
            }

            // Test compression
            val compressed = compress(originalData)
            if (compressed == null) {
                Log.e("CompressionUtil", "Compression failed")
                return false
            }

            Log.d("CompressionUtil", "Compressed ${originalData.size} bytes to ${compressed.size} bytes (${(compressed.size.toDouble() / originalData.size * 100).toInt()}%)")

            // Test decompression
            val decompressed = decompress(compressed, originalData.size)
            if (decompressed == null) {
                Log.e("CompressionUtil", "Decompression failed")
                return false
            }

            // Verify data integrity
            val isIdentical = originalData.contentEquals(decompressed)
            Log.d("CompressionUtil", "Data integrity check: $isIdentical")

            if (!isIdentical) {
                Log.e("CompressionUtil", "Decompressed data doesn't match original")
                return false
            }

            Log.i("CompressionUtil", "✅ deflate compression test PASSED - ready for iOS compatibility")
            return true

        } catch (e: Exception) {
            Log.e("CompressionUtil", "deflate compression test failed: ${e.message}")
            return false
        }
    }
}

package com.bitchat.android.protocol

import java.util.concurrent.Semaphore
import java.util.concurrent.TimeUnit
import kotlin.math.ceil

/**
 * Fair, weighted admission control for decompression allocations.
 *
 * Permits represent memory rather than workers: small packets can proceed concurrently while
 * near-limit packets consume most of the budget. Callers must reserve before allocating any
 * packet-specific compressed copy or expanded output.
 */
internal class DecompressionResourcePool(
    budgetBytes: Long,
    private val unitBytes: Int,
    private val waitTimeoutMs: Long
) {
    private val totalPermits = (budgetBytes / unitBytes).toInt().coerceAtLeast(1)
    private val permits = Semaphore(totalPermits, true)

    fun <T> withReservation(bytes: Long, block: () -> T): T? {
        val requiredPermits = permitsFor(bytes)
        val acquired = try {
            permits.tryAcquire(requiredPermits, waitTimeoutMs, TimeUnit.MILLISECONDS)
        } catch (_: InterruptedException) {
            Thread.currentThread().interrupt()
            false
        }
        if (!acquired) return null

        return try {
            block()
        } finally {
            permits.release(requiredPermits)
        }
    }

    internal fun permitsFor(bytes: Long): Int =
        ceil(bytes.coerceAtLeast(1).toDouble() / unitBytes.toDouble())
            .toInt()
            .coerceAtMost(totalPermits)

    internal val availablePermits: Int
        get() = permits.availablePermits()

    companion object {
        private const val DEFAULT_UNIT_BYTES = 256 * 1024
        private const val DEFAULT_WAIT_TIMEOUT_MS = 1_000L
        private const val HEAP_BUDGET_DIVISOR = 8L
        private const val MAX_BUDGET_BYTES = 64L * 1024 * 1024

        fun forRuntime(
            maxHeapBytes: Long = Runtime.getRuntime().maxMemory(),
            maxPacketResourceBytes: Long =
                2L * com.bitchat.android.util.AppConstants.Protocol.MAX_PAYLOAD_LENGTH
        ): DecompressionResourcePool {
            val budget = recommendedBudgetBytes(maxHeapBytes, maxPacketResourceBytes)
            return DecompressionResourcePool(
                budgetBytes = budget,
                unitBytes = DEFAULT_UNIT_BYTES,
                waitTimeoutMs = DEFAULT_WAIT_TIMEOUT_MS
            )
        }

        internal fun recommendedBudgetBytes(
            maxHeapBytes: Long,
            maxPacketResourceBytes: Long
        ): Long = (maxHeapBytes / HEAP_BUDGET_DIVISOR)
            .coerceAtLeast(maxPacketResourceBytes)
            .coerceAtMost(MAX_BUDGET_BYTES.coerceAtLeast(maxPacketResourceBytes))
    }
}

package com.bitchat.android.protocol

import java.security.SecureRandom

/**
 * Privacy-preserving padding utilities - exact same as iOS version
 * Provides traffic analysis resistance by normalizing message sizes
 */
object MessagePadding {
    // Standard block sizes for padding - exact same as iOS
    private val blockSizes = listOf(256, 512, 1024, 2048)

    /**
     * Find optimal block size for data - exact same logic as iOS
     */
    fun optimalBlockSize(dataSize: Int): Int {
        // Account for encryption overhead (~16 bytes for AES-GCM tag)
        val totalSize = dataSize + 16

        // Find smallest block that fits
        for (blockSize in blockSizes) {
            if (totalSize <= blockSize) {
                return blockSize
            }
        }

        // For very large messages, just use the original size
        // (will be fragmented anyway)
        return dataSize
    }

    /**
     * Add PKCS#7-style padding to reach target size - FIXED: proper PKCS#7 (iOS compatible)
     */
    fun pad(data: ByteArray, targetSize: Int): ByteArray {
        if (data.size >= targetSize) return data

        val paddingNeeded = targetSize - data.size

        // Constrain to 255 to fit a single-byte pad length marker
        if (paddingNeeded <= 0 || paddingNeeded > 255) return data

        val result = ByteArray(targetSize)

        // Copy original data
        System.arraycopy(data, 0, result, 0, data.size)

        // PKCS#7: All pad bytes are equal to the pad length (iOS fix)
        for (i in data.size until targetSize) {
            result[i] = paddingNeeded.toByte()
        }

        return result
    }

    /**
     * Remove padding from data - FIXED: strict PKCS#7 validation (iOS compatible)
     */
    fun unpad(data: ByteArray): ByteArray {
        if (data.isEmpty()) return data

        val last = data[data.size - 1]
        val paddingLength = last.toInt() and 0xFF

        // Must have at least 1 pad byte and not exceed data length
        if (paddingLength <= 0 || paddingLength > data.size) return data

        // Verify PKCS#7: all last N bytes equal to pad length (iOS fix)
        val start = data.size - paddingLength
        for (i in start until data.size) {
            if (data[i] != last) {
                return data // Invalid padding, return original
            }
        }

        return data.copyOfRange(0, start)
    }
}

package com.bitchat.android.service

import android.app.Application
import android.os.Process
import androidx.core.app.NotificationManagerCompat
import com.bitchat.android.mesh.MeshService
import com.bitchat.android.net.ArtiTorManager
import com.bitchat.android.net.TorMode
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.Job
import kotlinx.coroutines.async
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull
import java.util.concurrent.atomic.AtomicLong

/**
 * Coordinates a full application shutdown:
 * - Stop mesh cleanly
 * - Stop Tor without changing persistent setting
 * - Clear in-memory AppState
 * - Stop foreground service/notification
 * - Kill the process after completion or after a 5s timeout
 */
object AppShutdownCoordinator {
    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
    private val shutdownToken = AtomicLong(0L)
    @Volatile
    private var shutdownJob: Job? = null

    fun cancelPendingShutdown() {
        shutdownToken.incrementAndGet()
        shutdownJob?.cancel()
        shutdownJob = null
    }

    fun requestFullShutdownAndKill(
        app: Application,
        mesh: MeshService?,
        notificationManager: NotificationManagerCompat,
        stopForeground: () -> Unit,
        stopService: () -> Unit
    ) {
        val token = shutdownToken.incrementAndGet()
        shutdownJob?.cancel()
        val job = scope.launch {
            // Signal UI to finish gracefully before we kill the process
            try {
                val intent = android.content.Intent(com.bitchat.android.util.AppConstants.UI.ACTION_FORCE_FINISH)
                    .setPackage(app.packageName)
                app.sendBroadcast(intent, com.bitchat.android.util.AppConstants.UI.PERMISSION_FORCE_FINISH)
            } catch (_: Exception) { }

            // Stop mesh (best-effort)
            try { mesh?.stopServices() } catch (_: Exception) { }
            try { com.bitchat.android.nostr.NostrRelayManager.shared.disconnect() } catch (_: Exception) { }
            try { com.bitchat.android.mesh.PowerManager.getInstance(app).shutdown() } catch (_: Exception) { }

            // Stop Tor temporarily (do not change user setting)
            val torProvider = ArtiTorManager.getInstance()
            val torStop = async {
                try { torProvider.applyMode(app, TorMode.OFF) } catch (_: Exception) { }
            }
            val conversationFlush = async {
                try {
                    com.bitchat.android.services.AppStateStore
                        .awaitConversationPersistence()
                } catch (_: Exception) { }
            }

            // Clear AppState in-memory store
            try { com.bitchat.android.services.AppStateStore.clear() } catch (_: Exception) { }

            // Stop foreground and clear notification
            try { stopForeground() } catch (_: Exception) { }
            try { notificationManager.cancel(10001) } catch (_: Exception) { }

            // Wait up to 5 seconds for shutdown tasks
            withTimeoutOrNull(5000) {
                try { torStop.await() } catch (_: Exception) { }
                try { conversationFlush.await() } catch (_: Exception) { }
                delay(100)
            }

            // Stop the service itself
            if (!isActive || shutdownToken.get() != token) return@launch
            try { stopService() } catch (_: Exception) { }

            // Hard kill the app process
            if (!isActive || shutdownToken.get() != token) return@launch
            try { Process.killProcess(Process.myPid()) } catch (_: Exception) { }
            try { System.exit(0) } catch (_: Exception) { }
        }
        shutdownJob = job
        job.invokeOnCompletion {
            if (shutdownJob === job) {
                shutdownJob = null
            }
        }
    }
}

