    }

    fun isBackgroundEnabled(default: Boolean = true): Boolean {
        return prefs.getBoolean(KEY_BACKGROUND_ENABLED, default)
    }

    fun setBackgroundEnabled(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_BACKGROUND_ENABLED, enabled).apply()
    }
}

package com.bitchat.android.service

import android.Manifest
import android.annotation.SuppressLint
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.content.ContextCompat
import androidx.core.content.edit
import com.bitchat.android.MainActivity
import com.bitchat.android.R
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

internal enum class PeerAvailabilityAction {
    NONE,
    SHOW,
    CLEAR
}

internal interface PeerAvailabilityAlertHistory {
    var lastAlertAtMillis: Long?
}

internal class SharedPreferencesPeerAvailabilityAlertHistory(
    context: Context
) : PeerAvailabilityAlertHistory {
    companion object {
        internal const val PREFERENCES_NAME = "peer_availability_notifications"
        private const val KEY_LAST_ALERT_AT_MILLIS = "last_alert_at_millis"
    }

    private val preferences =
        context.getSharedPreferences(PREFERENCES_NAME, Context.MODE_PRIVATE)

    override var lastAlertAtMillis: Long?
        get() = if (preferences.contains(KEY_LAST_ALERT_AT_MILLIS)) {
            preferences.getLong(KEY_LAST_ALERT_AT_MILLIS, 0L)
        } else {
            null
        }
        set(value) {
            preferences.edit {
                if (value == null) {
                    remove(KEY_LAST_ALERT_AT_MILLIS)
                } else {
                    putLong(KEY_LAST_ALERT_AT_MILLIS, value)
                }
            }
        }
}

/**
 * Tracks mesh availability epochs with two anti-flapping gates:
 * - no more than one alert per persisted cooldown window;
 * - after an alert, the mesh must remain empty before another epoch can re-arm.
 */
internal class PeerAvailabilityTracker(
    private val alertHistory: PeerAvailabilityAlertHistory,
    private val nowMillis: () -> Long = System::currentTimeMillis,
    private val alertCooldownMs: Long = ALERT_COOLDOWN_MS,
    private val emptyRearmDelayMs: Long = EMPTY_REARM_DELAY_MS
) {
    companion object {
        internal const val ALERT_COOLDOWN_MS = 5 * 60_000L
        internal const val EMPTY_REARM_DELAY_MS = 30_000L
    }

    private var previousPeerCount = 0
    private var isArmed = true
    private var emptySinceMillis: Long? = null

    init {
        require(alertCooldownMs >= 0) { "alertCooldownMs must not be negative" }
        require(emptyRearmDelayMs >= 0) { "emptyRearmDelayMs must not be negative" }
    }

    fun update(peerCount: Int, isAppInBackground: Boolean): PeerAvailabilityAction {
        require(peerCount >= 0) { "peerCount must not be negative" }

        val now = nowMillis()
        if (peerCount == 0) {
            if (previousPeerCount > 0 || emptySinceMillis == null) {
                emptySinceMillis = now
            }
            previousPeerCount = 0
            return PeerAvailabilityAction.CLEAR
        }

        val transitionedFromEmpty = previousPeerCount == 0
        previousPeerCount = peerCount
        if (!transitionedFromEmpty) return PeerAvailabilityAction.NONE

        if (!isArmed) {
            val emptySince = emptySinceMillis
            val remainedEmptyLongEnough =
                emptySince != null && now - emptySince >= emptyRearmDelayMs
            if (!remainedEmptyLongEnough) {
                emptySinceMillis = null
                return PeerAvailabilityAction.NONE
            }
            isArmed = true
        }
        emptySinceMillis = null

        val lastAlertAt = alertHistory.lastAlertAtMillis
        val cooldownElapsed =
            lastAlertAt == null || now - lastAlertAt >= alertCooldownMs
        return if (isAppInBackground && cooldownElapsed) {
            PeerAvailabilityAction.SHOW
        } else {
            PeerAvailabilityAction.NONE
        }
    }

    /**
     * Called only after NotificationManager accepts the post. Failed or disabled posts
     * do not consume the cooldown or require the mesh to re-arm.
     */
    fun markAlertShown() {
        alertHistory.lastAlertAtMillis = nowMillis()
        isArmed = false
    }
}

internal interface PeerAvailabilityTextProvider {
    fun title(): String
    fun body(peerCount: Int): String
}

private class AndroidPeerAvailabilityTextProvider(
    private val context: Context
) : PeerAvailabilityTextProvider {
    override fun title(): String {
        return context.getString(R.string.notification_active_peers_title)
    }

    override fun body(peerCount: Int): String {
        return if (peerCount == 1) {
            context.getString(R.string.notification_active_peers_one)
        } else {
            context.getString(R.string.notification_active_peers_many, peerCount)
        }
    }
}

/**
 * Owns the user-visible "bitchatters nearby" notification independently of the UI delegate.
 * The first eligible peer starts a fixed aggregation window; arrivals within that window update
 * the count without postponing the alert indefinitely.
 */
internal class PeerAvailabilityNotifier(
    private val context: Context,
    private val scope: CoroutineScope,
    private val notificationManager: NotificationManagerCompat =
        NotificationManagerCompat.from(context),
    private val tracker: PeerAvailabilityTracker = PeerAvailabilityTracker(
        SharedPreferencesPeerAvailabilityAlertHistory(context)
    ),
    private val textProvider: PeerAvailabilityTextProvider =
        AndroidPeerAvailabilityTextProvider(context),
    private val isAppCurrentlyInBackground: () -> Boolean,
    private val aggregationWindowMs: Long = AGGREGATION_WINDOW_MS,
    private val canPostNotifications: () -> Boolean = {
        notificationManager.areNotificationsEnabled() &&
            (
                Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU ||
                    ContextCompat.checkSelfPermission(
                        context,
                        Manifest.permission.POST_NOTIFICATIONS
                    ) == PackageManager.PERMISSION_GRANTED
                )
    }
) {
    companion object {
        internal const val CHANNEL_ID = "bitchat_peer_availability_notifications"
        internal const val NOTIFICATION_ID = 997
        internal const val AGGREGATION_WINDOW_MS = 10_000L
        private const val TAG = "PeerAvailability"
    }

    private var latestPeerCount = 0
    private var pendingNotificationJob: Job? = null

    init {
        require(aggregationWindowMs >= 0) { "aggregationWindowMs must not be negative" }
        createNotificationChannel()
    }

    fun onPeerCountChanged(peerCount: Int, isAppInBackground: Boolean) {
        latestPeerCount = peerCount
        when (tracker.update(peerCount, isAppInBackground)) {
            PeerAvailabilityAction.NONE -> Unit
            PeerAvailabilityAction.CLEAR -> clear()
            PeerAvailabilityAction.SHOW -> scheduleNotification()
        }
    }

    fun clear() {
        pendingNotificationJob?.cancel()
        pendingNotificationJob = null
        notificationManager.cancel(NOTIFICATION_ID)
    }

    private fun scheduleNotification() {
        if (pendingNotificationJob?.isActive == true) return

        pendingNotificationJob = scope.launch {
            delay(aggregationWindowMs)
            pendingNotificationJob = null

            val peerCount = latestPeerCount
            if (peerCount > 0 && isAppCurrentlyInBackground()) {
                showNotification(peerCount)
            }
        }
    }

    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            CHANNEL_ID,
            textProvider.title(),
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            enableVibration(true)
            setShowBadge(false)
        }
        val systemManager =
            context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        systemManager.createNotificationChannel(channel)
    }

    @SuppressLint("MissingPermission")
    private fun showNotification(peerCount: Int) {
        if (!canPostNotifications()) {
            Log.i(TAG, "Skipping peer availability notification because notifications are disabled")
            return
        }

        val openAppIntent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            NOTIFICATION_ID,
            openAppIntent,
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(textProvider.title())
            .setContentText(textProvider.body(peerCount))
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .setOnlyAlertOnce(true)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setCategory(NotificationCompat.CATEGORY_SOCIAL)
            .setShowWhen(true)
            .setWhen(System.currentTimeMillis())
            .build()

        try {
            notificationManager.notify(NOTIFICATION_ID, notification)
            tracker.markAlertShown()
            Log.i(TAG, "Posted peer availability notification for $peerCount peer(s)")
        } catch (error: SecurityException) {
            Log.w(TAG, "Notification permission changed before peer alert was posted", error)
        }
    }
}

package com.bitchat.android.service

import android.util.Log
import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.util.toHexString
import kotlinx.coroutines.CancellationException
import java.security.MessageDigest
import java.util.Collections
import java.util.LinkedHashMap
import java.util.concurrent.ConcurrentHashMap

/**
 * Central bridge for routing packets between different transport layers
 * (e.g., Bluetooth LE <-> Wi-Fi Aware).
 * 
 * Allows a packet received on one transport to be seamlessly relayed
 * to all other active transports, effectively bridging separate meshes.
 */
object TransportBridgeService {
    private const val TAG = "TransportBridgeService"
    private const val MAX_SEEN_PACKETS = 4096
    private const val SEEN_PACKET_TTL_MS = 5 * 60 * 1000L

    /**
     * Interface that any transport layer (BLE, WiFi, Tor, etc.) must implement
     * to receive bridged packets.
     */
    interface TransportLayer {
        /**
         * Send a packet out via this transport.
         */
        fun send(packet: RoutedPacket)

        /**
         * Send a packet and report whether at least one concrete transport write was accepted.
         *
         * Receipt retries use this path so a registered-but-disconnected transport cannot be
         * mistaken for a successful send.
         */
        suspend fun sendAndReport(packet: RoutedPacket): Boolean = false

        /**
         * Send a packet to a specific peer via this transport (optional).
         */
        fun sendToPeer(peerID: String, packet: BitchatPacket) { }
    }

    private val transports = ConcurrentHashMap<String, TransportLayer>()
    private val seenPackets = Collections.synchronizedMap(
        object : LinkedHashMap<String, Long>(MAX_SEEN_PACKETS, 0.75f, true) {
            override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, Long>?): Boolean {
                return size > MAX_SEEN_PACKETS
            }
        }
    )
    private data class PreparedForward(
        val packet: BitchatPacket,
        val seenKey: String,
        val reservedAtMs: Long
    )

    /**
     * Register a transport layer to receive bridged packets.
     * @param id Unique identifier (e.g., "BLE", "WIFI")
     * @param layer The transport implementation
     */
    fun register(id: String, layer: TransportLayer) {
        Log.i(TAG, "Registering transport layer: $id")
        transports[id] = layer
    }

    /**
     * Unregister a transport layer.
     */
    fun unregister(id: String) {
        Log.i(TAG, "Unregistering transport layer: $id")
        transports.remove(id)
    }

    /**
     * Broadcast a packet from a specific source transport to ALL other registered transports.
     * 
     * @param sourceId The ID of the transport initiating the broadcast (e.g., "BLE").
     *                 The packet will NOT be sent back to this source.
     * @param packet The packet to bridge.
     */
    fun broadcast(sourceId: String, packet: RoutedPacket) {
        val targets = transports.filterKeys { it != sourceId }
        if (targets.isEmpty()) return
        val prepared = prepareForwardedPacket("broadcast", packet.packet) ?: return
        val forwardedPacket = prepared.packet
        // Prepared private-media fragments must remain the admitted plan when
        // crossing transports, but relay TTL still has to advance on every
        // hop. TTL is excluded from the signature and does not affect size.
        val forwarded = packet.copy(
            packet = forwardedPacket,
            preparedPackets = packet.preparedPackets?.map { prepared ->
                prepared.copy(ttl = forwardedPacket.ttl)
            }
        )

        // Log.v(TAG, "Bridging packet type ${packet.packet.type} from $sourceId to ${targets.keys}")

        targets.forEach { (id, layer) ->
            try {
                layer.send(forwarded)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to bridge packet to $id: ${e.message}")
            }
        }
    }

    /**
     * Broadcasts through every other active transport and reports whether any concrete write was
     * accepted. Failed attempts release their duplicate-suppression reservation so a later retry
     * can use a transport that reconnects during the retry window.
     */
    suspend fun broadcastAndReport(sourceId: String, packet: RoutedPacket): Boolean {
        val targets = transports.filterKeys { it != sourceId }
        if (targets.isEmpty()) return false
        val kind = "broadcast"
        val prepared = prepareForwardedPacket(kind, packet.packet) ?: return false
        val forwardedPacket = prepared.packet
        val forwarded = packet.copy(
            packet = forwardedPacket,
            preparedPackets = packet.preparedPackets?.map { prepared ->
                prepared.copy(ttl = forwardedPacket.ttl)
            }
        )

        var accepted = false
        targets.forEach { (id, layer) ->
            val targetAccepted = try {
                layer.sendAndReport(forwarded)
            } catch (e: CancellationException) {
                releaseSeenPacket(prepared)
                throw e
            } catch (e: Exception) {
                Log.e(TAG, "Failed to bridge packet to $id: ${e.message}")
                false
            }
            accepted = targetAccepted || accepted
        }
        if (!accepted) {
            releaseSeenPacket(prepared)
        }
        return accepted
    }

    /**
     * Send a packet to a specific peer across all other transports.
     */
    fun sendToPeer(sourceId: String, peerID: String, packet: BitchatPacket) {
        val targets = transports.filterKeys { it != sourceId }
        if (targets.isEmpty()) return
        val forwardedPacket =
            prepareForwardedPacket("peer:$peerID", packet)?.packet ?: return

        targets.forEach { (id, layer) ->
            try {
                layer.sendToPeer(peerID, forwardedPacket)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to bridge unicast packet to $id: ${e.message}")
            }
        }
    }

    /**
     * Send a locally originated packet to every active transport without applying relay TTL
     * handling. This is used for neighbor-only packets such as REQUEST_SYNC whose TTL is
     * intentionally zero on the first radio hop.
     */
    fun broadcastFromLocal(packet: RoutedPacket) {
        val targets = transports.toMap()
        if (targets.isEmpty()) return

        targets.forEach { (id, layer) ->
            try {
                layer.send(packet)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to send local packet to $id: ${e.message}")
            }
        }
    }

    /**
     * Send a locally originated packet directly to a peer on every active transport.
     */
    fun sendToPeerFromLocal(peerID: String, packet: BitchatPacket) {
        val targets = transports.toMap()
        if (targets.isEmpty()) return

        targets.forEach { (id, layer) ->
            try {
                layer.sendToPeer(peerID, packet)
            } catch (e: Exception) {
                Log.e(TAG, "Failed to send local peer packet to $id: ${e.message}")
            }
        }
    }

    private fun prepareForwardedPacket(kind: String, packet: BitchatPacket): PreparedForward? {
        if (packet.ttl == 0u.toUByte()) {
            Log.d(TAG, "Dropping bridged packet type ${packet.type}: TTL expired")
            return null
        }

        val key = "$kind:${logicalPacketId(packet)}"
        val now = System.currentTimeMillis()
        synchronized(seenPackets) {
            pruneSeen(now)
            val previous = seenPackets[key]
            if (previous != null && now - previous < SEEN_PACKET_TTL_MS) {
                Log.d(TAG, "Dropping duplicate bridged packet type ${packet.type}")
                return null
            }
            seenPackets[key] = now
        }

        return PreparedForward(
            packet = packet.copy(ttl = (packet.ttl - 1u).toUByte()),
            seenKey = key,
            reservedAtMs = now
        )
    }

    private fun releaseSeenPacket(prepared: PreparedForward) {
        synchronized(seenPackets) {
            if (seenPackets[prepared.seenKey] == prepared.reservedAtMs) {
                seenPackets.remove(prepared.seenKey)
            }
        }
    }

    private fun pruneSeen(now: Long) {
        val iterator = seenPackets.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (now - entry.value > SEEN_PACKET_TTL_MS) {
                iterator.remove()
            }
        }
    }

    private fun logicalPacketId(packet: BitchatPacket): String {
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(packet.type.toByte())
        digest.update(packet.senderID)
        packet.recipientID?.let { digest.update(it) }
        digest.update(packet.timestamp.toString().toByteArray(Charsets.UTF_8))
        digest.update(packet.payload)
        packet.route?.forEach { digest.update(it) }
        packet.signature?.let { digest.update(it) }
        return digest.digest().toHexString()
    }
}

package com.bitchat.android.services

import android.content.Context
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.DeliveryStatus
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Process-wide in-memory state store that survives Activity recreation.
 * The foreground Mesh service updates this store; UI subscribes/hydrates from it.
 */
object AppStateStore {
    // Global de-dup set by message id to avoid duplicate keys in Compose lists
    private val seenMessageIds = mutableSetOf<String>()
    private val reservedPrivateMessageIds = mutableSetOf<String>()
    private val seenPublicMessageKeys = mutableSetOf<String>()
    private val peerIdsByTransport = mutableMapOf<String, Set<String>>()
    private var privateWritesSinceGlobalPrune = 0
    // Direct (single-hop) peer IDs per transport, used to gossip a unified neighbor set.
    private val directPeerIdsByTransport = mutableMapOf<String, Set<String>>()
    private val _directPeers = MutableStateFlow<Set<String>>(emptySet())
    val directPeers: StateFlow<Set<String>> = _directPeers.asStateFlow()
    // Connected peer IDs (mesh ephemeral IDs)
    private val _peers = MutableStateFlow<List<String>>(emptyList())
    val peers: StateFlow<List<String>> = _peers.asStateFlow()

    // Public mesh timeline messages (non-channel)
    private val _publicMessages = MutableStateFlow<List<BitchatMessage>>(emptyList())
    val publicMessages: StateFlow<List<BitchatMessage>> = _publicMessages.asStateFlow()

    // Private messages by peerID
    private val _privateMessages = MutableStateFlow<Map<String, List<BitchatMessage>>>(emptyMap())
    val privateMessages: StateFlow<Map<String, List<BitchatMessage>>> = _privateMessages.asStateFlow()
    private val _readPrivateMessageIDs = MutableStateFlow<Set<String>>(emptySet())
    val readPrivateMessageIDs: StateFlow<Set<String>> = _readPrivateMessageIDs.asStateFlow()
    private val _unreadPrivateMessageCounts = MutableStateFlow<Map<String, Int>>(emptyMap())
    val unreadPrivateMessageCounts: StateFlow<Map<String, Int>> =
        _unreadPrivateMessageCounts.asStateFlow()
    private val _privateConversationDisplayNames =
        MutableStateFlow<Map<String, String>>(emptyMap())
    val privateConversationDisplayNames: StateFlow<Map<String, String>> =
        _privateConversationDisplayNames.asStateFlow()

    @Volatile
    private var conversationRepository: ConversationRepository? = null
    private var privateConversationWritesSuspended = false
    private var privateConversationGeneration = 0L

    private val _nickname = MutableStateFlow("")
    val nickname: StateFlow<String> = _nickname.asStateFlow()

    private val _selectedPrivateChatPeer = MutableStateFlow<String?>(null)
    val selectedPrivateChatPeer: StateFlow<String?> = _selectedPrivateChatPeer.asStateFlow()

    // Channel messages by channel name
    private val _channelMessages = MutableStateFlow<Map<String, List<BitchatMessage>>>(emptyMap())
    val channelMessages: StateFlow<Map<String, List<BitchatMessage>>> = _channelMessages.asStateFlow()

    fun setPeers(ids: List<String>) {
        synchronized(this) {
            _peers.value = ids.distinct()
        }
    }

    fun setNickname(nickname: String) {
        _nickname.value = nickname
    }

    fun setSelectedPrivateChatPeer(peerID: String?) {
        _selectedPrivateChatPeer.value = peerID
    }

    fun initializeConversationPersistence(context: Context) {
        val repository = ConversationRepository.getInstance(context.applicationContext)
        conversationRepository = repository
        repository.initialize(::restorePrivateConversations)
    }

    /**
     * Restores database state again for a newly created UI, even if Android reused this process
     * after a controlled shutdown cleared the process-wide state.
     */
    fun reloadConversationPersistence(context: Context) {
        val repository = ConversationRepository.getInstance(context.applicationContext)
        conversationRepository = repository
        repository.reload(::restorePrivateConversations)
    }

    internal fun setConversationRepositoryForTest(repository: ConversationRepository?) {
        conversationRepository = repository
    }

    suspend fun awaitConversationPersistence() {
        conversationRepository?.awaitPendingWrites()
    }

    suspend fun loadPrivateConversationHistory(conversationID: String): Boolean {
        val repository = conversationRepository ?: return false
        val snapshot = repository.loadConversationAndWait(
            ContactDirectory.canonicalConversationId(conversationID)
        ) ?: return false
        restorePrivateConversations(snapshot)
        return true
    }

    /**
     * Drops an opened conversation's full payloads from memory while retaining its summary row.
     * The complete bounded history remains encrypted in SQLite and is loaded again on demand.
     */
    fun releasePrivateConversationHistory(conversationID: String) {
        synchronized(this) {
            val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
            val matching = _privateMessages.value.entries.filter { (id, _) ->
                ContactDirectory.canonicalConversationId(id)
                    .equals(canonicalID, ignoreCase = true)
            }
            val latest = matching
                .flatMap { it.value }
                .distinctBy { it.id }
                .maxWithOrNull(
                    compareBy<BitchatMessage> {
                        PrivateMessageArrivalOrder.sequenceOf(it.id) ?: Long.MIN_VALUE
                    }.thenBy { it.timestamp.time }
                )
                ?: return
            val compacted = _privateMessages.value.toMutableMap()
            matching.forEach { compacted.remove(it.key) }
            compacted[canonicalID] = listOf(latest)
            _privateMessages.value = compacted
        }
    }

    val conversationStoreState: StateFlow<ConversationStoreState>
        get() = conversationRepository?.storeState ?: EMPTY_CONVERSATION_STORE_STATE

    fun setTransportPeers(transportId: String, ids: List<String>) {
        synchronized(this) {
            peerIdsByTransport[transportId] = ids.toSet()
            publishTransportPeersLocked()
        }
    }

    fun clearTransportPeers(transportId: String) {
        synchronized(this) {
            peerIdsByTransport.remove(transportId)
            publishTransportPeersLocked()
        }
    }

    private fun publishTransportPeersLocked() {
        _peers.value = peerIdsByTransport.values
            .asSequence()
            .flatten()
            .distinct()
            .toList()
    }

    /**
     * Record the set of direct (single-hop) peers reachable over a given transport. Each transport
     * (BLE, Wi-Fi Aware, ...) only knows its own direct peers; [getDirectPeers] unions them so every
     * transport can gossip the same complete neighbor list under our shared node identity.
     */
    fun setTransportDirectPeers(transportId: String, ids: Collection<String>) {
        synchronized(this) {
            directPeerIdsByTransport[transportId] = ids.toSet()
            publishDirectPeersLocked()
        }
    }

    fun clearTransportDirectPeers(transportId: String) {
        synchronized(this) {
            directPeerIdsByTransport.remove(transportId)
            publishDirectPeersLocked()
        }
    }

    /** Union of direct peers across all transports. */
    fun getDirectPeers(): Set<String> = _directPeers.value

    private fun publishDirectPeersLocked() {
        _directPeers.value = directPeerIdsByTransport.values
            .asSequence()
            .flatten()
            .toSet()
    }

    fun addPublicMessage(msg: BitchatMessage) {
        synchronized(this) {
            val publicKey = publicMessageKey(msg)
            if (seenMessageIds.contains(msg.id) || seenPublicMessageKeys.contains(publicKey)) return
            seenMessageIds.add(msg.id)
            seenPublicMessageKeys.add(publicKey)
            _publicMessages.value = _publicMessages.value + msg
        }
    }

    /** Replace a live media row by ID, or append it if the row was not admitted yet. */
    fun upsertPublicMessage(msg: BitchatMessage) {
        synchronized(this) {
            val index = _publicMessages.value.indexOfFirst { it.id == msg.id }
            if (index >= 0) {
                _publicMessages.value = _publicMessages.value.toMutableList().also { it[index] = msg }
            } else {
                seenMessageIds.add(msg.id)
                seenPublicMessageKeys.add(publicMessageKey(msg))
                _publicMessages.value = _publicMessages.value + msg
            }
        }
    }

    fun removePublicMessage(messageID: String) {
        synchronized(this) {
            val existing = _publicMessages.value.firstOrNull { it.id == messageID } ?: return
            _publicMessages.value = _publicMessages.value.filterNot { it.id == messageID }
            seenMessageIds.remove(messageID)
            seenPublicMessageKeys.remove(publicMessageKey(existing))
        }
    }

    fun addPrivateMessage(
        peerID: String,
        msg: BitchatMessage,
        forceRead: Boolean = false
    ): Boolean = synchronized(this) {
        addPrivateMessageLocked(peerID, msg, forceRead, persistAsynchronously = true)
    }

    /** Replace-or-append used by a live voice row as its partial file becomes final media. */
    fun upsertPrivateMessage(peerID: String, msg: BitchatMessage, forceRead: Boolean = false) {
        synchronized(this) {
            if (privateConversationWritesSuspended) return
            val canonicalID = ContactDirectory.canonicalConversationId(peerID)
            val map = _privateMessages.value.toMutableMap()
            val matchingKey = map.keys.firstOrNull {
                ContactDirectory.canonicalConversationId(it).equals(canonicalID, ignoreCase = true)
            } ?: canonicalID
            val messages = map[matchingKey].orEmpty().toMutableList()
            val index = messages.indexOfFirst { it.id == msg.id }
            if (index >= 0) {
                messages[index] = msg
            } else {
                messages += msg
                seenMessageIds.add(msg.id)
            }
            map[matchingKey] = messages
            _privateMessages.value = ContactDirectory.canonicalizePrivateChats(map)
            if (forceRead) {
                _readPrivateMessageIDs.value = _readPrivateMessageIDs.value + msg.id
            }
            conversationRepository?.upsertMessage(
                conversationID = canonicalID,
                aliases = privateConversationAliases(peerID, canonicalID),
                displayName = ContactDirectory.resolve(canonicalID).displayName,
                message = msg,
                isRead = forceRead
            )
        }
    }

    /**
     * Persists an incoming private message before it is admitted to UI, unread, haptic, or
     * notification state. Transport callbacks invoke this from their background worker.
     */
    suspend fun addPrivateMessageDurably(
        peerID: String,
        msg: BitchatMessage,
        forceRead: Boolean = false
    ): Boolean {
        val persistence = synchronized(this) {
            if (privateConversationWritesSuspended) return false
            if (seenMessageIds.contains(msg.id) || !reservedPrivateMessageIds.add(msg.id)) {
                return false
            }
            privateMessagePersistence(peerID, msg, forceRead)
        }
        val repository = persistence.repository
        if (repository == null) {
            synchronized(this) { reservedPrivateMessageIds.remove(msg.id) }
            return false
        }
        val persisted = repository.upsertMessageAndWait(
            conversationID = persistence.conversationID,
            aliases = persistence.aliases,
            displayName = persistence.displayName,
            message = msg,
            isRead = persistence.isRead
        )
        return synchronized(this) {
            reservedPrivateMessageIds.remove(msg.id)
            if (
                !persisted ||
                privateConversationWritesSuspended ||
                persistence.generation != privateConversationGeneration ||
                seenMessageIds.contains(msg.id)
            ) {
                return@synchronized false
            }
            addPrivateMessageLocked(
                peerID = peerID,
                msg = msg,
                forceRead = forceRead,
                persistAsynchronously = false
            )
        }
    }

    private fun addPrivateMessageLocked(
        peerID: String,
        msg: BitchatMessage,
        forceRead: Boolean,
        persistAsynchronously: Boolean
    ): Boolean {
        if (privateConversationWritesSuspended) return false
        if (seenMessageIds.contains(msg.id)) return false
        seenMessageIds.add(msg.id)
        PrivateMessageArrivalOrder.record(msg.id)
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val map = _privateMessages.value.toMutableMap()
        val list = (map[conversationID] ?: emptyList()) + msg
        map[conversationID] = list
        _privateMessages.value = ContactDirectory.canonicalizePrivateChats(map)

        val isRead = forceRead ||
            msg.sender == "system" ||
            msg.sender == _nickname.value ||
            _selectedPrivateChatPeer.value
                ?.let(ContactDirectory::canonicalConversationId)
                ?.equals(conversationID, ignoreCase = true) == true
        if (isRead) {
            _readPrivateMessageIDs.value = _readPrivateMessageIDs.value + msg.id
        } else {
            val counts = _unreadPrivateMessageCounts.value.toMutableMap()
            counts[conversationID] = (counts[conversationID] ?: 0) + 1
            _unreadPrivateMessageCounts.value = counts
        }
        val aliases = privateConversationAliases(peerID, conversationID)
        val displayName = ContactDirectory.resolve(conversationID).displayName
            ?: msg.sender.takeUnless {
                it.isBlank() || it == "system" || it == _nickname.value
            }
        displayName
            ?.takeUnless {
                it.isBlank() || it.equals("Unknown", ignoreCase = true)
            }
            ?.let { updateConversationDisplayNameLocked(conversationID, it) }
        if (persistAsynchronously) {
            conversationRepository?.upsertMessage(
                conversationID = conversationID,
                aliases = aliases,
                displayName = displayName,
                message = msg,
                isRead = isRead
            )
        }
        prunePrivateMessagesLocked(conversationID)
        return true
    }

    private fun privateMessagePersistence(
        peerID: String,
        msg: BitchatMessage,
        forceRead: Boolean
    ): PendingPrivateMessagePersistence {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val existingMessages = _privateMessages.value[conversationID].orEmpty()
        val isRead = forceRead ||
            msg.sender == "system" ||
            msg.sender == _nickname.value ||
            _selectedPrivateChatPeer.value
                ?.let(ContactDirectory::canonicalConversationId)
                ?.equals(conversationID, ignoreCase = true) == true
        val aliases = privateConversationAliases(peerID, conversationID)
        val displayName = ContactDirectory.resolve(conversationID).displayName
            ?: (existingMessages + msg)
                .lastOrNull { candidate ->
                    candidate.sender.isNotBlank() &&
                        candidate.sender != "system" &&
                        candidate.sender != _nickname.value
                }
                ?.sender
        return PendingPrivateMessagePersistence(
            repository = conversationRepository,
            conversationID = conversationID,
            aliases = aliases,
            displayName = displayName,
            isRead = isRead,
            generation = privateConversationGeneration
        )
    }

    /**
     * Derive aliases from the routed conversation, never from the message author.
     *
     * For outgoing messages senderPeerID is our own ID, which is shared by every private chat.
     * Persisting it as an alias would merge otherwise unrelated conversation histories.
     */
    private fun privateConversationAliases(
        peerID: String,
        conversationID: String
    ): Set<String> = runCatching {
        ContactDirectory.aliasesForConversation(peerID) +
            ContactDirectory.aliasesForConversation(conversationID)
    }.getOrDefault(setOf(peerID, conversationID))

    fun hasSeenMessage(messageID: String): Boolean = synchronized(this) {
        messageID in seenMessageIds
    }

    private fun statusPriority(status: DeliveryStatus?): Int = when (status) {
        null -> 0
        is DeliveryStatus.Sending -> 1
        is DeliveryStatus.Sent -> 2
        is DeliveryStatus.PartiallyDelivered -> 3
        is DeliveryStatus.Delivered -> 4
        is DeliveryStatus.Read -> 5
        is DeliveryStatus.Failed -> 0
    }

    fun updatePrivateMessageStatus(messageID: String, status: DeliveryStatus) {
        synchronized(this) {
            if (privateConversationWritesSuspended) return
            val map = _privateMessages.value.toMutableMap()
            var changed = false
            map.keys.toList().forEach { peer ->
                val list = map[peer]?.toMutableList() ?: mutableListOf()
                val idx = list.indexOfFirst { it.id == messageID }
                if (idx >= 0) {
                    val current = list[idx].deliveryStatus
                    // Do not downgrade (e.g., Read -> Delivered)
                    val mayReplace = when {
                        status is DeliveryStatus.Failed ->
                            current !is DeliveryStatus.Delivered &&
                                current !is DeliveryStatus.Read
                        current is DeliveryStatus.Failed -> true
                        else -> statusPriority(status) >= statusPriority(current)
                    }
                    if (mayReplace) {
                        list[idx] = list[idx].copy(deliveryStatus = status)
                        map[peer] = list
                        changed = true
                    }
                }
            }
            if (changed) {
                _privateMessages.value = map
            }
            // Full histories are unloaded after a chat closes, so the message may only exist in
            // SQLite. Always offer the update to the repository; it safely ignores unknown IDs
            // and enforces the same monotonic status rules as the in-memory path.
            conversationRepository?.updateDeliveryStatus(messageID, status)
        }
    }

    fun unifyPrivateChatsIntoPeer(targetPeerID: String, keysToMerge: List<String>) {
        if (keysToMerge.isEmpty()) return
        synchronized(this) {
            if (privateConversationWritesSuspended) return
            val targetConversationID = ContactDirectory.canonicalConversationId(targetPeerID)
            val persistenceAliases = (keysToMerge + targetPeerID + targetConversationID)
                .flatMap { key ->
                    runCatching {
                        ContactDirectory.aliasesForConversation(key).toList()
                    }.getOrDefault(listOf(key))
                }
                .toSet()
            conversationRepository?.mergeAliases(targetConversationID, persistenceAliases)
            val map = _privateMessages.value.toMutableMap()
            val targetList = (map[targetConversationID] ?: emptyList()).toMutableList()
            val targetIds = targetList.map { it.id }.toMutableSet()
            var changed = false

            keysToMerge.distinct().forEach { key ->
                val canonicalKey = ContactDirectory.canonicalConversationId(key)
                if (canonicalKey == targetConversationID) {
                    val messages = map.remove(key)
                    if (messages != null) {
                        changed = true
                        messages.forEach { message ->
                            if (targetIds.add(message.id)) targetList.add(message)
                        }
                    }
                    return@forEach
                }
                if (key == targetConversationID) return@forEach
                val messages = map.remove(key) ?: return@forEach
                changed = true
                messages.forEach { message ->
                    if (targetIds.add(message.id)) {
                        targetList.add(message)
                    }
                }
            }

            if (changed) {
                if (targetList.isEmpty()) {
                    map.remove(targetConversationID)
                } else {
                    map[targetConversationID] = targetList
                }
                _privateMessages.value = map
            }
            canonicalizePrivateConversationStateLocked()
        }
    }

    fun canonicalizePrivateChats() {
        synchronized(this) {
            canonicalizePrivateConversationStateLocked()
        }
    }

    /**
     * Applies current peer announcements to retained conversations and persists the latest name
     * independently of message history. A nickname change must not require another message to
     * survive process death.
     */
    fun updatePrivateConversationDisplayNames(peerNicknames: Map<String, String>) {
        if (peerNicknames.isEmpty()) return
        synchronized(this) {
            if (privateConversationWritesSuspended || _privateMessages.value.isEmpty()) return
            canonicalizePrivateConversationStateLocked()
            val conversationIDs = _privateMessages.value.keys
                .mapTo(mutableSetOf()) { it.lowercase() }
            peerNicknames.forEach { (peerID, nickname) ->
                val usableName = nickname.takeUnless {
                    it.isBlank() || it.equals("Unknown", ignoreCase = true)
                } ?: return@forEach
                val canonicalID = ContactDirectory.canonicalConversationId(peerID)
                if (canonicalID.lowercase() !in conversationIDs) {
                    return@forEach
                }
                updateConversationDisplayNameLocked(canonicalID, usableName)
                val aliases = runCatching {
                    ContactDirectory.aliasesForConversation(peerID) +
                        ContactDirectory.aliasesForConversation(canonicalID)
                }.getOrDefault(setOf(peerID, canonicalID))
                conversationRepository?.updateConversationIdentity(
                    conversationID = canonicalID,
                    aliases = aliases,
                    displayName = usableName
                )
            }
        }
    }

    fun markPrivateMessageRead(messageID: String) {
        synchronized(this) {
            if (privateConversationWritesSuspended) return
            if (messageID in _readPrivateMessageIDs.value) return
            canonicalizePrivateConversationStateLocked()
            _readPrivateMessageIDs.value = _readPrivateMessageIDs.value + messageID
            val conversationID = _privateMessages.value.entries
                .firstOrNull { (_, messages) -> messages.any { it.id == messageID } }
                ?.key
            if (conversationID != null) {
                val counts = _unreadPrivateMessageCounts.value.toMutableMap()
                val remaining = ((counts[conversationID] ?: 0) - 1).coerceAtLeast(0)
                if (remaining == 0) counts.remove(conversationID) else {
                    counts[conversationID] = remaining
                }
                _unreadPrivateMessageCounts.value = counts
            }
            conversationRepository?.markRead(messageID)
        }
    }

    fun isPrivateMessageRead(messageID: String): Boolean =
        messageID in _readPrivateMessageIDs.value

    suspend fun setPrivateConversationRead(
        conversationID: String,
        isRead: Boolean
    ): Boolean {
        val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
        val repository = conversationRepository ?: return false
        val result = repository.setConversationReadAndWait(canonicalID, isRead)
        if (!result.success) return false
        synchronized(this) {
            val messageIDs = _privateMessages.value
                .filterKeys { key ->
                    ContactDirectory.canonicalConversationId(key)
                        .equals(canonicalID, ignoreCase = true)
                }
                .values
                .flatten()
                .mapTo(linkedSetOf(), BitchatMessage::id)
            if (isRead) {
                _readPrivateMessageIDs.value = _readPrivateMessageIDs.value + messageIDs
                _unreadPrivateMessageCounts.value =
                    _unreadPrivateMessageCounts.value.filterKeys { key ->
                        !ContactDirectory.canonicalConversationId(key)
                            .equals(canonicalID, ignoreCase = true)
                    }
            } else {
                result.affectedMessageID?.let { latestMessageID ->
                    _readPrivateMessageIDs.value =
                        _readPrivateMessageIDs.value - latestMessageID
                    _unreadPrivateMessageCounts.value =
                        _unreadPrivateMessageCounts.value + (canonicalID to 1)
                }
            }
        }
        return true
    }

    fun deletePrivateConversation(peerOrConversationID: String): Set<String> {
        synchronized(this) {
            val canonicalID = ContactDirectory.canonicalConversationId(peerOrConversationID)
            val matchingKeys = _privateMessages.value.keys.filterTo(linkedSetOf()) { key ->
                ContactDirectory.canonicalConversationId(key)
                    .equals(canonicalID, ignoreCase = true)
            }
            val aliases = (matchingKeys + peerOrConversationID + canonicalID)
                .flatMap { key ->
                    runCatching {
                        ContactDirectory.aliasesForConversation(key).toList()
                    }.getOrDefault(listOf(key))
                }
                .toSet()
            val messageIDs = matchingKeys
                .flatMapTo(linkedSetOf()) { _privateMessages.value[it].orEmpty().map { it.id } }

            // Queue the database deletion while holding the same lock used by addPrivateMessage.
            // A genuinely new arrival is therefore queued after the delete and starts a fresh chat.
            conversationRepository?.deleteConversation(canonicalID, aliases)

            val updated = _privateMessages.value.toMutableMap()
            matchingKeys.forEach(updated::remove)
            _privateMessages.value = updated
            removeConversationDisplayNamesLocked(canonicalID)
            _readPrivateMessageIDs.value = _readPrivateMessageIDs.value - messageIDs
            _unreadPrivateMessageCounts.value =
                _unreadPrivateMessageCounts.value - matchingKeys - canonicalID
            if (
                _selectedPrivateChatPeer.value
                    ?.let(ContactDirectory::canonicalConversationId)
                    ?.equals(canonicalID, ignoreCase = true) == true
            ) {
                _selectedPrivateChatPeer.value = null
            }
            return messageIDs
        }
    }

    internal suspend fun deletePrivateConversationAndWait(
        peerOrConversationID: String
    ): DeletedPrivateConversation? {
        loadPrivateConversationHistory(peerOrConversationID)
        val deletion = synchronized(this) {
            if (privateConversationWritesSuspended) return null
            buildDeletedConversationLocked(peerOrConversationID)
        }
        val repository = conversationRepository ?: return null
        if (!repository.deleteConversationAndWait(deletion.conversationID, deletion.aliases)) {
            return null
        }
        synchronized(this) {
            val updated = _privateMessages.value.toMutableMap()
            updated.keys.toList().forEach { key ->
                if (
                    ContactDirectory.canonicalConversationId(key)
                        .equals(deletion.conversationID, ignoreCase = true)
                ) {
                    val remaining = updated[key].orEmpty().filterNot {
                        it.id in deletion.messageIDs
                    }
                    if (remaining.isEmpty()) updated.remove(key) else updated[key] = remaining
                }
            }
            _privateMessages.value = updated
            removeConversationDisplayNamesLocked(deletion.conversationID)
            _readPrivateMessageIDs.value =
                _readPrivateMessageIDs.value - deletion.messageIDs
            canonicalizePrivateConversationStateLocked()
            val counts = _unreadPrivateMessageCounts.value.toMutableMap()
            val currentCount = counts[deletion.conversationID] ?: 0
            val remainingUnread = (currentCount - deletion.unreadMessageCount).coerceAtLeast(0)
            if (remainingUnread == 0) counts.remove(deletion.conversationID) else {
                counts[deletion.conversationID] = remainingUnread
            }
            _unreadPrivateMessageCounts.value = counts
            if (
                _selectedPrivateChatPeer.value
                    ?.let(ContactDirectory::canonicalConversationId)
                    ?.equals(deletion.conversationID, ignoreCase = true) == true
            ) {
                _selectedPrivateChatPeer.value = null
            }
        }
        return deletion
    }

    internal suspend fun restoreDeletedConversation(
        deletion: DeletedPrivateConversation
    ): Boolean {
        val repository = conversationRepository ?: return false
        val restoredDisplayName =
            ContactDirectory.resolve(deletion.conversationID).displayName
                ?: deletion.displayName
        if (
            !repository.restoreConversationAndWait(
                conversationID = deletion.conversationID,
                aliases = deletion.aliases,
                displayName = restoredDisplayName,
                messages = deletion.messages,
                readMessageIDs = deletion.readMessageIDs
            )
        ) {
            return false
        }
        synchronized(this) {
            seenMessageIds.removeAll(deletion.messageIDs)
            deletion.messages.forEach { message ->
                addPrivateMessageLocked(
                    peerID = deletion.conversationID,
                    msg = message,
                    forceRead = message.id in deletion.readMessageIDs,
                    persistAsynchronously = false
                )
            }
            restoredDisplayName?.let {
                updateConversationDisplayNameLocked(deletion.conversationID, it)
            }
        }
        return true
    }

    private fun buildDeletedConversationLocked(
        peerOrConversationID: String
    ): DeletedPrivateConversation {
        val canonicalID = ContactDirectory.canonicalConversationId(peerOrConversationID)
        val matchingKeys = _privateMessages.value.keys.filterTo(linkedSetOf()) { key ->
            ContactDirectory.canonicalConversationId(key)
                .equals(canonicalID, ignoreCase = true)
        }
        val aliases = (matchingKeys + peerOrConversationID + canonicalID)
            .flatMap { key ->
                runCatching {
                    ContactDirectory.aliasesForConversation(key).toList()
                }.getOrDefault(listOf(key))
            }
            .toSet()
        val messages = matchingKeys
            .flatMap { _privateMessages.value[it].orEmpty() }
            .distinctBy(BitchatMessage::id)
        val messageIDs = messages.mapTo(linkedSetOf(), BitchatMessage::id)
        val readIDs = _readPrivateMessageIDs.value.intersect(messageIDs)
        return DeletedPrivateConversation(
            conversationID = canonicalID,
            aliases = aliases,
            displayName = _privateConversationDisplayNames.value.entries
                .firstOrNull { (key, _) ->
                    ContactDirectory.canonicalConversationId(key)
                        .equals(canonicalID, ignoreCase = true)
                }
                ?.value
                ?: ContactDirectory.resolve(canonicalID).displayName,
            messages = messages,
            readMessageIDs = readIDs,
            unreadMessageCount = messages.count { message ->
                message.id !in readIDs &&
                    message.sender != "system" &&
                    message.sender != _nickname.value
            }
        )
    }

    fun removePrivateMessage(messageID: String) {
        synchronized(this) {
            val updated = _privateMessages.value.toMutableMap()
            var changed = false
            updated.keys.toList().forEach { conversationID ->
                val messages = updated[conversationID].orEmpty()
                if (messages.any { it.id == messageID }) {
                    val remaining = messages.filterNot { it.id == messageID }
                    if (remaining.isEmpty()) {
                        updated.remove(conversationID)
                    } else {
                        updated[conversationID] = remaining
                    }
                    changed = true
                }
            }
            if (!changed) return
            conversationRepository?.deleteMessage(messageID)
            _privateMessages.value = updated
            val retainedConversationIDs = updated.keys
                .mapTo(mutableSetOf()) {
                    ContactDirectory.canonicalConversationId(it).lowercase()
                }
            _privateConversationDisplayNames.value =
                _privateConversationDisplayNames.value.filterKeys {
                    ContactDirectory.canonicalConversationId(it).lowercase() in
                        retainedConversationIDs
                }
            _readPrivateMessageIDs.value = _readPrivateMessageIDs.value - messageID
        }
    }

    /**
     * Atomically hides all conversations, rejects in-flight transport deliveries, then waits for
     * every earlier database write and the panic wipe itself to finish.
     */
    suspend fun panicClearPrivateConversations(): Boolean {
        val repository = synchronized(this) {
            privateConversationWritesSuspended = true
            privateConversationGeneration += 1
            _privateMessages.value = emptyMap()
            _readPrivateMessageIDs.value = emptySet()
            _unreadPrivateMessageCounts.value = emptyMap()
            _privateConversationDisplayNames.value = emptyMap()
            _selectedPrivateChatPeer.value = null
            conversationRepository
        }
        return repository?.clearAllAndWait() ?: true
    }

    fun resumePrivateConversationsAfterPanic() {
        synchronized(this) {
            privateConversationWritesSuspended = false
        }
    }

    fun addChannelMessage(channel: String, msg: BitchatMessage) {
        synchronized(this) {
            if (seenMessageIds.contains(msg.id)) return
            seenMessageIds.add(msg.id)
            val map = _channelMessages.value.toMutableMap()
            val list = (map[channel] ?: emptyList()) + msg
            map[channel] = list
            _channelMessages.value = map
        }
    }

    // Clear all in-memory state (used for full app shutdown)
    fun clear() {
        synchronized(this) {
            seenMessageIds.clear()
            reservedPrivateMessageIds.clear()
            privateConversationGeneration += 1
            seenPublicMessageKeys.clear()
            PrivateMessageArrivalOrder.clear()
            privateWritesSinceGlobalPrune = 0
            peerIdsByTransport.clear()
            directPeerIdsByTransport.clear()
            _peers.value = emptyList()
            _directPeers.value = emptySet()
            _publicMessages.value = emptyList()
            _privateMessages.value = emptyMap()
            _readPrivateMessageIDs.value = emptySet()
            _unreadPrivateMessageCounts.value = emptyMap()
            _privateConversationDisplayNames.value = emptyMap()
            _channelMessages.value = emptyMap()
            _nickname.value = ""
            _selectedPrivateChatPeer.value = null
        }
    }

    private fun publicMessageKey(msg: BitchatMessage): String {
        val sender = msg.senderPeerID ?: msg.sender
        return listOf(
            sender,
            msg.timestamp.time.toString(),
            msg.type.name,
            msg.channel ?: "",
            msg.content
        ).joinToString("\u001F")
    }

    internal fun restorePrivateConversations(snapshot: PersistedConversationSnapshot) {
        synchronized(this) {
            if (privateConversationWritesSuspended) return
            val liveChats = _privateMessages.value
            val liveMessageIDs = liveChats.values.flatten().map { it.id }
            PrivateMessageArrivalOrder.restore(
                snapshot.arrivalOrder,
                liveMessageIDs,
                snapshot.receivedAtByMessageID,
                snapshot.arrivalSequenceByMessageID
            )

            val merged = linkedMapOf<String, MutableList<BitchatMessage>>()
            snapshot.chats.forEach { (conversationID, messages) ->
                merged.getOrPut(conversationID) { mutableListOf() }.addAll(messages)
            }
            liveChats.forEach { (conversationID, messages) ->
                val target = merged.getOrPut(conversationID) { mutableListOf() }
                messages
                    .filterNot { it.id in snapshot.deletedMessageIDs }
                    .forEach { live ->
                        val existingIndex = target.indexOfFirst { it.id == live.id }
                        if (existingIndex >= 0) {
                            target[existingIndex] = live
                        } else {
                            target.add(live)
                        }
                    }
            }

            merged.values.flatten().forEach { seenMessageIds.add(it.id) }
            seenMessageIds.addAll(snapshot.deletedMessageIDs)
            _readPrivateMessageIDs.value =
                (snapshot.readMessageIDs + _readPrivateMessageIDs.value) -
                    snapshot.deletedMessageIDs
            val unreadCounts = _unreadPrivateMessageCounts.value.toMutableMap()
            snapshot.unreadCounts.forEach { (conversationID, count) ->
                if (count > 0) unreadCounts[conversationID] = count
                else unreadCounts.remove(conversationID)
            }
            _unreadPrivateMessageCounts.value = unreadCounts
            _privateConversationDisplayNames.value =
                snapshot.displayNames + _privateConversationDisplayNames.value
            _privateMessages.value = ContactDirectory.canonicalizePrivateChats(
                merged.mapValues { (_, messages) ->
                    PrivateMessageArrivalOrder.order(messages.distinctBy { it.id })
                }
            )
            canonicalizePrivateConversationStateLocked()
        }
    }

    private fun updateConversationDisplayNameLocked(
        conversationID: String,
        displayName: String
    ) {
        val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
        val updated = _privateConversationDisplayNames.value
            .filterKeys { key ->
                !ContactDirectory.canonicalConversationId(key)
                    .equals(canonicalID, ignoreCase = true)
            }
            .toMutableMap()
        updated[canonicalID] = displayName
        _privateConversationDisplayNames.value = updated
    }

    private fun removeConversationDisplayNamesLocked(conversationID: String) {
        val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
        _privateConversationDisplayNames.value =
            _privateConversationDisplayNames.value.filterKeys { key ->
                !ContactDirectory.canonicalConversationId(key)
                    .equals(canonicalID, ignoreCase = true)
            }
    }

    /**
     * Identity mappings can become richer after a Noise handshake or favorite/Nostr update.
     * Keep every process-wide projection on the same canonical key so unread/read/delete updates
     * cannot leave a stale alias behind.
     */
    private fun canonicalizePrivateConversationStateLocked() {
        val canonicalChats = ContactDirectory.canonicalizePrivateChats(_privateMessages.value)
        if (canonicalChats != _privateMessages.value) {
            _privateMessages.value = canonicalChats
        }

        val canonicalUnreadCounts = linkedMapOf<String, Int>()
        _unreadPrivateMessageCounts.value.forEach { (conversationID, count) ->
            if (count <= 0) return@forEach
            val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
            canonicalUnreadCounts[canonicalID] =
                (canonicalUnreadCounts[canonicalID] ?: 0) + count
        }
        if (canonicalUnreadCounts != _unreadPrivateMessageCounts.value) {
            _unreadPrivateMessageCounts.value = canonicalUnreadCounts
        }

        val canonicalDisplayNames = linkedMapOf<String, String>()
        _privateConversationDisplayNames.value.forEach { (conversationID, displayName) ->
            if (displayName.isBlank()) return@forEach
            canonicalDisplayNames[
                ContactDirectory.canonicalConversationId(conversationID)
            ] = displayName
        }
        if (canonicalDisplayNames != _privateConversationDisplayNames.value) {
            _privateConversationDisplayNames.value = canonicalDisplayNames
        }

        _selectedPrivateChatPeer.value?.let { selected ->
            val canonicalSelected = ContactDirectory.canonicalConversationId(selected)
            if (canonicalSelected != selected) {
                _selectedPrivateChatPeer.value = canonicalSelected
            }
        }
    }

    private fun prunePrivateMessagesLocked(recentConversationID: String) {
        val chats = _privateMessages.value.toMutableMap()
        val removedIDs = linkedSetOf<String>()
        val recentKey = chats.keys.firstOrNull { key ->
            ContactDirectory.canonicalConversationId(key)
                .equals(recentConversationID, ignoreCase = true)
        }
        if (recentKey != null) {
            val messages = chats[recentKey].orEmpty()
            val excess =
                messages.size - ConversationDatabase.MAX_MESSAGES_PER_CONVERSATION
            if (excess > 0) {
                val removable = messages
                    .dropLast(1)
                    .sortedWith(privateMessagePruneComparator())
                    .take(excess)
                    .mapTo(linkedSetOf()) { it.id }
                removedIDs.addAll(removable)
                chats[recentKey] = messages.filterNot { it.id in removable }
            }
        }

        privateWritesSinceGlobalPrune += 1
        if (privateWritesSinceGlobalPrune >= 64) {
            privateWritesSinceGlobalPrune = 0
            var totalMessages = chats.values.sumOf { it.size }
            var totalPayloadBytes = chats.values
                .asSequence()
                .flatten()
                .sumOf(::privateMessagePayloadBytes)
            if (
                totalMessages > ConversationDatabase.MAX_MESSAGES_TOTAL ||
                totalPayloadBytes > ConversationDatabase.MAX_PAYLOAD_BYTES
            ) {
                val candidates = chats.values
                    .asSequence()
                    .flatMap { messages -> messages.dropLast(1).asSequence() }
                    .sortedWith(privateMessagePruneComparator())
                    .iterator()
                while (
                    candidates.hasNext() &&
                    (
                        totalMessages > ConversationDatabase.MAX_MESSAGES_TOTAL ||
                            totalPayloadBytes > ConversationDatabase.MAX_PAYLOAD_BYTES
                        )
                ) {
                    val candidate = candidates.next()
                    if (!removedIDs.add(candidate.id)) continue
                    totalMessages -= 1
                    totalPayloadBytes -= privateMessagePayloadBytes(candidate)
                }
                if (
                    totalMessages > ConversationDatabase.MAX_MESSAGES_TOTAL ||
                    totalPayloadBytes > ConversationDatabase.MAX_PAYLOAD_BYTES
                ) {
                    // Enforce the hard bound even when every conversation contains only its
                    // newest message. Read conversations still sort ahead of unread ones.
                    val latestCandidates = chats.values
                        .asSequence()
                        .flatten()
                        .filterNot { it.id in removedIDs }
                        .sortedWith(privateMessagePruneComparator())
                        .iterator()
                    while (
                        latestCandidates.hasNext() &&
                        (
                            totalMessages > ConversationDatabase.MAX_MESSAGES_TOTAL ||
                                totalPayloadBytes > ConversationDatabase.MAX_PAYLOAD_BYTES
                            )
                    ) {
                        val candidate = latestCandidates.next()
                        if (!removedIDs.add(candidate.id)) continue
                        totalMessages -= 1
                        totalPayloadBytes -= privateMessagePayloadBytes(candidate)
                    }
                }
                if (removedIDs.isNotEmpty()) {
                    chats.keys.toList().forEach { key ->
                        chats[key] = chats[key].orEmpty().filterNot {
                            it.id in removedIDs
                        }
                    }
                }
            }
        }

        if (removedIDs.isNotEmpty()) {
            _privateMessages.value = chats.filterValues { it.isNotEmpty() }
            _readPrivateMessageIDs.value = _readPrivateMessageIDs.value - removedIDs
        }
    }

    private fun privateMessagePruneComparator(): Comparator<BitchatMessage> =
        compareByDescending<BitchatMessage> {
            it.id in _readPrivateMessageIDs.value
        }.thenBy {
            PrivateMessageArrivalOrder.sequenceOf(it.id) ?: Long.MAX_VALUE
        }

    private fun privateMessagePayloadBytes(message: BitchatMessage): Long =
        message.content.toByteArray(Charsets.UTF_8).size.toLong() +
            (message.encryptedContent?.size ?: 0) +
            message.mentions.orEmpty().sumOf {
                it.toByteArray(Charsets.UTF_8).size
            }
}

private data class PendingPrivateMessagePersistence(
    val repository: ConversationRepository?,
    val conversationID: String,
    val aliases: Set<String>,
    val displayName: String?,
    val isRead: Boolean,
    val generation: Long
)

internal data class DeletedPrivateConversation(
    val conversationID: String,
    val aliases: Set<String>,
    val displayName: String?,
    val messages: List<BitchatMessage>,
    val readMessageIDs: Set<String>,
    val unreadMessageCount: Int,
    val wasPinned: Boolean = false,
    val wasMuted: Boolean = false,
    val draft: String? = null
) {
    val messageIDs: Set<String> = messages.mapTo(linkedSetOf(), BitchatMessage::id)
}

private val EMPTY_CONVERSATION_STORE_STATE =
    MutableStateFlow<ConversationStoreState>(ConversationStoreState.Ready).asStateFlow()

package com.bitchat.android.services

import android.content.Context
import com.bitchat.android.favorites.FavoriteRelationship
import com.bitchat.android.favorites.FavoritesPersistenceService
import com.bitchat.android.identity.SecureIdentityStateManager
import com.bitchat.android.mesh.MeshService
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.nostr.GeohashAliasRegistry

object ContactDirectory {
    data class ContactResolution(
        val conversationID: String,
        val meshPeerID: String?,
        val noisePublicKey: ByteArray?,
        val nostrPubkey: String?,
        val displayName: String?,
        val isMutualFavorite: Boolean
    ) {
        val noiseKeyHex: String? get() = noisePublicKey?.let { ContactIdentityResolver.noiseKeyHex(it) }
    }

    @Volatile
    private var appContext: Context? = null

    @Volatile
    private var meshProvider: (() -> MeshService?)? = null

    @Volatile
    internal var identityManagerProvider: (Context) -> SecureIdentityStateManager =
        { SecureIdentityStateManager(it) }

    fun initialize(context: Context, meshProvider: () -> MeshService?) {
        appContext = context.applicationContext
        this.meshProvider = meshProvider
    }

    fun isContactConversationID(value: String): Boolean =
        ContactIdentityResolver.isContactConversationId(value)

    fun canonicalConversationId(peerOrConversationID: String): String {
        val value = peerOrConversationID.trim()
        if (ContactIdentityResolver.isContactConversationId(value)) return value.lowercase()

        noiseKeyForAlias(value)?.let {
            return ContactIdentityResolver.contactConversationIdForNoiseKey(it)
        }

        if (ContactIdentityResolver.isMeshPeerId(value)) {
            favoriteForMeshPeerID(value)?.peerNoisePublicKey?.let {
                return ContactIdentityResolver.contactConversationIdForNoiseKey(it)
            }
        }

        if (ContactIdentityResolver.isNostrAlias(value)) {
            nostrPubkeyHexForAlias(value)?.let { pubHex ->
                findFavoriteByNostrHex(pubHex)?.peerNoisePublicKey?.let {
                    return ContactIdentityResolver.contactConversationIdForNoiseKey(it)
                }
            }
        }

        return value
    }

    fun resolve(peerOrConversationID: String): ContactResolution {
        val conversationID = canonicalConversationId(peerOrConversationID)
        val contactFingerprint = ContactIdentityResolver.fingerprintFromContactConversationId(conversationID)

        val favorite = contactFingerprint?.let { findFavoriteByFingerprint(it) }
        val noiseKey = when {
            favorite != null -> favorite.peerNoisePublicKey
            ContactIdentityResolver.isNoiseKeyHex(peerOrConversationID) ->
                ContactIdentityResolver.bytesFromHex(peerOrConversationID)
            else -> null
        }
        val liveMeshPeerID = contactFingerprint?.let { findLiveMeshPeerForFingerprint(it) }
            ?: peerOrConversationID.takeIf { ContactIdentityResolver.isMeshPeerId(it) && isMeshPeerConnected(it) }

        return ContactResolution(
            conversationID = conversationID,
            meshPeerID = liveMeshPeerID,
            noisePublicKey = noiseKey ?: liveMeshPeerID?.let { meshProvider?.invoke()?.getPeerInfo(it)?.noisePublicKey },
            nostrPubkey = favorite?.peerNostrPublicKey
                ?: liveMeshPeerID?.let {
                    runCatching {
                        FavoritesPersistenceService.shared.findNostrPubkeyForPeerID(it)
                    }.getOrNull()
                },
            // A connected peer's current announcement is authoritative. Favorite and fingerprint
            // records are offline fallbacks and can legitimately contain an older nickname.
            displayName = liveMeshPeerID?.let { meshProvider?.invoke()?.getPeerInfo(it)?.nickname }
                ?.takeIf { it.isNotBlank() && !it.equals("Unknown", ignoreCase = true) }
                ?: favorite?.peerNickname?.takeIf {
                    it.isNotBlank() && !it.equals("Unknown", ignoreCase = true)
                }
                ?: contactFingerprint?.let { cachedFingerprintNickname(it) },
            isMutualFavorite = favorite?.isMutual == true
        )
    }

    fun canonicalizePrivateChats(
        chats: Map<String, List<BitchatMessage>>
    ): Map<String, List<BitchatMessage>> {
        if (chats.isEmpty()) return chats

        val merged = linkedMapOf<String, MutableList<BitchatMessage>>()
        chats.forEach { (key, messages) ->
            val canonical = canonicalConversationId(key)
            val list = merged.getOrPut(canonical) { mutableListOf() }
            list.addAll(messages)
        }

        return merged.mapValues { (_, messages) ->
            // A private message's timestamp comes from the sender and is not a reliable ordering
            // signal when peers' clocks differ. Use the local receipt sequence so interleaved
            // alias lists can be merged back into their global arrival order.
            PrivateMessageArrivalOrder.order(messages.distinctBy { it.id })
        }
    }

    fun aliasesForConversation(peerOrConversationID: String): Set<String> {
        val resolution = resolve(peerOrConversationID)
        val aliases = mutableSetOf<String>()
        aliases.add(peerOrConversationID)
        aliases.add(resolution.conversationID)
        resolution.meshPeerID?.let { aliases.add(it) }
        resolution.noiseKeyHex?.let { aliases.add(it) }
        resolution.nostrPubkey
            ?.let { ContactIdentityResolver.nostrAliasForPubkey(it) }
            ?.let { aliases.add(it) }
        return aliases
    }

    private fun noiseKeyForAlias(value: String): ByteArray? {
        if (ContactIdentityResolver.isNoiseKeyHex(value)) {
            return ContactIdentityResolver.bytesFromHex(value)
        }

        if (ContactIdentityResolver.isMeshPeerId(value)) {
            meshProvider?.invoke()?.getPeerInfo(value)?.noisePublicKey?.let { return it }
            cachedNoiseKey(value)?.let { return it }
        }

        return null
    }

    private fun cachedNoiseKey(peerID: String): ByteArray? {
        val context = appContext ?: return null
        return try {
            identityManagerProvider(context)
                .getCachedNoiseKey(peerID)
                ?.let { ContactIdentityResolver.bytesFromHex(it) }
        } catch (_: Exception) {
            null
        }
    }

    private fun cachedFingerprintNickname(fingerprint: String): String? {
        val context = appContext ?: return null
        return try {
            identityManagerProvider(context)
                .getCachedFingerprintNickname(fingerprint)
                ?.takeIf { it.isNotBlank() && !it.equals("Unknown", ignoreCase = true) }
        } catch (_: Exception) {
            null
        }
    }

    private fun favoriteForMeshPeerID(peerID: String): FavoriteRelationship? =
        try {
            FavoritesPersistenceService.shared.getFavoriteStatus(peerID)
        } catch (_: Exception) {
            null
        }

    private fun findFavoriteByFingerprint(fingerprint: String): FavoriteRelationship? =
        try {
            FavoritesPersistenceService.shared.getAllRelationships().firstOrNull {
                ContactIdentityResolver.fingerprintHex(it.peerNoisePublicKey).equals(fingerprint, ignoreCase = true)
            }
        } catch (_: Exception) {
            null
        }

    private fun findFavoriteByNostrHex(pubHex: String): FavoriteRelationship? =
        try {
            FavoritesPersistenceService.shared.getAllRelationships().firstOrNull {
                it.peerNostrPublicKey
                    ?.let { npub -> ContactIdentityResolver.nostrPubkeyHex(npub) }
                    ?.equals(pubHex, ignoreCase = true) == true
            }
        } catch (_: Exception) {
            null
        }

    private fun nostrPubkeyHexForAlias(alias: String): String? {
        GeohashAliasRegistry.get(alias)?.let { return it.lowercase() }
        val prefix = alias.removePrefix("nostr_").removePrefix("nostr:")
        if (prefix.isBlank()) return null
        return try {
            FavoritesPersistenceService.shared.getAllRelationships()
                .asSequence()
                .mapNotNull { it.peerNostrPublicKey?.let { npub -> ContactIdentityResolver.nostrPubkeyHex(npub) } }
                .firstOrNull { it.startsWith(prefix, ignoreCase = true) }
        } catch (_: Exception) {
            null
        }
    }

    private fun findLiveMeshPeerForFingerprint(fingerprint: String): String? {
        val mesh = meshProvider?.invoke() ?: return null
        return mesh.getPeerNicknames().keys.firstOrNull { peerID ->
            val info = mesh.getPeerInfo(peerID)
            val noiseKey = info?.noisePublicKey ?: cachedNoiseKey(peerID)
            noiseKey != null &&
                ContactIdentityResolver.fingerprintHex(noiseKey).equals(fingerprint, ignoreCase = true) &&
                info?.isConnected == true
        }
    }

    private fun isMeshPeerConnected(peerID: String): Boolean =
        try {
            meshProvider?.invoke()?.getPeerInfo(peerID)?.isConnected == true
        } catch (_: Exception) {
            false
        }
}

package com.bitchat.android.services

import com.bitchat.android.nostr.Bech32
import com.bitchat.android.util.dataFromHexString
import com.bitchat.android.util.hexEncodedString
import java.security.MessageDigest

object ContactIdentityResolver {
    private const val CONTACT_PREFIX = "contact_"
    private val meshPeerIdRegex = Regex("^[0-9a-fA-F]{16}$")
    private val noiseKeyRegex = Regex("^[0-9a-fA-F]{64}$")
    private val fingerprintRegex = Regex("^[0-9a-fA-F]{64}$")

    fun isMeshPeerId(value: String): Boolean = meshPeerIdRegex.matches(value)

    fun isNoiseKeyHex(value: String): Boolean = noiseKeyRegex.matches(value)

    fun isNostrAlias(value: String): Boolean =
        value.startsWith("nostr_") || value.startsWith("nostr:")

    fun noiseKeyHex(noisePublicKey: ByteArray): String = noisePublicKey.hexEncodedString()

    fun fingerprintHex(noisePublicKey: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(noisePublicKey)
        return digest.hexEncodedString()
    }

    fun contactConversationIdForNoiseKey(noisePublicKey: ByteArray): String =
        CONTACT_PREFIX + fingerprintHex(noisePublicKey)

    fun contactConversationIdForFingerprint(fingerprint: String): String? =
        fingerprint
            .takeIf { fingerprintRegex.matches(it) }
            ?.let { CONTACT_PREFIX + it.lowercase() }

    fun isContactConversationId(value: String): Boolean =
        value.startsWith(CONTACT_PREFIX) &&
            fingerprintRegex.matches(value.removePrefix(CONTACT_PREFIX))

    fun fingerprintFromContactConversationId(value: String): String? =
        value
            .takeIf { isContactConversationId(it) }
            ?.removePrefix(CONTACT_PREFIX)
            ?.lowercase()

    fun peerIdForNoiseKey(noisePublicKey: ByteArray): String =
        fingerprintHex(noisePublicKey).take(16)

    fun peerIdForNoiseKeyHex(noiseKeyHex: String): String? =
        bytesFromHex(noiseKeyHex)
            ?.takeIf { it.size == 32 }
            ?.let { peerIdForNoiseKey(it) }

    fun bytesFromHex(hex: String): ByteArray? {
        val clean = hex.trim()
        if (clean.length % 2 != 0) return null
        if (!clean.matches(Regex("^[0-9a-fA-F]+$"))) return null
        return clean.dataFromHexString()
    }

    fun nostrPubkeyHex(value: String): String? {
        val clean = value.trim()
        if (clean.startsWith("npub1", ignoreCase = true)) {
            return try {
                val (hrp, data) = Bech32.decode(clean.lowercase())
                if (hrp == "npub" && data.size == 32) data.hexEncodedString() else null
            } catch (_: Exception) {
                null
            }
        }
        return clean
            .takeIf { noiseKeyRegex.matches(it) }
            ?.lowercase()
    }

    fun npubFromHex(hex: String): String? =
        bytesFromHex(hex)
            ?.takeIf { it.size == 32 }
            ?.let { Bech32.encode("npub", it) }

    fun nostrAliasForPubkey(value: String): String? =
        nostrPubkeyHex(value)?.let { "nostr_${it.take(16)}" }
}

package com.bitchat.android.services

import com.bitchat.android.ui.ChatState

object ConversationAliasResolver {

    fun resolveCanonicalPeerID(
        selectedPeerID: String,
        connectedPeers: List<String>,
        meshNoiseKeyForPeer: (String) -> ByteArray?,
        nostrPubHexForAlias: (String) -> String?,
        findNoiseKeyForNostr: (String) -> ByteArray?
    ): String {
        var peer = selectedPeerID
        try {
            if (ContactIdentityResolver.isNostrAlias(peer)) {
                val pubHex = nostrPubHexForAlias(peer)
                if (pubHex != null) {
                    val noiseKey = findNoiseKeyForNostr(pubHex)
                    if (noiseKey != null) {
                        val noiseHex = ContactIdentityResolver.noiseKeyHex(noiseKey)
                        val meshPeer = connectedPeers.firstOrNull { pid ->
                            meshNoiseKeyForPeer(pid)?.contentEquals(noiseKey) == true
                        }
                        peer = meshPeer ?: noiseHex
                    }
                }
            } else if (ContactIdentityResolver.isNoiseKeyHex(peer)) {
                val noiseKey = ContactIdentityResolver.bytesFromHex(peer) ?: return peer
                val meshPeer = connectedPeers.firstOrNull { pid ->
                    meshNoiseKeyForPeer(pid)?.contentEquals(noiseKey) == true
                }
                if (meshPeer != null) {
                    peer = meshPeer
                }
            }
        } catch (_: Exception) { /* no-op */ }
        return ContactDirectory.canonicalConversationId(peer)
    }

    fun unifyChatsIntoPeer(
        state: ChatState,
        targetPeerID: String,
        keysToMerge: List<String>
    ) {
        if (keysToMerge.isEmpty()) return
        val targetConversationID = ContactDirectory.canonicalConversationId(targetPeerID)
        val mergeKeys = (keysToMerge + targetPeerID)
            .flatMap { ContactDirectory.aliasesForConversation(it) }
            .distinct()
        AppStateStore.unifyPrivateChatsIntoPeer(targetConversationID, mergeKeys)

        val currentChats = state.getPrivateChatsValue().toMutableMap()
        val targetList = currentChats[targetConversationID]?.toMutableList() ?: mutableListOf()
        var didMerge = false
        mergeKeys.forEach { key ->
            if (key == targetConversationID) return@forEach
            val list = currentChats[key]
            if (!list.isNullOrEmpty()) {
                targetList.addAll(list)
                currentChats.remove(key)
                didMerge = true
            }
        }
        if (didMerge) {
            currentChats[targetConversationID] = targetList
                .distinctBy { it.id }
            state.setPrivateChats(ContactDirectory.canonicalizePrivateChats(currentChats))

            // Move unread flags
            val unread = state.getUnreadPrivateMessagesValue().toMutableSet()
            var hadUnread = false
            mergeKeys.forEach { key -> if (unread.remove(key)) hadUnread = true }
            if (hadUnread) unread.add(targetConversationID)
            state.setUnreadPrivateMessages(unread)

            // Switch selection if currently viewing an alias that got merged
            val selected = state.getSelectedPrivateChatPeerValue()
            if (selected != null && mergeKeys.contains(selected)) {
                state.setSelectedPrivateChatPeer(targetConversationID)
            }

            // Switch sheet peer if currently viewing an alias that got merged
            val sheetPeer = state.getPrivateChatSheetPeerValue()
            if (sheetPeer != null && mergeKeys.contains(sheetPeer)) {
                state.setPrivateChatSheetPeer(targetConversationID)
            }
        }
    }
}

package com.bitchat.android.services

import android.content.Context
import com.bitchat.android.identity.SecureIdentityStateManager
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import org.json.JSONArray
import org.json.JSONObject

/**
 * Small encrypted, immediately observable preferences for conversation-list organization.
 *
 * Message history remains in SQLite; these compact sets and drafts belong in the app's existing
 * Keystore-backed preference store. Panic clearing the identity store also removes these values.
 */
internal class ConversationListPreferences private constructor(
    private val stateManager: SecureIdentityStateManager,
    private val canonicalize: (String) -> String
) {
    private constructor(context: Context) : this(
        SecureIdentityStateManager(context.applicationContext),
        ContactDirectory::canonicalConversationId
    )

    internal constructor(
        stateManager: SecureIdentityStateManager,
        testOnly: Boolean,
        canonicalize: (String) -> String = ContactDirectory::canonicalConversationId
    ) : this(stateManager, canonicalize) {
        require(testOnly) { "Injected conversation preferences are test-only" }
    }

    companion object {
        private const val PINNED_KEY = "conversation_pinned_v1"
        private const val MUTED_KEY = "conversation_muted_v1"
        private const val DRAFTS_KEY = "conversation_drafts_v1"
        private const val MAX_DRAFT_CHARS = 8_000
        private const val MAX_DRAFTS = 50
        private const val MAX_DRAFT_CHARS_TOTAL = 128_000

        @Volatile
        private var instance: ConversationListPreferences? = null

        fun getInstance(context: Context): ConversationListPreferences =
            instance ?: synchronized(this) {
                instance ?: ConversationListPreferences(context.applicationContext).also {
                    instance = it
                }
            }
    }

    private val _pinned = MutableStateFlow(loadSet(PINNED_KEY))
    val pinned: StateFlow<Set<String>> = _pinned.asStateFlow()
    private val _muted = MutableStateFlow(loadSet(MUTED_KEY))
    val muted: StateFlow<Set<String>> = _muted.asStateFlow()
    private val _drafts = MutableStateFlow(loadDrafts())
    val drafts: StateFlow<Map<String, String>> = _drafts.asStateFlow()

    fun togglePinned(conversationID: String) {
        _pinned.value = _pinned.value.toggle(normalize(conversationID))
        saveSet(PINNED_KEY, _pinned.value)
    }

    fun toggleMuted(conversationID: String) {
        _muted.value = _muted.value.toggle(normalize(conversationID))
        saveSet(MUTED_KEY, _muted.value)
    }

    fun isMuted(conversationID: String): Boolean =
        normalize(conversationID) in _muted.value

    fun isPinned(conversationID: String): Boolean =
        normalize(conversationID) in _pinned.value

    fun draftFor(conversationID: String): String? =
        _drafts.value[normalize(conversationID)]

    fun setDraft(conversationID: String, text: String) {
        val key = normalize(conversationID)
        val updated = _drafts.value.toMutableMap()
        // Reinsert edited drafts at the end so bounded eviction approximates least-recently-used.
        updated.remove(key)
        val bounded = text.take(MAX_DRAFT_CHARS)
        if (bounded.isNotBlank()) updated[key] = bounded
        val retained = boundDrafts(updated)
        _drafts.value = retained
        saveDrafts(retained)
    }

    fun removeConversation(conversationID: String) {
        val key = normalize(conversationID)
        _pinned.value = _pinned.value - key
        _muted.value = _muted.value - key
        _drafts.value = _drafts.value - key
        saveSet(PINNED_KEY, _pinned.value)
        saveSet(MUTED_KEY, _muted.value)
        saveDrafts(_drafts.value)
    }

    /**
     * Re-key list preferences when a transient mesh ID becomes a stable contact identity.
     * Without this, pin, mute, and draft state appears to disappear after a Noise/favorite update.
     */
    fun canonicalizeAliases() {
        val canonicalPinned = _pinned.value.mapTo(linkedSetOf(), ::normalize)
        val canonicalMuted = _muted.value.mapTo(linkedSetOf(), ::normalize)
        val canonicalDrafts = linkedMapOf<String, String>()
        _drafts.value.forEach { (conversationID, draft) ->
            canonicalDrafts[normalize(conversationID)] = draft
        }

        if (canonicalPinned != _pinned.value) {
            _pinned.value = canonicalPinned
            saveSet(PINNED_KEY, canonicalPinned)
        }
        if (canonicalMuted != _muted.value) {
            _muted.value = canonicalMuted
            saveSet(MUTED_KEY, canonicalMuted)
        }
        if (canonicalDrafts != _drafts.value) {
            val bounded = boundDrafts(canonicalDrafts)
            _drafts.value = bounded
            saveDrafts(bounded)
        }
    }

    fun clearInMemory() {
        _pinned.value = emptySet()
        _muted.value = emptySet()
        _drafts.value = emptyMap()
    }

    fun clearAll(): Boolean {
        val cleared = stateManager.clearSecureValuesSynchronously(
            PINNED_KEY,
            MUTED_KEY,
            DRAFTS_KEY
        )
        clearInMemory()
        return cleared
    }

    private fun loadSet(key: String): Set<String> = runCatching {
        val array = JSONArray(stateManager.getSecureValue(key) ?: return emptySet())
        buildSet {
            for (index in 0 until array.length()) add(normalize(array.getString(index)))
        }
    }.getOrDefault(emptySet())

    private fun saveSet(key: String, values: Set<String>) {
        stateManager.storeSecureValue(key, JSONArray(values.sorted()).toString())
    }

    private fun loadDrafts(): Map<String, String> = runCatching {
        val json = JSONObject(stateManager.getSecureValue(DRAFTS_KEY) ?: return emptyMap())
        val loaded = buildMap {
            json.keys().forEach { key ->
                json.optString(key).takeIf(String::isNotBlank)?.let {
                    put(normalize(key), it.take(MAX_DRAFT_CHARS))
                }
            }
        }
        boundDrafts(loaded)
    }.getOrDefault(emptyMap())

    private fun saveDrafts(values: Map<String, String>) {
        stateManager.storeSecureValue(
            DRAFTS_KEY,
            JSONObject().apply {
                values.forEach { (key, value) -> put(key, value) }
            }.toString()
        )
    }

    private fun Set<String>.toggle(value: String): Set<String> =
        if (value in this) this - value else this + value

    private fun normalize(value: String): String =
        canonicalize(value).lowercase()

    private fun boundDrafts(values: Map<String, String>): Map<String, String> {
        val retained = LinkedHashMap(values)
        while (
            retained.size > MAX_DRAFTS ||
            retained.values.sumOf(String::length) > MAX_DRAFT_CHARS_TOTAL
        ) {
            val oldest = retained.keys.firstOrNull() ?: break
            retained.remove(oldest)
        }
        return retained
    }

}

package com.bitchat.android.services

import android.content.ContentValues
import android.content.Context
import android.database.Cursor
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper
import android.util.Base64
import android.util.Log
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.BitchatMessageType
import com.bitchat.android.model.DeliveryStatus
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.asCoroutineDispatcher
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.security.MessageDigest
import java.util.Date
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Process-wide, serialized persistence for private conversations.
 *
 * Android's SQLite database is deliberately kept behind this small repository instead of leaking
 * cursors or database threading into the mesh and UI layers. Every mutation is queued on one
 * writer so a delete/merge followed by a newly arriving message is applied in the same order that
 * [AppStateStore] publishes it.
 */
class ConversationRepository internal constructor(
    context: Context,
    private val dispatcher: CoroutineDispatcher = Executors
        .newSingleThreadExecutor { runnable ->
            Thread(runnable, "conversation-store").apply { isDaemon = true }
        }
        .asCoroutineDispatcher(),
    databaseName: String = ConversationDatabase.DEFAULT_DATABASE_NAME,
    storageCipher: ConversationStorageCipher = AndroidConversationStorageCipher()
) {
    companion object {
        private const val TAG = "ConversationRepository"

        @Volatile
        private var instance: ConversationRepository? = null

        fun getInstance(context: Context): ConversationRepository =
            instance ?: synchronized(this) {
                instance ?: ConversationRepository(context.applicationContext).also {
                    instance = it
                }
            }

        fun tryGetInstance(): ConversationRepository? = instance
    }

    private val applicationContext = context.applicationContext
    private val database = ConversationDatabase(
        context = applicationContext,
        databaseName = databaseName,
        storageCipher = storageCipher
    )
    private val scope = CoroutineScope(SupervisorJob() + dispatcher)
    private val initialized = AtomicBoolean(false)
    private val _storeState =
        MutableStateFlow<ConversationStoreState>(ConversationStoreState.Loading)
    val storeState: StateFlow<ConversationStoreState> = _storeState.asStateFlow()

    internal fun initialize(onLoaded: (PersistedConversationSnapshot) -> Unit) {
        if (!initialized.compareAndSet(false, true)) return
        enqueueSnapshotLoad(pruneFirst = true, onLoaded = onLoaded)
    }

    /**
     * Re-reads persisted history even when this process already initialized the repository.
     *
     * This is required when the app's controlled shutdown cleared [AppStateStore], but Android
     * reused the still-running process when the user immediately reopened the UI.
     */
    internal fun reload(onLoaded: (PersistedConversationSnapshot) -> Unit) {
        enqueueSnapshotLoad(pruneFirst = false, onLoaded = onLoaded)
    }

    private fun enqueueSnapshotLoad(
        pruneFirst: Boolean,
        onLoaded: (PersistedConversationSnapshot) -> Unit
    ) {
        scope.launch {
            try {
                if (pruneFirst) {
                    deleteStoredMedia(database.pruneToRetentionLimits())
                }
                onLoaded(database.loadInitialSnapshot())
                _storeState.value = ConversationStoreState.Ready
            } catch (error: Exception) {
                Log.e(TAG, "Unable to restore private conversations", error)
                _storeState.value = ConversationStoreState.Error(
                    error.message ?: "Unable to restore conversations"
                )
            }
        }
    }

    /**
     * Suspends until all persistence work queued before this call has finished.
     */
    suspend fun awaitPendingWrites() {
        withContext(dispatcher) { Unit }
    }

    internal suspend fun loadConversationAndWait(
        conversationID: String
    ): PersistedConversationSnapshot? = withContext(dispatcher) {
        try {
            database.loadConversation(conversationID)
        } catch (error: Exception) {
            Log.e(TAG, "Unable to load private conversation", error)
            _storeState.value = ConversationStoreState.Error(
                error.message ?: "Unable to load conversation"
            )
            null
        }
    }

    fun upsertMessage(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        message: BitchatMessage,
        isRead: Boolean
    ) {
        scope.launch {
            upsertMessageLocked(conversationID, aliases, displayName, message, isRead)
        }
    }

    suspend fun upsertMessageAndWait(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        message: BitchatMessage,
        isRead: Boolean
    ): Boolean = withContext(dispatcher) {
        upsertMessageLocked(conversationID, aliases, displayName, message, isRead)
    }

    private fun upsertMessageLocked(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        message: BitchatMessage,
        isRead: Boolean
    ): Boolean = try {
        val result = database.upsertMessage(
            conversationID = conversationID,
            aliases = aliases,
            displayName = displayName,
            message = message,
            isRead = isRead
        )
        deleteStoredMedia(result.orphanedMediaPaths)
        _storeState.value = ConversationStoreState.Ready
        result.inserted
    } catch (error: Exception) {
        Log.e(TAG, "Unable to persist private message", error)
        _storeState.value = ConversationStoreState.Error(
            error.message ?: "Unable to save conversation"
        )
        false
    }

    fun updateDeliveryStatus(messageID: String, status: DeliveryStatus) {
        scope.launch {
            try {
                database.updateDeliveryStatus(messageID, status)
            } catch (error: Exception) {
                Log.e(TAG, "Unable to persist delivery status: ${error.message}")
            }
        }
    }

    fun markRead(messageID: String) {
        scope.launch {
            try {
                database.markRead(messageID)
            } catch (error: Exception) {
                Log.e(TAG, "Unable to persist local read state: ${error.message}")
            }
        }
    }

    internal suspend fun setConversationReadAndWait(
        conversationID: String,
        isRead: Boolean
    ): ConversationReadResult = withContext(dispatcher) {
        try {
            ConversationReadResult(
                success = true,
                affectedMessageID = database.setConversationRead(conversationID, isRead)
            )
        } catch (error: Exception) {
            Log.e(TAG, "Unable to update conversation read state", error)
            _storeState.value = ConversationStoreState.Error(
                error.message ?: "Unable to update conversation"
            )
            ConversationReadResult(success = false)
        }
    }

    fun mergeAliases(targetConversationID: String, aliases: Set<String>) {
        scope.launch {
            try {
                database.mergeAliases(targetConversationID, aliases)
            } catch (error: Exception) {
                Log.e(TAG, "Unable to merge conversation aliases: ${error.message}")
            }
        }
    }

    fun updateConversationIdentity(
        conversationID: String,
        aliases: Set<String>,
        displayName: String
    ) {
        scope.launch {
            try {
                database.updateConversationIdentity(conversationID, aliases, displayName)
            } catch (error: Exception) {
                Log.e(TAG, "Unable to persist conversation identity: ${error.message}")
            }
        }
    }

    fun deleteConversation(conversationID: String, aliases: Set<String>) {
        scope.launch {
            deleteConversationLocked(conversationID, aliases)
        }
    }

    suspend fun deleteConversationAndWait(
        conversationID: String,
        aliases: Set<String>
    ): Boolean = withContext(dispatcher) {
        deleteConversationLocked(conversationID, aliases)
    }

    suspend fun restoreConversationAndWait(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        messages: List<BitchatMessage>,
        readMessageIDs: Set<String>
    ): Boolean = withContext(dispatcher) {
        try {
            deleteStoredMedia(
                database.restoreConversation(
                    conversationID,
                    aliases,
                    displayName,
                    messages,
                    readMessageIDs
                )
            )
            _storeState.value = ConversationStoreState.Ready
            true
        } catch (error: Exception) {
            Log.e(TAG, "Unable to restore deleted conversation", error)
            _storeState.value = ConversationStoreState.Error(
                error.message ?: "Unable to restore conversation"
            )
            false
        }
    }

    private fun deleteConversationLocked(
        conversationID: String,
        aliases: Set<String>
    ): Boolean = try {
        deleteStoredMedia(database.deleteConversation(conversationID, aliases))
        _storeState.value = ConversationStoreState.Ready
        true
    } catch (error: Exception) {
        Log.e(TAG, "Unable to delete private conversation", error)
        _storeState.value = ConversationStoreState.Error(
            error.message ?: "Unable to delete conversation"
        )
        false
    }

    fun deleteMessage(messageID: String) {
        scope.launch {
            try {
                deleteStoredMedia(database.deleteMessage(messageID))
            } catch (error: Exception) {
                Log.e(TAG, "Unable to delete private message: ${error.message}")
            }
        }
    }

    /**
     * Drains earlier writes and completes the database wipe before returning.
     *
     * Panic mode uses this stronger variant so identity regeneration and transport restart cannot
     * race an outstanding message insert or an unfinished conversation deletion.
     */
    suspend fun clearAllAndWait(): Boolean = withContext(dispatcher) {
        try {
            database.clearAll()
            _storeState.value = ConversationStoreState.Ready
            true
        } catch (error: Exception) {
            Log.e(TAG, "Unable to synchronously clear private conversations", error)
            _storeState.value = ConversationStoreState.Error(
                error.message ?: "Unable to erase conversations"
            )
            false
        }
    }

    private fun deleteStoredMedia(paths: Collection<String>) {
        if (paths.isEmpty()) return
        com.bitchat.android.features.file.FileUtils.deleteStoredMediaPaths(
            applicationContext,
            paths
        )
    }

    internal fun closeForTest() {
        database.close()
    }
}

sealed interface ConversationStoreState {
    data object Loading : ConversationStoreState
    data object Ready : ConversationStoreState
    data class Error(val message: String) : ConversationStoreState
}

internal data class ConversationReadResult(
    val success: Boolean,
    val affectedMessageID: String? = null
)

internal data class ConversationUpsertResult(
    val inserted: Boolean,
    val orphanedMediaPaths: Set<String>
)

internal data class PersistedConversationSnapshot(
    val chats: Map<String, List<BitchatMessage>>,
    val readMessageIDs: Set<String>,
    val arrivalOrder: List<String>,
    val deletedMessageIDs: Set<String>,
    val displayNames: Map<String, String> = emptyMap(),
    val unreadCounts: Map<String, Int> = emptyMap(),
    val receivedAtByMessageID: Map<String, Long> = emptyMap(),
    val arrivalSequenceByMessageID: Map<String, Long> = emptyMap()
)

/**
 * Versioned SQLite schema for bounded private-message history.
 *
 * Conversation rows are intentionally tiny and remain until explicit deletion. Message rows are
 * bounded by per-conversation, global-row, and payload-byte limits. Media bytes stay in the app's
 * existing media storage; SQLite only stores the message metadata/path already present in content.
 */
internal class ConversationDatabase(
    context: Context,
    databaseName: String = DEFAULT_DATABASE_NAME,
    private val maxMessagesPerConversation: Int = MAX_MESSAGES_PER_CONVERSATION,
    private val maxMessagesTotal: Int = MAX_MESSAGES_TOTAL,
    private val maxPayloadBytes: Long = MAX_PAYLOAD_BYTES,
    private val maxMediaBytes: Long = MAX_MEDIA_BYTES,
    private val storageCipher: ConversationStorageCipher =
        AndroidConversationStorageCipher()
) : SQLiteOpenHelper(context, databaseName, null, DATABASE_VERSION) {

    companion object {
        private const val TAG = "ConversationDatabase"
        const val MAX_MESSAGES_PER_CONVERSATION = 1_000
        const val MAX_MESSAGES_TOTAL = 20_000
        const val MAX_PAYLOAD_BYTES = 32L * 1024L * 1024L
        const val MAX_MEDIA_BYTES = 256L * 1024L * 1024L

        internal const val DEFAULT_DATABASE_NAME = "private_conversations.db"
        internal const val DATABASE_VERSION = 4
        private const val PRUNE_INTERVAL = 64
        private const val PRUNE_BATCH_SIZE = 256
    }

    private val applicationContext = context.applicationContext
    private var writesSinceGlobalPrune = 0

    init {
        setWriteAheadLoggingEnabled(true)
    }

    override fun onConfigure(db: SQLiteDatabase) {
        super.onConfigure(db)
        db.setForeignKeyConstraintsEnabled(true)
        db.execSQL("PRAGMA auto_vacuum = INCREMENTAL")
        // Overwrite cells removed while migrating legacy plaintext payload columns.
        db.rawQuery("PRAGMA secure_delete = ON", null).use { cursor ->
            if (cursor.moveToFirst()) Unit
        }
    }

    override fun onOpen(db: SQLiteDatabase) {
        super.onOpen(db)
        // A v1 database may have written plaintext pages to its WAL before the encrypted migration.
        // Truncating it after SQLite's upgrade transaction prevents those historical frames from
        // lingering after the scrubbed rows are committed.
        runCatching {
            db.rawQuery("PRAGMA wal_checkpoint(TRUNCATE)", null).use { cursor ->
                if (cursor.moveToFirst()) Unit
            }
        }.onFailure { error ->
            Log.w(TAG, "Unable to truncate conversation WAL: ${error.message}")
        }
    }

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL(
            """
            CREATE TABLE conversations (
                conversation_id TEXT COLLATE NOCASE PRIMARY KEY NOT NULL,
                display_name TEXT,
                display_name_ciphertext BLOB,
                created_at INTEGER NOT NULL,
                updated_at INTEGER NOT NULL
            )
            """.trimIndent()
        )
        db.execSQL(
            """
            CREATE TABLE conversation_aliases (
                alias TEXT COLLATE NOCASE PRIMARY KEY NOT NULL,
                conversation_id TEXT COLLATE NOCASE NOT NULL,
                FOREIGN KEY(conversation_id) REFERENCES conversations(conversation_id)
                    ON DELETE CASCADE ON UPDATE CASCADE
            )
            """.trimIndent()
        )
        db.execSQL(
            """
            CREATE TABLE private_messages (
                arrival_sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                message_id TEXT UNIQUE NOT NULL,
                conversation_id TEXT COLLATE NOCASE NOT NULL,
                sender TEXT NOT NULL,
                content TEXT NOT NULL,
                message_type INTEGER NOT NULL,
                sent_at INTEGER NOT NULL,
                received_at INTEGER NOT NULL,
                is_relay INTEGER NOT NULL,
                original_sender TEXT,
                is_private INTEGER NOT NULL,
                recipient_nickname TEXT,
                sender_peer_id TEXT,
                mentions_json TEXT,
                channel_name TEXT,
                encrypted_content BLOB,
                is_encrypted INTEGER NOT NULL,
                delivery_type INTEGER NOT NULL,
                delivery_text TEXT,
                delivery_at INTEGER,
                delivery_reached INTEGER,
                delivery_total INTEGER,
                sender_nostr_pubkey TEXT,
                payload_ciphertext BLOB NOT NULL,
                is_read INTEGER NOT NULL DEFAULT 0,
                FOREIGN KEY(conversation_id) REFERENCES conversations(conversation_id)
                    ON DELETE CASCADE ON UPDATE CASCADE
            )
            """.trimIndent()
        )
        db.execSQL(
            "CREATE INDEX idx_private_messages_conversation_arrival " +
                "ON private_messages(conversation_id, arrival_sequence)"
        )
        db.execSQL(
            "CREATE INDEX idx_private_messages_read_arrival " +
                "ON private_messages(is_read, arrival_sequence)"
        )
        createAttachmentsTable(db)
        db.execSQL(
            "CREATE INDEX idx_conversation_aliases_conversation " +
                "ON conversation_aliases(conversation_id)"
        )
        db.execSQL(
            """
            CREATE TABLE deleted_private_messages (
                message_id TEXT PRIMARY KEY NOT NULL,
                deleted_at INTEGER NOT NULL
            )
            """.trimIndent()
        )
        db.execSQL(
            "CREATE INDEX idx_deleted_private_messages_time " +
                "ON deleted_private_messages(deleted_at)"
        )
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        var version = oldVersion
        if (version == 1) {
            migrateVersion1To2(db)
            version = 2
        }
        if (version == 2) {
            db.execSQL(
                "ALTER TABLE private_messages " +
                    "ADD COLUMN received_at INTEGER NOT NULL DEFAULT 0"
            )
            db.execSQL(
                "UPDATE private_messages SET received_at = sent_at WHERE received_at = 0"
            )
            version = 3
        }
        if (version == 3) {
            createAttachmentsTable(db)
            db.query(
                "private_messages",
                MESSAGE_COLUMNS,
                null,
                null,
                null,
                null,
                null
            ).use { cursor ->
                while (cursor.moveToNext()) {
                    registerAttachmentLocked(db, cursor.toMessage())
                }
            }
            version = 4
        }
        check(version == newVersion) {
            "Missing conversation database migration from $version to $newVersion"
        }
    }

    private fun migrateVersion1To2(db: SQLiteDatabase) {
        db.execSQL("ALTER TABLE conversations ADD COLUMN display_name_ciphertext BLOB")
        db.execSQL("ALTER TABLE private_messages ADD COLUMN payload_ciphertext BLOB")

        db.query(
            "conversations",
            arrayOf("conversation_id", "display_name"),
            "display_name IS NOT NULL AND display_name != ''",
            null,
            null,
            null,
            null
        ).use { cursor ->
            while (cursor.moveToNext()) {
                val conversationID = cursor.getString(0)
                val displayName = cursor.getString(1)
                db.update(
                    "conversations",
                    ContentValues().apply {
                        put(
                            "display_name_ciphertext",
                            encryptText(displayName, conversationDisplayNameAad(conversationID))
                        )
                        putNull("display_name")
                    },
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(conversationID)
                )
            }
        }

        db.query(
            "private_messages",
            LEGACY_MESSAGE_COLUMNS,
            null,
            null,
            null,
            null,
            "arrival_sequence ASC"
        ).use { cursor ->
            while (cursor.moveToNext()) {
                val message = cursor.toLegacyMessage()
                db.update(
                    "private_messages",
                    ContentValues().apply {
                        put(
                            "payload_ciphertext",
                            encryptMessagePayload(message)
                        )
                        scrubLegacyPayloadColumns(this)
                    },
                    "message_id = ?",
                    arrayOf(message.id)
                )
            }
        }
    }

    private fun createAttachmentsTable(db: SQLiteDatabase) {
        db.execSQL(
            """
            CREATE TABLE IF NOT EXISTS message_attachments (
                message_id TEXT PRIMARY KEY NOT NULL,
                path_hash BLOB NOT NULL,
                path_ciphertext BLOB NOT NULL,
                byte_size INTEGER NOT NULL,
                FOREIGN KEY(message_id) REFERENCES private_messages(message_id)
                    ON DELETE CASCADE ON UPDATE CASCADE
            )
            """.trimIndent()
        )
        db.execSQL(
            "CREATE INDEX IF NOT EXISTS idx_message_attachments_path_hash " +
                "ON message_attachments(path_hash)"
        )
    }

    fun loadSnapshot(): PersistedConversationSnapshot {
        return loadMessages(
            selection = null,
            selectionArgs = null,
            orderBy = "arrival_sequence ASC",
            displayNameConversationID = null
        )
    }

    /**
     * Loads one decrypted row per conversation for startup. Full histories are fetched only when
     * the user opens a chat, keeping cold-start work proportional to conversation count rather
     * than retained-message count.
     */
    fun loadInitialSnapshot(): PersistedConversationSnapshot {
        return loadMessages(
            selection = """
                arrival_sequence IN (
                    SELECT MAX(arrival_sequence)
                    FROM private_messages
                    GROUP BY conversation_id
                )
            """.trimIndent(),
            selectionArgs = null,
            orderBy = "arrival_sequence ASC",
            displayNameConversationID = null
        )
    }

    fun loadConversation(conversationID: String): PersistedConversationSnapshot {
        val resolved = resolveStoredConversationLocked(readableDatabase, conversationID)
        return loadMessages(
            selection = "conversation_id = ? COLLATE NOCASE",
            selectionArgs = arrayOf(resolved),
            orderBy = "arrival_sequence ASC",
            displayNameConversationID = resolved
        )
    }

    private fun loadMessages(
        selection: String?,
        selectionArgs: Array<String>?,
        orderBy: String,
        displayNameConversationID: String?
    ): PersistedConversationSnapshot {
        val chats = linkedMapOf<String, MutableList<BitchatMessage>>()
        val readIDs = linkedSetOf<String>()
        val arrivalOrder = mutableListOf<String>()
        val receivedAtByMessageID = linkedMapOf<String, Long>()
        val arrivalSequenceByMessageID = linkedMapOf<String, Long>()
        readableDatabase.query(
            "private_messages",
            MESSAGE_COLUMNS,
            selection,
            selectionArgs,
            null,
            null,
            orderBy
        ).use { cursor ->
            while (cursor.moveToNext()) {
                val conversationID = cursor.string("conversation_id")
                val message = cursor.toMessage()
                chats.getOrPut(conversationID) { mutableListOf() }.add(message)
                arrivalOrder.add(message.id)
                receivedAtByMessageID[message.id] = cursor.long("received_at")
                arrivalSequenceByMessageID[message.id] = cursor.long("arrival_sequence")
                if (cursor.boolean("is_read")) readIDs.add(message.id)
            }
        }
        return PersistedConversationSnapshot(
            chats = chats.mapValues { it.value.toList() },
            readMessageIDs = readIDs,
            arrivalOrder = arrivalOrder,
            deletedMessageIDs = loadDeletedMessageIDs(),
            displayNames = loadConversationDisplayNames(displayNameConversationID),
            unreadCounts = loadUnreadCounts(),
            receivedAtByMessageID = receivedAtByMessageID,
            arrivalSequenceByMessageID = arrivalSequenceByMessageID
        )
    }

    private fun loadConversationDisplayNames(
        conversationID: String?
    ): Map<String, String> {
        val selection = conversationID?.let { "conversation_id = ? COLLATE NOCASE" }
        val selectionArgs = conversationID?.let { arrayOf(it) }
        return readableDatabase.query(
            "conversations",
            arrayOf("conversation_id", "display_name", "display_name_ciphertext"),
            selection,
            selectionArgs,
            null,
            null,
            null
        ).use { cursor ->
            buildMap {
                while (cursor.moveToNext()) {
                    val storedConversationID = cursor.string("conversation_id")
                    val encryptedColumn =
                        cursor.getColumnIndexOrThrow("display_name_ciphertext")
                    val encryptedName = if (cursor.isNull(encryptedColumn)) {
                        null
                    } else {
                        cursor.getBlob(encryptedColumn)
                    }
                    val displayName = encryptedName?.let {
                        storageCipher.decrypt(
                            it,
                            conversationDisplayNameAad(storedConversationID)
                        ).toString(Charsets.UTF_8)
                    } ?: cursor.nullableString("display_name")
                    displayName
                        ?.takeIf(String::isNotBlank)
                        ?.let { put(storedConversationID, it) }
                }
            }
        }
    }

    private fun loadDeletedMessageIDs(): Set<String> {
        readableDatabase.query(
            "deleted_private_messages",
            arrayOf("message_id"),
            null,
            null,
            null,
            null,
            "deleted_at ASC"
        ).use { cursor ->
            return buildSet {
                while (cursor.moveToNext()) add(cursor.getString(0))
            }
        }
    }

    private fun loadUnreadCounts(): Map<String, Int> =
        readableDatabase.rawQuery(
            """
            SELECT conversation_id, COUNT(*)
            FROM private_messages
            WHERE is_read = 0
            GROUP BY conversation_id
            """.trimIndent(),
            null
        ).use { cursor ->
            buildMap {
                while (cursor.moveToNext()) put(cursor.getString(0), cursor.getInt(1))
            }
        }

    fun upsertMessage(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        message: BitchatMessage,
        isRead: Boolean
    ): ConversationUpsertResult {
        val normalizedID = conversationID.trim()
        if (normalizedID.isBlank()) {
            return ConversationUpsertResult(inserted = false, orphanedMediaPaths = emptySet())
        }
        val now = System.currentTimeMillis()
        val orphanedMediaPaths = linkedSetOf<String>()
        var messageInserted = false
        writableDatabase.inTransaction {
            if (isDeletedMessageLocked(this, message.id)) return@inTransaction
            mergeAliasesLocked(
                db = this,
                targetConversationID = normalizedID,
                aliases = aliases + normalizedID,
                displayName = displayName,
                now = now
            )
            val values = message.toContentValues(normalizedID, isRead)
            val inserted = insertWithOnConflict(
                "private_messages",
                null,
                values,
                SQLiteDatabase.CONFLICT_IGNORE
            )
            messageInserted = inserted != -1L
            if (inserted != -1L) {
                registerAttachmentLocked(this, message)
            }
            if (inserted == -1L) {
                val existingConversation = rawQuery(
                    "SELECT conversation_id, is_read FROM private_messages WHERE message_id = ?",
                    arrayOf(message.id)
                ).use { cursor ->
                    if (cursor.moveToFirst()) {
                        cursor.string("conversation_id") to cursor.boolean("is_read")
                    } else {
                        null
                    }
                }
                if (existingConversation != null) {
                    val canonicalExisting = resolveStoredConversationLocked(
                        this,
                        existingConversation.first
                    )
                    if (!canonicalExisting.equals(normalizedID, ignoreCase = true)) {
                        mergeAliasesLocked(
                            db = this,
                            targetConversationID = normalizedID,
                            aliases = aliases + canonicalExisting,
                            displayName = displayName,
                            now = now
                        )
                    }
                    if (isRead && !existingConversation.second) {
                        update(
                            "private_messages",
                            ContentValues().apply { put("is_read", 1) },
                            "message_id = ?",
                            arrayOf(message.id)
                        )
                    }
                }
            }
            updateConversationMetadataLocked(this, normalizedID, displayName, now)
            orphanedMediaPaths += pruneConversationLocked(this, normalizedID)
        }

        writesSinceGlobalPrune += 1
        if (writesSinceGlobalPrune >= PRUNE_INTERVAL) {
            writesSinceGlobalPrune = 0
            orphanedMediaPaths += pruneToRetentionLimits()
        }
        return ConversationUpsertResult(
            inserted = messageInserted,
            orphanedMediaPaths = orphanedMediaPaths
        )
    }

    fun updateDeliveryStatus(messageID: String, status: DeliveryStatus) {
        val db = writableDatabase
        var found = false
        val existing = db.rawQuery(
            """
            SELECT ${MESSAGE_COLUMNS.joinToString(",")}
            FROM private_messages WHERE message_id = ?
            """.trimIndent(),
            arrayOf(messageID)
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                found = true
                cursor.toMessage().deliveryStatus
            } else {
                null
            }
        }

        if (!found) return
        val mayReplace = when {
            status is DeliveryStatus.Failed ->
                existing !is DeliveryStatus.Delivered && existing !is DeliveryStatus.Read
            existing is DeliveryStatus.Failed -> true
            else -> statusPriority(status) >= statusPriority(existing)
        }
        if (!mayReplace) return
        db.inTransaction {
            val current = rawQuery(
                "SELECT ${MESSAGE_COLUMNS.joinToString(",")} " +
                    "FROM private_messages WHERE message_id = ?",
                arrayOf(messageID)
            ).use { cursor ->
                if (cursor.moveToFirst()) cursor.toMessage() else null
            } ?: return@inTransaction
            update(
                "private_messages",
                ContentValues().apply {
                    putAll(deliveryValues(status, includeSensitiveText = false))
                    put(
                        "payload_ciphertext",
                        encryptMessagePayload(current.copy(deliveryStatus = status))
                    )
                },
                "message_id = ?",
                arrayOf(messageID)
            )
        }
    }

    fun markRead(messageID: String) {
        writableDatabase.update(
            "private_messages",
            ContentValues().apply { put("is_read", 1) },
            "message_id = ?",
            arrayOf(messageID)
        )
    }

    fun setConversationRead(conversationID: String, isRead: Boolean): String? {
        val resolved = resolveStoredConversationLocked(writableDatabase, conversationID)
        return writableDatabase.inTransaction {
            if (isRead) {
                update(
                    "private_messages",
                    ContentValues().apply { put("is_read", 1) },
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(resolved)
                )
                null
            } else {
                val latestMessageID = rawQuery(
                    """
                    SELECT message_id
                    FROM private_messages
                    WHERE conversation_id = ? COLLATE NOCASE
                    ORDER BY arrival_sequence DESC
                    LIMIT 1
                    """.trimIndent(),
                    arrayOf(resolved)
                ).use { cursor ->
                    if (cursor.moveToFirst()) cursor.getString(0) else null
                }
                if (latestMessageID != null) {
                    update(
                        "private_messages",
                        ContentValues().apply { put("is_read", 0) },
                        "message_id = ?",
                        arrayOf(latestMessageID)
                    )
                }
                latestMessageID
            }
        }
    }

    fun mergeAliases(targetConversationID: String, aliases: Set<String>) {
        if (targetConversationID.isBlank()) return
        writableDatabase.inTransaction {
            mergeAliasesLocked(
                db = this,
                targetConversationID = targetConversationID,
                aliases = aliases + targetConversationID,
                displayName = null,
                now = System.currentTimeMillis()
            )
        }
    }

    fun updateConversationIdentity(
        conversationID: String,
        aliases: Set<String>,
        displayName: String
    ) {
        if (conversationID.isBlank() || displayName.isBlank()) return
        writableDatabase.inTransaction {
            mergeAliasesLocked(
                db = this,
                targetConversationID = conversationID,
                aliases = aliases + conversationID,
                displayName = displayName,
                now = System.currentTimeMillis()
            )
        }
    }

    fun deleteConversation(conversationID: String, aliases: Set<String>): Set<String> =
        writableDatabase.inTransaction {
            val ids = linkedSetOf<String>()
            (aliases + conversationID).forEach { value ->
                ids.add(resolveStoredConversationLocked(this, value))
                ids.add(value)
            }
            ids.filter { it.isNotBlank() }.forEach { id ->
                execSQL(
                    """
                    INSERT OR REPLACE INTO deleted_private_messages(message_id, deleted_at)
                    SELECT message_id, ? FROM private_messages
                    WHERE conversation_id = ? COLLATE NOCASE
                    """.trimIndent(),
                    arrayOf<Any>(System.currentTimeMillis(), id)
                )
            }
            val messageIDs = ids
                .filter(String::isNotBlank)
                .flatMapTo(linkedSetOf()) { id ->
                    queryMessageIDsLocked(this, id)
                }
            val attachmentCandidates = attachmentCandidatesLocked(this, messageIDs)
            ids.filter { it.isNotBlank() }.forEach { id ->
                delete(
                    "conversations",
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(id)
                )
            }
            pruneDeletedMessageIDsLocked(this)
            unreferencedAttachmentPathsLocked(this, attachmentCandidates)
        }

    fun deleteMessage(messageID: String): Set<String> =
        writableDatabase.inTransaction {
            val attachmentCandidates = attachmentCandidatesLocked(this, listOf(messageID))
            insertWithOnConflict(
                "deleted_private_messages",
                null,
                ContentValues().apply {
                    put("message_id", messageID)
                    put("deleted_at", System.currentTimeMillis())
                },
                SQLiteDatabase.CONFLICT_REPLACE
            )
            delete("private_messages", "message_id = ?", arrayOf(messageID))
            delete(
                "conversations",
                """
                NOT EXISTS (
                    SELECT 1 FROM private_messages
                    WHERE private_messages.conversation_id = conversations.conversation_id
                )
                """.trimIndent(),
                null
            )
            pruneDeletedMessageIDsLocked(this)
            unreferencedAttachmentPathsLocked(this, attachmentCandidates)
        }

    fun restoreConversation(
        conversationID: String,
        aliases: Set<String>,
        displayName: String?,
        messages: List<BitchatMessage>,
        readMessageIDs: Set<String>
    ): Set<String> {
        if (messages.isEmpty()) return emptySet()
        val now = System.currentTimeMillis()
        writableDatabase.inTransaction {
            mergeAliasesLocked(
                db = this,
                targetConversationID = conversationID,
                aliases = aliases + conversationID,
                displayName = displayName,
                now = now
            )
            messages.forEach { message ->
                delete(
                    "deleted_private_messages",
                    "message_id = ?",
                    arrayOf(message.id)
                )
                val inserted = insertWithOnConflict(
                    "private_messages",
                    null,
                    message.toContentValues(
                        conversationID = conversationID,
                        isRead = message.id in readMessageIDs
                    ),
                    SQLiteDatabase.CONFLICT_IGNORE
                )
                if (inserted != -1L) registerAttachmentLocked(this, message)
            }
            updateConversationMetadataLocked(this, conversationID, displayName, now)
        }
        return pruneToRetentionLimits()
    }

    fun clearAll() {
        // Destroy the only usable copy of the history key before attempting filesystem cleanup.
        storageCipher.destroyKey()
        writableDatabase.inTransaction {
            delete("conversation_aliases", null, null)
            delete("message_attachments", null, null)
            delete("private_messages", null, null)
            delete("conversations", null, null)
            delete("deleted_private_messages", null, null)
            execSQL("DELETE FROM sqlite_sequence WHERE name = 'private_messages'")
        }
        writableDatabase.rawQuery("PRAGMA wal_checkpoint(TRUNCATE)", null).use { }
        writableDatabase.rawQuery("PRAGMA incremental_vacuum", null).use { }
    }

    fun pruneToRetentionLimits(): Set<String> {
        val db = writableDatabase
        val orphanedMediaPaths = linkedSetOf<String>()
        db.inTransaction {
            rawQuery(
                "SELECT conversation_id FROM conversations",
                null
            ).use { cursor ->
                while (cursor.moveToNext()) {
                    orphanedMediaPaths += pruneConversationLocked(this, cursor.getString(0))
                }
            }

            var stats = storageStatsLocked(this)
            while (
                stats.messageCount > maxMessagesTotal ||
                stats.payloadBytes > maxPayloadBytes ||
                stats.mediaBytes > maxMediaBytes
            ) {
                val candidateLimit = if (stats.messageCount > maxMessagesTotal) {
                    (stats.messageCount - maxMessagesTotal)
                        .coerceAtMost(PRUNE_BATCH_SIZE.toLong())
                        .toInt()
                } else {
                    // Payload sizes vary, so recalculate after each removal instead of
                    // discarding an entire batch unnecessarily.
                    1
                }
                val candidates = pruneCandidatesLocked(
                    db = this,
                    readOnly = true,
                    preserveLatest = true,
                    limit = candidateLimit
                ).ifEmpty {
                    pruneCandidatesLocked(
                        db = this,
                        readOnly = false,
                        preserveLatest = true,
                        limit = candidateLimit
                    )
                }.ifEmpty {
                    // A store with one message in every conversation still needs a hard bound.
                    // Prefer retiring read conversations before unread ones.
                    pruneCandidatesLocked(
                        db = this,
                        readOnly = true,
                        preserveLatest = false,
                        limit = candidateLimit
                    )
                }.ifEmpty {
                    pruneCandidatesLocked(
                        db = this,
                        readOnly = false,
                        preserveLatest = false,
                        limit = candidateLimit
                    )
                }
                if (candidates.isEmpty()) break
                tombstoneMessagesLocked(this, candidates)
                val attachmentCandidates = attachmentCandidatesLocked(this, candidates)
                candidates.forEach { messageID ->
                    delete("private_messages", "message_id = ?", arrayOf(messageID))
                }
                orphanedMediaPaths +=
                    unreferencedAttachmentPathsLocked(this, attachmentCandidates)
                deleteEmptyConversationsLocked(this)
                pruneDeletedMessageIDsLocked(this)
                stats = storageStatsLocked(this)
            }
        }
        db.rawQuery("PRAGMA incremental_vacuum(128)", null).use { }
        return orphanedMediaPaths
    }

    private fun mergeAliasesLocked(
        db: SQLiteDatabase,
        targetConversationID: String,
        aliases: Set<String>,
        displayName: String?,
        now: Long
    ) {
        val normalizedAliases = aliases
            .map(String::trim)
            .filter(String::isNotBlank)
            .toSet()
        val sourceIDs = normalizedAliases
            .mapTo(linkedSetOf()) { resolveStoredConversationLocked(db, it) }
            .plus(
                db.queryValues(
                    table = "conversation_aliases",
                    resultColumn = "conversation_id",
                    selectionValues = normalizedAliases
                )
            )
        val effectiveDisplayName = displayName
            ?: (listOf(targetConversationID) + sourceIDs + normalizedAliases)
                .asSequence()
                .mapNotNull { storedConversationDisplayNameLocked(db, it) }
                .firstOrNull()
        ensureConversationLocked(db, targetConversationID, effectiveDisplayName, now)

        sourceIDs
            .filterNot { it.equals(targetConversationID, ignoreCase = true) }
            .forEach { sourceID ->
                db.update(
                    "private_messages",
                    ContentValues().apply { put("conversation_id", targetConversationID) },
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(sourceID)
                )
                db.update(
                    "conversation_aliases",
                    ContentValues().apply { put("conversation_id", targetConversationID) },
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(sourceID)
                )
                db.delete(
                    "conversations",
                    "conversation_id = ? COLLATE NOCASE",
                    arrayOf(sourceID)
                )
            }

        (normalizedAliases + sourceIDs + targetConversationID).forEach { alias ->
            db.insertWithOnConflict(
                "conversation_aliases",
                null,
                ContentValues().apply {
                    put("alias", alias)
                    put("conversation_id", targetConversationID)
                },
                SQLiteDatabase.CONFLICT_REPLACE
            )
        }
        updateConversationMetadataLocked(
            db,
            targetConversationID,
            effectiveDisplayName,
            now
        )
    }

    private fun storedConversationDisplayNameLocked(
        db: SQLiteDatabase,
        conversationID: String
    ): String? = db.query(
        "conversations",
        arrayOf("conversation_id", "display_name", "display_name_ciphertext"),
        "conversation_id = ? COLLATE NOCASE",
        arrayOf(conversationID),
        null,
        null,
        null,
        "1"
    ).use { cursor ->
        if (!cursor.moveToFirst()) return@use null
        val storedConversationID = cursor.string("conversation_id")
        cursor.blobOrNull("display_name_ciphertext")?.let {
            storageCipher.decrypt(
                it,
                conversationDisplayNameAad(storedConversationID)
            ).toString(Charsets.UTF_8)
        } ?: cursor.nullableString("display_name")
    }

    private fun ensureConversationLocked(
        db: SQLiteDatabase,
        conversationID: String,
        displayName: String?,
        now: Long
    ) {
        db.insertWithOnConflict(
            "conversations",
            null,
            ContentValues().apply {
                put("conversation_id", conversationID)
                putNull("display_name")
                if (!displayName.isNullOrBlank()) {
                    put(
                        "display_name_ciphertext",
                        encryptText(displayName, conversationDisplayNameAad(conversationID))
                    )
                }
                put("created_at", now)
                put("updated_at", now)
            },
            SQLiteDatabase.CONFLICT_IGNORE
        )
    }

    private fun updateConversationMetadataLocked(
        db: SQLiteDatabase,
        conversationID: String,
        displayName: String?,
        now: Long
    ) {
        db.update(
            "conversations",
            ContentValues().apply {
                if (!displayName.isNullOrBlank()) {
                    putNull("display_name")
                    put(
                        "display_name_ciphertext",
                        encryptText(displayName, conversationDisplayNameAad(conversationID))
                    )
                }
                put("updated_at", now)
            },
            "conversation_id = ? COLLATE NOCASE",
            arrayOf(conversationID)
        )
    }

    private fun resolveStoredConversationLocked(db: SQLiteDatabase, value: String): String {
        if (value.isBlank()) return value
        return db.rawQuery(
            "SELECT conversation_id FROM conversation_aliases WHERE alias = ? COLLATE NOCASE",
            arrayOf(value)
        ).use { cursor ->
            if (cursor.moveToFirst()) cursor.getString(0) else value
        }
    }

    private fun isDeletedMessageLocked(db: SQLiteDatabase, messageID: String): Boolean =
        db.longForQuery(
            "SELECT COUNT(*) FROM deleted_private_messages WHERE message_id = ?",
            arrayOf(messageID)
        ) > 0L

    private fun pruneDeletedMessageIDsLocked(db: SQLiteDatabase) {
        val excess = (
            db.longForQuery(
                "SELECT COUNT(*) FROM deleted_private_messages",
                emptyArray()
            ) - maxMessagesTotal
            ).coerceAtLeast(0L)
        if (excess == 0L) return
        db.execSQL(
            """
            DELETE FROM deleted_private_messages
            WHERE message_id IN (
                SELECT message_id FROM deleted_private_messages
                ORDER BY deleted_at ASC
                LIMIT ?
            )
            """.trimIndent(),
            arrayOf(excess)
        )
    }

    private fun pruneConversationLocked(
        db: SQLiteDatabase,
        conversationID: String
    ): Set<String> {
        val count = db.longForQuery(
            "SELECT COUNT(*) FROM private_messages WHERE conversation_id = ? COLLATE NOCASE",
            arrayOf(conversationID)
        )
        val excess = (count - maxMessagesPerConversation).coerceAtLeast(0L)
        if (excess == 0L) return emptySet()
        return db.rawQuery(
            """
            SELECT message_id
            FROM private_messages
            WHERE conversation_id = ? COLLATE NOCASE
                AND arrival_sequence < (
                    SELECT MAX(arrival_sequence)
                    FROM private_messages
                    WHERE conversation_id = ? COLLATE NOCASE
                )
            ORDER BY is_read DESC, arrival_sequence ASC
            LIMIT ?
            """.trimIndent(),
            arrayOf(conversationID, conversationID, excess.toString())
        ).use { cursor ->
            val ids = mutableListOf<String>()
            while (cursor.moveToNext()) ids.add(cursor.getString(0))
            val attachmentCandidates = attachmentCandidatesLocked(db, ids)
            tombstoneMessagesLocked(db, ids)
            ids.forEach { db.delete("private_messages", "message_id = ?", arrayOf(it)) }
            pruneDeletedMessageIDsLocked(db)
            unreferencedAttachmentPathsLocked(db, attachmentCandidates)
        }
    }

    private fun storageStatsLocked(db: SQLiteDatabase): ConversationStorageStats =
        db.rawQuery(
            """
            SELECT COUNT(*),
                COALESCE(SUM(
                    COALESCE(length(payload_ciphertext), 0)
                ), 0),
                COALESCE((
                    SELECT SUM(unique_attachment.byte_size)
                    FROM (
                        SELECT MAX(byte_size) AS byte_size
                        FROM message_attachments
                        GROUP BY path_hash
                    ) AS unique_attachment
                ), 0)
            FROM private_messages
            """.trimIndent(),
            null
        ).use { cursor ->
            cursor.moveToFirst()
            ConversationStorageStats(
                messageCount = cursor.getLong(0),
                payloadBytes = cursor.getLong(1),
                mediaBytes = cursor.getLong(2)
            )
        }

    private fun registerAttachmentLocked(db: SQLiteDatabase, message: BitchatMessage) {
        if (message.type !in MEDIA_MESSAGE_TYPES) return
        val path = appOwnedCanonicalPath(message.content) ?: return
        val pathBytes = path.toByteArray(Charsets.UTF_8)
        db.insertWithOnConflict(
            "message_attachments",
            null,
            ContentValues().apply {
                put("message_id", message.id)
                put("path_hash", MessageDigest.getInstance("SHA-256").digest(pathBytes))
                put(
                    "path_ciphertext",
                    storageCipher.encrypt(pathBytes, attachmentPathAad(message.id))
                )
                put("byte_size", File(path).takeIf(File::isFile)?.length() ?: 0L)
            },
            SQLiteDatabase.CONFLICT_REPLACE
        )
    }

    private fun queryMessageIDsLocked(
        db: SQLiteDatabase,
        conversationID: String
    ): List<String> =
        db.query(
            "private_messages",
            arrayOf("message_id"),
            "conversation_id = ? COLLATE NOCASE",
            arrayOf(conversationID),
            null,
            null,
            null
        ).use { cursor ->
            buildList {
                while (cursor.moveToNext()) add(cursor.getString(0))
            }
        }

    private fun attachmentCandidatesLocked(
        db: SQLiteDatabase,
        messageIDs: Collection<String>
    ): List<AttachmentCandidate> {
        if (messageIDs.isEmpty()) return emptyList()
        return buildList {
            messageIDs.toList().chunked(400).forEach { chunk ->
                val placeholders = chunk.joinToString(",") { "?" }
                db.rawQuery(
                    """
                    SELECT message_id, path_hash, path_ciphertext
                    FROM message_attachments
                    WHERE message_id IN ($placeholders)
                    """.trimIndent(),
                    chunk.toTypedArray()
                ).use { cursor ->
                    while (cursor.moveToNext()) {
                        val messageID = cursor.getString(0)
                        val path = storageCipher.decrypt(
                            cursor.getBlob(2),
                            attachmentPathAad(messageID)
                        ).toString(Charsets.UTF_8)
                        add(
                            AttachmentCandidate(
                                pathHash = cursor.getBlob(1),
                                canonicalPath = path
                            )
                        )
                    }
                }
            }
        }
    }

    private fun unreferencedAttachmentPathsLocked(
        db: SQLiteDatabase,
        candidates: Collection<AttachmentCandidate>
    ): Set<String> = candidates
        .filter { candidate ->
            db.rawQuery(
                "SELECT COUNT(*) FROM message_attachments WHERE hex(path_hash) = ?",
                arrayOf(candidate.pathHash.toHex().uppercase())
            ).use { cursor ->
                cursor.moveToFirst()
                cursor.getLong(0) == 0L
            }
        }
        .mapTo(linkedSetOf(), AttachmentCandidate::canonicalPath)

    private fun appOwnedCanonicalPath(value: String): String? {
        val file = runCatching { File(value.trim()).canonicalFile }.getOrNull() ?: return null
        val roots = listOf(applicationContext.filesDir, applicationContext.cacheDir)
            .mapNotNull { runCatching { it.canonicalFile }.getOrNull() }
        return file.path.takeIf { path ->
            roots.any { root ->
                path == root.path || path.startsWith(root.path + File.separator)
            }
        }
    }

    private fun attachmentPathAad(messageID: String): ByteArray =
        "attachment:$messageID:path".toByteArray(Charsets.UTF_8)

    private fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it) }

    private data class ConversationStorageStats(
        val messageCount: Long,
        val payloadBytes: Long,
        val mediaBytes: Long
    )

    private data class AttachmentCandidate(
        val pathHash: ByteArray,
        val canonicalPath: String
    )

    private val MEDIA_MESSAGE_TYPES = setOf(
        BitchatMessageType.Audio,
        BitchatMessageType.Image,
        BitchatMessageType.File
    )

    private fun pruneCandidatesLocked(
        db: SQLiteDatabase,
        readOnly: Boolean,
        preserveLatest: Boolean,
        limit: Int
    ): List<String> {
        val readClause = if (readOnly) "AND candidate.is_read = 1" else ""
        val newerMessageClause = if (preserveLatest) {
            """
            AND EXISTS (
                SELECT 1
                FROM private_messages AS newer
                WHERE newer.conversation_id = candidate.conversation_id
                    AND newer.arrival_sequence > candidate.arrival_sequence
            )
            """.trimIndent()
        } else {
            ""
        }
        return db.rawQuery(
            """
            SELECT candidate.message_id
            FROM private_messages AS candidate
            WHERE 1 = 1
            $newerMessageClause
            $readClause
            ORDER BY candidate.arrival_sequence ASC
            LIMIT $limit
            """.trimIndent(),
            null
        ).use { cursor ->
            buildList {
                while (cursor.moveToNext()) add(cursor.getString(0))
            }
        }
    }

    private fun deleteEmptyConversationsLocked(db: SQLiteDatabase) {
        db.delete(
            "conversations",
            """
            NOT EXISTS (
                SELECT 1 FROM private_messages
                WHERE private_messages.conversation_id = conversations.conversation_id
            )
            """.trimIndent(),
            null
        )
    }

    private fun tombstoneMessagesLocked(
        db: SQLiteDatabase,
        messageIDs: Collection<String>
    ) {
        val deletedAt = System.currentTimeMillis()
        messageIDs.forEach { messageID ->
            db.insertWithOnConflict(
                "deleted_private_messages",
                null,
                ContentValues().apply {
                    put("message_id", messageID)
                    put("deleted_at", deletedAt)
                },
                SQLiteDatabase.CONFLICT_REPLACE
            )
        }
    }

    private fun SQLiteDatabase.queryValues(
        table: String,
        resultColumn: String,
        selectionValues: Set<String>
    ): Set<String> {
        if (selectionValues.isEmpty()) return emptySet()
        val placeholders = selectionValues.joinToString(",") { "?" }
        return rawQuery(
            "SELECT $resultColumn FROM $table WHERE alias IN ($placeholders)",
            selectionValues.toTypedArray()
        ).use { cursor ->
            buildSet {
                while (cursor.moveToNext()) add(cursor.getString(0))
            }
        }
    }

    private fun SQLiteDatabase.longForQuery(sql: String, args: Array<String>): Long =
        rawQuery(sql, args).use { cursor ->
            cursor.moveToFirst()
            cursor.getLong(0)
        }

    private inline fun <T> SQLiteDatabase.inTransaction(block: SQLiteDatabase.() -> T): T {
        beginTransaction()
        return try {
            val result = block()
            setTransactionSuccessful()
            result
        } finally {
            endTransaction()
        }
    }

    private fun BitchatMessage.toContentValues(
        conversationID: String,
        isRead: Boolean
    ): ContentValues = ContentValues().apply {
        put("message_id", id)
        put("conversation_id", conversationID)
        // Version 1 columns remain for lossless migration compatibility, but sensitive values are
        // scrubbed and only the authenticated encrypted payload is populated for new writes.
        put("sender", "")
        put("content", "")
        put("message_type", type.ordinal)
        put("sent_at", timestamp.time)
        put("received_at", System.currentTimeMillis())
        put("is_relay", isRelay.asInt())
        putNull("original_sender")
        put("is_private", isPrivate.asInt())
        putNull("recipient_nickname")
        putNull("sender_peer_id")
        putNull("mentions_json")
        putNull("channel_name")
        putNull("encrypted_content")
        put("is_encrypted", isEncrypted.asInt())
        putAll(deliveryValues(deliveryStatus, includeSensitiveText = false))
        putNull("sender_nostr_pubkey")
        put("payload_ciphertext", encryptMessagePayload(this@toContentValues))
        put("is_read", isRead.asInt())
    }

    private fun deliveryValues(
        status: DeliveryStatus?,
        includeSensitiveText: Boolean = true
    ): ContentValues = ContentValues().apply {
        when (status) {
            null -> put("delivery_type", 0)
            DeliveryStatus.Sending -> put("delivery_type", 1)
            DeliveryStatus.Sent -> put("delivery_type", 2)
            is DeliveryStatus.Delivered -> {
                put("delivery_type", 3)
                if (includeSensitiveText) put("delivery_text", status.to) else putNull("delivery_text")
                put("delivery_at", status.at.time)
            }
            is DeliveryStatus.Read -> {
                put("delivery_type", 4)
                if (includeSensitiveText) put("delivery_text", status.by) else putNull("delivery_text")
                put("delivery_at", status.at.time)
            }
            is DeliveryStatus.Failed -> {
                put("delivery_type", 5)
                if (includeSensitiveText) put("delivery_text", status.reason) else putNull("delivery_text")
            }
            is DeliveryStatus.PartiallyDelivered -> {
                put("delivery_type", 6)
                put("delivery_reached", status.reached)
                put("delivery_total", status.total)
            }
        }
    }

    private fun statusPriority(status: DeliveryStatus?): Int = when (status) {
        null -> 0
        is DeliveryStatus.Failed -> 0
        DeliveryStatus.Sending -> 1
        DeliveryStatus.Sent -> 2
        is DeliveryStatus.PartiallyDelivered -> 3
        is DeliveryStatus.Delivered -> 4
        is DeliveryStatus.Read -> 5
    }

    private fun Cursor.toMessage(): BitchatMessage {
        val messageID = string("message_id")
        val encryptedPayload = blobOrNull("payload_ciphertext")
            ?: error("Conversation message $messageID has no encrypted payload")
        val payload = decryptMessagePayload(messageID, encryptedPayload)
        return BitchatMessage(
            id = messageID,
            sender = payload.sender,
            content = payload.content,
            type = BitchatMessageType.entries.getOrElse(int("message_type")) {
                BitchatMessageType.Message
            },
            timestamp = Date(long("sent_at")),
            isRelay = boolean("is_relay"),
            originalSender = payload.originalSender,
            isPrivate = boolean("is_private"),
            recipientNickname = payload.recipientNickname,
            senderPeerID = payload.senderPeerID,
            mentions = payload.mentions,
            channel = payload.channel,
            encryptedContent = payload.encryptedContent,
            isEncrypted = boolean("is_encrypted"),
            deliveryStatus = toDeliveryStatus(payload.deliveryText),
            senderNostrPubkey = payload.senderNostrPubkey
        )
    }

    private fun Cursor.toLegacyMessage(): BitchatMessage = BitchatMessage(
        id = string("message_id"),
        sender = string("sender"),
        content = string("content"),
        type = BitchatMessageType.entries.getOrElse(int("message_type")) {
            BitchatMessageType.Message
        },
        timestamp = Date(long("sent_at")),
        isRelay = boolean("is_relay"),
        originalSender = nullableString("original_sender"),
        isPrivate = boolean("is_private"),
        recipientNickname = nullableString("recipient_nickname"),
        senderPeerID = nullableString("sender_peer_id"),
        mentions = nullableString("mentions_json")?.let(::jsonStringList),
        channel = nullableString("channel_name"),
        encryptedContent = blobOrNull("encrypted_content"),
        isEncrypted = boolean("is_encrypted"),
        deliveryStatus = toDeliveryStatus(),
        senderNostrPubkey = nullableString("sender_nostr_pubkey")
    )

    private fun Cursor.toDeliveryStatus(deliveryText: String? = nullableString("delivery_text")):
        DeliveryStatus? = when (int("delivery_type")) {
        1 -> DeliveryStatus.Sending
        2 -> DeliveryStatus.Sent
        3 -> DeliveryStatus.Delivered(
            to = deliveryText.orEmpty(),
            at = Date(nullableLong("delivery_at") ?: 0L)
        )
        4 -> DeliveryStatus.Read(
            by = deliveryText.orEmpty(),
            at = Date(nullableLong("delivery_at") ?: 0L)
        )
        5 -> DeliveryStatus.Failed(deliveryText.orEmpty())
        6 -> DeliveryStatus.PartiallyDelivered(
            reached = nullableInt("delivery_reached") ?: 0,
            total = nullableInt("delivery_total") ?: 0
        )
        else -> null
    }

    private fun jsonStringList(json: String): List<String> {
        val array = JSONArray(json)
        return buildList(array.length()) {
            for (index in 0 until array.length()) add(array.getString(index))
        }
    }

    private fun Cursor.index(column: String): Int = getColumnIndexOrThrow(column)
    private fun Cursor.string(column: String): String = getString(index(column))
    private fun Cursor.nullableString(column: String): String? =
        index(column).let { if (isNull(it)) null else getString(it) }
    private fun Cursor.int(column: String): Int = getInt(index(column))
    private fun Cursor.nullableInt(column: String): Int? =
        index(column).let { if (isNull(it)) null else getInt(it) }
    private fun Cursor.long(column: String): Long = getLong(index(column))
    private fun Cursor.nullableLong(column: String): Long? =
        index(column).let { if (isNull(it)) null else getLong(it) }
    private fun Cursor.boolean(column: String): Boolean = int(column) != 0
    private fun Cursor.blobOrNull(column: String): ByteArray? =
        index(column).let { if (isNull(it)) null else getBlob(it) }
    private fun Boolean.asInt(): Int = if (this) 1 else 0

    private fun encryptMessagePayload(message: BitchatMessage): ByteArray {
        val json = JSONObject().apply {
            put("sender", message.sender)
            put("content", message.content)
            putNullable("original_sender", message.originalSender)
            putNullable("recipient_nickname", message.recipientNickname)
            putNullable("sender_peer_id", message.senderPeerID)
            putNullable("mentions_json", message.mentions?.let(::JSONArray))
            putNullable("channel_name", message.channel)
            putNullable(
                "encrypted_content",
                message.encryptedContent?.let {
                    Base64.encodeToString(it, Base64.NO_WRAP)
                }
            )
            putNullable("delivery_text", message.deliveryStatus.sensitiveText())
            putNullable("sender_nostr_pubkey", message.senderNostrPubkey)
        }
        return storageCipher.encrypt(
            json.toString().toByteArray(Charsets.UTF_8),
            messagePayloadAad(message.id)
        )
    }

    private fun decryptMessagePayload(
        messageID: String,
        encryptedPayload: ByteArray
    ): StoredMessagePayload {
        val json = JSONObject(
            storageCipher.decrypt(encryptedPayload, messagePayloadAad(messageID))
                .toString(Charsets.UTF_8)
        )
        return StoredMessagePayload(
            sender = json.getString("sender"),
            content = json.getString("content"),
            originalSender = json.optionalString("original_sender"),
            recipientNickname = json.optionalString("recipient_nickname"),
            senderPeerID = json.optionalString("sender_peer_id"),
            mentions = json.optionalArray("mentions_json")?.let(::jsonStringList),
            channel = json.optionalString("channel_name"),
            encryptedContent = json.optionalString("encrypted_content")?.let {
                Base64.decode(it, Base64.NO_WRAP)
            },
            deliveryText = json.optionalString("delivery_text"),
            senderNostrPubkey = json.optionalString("sender_nostr_pubkey")
        )
    }

    private fun encryptText(value: String, associatedData: ByteArray): ByteArray =
        storageCipher.encrypt(value.toByteArray(Charsets.UTF_8), associatedData)

    private fun messagePayloadAad(messageID: String): ByteArray =
        "message:$messageID".toByteArray(Charsets.UTF_8)

    private fun conversationDisplayNameAad(conversationID: String): ByteArray =
        "conversation:$conversationID:display-name".toByteArray(Charsets.UTF_8)

    private fun scrubLegacyPayloadColumns(values: ContentValues) {
        values.put("sender", "")
        values.put("content", "")
        values.putNull("original_sender")
        values.putNull("recipient_nickname")
        values.putNull("sender_peer_id")
        values.putNull("mentions_json")
        values.putNull("channel_name")
        values.putNull("encrypted_content")
        values.putNull("delivery_text")
        values.putNull("sender_nostr_pubkey")
    }

    private fun JSONObject.putNullable(key: String, value: Any?) {
        put(key, value ?: JSONObject.NULL)
    }

    private fun JSONObject.optionalString(key: String): String? =
        if (!has(key) || isNull(key)) null else getString(key)

    private fun JSONObject.optionalArray(key: String): JSONArray? =
        if (!has(key) || isNull(key)) null else getJSONArray(key)

    private fun jsonStringList(array: JSONArray): List<String> =
        buildList(array.length()) {
            for (index in 0 until array.length()) add(array.getString(index))
        }

    private fun DeliveryStatus?.sensitiveText(): String? = when (this) {
        is DeliveryStatus.Delivered -> to
        is DeliveryStatus.Read -> by
        is DeliveryStatus.Failed -> reason
        else -> null
    }

    private data class StoredMessagePayload(
        val sender: String,
        val content: String,
        val originalSender: String?,
        val recipientNickname: String?,
        val senderPeerID: String?,
        val mentions: List<String>?,
        val channel: String?,
        val encryptedContent: ByteArray?,
        val deliveryText: String?,
        val senderNostrPubkey: String?
    )

    private val MESSAGE_COLUMNS = arrayOf(
        "arrival_sequence",
        "message_id",
        "conversation_id",
        "sender",
        "content",
        "message_type",
        "sent_at",
        "received_at",
        "is_relay",
        "original_sender",
        "is_private",
        "recipient_nickname",
        "sender_peer_id",
        "mentions_json",
        "channel_name",
        "encrypted_content",
        "is_encrypted",
        "delivery_type",
        "delivery_text",
        "delivery_at",
        "delivery_reached",
        "delivery_total",
        "sender_nostr_pubkey",
        "payload_ciphertext",
        "is_read"
    )

    private val LEGACY_MESSAGE_COLUMNS = MESSAGE_COLUMNS.filterNot {
        it == "payload_ciphertext" || it == "received_at"
    }.toTypedArray()
}

package com.bitchat.android.services

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * Encrypts private-conversation payloads with a key that never leaves Android Keystore.
 *
 * Every value is bound to its database identity through AES-GCM associated data. This prevents an
 * encrypted payload copied from one message or conversation row from being accepted in another.
 * Deleting the dedicated alias provides practical cryptographic erasure before SQLite pages, WAL
 * records, and filesystem blocks are reclaimed.
 */
internal interface ConversationStorageCipher {
    fun encrypt(plaintext: ByteArray, associatedData: ByteArray): ByteArray
    fun decrypt(envelope: ByteArray, associatedData: ByteArray): ByteArray
    fun destroyKey()
}
internal class AndroidConversationStorageCipher(
    private val keyAlias: String = DEFAULT_KEY_ALIAS
) : ConversationStorageCipher {
    companion object {
        internal const val DEFAULT_KEY_ALIAS = "bitchat_conversation_storage_v1"
        private const val KEYSTORE_PROVIDER = "AndroidKeyStore"
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
        private const val ENVELOPE_VERSION: Byte = 1
        private const val GCM_TAG_BITS = 128
        private const val IV_BYTES = 12
    }

    private val keyLock = Any()
    @Volatile
    private var cachedKey: SecretKey? = null

    override fun encrypt(plaintext: ByteArray, associatedData: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, getOrCreateKey())
        cipher.updateAAD(associatedData)
        val ciphertext = cipher.doFinal(plaintext)
        check(cipher.iv.size == IV_BYTES) { "Unexpected AES-GCM IV length" }
        return byteArrayOf(ENVELOPE_VERSION) + cipher.iv + ciphertext
    }

    override fun decrypt(envelope: ByteArray, associatedData: ByteArray): ByteArray {
        require(envelope.size > 1 + IV_BYTES) { "Conversation payload envelope is truncated" }
        require(envelope[0] == ENVELOPE_VERSION) {
            "Unsupported conversation payload envelope version"
        }
        val iv = envelope.copyOfRange(1, 1 + IV_BYTES)
        val ciphertext = envelope.copyOfRange(1 + IV_BYTES, envelope.size)
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, getOrCreateKey(), GCMParameterSpec(GCM_TAG_BITS, iv))
        cipher.updateAAD(associatedData)
        return cipher.doFinal(ciphertext)
    }

    override fun destroyKey() {
        synchronized(keyLock) {
            cachedKey = null
            val keyStore = KeyStore.getInstance(KEYSTORE_PROVIDER).apply { load(null) }
            if (keyStore.containsAlias(keyAlias)) {
                keyStore.deleteEntry(keyAlias)
            }
        }
    }

    private fun getOrCreateKey(): SecretKey =
        cachedKey ?: synchronized(keyLock) {
            cachedKey ?: run {
                val keyStore = KeyStore.getInstance(KEYSTORE_PROVIDER).apply { load(null) }
                (keyStore.getKey(keyAlias, null) as? SecretKey) ?: generateKey()
            }.also { cachedKey = it }
        }

    private fun generateKey(): SecretKey {
        val generator = KeyGenerator.getInstance(
            KeyProperties.KEY_ALGORITHM_AES,
            KEYSTORE_PROVIDER
        )
        generator.init(
            KeyGenParameterSpec.Builder(
                keyAlias,
                KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
            )
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .setKeySize(256)
                .setRandomizedEncryptionRequired(true)
                .build()
        )
        return generator.generateKey()
    }
}

package com.bitchat.android.services

import com.bitchat.android.model.BitchatMessage
import kotlinx.coroutines.runBlocking

/**
 * Reflects an incoming transport message into process-wide state before any downstream effects.
 *
 * Private-message admission is authoritative: a duplicate or a message rejected while panic mode
 * is wiping state must not continue to UI delegates, unread tracking, haptics, or notifications.
 * Public and channel messages retain their existing best-effort behavior if state reflection fails.
 */
internal object IncomingMessageAdmission {
    fun admitToAppState(message: BitchatMessage): Boolean = try {
        when {
            message.isPrivate -> {
                val peerID = message.senderPeerID?.takeIf(String::isNotBlank)
                    ?: return false
                // Mesh transport callbacks run on their background service workers. Wait for the
                // serialized SQLite transaction so a notification can never advertise a message
                // that an immediate process death would lose.
                runBlocking {
                    AppStateStore.addPrivateMessageDurably(peerID, message)
                }
            }

            message.channel != null -> {
                AppStateStore.addChannelMessage(message.channel, message)
                true
            }

            else -> {
                AppStateStore.addPublicMessage(message)
                true
            }
        }
    } catch (_: Exception) {
        // Preserve the pre-existing best-effort dispatch for public/channel messages, but never
        // bypass private-message admission when persistence or canonicalization fails.
        !message.isPrivate
    }
}

