package com.bitchat.android.services

import com.bitchat.android.model.BitchatMessage

/**
 * Process-local receipt sequence for private messages.
 *
 * Peer-provided timestamps cannot safely order a conversation because clocks can differ. This
 * registry follows the lifetime of [AppStateStore] and lets alias merges reconstruct the order in
 * which messages entered the app, even when they were initially stored under different keys.
 */
internal object PrivateMessageArrivalOrder {
    private val sequenceByMessageID = mutableMapOf<String, Long>()
    private val receivedAtByMessageID = mutableMapOf<String, Long>()
    private var nextSequence = 0L

    fun record(messageID: String, receivedAt: Long = System.currentTimeMillis()) {
        synchronized(this) {
            if (messageID !in sequenceByMessageID) {
                sequenceByMessageID[messageID] = nextSequence++
                receivedAtByMessageID[messageID] = receivedAt
            }
        }
    }

    fun restore(
        persistedOrder: List<String>,
        liveMessageIDs: List<String>,
        persistedReceivedAt: Map<String, Long> = emptyMap(),
        persistedSequences: Map<String, Long> = emptyMap()
    ) {
        synchronized(this) {
            val previousSequences = sequenceByMessageID.toMap()
            val previousReceivedAt = receivedAtByMessageID.toMap()
            sequenceByMessageID.clear()
            receivedAtByMessageID.clear()
            nextSequence = (persistedSequences.values.maxOrNull() ?: -1L) + 1L
            (persistedOrder + liveMessageIDs).forEach { messageID ->
                if (messageID !in sequenceByMessageID) {
                    val sequence = persistedSequences[messageID]
                        ?: previousSequences[messageID]
                        ?: nextSequence++
                    sequenceByMessageID[messageID] = sequence
                    (persistedReceivedAt[messageID] ?: previousReceivedAt[messageID])?.let {
                        receivedAtByMessageID[messageID] = it
                    }
                }
            }
            nextSequence = maxOf(
                nextSequence,
                (sequenceByMessageID.values.maxOrNull() ?: -1L) + 1L
            )
        }
    }

    fun sequenceOf(messageID: String): Long? = synchronized(this) {
        sequenceByMessageID[messageID]
    }

    fun receivedAtOf(messageID: String): Long? = synchronized(this) {
        receivedAtByMessageID[messageID]
    }

    fun order(messages: List<BitchatMessage>): List<BitchatMessage> {
        synchronized(this) {
            if (messages.size < 2 || messages.any { it.id !in sequenceByMessageID }) {
                return messages
            }
            return messages.sortedBy { sequenceByMessageID.getValue(it.id) }
        }
    }

    fun clear() {
        synchronized(this) {
            sequenceByMessageID.clear()
            receivedAtByMessageID.clear()
            nextSequence = 0L
        }
    }
}

package com.bitchat.android.services

import android.annotation.SuppressLint
import android.content.Context
import android.util.Log
import com.bitchat.android.identity.SecureIdentityStateManager
import com.google.gson.Gson
import com.google.gson.annotations.SerializedName

/**
 * Persistent store for message IDs we've already acknowledged as delivered, read locally, or
 * admitted to a completed read-receipt send window.
 *
 * Local read state must not be used as proof that a read-receipt packet reached the sender.
 * Transport delivery is best-effort and retryable, while local read state drives unread UI.
 * Limits to last MAX_IDS entries per set to avoid memory bloat.
 */
class SeenMessageStore private constructor(private val context: Context) {
    companion object {
        private const val TAG = "SeenMessageStore"
        private const val STORAGE_KEY = "seen_message_store_v1"
        private const val MAX_IDS = com.bitchat.android.util.AppConstants.Services.SEEN_MESSAGE_MAX_IDS

        // The constructor always receives applicationContext, so process lifetime is intentional.
        @SuppressLint("StaticFieldLeak")
        @Volatile private var INSTANCE: SeenMessageStore? = null
        fun getInstance(appContext: Context): SeenMessageStore {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: SeenMessageStore(appContext.applicationContext).also { INSTANCE = it }
            }
        }
    }

    private val gson = Gson()
    private val secure = SecureIdentityStateManager(context)

    private val delivered = LinkedHashSet<String>(MAX_IDS)
    private val locallyRead = LinkedHashSet<String>(MAX_IDS)
    private val readReceiptsSent = LinkedHashSet<String>(MAX_IDS)

    init { load() }

    @Synchronized fun hasDelivered(id: String) = delivered.contains(id)
    @Synchronized fun hasBeenReadLocally(id: String) = locallyRead.contains(id)
    @Synchronized fun hasReadReceiptBeenSent(id: String) = readReceiptsSent.contains(id)

    @Synchronized fun markDelivered(id: String) {
        if (delivered.remove(id)) delivered.add(id) else {
            delivered.add(id)
            trim(delivered)
        }
        persist()
    }

    @Synchronized fun markReadLocally(id: String) {
        if (locallyRead.remove(id)) locallyRead.add(id) else {
            locallyRead.add(id)
            trim(locallyRead)
        }
        AppStateStore.markPrivateMessageRead(id)
        persist()
    }

    @Synchronized fun markReadReceiptSent(id: String) {
        if (readReceiptsSent.remove(id)) readReceiptsSent.add(id) else {
            readReceiptsSent.add(id)
            trim(readReceiptsSent)
        }
        persist()
    }

    @Synchronized fun remove(ids: Set<String>) {
        if (ids.isEmpty()) return
        delivered.removeAll(ids)
        locallyRead.removeAll(ids)
        readReceiptsSent.removeAll(ids)
        persist()
    }

    @Synchronized fun clear() {
        delivered.clear()
        locallyRead.clear()
        readReceiptsSent.clear()
        persist()
    }

    private fun trim(set: LinkedHashSet<String>) {
        if (set.size <= MAX_IDS) return
        val it = set.iterator()
        while (set.size > MAX_IDS && it.hasNext()) {
            it.next(); it.remove()
        }
    }

    @Synchronized private fun load() {
        try {
            val json = secure.getSecureValue(STORAGE_KEY) ?: return
            val data = gson.fromJson(json, StorePayload::class.java) ?: return
            delivered.clear(); locallyRead.clear(); readReceiptsSent.clear()
            data.delivered.takeLast(MAX_IDS).forEach { delivered.add(it) }
            data.locallyRead.takeLast(MAX_IDS).forEach { locallyRead.add(it) }
            // Older payloads used the local-read set to suppress receipt sends. Seed the new
            // explicit set once during migration to avoid replaying an entire chat history.
            (data.readReceiptsSent ?: data.locallyRead)
                .takeLast(MAX_IDS)
                .forEach { readReceiptsSent.add(it) }
            Log.d(
                TAG,
                "Loaded delivered=${delivered.size}, locallyRead=${locallyRead.size}, " +
                    "readReceiptsSent=${readReceiptsSent.size}"
            )
        } catch (e: Exception) {
            Log.e(TAG, "Failed to load SeenMessageStore: ${e.message}")
        }
    }

    @Synchronized private fun persist() {
        try {
            val payload = StorePayload(
                delivered = delivered.toList(),
                locallyRead = locallyRead.toList(),
                readReceiptsSent = readReceiptsSent.toList()
            )
            val json = gson.toJson(payload)
            secure.storeSecureValue(STORAGE_KEY, json)
        } catch (e: Exception) {
            Log.e(TAG, "Failed to persist SeenMessageStore: ${e.message}")
        }
    }

    private data class StorePayload(
        val delivered: List<String> = emptyList(),
        // Keep the existing JSON field name for backward-compatible secure-store migration.
        @SerializedName("read")
        val locallyRead: List<String> = emptyList(),
        @SerializedName("read_receipts_sent")
        val readReceiptsSent: List<String>? = null
    )
}

package com.bitchat.android.services.meshgraph

import android.util.Log

/**
 * Gossip TLV helpers for embedding direct neighbor peer IDs in ANNOUNCE payloads.
 * Uses compact TLV: [type=0x04][len=1 byte][value=N*8 bytes of peerIDs]
 */
object GossipTLV {
    // TLV type for a compact list of direct neighbor peerIDs (each 8 bytes)
    const val DIRECT_NEIGHBORS_TYPE: UByte = 0x04u

    /**
     * Encode up to 10 unique peerIDs (hex string up to 16 chars) as TLV value.
     */
    fun encodeNeighbors(peerIDs: List<String>): ByteArray {
        val unique = peerIDs.distinct().take(10)
        val valueBytes = unique.flatMap { id -> hexStringPeerIdTo8Bytes(id).toList() }.toByteArray()
        if (valueBytes.size > 255) {
            // Safety check, though 10*8 = 80 bytes, so well under 255
            Log.w("GossipTLV", "Neighbors value exceeds 255, truncating")
        }
        return byteArrayOf(DIRECT_NEIGHBORS_TYPE.toByte(), valueBytes.size.toByte()) + valueBytes
    }

    /**
     * Scan a TLV-encoded announce payload and extract neighbor peerIDs.
     * Returns null if the TLV is not present at all; returns an empty list if present with length 0.
     */
    fun decodeNeighborsFromAnnouncementPayload(payload: ByteArray): List<String>? {
        val result = mutableListOf<String>()
        var offset = 0
        while (offset + 2 <= payload.size) {
            val type = payload[offset].toUByte()
            val len = payload[offset + 1].toUByte().toInt()
            offset += 2
            if (offset + len > payload.size) break
            val value = payload.sliceArray(offset until offset + len)
            offset += len

            if (type == DIRECT_NEIGHBORS_TYPE) {
                // Value is N*8 bytes of peer IDs
                var pos = 0
                while (pos + 8 <= value.size) {
                    val idBytes = value.sliceArray(pos until pos + 8)
                    result.add(bytesToPeerIdHex(idBytes))
                    pos += 8
                }
                return result // present (possibly empty)
            }
        }
        // Not present
        return null
    }

    private fun hexStringPeerIdTo8Bytes(hexString: String): ByteArray {
        val clean = hexString.lowercase().take(16)
        val result = ByteArray(8) { 0 }
        var idx = 0
        var out = 0
        while (idx + 1 < clean.length && out < 8) {
            val byteStr = clean.substring(idx, idx + 2)
            val b = byteStr.toIntOrNull(16)?.toByte() ?: 0
            result[out++] = b
            idx += 2
        }
        return result
    }

    private fun bytesToPeerIdHex(bytes: ByteArray): String {
        val sb = StringBuilder()
        for (b in bytes.take(8)) {
            sb.append(String.format("%02x", b))
        }
        return sb.toString()
    }
}

package com.bitchat.android.services.meshgraph

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.concurrent.ConcurrentHashMap

/**
 * Maintains an internal graph of the mesh based on gossip.
 * Nodes are peers (peerID), edges are direct connections.
 */
class MeshGraphService private constructor() {
    data class GraphNode(val peerID: String, val nickname: String?)
    data class GraphEdge(val a: String, val b: String, val isConfirmed: Boolean, val confirmedBy: String? = null)
    data class GraphSnapshot(val nodes: List<GraphNode>, val edges: List<GraphEdge>)

    // Map peerID -> nickname (may be null if unknown)
    private val nicknames = ConcurrentHashMap<String, String?>()
    // Announcements: peerID -> set of neighbor peerIDs that *this* peer claims to see
    private val announcements = ConcurrentHashMap<String, Set<String>>()
    // Latest announcement timestamp per peer (ULong from packet)
    private val lastUpdate = ConcurrentHashMap<String, ULong>()

    private val _graphState = MutableStateFlow(GraphSnapshot(emptyList(), emptyList()))
    val graphState: StateFlow<GraphSnapshot> = _graphState.asStateFlow()

    /**
     * Update graph from a verified announcement.
     * Replaces previous neighbors for origin if this is newer (by timestamp).
     */
    fun updateFromAnnouncement(originPeerID: String, originNickname: String?, neighborsOrNull: List<String>?, timestamp: ULong) {
        synchronized(this) {
            // Always update nickname if provided
            if (originNickname != null) nicknames[originPeerID] = originNickname

            // 1. Check timestamp first to ensure this is the latest word from the peer
            val prevTs = lastUpdate[originPeerID]
            if (prevTs != null && prevTs >= timestamp) {
                // Older or equal update: ignore
                return
            }
            lastUpdate[originPeerID] = timestamp

            // 2. Latest announcement determines state.
            // If neighborsOrNull is null (TLV omitted), it means the peer is not reporting any neighbors (empty list).
            val neighbors = neighborsOrNull ?: emptyList()

            // Filter out self-loops just in case
            val newSet = neighbors.distinct().take(10).filter { it != originPeerID }.toSet()
            announcements[originPeerID] = newSet

            publishSnapshot()
        }
    }

    fun updateNickname(peerID: String, nickname: String?) {
        if (nickname == null) return
        nicknames[peerID] = nickname
        publishSnapshot()
    }

    /**
     * Remove a peer from the graph completely (e.g. when stale/offline).
     */
    fun removePeer(peerID: String) {
        synchronized(this) {
            nicknames.remove(peerID)
            announcements.remove(peerID)
            lastUpdate.remove(peerID)
            announcements.keys.toList().forEach { originPeerID ->
                announcements.computeIfPresent(originPeerID) { _, neighbors ->
                    neighbors - peerID
                }
            }
            publishSnapshot()
        }
    }

    private fun publishSnapshot() {
        // Collect all known nodes from nicknames and announcements
        val allNodes = mutableSetOf<String>()
        allNodes.addAll(nicknames.keys)
        announcements.forEach { (origin, neighbors) ->
            allNodes.add(origin)
            allNodes.addAll(neighbors)
        }

        val nodeList = allNodes.map { GraphNode(it, nicknames[it]) }.sortedBy { it.peerID }

        val edges = mutableListOf<GraphEdge>()
        val processedPairs = mutableSetOf<Pair<String, String>>()

        // We only care about connections that exist in at least one direction.
        // So iterating through all entries in `announcements` covers every declared edge.
        announcements.forEach { (source, targets) ->
            targets.forEach { target ->
                val pair = if (source <= target) source to target else target to source
                if (processedPairs.add(pair)) {
                    // This is a new pair we haven't evaluated yet
                    val (a, b) = pair
                    val aAnnouncesB = announcements[a]?.contains(b) == true
                    val bAnnouncesA = announcements[b]?.contains(a) == true

                    if (aAnnouncesB && bAnnouncesA) {
                        edges.add(GraphEdge(a, b, isConfirmed = true))
                    } else if (aAnnouncesB) {
                        edges.add(GraphEdge(a, b, isConfirmed = false, confirmedBy = a))
                    } else if (bAnnouncesA) {
                        edges.add(GraphEdge(a, b, isConfirmed = false, confirmedBy = b))
                    }
                }
            }
        }

        val sortedEdges = edges.sortedWith(compareBy({ it.a }, { it.b }))
        _graphState.value = GraphSnapshot(nodeList, sortedEdges)
    }

    companion object {
        @Volatile private var INSTANCE: MeshGraphService? = null
        fun getInstance(): MeshGraphService = INSTANCE ?: synchronized(this) {
            INSTANCE ?: MeshGraphService().also { INSTANCE = it }
        }

        @org.jetbrains.annotations.TestOnly
        fun resetForTesting() {
            synchronized(this) {
                INSTANCE = null
            }
        }
    }
}

package com.bitchat.android.services.meshgraph

import android.util.Log
import java.util.PriorityQueue

/**
 * Computes shortest paths on the current mesh graph snapshot using Dijkstra.
 * Assumes unit edge weights.
 */
object RoutePlanner {
    private const val TAG = "RoutePlanner"

    /**
     * Return full path [src, ..., dst] if reachable, else null.
     */
    fun shortestPath(src: String, dst: String): List<String>? {
        if (src == dst) return listOf(src)
        val snapshot = MeshGraphService.getInstance().graphState.value
        val neighbors = mutableMapOf<String, MutableSet<String>>()

        // Only consider confirmed edges for routing
        snapshot.edges.filter { it.isConfirmed }.forEach { e ->
            neighbors.getOrPut(e.a) { mutableSetOf() }.add(e.b)
            neighbors.getOrPut(e.b) { mutableSetOf() }.add(e.a)
        }
        // Ensure nodes known even if isolated
        snapshot.nodes.forEach { n -> neighbors.putIfAbsent(n.peerID, mutableSetOf()) }

        if (!neighbors.containsKey(src) || !neighbors.containsKey(dst)) return null

        val dist = mutableMapOf<String, Int>()
        val prev = mutableMapOf<String, String?>()
        val pq = PriorityQueue<Pair<String, Int>>(compareBy { it.second })

        neighbors.keys.forEach { v ->
            dist[v] = if (v == src) 0 else Int.MAX_VALUE
            prev[v] = null
        }
        pq.add(src to 0)

        while (pq.isNotEmpty()) {
            val top = pq.poll() ?: break
            val (u, d) = top
            if (d > (dist[u] ?: Int.MAX_VALUE)) continue
            if (u == dst) break
            neighbors[u]?.forEach { v ->
                val alt = d + 1
                if (alt < (dist[v] ?: Int.MAX_VALUE)) {
                    dist[v] = alt
                    prev[v] = u
                    pq.add(v to alt)
                }
            }
        }

        if ((dist[dst] ?: Int.MAX_VALUE) == Int.MAX_VALUE) return null

        val path = mutableListOf<String>()
        var cur: String? = dst
        while (cur != null) {
            path.add(cur)
            cur = prev[cur]
        }
        path.reverse()
        Log.d(TAG, "Computed path $path")
        return path
    }
}

package com.bitchat.android.sync

import java.security.MessageDigest
import kotlin.math.ceil
import kotlin.math.ln

/**
 * Golomb-Coded Set (GCS) filter implementation for sync.
 *
 * Hashing:
 * - h64(id) = first 8 bytes of SHA-256 over the 16-byte PacketId (big-endian unsigned)
 * - Map to range [0, M) via (h64 % M)
 *
 * Encoding (v1):
 * - Sort mapped values ascending; encode deltas (first is v0, then vi - v{i-1}) as positive integers
 * - For each delta x >= 1, write Golomb-Rice code with parameter P:
 *   q = (x - 1) >> P (unary q ones followed by a zero), then P low bits r = (x - 1) & ((1<<P)-1)
 * - Bitstream is packed MSB-first in each byte.
 */
object GCSFilter {
    data class Params(
        val p: Int,         // Golomb-Rice parameter (>= 1)
        val m: Long,        // Range M = N * 2^P
        val data: ByteArray // Encoded GR bitstream
    )

    // Derive P from target FPR; FPR ~= 1 / 2^P
    fun deriveP(targetFpr: Double): Int {
        val f = targetFpr.coerceIn(0.000001, 0.25)
        return ceil(ln(1.0 / f) / ln(2.0)).toInt().coerceAtLeast(1)
    }

    // Rough capacity estimate: expected bits per element ~= P + 2 (quotient unary ~ around 2 bits)
    fun estimateMaxElementsForSize(bytes: Int, p: Int): Int {
        val bits = (bytes * 8).coerceAtLeast(8)
        val per = (p + 2).coerceAtLeast(3)
        return (bits / per).coerceAtLeast(1)
    }

    fun buildFilter(
        ids: List<ByteArray>, // 16-byte PacketId bytes
        maxBytes: Int,
        targetFpr: Double
    ): Params {
        val p = deriveP(targetFpr)
        val nCap = estimateMaxElementsForSize(maxBytes, p)
        var trimmedN = ids.size.coerceAtMost(nCap)

        var finalM = (trimmedN.toLong() shl p).coerceAtLeast(1L)
        var selected = ids.take(trimmedN)
        var mapped = selected.map { id ->
            val v = h64(id) % finalM
            if (v == 0L) 1L else v
        }.distinct().sorted()
        var encoded = encode(mapped, p)

        // If estimate was too optimistic, trim until it fits
        while (encoded.size > maxBytes && trimmedN > 0) {
            trimmedN = (trimmedN * 9) / 10 // drop 10%
            finalM = (trimmedN.toLong() shl p).coerceAtLeast(1L)
            selected = ids.take(trimmedN)
            mapped = selected.map { id ->
                val v = h64(id) % finalM
                if (v == 0L) 1L else v
            }.distinct().sorted()
            encoded = encode(mapped, p)
        }

        return Params(p = p, m = finalM, data = encoded)
    }

    fun decodeToSortedSet(p: Int, m: Long, data: ByteArray): LongArray {
        val values = ArrayList<Long>()
        val reader = BitReader(data)
        var acc = 0L
        val mask = (1L shl p) - 1L
        while (!reader.eof()) {
            // Read unary quotient (q ones terminated by zero)
            var q = 0L
            while (true) {
                val b = reader.readBit() ?: break
                if (b == 1) q++ else break
            }
            if (reader.lastWasEOF) break
            // Read remainder
            val r = reader.readBits(p) ?: break
            val x = (q shl p) + r + 1
            acc += x
            if (acc >= m) break // out of range safeguard
            values.add(acc)
        }
        return values.toLongArray()
    }

    fun contains(sortedValues: LongArray, candidate: Long): Boolean {
        var lo = 0
        var hi = sortedValues.size - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            val v = sortedValues[mid]
            if (v == candidate) return true
            if (v < candidate) lo = mid + 1 else hi = mid - 1
        }
        return false
    }

    internal fun h64(id16: ByteArray): Long {
        val md = MessageDigest.getInstance("SHA-256")
        md.update(id16)
        val d = md.digest()
        var x = 0L
        for (i in 0 until 8) {
            x = (x shl 8) or ((d[i].toLong() and 0xFF))
        }
        return x and 0x7fff_ffff_ffff_ffffL // positive
    }

    private fun encode(sorted: List<Long>, p: Int): ByteArray {
        val bw = BitWriter()
        var prev = 0L
        val mask = (1L shl p) - 1L
        for (v in sorted) {
            val delta = v - prev
            prev = v
            val x = delta
            val q = (x - 1) ushr p
            val r = (x - 1) and mask
            // unary q ones then a zero
            repeat(q.toInt()) { bw.writeBit(1) }
            bw.writeBit(0)
            // then P bits of r (MSB-first)
            bw.writeBits(r, p)
        }
        return bw.toByteArray()
    }

    // Simple MSB-first bit writer
    private class BitWriter {
        private val buf = ArrayList<Byte>()
        private var cur = 0
        private var nbits = 0
        fun writeBit(bit: Int) {
            cur = (cur shl 1) or (bit and 1)
            nbits++
            if (nbits == 8) {
                buf.add(cur.toByte())
                cur = 0; nbits = 0
            }
        }
        fun writeBits(value: Long, count: Int) {
            if (count <= 0) return
            for (i in count - 1 downTo 0) {
                val bit = ((value ushr i) and 1L).toInt()
                writeBit(bit)
            }
        }
        fun toByteArray(): ByteArray {
            if (nbits > 0) {
                val rem = cur shl (8 - nbits)
                buf.add(rem.toByte())
                cur = 0; nbits = 0
            }
            return buf.toByteArray()
        }
    }

    // Simple MSB-first bit reader
    private class BitReader(private val data: ByteArray) {
        private var i = 0
        private var nleft = 8
        private var cur = if (data.isNotEmpty()) (data[0].toInt() and 0xFF) else 0
        var lastWasEOF: Boolean = false
            private set
        fun eof() = i >= data.size
        fun readBit(): Int? {
            if (i >= data.size) { lastWasEOF = true; return null }
            val bit = (cur ushr 7) and 1
            cur = (cur shl 1) and 0xFF
            nleft--
            if (nleft == 0) {
                i++
                if (i < data.size) {
                    cur = data[i].toInt() and 0xFF
                    nleft = 8
                }
            }
            return bit
        }
        fun readBits(count: Int): Long? {
            var v = 0L
            for (k in 0 until count) {
                val b = readBit() ?: return null
                v = (v shl 1) or b.toLong()
            }
            return v
        }
    }
}

package com.bitchat.android.sync

import android.util.Log
import com.bitchat.android.mesh.BluetoothPacketBroadcaster
import com.bitchat.android.model.RequestSyncPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.protocol.SpecialRecipients
import kotlinx.coroutines.*
import java.util.concurrent.ConcurrentHashMap

/**
 * Gossip-based synchronization manager using on-demand GCS filters.
 * Tracks seen public packets (ANNOUNCE, broadcast MESSAGE) and periodically requests sync
 * from neighbors. Responds to REQUEST_SYNC by sending missing packets.
 */
class GossipSyncManager(
    private val myPeerID: String,
    private val scope: CoroutineScope,
    private val configProvider: ConfigProvider
) {
    interface Delegate {
        fun sendPacket(packet: BitchatPacket)
        fun sendPacketToPeer(peerID: String, packet: BitchatPacket)
        fun signPacketForBroadcast(packet: BitchatPacket): BitchatPacket
    }

    interface ConfigProvider {
        fun seenCapacity(): Int // max packets we sync per request (cap across types)
        fun gcsMaxBytes(): Int
        fun gcsTargetFpr(): Double // percent -> 0.0..1.0
    }

    companion object {
        private const val TAG = "GossipSyncManager"
    }

    var delegate: Delegate? = null

    // Defaults (configurable constants)
    private val defaultMaxBytes = SyncDefaults.DEFAULT_FILTER_BYTES
    private val defaultFpr = SyncDefaults.DEFAULT_FPR_PERCENT

    // Stored packets for sync:
    // - broadcast messages: keep up to seenCapacity() most recent, keyed by packetId
    private val messages = LinkedHashMap<String, BitchatPacket>()
    // - announcements: only keep latest per sender peerID
    private val latestAnnouncementByPeer = ConcurrentHashMap<String, Pair<String, BitchatPacket>>()

    private var periodicJob: Job? = null
    private var cleanupJob: Job? = null
    fun start() {
        periodicJob?.cancel()
        periodicJob = scope.launch(Dispatchers.IO) {
            while (isActive) {
                try {
                    delay(30_000)
                    sendRequestSync()
                } catch (e: CancellationException) { throw e }
                catch (e: Exception) { Log.e(TAG, "Periodic sync error: ${e.message}") }
            }
        }

        // Start periodic cleanup of stale announcements and messages
        cleanupJob?.cancel()
        cleanupJob = scope.launch(Dispatchers.IO) {
            while (isActive) {
                try {
                    delay(com.bitchat.android.util.AppConstants.Sync.CLEANUP_INTERVAL_MS)
                    pruneStaleAnnouncements()
                } catch (e: CancellationException) { throw e }
                catch (e: Exception) { Log.e(TAG, "Periodic cleanup error: ${e.message}") }
            }
        }
    }

    fun stop() {
        periodicJob?.cancel(); periodicJob = null
        cleanupJob?.cancel(); cleanupJob = null
    }

    @Synchronized
    fun clear() {
        synchronized(messages) {
            messages.clear()
        }
        latestAnnouncementByPeer.clear()
        Log.d(TAG, "Cleared all gossip sync messages and announcements")
    }

    fun scheduleInitialSync(delayMs: Long = 5_000L) {
        scope.launch(Dispatchers.IO) {
            delay(delayMs)
            sendRequestSync()
        }
    }

    fun scheduleInitialSyncToPeer(peerID: String, delayMs: Long = 5_000L) {
        scope.launch(Dispatchers.IO) {
            delay(delayMs)
            sendRequestSyncToPeer(peerID)
        }
    }

    fun onPublicPacketSeen(packet: BitchatPacket) {
        // Only ANNOUNCE or broadcast MESSAGE
        val mt = MessageType.fromValue(packet.type)
        val isBroadcastMessage = (mt == MessageType.MESSAGE && (packet.recipientID == null || packet.recipientID.contentEquals(SpecialRecipients.BROADCAST)))
        val isAnnouncement = (mt == MessageType.ANNOUNCE)
        if (!isBroadcastMessage && !isAnnouncement) return

        val idBytes = PacketIdUtil.computeIdBytes(packet)
        val id = idBytes.joinToString("") { b -> "%02x".format(b) }

        if (isBroadcastMessage) {
            synchronized(messages) {
                messages[id] = packet
                // Enforce capacity (remove oldest when exceeded)
                val cap = configProvider.seenCapacity().coerceAtLeast(1)
                while (messages.size > cap) {
                    val it = messages.entries.iterator()
                    if (it.hasNext()) { it.next(); it.remove() } else break
                }
            }
        } else if (isAnnouncement) {
            // Ignore stale announcements older than STALE_PEER_TIMEOUT
            val now = System.currentTimeMillis()
            val age = now - packet.timestamp.toLong()
            if (age > com.bitchat.android.util.AppConstants.Mesh.STALE_PEER_TIMEOUT_MS) {
                Log.d(TAG, "Ignoring stale ANNOUNCE (age=${age}ms > ${com.bitchat.android.util.AppConstants.Mesh.STALE_PEER_TIMEOUT_MS}ms)")
                return
            }
            // senderID is fixed-size 8 bytes; map to hex string for key
            val sender = packet.senderID.joinToString("") { b -> "%02x".format(b) }
            latestAnnouncementByPeer[sender] = id to packet
            // Enforce capacity (remove oldest when exceeded)
            val cap = configProvider.seenCapacity().coerceAtLeast(1)
            while (latestAnnouncementByPeer.size > cap) {
                val it = latestAnnouncementByPeer.entries.iterator()
                if (it.hasNext()) { it.next(); it.remove() } else break
            }
        }
    }

    private fun sendRequestSync() {
        val payload = buildGcsPayload()

        val packet = BitchatPacket(
            type = MessageType.REQUEST_SYNC.value,
            senderID = hexStringToByteArray(myPeerID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = com.bitchat.android.util.AppConstants.SYNC_TTL_HOPS // neighbors only
        )
        // Sign and broadcast
        val signed = delegate?.signPacketForBroadcast(packet) ?: packet
        delegate?.sendPacket(signed)
    }

    private fun sendRequestSyncToPeer(peerID: String) {
        val payload = buildGcsPayload()

        val packet = BitchatPacket(
            type = MessageType.REQUEST_SYNC.value,
            senderID = hexStringToByteArray(myPeerID),
            recipientID = hexStringToByteArray(peerID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = com.bitchat.android.util.AppConstants.SYNC_TTL_HOPS // neighbor only
        )
        Log.d(TAG, "Sending sync request to $peerID (${payload.size} bytes)")
        // Sign and send directly to peer
        val signed = delegate?.signPacketForBroadcast(packet) ?: packet
        delegate?.sendPacketToPeer(peerID, signed)
    }

    fun handleRequestSync(fromPeerID: String, request: RequestSyncPacket) {
        // Decode GCS into sorted set for membership checks
        val sorted = GCSFilter.decodeToSortedSet(request.p, request.m, request.data)
        fun mightContain(id: ByteArray): Boolean {
            val v = GCSFilter.h64(id) % request.m
            val nonZeroV = if (v == 0L) 1L else v
            return GCSFilter.contains(sorted, nonZeroV)
        }

        // 1) Announcements: send latest per peerID if remote doesn't have them
        for ((_, pair) in latestAnnouncementByPeer.entries) {
            val (id, pkt) = pair
            val idBytes = hexToBytes(id)
            if (!mightContain(idBytes)) {
                // Send original packet unchanged to requester only (keep local TTL)
                val toSend = pkt.copy(ttl = com.bitchat.android.util.AppConstants.SYNC_TTL_HOPS)
                delegate?.sendPacketToPeer(fromPeerID, toSend)
                Log.d(TAG, "Sent sync announce: Type ${toSend.type} from ${toSend.senderID.toHexString()} to $fromPeerID packet id ${idBytes.toHexString()}")
            }
        }

        // 2) Broadcast messages: send all they lack
        val toSendMsgs = synchronized(messages) { messages.values.toList() }
        for (pkt in toSendMsgs) {
            val idBytes = PacketIdUtil.computeIdBytes(pkt)
            if (!mightContain(idBytes)) {
                val toSend = pkt.copy(ttl = com.bitchat.android.util.AppConstants.SYNC_TTL_HOPS)
                delegate?.sendPacketToPeer(fromPeerID, toSend)
                Log.d(TAG, "Sent sync message: Type ${toSend.type} to $fromPeerID packet id ${idBytes.toHexString()}")
            }
        }
    }

    private fun hexStringToByteArray(hexString: String): ByteArray {
        val result = ByteArray(8) { 0 }
        var tempID = hexString
        var index = 0
        while (tempID.length >= 2 && index < 8) {
            val hexByte = tempID.substring(0, 2)
            val byte = hexByte.toIntOrNull(16)?.toByte()
            if (byte != null) result[index] = byte
            tempID = tempID.substring(2)
            index++
        }
        return result
    }

    private fun hexToBytes(hex: String): ByteArray {
        val clean = if (hex.length % 2 == 0) hex else "0$hex"
        val out = ByteArray(clean.length / 2)
        var i = 0
        while (i < clean.length) {
            out[i/2] = clean.substring(i, i+2).toInt(16).toByte()
            i += 2
        }
        return out
    }

    private fun buildGcsPayload(): ByteArray {
        // Collect candidates: latest announcement per peer + recent broadcast messages
        val list = ArrayList<BitchatPacket>()
        // announcements
        for ((_, pair) in latestAnnouncementByPeer) {
            list.add(pair.second)
        }
        // messages
        synchronized(messages) {
            list.addAll(messages.values)
        }
        // sort by timestamp desc, then take up to min(seenCapacity, fit capacity)
        list.sortByDescending { it.timestamp.toLong() }

        val maxBytes = try { configProvider.gcsMaxBytes() } catch (_: Exception) { defaultMaxBytes }
        val fpr = try { configProvider.gcsTargetFpr() } catch (_: Exception) { defaultFpr }
        val p = GCSFilter.deriveP(fpr)
        val nMax = GCSFilter.estimateMaxElementsForSize(maxBytes, p)
        val cap = configProvider.seenCapacity().coerceAtLeast(1)
        val takeN = minOf(nMax, cap, list.size)
        if (takeN <= 0) {
            val p0 = GCSFilter.deriveP(fpr)
            return RequestSyncPacket(p = p0, m = 1, data = ByteArray(0)).encode()
        }
        val ids = list.take(takeN).map { pkt -> PacketIdUtil.computeIdBytes(pkt) }
        val params = GCSFilter.buildFilter(ids, maxBytes, fpr)
        val mVal = if (params.m <= 0L) 1 else params.m
        return RequestSyncPacket(p = params.p, m = mVal, data = params.data).encode()
    }

    // Periodically remove stale announcements and all their messages
    private fun pruneStaleAnnouncements() {
        val now = System.currentTimeMillis()
        val stalePeers = mutableListOf<String>()

        // Identify stale announcements by age
        for ((peerID, pair) in latestAnnouncementByPeer.entries) {
            val pkt = pair.second
            val age = now - pkt.timestamp.toLong()
            if (age > com.bitchat.android.util.AppConstants.Mesh.STALE_PEER_TIMEOUT_MS) {
                stalePeers.add(peerID)
            }
        }

        if (stalePeers.isEmpty()) return

        // Remove announcements and their messages
        var totalPrunedMsgs = 0
        for (peerID in stalePeers) {
            // Count messages to be pruned for logging
            val toRemove = mutableListOf<String>()
            synchronized(messages) {
                for ((id, message) in messages) {
                    val sender = message.senderID.joinToString("") { b -> "%02x".format(b) }
                    if (sender == peerID) toRemove.add(id)
                }
            }
            totalPrunedMsgs += toRemove.size

            // Reuse existing removal which also clears announcement entry
            removeAnnouncementForPeer(peerID)
        }

        Log.d(TAG, "Pruned ${stalePeers.size} stale announcements and $totalPrunedMsgs messages")
    }

    // Explicitly remove stored announcement for a given peer (hex ID)
    fun removeAnnouncementForPeer(peerID: String) {
        val key = peerID.lowercase()
        if (latestAnnouncementByPeer.remove(key) != null) {
            Log.d(TAG, "Removed stored announcement for peer $peerID")
        }

        // Collect IDs to remove first to avoid modifying collection while iterating
        val idsToRemove = mutableListOf<String>()
        synchronized(messages) {
            for ((id, message) in messages) {
                val sender = message.senderID.joinToString("") { b -> "%02x".format(b) }
                if (sender == key) {
                    idsToRemove.add(id)
                }
            }
        }

        // Now remove the collected IDs
        synchronized(messages) {
            for (id in idsToRemove) {
                messages.remove(id)
            }
        }

        if (idsToRemove.isNotEmpty()) {
            Log.d(TAG, "Pruned ${idsToRemove.size} messages with senders without announcements")
        }
    }
}

package com.bitchat.android.sync

import com.bitchat.android.protocol.BitchatPacket
import java.security.MessageDigest

/**
 * Deterministic packet ID helper for sync purposes.
 * Uses SHA-256 over a canonical subset of packet fields:
 * [type | senderID | timestamp | payload] to generate a stable ID.
 * Returns a 16-byte (128-bit) truncated hash for compactness.
 */
object PacketIdUtil {
    fun computeIdBytes(packet: BitchatPacket): ByteArray {
        val md = MessageDigest.getInstance("SHA-256")
        md.update(packet.type.toByte())
        md.update(packet.senderID)
        // Timestamp as 8 bytes big-endian
        val ts = packet.timestamp.toLong()
        for (i in 7 downTo 0) {
            md.update(((ts ushr (i * 8)) and 0xFF).toByte())
        }
        md.update(packet.payload)
        val digest = md.digest()
        return digest.copyOf(16) // 128-bit ID
    }

    fun computeIdHex(packet: BitchatPacket): String {
        return computeIdBytes(packet).joinToString("") { b -> "%02x".format(b) }
    }
}

package com.bitchat.android.sync

object SyncDefaults {
    // Default values used when debug prefs are unavailable
    const val DEFAULT_FILTER_BYTES: Int = 256
    const val DEFAULT_FPR_PERCENT: Double = 1.0

    // Receiver-side hard cap to avoid DoS (also enforced in RequestSyncPacket)
    const val MAX_ACCEPT_FILTER_BYTES: Int = 1024
}

