/**
 * Unified settings toggle row with icon, title, subtitle, and switch
 * Apple-like design with proper spacing
 */
@Composable
private fun SettingsToggleRow(
    icon: ImageVector,
    title: String,
    subtitle: String,
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    enabled: Boolean = true,
    statusIndicator: (@Composable () -> Unit)? = null
) {
    val colorScheme = MaterialTheme.colorScheme
    val palette = LocalBitchatPalette.current
    val interactionSource = remember { MutableInteractionSource() }

    // Colours cross-fade so a row becoming available (Tor finishing bootstrap) eases in rather
    // than popping.
    val iconTint by animateColorAsState(
        targetValue = if (enabled) colorScheme.primary else palette.textTertiary,
        animationSpec = tween(BitchatMotion.STANDARD_MS, easing = FastOutSlowInEasing),
        label = "settingsRowIcon"
    )
    val titleColor by animateColorAsState(
        targetValue = if (enabled) colorScheme.onSurface else palette.textTertiary,
        animationSpec = tween(BitchatMotion.STANDARD_MS, easing = FastOutSlowInEasing),
        label = "settingsRowTitle"
    )
    val subtitleColor by animateColorAsState(
        targetValue = if (enabled) colorScheme.onSurfaceVariant else palette.textTertiary,
        animationSpec = tween(BitchatMotion.STANDARD_MS, easing = FastOutSlowInEasing),
        label = "settingsRowSubtitle"
    )

    Row(
        modifier = Modifier
            .fillMaxWidth()
            // The whole row toggles, not just the switch: a 14.dp-tall switch is a poor target
            // when there is a full-width row sitting right next to it.
            .clickable(
                interactionSource = interactionSource,
                indication = null,
                enabled = enabled
            ) { onCheckedChange(!checked) }
            .padding(horizontal = 16.dp, vertical = 13.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Icon(
            imageVector = icon,
            contentDescription = null,
            tint = iconTint,
            modifier = Modifier.size(22.dp)
        )

        Spacer(modifier = Modifier.width(16.dp))

        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(2.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = title,
                    fontFamily = BitchatFontFamily,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Medium,
                    color = titleColor
                )
                statusIndicator?.invoke()
            }
            Text(
                text = subtitle,
                fontFamily = BitchatFontFamily,
                fontSize = 12.sp,
                color = subtitleColor,
                lineHeight = 17.sp
            )
        }

        Spacer(modifier = Modifier.width(16.dp))

        Switch(
            checked = checked,
            onCheckedChange = { if (enabled) onCheckedChange(it) },
            enabled = enabled,
            interactionSource = interactionSource,
            colors = SwitchDefaults.colors(
                checkedThumbColor = Color.White,
                checkedTrackColor = colorScheme.primary,
                uncheckedThumbColor = Color.White,
                uncheckedTrackColor = colorScheme.surfaceVariant
            )
        )
    }
}

/**
 * Apple-like About/Settings Sheet with high-quality design
 * Professional UX optimized for checkout scenarios
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AboutSheet(
    isPresented: Boolean,
    onDismiss: () -> Unit,
    onShowDebug: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current

    // Get version name from package info
    val versionName = remember {
        try {
            context.packageManager.getPackageInfo(context.packageName, 0).versionName
        } catch (e: Exception) {
            "1.0.0" // fallback version
        }
    }

    val lazyListState = rememberLazyListState()
    val isScrolled by remember {
        derivedStateOf {
            lazyListState.firstVisibleItemIndex > 0 || lazyListState.firstVisibleItemScrollOffset > 0
        }
    }
    val topBarAlpha by animateFloatAsState(
        targetValue = if (isScrolled) 0.98f else 0f,
        animationSpec = tween(BitchatMotion.EMPHASIZED_MS, easing = FastOutSlowInEasing),
        label = "topBarAlpha"
    )

    val colorScheme = MaterialTheme.colorScheme
    val palette = LocalBitchatPalette.current
    var selectedTab by remember { mutableStateOf(AboutTab.Info) }
    val supportedLanguages = remember(context) {
        LanguagePreferenceManager.supportedLanguages(context)
    }
    var selectedLanguageTag by remember {
        mutableStateOf(LanguagePreferenceManager.currentLanguageTag())
    }
    var showLanguagePicker by remember { mutableStateOf(false) }

    if (isPresented) {
        BitchatBottomSheet(
            modifier = modifier,
            onDismissRequest = onDismiss,
        ) {
            Box(modifier = Modifier.fillMaxWidth()) {
                LazyColumn(
                    state = lazyListState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(top = 72.dp, bottom = 32.dp),
                    verticalArrangement = Arrangement.spacedBy(0.dp)
                ) {
                    // Header Section - App Identity
                    item(key = "hero") {
                        AboutHero(versionName = versionName ?: "")
                    }

                    item(key = "tabs") {
                        AboutTabBar(
                            selected = selectedTab,
                            onSelect = { selectedTab = it },
                            modifier = Modifier.padding(top = 24.dp)
                        )
                    }

                    if (selectedTab == AboutTab.Info) {
                        // What the app is, then how to drive it. Both are reference material a
                        // new user reads once, so they belong on the same tab.
                        item(key = "features") {
                            Column {
                                AboutSectionLabel(text = stringResource(R.string.about_section_about))
                                AboutFeatureCard()
                            }
                        }

                        item(key = "how_to_use") {
                            AboutHowToUseSection()
                        }
                    }

                    if (selectedTab == AboutTab.Settings) {
                    // Appearance Section
                    item(key = "appearance") {
                        Column {
                            AboutSectionLabel(text = stringResource(R.string.about_section_theme))
                            val themePref by com.bitchat.android.ui.theme.ThemePreferenceManager.themeFlow.collectAsState()
                            val chatUiMode by com.bitchat.android.ui.theme.ChatUiModeManager.modeFlow.collectAsState()
                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = AboutHorizontalPadding),
                                color = colorScheme.surface,
                                shape = AboutCardShape
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    verticalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        ThemeChip(
                                            label = stringResource(R.string.about_system),
                                            selected = themePref.isSystem,
                                            onClick = { com.bitchat.android.ui.theme.ThemePreferenceManager.set(context, com.bitchat.android.ui.theme.ThemePreference.System) },
                                            modifier = Modifier.weight(1f)
                                        )
                                        ThemeChip(
                                            label = stringResource(R.string.about_light),
                                            selected = themePref.isLight,
                                            onClick = { com.bitchat.android.ui.theme.ThemePreferenceManager.set(context, com.bitchat.android.ui.theme.ThemePreference.Light) },
                                            modifier = Modifier.weight(1f)
                                        )
                                        ThemeChip(
                                            label = stringResource(R.string.about_dark),
                                            selected = themePref.isDark,
                                            onClick = { com.bitchat.android.ui.theme.ThemePreferenceManager.set(context, com.bitchat.android.ui.theme.ThemePreference.Dark) },
                                            modifier = Modifier.weight(1f)
                                        )
                                    }
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        ThemeChip(
                                            label = stringResource(R.string.chat_ui_bubbles),
                                            selected = chatUiMode.isBubbles,
                                            onClick = { com.bitchat.android.ui.theme.ChatUiModeManager.set(context, com.bitchat.android.ui.theme.ChatUiMode.Bubbles) },
                                            modifier = Modifier.weight(1f)
                                        )
                                        ThemeChip(
                                            label = stringResource(R.string.chat_ui_matrix),
                                            selected = chatUiMode.isMatrix,
                                            onClick = { com.bitchat.android.ui.theme.ChatUiModeManager.set(context, com.bitchat.android.ui.theme.ChatUiMode.Matrix) },
                                            modifier = Modifier.weight(1f)
                                        )
                                    }
                                }
                            }
                        }
                    }

                    item(key = "language") {
                        val selectedLanguageName = supportedLanguages
                            .firstOrNull { it.languageTag == selectedLanguageTag }
                            ?.endonym
                            ?: stringResource(R.string.about_system_default)

                        Column {
                            AboutSectionLabel(text = stringResource(R.string.about_language))
                            BoxWithConstraints(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = AboutHorizontalPadding),
                            ) {
                                Surface(
                                    modifier = Modifier.fillMaxWidth(),
                                    color = colorScheme.surface,
                                    shape = AboutCardShape,
                                ) {
                                    LanguageSettingsRow(
                                        selectedLanguageName = selectedLanguageName,
                                        onClick = { showLanguagePicker = true },
                                    )
                                }
                                DropdownMenu(
                                    expanded = showLanguagePicker,
                                    onDismissRequest = { showLanguagePicker = false },
                                    modifier = Modifier.width(maxWidth),
                                ) {
                                    LanguageMenuItem(
                                        label = stringResource(R.string.about_system_default),
                                        selected = selectedLanguageTag.isEmpty(),
                                        onClick = {
                                            showLanguagePicker = false
                                            if (selectedLanguageTag.isNotEmpty()) {
                                                selectedLanguageTag = ""
                                                LanguagePreferenceManager.setLanguage("")
                                            }
                                        },
                                    )
                                    HorizontalDivider()
                                    supportedLanguages.forEach { language ->
                                        LanguageMenuItem(
                                            label = language.endonym,
                                            selected = selectedLanguageTag == language.languageTag,
                                            onClick = {
                                                showLanguagePicker = false
                                                if (language.languageTag != selectedLanguageTag) {
                                                    selectedLanguageTag = language.languageTag
                                                    LanguagePreferenceManager.setLanguage(language.languageTag)
                                                }
                                            },
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Settings Section - Unified Card with Toggles
                    item(key = "settings") {
                        LaunchedEffect(Unit) { PoWPreferenceManager.init(context) }
                        val powEnabled by PoWPreferenceManager.powEnabled.collectAsState()
                        val powDifficulty by PoWPreferenceManager.powDifficulty.collectAsState()
                        var backgroundEnabled by remember { mutableStateOf(com.bitchat.android.service.MeshServicePreferences.isBackgroundEnabled(true)) }
                        var liveVoiceEnabled by remember {
                            mutableStateOf(com.bitchat.android.features.voice.LiveVoicePreferences.isEnabled(context))
                        }
                        val torMode = remember { mutableStateOf(TorPreferenceManager.get(context)) }
                        val torProvider = remember { ArtiTorManager.getInstance() }
                        val torStatus by torProvider.statusFlow.collectAsState()
                        val torAvailable = remember { torProvider.isTorAvailable() }

                        Column {
                            AboutSectionLabel(text = stringResource(R.string.about_section_settings))
                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(horizontal = AboutHorizontalPadding),
                                color = colorScheme.surface,
                                shape = AboutCardShape
                            ) {
                                Column {
                                    // Background Mode Toggle
                                    SettingsToggleRow(
                                        icon = Icons.Filled.Bluetooth,
                                        title = stringResource(R.string.about_background_title),
                                        subtitle = stringResource(R.string.about_background_desc),
                                        checked = backgroundEnabled,
                                        onCheckedChange = { enabled ->
                                            backgroundEnabled = enabled
                                            com.bitchat.android.service.MeshServicePreferences.setBackgroundEnabled(enabled)
                                            if (!enabled) {
                                                com.bitchat.android.service.MeshForegroundService.stop(context)
                                            } else {
                                                com.bitchat.android.service.MeshForegroundService.start(context)
                                            }
                                        }
                                    )

                                    HorizontalDivider(
                                        modifier = Modifier.padding(start = 54.dp),
                                        thickness = 1.dp,
                                        color = colorScheme.outlineVariant
                                    )

                                    SettingsToggleRow(
                                        icon = Icons.Filled.Mic,
                                        title = "Live push-to-talk",
                                        subtitle = "Play voice bursts live on the mesh; voice notes are always sent on release",
                                        checked = liveVoiceEnabled,
                                        onCheckedChange = { enabled ->
                                            liveVoiceEnabled = enabled
                                            com.bitchat.android.features.voice.LiveVoicePreferences.setEnabled(context, enabled)
                                        }
                                    )

                                    HorizontalDivider(
                                        modifier = Modifier.padding(start = 54.dp),
                                        thickness = 1.dp,
                                        color = colorScheme.outlineVariant
                                    )

                                    // Proof of Work Toggle
                                    SettingsToggleRow(
                                        icon = Icons.Filled.Speed,
                                        title = stringResource(R.string.about_pow),
                                        subtitle = stringResource(R.string.about_pow_tip),
                                        checked = powEnabled,
                                        onCheckedChange = { PoWPreferenceManager.setPowEnabled(it) }
                                    )

                                    HorizontalDivider(
                                        modifier = Modifier.padding(start = 54.dp),
                                        thickness = 1.dp,
                                        color = colorScheme.outlineVariant
                                    )

                                    // Tor Toggle
                                    SettingsToggleRow(
                                        icon = Icons.Filled.Security,
                                        title = stringResource(R.string.about_tor_title),
                                        subtitle = stringResource(R.string.about_tor_route),
                                        checked = torMode.value == TorMode.ON,
                                        onCheckedChange = { enabled ->
                                            if (torAvailable) {
                                                torMode.value = if (enabled) TorMode.ON else TorMode.OFF
                                                TorPreferenceManager.set(context, torMode.value)
                                            }
                                        },
                                        enabled = torAvailable,
                                        statusIndicator = if (torMode.value == TorMode.ON) {
                                            {
                                                val statusColor = when {
                                                    torStatus.running && torStatus.bootstrapPercent >= 100 -> colorScheme.primary
                                                    torStatus.running -> palette.accentOrange
                                                    else -> colorScheme.error
                                                }
                                                Surface(
                                                    color = statusColor,
                                                    shape = CircleShape,
                                                    modifier = Modifier.size(8.dp)
                                                ) {}
                                            }
                                        } else null
                                    )

                                    HorizontalDivider(
                                        modifier = Modifier.padding(start = 56.dp),
                                        color = colorScheme.outline.copy(alpha = 0.12f)
                                    )

                                    // === Prepare App for Sharing Section ===
                                    val apkViewModel: ApkDownloadViewModel = viewModel()
                                    val apkUiState by apkViewModel.state.collectAsStateWithLifecycle()
                                    val apkStatus = apkUiState.apkStatus
                                    val downloadProgress = apkUiState.downloadProgress

                                    // Handle one-shot effects (navigation, toasts, share intents)
                                    LaunchedEffect(Unit) {
                                        apkViewModel.onEvent(ApkUiEvent.CheckStatus)
                                        apkViewModel.effect.collect { effect ->
                                            when (effect) {
                                                is ApkUiEffect.NavigateToHotspot -> {
                                                    val intent = Intent(context, HotspotActivity::class.java)
                                                    intent.putExtra(HotspotActivity.EXTRA_APK_PATH, effect.apkPath)
                                                    context.startActivity(intent)
                                                }
                                                is ApkUiEffect.ShareApk -> {
                                                    val intent = Intent(Intent.ACTION_SEND).apply {
                                                        type = "application/vnd.android.package-archive"
                                                        putExtra(Intent.EXTRA_STREAM, effect.apkUri)
                                                        clipData = android.content.ClipData.newRawUri("", effect.apkUri)
                                                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                                    }
                                                    val chooser = Intent.createChooser(intent, effect.chooserTitle).apply {
                                                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                                    }
                                                    context.startActivity(chooser)
                                                }
                                                is ApkUiEffect.ShowToast -> {
                                                    Toast.makeText(context, effect.message, Toast.LENGTH_SHORT).show()
                                                }
                                            }
                                        }
                                    }

                                    // Prepare App for Sharing Row
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable(enabled = apkStatus !is ApkPreparationStatus.Downloading) {
                                                apkViewModel.onEvent(ApkUiEvent.PrepareRowClicked)
                                            }
                                            .padding(horizontal = 16.dp, vertical = 14.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = if (apkStatus is ApkPreparationStatus.Ready) {
                                                Icons.Default.Share
                                            } else {
                                                Icons.Default.CloudDownload
                                            },
                                            contentDescription = null,
                                            tint = colorScheme.primary,
                                            modifier = Modifier.size(22.dp)
                                        )

                                        Spacer(modifier = Modifier.width(14.dp))

                                        Column(
                                            modifier = Modifier.weight(1f),
                                            verticalArrangement = Arrangement.spacedBy(2.dp)
                                        ) {
                                            Text(
                                                text = if (apkStatus is ApkPreparationStatus.Ready) {
                                                    stringResource(R.string.prepare_apk_ready_title)
                                                } else {
                                                    stringResource(R.string.prepare_apk_title)
                                                },
                                                style = MaterialTheme.typography.bodyMedium,
                                                fontWeight = FontWeight.Medium,
                                                color = colorScheme.onSurface
                                            )
                                            Text(
                                                text = when (val status = apkStatus) {
                                                    is ApkPreparationStatus.Loading -> stringResource(R.string.checking)
                                                    is ApkPreparationStatus.NotDownloaded -> stringResource(R.string.prepare_apk_status_not_downloaded)
                                                    is ApkPreparationStatus.Ready -> {
                                                        val source = when {
                                                            status.source == UniversalApkManager.ApkSource.GITHUB ->
                                                                stringResource(R.string.prepare_apk_source_github)
                                                            status.variant == ShareableApkVariant.ARM64 ->
                                                                stringResource(R.string.prepare_apk_source_installed_arm64)
                                                            else ->
                                                                stringResource(R.string.prepare_apk_source_installed)
                                                        }
                                                        stringResource(R.string.prepare_apk_status_ready) +
                                                            " • ${status.version} • ${status.sizeMB} MB\n$source"
                                                    }
                                                    is ApkPreparationStatus.UpdateAvailable -> stringResource(R.string.prepare_apk_status_update_available) + " (${status.newVersion})"
                                                    is ApkPreparationStatus.Downloading -> stringResource(R.string.prepare_apk_status_downloading, downloadProgress)
                                                    is ApkPreparationStatus.Resumable -> "Tap to resume • ${status.progressPercent}% downloaded"
                                                    is ApkPreparationStatus.Error -> status.message
                                                },
                                                style = MaterialTheme.typography.bodySmall,
                                                color = when (apkStatus) {
                                                    is ApkPreparationStatus.Error -> colorScheme.error
                                                    is ApkPreparationStatus.Resumable -> colorScheme.primary
                                                    is ApkPreparationStatus.UpdateAvailable -> colorScheme.primary
                                                    else -> colorScheme.onSurface.copy(alpha = 0.6f)
                                                },
                                                lineHeight = 16.sp
                                            )
                                        }

                                        // Action buttons
                                        when (apkStatus) {
                                            is ApkPreparationStatus.Downloading -> {
                                                CircularProgressIndicator(
                                                    modifier = Modifier.size(20.dp),
                                                    strokeWidth = 2.dp
                                                )
                                            }
                                            is ApkPreparationStatus.Ready -> {
                                                if (apkStatus.variant == ShareableApkVariant.ARM64) {
                                                    TextButton(
                                                        onClick = {
                                                            apkViewModel.onEvent(
                                                                ApkUiEvent.DownloadUniversalClicked
                                                            )
                                                        }
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.CloudDownload,
                                                            contentDescription = null,
                                                            modifier = Modifier.size(18.dp)
                                                        )
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        Text(
                                                            stringResource(
                                                                R.string.prepare_apk_get_universal
                                                            )
                                                        )
                                                    }
                                                } else if (apkStatus.source == UniversalApkManager.ApkSource.GITHUB) {
                                                    androidx.compose.material3.IconButton(
                                                        onClick = { apkViewModel.onEvent(ApkUiEvent.DeleteClicked) },
                                                        modifier = Modifier.size(48.dp)
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.Delete,
                                                            contentDescription = stringResource(
                                                                R.string.prepare_apk_delete_confirm
                                                            ),
                                                            tint = colorScheme.error,
                                                            modifier = Modifier.size(20.dp)
                                                        )
                                                    }
                                                }
                                            }
                                            is ApkPreparationStatus.UpdateAvailable -> {
                                                androidx.compose.material3.IconButton(
                                                    onClick = { apkViewModel.onEvent(ApkUiEvent.DeleteClicked) },
                                                    modifier = Modifier.size(48.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.Delete,
                                                        contentDescription = stringResource(
                                                            R.string.prepare_apk_delete_confirm
                                                        ),
                                                        tint = colorScheme.error,
                                                        modifier = Modifier.size(20.dp)
                                                    )
                                                }
                                            }
                                            else -> {}
                                        }
                                    }

                                    // Prepare Dialog
                                    if (apkUiState.showPrepareDialog) {
                                        val status = apkStatus
                                        val sizeMB: Int? = when (status) {
                                            is ApkPreparationStatus.NotDownloaded -> status.sizeMB
                                            is ApkPreparationStatus.UpdateAvailable -> status.newSizeMB
                                            else -> null
                                        }
                                        AlertDialog(
                                            onDismissRequest = { apkViewModel.onEvent(ApkUiEvent.DismissPrepareDialog) },
                                            title = {
                                                Text(
                                                    text = if (status is ApkPreparationStatus.UpdateAvailable) {
                                                        stringResource(R.string.prepare_apk_update_dialog_title)
                                                    } else {
                                                        stringResource(R.string.prepare_apk_dialog_title)
                                                    },
                                                    style = MaterialTheme.typography.titleLarge
                                                )
                                            },
                                            text = {
                                                Text(
                                                    text = if (status is ApkPreparationStatus.UpdateAvailable) {
                                                        stringResource(R.string.prepare_apk_update_dialog_message, status.newVersion, status.currentVersion)
                                                    } else if (sizeMB != null) {
                                                        stringResource(R.string.prepare_apk_dialog_message, sizeMB)
                                                    } else {
                                                        stringResource(R.string.prepare_apk_dialog_message_unknown_size)
                                                    },
                                                    style = MaterialTheme.typography.bodyMedium
                                                )
                                            },
                                            confirmButton = {
                                                Button(onClick = {
                                                    apkViewModel.onEvent(ApkUiEvent.ConfirmDownload)
                                                }) {
                                                    Text(stringResource(R.string.prepare_apk_dialog_confirm))
                                                }
                                            },
                                            dismissButton = {
                                                TextButton(onClick = { apkViewModel.onEvent(ApkUiEvent.DismissPrepareDialog) }) {
                                                    Text(stringResource(R.string.cancel))
                                                }
                                            },
                                            containerColor = colorScheme.surface
                                        )
                                    }

                                    // Delete Dialog
                                    if (apkUiState.showDeleteDialog) {
                                        val sizeMB = (apkStatus as? ApkPreparationStatus.Ready)?.sizeMB ?: 0
                                        AlertDialog(
                                            onDismissRequest = { apkViewModel.onEvent(ApkUiEvent.DismissDeleteDialog) },
                                            title = {
                                                Text(
                                                    text = stringResource(R.string.prepare_apk_delete_confirm),
                                                    style = MaterialTheme.typography.titleLarge
                                                )
                                            },
                                            text = {
                                                Text(
                                                    text = stringResource(R.string.prepare_apk_delete_message, sizeMB),
                                                    style = MaterialTheme.typography.bodyMedium
                                                )
                                            },
                                            confirmButton = {
                                                Button(
                                                    onClick = {
                                                        apkViewModel.onEvent(ApkUiEvent.ConfirmDelete)
                                                    },
                                                    colors = androidx.compose.material3.ButtonDefaults.buttonColors(
                                                        containerColor = colorScheme.error
                                                    )
                                                ) {
                                                    Text("Delete")
                                                }
                                            },
                                            dismissButton = {
                                                TextButton(onClick = { apkViewModel.onEvent(ApkUiEvent.DismissDeleteDialog) }) {
                                                    Text(stringResource(R.string.cancel))
                                                }
                                            },
                                            containerColor = colorScheme.surface
                                        )
                                    }

                                    // Show sharing rows only when APK is ready
                                    val canShareAPK = apkStatus is ApkPreparationStatus.Ready ||
                                            apkStatus is ApkPreparationStatus.UpdateAvailable

                                    AnimatedVisibility(
                                        visible = canShareAPK,
                                        enter = fadeIn() + expandVertically(),
                                        exit = fadeOut() + shrinkVertically()
                                    ) {
                                        Column {
                                            HorizontalDivider(
                                                modifier = Modifier.padding(start = 56.dp),
                                                color = colorScheme.outline.copy(alpha = 0.12f)
                                            )

                                            // === Share via Hotspot Row ===
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        apkViewModel.onEvent(ApkUiEvent.HotspotShareClicked)
                                                    }
                                                    .padding(horizontal = 16.dp, vertical = 14.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                        Icon(
                                            imageVector = Icons.Default.Wifi,
                                            contentDescription = null,
                                            tint = colorScheme.primary,
                                            modifier = Modifier.size(22.dp)
                                        )

                                        Spacer(modifier = Modifier.width(14.dp))

                                        Column(
                                            modifier = Modifier.weight(1f),
                                            verticalArrangement = Arrangement.spacedBy(2.dp)
                                        ) {
                                            Text(
                                                text = stringResource(R.string.hotspot_share_via),
                                                style = MaterialTheme.typography.bodyMedium,
                                                fontWeight = FontWeight.Medium,
                                                color = colorScheme.onSurface
                                            )
                                            Text(
                                                text = stringResource(R.string.hotspot_share_via_subtitle),
                                                style = MaterialTheme.typography.bodySmall,
                                                color = colorScheme.onSurface.copy(alpha = 0.6f),
                                                lineHeight = 16.sp
                                            )
                                        }

                                        Icon(
                                            imageVector = Icons.Default.ChevronRight,
                                            contentDescription = null,
                                            tint = colorScheme.onSurface.copy(alpha = 0.4f),
                                            modifier = Modifier.size(20.dp)
                                        )
                                            }

                                            HorizontalDivider(
                                        modifier = Modifier.padding(start = 56.dp),
                                        color = colorScheme.outline.copy(alpha = 0.12f)
                                    )

                                    // === Share via Bluetooth/Email Row (Fallback) ===
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable { apkViewModel.onEvent(ApkUiEvent.AppShareClicked) }
                                            .padding(horizontal = 16.dp, vertical = 14.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Bluetooth,
                                            contentDescription = null,
                                            tint = colorScheme.primary,
                                            modifier = Modifier.size(22.dp)
                                        )

                                        Spacer(modifier = Modifier.width(14.dp))

                                        Column(
                                            modifier = Modifier.weight(1f),
                                            verticalArrangement = Arrangement.spacedBy(2.dp)
                                        ) {
                                            Text(
                                                text = stringResource(R.string.hotspot_share_other),
                                                style = MaterialTheme.typography.bodyMedium,
                                                fontWeight = FontWeight.Medium,
                                                color = colorScheme.onSurface
                                            )
                                            Text(
                                                text = stringResource(R.string.hotspot_share_other_subtitle),
                                                style = MaterialTheme.typography.bodySmall,
                                                color = colorScheme.onSurface.copy(alpha = 0.6f),
                                                lineHeight = 16.sp
                                            )
                                        }

                                        Icon(
                                            imageVector = Icons.Default.ChevronRight,
                                            contentDescription = null,
                                            tint = colorScheme.onSurface.copy(alpha = 0.4f),
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }

                                            // APK Share Dialog
                                            ApkShareExplanationDialog(
                                                show = apkUiState.showShareApkDialog,
                                                onConfirm = {
                                                    apkViewModel.onEvent(ApkUiEvent.ConfirmAppShare)
                                                },
                                                onDismiss = { apkViewModel.onEvent(ApkUiEvent.DismissShareDialog) }
                                            )
                                        }
                                    }

                                }
                            }

                            // Tor unavailable hint
                            if (!torAvailable) {
                                Text(
                                    text = stringResource(R.string.tor_not_available_in_this_build),
                                    fontSize = 12.sp,
                                    fontFamily = BitchatFontFamily,
                                    color = palette.textTertiary,
                                    modifier = Modifier.padding(
                                        start = AboutHorizontalPadding + 16.dp,
                                        top = 8.dp
                                    )
                                )
                            }
                        }
                    }

                    // PoW Difficulty Slider (when enabled)
                    item(key = "pow_slider") {
                        val powEnabled by PoWPreferenceManager.powEnabled.collectAsState()
                        val powDifficulty by PoWPreferenceManager.powDifficulty.collectAsState()

                        if (powEnabled) {
                            Column(modifier = Modifier.padding(top = 12.dp)) {
                                Surface(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = AboutHorizontalPadding),
                                    color = colorScheme.surface,
                                    shape = AboutCardShape
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = stringResource(R.string.about_difficulty),
                                                fontFamily = BitchatFontFamily,
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Medium,
                                                color = colorScheme.onSurface
                                            )
                                            AnimatedCountLabel(
                                                count = powDifficulty,
                                                text = stringResource(
                                                    R.string.about_difficulty_value,
                                                    powDifficulty,
                                                    NostrProofOfWork.estimateMiningTime(powDifficulty)
                                                ),
                                                fontFamily = BitchatFontFamily,
                                                fontSize = 12.sp,
                                                color = colorScheme.onSurfaceVariant
                                            )
                                        }

                                        Slider(
                                            value = powDifficulty.toFloat(),
                                            onValueChange = { PoWPreferenceManager.setPowDifficulty(it.toInt()) },
                                            valueRange = 0f..32f,
                                            steps = 31,
                                            colors = SliderDefaults.colors(
                                                thumbColor = colorScheme.primary,
                                                activeTrackColor = colorScheme.primary,
                                                inactiveTrackColor = colorScheme.surfaceVariant
                                            )
                                        )

                                        AnimatedCountLabel(
                                            count = powDifficulty,
                                            text = when {
                                                powDifficulty == 0 -> stringResource(R.string.about_pow_desc_none)
                                                powDifficulty <= 8 -> stringResource(R.string.about_pow_desc_very_low)
                                                powDifficulty <= 12 -> stringResource(R.string.about_pow_desc_low)
                                                powDifficulty <= 16 -> stringResource(R.string.about_pow_desc_medium)
                                                powDifficulty <= 20 -> stringResource(R.string.about_pow_desc_high)
                                                powDifficulty <= 24 -> stringResource(R.string.about_pow_desc_very_high)
                                                else -> stringResource(R.string.about_pow_desc_extreme)
                                            },
                                            fontSize = 12.sp,
                                            fontFamily = BitchatFontFamily,
                                            color = palette.textTertiary
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Tor Status (when enabled)
                    item(key = "tor_status") {
                        val torMode = remember { mutableStateOf(TorPreferenceManager.get(context)) }
                        val torProvider = remember { ArtiTorManager.getInstance() }
                        val torStatus by torProvider.statusFlow.collectAsState()

                        if (torMode.value == TorMode.ON) {
                            Column(modifier = Modifier.padding(top = 12.dp)) {
                                Surface(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = AboutHorizontalPadding),
                                    color = colorScheme.surface,
                                    shape = AboutCardShape
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            val statusColor = when {
                                                torStatus.running && torStatus.bootstrapPercent >= 100 -> colorScheme.primary
                                                torStatus.running -> palette.accentOrange
                                                else -> colorScheme.error
                                            }
                                            Surface(color = statusColor, shape = CircleShape, modifier = Modifier.size(10.dp)) {}
                                            Text(
                                                text = if (torStatus.running) {
                                                    stringResource(R.string.about_tor_connected, torStatus.bootstrapPercent)
                                                } else {
                                                    stringResource(R.string.about_tor_disconnected)
                                                },
                                                fontFamily = BitchatFontFamily,
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Medium,
                                                color = colorScheme.onSurface
                                            )
                                        }
                                        if (torStatus.lastLogLine.isNotEmpty()) {
                                            Text(
                                                text = torStatus.lastLogLine.take(120),
                                                fontSize = 11.sp,
                                                fontFamily = BitchatFontFamily,
                                                color = palette.textTertiary,
                                                maxLines = 2
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }

                    } // end Settings tab

                    // Footer
                    item(key = "footer") {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(
                                    start = AboutHorizontalPadding,
                                    end = AboutHorizontalPadding,
                                    top = 24.dp
                                ),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            if (selectedTab == AboutTab.Settings && onShowDebug != null) {
                                TextButton(onClick = onShowDebug) {
                                    Text(
                                        text = stringResource(R.string.about_debug_settings),
                                        fontSize = 13.sp,
                                        fontFamily = BitchatFontFamily,
                                        color = colorScheme.primary
                                    )
                                }
                            }
                            Text(
                                text = stringResource(R.string.about_footer),
                                fontSize = 11.sp,
                                fontFamily = BitchatFontFamily,
                                color = palette.textTertiary
                            )
                            Spacer(modifier = Modifier.height(20.dp))
                        }
                    }
                }

                // TopBar
                Box(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .fillMaxWidth()
                        .height(64.dp)
                        .background(colorScheme.background.copy(alpha = topBarAlpha))
                ) {
                    val dismiss = LocalSheetDismiss.current
                    CloseButton(
                        onClick = { dismiss?.invoke() ?: onDismiss() },
                        modifier = modifier
                            .align(Alignment.CenterEnd)
                            .padding(horizontal = 16.dp),
                    )
                }
            }
        }
    }
}

/**
 * Password prompt dialog for password-protected channels
 * Kept as dialog since it requires user input
 */
@Composable
fun PasswordPromptDialog(
    show: Boolean,
    channelName: String?,
    passwordInput: String,
    onPasswordChange: (String) -> Unit,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit
) {
    if (show && channelName != null) {
        val colorScheme = MaterialTheme.colorScheme

        AlertDialog(
            onDismissRequest = onDismiss,
            title = {
                Text(
                    text = stringResource(R.string.pwd_prompt_title),
                    style = MaterialTheme.typography.titleMedium,
                    color = colorScheme.onSurface
                )
            },
            text = {
                Column {
                    Text(
                        text = stringResource(R.string.pwd_prompt_message, channelName ?: ""),
                        style = MaterialTheme.typography.bodyMedium,
                        color = colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(8.dp))

                    OutlinedTextField(
                        value = passwordInput,
                        onValueChange = onPasswordChange,
                        label = { Text(stringResource(R.string.pwd_label), style = MaterialTheme.typography.bodyMedium) },
                        textStyle = MaterialTheme.typography.bodyMedium.copy(
                            fontFamily = BitchatFontFamily
                        ),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = colorScheme.primary,
                            unfocusedBorderColor = colorScheme.outline
                        )
                    )
                }
            },
            confirmButton = {
                TextButton(onClick = onConfirm) {
                    Text(
                        text = stringResource(R.string.join),
                        style = MaterialTheme.typography.bodyMedium,
                        color = colorScheme.primary
                    )
                }
            },
            dismissButton = {
                TextButton(onClick = onDismiss) {
                    Text(
                        text = stringResource(R.string.cancel),
                        style = MaterialTheme.typography.bodyMedium,
                        color = colorScheme.onSurface
                    )
                }
            },
            containerColor = colorScheme.surface,
            tonalElevation = 8.dp
        )
    }
}


/**
 * Dialog explaining APK sharing feature before sharing
 */
@Composable
private fun ApkShareExplanationDialog(
    show: Boolean,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit
) {
    if (show) {
        val colorScheme = MaterialTheme.colorScheme

        AlertDialog(
            onDismissRequest = onDismiss,
            icon = {
                Icon(
                    imageVector = Icons.Default.Share,
                    contentDescription = null,
                    tint = colorScheme.primary,
                    modifier = Modifier.size(32.dp)
                )
            },
            title = {
                Text(
                    text = stringResource(R.string.share_apk_title),
                    style = MaterialTheme.typography.titleLarge,
                    color = colorScheme.onSurface
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text(
                        text = stringResource(R.string.share_apk_explanation),
                        style = MaterialTheme.typography.bodyMedium,
                        color = colorScheme.onSurface
                    )

                    // Info box with receiver instructions
                    Surface(
                        color = colorScheme.primaryContainer.copy(alpha = 0.3f),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Row(
                            modifier = Modifier.padding(12.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.Top
                        ) {
                            Icon(
                                imageVector = Icons.Outlined.Info,
                                contentDescription = null,
                                tint = colorScheme.primary,
                                modifier = Modifier.size(20.dp)
                            )
                            Text(
                                text = stringResource(R.string.share_apk_receiver_instructions),
                                style = MaterialTheme.typography.bodySmall,
                                color = colorScheme.onSurface.copy(alpha = 0.8f),
                                lineHeight = 18.sp
                            )
                        }
                    }
                }
            },
            confirmButton = {
                Button(onClick = onConfirm) {
                    Text(
                        text = stringResource(R.string.share_apk_confirm),
                        style = MaterialTheme.typography.bodyMedium
                    )
                }
            },
            dismissButton = {
                TextButton(onClick = onDismiss) {
                    Text(
                        text = stringResource(R.string.cancel),
                        style = MaterialTheme.typography.bodyMedium,
                        color = colorScheme.onSurface
                    )
                }
            },
            containerColor = colorScheme.surface,
            tonalElevation = 8.dp
        )
    }
}

package com.bitchat.android.ui

import androidx.compose.animation.BoundsTransform
import androidx.compose.animation.ExperimentalSharedTransitionApi
import androidx.compose.animation.animateBounds
import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.FiniteAnimationSpec
import androidx.compose.animation.core.Spring
import androidx.compose.animation.core.VisibilityThreshold
import androidx.compose.animation.core.spring
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.key
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.layout.LookaheadScope

/**
 * Motion for a row moving to a new position, or resizing in place.
 *
 * People lists reorder themselves constantly and without user input — someone sends a DM and jumps
 * to the top, a peer drops off the mesh, a favourite comes online. Rows teleporting between
 * positions makes the list feel unreliable and costs the reader their place in it.
 */
@OptIn(ExperimentalSharedTransitionApi::class)
private val RowBoundsTransform = BoundsTransform { _, _ ->
    spring(
        dampingRatio = Spring.DampingRatioNoBouncy,
        stiffness = Spring.StiffnessMediumLow,
        visibilityThreshold = Rect.VisibilityThreshold
    )
}

/** Entry fade for a row that was not previously in the list. */
private val RowEnterSpec: FiniteAnimationSpec<Float> =
    spring(dampingRatio = Spring.DampingRatioNoBouncy, stiffness = 900f)

/**
 * A vertical list whose rows animate when they are added, removed, or reordered.
 *
 * Deliberately not a `LazyColumn`: both people lists live *inside* an outer `LazyColumn` item, where
 * nesting another lazy list is not possible. [LookaheadScope] plus [Modifier.animateBounds] gives
 * the same reorder-and-resize animation that `LazyItemScope.animateItem` provides, without the list
 * needing to be lazy. These lists are bounded (and the geohash one is explicitly capped), so
 * nothing is lost by composing every row.
 *
 * Rows are keyed so identity survives reordering. Without stable keys a row that moved would look
 * like a different row appearing, and would fade instead of sliding.
 */
@OptIn(ExperimentalSharedTransitionApi::class)
@Composable
fun <T> AnimatedRowColumn(
    items: List<T>,
    key: (T) -> Any,
    modifier: Modifier = Modifier,
    row: @Composable (index: Int, item: T) -> Unit
) {
    LookaheadScope {
        Column(modifier = modifier) {
            items.forEachIndexed { index, item ->
                key(key(item)) {
                    // Fades the row in on the composition it first appears, then never again —
                    // reordering an existing row must slide, not blink.
                    val enter = remember { Animatable(0f) }
                    LaunchedEffect(Unit) { enter.animateTo(1f, RowEnterSpec) }

                    Box(
                        modifier = Modifier
                            .animateBounds(
                                lookaheadScope = this@LookaheadScope,
                                boundsTransform = RowBoundsTransform
                            )
                            .graphicsLayer { alpha = enter.value }
                    ) {
                        row(index, item)
                    }
                }
            }
        }
    }
}

package com.bitchat.android.ui

import android.app.Application
import android.util.Log
import androidx.core.content.FileProvider
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.bitchat.android.R
import com.bitchat.android.util.ApkDownloader
import com.bitchat.android.util.ShareableApkVariant
import com.bitchat.android.util.UniversalApkManager
import com.bitchat.android.util.WorkManagerApkDownloader
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.receiveAsFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

// --- State ---

sealed class ApkPreparationStatus {
    object Loading : ApkPreparationStatus()
    data class NotDownloaded(val sizeMB: Int?) : ApkPreparationStatus()
    data class Ready(
        val version: String,
        val sizeMB: Int,
        val source: UniversalApkManager.ApkSource,
        val variant: ShareableApkVariant
    ) : ApkPreparationStatus()
    data class UpdateAvailable(
        val currentVersion: String,
        val newVersion: String,
        val newSizeMB: Int
    ) : ApkPreparationStatus()
    object Downloading : ApkPreparationStatus()
    data class Resumable(val progressPercent: Int, val message: String) : ApkPreparationStatus()
    data class Error(val message: String) : ApkPreparationStatus()
}

data class ApkUiState(
    val apkStatus: ApkPreparationStatus = ApkPreparationStatus.Loading,
    val downloadProgress: Int = 0,
    val showPrepareDialog: Boolean = false,
    val showDeleteDialog: Boolean = false,
    val showShareApkDialog: Boolean = false
)

// --- Events (UI → ViewModel) ---

sealed class ApkUiEvent {
    object CheckStatus : ApkUiEvent()
    object PrepareRowClicked : ApkUiEvent()
    object DownloadUniversalClicked : ApkUiEvent()
    object ConfirmDownload : ApkUiEvent()
    object DismissPrepareDialog : ApkUiEvent()
    object DeleteClicked : ApkUiEvent()
    object ConfirmDelete : ApkUiEvent()
    object DismissDeleteDialog : ApkUiEvent()
    object HotspotShareClicked : ApkUiEvent()
    object AppShareClicked : ApkUiEvent()
    object ConfirmAppShare : ApkUiEvent()
    object DismissShareDialog : ApkUiEvent()
    object CancelDownload : ApkUiEvent()
}

// --- Effects (ViewModel → UI, one-shot) ---

sealed class ApkUiEffect {
    data class NavigateToHotspot(val apkPath: String) : ApkUiEffect()
    data class ShareApk(val apkUri: android.net.Uri, val chooserTitle: String) : ApkUiEffect()
    data class ShowToast(val message: String) : ApkUiEffect()
}

/**
 * ViewModel for APK download/status/share logic following MVI pattern.
 * UI sends [ApkUiEvent], observes [ApkUiState], and collects [ApkUiEffect].
 */
class ApkDownloadViewModel(application: Application) : AndroidViewModel(application) {

    companion object {
        private const val TAG = "ApkDownloadVM"
    }

    private val apkManager = UniversalApkManager(application)
    private val downloader: ApkDownloader = WorkManagerApkDownloader(application)

    private val _state = MutableStateFlow(ApkUiState())
    val state: StateFlow<ApkUiState> = _state.asStateFlow()

    private val _effect = Channel<ApkUiEffect>(Channel.BUFFERED)
    val effect = _effect.receiveAsFlow()

    init {
        observeDownloader()
    }

    fun onEvent(event: ApkUiEvent) {
        when (event) {
            is ApkUiEvent.CheckStatus -> checkStatus()
            is ApkUiEvent.PrepareRowClicked -> onPrepareRowClicked()
            is ApkUiEvent.DownloadUniversalClicked -> onDownloadUniversalClicked()
            is ApkUiEvent.ConfirmDownload -> onConfirmDownload()
            is ApkUiEvent.DismissPrepareDialog -> _state.update { it.copy(showPrepareDialog = false) }
            is ApkUiEvent.DeleteClicked -> _state.update { it.copy(showDeleteDialog = true) }
            is ApkUiEvent.ConfirmDelete -> onConfirmDelete()
            is ApkUiEvent.DismissDeleteDialog -> _state.update { it.copy(showDeleteDialog = false) }
            is ApkUiEvent.HotspotShareClicked -> onHotspotShareClicked()
            is ApkUiEvent.AppShareClicked -> _state.update { it.copy(showShareApkDialog = true) }
            is ApkUiEvent.ConfirmAppShare -> onConfirmAppShare()
            is ApkUiEvent.DismissShareDialog -> _state.update { it.copy(showShareApkDialog = false) }
            is ApkUiEvent.CancelDownload -> onCancelDownload()
        }
    }

    private fun onPrepareRowClicked() {
        when (_state.value.apkStatus) {
            is ApkPreparationStatus.NotDownloaded,
            is ApkPreparationStatus.UpdateAvailable,
            is ApkPreparationStatus.Error -> {
                _state.update { it.copy(showPrepareDialog = true) }
            }
            is ApkPreparationStatus.Resumable -> {
                startDownload()
            }
            else -> {}
        }
    }

    private fun onConfirmDownload() {
        _state.update { it.copy(showPrepareDialog = false) }
        startDownload()
    }

    private fun onDownloadUniversalClicked() {
        val status = _state.value.apkStatus
        if (status is ApkPreparationStatus.Ready &&
            status.variant == ShareableApkVariant.ARM64
        ) {
            _state.update { it.copy(showPrepareDialog = true) }
        }
    }

    private fun onConfirmDelete() {
        _state.update { it.copy(showDeleteDialog = false) }
        downloader.cancelDownload()
        apkManager.deleteCachedApk()
        checkStatus()
    }

    private fun onHotspotShareClicked() {
        val apkFile = apkManager.getCachedApk()
        if (apkFile != null) {
            viewModelScope.launch {
                _effect.send(ApkUiEffect.NavigateToHotspot(apkFile.absolutePath))
            }
        } else {
            sendToast(getString(R.string.apk_not_ready_please_prepare_it_first))
        }
    }

    private fun onConfirmAppShare() {
        _state.update { it.copy(showShareApkDialog = false) }
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val apkFile = apkManager.getCachedApk()
                if (apkFile == null || !apkFile.exists()) {
                    sendToast(getString(R.string.apk_not_ready_please_prepare_it_first))
                    return@launch
                }

                val context = getApplication<Application>()
                val uri = FileProvider.getUriForFile(
                    context,
                    "${context.packageName}.fileprovider",
                    apkFile
                )
                _effect.send(
                    ApkUiEffect.ShareApk(
                        apkUri = uri,
                        chooserTitle = getString(R.string.share_apk_chooser_title)
                    )
                )
            } catch (e: Exception) {
                Log.e(TAG, "Error preparing APK share", e)
                sendToast(getString(R.string.share_apk_error))
            }
        }
    }

    private fun onCancelDownload() {
        downloader.cancelDownload()
        checkStatus()
    }

    private fun startDownload() {
        val partial = apkManager.getPartialDownloadProgress()
        _state.update {
            it.copy(
                apkStatus = ApkPreparationStatus.Downloading,
                downloadProgress = partial ?: 0
            )
        }
        downloader.startDownload()
    }

    private fun checkStatus() {
        viewModelScope.launch {
            // WorkManager is the source of truth for active work. A queued or
            // newly started job legitimately has no partial file yet, so never
            // infer that it is orphaned from cache contents.
            if (_state.value.apkStatus is ApkPreparationStatus.Downloading) {
                return@launch
            }

            val resolvedStatus = resolveApkStatus()
            _state.update { current ->
                if (current.apkStatus is ApkPreparationStatus.Downloading) {
                    current
                } else {
                    current.copy(apkStatus = resolvedStatus)
                }
            }
        }
    }

    private fun observeDownloader() {
        viewModelScope.launch {
            downloader.downloadState.collect { downloadState ->
                when (downloadState) {
                    is ApkDownloader.DownloadState.Idle -> {
                        // Don't overwrite — status set by checkStatus()
                    }
                    is ApkDownloader.DownloadState.Downloading -> {
                        _state.update {
                            it.copy(
                                apkStatus = ApkPreparationStatus.Downloading,
                                downloadProgress = downloadState.progressPercent
                            )
                        }
                    }
                    is ApkDownloader.DownloadState.Success -> {
                        val info = apkManager.getCachedApkInfo()
                        _state.update {
                            it.copy(
                                apkStatus = ApkPreparationStatus.Ready(
                                    version = info?.version ?: downloadState.version,
                                    sizeMB = info?.let { cached ->
                                        (cached.size / 1024 / 1024).toInt()
                                    } ?: downloadState.sizeMB,
                                    source = info?.source ?: UniversalApkManager.ApkSource.GITHUB,
                                    variant = info?.variant ?: ShareableApkVariant.UNIVERSAL
                                ),
                                downloadProgress = 100
                            )
                        }
                    }
                    is ApkDownloader.DownloadState.Failed -> {
                        val localArm64 = apkManager.getCachedApkInfo()
                            ?.takeIf { it.variant == ShareableApkVariant.ARM64 }
                        if (localArm64 != null) {
                            _state.update {
                                it.copy(
                                    apkStatus = ApkPreparationStatus.Ready(
                                        version = localArm64.version,
                                        sizeMB = (localArm64.size / 1024 / 1024).toInt(),
                                        source = localArm64.source,
                                        variant = localArm64.variant
                                    )
                                )
                            }
                            _effect.send(ApkUiEffect.ShowToast(downloadState.message))
                        } else {
                            _state.update {
                                if (downloadState.resumablePercent != null) {
                                    it.copy(
                                        apkStatus = ApkPreparationStatus.Resumable(
                                            progressPercent = downloadState.resumablePercent,
                                            message = downloadState.message
                                        ),
                                        downloadProgress = downloadState.resumablePercent
                                    )
                                } else {
                                    it.copy(
                                        apkStatus = ApkPreparationStatus.Error(downloadState.message)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun sendToast(message: String) {
        viewModelScope.launch {
            _effect.send(ApkUiEffect.ShowToast(message))
        }
    }

    private fun getString(resId: Int): String {
        return getApplication<Application>().getString(resId)
    }

    private suspend fun resolveApkStatus(): ApkPreparationStatus = withContext(Dispatchers.IO) {
        try {
            val updateStatus = apkManager.checkForUpdate()
            when (updateStatus) {
                is UniversalApkManager.UpdateStatus.NotDownloaded -> {
                    val partial = apkManager.getPartialDownloadProgress()
                    if (partial != null) {
                        ApkPreparationStatus.Resumable(
                            progressPercent = partial,
                            message = getString(R.string.prepare_apk_download_interrupted)
                        )
                    } else {
                        ApkPreparationStatus.NotDownloaded(
                            sizeMB = (updateStatus.latestRelease.universalApkSize / 1024 / 1024).toInt()
                        )
                    }
                }
                is UniversalApkManager.UpdateStatus.UpToDate -> {
                    val info = apkManager.getCachedApkInfo()
                    if (info != null) {
                        ApkPreparationStatus.Ready(
                            version = info.version,
                            sizeMB = (info.size / 1024 / 1024).toInt(),
                            source = info.source,
                            variant = info.variant
                        )
                    } else {
                        ApkPreparationStatus.Error("Cached APK info not found")
                    }
                }
                is UniversalApkManager.UpdateStatus.UpdateAvailable -> {
                    ApkPreparationStatus.UpdateAvailable(
                        currentVersion = updateStatus.currentVersion,
                        newVersion = updateStatus.latestRelease.versionName,
                        newSizeMB = (updateStatus.latestRelease.universalApkSize / 1024 / 1024).toInt()
                    )
                }
                is UniversalApkManager.UpdateStatus.Error -> {
                    // A cached artifact stays shareable even when the update
                    // check fails or the release lags the installed version.
                    val info = apkManager.getCachedApkInfo()
                    if (info != null) {
                        ApkPreparationStatus.Ready(
                            version = info.version,
                            sizeMB = (info.size / 1024 / 1024).toInt(),
                            source = info.source,
                            variant = info.variant
                        )
                    } else {
                        val partial = apkManager.getPartialDownloadProgress()
                        if (partial != null) {
                            ApkPreparationStatus.Resumable(
                                progressPercent = partial,
                                message = getString(R.string.prepare_apk_download_interrupted)
                            )
                        } else {
                            ApkPreparationStatus.Error(updateStatus.message)
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error checking APK status", e)
            ApkPreparationStatus.Error(
                e.message ?: getString(R.string.prepare_apk_error_github)
            )
        }
    }
}

package com.bitchat.android.ui

import com.google.gson.JsonParser
import java.net.URI
import java.net.URLEncoder
import java.nio.charset.StandardCharsets
import java.math.BigDecimal
import java.util.Base64
import java.util.Currency
import java.util.Locale

/**
 * Bounded, display-only Cashu token decoder. Tokens are bearer instruments, so
 * this class never contacts a mint or attempts to hold/redeem funds.
 */
object CashuTokenDecoder {
    const val MAX_TOKEN_LENGTH = 60_000
    private const val MAX_AMOUNT = 2_100_000_000_000_000L

    data class TokenInfo(
        val version: Char,
        val amount: Long?,
        val unit: String?,
        val mintHost: String?,
        val memo: String?
    ) {
        val displayAmount: String?
            get() = amount?.let { value ->
                val displayUnit = unit ?: "sat"
                val minorDigits = minorUnitDigits(displayUnit)
                val formatted = if (minorDigits == null || minorDigits == 0) {
                    value.toString()
                } else {
                    BigDecimal.valueOf(value, minorDigits).setScale(minorDigits).toPlainString()
                }
                "$formatted $displayUnit"
            }
    }

    fun bareToken(raw: String): String? {
        var token = raw.trim()
        if ('%' in token) token = percentDecode(token) ?: return null
        token = when {
            token.startsWith("cashu://", ignoreCase = true) -> token.substring(8)
            token.startsWith("cashu:", ignoreCase = true) -> token.substring(6)
            else -> token
        }
        if (token.length !in 12..MAX_TOKEN_LENGTH) return null
        if (!token.startsWith("cashuA") && !token.startsWith("cashuB")) return null
        if (token.any { !it.isLetterOrDigit() && it !in "-_+/=" }) return null
        return token
    }

    /**
     * Permissive decoding is suitable for display: unsupported but plausible
     * v4 CBOR still gets a generic chip. Strict decoding is required before
     * sending and accepts only a fully parsed token with a positive amount.
     */
    fun decode(raw: String, strict: Boolean = false): TokenInfo? {
        val token = bareToken(raw) ?: return null
        val payload = decodeBase64Url(token.substring(6)) ?: return null
        if (payload.isEmpty()) return null
        val info = when (token[5]) {
            'A' -> decodeV3(payload)
            'B' -> decodeV4(payload) ?: if (strict) null else TokenInfo('B', null, null, null, null)
            else -> null
        } ?: return null
        return if (!strict || (info.amount != null && info.amount > 0)) info else null
    }

    fun extractTokens(text: String, max: Int = 3): List<String> {
        if (text.isEmpty() || max <= 0) return emptyList()
        val matches = TOKEN_REGEX.findAll(text)
        val result = LinkedHashSet<String>()
        for (match in matches) {
            bareToken(match.value)?.let(result::add)
            if (result.size == max) break
        }
        return result.toList()
    }

    fun walletUri(token: String): String? = bareToken(token)?.let { "cashu:${encodeUriComponent(it)}" }

    fun webRedeemUri(token: String): String? =
        bareToken(token)?.let { "https://redeem.cashu.me/?token=${encodeUriComponent(it)}" }

    private fun encodeUriComponent(value: String): String =
        URLEncoder.encode(value, StandardCharsets.UTF_8.name()).replace("+", "%20")

    /** Percent-decodes URI input without URLDecoder's form-specific '+' → space conversion. */
    private fun percentDecode(value: String): String? {
        val output = StringBuilder(value.length)
        var index = 0
        while (index < value.length) {
            if (value[index] != '%') {
                output.append(value[index++])
                continue
            }
            val bytes = ArrayList<Byte>()
            while (index < value.length && value[index] == '%') {
                if (index + 2 >= value.length) return null
                val byte = value.substring(index + 1, index + 3).toIntOrNull(16) ?: return null
                bytes += byte.toByte()
                index += 3
            }
            output.append(String(bytes.toByteArray(), StandardCharsets.UTF_8))
        }
        return output.toString()
    }

    private fun decodeBase64Url(input: String): ByteArray? {
        val normalized = input.replace('-', '+').replace('_', '/').trimEnd('=')
        if (normalized.length % 4 == 1) return null
        val padded = normalized + "=".repeat((4 - normalized.length % 4) % 4)
        return runCatching { Base64.getDecoder().decode(padded) }.getOrNull()
    }

    private fun decodeV3(payload: ByteArray): TokenInfo? = runCatching {
        val root = JsonParser.parseString(String(payload, StandardCharsets.UTF_8)).asJsonObject
        val entries = root.getAsJsonArray("token")?.takeIf { it.size() > 0 } ?: return null
        var total = 0L
        var sawAmount = false
        var mintHost: String? = null
        for (entryElement in entries) {
            val entry = entryElement.takeIf { it.isJsonObject }?.asJsonObject ?: continue
            if (mintHost == null) mintHost = sanitizeHost(entry.get("mint")?.takeIf { it.isJsonPrimitive }?.asString)
            val proofs = entry.getAsJsonArray("proofs") ?: continue
            for (proofElement in proofs) {
                val amountElement = proofElement.takeIf { it.isJsonObject }?.asJsonObject?.get("amount") ?: continue
                if (!amountElement.isJsonPrimitive || !amountElement.asJsonPrimitive.isNumber) continue
                val value = runCatching { amountElement.asBigDecimal.longValueExact() }.getOrNull() ?: continue
                if (value <= 0 || value > MAX_AMOUNT) continue
                if (total > MAX_AMOUNT - value) return null
                total += value
                sawAmount = true
            }
        }
        TokenInfo(
            version = 'A',
            amount = total.takeIf { sawAmount },
            unit = sanitizeUnit(root.get("unit")?.takeIf { it.isJsonPrimitive }?.asString),
            mintHost = mintHost,
            memo = sanitizeMemo(root.get("memo")?.takeIf { it.isJsonPrimitive }?.asString)
        )
    }.getOrNull()

    private fun decodeV4(payload: ByteArray): TokenInfo? {
        val root = CborReader(payload).parseComplete() as? CborValue.MapValue ?: return null
        var total = 0L
        var sawAmount = false
        var mintHost: String? = null
        var unit: String? = null
        var memo: String? = null
        for ((key, value) in root.pairs) {
            when ((key as? CborValue.Text)?.value) {
                "m" -> mintHost = sanitizeHost((value as? CborValue.Text)?.value)
                "u" -> unit = sanitizeUnit((value as? CborValue.Text)?.value)
                "d" -> memo = sanitizeMemo((value as? CborValue.Text)?.value)
                "t" -> for (group in (value as? CborValue.ArrayValue)?.values.orEmpty()) {
                    for ((groupKey, groupValue) in (group as? CborValue.MapValue)?.pairs.orEmpty()) {
                        if ((groupKey as? CborValue.Text)?.value != "p") continue
                        for (proof in (groupValue as? CborValue.ArrayValue)?.values.orEmpty()) {
                            for ((proofKey, proofValue) in (proof as? CborValue.MapValue)?.pairs.orEmpty()) {
                                if ((proofKey as? CborValue.Text)?.value != "a") continue
                                val amount = (proofValue as? CborValue.Unsigned)?.value ?: continue
                                if (amount == 0L || amount > MAX_AMOUNT) continue
                                if (total > MAX_AMOUNT - amount) return null
                                total += amount
                                sawAmount = true
                            }
                        }
                    }
                }
            }
        }
        return TokenInfo('B', total.takeIf { sawAmount }, unit, mintHost, memo)
    }

    private fun sanitizeHost(value: String?): String? = value
        ?.takeIf { it.length <= 512 }
        ?.let { runCatching { URI(it).host }.getOrNull() }
        ?.takeIf { it.isNotEmpty() }
        ?.lowercase()
        ?.take(48)

    private fun sanitizeUnit(value: String?): String? =
        value?.takeIf { it.isNotEmpty() && it.length <= 12 && it.all(Char::isLetterOrDigit) }

    private fun sanitizeMemo(value: String?): String? {
        if (value == null || value.length > 512) return null
        return value.filterNot(Char::isISOControl).trim().take(80).takeIf(String::isNotEmpty)
    }

    /** ISO-4217 values use their currency's minor unit; custom units stay integer-denominated. */
    private fun minorUnitDigits(unit: String): Int? {
        return runCatching {
            Currency.getInstance(unit.uppercase(Locale.ROOT)).defaultFractionDigits
        }.getOrNull()?.takeIf { it >= 0 }
    }

    private val TOKEN_REGEX = Regex("""(?i:cashu:(?://)?)?cashu[AB][A-Za-z0-9_+/%=-]{6,}""")
}

private sealed interface CborValue {
    data class Unsigned(val value: Long) : CborValue
    data class Text(val value: String) : CborValue
    data class ArrayValue(val values: List<CborValue>) : CborValue
    data class MapValue(val pairs: List<Pair<CborValue, CborValue>>) : CborValue
    data object Opaque : CborValue
}

private class CborReader(private val bytes: ByteArray) {
    private var index = 0
    private var itemBudget = 50_000

    fun parseComplete(): CborValue? {
        val value = parseValue(0) ?: return null
        return value.takeIf { index == bytes.size }
    }

    private fun parseValue(depth: Int): CborValue? {
        if (depth >= 16 || itemBudget-- <= 0) return null
        val (major, argument) = readHead() ?: return null
        return when (major) {
            0 -> CborValue.Unsigned(argument.takeIf { it <= Long.MAX_VALUE }?.toLong() ?: return null)
            1 -> CborValue.Opaque
            2 -> if (readBytes(argument) != null) CborValue.Opaque else null
            3 -> readBytes(argument)?.toString(StandardCharsets.UTF_8)?.let(CborValue::Text)
            4 -> parseContainer(argument, depth) { CborValue.ArrayValue(it) }
            5 -> {
                if (argument > 10_000 || argument > itemBudget / 2) return null
                val pairs = ArrayList<Pair<CborValue, CborValue>>(argument.coerceAtMost(64).toInt())
                repeat(argument.toInt()) {
                    pairs += (parseValue(depth + 1) ?: return null) to (parseValue(depth + 1) ?: return null)
                }
                CborValue.MapValue(pairs)
            }
            6 -> parseValue(depth + 1)
            7 -> CborValue.Opaque
            else -> null
        }
    }

    private fun parseContainer(
        count: Long,
        depth: Int,
        wrap: (List<CborValue>) -> CborValue
    ): CborValue? {
        if (count > 10_000 || count > itemBudget) return null
        val values = ArrayList<CborValue>(count.coerceAtMost(64).toInt())
        repeat(count.toInt()) { values += parseValue(depth + 1) ?: return null }
        return wrap(values)
    }

    private fun readHead(): Pair<Int, Long>? {
        if (index >= bytes.size) return null
        val head = bytes[index++].toInt() and 0xff
        val major = head ushr 5
        val info = head and 0x1f
        val argument = when (info) {
            in 0..23 -> info.toLong()
            24 -> readUInt(1)
            25 -> readUInt(2)
            26 -> readUInt(4)
            27 -> readUInt(8)
            else -> null
        } ?: return null
        return major to argument
    }

    private fun readUInt(width: Int): Long? {
        if (bytes.size - index < width) return null
        var value = 0L
        repeat(width) {
            val next = bytes[index++].toLong() and 0xff
            if (value > (Long.MAX_VALUE - next) ushr 8) return null
            value = (value shl 8) or next
        }
        return value
    }

    private fun readBytes(count: Long): ByteArray? {
        if (count < 0 || count > bytes.size - index) return null
        val end = index + count.toInt()
        return bytes.copyOfRange(index, end).also { index = end }
    }
}

