        sortConversationSummaries(
            summaries.map { summary ->
                val key = summary.conversationID.lowercase()
                summary.copy(
                    isPinned = key in pinned,
                    isMuted = key in muted,
                    draft = drafts[key]
                )
            }
        )
    }
        .flowOn(Dispatchers.IO)
