    /**
     * Dismiss the command and mention popups. The composer clears its field in code
     * after a send, which does not run onValueChange, so the popups need an explicit
     * clear.
     */
    fun clearSuggestions() {
        state.setShowCommandSuggestions(false)
        state.setCommandSuggestions(emptyList())
        state.setShowMentionSuggestions(false)
        state.setMentionSuggestions(emptyList())
    }

    // MARK: - Command Autocomplete

    fun updateCommandSuggestions(input: String) {
        if (!input.startsWith("/")) {
            state.setShowCommandSuggestions(false)
            state.setCommandSuggestions(emptyList())
            return
        }

        // Get all available commands based on context
        val allCommands = getAllAvailableCommands()

        // Filter commands based on input
        val filteredCommands = filterCommands(allCommands, input.lowercase())

        if (filteredCommands.isNotEmpty()) {
            state.setCommandSuggestions(filteredCommands)
            state.setShowCommandSuggestions(true)
        } else {
            state.setShowCommandSuggestions(false)
            state.setCommandSuggestions(emptyList())
        }
    }

    private fun getAllAvailableCommands(): List<CommandSuggestion> {
        // Add channel-specific commands if in a channel
        val channelCommands = if (state.getCurrentChannelValue() != null) {
            listOf(
                CommandSuggestion("/pass", emptyList(), "[password]", "change channel password"),
                CommandSuggestion("/save", emptyList(), null, "save channel messages locally"),
                CommandSuggestion("/transfer", emptyList(), "<nickname>", "transfer channel ownership")
            )
        } else {
            emptyList()
        }

        val isPublicGeohash =
            state.getSelectedPrivateChatPeerValue() == null &&
                state.selectedLocationChannel.value is com.bitchat.android.geohash.ChannelID.Location
        return (baseCommands + channelCommands).filterNot {
            isPublicGeohash && it.command == "/pay"
        }
    }

    private fun filterCommands(commands: List<CommandSuggestion>, input: String): List<CommandSuggestion> {
        return commands.filter { command ->
            // Check primary command
            command.command.startsWith(input) ||
            // Check aliases
            command.aliases.any { it.startsWith(input) }
        }.sortedBy { it.command }
    }

    fun selectCommandSuggestion(suggestion: CommandSuggestion): String {
        state.setShowCommandSuggestions(false)
        state.setCommandSuggestions(emptyList())
        return "${suggestion.command} "
    }

    // MARK: - Mention Autocomplete

    fun updateMentionSuggestions(input: String, meshService: MeshService, viewModel: ChatViewModel? = null) {
        // Check if input contains @ and we're at the end of a word or at the end of input
        val atIndex = input.lastIndexOf('@')
        if (atIndex == -1) {
            state.setShowMentionSuggestions(false)
            state.setMentionSuggestions(emptyList())
            return
        }

        // Get the text after the @ symbol
        val textAfterAt = input.substring(atIndex + 1)

        // If there's a space after @, don't show suggestions
        if (textAfterAt.contains(' ')) {
            state.setShowMentionSuggestions(false)
            state.setMentionSuggestions(emptyList())
            return
        }

        // Get peer candidates based on active channel (matches iOS logic exactly)
        val peerCandidates: List<String> = if (viewModel != null) {
            when (val selectedChannel = viewModel.selectedLocationChannel.value) {
                is com.bitchat.android.geohash.ChannelID.Mesh,
                null -> {
                    // Mesh channel: use Bluetooth mesh peer nicknames
                    val peerNicknames = meshService.getPeerNicknames()
                    peerNicknames.values.filter { it != peerNicknames[meshService.myPeerID] }
                }

                is com.bitchat.android.geohash.ChannelID.Location -> {
                    // Location channel: use geohash participants with collision-resistant suffixes
                    val geohashPeople = viewModel.geohashPeople.value
                    val currentNickname = state.getNicknameValue()
                    val duplicateNames = duplicateGeohashBaseNames(geohashPeople)

                    geohashPeople.mapNotNull { person ->
                        val baseName = splitSuffix(person.displayName).first
                        val hasNicknameCollision =
                            baseName.lowercase(Locale.ROOT) in duplicateNames
                        val displayName = disambiguatedGeohashDisplayName(person, duplicateNames)
                        // A unique local nickname can be excluded directly. If it collides, the
                        // nickname alone cannot identify which row is self, so keep the suffixed
                        // rows rather than accidentally hiding the other user.
                        if (
                            !hasNicknameCollision &&
                            baseName.equals(currentNickname, ignoreCase = true)
                        ) {
                            null
                        } else {
                            displayName
                        }
                    }
                }
            }
        } else {
            // Fallback to mesh peers if no viewModel available
            val peerNicknames = meshService.getPeerNicknames()
            peerNicknames.values.filter { it != peerNicknames[meshService.myPeerID] }
        }

        val filteredNicknames = filterMentionCandidates(peerCandidates, textAfterAt)

        if (filteredNicknames.isNotEmpty()) {
            state.setMentionSuggestions(filteredNicknames)
            state.setShowMentionSuggestions(true)
        } else {
            state.setShowMentionSuggestions(false)
            state.setMentionSuggestions(emptyList())
        }
    }

    fun selectMentionSuggestion(nickname: String, currentText: String): String {
        state.setShowMentionSuggestions(false)
        state.setMentionSuggestions(emptyList())

        // Find the last @ symbol position
        val atIndex = currentText.lastIndexOf('@')
        if (atIndex == -1) {
            return "$currentText@$nickname "
        }

        // Replace the text from the @ symbol to the end with the mention
        val textBeforeAt = currentText.substring(0, atIndex)
        return "$textBeforeAt@$nickname "
    }

    // MARK: - Utility Functions

    private fun getPeerIDForNickname(nickname: String, meshService: MeshService): String? {
        return meshService.getPeerNicknames().entries.find { it.value == nickname }?.key
    }

    private fun getPeerNickname(peerID: String, meshService: MeshService): String {
        return meshService.getPeerNicknames()[peerID]
            ?: peerID
    }

    private fun getMyPeerID(meshService: MeshService): String {
        return meshService.myPeerID
    }

    private fun sendPrivateMessage(
        content: String,
        peerID: String,
        recipientNickname: String?,
        senderNickname: String?,
        myPeerID: String,
        meshService: MeshService,
        viewModel: ChatViewModel?
    ) {
        val send: (String, String, String, String) -> Unit =
            { messageContent, peerIdParam, recipientNicknameParam, messageId ->
                sendPrivateMessageVia(
                    meshService,
                    messageContent,
                    peerIdParam,
                    recipientNicknameParam,
                    messageId,
                    viewModel
                )
            }
        val scope = coroutineScope
        if (scope == null) {
            privateChatManager.sendPrivateMessage(
                content,
                peerID,
                recipientNickname,
                senderNickname,
                myPeerID,
                send
            )
        } else {
            scope.launch {
                privateChatManager.sendPrivateMessageDurably(
                    content,
                    peerID,
                    recipientNickname,
                    senderNickname,
                    myPeerID,
                    send
                )
            }
        }
    }

    private fun sendPrivateMessageVia(
        meshService: MeshService,
        content: String,
        peerID: String,
        recipientNickname: String,
        messageId: String,
        viewModel: ChatViewModel?
    ) {
        if (viewModel != null) {
            com.bitchat.android.services.MessageRouter
                .getInstance(viewModel.getApplication(), meshService)
                .sendPrivate(content, peerID, recipientNickname, messageId)
        } else {
            meshService.sendPrivateMessage(content, peerID, recipientNickname, messageId)
        }
    }
}

/**
 * Keep mention autocomplete useful in crowded channels: a bare `anon` identity has not announced
 * a username and is not actionable. Names such as `anon1234` are announced usernames and remain
 * valid mention targets.
 */
internal fun filterMentionCandidates(
    candidates: List<String>,
    query: String
): List<String> {
    return candidates.asSequence()
        .map(String::trim)
        .filter(String::isNotEmpty)
        .filterNot(::isUnannouncedNickname)
        .filter { nickname -> nickname.startsWith(query, ignoreCase = true) }
        .distinctBy { nickname -> nickname.lowercase(Locale.ROOT) }
        .sortedWith(String.CASE_INSENSITIVE_ORDER)
        .toList()
}

package com.bitchat.android.ui

/**
 * Resolves the Noise session shown for a private conversation.
 *
 * Persistent conversations use a canonical contact ID, while live Noise sessions are keyed by
 * the currently connected mesh peer ID. Prefer that live identity and retain the conversation ID
 * as a fallback for peers whose IDs are already identical.
 */
internal fun resolveConversationSessionState(
    conversationID: String,
    activeMeshPeerID: String?,
    peerSessionStates: Map<String, String>
): String? {
    return activeMeshPeerID?.let(peerSessionStates::get)
        ?: peerSessionStates[conversationID]
}

package com.bitchat.android.ui

import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.BitchatMessageType
import com.bitchat.android.model.DeliveryStatus
import com.bitchat.android.services.PrivateMessageArrivalOrder

/**
 * Presence-independent presentation state for every retained private conversation.
 */
internal data class ConversationSummary(
    val conversationID: String,
    val displayName: String,
    val unreadCount: Int,
    val latestMessageAt: Long,
    val latestActivityOrder: Long,
    val latestMessageType: BitchatMessageType,
    val latestMessagePreview: String,
    val latestMessageIsOutgoing: Boolean = false,
    val latestDeliveryStatus: DeliveryStatus? = null,
    val transport: DirectMessageTransport,
    val nostrPubkey: String?,
    val identityAliases: Set<String>,
    val isConnected: Boolean = false,
    val connectedPeerID: String? = null,
    val sourceGeohash: String? = null,
    val isPinned: Boolean = false,
    val isMuted: Boolean = false,
    val draft: String? = null
)

internal fun buildConversationSummaries(
    unreadConversationIDs: Set<String>,
    privateChats: Map<String, List<BitchatMessage>>,
    currentUserIdentifiers: Set<String>,
    canonicalize: (String) -> String,
    isMessageRead: (BitchatMessage) -> Boolean,
    persistedUnreadCounts: Map<String, Int> = emptyMap()
): List<ConversationSummary> {
    if (privateChats.isEmpty()) return emptyList()

    val currentUsers = currentUserIdentifiers
        .filter(String::isNotBlank)
        .mapTo(mutableSetOf()) { it.lowercase() }
    val unreadCanonicalIDs = unreadConversationIDs
        .mapTo(mutableSetOf()) { canonicalize(it).lowercase() }
    val unreadCountsByCanonicalID = persistedUnreadCounts.entries
        .groupingBy { canonicalize(it.key).lowercase() }
        .fold(0) { total, entry -> total + entry.value }
    val aliasesByCanonicalID = linkedMapOf<String, MutableSet<String>>()
    val messagesByCanonicalID = linkedMapOf<String, MutableList<BitchatMessage>>()
    val displayCanonicalIDByNormalized = linkedMapOf<String, String>()

    privateChats.forEach { (sourceID, messages) ->
        val canonicalID = canonicalize(sourceID)
        val normalizedID = canonicalID.lowercase()
        displayCanonicalIDByNormalized.putIfAbsent(normalizedID, canonicalID)
        aliasesByCanonicalID
            .getOrPut(normalizedID) { linkedSetOf() }
            .add(sourceID)
        messagesByCanonicalID
            .getOrPut(normalizedID) { mutableListOf() }
            .addAll(messages)
    }

    return messagesByCanonicalID.mapNotNull { (normalizedConversationID, sourceMessages) ->
        val conversationID =
            displayCanonicalIDByNormalized.getValue(normalizedConversationID)
        val messages = sourceMessages.distinctBy { it.id }
        if (messages.isEmpty()) return@mapNotNull null

        fun activityOrder(message: BitchatMessage): Long =
            PrivateMessageArrivalOrder.sequenceOf(message.id) ?: message.timestamp.time

        val latest = messages.maxWithOrNull(
            compareBy<BitchatMessage>(::activityOrder).thenBy { it.id }
        ) ?: return@mapNotNull null
        fun isOutgoing(message: BitchatMessage): Boolean =
            message.sender.lowercase() in currentUsers ||
                message.senderPeerID?.lowercase() in currentUsers

        val incoming = messages.filterNot {
            isOutgoing(it) || it.sender == "system"
        }
        val latestIncoming = incoming.maxWithOrNull(
            compareBy<BitchatMessage>(::activityOrder).thenBy { it.id }
        )
        val canonicalUnread = conversationID.lowercase() in unreadCanonicalIDs
        val persistedUnreadCount = unreadCountsByCanonicalID[conversationID.lowercase()] ?: 0
        val unreadCount = maxOf(
            persistedUnreadCount,
            if (canonicalUnread && incoming.isNotEmpty()) {
                incoming.count { !isMessageRead(it) }.coerceAtLeast(1)
            } else {
                0
            }
        )
        val aliases = aliasesByCanonicalID[normalizedConversationID].orEmpty()
        val nostrPubkey = latestIncoming?.senderNostrPubkey ?: latest.senderNostrPubkey
        val isNostrConversation = nostrPubkey != null ||
            aliases.any(::isNostrConversationKey) ||
            isNostrConversationKey(conversationID)
        val displayName = latestIncoming
            ?.sender
            ?.takeIf { it.isNotBlank() }
            ?: latest.recipientNickname
                ?.takeIf { it.isNotBlank() }
            ?: latest.sender.takeIf {
                it.isNotBlank() && it !in currentUsers && it != "system"
            }
            ?: conversationID.take(12)

        ConversationSummary(
            conversationID = conversationID,
            displayName = displayName,
            unreadCount = unreadCount,
            latestMessageAt =
                PrivateMessageArrivalOrder.receivedAtOf(latest.id) ?: latest.timestamp.time,
            latestActivityOrder = activityOrder(latest),
            latestMessageType = latest.type,
            latestMessagePreview = latest.conversationPreview(),
            latestMessageIsOutgoing = isOutgoing(latest),
            latestDeliveryStatus = latest.deliveryStatus,
            transport = if (isNostrConversation) {
                DirectMessageTransport.NOSTR
            } else {
                DirectMessageTransport.MESH
            },
            nostrPubkey = nostrPubkey,
            identityAliases = (aliases + conversationID)
                .mapTo(mutableSetOf()) { it.lowercase() }
        )
    }
}

internal fun resolveConversationDisplayName(
    fallbackName: String,
    connectedPeerID: String?,
    peerNicknames: Map<String, String>,
    resolvedContactName: String?,
    persistedDisplayName: String?
): String {
    fun String?.usableName(): String? = this?.takeUnless {
        it.isBlank() || it.equals("Unknown", ignoreCase = true)
    }

    val liveName = connectedPeerID?.let { peerID ->
        peerNicknames[peerID]
            ?: peerNicknames.entries
                .firstOrNull { (candidateID, _) ->
                    candidateID.equals(peerID, ignoreCase = true)
                }
                ?.value
    }
    return liveName.usableName()
        ?: resolvedContactName.usableName()
        ?: persistedDisplayName.usableName()
        ?: fallbackName
}

internal fun sortConversationSummaries(
    conversations: List<ConversationSummary>
): List<ConversationSummary> = conversations.sortedWith(
    compareByDescending<ConversationSummary> { it.isConnected }
        .thenByDescending { it.isPinned }
        .thenByDescending { it.unreadCount > 0 }
        .thenByDescending { it.latestActivityOrder }
        .thenBy { it.displayName.lowercase() }
        .thenBy { it.conversationID }
)

private fun isNostrConversationKey(value: String): Boolean =
    value.startsWith("nostr_") || value.startsWith("nostr:")

private fun BitchatMessage.conversationPreview(): String {
    val preview = when (type) {
        BitchatMessageType.File -> content
            .substringAfterLast('/')
            .substringAfterLast('\\')
        else -> content
    }
    return preview
        .replace(CONVERSATION_PREVIEW_WHITESPACE, " ")
        .trim()
        .take(MAX_CONVERSATION_PREVIEW_LENGTH)
}

private val CONVERSATION_PREVIEW_WHITESPACE = Regex("\\s+")
private const val MAX_CONVERSATION_PREVIEW_LENGTH = 240

package com.bitchat.android.ui

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import com.bitchat.android.geohash.DEFAULT_LIVE_LOCATION_ENABLED
import com.google.gson.Gson
import kotlin.random.Random

/**
 * Handles data persistence operations for the chat system
 */
class DataManager(private val context: Context) {

    companion object {
        private const val TAG = "DataManager"
    }

    private val prefs: SharedPreferences = context.getSharedPreferences("bitchat_prefs", Context.MODE_PRIVATE)
    private val gson = Gson()

    // Channel-related maps that need to persist state
    private val _channelCreators = mutableMapOf<String, String>()
    private val _favoritePeers = mutableSetOf<String>()
    private val _blockedUsers = mutableSetOf<String>()
    private val _channelMembers = mutableMapOf<String, MutableSet<String>>()

    val channelCreators: Map<String, String> get() = _channelCreators
    val favoritePeers: Set<String> get() = _favoritePeers
    val blockedUsers: Set<String> get() = _blockedUsers
    val channelMembers: Map<String, MutableSet<String>> get() = _channelMembers

    // MARK: - Nickname Management

    fun loadNickname(): String {
        val savedNickname = prefs.getString("nickname", null)
        return if (savedNickname != null) {
            savedNickname
        } else {
            val randomNickname = "anon${Random.nextInt(1000, 9999)}"
            saveNickname(randomNickname)
            randomNickname
        }
    }

    fun saveNickname(nickname: String) {
        prefs.edit().putString("nickname", nickname).apply()
    }

    // MARK: - Geohash Channel Persistence

    fun loadLastGeohashChannel(): String? {
        return prefs.getString("last_geohash_channel", null)
    }

    fun saveLastGeohashChannel(channelData: String) {
        prefs.edit().putString("last_geohash_channel", channelData).apply()
        Log.d(TAG, "Saved last geohash channel")
    }

    fun clearLastGeohashChannel() {
        prefs.edit().remove("last_geohash_channel").apply()
        Log.d(TAG, "Cleared last geohash channel")
    }

    // MARK: - Location Services State

    fun saveLocationServicesEnabled(enabled: Boolean) {
        prefs.edit().putBoolean("location_services_enabled", enabled).commit()
        Log.d(TAG, "Saved location services enabled state: $enabled")
    }

    fun isLocationServicesEnabled(): Boolean {
        return prefs.getBoolean("location_services_enabled", DEFAULT_LIVE_LOCATION_ENABLED)
    }

    // MARK: - Channel Data Management

    fun loadChannelData(): Pair<Set<String>, Set<String>> {
        // Load joined channels
        val savedChannels = prefs.getStringSet("joined_channels", emptySet()) ?: emptySet()

        // Load password protected channels
        val savedProtectedChannels = prefs.getStringSet("password_protected_channels", emptySet()) ?: emptySet()

        // Load channel creators
        val creatorsJson = prefs.getString("channel_creators", "{}")
        try {
            val creatorsMap = gson.fromJson(creatorsJson, Map::class.java) as? Map<String, String>
            creatorsMap?.let { _channelCreators.putAll(it) }
        } catch (e: Exception) {
            // Ignore parsing errors
        }

        // Initialize channel members for loaded channels
        savedChannels.forEach { channel ->
            if (!_channelMembers.containsKey(channel)) {
                _channelMembers[channel] = mutableSetOf()
            }
        }

        return Pair(savedChannels, savedProtectedChannels)
    }

    fun saveChannelData(joinedChannels: Set<String>, passwordProtectedChannels: Set<String>) {
        prefs.edit().apply {
            putStringSet("joined_channels", joinedChannels)
            putStringSet("password_protected_channels", passwordProtectedChannels)
            putString("channel_creators", gson.toJson(_channelCreators))
            apply()
        }
    }

    fun addChannelCreator(channel: String, creatorID: String) {
        _channelCreators[channel] = creatorID
    }

    fun removeChannelCreator(channel: String) {
        _channelCreators.remove(channel)
    }

    fun isChannelCreator(channel: String, peerID: String): Boolean {
        return _channelCreators[channel] == peerID
    }

    // MARK: - Channel Members Management

    fun addChannelMember(channel: String, peerID: String) {
        if (!_channelMembers.containsKey(channel)) {
            _channelMembers[channel] = mutableSetOf()
        }
        _channelMembers[channel]?.add(peerID)
    }

    fun removeChannelMember(channel: String, peerID: String) {
        _channelMembers[channel]?.remove(peerID)
    }

    fun removeChannelMembers(channel: String) {
        _channelMembers.remove(channel)
    }

    fun cleanupDisconnectedMembers(channel: String, connectedPeers: List<String>, myPeerID: String) {
        _channelMembers[channel]?.removeAll { memberID ->
            memberID != myPeerID && !connectedPeers.contains(memberID)
        }
    }

    fun cleanupAllDisconnectedMembers(connectedPeers: List<String>, myPeerID: String) {
        _channelMembers.values.forEach { members ->
            members.removeAll { memberID ->
                memberID != myPeerID && !connectedPeers.contains(memberID)
            }
        }
    }

    // MARK: - Favorites Management

    fun loadFavorites() {
        val savedFavorites = prefs.getStringSet("favorites", emptySet()) ?: emptySet()
        _favoritePeers.addAll(savedFavorites)
        Log.d(TAG, "Loaded ${savedFavorites.size} favorite users from storage: $savedFavorites")
    }

    fun saveFavorites() {
        prefs.edit().putStringSet("favorites", _favoritePeers).apply()
        Log.d(TAG, "Saved ${_favoritePeers.size} favorite users to storage: $_favoritePeers")
    }

    fun addFavorite(fingerprint: String) {
        val wasAdded = _favoritePeers.add(fingerprint)
        Log.d(TAG, "addFavorite: fingerprint=$fingerprint, wasAdded=$wasAdded")
        saveFavorites()
        logAllFavorites()
    }

    fun removeFavorite(fingerprint: String) {
        val wasRemoved = _favoritePeers.remove(fingerprint)
        Log.d(TAG, "removeFavorite: fingerprint=$fingerprint, wasRemoved=$wasRemoved")
        saveFavorites()
        logAllFavorites()
    }

    fun isFavorite(fingerprint: String): Boolean {
        val result = _favoritePeers.contains(fingerprint)
        Log.d(TAG, "isFavorite check: fingerprint=$fingerprint, result=$result")
        return result
    }

    fun logAllFavorites() {
        Log.i(TAG, "=== ALL FAVORITE USERS ===")
        Log.i(TAG, "Total favorites: ${_favoritePeers.size}")
        _favoritePeers.forEach { fingerprint ->
            Log.i(TAG, "Favorite fingerprint: $fingerprint")
        }
        Log.i(TAG, "========================")
    }

    // MARK: - Blocked Users Management

    @Synchronized
    fun loadBlockedUsers() {
        val savedBlockedUsers = prefs.getStringSet("blocked_users", emptySet()) ?: emptySet()
        _blockedUsers.clear()
        _blockedUsers.addAll(savedBlockedUsers)
    }

    fun saveBlockedUsers() {
        prefs.edit().putStringSet("blocked_users", _blockedUsers).apply()
    }

    fun addBlockedUser(fingerprint: String) {
        _blockedUsers.add(fingerprint)
        saveBlockedUsers()
    }

    fun removeBlockedUser(fingerprint: String) {
        _blockedUsers.remove(fingerprint)
        saveBlockedUsers()
    }

    @Synchronized
    fun isUserBlocked(fingerprint: String): Boolean {
        return _blockedUsers.contains(fingerprint)
    }

    // MARK: - Geohash Blocked Users Management

    private val _geohashBlockedUsers = mutableSetOf<String>() // Set of nostr pubkey hex
    val geohashBlockedUsers: Set<String> get() = _geohashBlockedUsers.toSet()

    @Synchronized
    fun loadGeohashBlockedUsers() {
        val savedGeohashBlockedUsers = prefs.getStringSet("geohash_blocked_users", emptySet()) ?: emptySet()
        _geohashBlockedUsers.clear()
        _geohashBlockedUsers.addAll(savedGeohashBlockedUsers)
    }

    fun saveGeohashBlockedUsers() {
        prefs.edit().putStringSet("geohash_blocked_users", _geohashBlockedUsers).apply()
    }

    fun addGeohashBlockedUser(pubkeyHex: String) {
        _geohashBlockedUsers.add(pubkeyHex)
        saveGeohashBlockedUsers()
    }

    fun removeGeohashBlockedUser(pubkeyHex: String) {
        _geohashBlockedUsers.remove(pubkeyHex)
        saveGeohashBlockedUsers()
    }

    @Synchronized
    fun isGeohashUserBlocked(pubkeyHex: String): Boolean {
        return _geohashBlockedUsers.contains(pubkeyHex)
    }

    // MARK: - Emergency Clear

    fun clearAllData() {
        _channelCreators.clear()
        _favoritePeers.clear()
        _blockedUsers.clear()
        _geohashBlockedUsers.clear()
        _channelMembers.clear()
        prefs.edit().clear().apply()
    }
}

