                    }

                    // Floating info pill
                    Surface(
                        modifier = Modifier
                            .align(Alignment.TopCenter)
                            .statusBarsPadding()
                            .padding(top = 20.dp)
                            .fillMaxWidth(0.8f),
                        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.85f),
                        shape = RoundedCornerShape(12.dp),
                        tonalElevation = 3.dp,
                        shadowElevation = 6.dp
                    ) {
                        Text(
