                            fontSize = 12.sp,
                            textAlign = TextAlign.Center,
                            fontFamily = BitchatFontFamily,
                            color = MaterialTheme.colorScheme.onSurface,
                            modifier = Modifier
                                .padding(horizontal = 14.dp, vertical = 10.dp)
