/**
 * Message display components for ChatScreen
 * Extracted from ChatScreen.kt for better organization
 */

/** How far a newly arrived message travels up into place. */
private val MessageEntrySlide = 14.dp

/**
 * Entry motion for a new message: quick, with just enough damping to settle rather than snap.
 * Runs entirely on a graphics layer, so it costs a transform and nothing else.
 */
private val MessageEntrySpec: AnimationSpec<Float> =
    spring(dampingRatio = 0.85f, stiffness = 1200f)

/**
 * Motion for messages being pushed out of the way by an arrival. Softer than the entry so the
 * conversation glides up while the new message itself lands crisply.
 */
private val MessagePlacementSpec: FiniteAnimationSpec<IntOffset> = spring(
    dampingRatio = Spring.DampingRatioNoBouncy,
    stiffness = Spring.StiffnessMediumLow,
    visibilityThreshold = IntOffset.VisibilityThreshold
)

/** Removals are not worth dwelling on. */
private val MessageFadeOutSpec: FiniteAnimationSpec<Float> = tween(BitchatMotion.QUICK_MS)

/**
 * How long placement animation stays armed after the list gains or loses a message.
 *
 * Comfortably longer than [MessagePlacementSpec] takes to settle, so an arrival's push is never cut
 * short.
 */
private const val PlacementArmWindowMs = 600L

/**
 * Above this many simultaneous arrivals, entry animations are skipped.
 *
 * A history sync or a channel switch can append hundreds of messages in one frame. Animating each
 * would spend the entire frame budget on motion nobody asked to see, so a burst is adopted
 * silently and only conversational-pace arrivals animate.
 */
internal const val MaxAnimatedArrivals = 6

/**
 * Remembers which message ids have already been seen, so genuine arrivals can be told apart from
 * items merely scrolling back into view.
 *
 * This distinction is the whole reason the entry animation is usable: `LazyColumn` composes items
 * on demand, so animating on first composition would replay the animation for every old message
 * the user scrolled back to.
 */
internal class MessageArrivalTracker {
    val known = HashSet<String>()
    var seeded = false
}

/**
 * Ids that should animate in on this composition pass.
 *
 * Deliberately computed during composition rather than in a `LaunchedEffect`: effects run *after*
 * the frame's composition, by which point a new message's item has already composed and would
 * have missed its cue.
 */
internal fun MessageArrivalTracker.arrivals(messages: List<BitchatMessage>): Set<String> {
    if (!seeded) {
        // First load adopts everything silently. A whole screenful animating on open reads as a
        // glitch, not a flourish.
        messages.forEach { known.add(it.id) }
        seeded = true
        return emptySet()
    }

    // A list with nothing in common with the last one is a different conversation, not a burst of
    // arrivals — /clear, or a switch the caller did not give us a distinct key for. Adopt it
    // silently rather than sliding in every message at once.
    val isWholesaleReplacement =
        messages.isNotEmpty() && known.isNotEmpty() && messages.none { it.id in known }

    // `HashSet.add` reports whether the id was new, so this both diffs and updates in one pass.
    val added = messages.filter { known.add(it.id) }

    if (known.size > messages.size) {
        // Messages disappeared (/clear, channel switch). Drop the stale ids so the set cannot
        // grow without bound and so re-added messages animate again.
        known.retainAll(messages.mapTo(HashSet(messages.size)) { it.id })
    }

    return when {
        isWholesaleReplacement -> emptySet()
        added.isEmpty() || added.size > MaxAnimatedArrivals -> emptySet()
        else -> added.mapTo(HashSet(added.size)) { it.id }
    }
}

@Composable
fun MessagesList(
    messages: List<BitchatMessage>,
    currentUserNickname: String,
    meshService: MeshService,
    modifier: Modifier = Modifier,
    mentionPeerIdentities: Map<String, PeerIdentity>? = null,
    /**
     * Extra inset on top of the list's own gutters.
     *
     * The chat screen's bars are translucent and the list scrolls underneath them, so the caller
     * has to reserve room for their heights here rather than by shrinking the viewport.
     */
    contentPadding: PaddingValues = PaddingValues(0.dp),
    /**
     * Identity of the conversation being shown — a channel, a geohash, a peer.
     *
     * Everything below that is per-conversation state is keyed on this. Without it, switching
     * channels reused the previous conversation's scroll offset, follow flag and seen-message set,
     * so the new channel opened at a stale position and then animated itself into place.
     */
    conversationKey: Any? = null,
    forceScrollToBottom: Boolean = false,
    onScrolledUpChanged: ((Boolean) -> Unit)? = null,
    onNicknameClick: ((String) -> Unit)? = null,
    onMessageLongPress: ((BitchatMessage) -> Unit)? = null,
    onCancelTransfer: ((BitchatMessage) -> Unit)? = null,
    onImageClick: ((String, List<String>, Int) -> Unit)? = null
) {
    val resolvedMentionPeerIdentities = remember(messages, mentionPeerIdentities) {
        mentionPeerIdentities ?: buildMentionPeerIdentityMap(messages)
    }

    // Collected once here so individual rows never subscribe to the preference flow; a mode
    // switch simply recomposes the list against the new layout.
    val bubbles by ChatUiModeManager.modeFlow.collectAsState()

    // A fresh scroll position per conversation. Sharing one state meant a switch inherited the
    // previous channel's offset and then had to correct itself, which is what the jump was.
    //
    // Passing the key as an *input* rather than as `key =` is deliberate: it discards the saved
    // offset on every switch, so a conversation always opens on its newest message instead of
    // wherever the reader happened to be some time ago, with unseen messages below them.
    val listState = rememberSaveable(conversationKey, saver = LazyListState.Saver) {
        LazyListState()
    }

    // Track if this is the first time messages are being loaded
    var hasScrolledToInitialPosition by remember(conversationKey) { mutableStateOf(false) }
    var followIncomingMessages by remember(conversationKey) { mutableStateOf(true) }

    // Smart scroll: auto-scroll to bottom for initial load, then follow unless user scrolls away
    LaunchedEffect(messages.size) {
        if (messages.isNotEmpty()) {
            val isFirstLoad = !hasScrolledToInitialPosition
            if (isFirstLoad || followIncomingMessages) {
                listState.scrollToItem(0)
                if (isFirstLoad) {
                    hasScrolledToInitialPosition = true
                }
            }
        }
    }

    // Track whether user has scrolled away from the latest messages
    val isAtLatest by remember(listState) {
        derivedStateOf {
            val firstVisibleIndex = listState.layoutInfo.visibleItemsInfo.firstOrNull()?.index ?: -1
            firstVisibleIndex <= 2
        }
    }
    LaunchedEffect(isAtLatest) {
        followIncomingMessages = isAtLatest
        onScrolledUpChanged?.invoke(!isAtLatest)
    }

    // Force scroll to bottom when requested (e.g., when user sends a message)
    LaunchedEffect(forceScrollToBottom) {
        if (messages.isNotEmpty()) {
            // With reverseLayout=true and reversed data, latest is at index 0
            followIncomingMessages = true
            listState.scrollToItem(0)
        }
    }

    // Recomputed only when the list actually gains or loses a message, and synchronously, so the
    // arriving item can read its cue during the same composition pass in which it first appears.
    // Reset per conversation, so a switch adopts the incoming messages silently instead of
    // treating a whole channel's backlog as brand-new arrivals and sliding each one in.
    val arrivalTracker = remember(conversationKey) { MessageArrivalTracker() }
    val enteringIds = remember(conversationKey, messages.size, messages.lastOrNull()?.id) {
        arrivalTracker.arrivals(messages)
    }

    // Placement animation exists to soften insertions and removals. But *any* relayout moves every
    // item — the keyboard opening behind a bottom sheet, that sheet closing again, the composer
    // growing a line — and animating those made the whole conversation lurch. So it is armed only
    // briefly around a genuine change to the list, and is otherwise off, letting items track the
    // viewport exactly.
    var placementArmed by remember(conversationKey) { mutableStateOf(false) }
    var previousMessageCount by remember(conversationKey) { mutableStateOf<Int?>(null) }
    LaunchedEffect(conversationKey, messages.size) {
        val previous = previousMessageCount
        previousMessageCount = messages.size
        // Skip the first composition: the list settling into its initial padding is not a change
        // worth animating.
        if (previous == null || previous == messages.size) return@LaunchedEffect
        placementArmed = true
        delay(PlacementArmWindowMs)
        placementArmed = false
    }

    val layoutDirection = LocalLayoutDirection.current
    LazyColumn(
        state = listState,
        // Wider side gutters than the old 12.dp: the redesign trades a little line length for
        // a much calmer edge, and long monospace lines were running into the screen bezel.
        contentPadding = PaddingValues(
            start = 16.dp + contentPadding.calculateStartPadding(layoutDirection),
            end = 16.dp + contentPadding.calculateEndPadding(layoutDirection),
            top = 8.dp + contentPadding.calculateTopPadding(),
            bottom = 12.dp + contentPadding.calculateBottomPadding()
        ),
        // Spacing is owned by each item. The exported transcript uses a consistent 8.dp rhythm;
        // a new speaker gets additional separation from the visible sender row's top inset.
        verticalArrangement = Arrangement.spacedBy(0.dp),
        modifier = modifier,
        reverseLayout = true
    ) {
        val reversed = messages.asReversed()
        itemsIndexed(
            items = reversed,
            key = { _, message -> message.id }
        ) { reversedIndex, message ->
            // reverseLayout renders index 0 at the bottom, so the chronological predecessor of
            // this row lives at a *higher* original index offset. Resolve against the original
            // list rather than the reversed view to keep the grouping logic readable.
            val originalIndex = messages.lastIndex - reversedIndex
            val previous = messages.getOrNull(originalIndex - 1)
            val isGrouped = MessageGrouping.shouldGroup(previous, message)

            // Decided once per item instance, so an item recycling back into view during a scroll
            // never re-animates. Items that are not arriving skip the animation machinery
            // entirely: no Animatable, no coroutine, and no extra render layer per row.
            val isArriving = remember(message.id) { message.id in enteringIds }
            val entryModifier = if (isArriving) {
                val entry = remember(message.id) { Animatable(0f) }
                LaunchedEffect(message.id) { entry.animateTo(1f, MessageEntrySpec) }
                // A draw-time transform only: no measure, no layout, and no recomposition of the
                // message content on any frame of the animation.
                Modifier.graphicsLayer {
                    val progress = entry.value
                    alpha = progress
                    translationY = (1f - progress) * MessageEntrySlide.toPx()
                }
            } else {
                Modifier
            }

            MessageItem(
                message = message,
                messages = messages,
                currentUserNickname = currentUserNickname,
                meshService = meshService,
                mentionPeerIdentities = resolvedMentionPeerIdentities,
                showSender = !isGrouped,
                bubbles = bubbles.isBubbles,
                topSpacing = MessageGrouping.topSpacingFor(
                    isGrouped = isGrouped,
                    isFirstInList = originalIndex == 0
                ),
                onNicknameClick = onNicknameClick,
                onMessageLongPress = onMessageLongPress,
                onCancelTransfer = onCancelTransfer,
                onImageClick = onImageClick,
                modifier = Modifier
                    // Animates the shift when a neighbour is inserted or removed: this is what
                    // makes the conversation glide up instead of jumping.
                    .animateItem(
                        // Entry fade is handled by entryModifier, together with the slide, so the
                        // two cannot drift out of step.
                        fadeInSpec = null,
                        placementSpec = if (placementArmed) MessagePlacementSpec else null,
                        fadeOutSpec = MessageFadeOutSpec
                    )
                    .then(entryModifier)
            )
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
fun MessageItem(
    message: BitchatMessage,
    currentUserNickname: String,
    meshService: MeshService,
    messages: List<BitchatMessage> = emptyList(),
    mentionPeerIdentities: Map<String, PeerIdentity> = emptyMap(),
    showSender: Boolean = true,
    bubbles: Boolean = false,
    topSpacing: Dp = 0.dp,
    onNicknameClick: ((String) -> Unit)? = null,
    onMessageLongPress: ((BitchatMessage) -> Unit)? = null,
    onCancelTransfer: ((BitchatMessage) -> Unit)? = null,
    onImageClick: ((String, List<String>, Int) -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val colorScheme = MaterialTheme.colorScheme
    val timeFormatter = remember { SimpleDateFormat(CHAT_TIMESTAMP_PATTERN, Locale.getDefault()) }

    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(top = topSpacing),
        verticalArrangement = Arrangement.spacedBy(0.dp)
    ) {
        Box(modifier = Modifier.fillMaxWidth()) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.Start,
                verticalAlignment = Alignment.Top
            ) {
                // Provide a small end padding for own private messages so overlay doesn't cover text.
                // Bubble mode draws the status beneath the bubble instead, so no inset is needed.
                val endPad = if (!bubbles && message.isPrivate && message.sender == currentUserNickname) 16.dp else 0.dp
                // Create a custom layout that combines selectable text with clickable nickname areas
                MessageTextWithClickableNicknames(
                    message = message,
                    messages = messages,
                    currentUserNickname = currentUserNickname,
                    meshService = meshService,
                    mentionPeerIdentities = mentionPeerIdentities,
                    colorScheme = colorScheme,
                    timeFormatter = timeFormatter,
                    showSender = showSender,
                    bubbles = bubbles,
                    onNicknameClick = onNicknameClick,
                    onMessageLongPress = onMessageLongPress,
                    onCancelTransfer = onCancelTransfer,
                    onImageClick = onImageClick,
                    modifier = Modifier
                        .weight(1f)
                        .padding(end = endPad)
                )
            }

            // Delivery status for private messages (overlay, non-displacing). Bubble mode aligns
            // own messages to the end edge where this overlay lives, so it renders below instead.
            if (!bubbles && message.isPrivate && message.sender == currentUserNickname) {
                message.deliveryStatus?.let { status ->
                    Box(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(top = 2.dp)
                    ) {
                        DeliveryStatusIcon(status = status)
                    }
                }
            }
        }

        // Bubble mode: text and media bubbles carry the marker inline, trailing the timestamp.
        // File rows have no bubble shell, so their marker stays beneath the end-aligned row.
        if (bubbles && message.type == BitchatMessageType.File &&
            message.isPrivate && message.sender == currentUserNickname
        ) {
            message.deliveryStatus?.let { status ->
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 2.dp, end = 4.dp),
                    contentAlignment = Alignment.CenterEnd
                ) {
                    DeliveryStatusIcon(status = status)
                }
            }
        }

        // Link previews removed; links are now highlighted inline and clickable within the message text
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
    private fun MessageTextWithClickableNicknames(
        message: BitchatMessage,
        messages: List<BitchatMessage>,
        currentUserNickname: String,
        meshService: MeshService,
        mentionPeerIdentities: Map<String, PeerIdentity>,
        colorScheme: ColorScheme,
        timeFormatter: SimpleDateFormat,
        showSender: Boolean,
        bubbles: Boolean = false,
        onNicknameClick: ((String) -> Unit)?,
        onMessageLongPress: ((BitchatMessage) -> Unit)?,
        onCancelTransfer: ((BitchatMessage) -> Unit)?,
        onImageClick: ((String, List<String>, Int) -> Unit)?,
        modifier: Modifier = Modifier
    ) {
    val palette = LocalBitchatPalette.current

    // Image special rendering
    if (message.type == BitchatMessageType.Image) {
        com.bitchat.android.ui.media.ImageMessageItem(
            message = message,
            messages = messages,
            currentUserNickname = currentUserNickname,
            meshService = meshService,
            colorScheme = colorScheme,
            timeFormatter = timeFormatter,
            showSender = showSender,
            bubbles = bubbles,
            onNicknameClick = onNicknameClick,
            onMessageLongPress = onMessageLongPress,
            onCancelTransfer = onCancelTransfer,
            onImageClick = onImageClick,
            modifier = modifier
        )
        return
    }

    // Voice note special rendering
    if (message.type == BitchatMessageType.Audio) {
        com.bitchat.android.ui.media.AudioMessageItem(
            message = message,
            currentUserNickname = currentUserNickname,
            meshService = meshService,
            colorScheme = colorScheme,
            timeFormatter = timeFormatter,
            showSender = showSender,
            bubbles = bubbles,
            onNicknameClick = onNicknameClick,
            onMessageLongPress = onMessageLongPress,
            onCancelTransfer = onCancelTransfer,
            modifier = modifier
        )
        return
    }

    // File special rendering
    if (message.type == BitchatMessageType.File) {
        val path = message.content.trim()
        // Derive sending progress if applicable
        val (overrideProgress, _) = when (val st = message.deliveryStatus) {
            is com.bitchat.android.model.DeliveryStatus.PartiallyDelivered -> {
                if (st.total > 0 && st.reached < st.total) {
                    (st.reached.toFloat() / st.total.toFloat()) to Color(0xFF1E88E5) // blue while sending
                } else null to null
            }
            else -> null to null
        }
        Column(
            modifier = modifier.fillMaxWidth(),
            // Bubble mode aligns self-authored file rows to the end side, mirroring text bubbles.
            horizontalAlignment = if (bubbles && message.isFromSelf(currentUserNickname, meshService.myPeerID)) {
                Alignment.End
            } else {
                Alignment.Start
            },
        ) {
            // Header: nickname + timestamp line above the file, identical styling to text messages
            val headerText = formatMessageHeaderAnnotatedString(
                message = message,
                currentUserNickname = currentUserNickname,
                myPeerID = meshService.myPeerID,
                palette = palette,
                contentColor = colorScheme.onSurface,
                timeFormatter = timeFormatter,
                includeSender = showSender
            )
            val haptic = LocalHapticFeedback.current
            AnnotatedClickableText(
                text = headerText,
                annotationTags = listOf("nickname_click"),
                onAnnotationClick = { tag, item ->
                    if (tag == "nickname_click" && onNicknameClick != null) {
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                        onNicknameClick.invoke(item)
                        true
                    } else {
                        false
                    }
                },
                onLongPress = { onMessageLongPress?.invoke(message) },
                fontFamily = BitchatFontFamily,
                color = colorScheme.onSurface,
            )

            // Try to load the file packet from the path
            val packet = try {
                val file = java.io.File(path)
                if (file.exists()) {
                    // Create a temporary BitchatFilePacket for display
                    // In a real implementation, this would be stored with the packet metadata
                    com.bitchat.android.model.BitchatFilePacket(
                        fileName = file.name,
                        fileSize = file.length(),
                        mimeType = com.bitchat.android.features.file.FileUtils.getMimeTypeFromExtension(file.name),
                        content = file.readBytes()
                    )
                } else null
            } catch (e: Exception) {
                null
            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = if (bubbles && message.isFromSelf(currentUserNickname, meshService.myPeerID)) {
                    Arrangement.End
                } else {
                    Arrangement.Start
                }
            ) {
                Box {
                    if (packet != null) {
                        if (overrideProgress != null) {
                            // Show sending animation while in-flight
                            com.bitchat.android.ui.media.FileSendingAnimation(
                                fileName = packet.fileName,
                                progress = overrideProgress,
                                modifier = Modifier.fillMaxWidth()
                            )
                        } else {
                            // Static file display with open/save dialog
                            FileMessageItem(
                                packet = packet,
                                onFileClick = {
                                    // handled inside FileMessageItem via dialog
                                }
                            )
                        }

                        // Cancel button overlay during sending
                        val showCancel = message.sender == currentUserNickname && (message.deliveryStatus is DeliveryStatus.PartiallyDelivered)
                        if (showCancel) {
                            Box(
                                modifier = Modifier
                                    .align(Alignment.TopEnd)
                                    .padding(4.dp)
                                    .size(22.dp)
                                    .background(colorScheme.surfaceVariant.copy(alpha = 0.85f), CircleShape)
                                    .clickable { onCancelTransfer?.invoke(message) },
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Close,
                                    contentDescription = stringResource(R.string.cd_cancel),
                                    tint = colorScheme.onSurface,
                                    modifier = Modifier.size(14.dp)
                                )
                            }
                        }
                    } else {
                        Text(
                            text = stringResource(R.string.file_unavailable),
                            fontFamily = BitchatFontFamily,
                            color = palette.textTertiary
                        )
                    }
                }
            }
        }
        return
    }

    val cashuTokens = remember(message.content) {
        CashuTokenDecoder.extractTokens(message.content)
    }
    if (cashuTokens.isNotEmpty() && message.sender != "system") {
        CashuMessageContent(
            message = message,
            tokens = cashuTokens,
            currentUserNickname = currentUserNickname,
            meshService = meshService,
            colorScheme = colorScheme,
            timeFormatter = timeFormatter,
            bubbles = bubbles,
            onNicknameClick = onNicknameClick,
            onMessageLongPress = onMessageLongPress,
            modifier = modifier
        )
        return
    }

    if (message.sender == "system") {
        // Background narration: `// Tor started. Routing all chats…`
        val annotatedText = remember(message, colorScheme.onSurface) {
            formatSystemMessage(
                message = message,
                contentColor = colorScheme.onSurface,
                timeFormatter = timeFormatter
            )
        }

        val haptic = LocalHapticFeedback.current
        Text(
            text = annotatedText,
            modifier = modifier.pointerInput(message) {
                detectTapGestures(
                    onLongPress = {
                        haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                        onMessageLongPress?.invoke(message)
                    }
                )
            },
            fontFamily = BitchatFontFamily,
            softWrap = true,
            overflow = TextOverflow.Visible,
            style = ChatVisualTokens.SystemActionStyle.copy(
                color = colorScheme.onSurface.copy(alpha = ChatVisualTokens.MutedTextAlpha),
            )
        )
    } else {
        TextMessageLayout(
            message = message,
            currentUserNickname = currentUserNickname,
            meshService = meshService,
            mentionPeerIdentities = mentionPeerIdentities,
            colorScheme = colorScheme,
            timeFormatter = timeFormatter,
            showSender = showSender,
            bubbles = bubbles,
            onNicknameClick = onNicknameClick,
            onMessageLongPress = onMessageLongPress,
            modifier = modifier,
        )
    }
}

@Composable
internal fun TextMessageLayout(
    message: BitchatMessage,
    currentUserNickname: String,
    meshService: MeshService,
    mentionPeerIdentities: Map<String, PeerIdentity> = emptyMap(),
    colorScheme: ColorScheme,
    timeFormatter: SimpleDateFormat,
    onNicknameClick: ((String) -> Unit)?,
    onMessageLongPress: ((BitchatMessage) -> Unit)?,
    modifier: Modifier = Modifier,
    showSender: Boolean = true,
    bubbles: Boolean = false,
    bodyContent: String = message.content,
) {
    val palette = LocalBitchatPalette.current
    val myPeerId = meshService.myPeerID
    val displayMessage = remember(message, bodyContent) {
        if (bodyContent == message.content) message else message.copy(content = bodyContent)
    }
    val senderText = remember(message, currentUserNickname, myPeerId, palette) {
        formatTextMessageSender(
            message = message,
            currentUserNickname = currentUserNickname,
            myPeerID = myPeerId,
            palette = palette,
        )
    }
    val isSelf = message.isFromSelf(currentUserNickname, myPeerId)
    val haptic = LocalHapticFeedback.current
    val context = LocalContext.current
    val handleLongPress: () -> Unit = {
        haptic.performHapticFeedback(HapticFeedbackType.LongPress)
        onMessageLongPress?.invoke(message)
    }

    // The timestamp trails the body rather than occupying its own column, so a short message
    // no longer reserves a full-width row for eight grey characters. Self bubbles leave the
    // timestamp to their meta cluster (see BubbleTextMessageLayout).
    val bodyText = remember(
        displayMessage,
        currentUserNickname,
        palette,
        colorScheme.onSurface,
        colorScheme.secondary,
        mentionPeerIdentities,
        timeFormatter,
        bubbles,
        isSelf
    ) {
        formatTextMessageBody(
            message = displayMessage,
            currentUserNickname = currentUserNickname,
            palette = palette,
            contentColor = colorScheme.onSurface,
            linkColor = colorScheme.secondary,
            mentionPeerIdentities = mentionPeerIdentities,
            timeFormatter = timeFormatter,
            includeTimestamp = !bubbles || !isSelf,
        )
    }

    if (bubbles) {
        BubbleTextMessageLayout(
            message = message,
            senderText = senderText,
            bodyText = bodyText,
            isSelf = isSelf,
            showSender = showSender,
            timeFormatter = timeFormatter,
            onNicknameClick = onNicknameClick,
            onLongPress = handleLongPress,
            modifier = modifier,
        )
        return
    }

    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(MessageGrouping.SENDER_TO_BODY_SPACING),
    ) {
        if (showSender) {
            AnnotatedClickableText(
                text = senderText,
                annotationTags = listOf("nickname_click"),
                onAnnotationClick = { tag, item ->
                    if (tag == "nickname_click" && !isSelf && onNicknameClick != null) {
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                        onNicknameClick.invoke(item)
                        true
                    } else {
                        false
                    }
                },
                onLongPress = handleLongPress,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = MessageGrouping.SENDER_TOP_PADDING),
                fontFamily = BitchatFontFamily,
                softWrap = false,
                overflow = TextOverflow.Ellipsis,
                style = MessageSenderTextStyle,
            )
        }

        AnnotatedClickableText(
            text = bodyText,
            annotationTags = listOf("geohash_click", "url_click"),
            onAnnotationClick = { tag, item ->
                when (tag) {
                    "geohash_click" -> {
                        navigateToGeohash(context, item)
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                        true
                    }

                    "url_click" -> {
                        openMessageUrl(context, item)
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                        true
                    }

                    else -> false
                }
            },
            onLongPress = handleLongPress,
            fontFamily = BitchatFontFamily,
            softWrap = true,
            overflow = TextOverflow.Visible,
            style = MessageBodyTextStyle.copy(color = colorScheme.onSurface),
        )
    }
}

/**
 * Classic messenger rendering of a text message: a rounded bubble that hugs its content, own
 * messages on the right and everyone else on the left, with the corner on the speaker's side
 * tightened into a subtle tail.
 *
 * The bubble is washed with the author's stable peer colour — the same identity-derived colour
 * the `@name` label and mention chips already use — so the speaker stays identifiable at a
 * glance without touching any surface, background, or theme colour. Body text keeps the
 * standard `onSurface` tone; only the bubble shell carries the identity.
 */
@Composable
private fun BubbleTextMessageLayout(
    message: BitchatMessage,
    senderText: AnnotatedString,
    bodyText: AnnotatedString,
    isSelf: Boolean,
    showSender: Boolean,
    timeFormatter: SimpleDateFormat,
    onNicknameClick: ((String) -> Unit)?,
    onLongPress: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val palette = LocalBitchatPalette.current
    val haptic = LocalHapticFeedback.current
    val context = LocalContext.current

    val authorColor = remember(message, isSelf, palette) {
        if (isSelf) palette.accentOrange else colorForPeer(peerIdentityForMessage(message), palette)
    }

    val corner = ChatVisualTokens.BubbleCornerRadius
    val tail = ChatVisualTokens.BubbleTailRadius
    val bubbleShape = if (isSelf) {
        RoundedCornerShape(topStart = corner, topEnd = corner, bottomEnd = tail, bottomStart = corner)
    } else {
        RoundedCornerShape(topStart = corner, topEnd = corner, bottomEnd = corner, bottomStart = tail)
    }

    Column(
        modifier = modifier.fillMaxWidth(),
        horizontalAlignment = if (isSelf) Alignment.End else Alignment.Start,
    ) {
        // Cap the bubble at a fraction of the row so long messages wrap instead of touching the
        // opposite edge, while short ones hug their content.
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val maxBubbleWidth = maxWidth * ChatVisualTokens.BubbleMaxWidthFraction
            val density = LocalDensity.current
            val textCapPx = with(density) {
                (maxBubbleWidth - ChatVisualTokens.BubblePaddingHorizontal * 2 - 2.dp).toPx()
            }
            var bodyLayout by remember { mutableStateOf<TextLayoutResult?>(null) }
            var clusterSize by remember { mutableStateOf(IntSize.Zero) }

            // The meta cluster (timestamp, then delivery checks for own private messages) rides
            // flush-right on the body's last line when that line has room for it, and drops
            // below the text only when it does not. Placement is computed from the laid-out
            // text, so wrapping is never influenced by the cluster: no early wraps, no slack
            // carved out of the first lines, no minimum bubble width.
            val metaGapPx = with(density) { 8.dp.toPx() }
            val metaPlan = remember(bodyLayout, clusterSize, textCapPx) {
                val layout = bodyLayout ?: return@remember null
                if (layout.lineCount == 0 || clusterSize.width <= 0) return@remember null
                val lastLineRight = layout.getLineRight(layout.lineCount - 1)
                if (lastLineRight + metaGapPx + clusterSize.width <= textCapPx) {
                    BubbleMetaPlan(
                        widthPx = maxOf(layout.size.width.toFloat(), lastLineRight + metaGapPx + clusterSize.width),
                        reserveOwnLine = false,
                    )
                } else {
                    BubbleMetaPlan(
                        widthPx = maxOf(layout.size.width.toFloat(), clusterSize.width.toFloat()),
                        reserveOwnLine = true,
                    )
                }
            }

            Box(
                modifier = Modifier
                    .align(if (isSelf) Alignment.CenterEnd else Alignment.CenterStart)
                    .widthIn(max = maxBubbleWidth)
                    .border(
                        width = 1.dp,
                        color = authorColor.copy(alpha = ChatVisualTokens.BubbleBorderAlpha),
                        shape = bubbleShape
                    )
                    .background(
                        color = authorColor.copy(alpha = ChatVisualTokens.BubbleBackgroundAlpha),
                        shape = bubbleShape
                    )
                    .padding(
                        horizontal = ChatVisualTokens.BubblePaddingHorizontal,
                        vertical = ChatVisualTokens.BubblePaddingVertical,
                    )
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    // The sender's name heads the first bubble of their run, like classic group
                    // messengers, instead of floating above it. Own bubbles never show a name —
                    // the end side is attribution enough. Continuation bubbles skip it too.
                    if (showSender && !isSelf) {
                        AnnotatedClickableText(
                            text = senderText,
                            annotationTags = listOf("nickname_click"),
                            onAnnotationClick = { tag, item ->
                                if (tag == "nickname_click" && !isSelf && onNicknameClick != null) {
                                    haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                    onNicknameClick.invoke(item)
                                    true
                                } else {
                                    false
                                }
                            },
                            onLongPress = onLongPress,
                            fontFamily = BitchatFontFamily,
                            softWrap = false,
                            overflow = TextOverflow.Ellipsis,
                            style = MessageSenderTextStyle,
                        )
                    }

                    Box(
                        modifier = if (isSelf && metaPlan != null) {
                            Modifier.width(with(density) { metaPlan!!.widthPx.toDp() })
                        } else {
                            Modifier
                        }
                    ) {
                        AnnotatedClickableText(
                            text = bodyText,
                            annotationTags = listOf("geohash_click", "url_click"),
                            onAnnotationClick = { tag, item ->
                                when (tag) {
                                    "geohash_click" -> {
                                        navigateToGeohash(context, item)
                                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                        true
                                    }

                                    "url_click" -> {
                                        openMessageUrl(context, item)
                                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                        true
                                    }

                                    else -> false
                                }
                            },
                            onLongPress = onLongPress,
                            modifier = Modifier.padding(
                                bottom = if (metaPlan?.reserveOwnLine == true) {
                                    with(density) { clusterSize.height.toDp() }
                                } else {
                                    0.dp
                                }
                            ),
                            fontFamily = BitchatFontFamily,
                            softWrap = true,
                            overflow = TextOverflow.Visible,
                            style = MessageBodyTextStyle.copy(color = MaterialTheme.colorScheme.onSurface),
                            onTextLayout = { bodyLayout = it },
                        )

                        if (isSelf) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier
                                    .align(Alignment.BottomEnd)
                                    .onSizeChanged { clusterSize = it }
                                    .graphicsLayer { alpha = if (metaPlan != null) 1f else 0f },
                            ) {
                                Text(
                                    text = formatTextMessageMetadata(message, timeFormatter),
                                    fontFamily = BitchatFontFamily,
                                )
                                if (message.isPrivate) {
                                    message.deliveryStatus?.let { status ->
                                        Spacer(Modifier.width(4.dp))
                                        DeliveryStatusIcon(status = status)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

private data class BubbleMetaPlan(
    val widthPx: Float,
    val reserveOwnLine: Boolean,
)

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun CashuMessageContent(
    message: BitchatMessage,
    tokens: List<String>,
    currentUserNickname: String,
    meshService: MeshService,
    colorScheme: ColorScheme,
    timeFormatter: SimpleDateFormat,
    bubbles: Boolean = false,
    onNicknameClick: ((String) -> Unit)?,
    onMessageLongPress: ((BitchatMessage) -> Unit)?,
    modifier: Modifier = Modifier
) {
    val remainingText = tokens.fold(message.content) { text, token ->
        text.replace("cashu://$token", "", ignoreCase = true)
            .replace("cashu:$token", "", ignoreCase = true)
            .replace(token, "")
    }.trim()
    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        TextMessageLayout(
            message = message,
            currentUserNickname = currentUserNickname,
            meshService = meshService,
            colorScheme = colorScheme,
            timeFormatter = timeFormatter,
            bubbles = bubbles,
            onNicknameClick = onNicknameClick,
            onMessageLongPress = onMessageLongPress,
            bodyContent = remainingText,
        )
        tokens.forEach { token -> CashuPaymentChip(token) }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
internal fun CashuPaymentChip(
    token: String,
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null,
    showActions: Boolean = true,
) {
    val context = LocalContext.current
    val info = remember(token) { CashuTokenDecoder.decode(token) }
    val primaryLabel = listOfNotNull(info?.displayAmount, info?.mintHost)
        .joinToString(" · ")
        .ifEmpty { stringResource(R.string.cashu_pay_via) }
    var showMenu by remember { mutableStateOf(false) }

    Box {
        Row(
            modifier = modifier
                .border(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.25f), RoundedCornerShape(12.dp))
                .background(
                    MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.45f),
                    RoundedCornerShape(12.dp)
                )
                .combinedClickable(
                    onClick = onClick ?: { redeemCashu(context, token, preferWallet = true) },
                    onLongClick = if (showActions) {
                        { showMenu = true }
                    } else {
                        null
                    }
                )
                .semantics {
                    contentDescription = buildString {
                        append(context.getString(R.string.cashu_payment_description))
                        append(": ")
                        append(primaryLabel)
                        info?.memo?.let { append(", $it") }
                    }
                }
                .heightIn(min = 48.dp)
                .padding(horizontal = 12.dp, vertical = 6.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text("🥜")
            Column {
                Text(
                    primaryLabel,
                    style = MaterialTheme.typography.labelLarge,
                    color = MaterialTheme.colorScheme.onSecondaryContainer
                )
                info?.memo?.let {
                    Text(
                        it,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSecondaryContainer.copy(alpha = 0.7f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }
        }
        DropdownMenu(
            expanded = showActions && showMenu,
            onDismissRequest = { showMenu = false }
        ) {
            DropdownMenuItem(
                text = { Text(stringResource(R.string.cashu_copy_token)) },
                onClick = {
                    val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
                    clipboard.setPrimaryClip(ClipData.newPlainText("Cashu token", token))
                    showMenu = false
                }
            )
            DropdownMenuItem(
                text = { Text(stringResource(R.string.cashu_redeem_wallet)) },
                onClick = {
                    showMenu = false
                    redeemCashu(context, token, preferWallet = true)
                }
            )
            DropdownMenuItem(
                text = { Text(stringResource(R.string.cashu_redeem_web)) },
                onClick = {
                    showMenu = false
                    redeemCashu(context, token, preferWallet = false)
                }
            )
        }
    }
}

private fun redeemCashu(context: Context, token: String, preferWallet: Boolean) {
    val wallet = CashuTokenDecoder.walletUri(token)
    val web = CashuTokenDecoder.webRedeemUri(token) ?: return
    if (preferWallet && wallet != null) {
        val walletIntent = Intent(Intent.ACTION_VIEW, Uri.parse(wallet))
        try {
            context.startActivity(walletIntent)
            return
        } catch (_: ActivityNotFoundException) {
            // No wallet registered for cashu:, so use the explicit web fallback.
        }
    }
    runCatching { context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(web))) }
}

/**
 * Per-check target colours for the delivery marker.
 *
 * Both checks always render — grey (disabled) until an acknowledgement turns them on — so a
 * status change recolours in place and never reflows text around it. Read receipts use the
 * app's primary green rather than a separate accent. [status] == null yields the all-grey
 * baseline used while a message is still being sent.
 */
private fun deliveryCheckColors(status: DeliveryStatus?, colorScheme: ColorScheme): Pair<Color, Color> {
    val grey = colorScheme.onSurface.copy(alpha = 0.35f)
    val green = colorScheme.primary
    return when (status) {
        is DeliveryStatus.Read -> green to green
        is DeliveryStatus.Delivered -> green to grey
        is DeliveryStatus.PartiallyDelivered -> green to grey
        is DeliveryStatus.Failed -> colorScheme.error to colorScheme.error
        else -> grey to grey
    }
}

/** Acknowledgement progress ordering, used to fire the pop only when the state advances. */
private fun deliveryCheckRank(status: DeliveryStatus): Int = when (status) {
    is DeliveryStatus.Read -> 3
    is DeliveryStatus.Delivered -> 2
    is DeliveryStatus.PartiallyDelivered -> 2
    is DeliveryStatus.Failed -> 1
    else -> 0
}

@Composable
fun DeliveryStatusIcon(status: DeliveryStatus) {
    val colorScheme = MaterialTheme.colorScheme
    val (firstTarget, secondTarget) = deliveryCheckColors(status, colorScheme)
    val first by animateColorAsState(
        targetValue = firstTarget,
        animationSpec = tween(BitchatMotion.QUICK_MS),
        label = "firstCheckColor",
    )
    val second by animateColorAsState(
        targetValue = secondTarget,
        animationSpec = tween(BitchatMotion.QUICK_MS),
        label = "secondCheckColor",
    )

    // Snappy micro pop when the state advances to (more) acknowledged. Keyed on the rank, not
    // the instance, because Delivered/Read carry timestamps that would retrigger it otherwise.
    val scale = remember { Animatable(1f) }
    LaunchedEffect(deliveryCheckRank(status)) {
        if (deliveryCheckRank(status) >= 2) {
            scale.snapTo(1.3f)
            scale.animateTo(1f, spring(dampingRatio = 0.55f, stiffness = 900f))
        }
    }

    val text = remember(first, second) {
        androidx.compose.ui.text.buildAnnotatedString {
            pushStyle(androidx.compose.ui.text.SpanStyle(color = first))
            append("✓")
            pop()
            pushStyle(androidx.compose.ui.text.SpanStyle(color = second))
            append("✓")
            pop()
        }
    }
    Text(
        text = text,
        fontSize = 10.sp,
        fontWeight = FontWeight.Normal,
        modifier = Modifier.graphicsLayer {
            scaleX = scale.value
            scaleY = scale.value
        }
    )
}

package com.bitchat.android.ui

import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.ui.theme.ChatVisualTokens

/**
 * Consecutive-message grouping for the chat surface.
 *
 * The redesign suppresses the `@sender` label on runs of messages from the same author so the
 * eye only has to register a name when the speaker actually changes. The transcript uses one
 * consistent item rhythm; new groups get their additional separation from the visible sender
 * row's own top padding.
 */
object MessageGrouping {

    /** Space above the first message of a group (i.e. one that renders its sender label). */
    val NEW_GROUP_SPACING: Dp = ChatVisualTokens.MessageItemSpacing

    /** Space above a continuation message inside an existing group. */
    val GROUPED_SPACING: Dp = ChatVisualTokens.MessageItemSpacing

    /** Gap between the sender label and the first line of the body. */
    val SENDER_TO_BODY_SPACING: Dp = ChatVisualTokens.SenderToBodySpacing

    /** Top inset inside a visible sender row. */
    val SENDER_TOP_PADDING: Dp = ChatVisualTokens.SenderTopPadding

    /**
     * Messages further apart than this always start a new group, even from the same sender:
     * a reply an hour later is a new thought, not a continuation.
     */
    const val GROUPING_WINDOW_MS: Long = 5 * 60 * 1000L

    private const val SYSTEM_SENDER = "system"

    /**
     * Whether [current] should be rendered as a continuation of [previous], hiding its sender
     * label.
     *
     * [previous] is the message immediately *before* [current] in chronological order. Note the
     * message list renders with `reverseLayout = true`, so callers must be careful to resolve
     * the chronological predecessor rather than the visually preceding item.
     */
    fun shouldGroup(previous: BitchatMessage?, current: BitchatMessage): Boolean {
        if (previous == null) return false

        // System/action lines never participate in grouping in either direction: they are
        // narration, and folding a real message into them would attribute it to "system".
        if (previous.sender == SYSTEM_SENDER || current.sender == SYSTEM_SENDER) return false

        // Never group across the public/private boundary or between different channels.
        if (previous.isPrivate != current.isPrivate) return false
        if (previous.channel != current.channel) return false

        if (!isSameSender(previous, current)) return false

        val elapsed = current.timestamp.time - previous.timestamp.time
        return elapsed in 0..GROUPING_WINDOW_MS
    }

    /**
     * Identity comparison. Peer IDs are authoritative when both messages carry one, because two
     * different peers can share a nickname. Falls back to the display name (which includes the
     * `#abcd` suffix) when peer IDs are unavailable, e.g. for locally injected messages.
     */
    private fun isSameSender(previous: BitchatMessage, current: BitchatMessage): Boolean {
        val previousPeerID = previous.senderPeerID
        val currentPeerID = current.senderPeerID
        return if (previousPeerID != null && currentPeerID != null) {
            previousPeerID.equals(currentPeerID, ignoreCase = true)
        } else {
            previous.sender == current.sender
        }
    }

    /** Top padding for a message given whether it continues the previous author's run. */
    fun topSpacingFor(isGrouped: Boolean, isFirstInList: Boolean): Dp = when {
        isFirstInList -> 0.dp
        isGrouped -> GROUPED_SPACING
        else -> NEW_GROUP_SPACING
    }
}

package com.bitchat.android.ui

import android.content.Context
import android.content.Intent
import androidx.core.net.toUri
import com.bitchat.android.geohash.GeohashChannel
import com.bitchat.android.geohash.GeohashChannelLevel
import com.bitchat.android.geohash.LocationChannelManager
import com.bitchat.android.model.BitchatMessage

internal fun BitchatMessage.isFromSelf(
    currentUserNickname: String,
    myPeerId: String,
): Boolean =
    senderPeerID == myPeerId ||
        sender == currentUserNickname ||
        sender.startsWith("$currentUserNickname#")

internal fun normalizeMessageUrl(rawUrl: String): String =
    if (
        rawUrl.startsWith("http://", ignoreCase = true) ||
        rawUrl.startsWith("https://", ignoreCase = true)
    ) {
        rawUrl
    } else {
        "https://$rawUrl"
    }

internal fun openMessageUrl(context: Context, rawUrl: String): Boolean =
    runCatching {
        val intent = Intent(Intent.ACTION_VIEW, normalizeMessageUrl(rawUrl).toUri())
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        context.startActivity(intent)
    }.isSuccess

internal fun channelForGeohash(geohash: String): GeohashChannel {
    val level = when (geohash.length) {
        in 0..2 -> GeohashChannelLevel.REGION
        in 3..4 -> GeohashChannelLevel.PROVINCE
        5 -> GeohashChannelLevel.CITY
        6 -> GeohashChannelLevel.NEIGHBORHOOD
        else -> GeohashChannelLevel.BLOCK
    }
    return GeohashChannel(level, geohash.lowercase())
}

internal fun navigateToGeohash(context: Context, geohash: String): Boolean =
    runCatching {
        val locationManager = LocationChannelManager.getInstance(context)
        locationManager.selectManual(channelForGeohash(geohash))
    }.isSuccess

package com.bitchat.android.ui

import com.bitchat.android.model.BitchatMessage
import com.bitchat.android.model.DeliveryStatus
import com.bitchat.android.services.ContactDirectory
import java.util.*
import java.util.Collections

/**
 * Handles all message-related operations including deduplication and organization
 */
class MessageManager(private val state: ChatState) {

    // Message deduplication for duplicate deliveries from multiple local transports.
    private val processedUIMessages = Collections.synchronizedSet(mutableSetOf<String>())
    private val recentSystemEvents = Collections.synchronizedMap(mutableMapOf<String, Long>())
    private val MESSAGE_DEDUP_TIMEOUT = com.bitchat.android.util.AppConstants.UI.MESSAGE_DEDUP_TIMEOUT_MS // 30 seconds
    private val SYSTEM_EVENT_DEDUP_TIMEOUT = com.bitchat.android.util.AppConstants.UI.SYSTEM_EVENT_DEDUP_TIMEOUT_MS // 5 seconds

    // MARK: - Public Message Management

    fun addMessage(message: BitchatMessage) {
        val currentMessages = state.getMessagesValue().toMutableList()
        currentMessages.add(message)
        state.setMessages(currentMessages)
        // Reflect into process-wide store so snapshot replacements don't drop local outgoing messages
        try { com.bitchat.android.services.AppStateStore.addPublicMessage(message) } catch (_: Exception) { }
    }

    // Log a system message into the main chat (visible to user)
    fun addSystemMessage(text: String) {
        val sys = BitchatMessage(
            sender = "system",
            content = text,
            timestamp = Date(),
            isRelay = false
        )
        addMessage(sys)
    }

    fun clearMessages() {
        state.setMessages(emptyList())
        state.setChannelMessages(emptyMap())
    }

    // MARK: - Channel Message Management

    fun addChannelMessage(channel: String, message: BitchatMessage) {
        val currentChannelMessages = state.getChannelMessagesValue().toMutableMap()
        if (!currentChannelMessages.containsKey(channel)) {
            currentChannelMessages[channel] = mutableListOf()
        }

        val channelMessageList = currentChannelMessages[channel]?.toMutableList() ?: mutableListOf()
        channelMessageList.add(message)
        currentChannelMessages[channel] = channelMessageList
        state.setChannelMessages(currentChannelMessages)
        // Reflect into process-wide store
        try { com.bitchat.android.services.AppStateStore.addChannelMessage(channel, message) } catch (_: Exception) { }

        // Update unread count if not currently viewing this channel
        // Consider both classic channels (state.currentChannel) and geohash location channel selection
        val viewingClassicChannel = state.getCurrentChannelValue() == channel
        val viewingGeohashChannel = try {
            if (channel.startsWith("geo:")) {
                val geo = channel.removePrefix("geo:")
                val selected = state.selectedLocationChannel.value
                selected is com.bitchat.android.geohash.ChannelID.Location && selected.channel.geohash.equals(geo, ignoreCase = true)
            } else false
        } catch (_: Exception) { false }

        if (!viewingClassicChannel && !viewingGeohashChannel) {
            val currentUnread = state.getUnreadChannelMessagesValue().toMutableMap()
            currentUnread[channel] = (currentUnread[channel] ?: 0) + 1
            state.setUnreadChannelMessages(currentUnread)
        }
    }

    fun clearChannelMessages(channel: String) {
        val updatedChannelMessages = state.getChannelMessagesValue().toMutableMap()
        updatedChannelMessages[channel] = emptyList()
        state.setChannelMessages(updatedChannelMessages)
    }

    fun removeChannelMessages(channel: String) {
        val updatedChannelMessages = state.getChannelMessagesValue().toMutableMap()
        updatedChannelMessages.remove(channel)
        state.setChannelMessages(updatedChannelMessages)

        val updatedUnread = state.getUnreadChannelMessagesValue().toMutableMap()
        updatedUnread.remove(channel)
        state.setUnreadChannelMessages(updatedUnread)
    }

    fun clearChannelUnreadCount(channel: String) {
        val currentUnread = state.getUnreadChannelMessagesValue().toMutableMap()
        currentUnread.remove(channel)
        state.setUnreadChannelMessages(currentUnread)
    }

    // MARK: - Private Message Management

    fun addPrivateMessage(peerID: String, message: BitchatMessage) {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val accepted = try {
            com.bitchat.android.services.AppStateStore.addPrivateMessage(
                conversationID,
                message
            )
        } catch (_: Exception) {
            false
        }
        if (!accepted) return
        publishAcceptedPrivateMessage(conversationID, message, forceRead = false)
    }

    /**
     * Adds a private message only after its database transaction has completed.
     *
     * Outgoing sends and non-mesh transports use this path so the local echo is never shown or
     * transmitted unless it can survive an immediate process death.
     */
    suspend fun addPrivateMessageDurably(
        peerID: String,
        message: BitchatMessage,
        forceRead: Boolean = false
    ): Boolean {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val accepted = try {
            com.bitchat.android.services.AppStateStore.addPrivateMessageDurably(
                peerID = conversationID,
                msg = message,
                forceRead = forceRead
            )
        } catch (_: Exception) {
            false
        }
        if (!accepted) return false
        publishAcceptedPrivateMessage(conversationID, message, forceRead)
        return true
    }

    private fun publishAcceptedPrivateMessage(
        conversationID: String,
        message: BitchatMessage,
        forceRead: Boolean
    ) {
        val currentPrivateChats = state.getPrivateChatsValue().toMutableMap()
        if (!currentPrivateChats.containsKey(conversationID)) {
            currentPrivateChats[conversationID] = mutableListOf()
        }

        val chatMessages = currentPrivateChats[conversationID]?.toMutableList() ?: mutableListOf()
        chatMessages.add(message)
        currentPrivateChats[conversationID] = chatMessages
        state.setPrivateChats(ContactDirectory.canonicalizePrivateChats(currentPrivateChats))

        // Mark as unread if not currently viewing this chat
        val selectedConversationID = state.getSelectedPrivateChatPeerValue()
            ?.let(ContactDirectory::canonicalConversationId)
        if (
            !forceRead &&
            selectedConversationID != conversationID &&
            message.sender != state.getNicknameValue()
        ) {
            val currentUnread = state.getUnreadPrivateMessagesValue().toMutableSet()
            currentUnread.add(conversationID)
            state.setUnreadPrivateMessages(currentUnread)
        }
    }

    // Variant that does not mark unread (used when we know the message has been read already, e.g., persisted Nostr read store)
    fun addPrivateMessageNoUnread(peerID: String, message: BitchatMessage) {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val accepted = try {
            com.bitchat.android.services.AppStateStore.addPrivateMessage(
                peerID = conversationID,
                msg = message,
                forceRead = true
            )
        } catch (_: Exception) {
            false
        }
        if (!accepted) return
        publishAcceptedPrivateMessage(conversationID, message, forceRead = true)
    }

    fun clearPrivateMessages(peerID: String) {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        com.bitchat.android.services.AppStateStore.deletePrivateConversation(conversationID)
        val updatedChats = state.getPrivateChatsValue().toMutableMap()
        updatedChats.keys.removeAll { key ->
            ContactDirectory.canonicalConversationId(key)
                .equals(conversationID, ignoreCase = true)
        }
        state.setPrivateChats(updatedChats)
        clearPrivateUnreadMessages(conversationID)
    }

    fun initializePrivateChat(peerID: String) {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        if (state.getPrivateChatsValue().containsKey(conversationID)) return

        val updatedChats = state.getPrivateChatsValue().toMutableMap()
        updatedChats[conversationID] = emptyList()
        state.setPrivateChats(updatedChats)
    }

    fun clearPrivateUnreadMessages(
        peerID: String,
        aliases: Set<String> = emptySet()
    ) {
        val conversationID = ContactDirectory.canonicalConversationId(peerID)
        val updatedUnread = state.getUnreadPrivateMessagesValue().toMutableSet()
        val normalizedAliases = (aliases + peerID + conversationID)
            .mapTo(mutableSetOf()) { it.lowercase() }
        updatedUnread.removeAll { unreadID ->
            unreadID.lowercase() in normalizedAliases
        }
        state.setUnreadPrivateMessages(updatedUnread)
    }

    // MARK: - Message Deduplication

    /**
     * Generate a unique key for message deduplication
     */
    fun generateMessageKey(message: BitchatMessage): String {
        val senderKey = message.senderPeerID ?: message.sender
        val contentHash = message.content.hashCode()
        return "$senderKey-${message.timestamp.time}-$contentHash"
    }

    /**
     * Check if a message has already been processed
     */
    fun isMessageProcessed(messageKey: String): Boolean {
        return processedUIMessages.contains(messageKey)
    }

    /**
     * Mark a message as processed
     */
    fun markMessageProcessed(messageKey: String) {
        processedUIMessages.add(messageKey)
    }

    /**
     * Check if a system event is a duplicate within the timeout window
     */
    fun isDuplicateSystemEvent(eventType: String, peerID: String): Boolean {
        val now = System.currentTimeMillis()
        val eventKey = "$eventType-$peerID"
        val lastEvent = recentSystemEvents[eventKey]

        if (lastEvent != null && (now - lastEvent) < SYSTEM_EVENT_DEDUP_TIMEOUT) {
            return true // Duplicate event
        }

        recentSystemEvents[eventKey] = now
        return false
    }

    /**
     * Clean up old entries from deduplication caches
     */
    fun cleanupDeduplicationCaches() {
        val now = System.currentTimeMillis()

        // Clean up processed UI messages (remove entries older than 30 seconds)
        if (processedUIMessages.size > 1000) {
            processedUIMessages.clear()
        }

        // Clean up recent system events (remove entries older than timeout)
        recentSystemEvents.entries.removeAll { (_, timestamp) ->
            (now - timestamp) > SYSTEM_EVENT_DEDUP_TIMEOUT * 2
        }
    }

    // MARK: - Delivery Status Updates

    private fun statusPriority(status: DeliveryStatus?): Int = when (status) {
        null -> 0
        is DeliveryStatus.Sending -> 1
        is DeliveryStatus.Sent -> 2
        is DeliveryStatus.PartiallyDelivered -> 3
        is DeliveryStatus.Delivered -> 4
        is DeliveryStatus.Read -> 5
        is DeliveryStatus.Failed -> 0
    }

    private fun chooseStatus(old: DeliveryStatus?, new: DeliveryStatus): DeliveryStatus? {
        // A send failure may replace an in-flight state, but never a confirmed delivery/read.
        return when {
            new is DeliveryStatus.Failed &&
                old !is DeliveryStatus.Delivered &&
                old !is DeliveryStatus.Read -> new
            old is DeliveryStatus.Failed -> new
            statusPriority(new) >= statusPriority(old) -> new
            else -> old
        }
    }

    fun updateMessageDeliveryStatus(messageID: String, status: DeliveryStatus) {
        // Update in private chats
        val updatedPrivateChats = state.getPrivateChatsValue().toMutableMap()
        var updated = false

        updatedPrivateChats.forEach { (peerID, messages) ->
            val updatedMessages = messages.toMutableList()
            val messageIndex = updatedMessages.indexOfFirst { it.id == messageID }
            if (messageIndex >= 0) {
                val current = updatedMessages[messageIndex].deliveryStatus
                val finalStatus = chooseStatus(current, status)
                if (finalStatus !== current) {
                    updatedMessages[messageIndex] = updatedMessages[messageIndex].copy(deliveryStatus = finalStatus)
                    updatedPrivateChats[peerID] = updatedMessages
                    updated = true
                }
            }
        }

        if (updated) {
            state.setPrivateChats(updatedPrivateChats)
            // Keep process-wide store in sync to prevent snapshot overwrites resetting status
            try { com.bitchat.android.services.AppStateStore.updatePrivateMessageStatus(messageID, status) } catch (_: Exception) { }
        }

        // Update in main messages
        val updatedMessages = state.getMessagesValue().toMutableList()
        val messageIndex = updatedMessages.indexOfFirst { it.id == messageID }
        if (messageIndex >= 0) {
            val current = updatedMessages[messageIndex].deliveryStatus
            val finalStatus = chooseStatus(current, status)
            if (finalStatus !== current) {
                updatedMessages[messageIndex] = updatedMessages[messageIndex].copy(deliveryStatus = finalStatus)
                state.setMessages(updatedMessages)
            }
        }

        // Update in channel messages
        val updatedChannelMessages = state.getChannelMessagesValue().toMutableMap()
        updatedChannelMessages.forEach { (channel, messages) ->
            val channelMessagesList = messages.toMutableList()
            val channelMessageIndex = channelMessagesList.indexOfFirst { it.id == messageID }
            if (channelMessageIndex >= 0) {
                val current = channelMessagesList[channelMessageIndex].deliveryStatus
                val finalStatus = chooseStatus(current, status)
                if (finalStatus !== current) {
                    channelMessagesList[channelMessageIndex] = channelMessagesList[channelMessageIndex].copy(deliveryStatus = finalStatus)
                    updatedChannelMessages[channel] = channelMessagesList
                }
            }
        }
        state.setChannelMessages(updatedChannelMessages)
    }

    // Remove a message from all locations (main timeline, private chats, channels)
    fun removeMessageById(messageID: String) {
        // Main timeline
        run {
            val list = state.getMessagesValue().toMutableList()
            val idx = list.indexOfFirst { it.id == messageID }
            if (idx >= 0) {
                list.removeAt(idx)
                state.setMessages(list)
            }
        }
        // Private chats
        run {
            val chats = state.getPrivateChatsValue().toMutableMap()
            var changed = false
            chats.keys.toList().forEach { key ->
                val msgs = chats[key]?.toMutableList() ?: mutableListOf()
                val idx = msgs.indexOfFirst { it.id == messageID }
                if (idx >= 0) {
                    msgs.removeAt(idx)
                    chats[key] = msgs
                    changed = true
                }
            }
            if (changed) {
                state.setPrivateChats(chats.filterValues { it.isNotEmpty() })
                com.bitchat.android.services.AppStateStore.removePrivateMessage(messageID)
            }
        }
        // Channels
        run {
            val chans = state.getChannelMessagesValue().toMutableMap()
            var changed = false
            chans.keys.toList().forEach { ch ->
                val msgs = chans[ch]?.toMutableList() ?: mutableListOf()
                val idx = msgs.indexOfFirst { it.id == messageID }
                if (idx >= 0) {
                    msgs.removeAt(idx)
                    chans[ch] = msgs
                    changed = true
                }
            }
            if (changed) state.setChannelMessages(chans)
        }
    }

    // MARK: - Utility Functions

    fun parseMentions(content: String, peerNicknames: Set<String>, currentNickname: String?): List<String> {
        val mentionRegex = "@([a-zA-Z0-9_]+)".toRegex()
        val allNicknames = peerNicknames + (currentNickname ?: "")

        return mentionRegex.findAll(content)
            .map { it.groupValues[1] }
            .filter { allNicknames.contains(it) }
            .distinct()
            .toList()
    }

    fun parseChannels(content: String): List<String> {
        val channelRegex = "#([a-zA-Z0-9_]+)".toRegex()
        return channelRegex.findAll(content)
            .map { it.groupValues[0] } // Include the #
            .distinct()
            .toList()
    }

    // MARK: - Emergency Clear

    fun clearAllMessages() {
        state.setMessages(emptyList())
        state.setPrivateChats(emptyMap())
        state.setChannelMessages(emptyMap())
        state.setUnreadPrivateMessages(emptySet())
        state.setUnreadChannelMessages(emptyMap())
        processedUIMessages.clear()
        recentSystemEvents.clear()
    }
}

package com.bitchat.android.ui

import androidx.compose.ui.text.AnnotatedString
import android.util.Patterns

/**
 * Utilities for parsing special tokens in chat messages (geohashes, etc.).
 */
object MessageSpecialParser {
    // Standalone geohash pattern like "#9q" or longer. Word boundaries enforced.
    // Geohash alphabet is base32: 0123456789bcdefghjkmnpqrstuvwxyz
    private val standaloneGeohashRegex = Regex("(^|[^A-Za-z0-9_#])#([0-9bcdefghjkmnpqrstuvwxyz]{2,})($|[^A-Za-z0-9_])", RegexOption.IGNORE_CASE)

    data class GeohashMatch(val start: Int, val endExclusive: Int, val geohash: String)
    data class UrlMatch(val start: Int, val endExclusive: Int, val url: String)

    /**
     * Finds standalone geohashes within [text]. A match is returned only when
     * the '#' token is not part of another word (e.g., not in '@anon#9qk2').
     */
    fun findStandaloneGeohashes(text: String): List<GeohashMatch> {
        if (text.isEmpty()) return emptyList()
        val matches = mutableListOf<GeohashMatch>()
        var index = 0
        while (index < text.length) {
            val m = standaloneGeohashRegex.find(text, index) ?: break
            // Adjust to only cover the geohash token starting at '#'
            val fullRange = m.range
            // Find the '#' within this match substring
            val sub = text.substring(fullRange)
            val hashPos = sub.indexOf('#')
            if (hashPos >= 0) {
                val tokenStart = fullRange.first + hashPos
                // Consume '#' + geohash letters
                var cursor = tokenStart + 1
                while (cursor < text.length) {
                    val ch = text[cursor].lowercaseChar()
                    val isGeoChar = (ch in '0'..'9') || (ch in "bcdefghjkmnpqrstuvwxyz")
                    if (!isGeoChar) break
                    cursor++
                }
                val token = text.substring(tokenStart + 1, cursor)
                if (token.length >= 2) {
                    matches.add(GeohashMatch(tokenStart, cursor, token.lowercase()))
                }
                index = cursor
            } else {
                index = fullRange.last + 1
            }
        }
        return matches
    }

    /**
     * Detect URLs in text. Supports http(s) schemes, www.* domains, and bare domains with TLDs.
     * Trailing punctuation like '.', ',', ')', '!' is trimmed from the match.
     */
    fun findUrls(text: String): List<UrlMatch> {
        if (text.isEmpty()) return emptyList()
        val results = mutableListOf<UrlMatch>()

        // 1) Use Android's WEB_URL for robust detection of http(s) and www.*
        val webUrl = Patterns.WEB_URL
        val matcher = webUrl.matcher(text)
        while (matcher.find()) {
            var start = matcher.start()
            var endExclusive = matcher.end()
            var token = text.substring(start, endExclusive)

            // Trim trailing punctuation
            while (token.isNotEmpty() && token.last() in setOf('.', ',', ';', ':', '!', '?', '\'', '"')) {
                endExclusive -= 1
                token = text.substring(start, endExclusive)
            }
            results.add(UrlMatch(start, endExclusive, token))
        }

        // 2) Bare-domain fallback for things WEB_URL can miss (e.g., google.com)
        val bare = Regex("(?<!@)(?<![A-Za-z0-9_-])([A-Za-z0-9-]+\\.[A-Za-z]{2,}(?:/[A-Za-z0-9@:%._+~#=/?&!$'()*,-]*)?)")
        for (m in bare.findAll(text)) {
            val start = m.range.first
            var endExclusive = m.range.last + 1
            var token = text.substring(start, endExclusive)

            // Exclude if overlaps any already-found match
            val overlapsExisting = results.any { start < it.endExclusive && endExclusive > it.start }
            if (overlapsExisting) continue

            // Skip emails
            if (token.contains('@')) continue

            // Trim trailing punctuation
            while (token.isNotEmpty() && token.last() in setOf('.', ',', ';', ':', '!', '?', '\'', '"')) {
                endExclusive -= 1
                token = text.substring(start, endExclusive)
            }

            // Require at least one dot
            if (!token.contains('.')) continue

            results.add(UrlMatch(start, endExclusive, token))
        }

        // Sort by start index
        results.sortBy { it.start }
        return results
    }
}

package com.bitchat.android.ui

import android.Manifest
import android.app.NotificationChannel
import android.app.NotificationManager as AndroidNotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.app.Person
import androidx.core.app.NotificationManagerCompat
import androidx.core.app.RemoteInput
import androidx.core.content.ContextCompat
import androidx.core.content.pm.ShortcutInfoCompat
import androidx.core.content.pm.ShortcutManagerCompat
import androidx.core.content.LocusIdCompat
import androidx.core.graphics.drawable.IconCompat
import com.bitchat.android.MainActivity
import com.bitchat.android.R
import com.bitchat.android.service.ConversationNotificationReceiver
import com.bitchat.android.services.ContactDirectory
import com.bitchat.android.services.ConversationListPreferences
import java.util.Collections
import java.util.WeakHashMap
import java.util.concurrent.ConcurrentHashMap

/**
 * Enhanced notification manager for direct messages and geohash chats with production-ready features:
 * - Notification grouping per sender/geohash
 * - Click handling to open specific DM or geohash chat
 * - App background state awareness
 * - Support for mention notifications in geohash chats
 * - Support for first message notifications in geohash chats
 * - Proper notification management and cleanup
 */
class NotificationManager(
  private val context: Context,
  private val notificationManager: NotificationManagerCompat
) {

    companion object {
        private const val TAG = "NotificationManager"
        private const val CHANNEL_ID = "bitchat_dm_notifications"
        private const val GEOHASH_CHANNEL_ID = "bitchat_geohash_notifications"
        private const val GROUP_KEY_DM = "bitchat_dm_group"
        private const val GROUP_KEY_GEOHASH = "bitchat_geohash_group"
        private const val NOTIFICATION_REQUEST_CODE = 1000
        private const val GEOHASH_NOTIFICATION_REQUEST_CODE = 2000
        private const val SUMMARY_NOTIFICATION_ID = 999
      private const val GEOHASH_SUMMARY_NOTIFICATION_ID = 998
        private const val MAX_MESSAGES_IN_NOTIFICATION = 25

        // Intent extras for notification handling
        const val EXTRA_OPEN_PRIVATE_CHAT = "open_private_chat"
        const val EXTRA_OPEN_GEOHASH_CHAT = "open_geohash_chat"
        const val EXTRA_PEER_ID = "peer_id"
        const val EXTRA_SENDER_NICKNAME = "sender_nickname"
        const val EXTRA_GEOHASH = "geohash"
        const val ACTION_REPLY_TO_CONVERSATION =
            "com.bitchat.android.action.REPLY_TO_CONVERSATION"
        const val ACTION_MARK_CONVERSATION_READ =
            "com.bitchat.android.action.MARK_CONVERSATION_READ"
        const val KEY_TEXT_REPLY = "conversation_reply_text"

        private val liveManagers: MutableSet<NotificationManager> =
            Collections.newSetFromMap(WeakHashMap<NotificationManager, Boolean>())

        /**
         * Synchronizes notification action receivers with every manager instance in this process.
         * Without this, an old in-memory MessagingStyle history could reappear on the next DM.
         */
        fun acknowledgeConversation(context: Context, conversationID: String) {
            val canonicalID = ContactDirectory.canonicalConversationId(conversationID)
            val managers = synchronized(liveManagers) { liveManagers.toList() }
            managers.forEach { it.clearNotificationsForSender(canonicalID) }
            if (managers.isEmpty()) {
                NotificationManagerCompat.from(context).cancel(canonicalID.hashCode())
            }
        }
    }

    private val systemNotificationManager =
        context.getSystemService(Context.NOTIFICATION_SERVICE) as AndroidNotificationManager
    private val conversationPreferences =
        ConversationListPreferences.getInstance(context.applicationContext)

    // Track pending notifications per sender to enable grouping
    private val pendingNotifications = ConcurrentHashMap<String, MutableList<PendingNotification>>()
    private val pendingGeohashNotifications = ConcurrentHashMap<String, MutableList<GeohashNotification>>()

    // Track app background state
    @Volatile
    private var isAppInBackground = false

    // Track current view state
    @Volatile
    private var currentPrivateChatPeer: String? = null

    @Volatile
    private var currentGeohash: String? = null

    data class PendingNotification(
        val senderPeerID: String,
        val senderNickname: String, 
        val messageContent: String,
        val timestamp: Long
    )

    data class GeohashNotification(
        val geohash: String,
        val senderNickname: String,
        val messageContent: String,
        val timestamp: Long,
        val isMention: Boolean,
        val isFirstMessage: Boolean,
        val locationName: String? = null
    )

    init {
        synchronized(liveManagers) { liveManagers.add(this) }
        createNotificationChannel()
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            // DM notifications channel
            val dmName = context.getString(R.string.notification_channel_direct_messages)
            val dmDescriptionText =
                context.getString(R.string.notification_channel_direct_messages_description)
            val dmImportance = AndroidNotificationManager.IMPORTANCE_HIGH
            val dmChannel = NotificationChannel(CHANNEL_ID, dmName, dmImportance).apply {
                description = dmDescriptionText
                enableVibration(true)
                setShowBadge(true)
            }
            systemNotificationManager.createNotificationChannel(dmChannel)

            // Geohash notifications channel
            val geohashName = context.getString(R.string.notification_channel_geohash)
            val geohashDescriptionText =
                context.getString(R.string.notification_channel_geohash_description)
            val geohashImportance = AndroidNotificationManager.IMPORTANCE_HIGH
            val geohashChannel = NotificationChannel(GEOHASH_CHANNEL_ID, geohashName, geohashImportance).apply {
                description = geohashDescriptionText
                enableVibration(true)
                setShowBadge(true)
            }
            systemNotificationManager.createNotificationChannel(geohashChannel)
        }
    }

    /**
     * Update app background state - notifications should only be shown when app is backgrounded
     */
    fun setAppBackgroundState(inBackground: Boolean) {
        isAppInBackground = inBackground
        Log.d(TAG, "App background state changed: $inBackground")
    }

    /**
     * Update current private chat peer - affects notification logic
     */
    fun setCurrentPrivateChatPeer(peerID: String?) {
        currentPrivateChatPeer = peerID?.let { ContactDirectory.canonicalConversationId(it) }
        Log.d(TAG, "Current private chat peer changed: $currentPrivateChatPeer")
    }

    /**
     * Update current geohash - affects notification logic for geohash chats
     */
    fun setCurrentGeohash(geohash: String?) {
        currentGeohash = geohash
        Log.d(TAG, "Current geohash changed")
    }

    /**
     * Show a notification for a private message with proper grouping and state awareness
     */
    fun showPrivateMessageNotification(senderPeerID: String, senderNickname: String, messageContent: String) {
        val conversationID = ContactDirectory.canonicalConversationId(senderPeerID)
        if (conversationPreferences.isMuted(conversationID)) {
            Log.d(TAG, "Skipping muted conversation notification")
            return
        }
        // Only show notifications if app is in background OR user is not viewing this specific chat
        val shouldNotify = isAppInBackground ||
            (!isAppInBackground && currentPrivateChatPeer != conversationID)

        if (!shouldNotify) {
            Log.d(TAG, "Skipping notification - app in foreground and viewing chat with $senderNickname")
            return
        }

        Log.d(TAG, "Showing notification for message from $senderNickname (conversationID: $conversationID)")

        val notification = PendingNotification(
            senderPeerID = conversationID,
            senderNickname = senderNickname,
            messageContent = messageContent,
            timestamp = System.currentTimeMillis()
        )

        // Add to pending notifications for this sender
        pendingNotifications.computeIfAbsent(conversationID) { mutableListOf() }.add(notification)

        // Create or update notification for this sender
        showNotificationForSender(conversationID)

        // Update summary notification if we have multiple senders
        if (pendingNotifications.size > 1) {
            showSummaryNotification()
        }
    }

    private fun showNotificationForSender(senderPeerID: String) {
        val notifications = pendingNotifications[senderPeerID] ?: return
        if (notifications.isEmpty()) return

        val latestNotification = notifications.last()
        val messageCount = notifications.size

        // Create intent to open the specific private chat
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            putExtra(EXTRA_OPEN_PRIVATE_CHAT, true)
            putExtra(EXTRA_PEER_ID, senderPeerID)
            putExtra(EXTRA_SENDER_NICKNAME, latestNotification.senderNickname)
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            NOTIFICATION_REQUEST_CODE + senderPeerID.hashCode(),
            intent,
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )

        // Create person for better notification styling
        val person = Person.Builder()
            .setName(latestNotification.senderNickname)
            .setKey(senderPeerID)
            .build()
        val shortcutID = conversationShortcutID(senderPeerID)
        publishConversationShortcut(
            shortcutID = shortcutID,
            person = person,
            contentIntent = intent
        )

        // Build notification content
        val contentText = if (messageCount == 1) {
            latestNotification.messageContent
        } else {
            "${latestNotification.messageContent} (+${messageCount - 1} more)"
        }

        val contentTitle = if (messageCount == 1) {
            latestNotification.senderNickname
        } else {
            "${latestNotification.senderNickname} ($messageCount messages)"
        }

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(contentTitle)
            .setContentText(contentText)
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setCategory(NotificationCompat.CATEGORY_MESSAGE)
            .addPerson(person)
            .setShortcutId(shortcutID)
            .setLocusId(LocusIdCompat(shortcutID))
            .setVisibility(NotificationCompat.VISIBILITY_PRIVATE)
            .setShowWhen(true)
            .setWhen(latestNotification.timestamp)

        val markReadIntent = Intent(context, ConversationNotificationReceiver::class.java).apply {
            action = ACTION_MARK_CONVERSATION_READ
            putExtra(EXTRA_PEER_ID, senderPeerID)
        }
        val markReadPendingIntent = PendingIntent.getBroadcast(
            context,
            NOTIFICATION_REQUEST_CODE + senderPeerID.hashCode() + 1,
            markReadIntent,
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        val replyIntent = Intent(context, ConversationNotificationReceiver::class.java).apply {
            action = ACTION_REPLY_TO_CONVERSATION
            putExtra(EXTRA_PEER_ID, senderPeerID)
            putExtra(EXTRA_SENDER_NICKNAME, latestNotification.senderNickname)
        }
        val replyPendingIntent = PendingIntent.getBroadcast(
            context,
            NOTIFICATION_REQUEST_CODE + senderPeerID.hashCode() + 2,
            replyIntent,
            PendingIntent.FLAG_MUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
        )
        val remoteInput = RemoteInput.Builder(KEY_TEXT_REPLY)
            .setLabel(context.getString(R.string.notification_reply))
            .build()
        builder
            .addAction(
                NotificationCompat.Action.Builder(
                    R.drawable.ic_notification,
                    context.getString(R.string.notification_mark_read),
                    markReadPendingIntent
                ).build()
            )
            .addAction(
                NotificationCompat.Action.Builder(
                    R.drawable.ic_notification,
                    context.getString(R.string.notification_reply),
                    replyPendingIntent
                )
                    .addRemoteInput(remoteInput)
                    .setAllowGeneratedReplies(true)
                    .build()
            )
            .setPublicVersion(
                NotificationCompat.Builder(context, CHANNEL_ID)
                    .setSmallIcon(R.drawable.ic_notification)
                    .setContentTitle(context.getString(R.string.notification_private_message))
                    .setContentText(context.getString(R.string.notification_content_hidden))
                    .build()
            )

        // Add to notification group if we have multiple senders
        if (pendingNotifications.size > 1) {
            builder.setGroup(GROUP_KEY_DM)
        }

        val self = Person.Builder()
            .setName(context.getString(R.string.you))
            .setKey("bitchat-self")
            .build()
        val messagingStyle = NotificationCompat.MessagingStyle(self)
            .setGroupConversation(false)
        notifications.takeLast(MAX_MESSAGES_IN_NOTIFICATION).forEach { notification ->
            messagingStyle.addMessage(
                notification.messageContent,
                notification.timestamp,
                person
            )
        }
        builder.setStyle(messagingStyle)

        // Use sender peer ID hash as notification ID to group messages from same sender
        val notificationId = senderPeerID.hashCode()
        notifySafely(notificationId, builder.build())

        Log.d(TAG, "Displayed notification for $contentTitle with ID $notificationId")
    }

    private fun conversationShortcutID(conversationID: String): String =
        "dm_" + java.util.UUID.nameUUIDFromBytes(
            conversationID.lowercase().toByteArray(Charsets.UTF_8)
        ).toString()

    private fun publishConversationShortcut(
        shortcutID: String,
        person: Person,
        contentIntent: Intent
    ) {
        val shortcut = ShortcutInfoCompat.Builder(context, shortcutID)
            .setShortLabel(person.name?.toString()?.take(40).orEmpty())
            .setLongLived(true)
            .setPerson(person)
            .setLocusId(LocusIdCompat(shortcutID))
            .setIcon(IconCompat.createWithResource(context, R.drawable.ic_notification))
            .setIntent(Intent(contentIntent).apply { action = Intent.ACTION_VIEW })
            .build()
        ShortcutManagerCompat.pushDynamicShortcut(context, shortcut)
    }

    fun showVerificationNotification(title: String, body: String, peerID: String? = null) {
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
