// Physics constants
private const val REPULSION_FORCE = 100000f
private const val SPRING_LENGTH = 150f
private const val SPRING_STRENGTH = 0.02f
private const val CENTER_GRAVITY = 0.02f
private const val DAMPING = 0.85f
private const val MAX_VELOCITY = 30f
private const val PULSE_DECAY = 0.05f
private const val ROUTE_DECAY = 0.02f
private val EDGE_ICON_OFFSET = 14.dp

private enum class EdgeTransport { WIFI, BLE }

private data class EdgeMarker(val x: Float, val y: Float, val transport: EdgeTransport)

private fun shouldMarkDirectEdge(
    edge: MeshGraphService.GraphEdge,
    transportPeerIDs: Set<String>,
    localID: String?
): Boolean {
    if (transportPeerIDs.isEmpty()) return false
    return if (localID != null) {
        (edge.a == localID && edge.b in transportPeerIDs) ||
            (edge.b == localID && edge.a in transportPeerIDs)
    } else {
        edge.a in transportPeerIDs || edge.b in transportPeerIDs
    }
}

private fun edgeMarkerPosition(
    x1: Float,
    y1: Float,
    x2: Float,
    y2: Float,
    offsetPx: Float,
    sideSign: Float
): Pair<Float, Float> {
    val midX = (x1 + x2) / 2f
    val midY = (y1 + y2) / 2f
    val dx = x2 - x1
    val dy = y2 - y1
    val len = sqrt(dx * dx + dy * dy)
    if (len < 0.1f) return midX to midY
    val px = -dy / len * offsetPx * sideSign
    val py = dx / len * offsetPx * sideSign
    return (midX + px) to (midY + py)
}

private class GraphNodeState(
    val id: String,
    var label: String,
    var x: Float,
    var y: Float
) {
    var vx: Float = 0f
    var vy: Float = 0f
    var isDragged: Boolean = false
    var pulseLevel: Float = 0f // 0f to 1f, used for size/glow animation
}

private class Simulation {
    val nodes = mutableMapOf<String, GraphNodeState>()
    // Storing edges as pairs of IDs
    val edges = mutableListOf<MeshGraphService.GraphEdge>()
    // Active routes being animated: List of peerIDs in order -> intensity (1.0..0.0)
    val activeRoutes = mutableListOf<Pair<List<String>, Float>>()

    // Bounds for initial placement and centering
    var width: Float = 1000f
    var height: Float = 1000f

    fun updateTopology(
        newNodes: List<MeshGraphService.GraphNode>,
        newEdges: List<MeshGraphService.GraphEdge>
    ) {
        // Remove stale nodes
        val newIds = newNodes.map { it.peerID }.toSet()
        nodes.keys.toList().forEach { id ->
            if (id !in newIds) nodes.remove(id)
        }

        // Add/Update nodes
        newNodes.forEach { n ->
            val existing = nodes[n.peerID]
            val displayLabel = n.nickname ?: n.peerID.take(8)
            if (existing != null) {
                existing.label = displayLabel
            } else {
                // Spawn near center with random jitter
                val angle = Random.nextFloat() * 2 * PI
                val radius = 50f + Random.nextFloat() * 50f
                nodes[n.peerID] = GraphNodeState(
                    id = n.peerID,
                    label = displayLabel,
                    x = (width / 2f) + (cos(angle) * radius).toFloat(),
                    y = (height / 2f) + (sin(angle) * radius).toFloat()
                )
            }
        }

        // Update edges
        edges.clear()
        edges.addAll(newEdges)
    }

    fun triggerNodePulse(peerID: String) {
        nodes[peerID]?.pulseLevel = 1f
    }

    fun triggerRouteAnimation(route: List<String>) {
        if (route.size > 1) {
            activeRoutes.add(route to 1f)
        }
    }

    fun step() {
        val nodeList = nodes.values.toList()
        val cx = width / 2f
        val cy = height / 2f

        // 1. Repulsion (Node-Node)
        for (i in nodeList.indices) {
            val n1 = nodeList[i]
            for (j in i + 1 until nodeList.size) {
                val n2 = nodeList[j]
                val dx = n1.x - n2.x
                val dy = n1.y - n2.y
                val distSq = dx * dx + dy * dy
                if (distSq > 0.1f) {
                    val dist = sqrt(distSq)
                    val force = REPULSION_FORCE / distSq
                    val fx = (dx / dist) * force
                    val fy = (dy / dist) * force

                    if (!n1.isDragged) {
                        n1.vx += fx
                        n1.vy += fy
                    }
                    if (!n2.isDragged) {
                        n2.vx -= fx
                        n2.vy -= fy
                    }
                }
            }
        }

        // 2. Attraction (Edges)
        edges.forEach { edge ->
            val n1 = nodes[edge.a]
            val n2 = nodes[edge.b]
            if (n1 != null && n2 != null) {
                val dx = n1.x - n2.x
                val dy = n1.y - n2.y
                val dist = sqrt(dx * dx + dy * dy)
                if (dist > 0.1f) {
                    val force = (dist - SPRING_LENGTH) * SPRING_STRENGTH
                    val fx = (dx / dist) * force
                    val fy = (dy / dist) * force

                    if (!n1.isDragged) {
                        n1.vx -= fx
                        n1.vy -= fy
                    }
                    if (!n2.isDragged) {
                        n2.vx += fx
                        n2.vy += fy
                    }
                }
            }
        }

        // 3. Center Gravity & Integration & Animation Decay
        nodeList.forEach { n ->
            if (!n.isDragged) {
                // Pull to center
                val dx = n.x - cx
                val dy = n.y - cy
                n.vx -= dx * CENTER_GRAVITY
                n.vy -= dy * CENTER_GRAVITY

                // Apply velocity
                val vMag = sqrt(n.vx * n.vx + n.vy * n.vy)
                if (vMag > MAX_VELOCITY) {
                    n.vx = (n.vx / vMag) * MAX_VELOCITY
                    n.vy = (n.vy / vMag) * MAX_VELOCITY
                }

                n.x += n.vx
                n.y += n.vy

                // Damping
                n.vx *= DAMPING
                n.vy *= DAMPING
            } else {
                n.vx = 0f
                n.vy = 0f
            }

            // Decay pulse
            if (n.pulseLevel > 0f) {
                n.pulseLevel = (n.pulseLevel - PULSE_DECAY).coerceAtLeast(0f)
            }
        }

        // Decay active routes
        val iter = activeRoutes.iterator()
        while (iter.hasNext()) {
            val (route, intensity) = iter.next()
            val newIntensity = intensity - ROUTE_DECAY
            if (newIntensity <= 0f) {
                iter.remove()
            } else {
                // Ugly mutation but efficient for simulation loop
                // We need to replace the pair since pairs are immutable
                // Finding index is O(N) but N is small
                val idx = activeRoutes.indexOfFirst { it.first === route && it.second == intensity }
                if (idx >= 0) {
                     activeRoutes[idx] = route to newIntensity
                }
            }
        }
    }
}

@Composable
fun ForceDirectedMeshGraph(
    nodes: List<MeshGraphService.GraphNode>,
    edges: List<MeshGraphService.GraphEdge>,
    wifiAwarePeerIDs: Set<String> = emptySet(),
    blePeerIDs: Set<String> = emptySet(),
    localPeerID: String? = null,
    modifier: Modifier = Modifier
) {
    val density = LocalDensity.current
    val simulation = remember { Simulation() }
    val colorScheme = MaterialTheme.colorScheme

    // Listen for visual events
    val debugManager = remember { DebugSettingsManager.getInstance() }
    LaunchedEffect(Unit) {
        debugManager.meshVisualEvents.collect { event ->
            when (event) {
                is MeshVisualEvent.PacketActivity -> simulation.triggerNodePulse(event.peerID)
                is MeshVisualEvent.RouteActivity -> simulation.triggerRouteAnimation(event.route)
            }
        }
    }

    // We need a state that changes on every tick to trigger redraw
    var tick by remember { mutableLongStateOf(0L) }

    // Update topology when input data changes
    LaunchedEffect(nodes, edges) {
        simulation.updateTopology(nodes, edges)
    }

    // Animation Loop
    LaunchedEffect(Unit) {
        while (true) {
            withFrameNanos { 
                simulation.step()
                tick++ 
            }
        }
    }

    BoxWithConstraints(modifier = modifier) {
        val w = maxWidth.value * density.density
        val h = maxHeight.value * density.density

        // Update simulation bounds if size changes
        SideEffect {
            simulation.width = w
            simulation.height = h
        }

        Canvas(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(Unit) {
                    detectDragGestures(
                        onDragStart = { offset ->
                            // Find closest node
                            val closest = simulation.nodes.values.minByOrNull { 
                                val dx = it.x - offset.x
                                val dy = it.y - offset.y
                                dx*dx + dy*dy
                            }
                            if (closest != null) {
                                val dist = sqrt((closest.x - offset.x).pow(2) + (closest.y - offset.y).pow(2))
                                if (dist < 80f) { // Touch radius
                                    closest.isDragged = true
                                }
                            }
                        },
                        onDragEnd = {
                             simulation.nodes.values.forEach { it.isDragged = false }
                        },
                        onDragCancel = {
                             simulation.nodes.values.forEach { it.isDragged = false }
                        },
                        onDrag = { change, dragAmount ->
                            change.consume()
                            val dragged = simulation.nodes.values.find { it.isDragged }
                            if (dragged != null) {
                                dragged.x += dragAmount.x
                                dragged.y += dragAmount.y
                            }
                        }
                    )
                }
        ) {
            // Read tick to ensure recomposition
            val t = tick 

            val nodeMap = simulation.nodes

            // Draw Edges
            simulation.edges.forEach { edge ->
                val n1 = nodeMap[edge.a]
                val n2 = nodeMap[edge.b]

                if (n1 != null && n2 != null) {
                    val start = Offset(n1.x, n1.y)
                    val end = Offset(n2.x, n2.y)
                    val baseColor = Color(0xFF4A90E2)

                    if (edge.isConfirmed) {
                        drawLine(
                            color = baseColor,
                            start = start,
                            end = end,
                            strokeWidth = 5f
                        )
                    } else {
                        // Unconfirmed: draw "solid" from declarer, "dashed" from other
                        val isA = (edge.confirmedBy == edge.a)
                        val solidStart = if (isA) start else end
                        val solidEnd = if (isA) end else start

                        val midX = (start.x + end.x) / 2
                        val midY = (start.y + end.y) / 2
                        val mid = Offset(midX, midY)

                        drawLine(
                            color = baseColor,
                            start = solidStart,
                            end = mid,
                            strokeWidth = 4f
                        )

                        drawLine(
                            color = baseColor.copy(alpha = 0.6f),
                            start = mid,
                            end = solidEnd,
                            strokeWidth = 4f,
                            pathEffect = PathEffect.dashPathEffect(floatArrayOf(10f, 10f), 0f)
                        )
                    }
                }
            }

            // Draw Active Routes (overlay)
            simulation.activeRoutes.forEach { (route, intensity) ->
                val routeColor = Color(0xFFFFD700).copy(alpha = intensity) // Gold
                val strokeW = 4f * intensity + 2f

                for (i in 0 until route.size - 1) {
                    val p1 = nodeMap[route[i]]
                    val p2 = nodeMap[route[i+1]]
                    if (p1 != null && p2 != null) {
                        drawLine(
                            color = routeColor,
                            start = Offset(p1.x, p1.y),
                            end = Offset(p2.x, p2.y),
                            strokeWidth = strokeW,
                            cap = androidx.compose.ui.graphics.StrokeCap.Round
                        )
                    }
                }
            }

            // Draw Nodes
            val labelColor = colorScheme.onSurface.toArgb()
            val textPaint = android.graphics.Paint().apply {
                isAntiAlias = true
                textSize = 12.sp.toPx()
                this.color = labelColor
            }

            nodeMap.values.forEach { node ->
                val center = Offset(node.x, node.y)
                val pulse = node.pulseLevel

                // Pulse glow
                if (pulse > 0.05f) {
                     drawCircle(
                        color = Color(0xFF00FF00).copy(alpha = pulse * 0.6f),
                        radius = 16f + (pulse * 20f),
                        center = center
                    )
                }

                drawCircle(
                    color = Color(0xFF00C851),
                    radius = 16f + (pulse * 4f), // Slight scale up
                    center = center
                )
                drawCircle(
                    color = Color.White,
                    radius = 12f + (pulse * 3f),
                    center = center,
                    style = Stroke(width = 2f)
                )

                // Label
                drawContext.canvas.nativeCanvas.drawText(
                    node.label,
                    node.x + 22f + (pulse * 5f), 
                    node.y + 4f,
                    textPaint
                )
            }
        }

        val iconSize = 16.dp
        val iconSizePx = with(density) { iconSize.toPx() }
        val halfIconSizePx = iconSizePx / 2f
        val iconOffsetPx = with(density) { EDGE_ICON_OFFSET.toPx() }
        val localID = localPeerID

        val edgeMarkers = tick.let {
            simulation.edges.flatMap { edge ->
                val n1 = simulation.nodes[edge.a]
                val n2 = simulation.nodes[edge.b]
                if (n1 == null || n2 == null) return@flatMap emptyList()

                val isWifi = shouldMarkDirectEdge(edge, wifiAwarePeerIDs, localID)
                val isBle = shouldMarkDirectEdge(edge, blePeerIDs, localID)
                if (!isWifi && !isBle) return@flatMap emptyList()

                val markers = mutableListOf<EdgeMarker>()
                if (isWifi) {
                    val (x, y) = edgeMarkerPosition(n1.x, n1.y, n2.x, n2.y, iconOffsetPx, sideSign = 1f)
                    markers.add(EdgeMarker(x, y, EdgeTransport.WIFI))
                }
                if (isBle) {
                    val side = if (isWifi) -1f else 1f
                    val (x, y) = edgeMarkerPosition(n1.x, n1.y, n2.x, n2.y, iconOffsetPx, sideSign = side)
                    markers.add(EdgeMarker(x, y, EdgeTransport.BLE))
                }
                markers
            }
        }

        edgeMarkers.forEach { marker ->
            Icon(
                imageVector = when (marker.transport) {
                    EdgeTransport.WIFI -> Icons.Filled.Wifi
                    EdgeTransport.BLE -> Icons.Outlined.Bluetooth
                },
                contentDescription = null,
                tint = colorScheme.onSurface.copy(alpha = 0.82f),
                modifier = Modifier
                    .offset {
                        IntOffset(
                            x = (marker.x - halfIconSizePx).roundToInt(),
                            y = (marker.y - halfIconSizePx).roundToInt()
                        )
                    }
                    .size(iconSize)
            )
        }
    }
}

package com.bitchat.android.ui.events

/**
 * Lightweight dispatcher so lower-level UI (MessageInput) can trigger
 * file sending without holding a direct reference to ChatViewModel.
 */
object FileShareDispatcher {
    @Volatile private var handler: ((String?, String?, String) -> Unit)? = null

    fun setHandler(h: ((String?, String?, String) -> Unit)?) {
        handler = h
    }

    fun dispatch(peerIdOrNull: String?, channelOrNull: String?, path: String) {
        handler?.invoke(peerIdOrNull, channelOrNull, path)
    }
}

package com.bitchat.android.ui.globe

import kotlin.math.*

/**
 * Orthographic globe projection and geohash zoom math for the 3D globe picker.
 *
 * The globe is rendered as a disc of radius R centered on screen. Points are
 * projected with an orthographic projection around a view center lat/lon.
 */
object GlobeMath {

    data class Projection(val x: Float, val y: Float, val cosC: Float)

    /**
     * Frame-local projector for prepared static geometry. Center terms are calculated once
     * and projection results are written to a caller-owned array without allocating objects.
     */
    class PreparedProjector(centerLatDeg: Double, centerLonDeg: Double) {
        private val sinCenterLat = sin(Math.toRadians(centerLatDeg)).toFloat()
        private val cosCenterLat = cos(Math.toRadians(centerLatDeg)).toFloat()
        private val sinCenterLon = sin(Math.toRadians(centerLonDeg)).toFloat()
        private val cosCenterLon = cos(Math.toRadians(centerLonDeg)).toFloat()

        fun project(terms: FloatArray, termOffset: Int, out: FloatArray, outOffset: Int) {
            val sinLat = terms[termOffset]
            val cosLat = terms[termOffset + 1]
            val sinLon = terms[termOffset + 2]
            val cosLon = terms[termOffset + 3]
            val sinDeltaLon = sinLon * cosCenterLon - cosLon * sinCenterLon
            val cosDeltaLon = cosLon * cosCenterLon + sinLon * sinCenterLon
            out[outOffset] = cosLat * sinDeltaLon
            out[outOffset + 1] = -(
                cosCenterLat * sinLat -
                    sinCenterLat * cosLat * cosDeltaLon
                )
            out[outOffset + 2] =
                sinCenterLat * sinLat + cosCenterLat * cosLat * cosDeltaLon
        }
    }

    /**
     * Projects (lat, lon) onto the view disc of a globe centered at (centerLat, centerLon).
     * Returns x/y in units of globe radius (screen y down). [Projection.cosC] is negative
     * when the point is on the far side of the sphere.
     */
    fun projectRaw(latDeg: Double, lonDeg: Double, centerLatDeg: Double, centerLonDeg: Double): Projection {
        val phi = Math.toRadians(latDeg)
        val phi0 = Math.toRadians(centerLatDeg)
        val dLambda = Math.toRadians(normalizeLon(lonDeg - centerLonDeg))
        val cosC = sin(phi0) * sin(phi) + cos(phi0) * cos(phi) * cos(dLambda)
        val x = cos(phi) * sin(dLambda)
        val y = -(cos(phi0) * sin(phi) - sin(phi0) * cos(phi) * cos(dLambda))
        return Projection(x.toFloat(), y.toFloat(), cosC.toFloat())
    }

    /** Like [projectRaw] but null when the point is behind the limb. */
    fun project(latDeg: Double, lonDeg: Double, centerLatDeg: Double, centerLonDeg: Double): Projection? {
        val p = projectRaw(latDeg, lonDeg, centerLatDeg, centerLonDeg)
        return if (p.cosC >= 0f) p else null
    }

    /**
     * Inverse projection: disc coordinates (units of radius, screen y down) back to lat/lon.
     * Returns null if the point lies outside the disc.
     */
    fun unproject(x: Double, y: Double, centerLatDeg: Double, centerLonDeg: Double): Pair<Double, Double>? {
        val rho = sqrt(x * x + y * y)
        if (rho > 1.0) return null
        val c = asin(rho.coerceIn(-1.0, 1.0))
        val phi0 = Math.toRadians(centerLatDeg)
        val sinC = sin(c)
        val cosC = cos(c)
        val lat: Double
        val lonOffset: Double
        if (rho < 1e-9) {
            lat = centerLatDeg
            lonOffset = 0.0
        } else {
            lat = Math.toDegrees(asin(cosC * sin(phi0) + (-y) * sinC * cos(phi0) / rho))
            lonOffset = Math.toDegrees(atan2(x * sinC, rho * cos(phi0) * cosC - (-y) * sin(phi0) * sinC))
        }
        return lat to normalizeLon(centerLonDeg + lonOffset)
    }

    fun normalizeLon(lon: Double): Double {
        var x = lon % 360.0
        if (x > 180.0) x -= 360.0
        if (x < -180.0) x += 360.0
        return x
    }

    /** Longitude span of a geohash cell in degrees. */
    fun cellSpanLon(precision: Int): Double = 360.0 / 2.0.pow(ceil(5.0 * precision / 2.0))

    /** Latitude span of a geohash cell in degrees. */
    fun cellSpanLat(precision: Int): Double = 180.0 / 2.0.pow(floor(5.0 * precision / 2.0))

    /**
     * Picks the geohash precision whose cells render at a comfortable on-screen size
     * for the current zoom: the largest precision whose cell is at least ~22% of the
     * screen's smallest dimension.
     */
    fun autoPrecision(globeRadiusPx: Float, screenMinPx: Float): Int {
        val targetPx = screenMinPx * 0.22f
        var best = 1
        for (p in 1..MAX_PRECISION) {
            val spanPx = (cellSpanLat(p) * (Math.PI / 180.0) * globeRadiusPx).toFloat()
            if (spanPx >= targetPx) best = p else break
        }
        return best.coerceIn(1, MAX_PRECISION)
    }

    /**
     * Zoom factor (globe radius multiplier over the fit-to-screen base radius) that frames
     * a cell of the given precision nicely: the cell spans ~1/3 of the screen.
     */
    fun zoomForPrecision(precision: Int, baseRadiusPx: Float, screenMinPx: Float): Float {
        val spanRad = cellSpanLat(precision) * (Math.PI / 180.0)
        val targetRadius = (screenMinPx / 3.0) / spanRad
        return (targetRadius / baseRadiusPx).toFloat().coerceIn(MIN_ZOOM, MAX_ZOOM)
    }

    const val MIN_ZOOM = 1f
    const val MAX_ZOOM = 120000f
    const val MAX_PRECISION = 12
}

package com.bitchat.android.ui.globe

import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.FastOutSlowInEasing
import androidx.compose.animation.core.tween
import androidx.compose.runtime.getValue
import androidx.compose.runtime.Stable
import androidx.compose.runtime.mutableFloatStateOf
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.bitchat.android.geohash.Geohash
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import androidx.compose.runtime.withFrameNanos
import kotlin.math.abs
import kotlin.math.exp
import kotlin.math.pow

/**
 * Hoisted state for the interactive 3D globe: view center, zoom, geohash precision
 * and the current selection. All mutation funnels through this class so rendering,
 * gestures and buttons stay in sync.
 */
@Stable
class GlobeState(
    targetLat: Double,
    targetLon: Double,
    initialPrecision: Int,
    startZoomedOut: Boolean
) {
    var centerLat by mutableFloatStateOf(if (startZoomedOut) (targetLat * 0.4).toFloat() else targetLat.toFloat())
        private set
    var centerLon by mutableFloatStateOf(if (startZoomedOut) GlobeMath.normalizeLon(targetLon - 70.0).toFloat() else targetLon.toFloat())
        private set
    var zoom by mutableFloatStateOf(if (startZoomedOut) GlobeMath.MIN_ZOOM else 1f)
        private set
    var precision by mutableIntStateOf(initialPrecision.coerceIn(1, GlobeMath.MAX_PRECISION))
        private set
    var selectedGeohash by mutableStateOf("")
        private set
    var isInteracting by mutableStateOf(false)
        internal set
    var isAnimating by mutableStateOf(false)
        private set

    internal var baseRadiusPx by mutableFloatStateOf(0f)
    internal var screenMinPx by mutableFloatStateOf(0f)

    private var scope: CoroutineScope? = null
    private var animJob: Job? = null
    private var animationGeneration = 0

    /** Pending cinematic intro target (lat, lon, precision); consumed when played. */
    var introTarget: Triple<Double, Double, Int>? = null
    private var introPlayed = false

    fun playPendingIntroIfAny() {
        if (introPlayed) return
        val target = introTarget ?: return
        introPlayed = true
        introTarget = null
        playIntro(target.first, target.second, target.third)
    }

    fun attach(scope: CoroutineScope) {
        this.scope = scope
    }

    fun setViewport(baseRadiusPx: Float, screenMinPx: Float) {
        if (baseRadiusPx <= 0f || screenMinPx <= 0f) return
        this.baseRadiusPx = baseRadiusPx
        this.screenMinPx = screenMinPx
        syncSelection()
    }

    val globeRadiusPx: Float get() = baseRadiusPx * zoom

    /** Direct rotation from drag gestures. Deltas are in screen px. */
    fun rotateBy(dxPx: Float, dyPx: Float) {
        val r = globeRadiusPx
        if (r <= 0f) return
        val degPerPx = 180.0 / (Math.PI * r)
        centerLon = GlobeMath.normalizeLon(centerLon - dxPx * degPerPx).toFloat()
        centerLat = (centerLat + dyPx * degPerPx).toFloat().coerceIn(MIN_LAT, MAX_LAT)
        syncSelection()
    }

    /** Continuous zoom from pinch gestures; precision follows automatically. */
    fun zoomBy(factor: Float) {
        if (factor == 1f) return
        zoom = (zoom * factor).coerceIn(GlobeMath.MIN_ZOOM, GlobeMath.MAX_ZOOM)
        syncPrecisionFromZoom()
        syncSelection()
    }

    private fun syncPrecisionFromZoom() {
        if (baseRadiusPx <= 0f) return
        precision = GlobeMath.autoPrecision(globeRadiusPx, screenMinPx)
    }

    /** Animate the view to a lat/lon, optionally to a zoom and precision. */
    fun animateTo(
        lat: Double,
        lon: Double,
        targetZoom: Float? = null,
        targetPrecision: Int? = null,
        durationMs: Int = 550
    ) {
        val s = scope ?: return
        animJob?.cancel()
        val startLat = centerLat
        val startLon = centerLon
        val dLon = GlobeMath.normalizeLon(lon - startLon)
        val startZoom = zoom
        val endZoom = (targetZoom ?: zoom).coerceIn(GlobeMath.MIN_ZOOM, GlobeMath.MAX_ZOOM)
        val generation = ++animationGeneration
        isAnimating = true
        animJob = s.launch {
            try {
                val anim = Animatable(0f)
                anim.animateTo(1f, tween(durationMs, easing = FastOutSlowInEasing)) {
                    val t = value
                    centerLat = (startLat + (lat.toFloat() - startLat) * t).coerceIn(MIN_LAT, MAX_LAT)
                    centerLon = GlobeMath.normalizeLon(startLon + dLon * t).toFloat()
                    // exponential interpolation feels natural for zoom
                    zoom = startZoom * (endZoom / startZoom).pow(t)
                    if (targetPrecision != null) {
                        precision = targetPrecision.coerceIn(1, GlobeMath.MAX_PRECISION)
                    } else {
                        syncPrecisionFromZoom()
                    }
                    syncSelection()
                }
            } finally {
                if (animationGeneration == generation) {
                    isAnimating = false
                    animJob = null
                }
            }
        }
    }

    /** Button-driven precision change: adjusts precision and animates zoom to frame it. */
    fun animatePrecision(newPrecision: Int) {
        val p = newPrecision.coerceIn(1, GlobeMath.MAX_PRECISION)
        if (p == precision || baseRadiusPx <= 0f) return
        val targetZoom = GlobeMath.zoomForPrecision(p, baseRadiusPx, screenMinPx)
        animateTo(centerLat.toDouble(), centerLon.toDouble(), targetZoom, p, durationMs = 450)
    }

    /** Cinematic intro: spin and zoom from a far view into the target location. */
    private fun playIntro(targetLat: Double, targetLon: Double, targetPrecision: Int) {
        if (baseRadiusPx <= 0f) {
            // viewport not ready yet; retry once attached to layout via caller
            return
        }
        val targetZoom = GlobeMath.zoomForPrecision(targetPrecision, baseRadiusPx, screenMinPx)
        animateTo(targetLat, targetLon, targetZoom, targetPrecision, durationMs = 1400)
    }

    /** Inertial spin after a fling. Velocities are in px/second. */
    fun fling(velocityX: Float, velocityY: Float) {
        val s = scope ?: return
        var initialVx = velocityX.coerceIn(-MAX_FLING_PX_PER_SECOND, MAX_FLING_PX_PER_SECOND)
        var initialVy = velocityY.coerceIn(-MAX_FLING_PX_PER_SECOND, MAX_FLING_PX_PER_SECOND)
        if (abs(initialVx) < MIN_FLING_PX_PER_SECOND) initialVx = 0f
        if (abs(initialVy) < MIN_FLING_PX_PER_SECOND) initialVy = 0f
        if (initialVx == 0f && initialVy == 0f) return
        animJob?.cancel()
        val generation = ++animationGeneration
        isAnimating = true
        animJob = s.launch {
            try {
                var vx = initialVx
                var vy = initialVy
                var lastFrameNanos = withFrameNanos { it }
                while (abs(vx) >= MIN_FLING_PX_PER_SECOND || abs(vy) >= MIN_FLING_PX_PER_SECOND) {
                    val frameNanos = withFrameNanos { it }
                    val dtSeconds = ((frameNanos - lastFrameNanos) / 1_000_000_000f)
                        .coerceIn(0f, MAX_FRAME_DELTA_SECONDS)
                    lastFrameNanos = frameNanos
                    val maxStep = globeRadiusPx * MAX_FLING_RADIUS_FRACTION_PER_FRAME
                    rotateBy(
                        (vx * dtSeconds).coerceIn(-maxStep, maxStep),
                        (vy * dtSeconds).coerceIn(-maxStep, maxStep)
                    )
                    val decay = exp(-FLING_FRICTION_PER_SECOND * dtSeconds)
                    vx *= decay
                    vy *= decay
                }
            } finally {
                if (animationGeneration == generation) {
                    isAnimating = false
                    animJob = null
                }
            }
        }
    }

    fun cancelAnimations() {
        animationGeneration++
        animJob?.cancel()
        animJob = null
        isAnimating = false
    }

    val isInMotion: Boolean get() = isInteracting || isAnimating

    private companion object {
        // Close to the projection limit so polar geohash cells remain selectable;
        // clamping tighter would make syncSelection() encode the wrong cell.
        const val MIN_LAT = -89f
        const val MAX_LAT = 89f
        const val MIN_FLING_PX_PER_SECOND = 90f
        const val MAX_FLING_PX_PER_SECOND = 3_200f
        const val MAX_FRAME_DELTA_SECONDS = 1f / 30f
        const val MAX_FLING_RADIUS_FRACTION_PER_FRAME = 0.12f
        const val FLING_FRICTION_PER_SECOND = 4.2f
    }

    private fun syncSelection() {
        if (baseRadiusPx <= 0f) return
        val gh = Geohash.encode(centerLat.toDouble(), centerLon.toDouble(), precision)
        if (gh != selectedGeohash) selectedGeohash = gh
    }
}

