/**
 * Read-only diagnostics describing how the currently running app was packaged
 * and installed. These values are facts about the installed artifact, not
 * settings that can be changed at runtime.
 */
object DistributionInfoProvider {
    private val UNIVERSAL_RELEASE_ABIS = setOf(
        "arm64-v8a",
        "armeabi-v7a",
        "x86_64",
        "x86"
    )

    fun inspect(context: Context): DistributionInfo {
        val packageInfo = context.packageManager.getPackageInfo(
            context.packageName,
            signingFlags()
        )
        val applicationInfo = context.applicationInfo
        val splitApks = applicationInfo.splitSourceDirs.orEmpty()
        val installerPackage = installerPackageName(context)
        val certificateSha256 = signingCertificateSha256(packageInfo)
        val installedApkVariant = if (splitApks.isEmpty()) {
            shareableApkVariant(File(applicationInfo.sourceDir))
        } else {
            null
        }

        return DistributionInfo(
            installSource = installSourceLabel(installerPackage),
            installerPackage = installerPackage,
            packageFormat = if (splitApks.isEmpty()) "Standalone APK" else "Split APK set",
            architecture = architectureLabel(applicationInfo.sourceDir, splitApks),
            sharingSource = when (installedApkVariant) {
                ShareableApkVariant.UNIVERSAL -> "Current installed APK"
                ShareableApkVariant.ARM64 -> "Current installed APK (ARM64)"
                null -> "Verified GitHub universal APK"
            },
            versionName = packageInfo.versionName ?: BuildConfig.VERSION_NAME,
            versionCode = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                packageInfo.longVersionCode
            } else {
                @Suppress("DEPRECATION")
                packageInfo.versionCode.toLong()
            },
            signingChannel = signingChannel(installerPackage, certificateSha256),
            certificateSha256 = certificateSha256
        )
    }

    private fun installerPackageName(context: Context): String? {
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                context.packageManager
                    .getInstallSourceInfo(context.packageName)
                    .installingPackageName
            } else {
                @Suppress("DEPRECATION")
                context.packageManager.getInstallerPackageName(context.packageName)
            }
        } catch (_: Exception) {
            null
        }
    }

    private fun installSourceLabel(installerPackage: String?): String {
        return when (installerPackage) {
            "com.android.vending" -> "Google Play"
            "com.amazon.venezia" -> "Amazon Appstore"
            "org.fdroid.fdroid" -> "F-Droid"
            "com.android.packageinstaller",
            "com.google.android.packageinstaller",
            "com.android.permissioncontroller" -> "Android package installer"
            null -> if (BuildConfig.DEBUG) "ADB / local install" else "Unknown / local install"
            else -> installerPackage
        }
    }

    private fun architectureLabel(baseApkPath: String, splitApkPaths: Array<out String>): String {
        val apkPaths = listOf(baseApkPath) + splitApkPaths
        val packagedAbis = buildSet {
            apkPaths.forEach { path ->
                addAll(nativeAbisInApk(File(path)))
                addAll(abisInSplitName(File(path).name))
            }
        }

        return when {
            packagedAbis.containsAll(UNIVERSAL_RELEASE_ABIS) ->
                "Universal (${packagedAbis.joinToString()})"
            packagedAbis.size > 1 -> "Multi-ABI (${packagedAbis.joinToString()})"
            packagedAbis.size == 1 -> packagedAbis.single()
            splitApkPaths.isNotEmpty() -> "Device ABI (${Build.SUPPORTED_ABIS.firstOrNull() ?: "unknown"})"
            else -> "Universal (no native ABI payload)"
        }
    }

    /**
     * An APK with no native payload works across ABIs. When native libraries
     * are present, require every ABI produced by the release workflow.
     */
    fun isUniversalApk(apk: File): Boolean {
        val packagedAbis = nativeAbisInApk(apk)
        return packagedAbis.isEmpty() || packagedAbis.containsAll(UNIVERSAL_RELEASE_ABIS)
    }

    /**
     * Returns the compatibility of an APK that is safe to offer for sharing.
     * ARM64 is intentionally the only architecture-limited release variant
     * supported because it is the project's primary per-ABI build.
     */
    fun shareableApkVariant(apk: File): ShareableApkVariant? {
        val packagedAbis = nativeAbisInApk(apk)
        return when {
            packagedAbis.isEmpty() || packagedAbis.containsAll(UNIVERSAL_RELEASE_ABIS) ->
                ShareableApkVariant.UNIVERSAL
            packagedAbis == setOf("arm64-v8a") -> ShareableApkVariant.ARM64
            else -> null
        }
    }

    internal fun nativeAbisInApk(apk: File): Set<String> {
        if (!apk.isFile) return emptySet()
        return try {
            ZipFile(apk).use { zip ->
                buildSet {
                    val entries = zip.entries()
                    while (entries.hasMoreElements()) {
                        val path = entries.nextElement().name
                        if (path.startsWith("lib/")) {
                            path.split('/').getOrNull(1)
                                ?.takeIf { it.isNotBlank() }
                                ?.let(::add)
                        }
                    }
                }
            }
        } catch (_: Exception) {
            emptySet()
        }
    }

    private fun abisInSplitName(fileName: String): Set<String> {
        val normalizedName = fileName.replace('_', '-')
        return Build.SUPPORTED_ABIS
            .filter { abi -> normalizedName.contains(abi.replace('_', '-'), ignoreCase = true) }
            .toSet()
    }

    private fun signingChannel(installerPackage: String?, certificateSha256: String?): String {
        if (BuildConfig.DEBUG) return "Debug"
        if (installerPackage == "com.android.vending") return "Google Play"

        val pinnedGitHubCert = BuildConfig.GITHUB_RELEASE_CERT_SHA256
            .replace(":", "")
            .lowercase()
            .takeIf { it.matches(Regex("[a-f0-9]{64}")) }
        return if (certificateSha256 != null && certificateSha256 == pinnedGitHubCert) {
            "GitHub release"
        } else {
            "Release / unknown channel"
        }
    }

    private fun signingCertificateSha256(packageInfo: PackageInfo): String? {
        val signatures = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            packageInfo.signingInfo?.apkContentsSigners
        } else {
            @Suppress("DEPRECATION")
            packageInfo.signatures
        }
        val signature = signatures?.firstOrNull() ?: return null
        return MessageDigest.getInstance("SHA-256")
            .digest(signature.toByteArray())
            .joinToString("") { "%02x".format(it) }
    }

    private fun signingFlags(): Int {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            PackageManager.GET_SIGNING_CERTIFICATES
        } else {
            @Suppress("DEPRECATION")
            PackageManager.GET_SIGNATURES
        }
    }

    data class DistributionInfo(
        val installSource: String,
        val installerPackage: String?,
        val packageFormat: String,
        val architecture: String,
        val sharingSource: String,
        val versionName: String,
        val versionCode: Long,
        val signingChannel: String,
        val certificateSha256: String?
    )
}

enum class ShareableApkVariant {
    UNIVERSAL,
    ARM64
}

package com.bitchat.android.util

import android.util.Log
import com.bitchat.android.net.ArtiTorManager
import com.bitchat.android.net.OkHttpProvider
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import okhttp3.Request
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

/**
 * Client for fetching BitChat release information from GitHub API.
 */
object GitHubReleaseClient {
    private const val TAG = "GitHubAPI"
    private const val GITHUB_API_URL = "https://api.github.com/repos/permissionlesstech/bitchat-android/releases/latest"
    private const val USER_AGENT = "BitChat-Android"
    private const val CACHE_TTL_MILLIS = 10 * 60 * 1000L
    private const val MAX_FETCH_ATTEMPTS = 3
    private const val ROUTE_READY_TIMEOUT_MILLIS = 60_000L

    private val fetchMutex = Mutex()

    @Volatile
    private var cachedRelease: CachedRelease? = null

    private val client
        get() = OkHttpProvider.httpClient().newBuilder()
            // GitHub requests may travel through Tor, where a 15-second total
            // timeout is too aggressive during circuit establishment.
            .callTimeout(45, TimeUnit.SECONDS)
            .connectTimeout(20, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .build()

    /**
     * Fetch the latest release information from GitHub.
     * Successful metadata is cached briefly so the status screen and download
     * worker use the same release snapshot instead of making duplicate calls.
     */
    suspend fun fetchLatestRelease(forceRefresh: Boolean = false): Result<Release> =
        withContext(Dispatchers.IO) {
            fetchMutex.withLock {
                if (!forceRefresh) {
                    cachedRelease
                        ?.takeIf { System.currentTimeMillis() - it.fetchedAtMillis < CACHE_TTL_MILLIS }
                        ?.let { return@withLock Result.success(it.release) }
                }

                if (!awaitSelectedNetworkRoute()) {
                    return@withLock Result.failure(
                        ReleaseFetchException(
                            message = "Tor is still connecting. Try again when Tor is ready.",
                            retryable = true
                        )
                    )
                }

                var lastFailure: Throwable = ReleaseFetchException(
                    "Failed to fetch the latest release from GitHub"
                )

                repeat(MAX_FETCH_ATTEMPTS) { attempt ->
                    val result = fetchLatestReleaseOnce()
                    result.onSuccess { release ->
                        cachedRelease = CachedRelease(release, System.currentTimeMillis())
                        return@withLock Result.success(release)
                    }
                    lastFailure = result.exceptionOrNull() ?: lastFailure

                    if (!isRetryable(lastFailure) || attempt == MAX_FETCH_ATTEMPTS - 1) {
                        return@withLock Result.failure(lastFailure)
                    }

                    delay(1_000L shl attempt)
                }

                Result.failure(lastFailure)
            }
        }

    /**
     * Wait for Tor when it is the selected route. This deliberately does not
     * fall back to a direct connection because doing so would violate the
     * user's Tor preference.
     */
    suspend fun awaitSelectedNetworkRoute(): Boolean {
        return ArtiTorManager.getInstance()
            .awaitSelectedRoute(ROUTE_READY_TIMEOUT_MILLIS)
    }

    private fun fetchLatestReleaseOnce(): Result<Release> {
        return try {
            Log.d(TAG, "Fetching latest release from GitHub API")
            val request = Request.Builder()
                .url(GITHUB_API_URL)
                .addHeader("User-Agent", USER_AGENT)
                .addHeader("Accept", "application/vnd.github+json")
                .addHeader("X-GitHub-Api-Version", "2022-11-28")
                .build()

            client.newCall(request).execute().use { response ->
                if (!response.isSuccessful) {
                    val remaining = response.header("X-RateLimit-Remaining")
                    val resetAt = response.header("X-RateLimit-Reset")
                    val message = when {
                        response.code == 403 && remaining == "0" ->
                            "GitHub API rate limit exceeded. Try again after reset time $resetAt."
                        response.code == 429 ->
                            "GitHub API rate limit exceeded. Please try again later."
                        else ->
                            "GitHub release request failed: HTTP ${response.code} ${response.message}"
                    }
                    Log.e(TAG, message)
                    return Result.failure(
                        ReleaseFetchException(
                            message = message,
                            httpCode = response.code,
                            retryable = response.code == 403 ||
                                response.code == 408 ||
                                response.code == 429 ||
                                response.code >= 500
                        )
                    )
                }

                val body = response.body?.string()
                if (body.isNullOrBlank()) {
                    return Result.failure(
                        ReleaseFetchException(
                            message = "GitHub returned an empty response",
                            retryable = true
                        )
                    )
                }

                val release = parseRelease(body)
                    ?: return Result.failure(
                        ReleaseFetchException(
                            message = "GitHub's latest release has no universal APK asset",
                            retryable = false
                        )
                    )
                Result.success(release)
            }
        } catch (e: IOException) {
            Log.e(TAG, "Network error fetching release", e)
            Result.failure(
                ReleaseFetchException(
                    "Could not reach GitHub${e.message?.let { ": $it" } ?: ""}",
                    cause = e
                )
            )
        } catch (e: Exception) {
            Log.e(TAG, "Error fetching release", e)
            Result.failure(ReleaseFetchException("Invalid GitHub release response", cause = e))
        }
    }

    private fun isRetryable(error: Throwable): Boolean {
        return error !is ReleaseFetchException || error.retryable
    }

    /**
     * Parse GitHub API JSON response into Release object.
     */
    internal fun parseRelease(jsonString: String): Release? {
        try {
            val json = JSONObject(jsonString)
            val tagName = json.optString("tag_name", "")
            val versionName = tagName.removePrefix("v") // Remove "v" prefix if present

            if (versionName.isBlank()) {
                Log.e(TAG, "No version tag found in release")
                return null
            }

            Log.d(TAG, "Found release: $versionName")

            // Parse assets array to find universal APK
            val assets = json.optJSONArray("assets")
            if (assets == null || assets.length() == 0) {
                Log.e(TAG, "No assets found in release")
                return null
            }

            // Look for universal APK (usually named "app-universal-release.apk")
            for (i in 0 until assets.length()) {
                val asset = assets.getJSONObject(i)
                val name = asset.optString("name", "")

                if (name.contains("universal", ignoreCase = true) && name.endsWith(".apk")) {
                    val downloadUrl = asset.optString("browser_download_url", "")
                    val size = asset.optLong("size", 0L)

                    if (downloadUrl.isBlank()) {
                        Log.e(TAG, "Universal APK found but no download URL")
                        continue
                    }

                    // Prefer GitHub's asset digest when available, then fall
                    // back to release notes used by older releases.
                    val body = json.optString("body", "")
                    val assetDigest = asset.optString("digest", "")
                        .takeIf { it.startsWith("sha256:", ignoreCase = true) }
                        ?.substringAfter(":")
                        ?.takeIf { it.matches(Regex("[a-fA-F0-9]{64}")) }
                        ?.lowercase()
                    val sha256 = assetDigest ?: extractSha256FromBody(body, name)

                    Log.d(TAG, "Found universal APK: $name (${size / 1024 / 1024}MB)")

                    return Release(
                        tagName = tagName,
                        versionName = versionName,
                        universalApkUrl = downloadUrl,
                        universalApkSha256 = sha256,
                        universalApkSize = size,
                        universalApkName = name
                    )
                }
            }

            Log.e(TAG, "No universal APK found in release assets")
            return null

        } catch (e: Exception) {
            Log.e(TAG, "Error parsing release JSON", e)
            return null
        }
    }

    /**
     * Extract SHA256 checksum from release body/notes.
     * Looks for patterns like:
     * - sha256:abc123...
     * - SHA256: abc123...
     * - app-universal-release.apk: abc123...
     */
    private fun extractSha256FromBody(body: String, apkName: String): String? {
        if (body.isBlank()) return null

        try {
            // Pattern 1: Look for "sha256:" followed by hash
            val sha256Pattern = Regex("""sha256:\s*([a-fA-F0-9]{64})""", RegexOption.IGNORE_CASE)
            sha256Pattern.find(body)?.let { match ->
                return match.groupValues[1].lowercase()
            }

            // Pattern 2: Look for APK name followed by hash
            val apkPattern = Regex("""${Regex.escape(apkName)}.*?([a-fA-F0-9]{64})""", RegexOption.IGNORE_CASE)
            apkPattern.find(body)?.let { match ->
                return match.groupValues[1].lowercase()
            }

            Log.w(TAG, "Could not extract SHA256 from release body")
            return null

        } catch (e: Exception) {
            Log.w(TAG, "Error extracting SHA256", e)
            return null
        }
    }

    /**
     * Check if a newer version is available.
     * @param currentVersion Current installed/cached version
     * @param latestRelease Latest release from GitHub
     * @return true if latestRelease is newer
     */
    fun isNewerVersion(currentVersion: String, latestRelease: Release): Boolean {
        return isNewerVersion(currentVersion, latestRelease.versionName)
    }

    internal fun isNewerVersion(currentVersion: String, candidateVersion: String): Boolean {
        return try {
            // Simple version comparison (assumes semantic versioning)
            // Remove any non-numeric prefixes
            val current = currentVersion.removePrefix("v").trim()
            val latest = candidateVersion.removePrefix("v").trim()

            if (current == latest) {
                return false
            }

            // Split by dots and compare each part
            val currentParts = current.split(".").mapNotNull { it.toIntOrNull() }
            val latestParts = latest.split(".").mapNotNull { it.toIntOrNull() }

            val maxLength = maxOf(currentParts.size, latestParts.size)

            for (i in 0 until maxLength) {
                val currentPart = currentParts.getOrNull(i) ?: 0
                val latestPart = latestParts.getOrNull(i) ?: 0

                if (latestPart > currentPart) {
                    return true
                } else if (latestPart < currentPart) {
                    return false
                }
            }

            false
        } catch (e: Exception) {
            Log.e(TAG, "Error comparing versions", e)
            false
        }
    }

    /**
     * Release information from GitHub.
     */
    data class Release(
        val tagName: String,
        val versionName: String,
        val universalApkUrl: String,
        val universalApkSha256: String?,
        val universalApkSize: Long,
        val universalApkName: String
    )

    class ReleaseFetchException(
        message: String,
        val httpCode: Int? = null,
        val retryable: Boolean = true,
        cause: Throwable? = null
    ) : IOException(message, cause)

    private data class CachedRelease(
        val release: Release,
        val fetchedAtMillis: Long
    )
}

package com.bitchat.android.util

import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import android.util.Log
import com.bitchat.android.BuildConfig
import com.bitchat.android.net.OkHttpProvider
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import okhttp3.Call
import okhttp3.Callback
import okhttp3.Request
import okhttp3.Response
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.io.IOException
import java.nio.file.AtomicMoveNotSupportedException
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.security.MessageDigest

/**
 * Manages local and downloaded APK artifacts for offline sharing.
 */
class UniversalApkManager(private val context: Context) {

    companion object {
        private const val TAG = "UniversalApk"
        private const val CACHE_DIR_NAME = "universal_apk"
        private const val METADATA_FILE_NAME = "universal_apk_info.json"
        private const val PROGRESS_FILE_NAME = "download_progress.json"
        private const val APK_FILE_PREFIX = "bitchat-universal-"

        // Download buffer size (128KB)
        private const val BUFFER_SIZE = 128 * 1024
    }

    private val cacheDir: File
        get() = File(context.cacheDir, CACHE_DIR_NAME).also { it.mkdirs() }

    private val metadataFile: File get() = File(cacheDir, METADATA_FILE_NAME)
    private val progressFile: File get() = File(cacheDir, PROGRESS_FILE_NAME)

    // Download client: inherits Tor proxy settings but with no call timeout
    // for large file downloads that can take minutes
    private val downloadClient
        get() = OkHttpProvider.httpClient().newBuilder()
            .callTimeout(0, java.util.concurrent.TimeUnit.SECONDS)
            .readTimeout(60, java.util.concurrent.TimeUnit.SECONDS)
            .build()

    /**
     * Get information about the cached sharing APK, if it exists.
     */
    fun getCachedApkInfo(): ApkInfo? {
        return try {
            if (!metadataFile.exists()) {
                return null
            }

            val json = JSONObject(metadataFile.readText())
            val version = json.optString("version", "")
            val checksum = json.optString("checksum", "")
            val downloadDate = json.optLong("downloadDate", 0L)
            val size = json.optLong("size", 0L)
            val fileName = json.optString("fileName", "")
            val source = runCatching {
                ApkSource.valueOf(json.optString("source", ApkSource.GITHUB.name))
            }.getOrDefault(ApkSource.GITHUB)

            if (version.isBlank() || fileName.isBlank()) {
                return null
            }

            val apkFile = File(cacheDir, fileName)
            if (!apkFile.exists()) {
                Log.w(TAG, "Metadata exists but APK file not found: ${apkFile.path}")
                return null
            }
            val variant = runCatching {
                ShareableApkVariant.valueOf(json.optString("variant"))
            }.getOrNull() ?: DistributionInfoProvider.shareableApkVariant(apkFile)
            if (variant == null) {
                Log.w(TAG, "Cached APK is not a supported sharing variant")
                return null
            }

            ApkInfo(
                version = version,
                checksum = checksum,
                downloadDate = downloadDate,
                size = size,
                file = apkFile,
                source = source,
                variant = variant
            )
        } catch (e: Exception) {
            Log.e(TAG, "Error reading cached APK info", e)
            null
        }
    }

    /**
     * Get the cached APK file, if it exists.
     */
    fun getCachedApk(): File? {
        return getCachedApkInfo()?.file
    }

    /**
     * Check if a partial (resumable) download exists.
     * Returns the progress percentage (0-100) or null if no partial download.
     */
    fun getPartialDownloadProgress(): Int? {
        val tempFile = File(cacheDir, "download_temp.apk")
        val resumeInfo = loadResumeInfo()
        if (tempFile.exists() && resumeInfo != null) {
            val expectedSize = resumeInfo.optLong("expectedSize", 0L)
            if (expectedSize > 0) {
                return ((tempFile.length() * 100) / expectedSize).toInt().coerceIn(0, 99)
            }
        }
        return null
    }

    /**
     * Check for updates from GitHub.
     * @return UpdateStatus indicating if update is available, current version, etc.
     */
    suspend fun checkForUpdate(): UpdateStatus = withContext(Dispatchers.IO) {
        try {
            // A supported standalone APK is already an installable sharing
            // artifact. Split installs still need the universal GitHub artifact.
            val installedApkInfo = cacheInstalledApkIfPreferred()
            if (installedApkInfo?.source == ApkSource.INSTALLED) {
                return@withContext UpdateStatus.UpToDate(installedApkInfo.version)
            }

            val cachedInfo = getCachedApkInfo()
            val latestRelease = GitHubReleaseClient.fetchLatestRelease().getOrElse { error ->
                return@withContext UpdateStatus.Error(
                    error.message ?: "Failed to fetch latest release from GitHub"
                )
            }
            // The GitHub release may briefly lag behind the installed version
            // (upstream bumps versionName in main before tagging the release).
            // An older release is still a genuine, signed, universal artifact —
            // recipients with a newer install can't be downgraded by Android
            // anyway — so share it rather than disabling the feature.
            if (isOlderThanInstalledVersion(latestRelease.versionName)) {
                Log.i(
                    TAG,
                    "GitHub universal APK ${latestRelease.versionName} is older than installed " +
                        "app ${installedVersionName()}; sharing it until the matching release ships"
                )
            }

            if (cachedInfo == null) {
                // No cached APK
                return@withContext UpdateStatus.NotDownloaded(latestRelease)
            }

            // Compare versions
            val isNewer = GitHubReleaseClient.isNewerVersion(cachedInfo.version, latestRelease)

            if (isNewer) {
                UpdateStatus.UpdateAvailable(
                    currentVersion = cachedInfo.version,
                    latestRelease = latestRelease
                )
            } else {
                UpdateStatus.UpToDate(cachedInfo.version)
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error checking for update", e)
            UpdateStatus.Error(e.message ?: "Unknown error")
        }
    }

    /**
     * Check if there's enough disk space to download the APK.
     * Requires 1.5x the file size for safety margin (temp + final file).
     * @throws IOException if insufficient space
     */
    private fun checkDiskSpace(requiredSize: Long) {
        val availableSpace = cacheDir.usableSpace
        val requiredWithMargin = (requiredSize * 1.5).toLong()

        if (availableSpace < requiredWithMargin) {
            val requiredMB = requiredWithMargin / 1024 / 1024
            val availableMB = availableSpace / 1024 / 1024
            val error = "Insufficient storage: need ${requiredMB}MB, have ${availableMB}MB"
            Log.e(TAG, error)
            throw IOException(error)
        }
    }

    /**
     * Download the universal APK from GitHub with resume support.
     * @param progressCallback Called with progress percentage (0-100)
     * @return Result with File on success, or error message
     */
    suspend fun downloadUniversalApk(
        progressCallback: ((Int) -> Unit)? = null
    ): Result<File> = withContext(Dispatchers.IO) {
        try {
            Log.d(TAG, "Starting universal APK download")

            // Fetch latest release info
            // Reuses the short-lived release metadata cache populated by the
            // status check. If this worker is running after process death, the
            // client performs a retried network fetch instead.
            val release = GitHubReleaseClient.fetchLatestRelease().getOrElse { error ->
                return@withContext Result.failure(error)
            }

            if (!GitHubReleaseClient.awaitSelectedNetworkRoute()) {
                return@withContext Result.failure(
                    IOException("Tor is still connecting. Try the download again when Tor is ready.")
                )
            }

            val url = release.universalApkUrl
            val expectedSize = release.universalApkSize

            Log.d(TAG, "Downloading from: $url")
            Log.d(TAG, "Expected size: ${expectedSize / 1024 / 1024}MB")

            val tempFile = File(cacheDir, "download_temp.apk")

            // Check for resumable download
            var existingBytes = 0L
            if (tempFile.exists()) {
                val resumeInfo = loadResumeInfo()
                if (resumeInfo != null &&
                    resumeInfo.optString("url") == url &&
                    resumeInfo.optString("versionName") == release.versionName
                ) {
                    existingBytes = tempFile.length()
                    Log.d(TAG, "Resuming download from $existingBytes bytes")
                } else {
                    Log.d(TAG, "Stale temp file found, starting fresh")
                    tempFile.delete()
                    progressFile.delete()
                }
            }

            // Bytes already in the temp file have already consumed storage, so
            // a resume only needs room for the remaining tail. Promotion is a
            // rename and needs no extra space.
            checkDiskSpace((expectedSize - existingBytes).coerceAtLeast(0))

            // A temp file that already holds the full asset means the process
            // died between download and verification. Requesting
            // "Range: bytes=<size>-" for it would get HTTP 416 forever, so skip
            // the network and let checksum/signature verification decide its fate.
            if (expectedSize > 0 && existingBytes >= expectedSize) {
                Log.d(TAG, "Temp file already complete ($existingBytes bytes), skipping to verification")
            } else {
                val requestBuilder = Request.Builder()
                    .url(url)
                    .addHeader("User-Agent", "BitChat-Android")

                if (existingBytes > 0) {
                    requestBuilder.addHeader("Range", "bytes=$existingBytes-")
                    Log.d(TAG, "Added Range header: bytes=$existingBytes-")
                }

                val request = requestBuilder.build()
                downloadToTempFile(
                    call = downloadClient.newCall(request),
                    tempFile = tempFile,
                    url = url,
                    expectedSize = expectedSize,
                    versionName = release.versionName,
                    existingBytes = existingBytes,
                    progressCallback = progressCallback
                )
            }

            // Verify checksum if available
            if (release.universalApkSha256 != null) {
                Log.d(TAG, "Verifying checksum...")
                val isValid = verifyChecksum(tempFile, release.universalApkSha256)
                if (!isValid) {
                    tempFile.delete()
                    progressFile.delete()
                    return@withContext Result.failure(
                        Exception("Checksum verification failed. Downloaded file may be corrupted.")
                    )
                }
                Log.d(TAG, "Checksum verified successfully")
            } else {
                Log.w(TAG, "No checksum available for verification")
            }

            // Verify the downloaded APK against trusted signing certificates.
            Log.d(TAG, "Verifying APK signature...")
            if (!verifyApkSignature(tempFile)) {
                tempFile.delete()
                progressFile.delete()
                return@withContext Result.failure(
                    Exception("APK signature verification failed. The downloaded APK is not signed by a trusted BitChat release key.")
                )
            }
            Log.d(TAG, "Signature verified successfully")

            if (!DistributionInfoProvider.isUniversalApk(tempFile)) {
                tempFile.delete()
                progressFile.delete()
                return@withContext Result.failure(
                    Exception(
                        "GitHub asset is architecture-specific, not universal. " +
                            "Release packaging must be corrected."
                    )
                )
            }

            // Move to final location without deleting the currently usable APK
            // first. Old versions are removed only after the replacement and
            // metadata have both been committed.
            val finalFileName = "$APK_FILE_PREFIX${release.versionName}.apk"
            val finalFile = File(cacheDir, finalFileName)
            replaceFileSafely(tempFile, finalFile)

            // Clean up resume metadata on success
            progressFile.delete()

            // Save metadata
            saveMetadata(
                version = release.versionName,
                checksum = release.universalApkSha256 ?: "",
                size = finalFile.length(),
                fileName = finalFileName,
                source = ApkSource.GITHUB,
                variant = ShareableApkVariant.UNIVERSAL
            )
            cleanupOldApks(except = finalFile)

            Log.d(TAG, "Universal APK downloaded successfully: ${finalFile.path}")
            Result.success(finalFile)

        } catch (e: CancellationException) {
            throw e
        } catch (e: IOException) {
            Log.e(TAG, "Network error downloading APK", e)
            Result.failure(e)
        } catch (e: Exception) {
            Log.e(TAG, "Error downloading APK", e)
            Result.failure(e)
        }
    }

    /**
     * Streams an HTTP response into [tempFile] while keeping the coroutine
     * suspended for the lifetime of the response body. Cancelling the worker
     * therefore cancels the OkHttp call and promptly unblocks a pending read.
     */
    private suspend fun downloadToTempFile(
        call: Call,
        tempFile: File,
        url: String,
        expectedSize: Long,
        versionName: String,
        existingBytes: Long,
        progressCallback: ((Int) -> Unit)?
    ) = suspendCancellableCoroutine { continuation ->
        fun completeSuccessfully() {
            continuation.resumeWith(Result.success(Unit))
        }

        fun completeWithError(error: Throwable) {
            continuation.resumeWith(Result.failure(error))
        }

        continuation.invokeOnCancellation {
            call.cancel()
        }

        try {
            call.enqueue(object : Callback {
                override fun onFailure(call: Call, e: IOException) {
                    completeWithError(e)
                }

                override fun onResponse(call: Call, response: Response) {
                    try {
                        response.use {
                            if (response.code == 416) {
                                // Our offset is no longer valid for this asset; discard
                                // the partial state so the retry starts from scratch.
                                Log.w(TAG, "Server rejected resume range, restarting download")
                                tempFile.delete()
                                progressFile.delete()
                                throw IOException(
                                    "Resume rejected by server. Download will restart."
                                )
                            }
                            if (!response.isSuccessful && response.code != 206) {
                                throw IOException(
                                    "Download failed: ${response.code} ${response.message}"
                                )
                            }

                            val body = response.body
                                ?: throw IOException("Empty response body")

                            // Handle resume: 206 = partial content (append), 200 = full
                            // content (overwrite).
                            val append = response.code == 206
                            val resumedBytes = if (!append && existingBytes > 0) {
                                Log.d(
                                    TAG,
                                    "Server didn't honor Range request, starting from scratch"
                                )
                                0L
                            } else {
                                existingBytes
                            }

                            saveResumeInfo(url, expectedSize, versionName)

                            if (resumedBytes > 0 && expectedSize > 0) {
                                val initialProgress =
                                    ((resumedBytes * 100) / expectedSize).toInt()
                                progressCallback?.invoke(initialProgress)
                            }

                            body.byteStream().use { input ->
                                FileOutputStream(tempFile, append).use { output ->
                                    val buffer = ByteArray(BUFFER_SIZE)
                                    var bytesRead: Int
                                    var totalBytesRead = resumedBytes
                                    var lastProgress = if (expectedSize > 0) {
                                        ((resumedBytes * 100) / expectedSize).toInt()
                                    } else {
                                        0
                                    }

                                    while (input.read(buffer).also { bytesRead = it } != -1) {
                                        output.write(buffer, 0, bytesRead)
                                        totalBytesRead += bytesRead

                                        if (expectedSize > 0) {
                                            val progress =
                                                ((totalBytesRead * 100) / expectedSize).toInt()
                                            if (progress != lastProgress) {
                                                lastProgress = progress
                                                progressCallback?.invoke(progress)
                                            }
                                        }
                                    }

                                    Log.d(
                                        TAG,
                                        "Download complete: ${totalBytesRead / 1024 / 1024}MB"
                                    )
                                }
                            }
                        }
                        completeSuccessfully()
                    } catch (e: Exception) {
                        completeWithError(e)
                    }
                }
            })
        } catch (e: Exception) {
            completeWithError(e)
        }
    }

    /**
     * Cache the APK this process was installed from when it is a standalone
     * universal or ARM64 artifact. A base APK from a split install is incomplete.
     */
    private fun cacheInstalledApkIfPreferred(): ApkInfo? {
        return try {
            val applicationInfo = context.applicationInfo
            if (!applicationInfo.splitSourceDirs.isNullOrEmpty()) {
                return null
            }

            val installedApk = File(applicationInfo.sourceDir)
            if (!installedApk.isFile || installedApk.length() <= 0L) {
                return null
            }
            val installedVariant = DistributionInfoProvider.shareableApkVariant(installedApk)
            if (installedVariant == null) {
                Log.d(TAG, "Installed APK is not a supported sharing variant")
                return null
            }

            val installedVersion = installedVersionName()
            val cachedInfo = getCachedApkInfo()

            // Downloading the universal release is an explicit compatibility
            // choice. Keep it even when the running ARM64 build is newer; the
            // user can delete it from the UI to return to the local artifact.
            if (installedVariant == ShareableApkVariant.ARM64 &&
                cachedInfo?.source == ApkSource.GITHUB &&
                cachedInfo.variant == ShareableApkVariant.UNIVERSAL
            ) {
                return cachedInfo
            }

            // Keep an already cached artifact if it is the same version or
            // newer. Otherwise prefer the running build so sharing cannot
            // silently downgrade recipients to an older GitHub release.
            if (cachedInfo != null &&
                !GitHubReleaseClient.isNewerVersion(cachedInfo.version, installedVersion)
            ) {
                return cachedInfo
            }

            checkDiskSpace(installedApk.length())
            val safeVersion = installedVersion.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val variantSuffix = when (installedVariant) {
                ShareableApkVariant.UNIVERSAL -> ""
                ShareableApkVariant.ARM64 -> "-arm64-v8a"
            }
            val finalFileName = "$APK_FILE_PREFIX$safeVersion$variantSuffix.apk"
            val finalFile = File(cacheDir, finalFileName)
            val pendingFile = File(cacheDir, "$finalFileName.new")

            installedApk.inputStream().use { input ->
                FileOutputStream(pendingFile).use { output ->
                    input.copyTo(output, BUFFER_SIZE)
                }
            }
            replaceFileSafely(pendingFile, finalFile)

            val checksum = calculateChecksum(finalFile)
            saveMetadata(
                version = installedVersion,
                checksum = checksum,
                size = finalFile.length(),
                fileName = finalFileName,
                source = ApkSource.INSTALLED,
                variant = installedVariant
            )
            cleanupOldApks(except = finalFile)

            Log.d(TAG, "Cached running standalone APK for offline sharing")
            getCachedApkInfo()
        } catch (e: Exception) {
            Log.w(TAG, "Running APK cannot be used as a standalone sharing artifact", e)
            null
        }
    }

    private fun installedVersionName(): String {
        return context.packageManager
            .getPackageInfo(context.packageName, 0)
            .versionName
            ?.takeIf { it.isNotBlank() }
            ?: BuildConfig.VERSION_NAME
    }

    private fun isOlderThanInstalledVersion(candidateVersion: String): Boolean {
        return GitHubReleaseClient.isNewerVersion(candidateVersion, installedVersionName())
    }

    /**
     * Verify the downloaded APK against either the running app's signing lineage
     * or the pinned GitHub release certificate. The latter supports Play installs
     * when GitHub distribution uses a separate, explicitly trusted release key.
     * Debug builds without a configured pin accept any signed (never unsigned) APK.
     */
    private fun verifyApkSignature(apkFile: File): Boolean {
        return try {
            val packageInfo = context.packageManager.getPackageArchiveInfo(apkFile.absolutePath, signingFlags())
                ?: run {
                    Log.e(TAG, "Could not parse APK for signature verification")
                    return false
                }
            val apkCerts = signatureDigests(packageInfo)
            if (apkCerts.isEmpty()) {
                Log.e(TAG, "No signatures found in downloaded APK")
                return false
            }

            val ownCerts = signatureDigests(
                context.packageManager.getPackageInfo(context.packageName, signingFlags())
            )
            val pinnedReleaseCert = normalizeCertificateDigest(
                BuildConfig.GITHUB_RELEASE_CERT_SHA256
            )
            val trustedCerts = ownCerts + listOfNotNull(pinnedReleaseCert)

            // Debug builds may use a different local signing key, but still
            // require the downloaded artifact itself to be signed. Production
            // builds must match either this installation's signing lineage or
            // the explicitly pinned GitHub release certificate.
            if (BuildConfig.DEBUG && pinnedReleaseCert == null) {
                Log.w(TAG, "Debug build has no pinned release certificate; accepting signed APK")
                return true
            }

            if (trustedCerts.isEmpty()) {
                Log.e(TAG, "No trusted APK signing certificates are configured")
                return false
            }

            val matches = apkCerts.intersect(trustedCerts).isNotEmpty()
            if (!matches) {
                Log.e(TAG, "Signature mismatch!")
                Log.e(TAG, "Trusted cert(s): $trustedCerts")
                Log.e(TAG, "APK cert(s): $apkCerts")
            }
            matches
        } catch (e: Exception) {
            Log.e(TAG, "Error verifying APK signature", e)
            false
        }
    }

    private fun signingFlags(): Int {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            PackageManager.GET_SIGNING_CERTIFICATES
        } else {
            @Suppress("DEPRECATION")
            PackageManager.GET_SIGNATURES
        }
    }

    private fun signatureDigests(packageInfo: android.content.pm.PackageInfo): Set<String> {
        val signatures = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            val signingInfo = packageInfo.signingInfo ?: return emptySet()
            if (signingInfo.hasMultipleSigners()) {
                signingInfo.apkContentsSigners
            } else {
                signingInfo.signingCertificateHistory
            }
        } else {
            @Suppress("DEPRECATION")
            packageInfo.signatures
        }
        if (signatures.isNullOrEmpty()) return emptySet()

        val digest = MessageDigest.getInstance("SHA-256")
        return signatures.map { sig ->
            digest.digest(sig.toByteArray()).joinToString("") { "%02x".format(it) }
        }.toSet()
    }

    private fun normalizeCertificateDigest(value: String): String? {
        return value
            .replace(":", "")
            .trim()
            .lowercase()
            .takeIf { it.matches(Regex("[a-f0-9]{64}")) }
    }

    /**
     * Verify the SHA256 checksum of a file.
     */
    suspend fun verifyChecksum(file: File, expectedSha256: String): Boolean = withContext(Dispatchers.IO) {
        try {
            val checksum = calculateChecksum(file)
            val matches = checksum.equals(expectedSha256, ignoreCase = true)

            if (!matches) {
                Log.e(TAG, "Checksum mismatch!")
                Log.e(TAG, "Expected: $expectedSha256")
                Log.e(TAG, "Actual:   $checksum")
            }

            matches
        } catch (e: Exception) {
            Log.e(TAG, "Error verifying checksum", e)
            false
        }
    }

    private fun calculateChecksum(file: File): String {
        val digest = MessageDigest.getInstance("SHA-256")
        file.inputStream().use { input ->
            val buffer = ByteArray(BUFFER_SIZE)
            var bytesRead: Int
            while (input.read(buffer).also { bytesRead = it } != -1) {
                digest.update(buffer, 0, bytesRead)
            }
        }
        return digest.digest().joinToString("") { "%02x".format(it) }
    }

    /**
     * Delete the cached universal APK.
     */
    fun deleteCachedApk(): Boolean {
        return try {
            val info = getCachedApkInfo()
            if (info != null) {
                info.file.delete()
                metadataFile.delete()
                progressFile.delete()
                Log.d(TAG, "Deleted cached APK: ${info.version}")
                true
            } else {
                Log.w(TAG, "No cached APK to delete")
                false
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error deleting cached APK", e)
            false
        }
    }

    /**
     * Clean up old APK files (keep only the current one).
     */
    private fun cleanupOldApks(except: File) {
        try {
            cacheDir.listFiles()?.forEach { file ->
                if (file != except &&
                    file.name.startsWith(APK_FILE_PREFIX) &&
                    file.name.endsWith(".apk")
                ) {
                    file.delete()
                    Log.d(TAG, "Cleaned up old APK: ${file.name}")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error cleaning up old APKs", e)
        }
    }

    /**
     * Save metadata about the downloaded APK.
     */
    private fun saveMetadata(
        version: String,
        checksum: String,
        size: Long,
        fileName: String,
        source: ApkSource,
        variant: ShareableApkVariant
    ) {
        val json = JSONObject().apply {
            put("version", version)
            put("checksum", checksum)
            put("downloadDate", System.currentTimeMillis())
            put("size", size)
            put("fileName", fileName)
            put("source", source.name)
            put("variant", variant.name)
        }

        val pendingMetadata = File(cacheDir, "$METADATA_FILE_NAME.new")
        pendingMetadata.writeText(json.toString())
        replaceFileSafely(pendingMetadata, metadataFile)
        Log.d(TAG, "Saved metadata: $version")
    }

    private fun saveResumeInfo(url: String, expectedSize: Long, versionName: String) {
        try {
            val json = JSONObject().apply {
                put("url", url)
                put("expectedSize", expectedSize)
                put("versionName", versionName)
            }
            progressFile.writeText(json.toString())
        } catch (e: Exception) {
            Log.e(TAG, "Error saving resume info", e)
        }
    }

    private fun loadResumeInfo(): JSONObject? {
        return try {
            if (progressFile.exists()) {
                JSONObject(progressFile.readText())
            } else null
        } catch (e: Exception) {
            Log.e(TAG, "Error loading resume info", e)
            null
        }
    }

    /**
     * Commit [source] to [target] without removing a valid target first.
     * Both files live in the same cache directory, so this is a rename, not a
     * copy — no extra disk space is needed and ATOMIC_MOVE either fully
     * succeeds or leaves both files intact.
     */
    private fun replaceFileSafely(source: File, target: File) {
        try {
            Files.move(
                source.toPath(),
                target.toPath(),
                StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING
            )
        } catch (_: AtomicMoveNotSupportedException) {
            Files.move(
                source.toPath(),
                target.toPath(),
                StandardCopyOption.REPLACE_EXISTING
            )
        }
    }

    /**
     * Information about a cached APK.
     */
    data class ApkInfo(
        val version: String,
        val checksum: String,
        val downloadDate: Long,
        val size: Long,
        val file: File,
        val source: ApkSource,
        val variant: ShareableApkVariant
    )

    enum class ApkSource {
        INSTALLED,
        GITHUB
    }

    /**
     * Update check status.
     */
    sealed class UpdateStatus {
        data class NotDownloaded(val latestRelease: GitHubReleaseClient.Release) : UpdateStatus()
        data class UpToDate(val currentVersion: String) : UpdateStatus()
        data class UpdateAvailable(
            val currentVersion: String,
            val latestRelease: GitHubReleaseClient.Release
        ) : UpdateStatus()
        data class Error(val message: String) : UpdateStatus()
    }
}

package com.bitchat.android.util

import android.content.Context
import androidx.work.Constraints
import androidx.work.BackoffPolicy
import com.bitchat.android.R
import androidx.work.ExistingWorkPolicy
import androidx.work.NetworkType
import androidx.work.OneTimeWorkRequestBuilder
import androidx.work.WorkInfo
import androidx.work.WorkManager
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import java.util.concurrent.TimeUnit

/**
 * WorkManager-backed implementation of [ApkDownloader].
 * Downloads survive app backgrounding, process death, and device reboots.
 */
class WorkManagerApkDownloader(context: Context) : ApkDownloader {

    private val appContext = context.applicationContext
    private val workManager = WorkManager.getInstance(appContext)
    private val apkManager = UniversalApkManager(appContext)

    override val downloadState: Flow<ApkDownloader.DownloadState> =
        workManager.getWorkInfosForUniqueWorkFlow(ApkDownloadWorker.WORK_NAME)
            .map { workInfos -> mapWorkInfoToState(workInfos.firstOrNull()) }

    override fun startDownload() {
        val constraints = Constraints.Builder()
            .setRequiredNetworkType(NetworkType.CONNECTED)
            .build()

        val request = OneTimeWorkRequestBuilder<ApkDownloadWorker>()
            .setConstraints(constraints)
            .setBackoffCriteria(
                BackoffPolicy.EXPONENTIAL,
                15,
                TimeUnit.SECONDS
            )
            .addTag(ApkDownloadWorker.TAG)
            .build()

        workManager.enqueueUniqueWork(
            ApkDownloadWorker.WORK_NAME,
            ExistingWorkPolicy.KEEP,
            request
        )
    }

    override fun cancelDownload() {
        workManager.cancelUniqueWork(ApkDownloadWorker.WORK_NAME)
    }

    private fun mapWorkInfoToState(workInfo: WorkInfo?): ApkDownloader.DownloadState {
        if (workInfo == null) return ApkDownloader.DownloadState.Idle

        return when (workInfo.state) {
            WorkInfo.State.ENQUEUED,
            WorkInfo.State.BLOCKED -> {
                // Waiting for constraints (network). Show existing partial progress if any.
                val partial = apkManager.getPartialDownloadProgress()
                ApkDownloader.DownloadState.Downloading(partial ?: 0)
            }
            WorkInfo.State.RUNNING -> {
                val progress = workInfo.progress.getInt(ApkDownloadWorker.KEY_PROGRESS, 0)
                ApkDownloader.DownloadState.Downloading(progress)
            }
            WorkInfo.State.SUCCEEDED -> {
                val version = workInfo.outputData.getString(ApkDownloadWorker.KEY_VERSION) ?: ""
                val sizeMB = workInfo.outputData.getInt(ApkDownloadWorker.KEY_SIZE_MB, 0)
                ApkDownloader.DownloadState.Success(version, sizeMB)
            }
            WorkInfo.State.FAILED -> {
                val error = workInfo.outputData.getString(ApkDownloadWorker.KEY_ERROR) ?: "Download failed"
                val resumable = workInfo.outputData.getInt(ApkDownloadWorker.KEY_RESUMABLE_PERCENT, -1)
                ApkDownloader.DownloadState.Failed(error, if (resumable >= 0) resumable else null)
            }
            WorkInfo.State.CANCELLED -> {
                val partial = apkManager.getPartialDownloadProgress()
                if (partial != null) {
                    ApkDownloader.DownloadState.Failed(
                        appContext.getString(R.string.prepare_apk_download_cancelled),
                        partial
                    )
                } else {
                    ApkDownloader.DownloadState.Idle
                }
            }
        }
    }
}

package com.bitchat.android.utils

import android.content.Context
import android.content.res.Configuration
import android.util.DisplayMetrics
import android.view.WindowManager
import androidx.core.content.getSystemService
import kotlin.math.sqrt

object DeviceUtils {

    /**
     * Determines if the current device is a tablet based on screen size and density.
     * Uses multiple criteria to accurately detect tablets vs phones.
     */
    fun isTablet(context: Context): Boolean {
        val windowManager = context.getSystemService<WindowManager>()
        val displayMetrics = DisplayMetrics()
        windowManager?.defaultDisplay?.getMetrics(displayMetrics)

        // Calculate screen size in inches
        val widthInches = displayMetrics.widthPixels / displayMetrics.xdpi
        val heightInches = displayMetrics.heightPixels / displayMetrics.ydpi
        val diagonalInches = sqrt((widthInches * widthInches) + (heightInches * heightInches))

        // Check if device has tablet configuration
        val configuration = context.resources.configuration
        val isLargeScreen = (configuration.screenLayout and Configuration.SCREENLAYOUT_SIZE_MASK) >= Configuration.SCREENLAYOUT_SIZE_LARGE
        val isXLargeScreen = (configuration.screenLayout and Configuration.SCREENLAYOUT_SIZE_MASK) == Configuration.SCREENLAYOUT_SIZE_XLARGE

        // A device is considered a tablet if:
        // 1. Screen diagonal is 7 inches or larger, OR
        // 2. Configuration indicates large or xlarge screen, OR
        // 3. Smallest width is 600dp or more (sw600dp)
        val smallestWidthDp = context.resources.configuration.smallestScreenWidthDp

        return diagonalInches >= 7.0 || isLargeScreen || isXLargeScreen || smallestWidthDp >= 600
    }
}

package com.bitchat.android.wifiaware

/** Resolves a packet to the exact still-active ingress link that delivered it. */
internal object IngressLinkPolicy {
    data class Link<T : Any>(
        val relayAddress: String,
        val transport: T
    )

    fun <T : Any> resolve(
        ingressLinkID: String?,
        relayAddress: String?,
        links: Map<String, Link<T>>,
        currentTransportForRelay: (String) -> T?
    ): Link<T>? {
        val linkID = ingressLinkID ?: return null
        val relayAddress = relayAddress ?: return null
        val link = links[linkID] ?: return null
        if (link.relayAddress != relayAddress) return null
        return link.takeIf { currentTransportForRelay(relayAddress) === it.transport }
    }
}

package com.bitchat.android.wifiaware

import java.io.DataInputStream
import java.io.DataOutputStream
import java.io.IOException
import java.net.Socket
import java.util.concurrent.locks.ReentrantLock
import kotlin.concurrent.withLock
import android.util.Log

/**
 * A synchronized wrapper around a raw Socket that implements a framed protocol:
 * [4 bytes length][N bytes payload]
 */
class SyncedSocket(
    val rawSocket: Socket,
    readTimeoutMs: Int = DEFAULT_READ_TIMEOUT_MS
) {
    private val TAG = "SyncedSocket"
    private val writeLock = ReentrantLock()
    private val readLock = ReentrantLock()

    private val inputStream: DataInputStream
    private val outputStream: DataOutputStream

    companion object {
        // Critical-background peers send at most every 30s. Tolerate three missed frames so a
        // faster local profile cannot drop a healthy, slower remote peer merely for being idle.
        const val DEFAULT_READ_TIMEOUT_MS = 90_000
    }

    init {
        // A read timeout converts dead/half-open connections into a SocketTimeoutException
        // (an IOException) so read() returns null and the peer is cleaned up.
        try { rawSocket.soTimeout = readTimeoutMs } catch (_: Exception) {}
        // We wrap streams to create DataInput/Output helpers
        inputStream = DataInputStream(rawSocket.getInputStream())
        outputStream = DataOutputStream(rawSocket.getOutputStream())
    }

    /**
     * Writes a framed message to the socket.
     * Thread-safe.
     */
    fun write(data: ByteArray) {
        writeLock.withLock {
            Log.v(TAG, "Writing frame of size: ${data.size}")
            outputStream.writeInt(data.size)
            if (data.isNotEmpty()) {
                outputStream.write(data)
            }
            outputStream.flush()
        }
    }

    /**
     * Reads a framed message from the socket.
     * Blocks until a full frame is available.
     * Returns null if socket is closed or EOF.
     * Returns empty byte array for keep-alive (0 length frame).
     */
    fun read(): ByteArray? {
        readLock.withLock {
            try {
                // Read length prefix
                val length = try {
                    inputStream.readInt()
                } catch (e: java.io.EOFException) {
                    return null
                }
                Log.v(TAG, "Reading frame of size: $length")

                if (length < 0) throw IOException("Negative frame length: $length")
                if (length > 64 * 1024) throw IOException("Frame length exceeds 64KB limit: $length")

                if (length == 0) {
                    return ByteArray(0)
                }

                val buf = ByteArray(length)
                inputStream.readFully(buf)
                return buf
            } catch (e: IOException) {
                Log.e(TAG, "Socket read failed: ${e.message}")
                // Socket closed or error
                return null
            }
        }
    }

    fun close() {
        try { rawSocket.close() } catch (_: Exception) {}
    }

    fun isClosed() = rawSocket.isClosed
    fun isConnected() = rawSocket.isConnected
    val inetAddress get() = rawSocket.inetAddress
}

package com.bitchat.android.wifiaware

import android.net.ConnectivityManager
import android.util.Log
import com.bitchat.android.mesh.MeshConnectionTracker
import kotlinx.coroutines.CoroutineScope
import java.net.ServerSocket
import java.net.Socket
import java.util.concurrent.ConcurrentHashMap

/**
 * Tracks Wi-Fi Aware connections and manages retry logic using the shared state machine.
 */
class WifiAwareConnectionTracker(
    scope: CoroutineScope,
    private val cm: ConnectivityManager
) : MeshConnectionTracker(scope, TAG) {

    companion object {
        private const val TAG = "WifiAwareConnectionTracker"
    }

    // Active resources per peer
    val peerSockets = ConcurrentHashMap<String, SyncedSocket>()
    private val socketAliases = ConcurrentHashMap<String, String>()
    private val socketBindingLock = Any()
    val serverSockets = ConcurrentHashMap<String, ServerSocket>()
    val networkCallbacks = ConcurrentHashMap<String, ConnectivityManager.NetworkCallback>()

    override fun isConnected(id: String): Boolean {
        // We consider it connected if we have a client socket to them
        return getSocketForPeer(id) != null
    }

    override fun disconnect(id: String) {
        synchronized(socketBindingLock) {
            Log.d(TAG, "Disconnecting peer $id")
            val canonicalId = resolveCanonicalPeerId(id)

            // 1. Close client socket
            peerSockets.remove(canonicalId)?.let {
                try { it.close() } catch (e: Exception) { Log.w(TAG, "Error closing socket for $id: ${e.message}") }
            }
            socketAliases.entries.removeIf { it.key == id || it.key == canonicalId || it.value == canonicalId }

            // 2. Close server socket
            serverSockets.remove(canonicalId)?.let {
                try { it.close() } catch (e: Exception) { Log.w(TAG, "Error closing server socket for $id: ${e.message}") }
            }

            // Ensure any pending/active network request is explicitly released
            releaseNetworkRequest(canonicalId)
            removePendingConnection(id)
            removePendingConnection(canonicalId)
        }
    }

    fun releaseNetworkRequest(id: String) {
        val canonicalId = resolveCanonicalPeerId(id)
        if (!networkCallbacks.containsKey(canonicalId)) return

        // 3. Unregister network callback properly from ConnectivityManager
        networkCallbacks.remove(canonicalId)?.let {
            try { 
                Log.d(TAG, "Unregistering network callback for $canonicalId")
                cm.unregisterNetworkCallback(it) 
            } catch (e: Exception) { Log.w(TAG, "Error unregistering callback for $canonicalId: ${e.message}") }
        }
    }

    override fun getConnectionCount(): Int = peerSockets.size

    /**
     * Successfully established a client connection
     */
    fun onClientConnected(peerId: String, socket: SyncedSocket) {
        synchronized(socketBindingLock) {
            val canonicalPeerId = resolveCanonicalPeerId(peerId)
            // Close previous socket if one exists to prevent zombie readers
            peerSockets[canonicalPeerId]?.let {
                try { it.close() } catch (_: Exception) {}
            }
            peerSockets[canonicalPeerId] = socket
            removePendingConnection(peerId) // Clear retry state on success
            if (canonicalPeerId != peerId) removePendingConnection(canonicalPeerId)
        }
    }

    fun getSocketForPeer(peerId: String): SyncedSocket? {
        val canonicalId = resolveCanonicalPeerId(peerId)
        return peerSockets[canonicalId]
    }

    fun canonicalPeerId(peerId: String): String = resolveCanonicalPeerId(peerId)

    fun rebindPeerId(previousPeerId: String, resolvedPeerId: String, socket: SyncedSocket): String {
        return synchronized(socketBindingLock) {
            rebindPeerIdLocked(previousPeerId, resolvedPeerId, socket)
        }
    }

    /**
     * Atomically require that [expectedSocket] is still the active provisional transport before
     * rebinding it. This closes the gap where a replacement socket could land after ANNOUNCE
     * validation but before mutation and the stale socket would become canonical.
     */
    fun rebindPeerIdIfCurrent(
        previousPeerId: String,
        resolvedPeerId: String,
        expectedSocket: SyncedSocket
    ): Boolean = synchronized(socketBindingLock) {
        val previousCanonical = resolveCanonicalPeerId(previousPeerId)
        if (peerSockets[previousCanonical] !== expectedSocket) return@synchronized false
        val resolvedCanonical = resolveCanonicalPeerId(resolvedPeerId)
        val existingResolvedSocket = peerSockets[resolvedCanonical]
        if (existingResolvedSocket != null && existingResolvedSocket !== expectedSocket) {
            return@synchronized false
        }
        rebindPeerIdLocked(previousPeerId, resolvedPeerId, expectedSocket)
        true
    }

    private fun rebindPeerIdLocked(
        previousPeerId: String,
        resolvedPeerId: String,
        socket: SyncedSocket
    ): String {
        if (previousPeerId == resolvedPeerId) {
            peerSockets[resolvedPeerId] = socket
            return resolvedPeerId
        }

        val previousCanonical = resolveCanonicalPeerId(previousPeerId)
        val existing = peerSockets[previousCanonical]
        if (existing === socket) {
            peerSockets.remove(previousCanonical)
        }

        peerSockets[resolvedPeerId]?.let { current ->
            if (current !== socket) {
                try { current.close() } catch (_: Exception) { }
            }
        }
        peerSockets[resolvedPeerId] = socket
        serverSockets.remove(previousCanonical)?.let { serverSockets[resolvedPeerId] = it }
        networkCallbacks.remove(previousCanonical)?.let { networkCallbacks[resolvedPeerId] = it }
        socketAliases[previousPeerId] = resolvedPeerId
        if (previousCanonical != previousPeerId) {
            socketAliases[previousCanonical] = resolvedPeerId
        }
        removePendingConnection(previousPeerId)
        removePendingConnection(resolvedPeerId)

        Log.i(TAG, "Rebound Wi-Fi Aware socket ${previousPeerId.take(8)} -> ${resolvedPeerId.take(8)}")
        return resolvedPeerId
    }

    private fun resolveCanonicalPeerId(peerId: String): String {
        var current = peerId
        val visited = mutableSetOf<String>()
        while (visited.add(current)) {
            val next = socketAliases[current] ?: return current
            current = next
        }
        return current
    }

    fun addServerSocket(peerId: String, socket: ServerSocket) {
        val canonicalId = resolveCanonicalPeerId(peerId)
        serverSockets.put(canonicalId, socket)?.let {
            try { it.close() } catch (e: Exception) { Log.w(TAG, "Error closing replaced server socket for $peerId: ${e.message}") }
        }
    }

    fun hasOpenServerSocket(peerId: String): Boolean {
        val canonicalId = resolveCanonicalPeerId(peerId)
        val socket = serverSockets[canonicalId] ?: return false
        if (!socket.isClosed) return true
        serverSockets.remove(canonicalId)
        return false
    }

    fun closeServerSocket(peerId: String) {
        val canonicalId = resolveCanonicalPeerId(peerId)
        serverSockets.remove(canonicalId)?.let {
            try { it.close() } catch (e: Exception) { Log.w(TAG, "Error closing server socket for $peerId: ${e.message}") }
        }
    }

    fun hasPendingDataPathRequest(exceptPeerId: String? = null): Boolean {
        val exceptCanonical = exceptPeerId?.let { resolveCanonicalPeerId(it) }
        return pendingDataPathPeerIds(exceptCanonical).isNotEmpty()
    }

    fun pendingDataPathPeerIds(exceptPeerId: String? = null): Set<String> {
        val exceptCanonical = exceptPeerId?.let { resolveCanonicalPeerId(it) }
        val pendingIds = linkedSetOf<String>()

        pendingConnections.keys.forEach { peerId ->
            val canonicalId = resolveCanonicalPeerId(peerId)
            if (canonicalId != exceptCanonical && !isConnected(canonicalId)) {
                pendingIds.add(canonicalId)
            }
        }

        networkCallbacks.keys.forEach { peerId ->
            val canonicalId = resolveCanonicalPeerId(peerId)
            if (canonicalId != exceptCanonical && !isConnected(canonicalId)) {
                pendingIds.add(canonicalId)
            }
        }

        return pendingIds
    }

    fun pendingServerDataPathPeerIds(exceptPeerId: String? = null): Set<String> {
        val exceptCanonical = exceptPeerId?.let { resolveCanonicalPeerId(it) }
        return serverSockets.keys.map { resolveCanonicalPeerId(it) }
            .filter { peerId ->
                peerId != exceptCanonical &&
                    !isConnected(peerId) &&
                    networkCallbacks.containsKey(peerId) &&
                    serverSockets[peerId]?.isClosed == false
            }
            .toSet()
    }

    fun cancelPendingServerDataPaths(exceptPeerId: String? = null): Set<String> {
        val cancelled = pendingServerDataPathPeerIds(exceptPeerId)
        cancelled.forEach { disconnect(it) }
        return cancelled
    }

    fun addNetworkCallback(peerId: String, callback: ConnectivityManager.NetworkCallback) {
        val canonicalId = resolveCanonicalPeerId(peerId)
        networkCallbacks.put(canonicalId, callback)?.let {
            try {
                Log.d(TAG, "Replacing network callback for $canonicalId")
                cm.unregisterNetworkCallback(it)
            } catch (e: Exception) {
                Log.w(TAG, "Error unregistering replaced callback for $canonicalId: ${e.message}")
            }
        }
    }

    /**
     * Clean up all resources
     */
    override fun stop() {
        super.stop()
        val allIds = peerSockets.keys + serverSockets.keys + networkCallbacks.keys
        allIds.toSet().forEach { disconnect(it) }
    }

    fun getDebugInfo(): String {
        return buildString {
            appendLine("Aware Connections: ${getConnectionCount()}")
            peerSockets.keys.forEach { pid ->
                appendLine("  - $pid (Socket)")
            }
            if (socketAliases.isNotEmpty()) {
                appendLine("Socket aliases:")
                socketAliases.forEach { (alias, canonical) ->
                    appendLine("  - $alias -> $canonical")
                }
            }
            appendLine("Server Sockets: ${serverSockets.size}")
            serverSockets.keys.forEach { pid ->
                appendLine("  - $pid (Listening)")
            }
            appendLine("Pending Attempts: ${pendingConnections.size}")
            pendingConnections.forEach { (pid, attempt) ->
                appendLine("  - $pid: ${attempt.attempts} attempts")
            }
        }
    }
}

package com.bitchat.android.wifiaware

import android.content.Context
import android.os.Build
import android.util.Log
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import androidx.annotation.VisibleForTesting
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicInteger

/**
 * WifiAwareController manages lifecycle and debug surfacing for the WifiAwareMeshService.
 * It starts/stops the service based on debug preferences and exposes simple flows for UI.
 */
object WifiAwareController {
    private const val TAG = "WifiAwareController"
    private const val MAX_RESTART_ATTEMPTS = 15
    private const val RESTART_RETRY_DELAY_MS = 2_000L

    private var service: WifiAwareMeshService? = null
    private var appContext: Context? = null
    private val lifecycleLock = Any()
    private var starting = false
    private val restartInFlight = AtomicBoolean(false)
    private val restartRequested = AtomicBoolean(false)
    private var awareReceiverRegistered = false
    private var lastBlockedReason: String? = null

    /**
     * How many hotspot sessions currently need the radio.
     *
     * Wi-Fi Aware (NAN) and Wi-Fi Direct (P2P) cannot hold interfaces at the same time on
     * common chipsets — the HAL fails to create the P2P iface and every createGroup is
     * answered with BUSY. A non-zero count also blocks [startIfPossible], so a resume or
     * mesh-service restart cannot bring Aware back while a hotspot is up.
     *
     * A count rather than a flag because teardown is asynchronous and sessions can
     * overlap. Callers receive a once-releasable [HotspotLease], so one session cannot
     * accidentally consume another session's hold.
     */
    private val hotspotHolds = AtomicInteger(0)

    /** True while any hotspot session still needs the radio. */
    @VisibleForTesting
    internal fun isHeldForHotspot(): Boolean = hotspotHolds.get() > 0

    private fun heldForHotspot(): Boolean = isHeldForHotspot()

    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    private val _enabled = MutableStateFlow(false)
    val enabled: StateFlow<Boolean> = _enabled.asStateFlow()

    private val _supported = MutableStateFlow(false)
    val supported: StateFlow<Boolean> = _supported.asStateFlow()

    private val _available = MutableStateFlow(false)
    val available: StateFlow<Boolean> = _available.asStateFlow()

    private val _supportStatus = MutableStateFlow<WifiAwareSupport.Status?>(null)
    val supportStatus: StateFlow<WifiAwareSupport.Status?> = _supportStatus.asStateFlow()

    private val _running = MutableStateFlow(false)
    val running: StateFlow<Boolean> = _running.asStateFlow()

    // Simple debug surfacing
    private val _connectedPeers = MutableStateFlow<Map<String, String>>(emptyMap()) // peerID -> ip
    val connectedPeers: StateFlow<Map<String, String>> = _connectedPeers.asStateFlow()

    private val _knownPeers = MutableStateFlow<Map<String, String>>(emptyMap()) // peerID -> nickname
    val knownPeers: StateFlow<Map<String, String>> = _knownPeers.asStateFlow()

    private val _discoveredPeers = MutableStateFlow<Set<String>>(emptySet())
    val discoveredPeers: StateFlow<Set<String>> = _discoveredPeers.asStateFlow()

    fun initialize(context: Context, enabledByDefault: Boolean) {
        appContext = context.applicationContext
        val status = refreshSupportStatus(appContext!!)
        if (status.supported) {
            registerAwareStateReceiver(appContext!!)
        } else {
            Log.i(TAG, "Wi-Fi Aware unsupported: ${status.reason}")
        }
        setEnabled(enabledByDefault)
    }

    internal fun publishDebugSnapshot(
        connected: Map<String, String>,
        known: Map<String, String>,
        discovered: Set<String>
    ) {
        _connectedPeers.value = connected
        _knownPeers.value = known
        _discoveredPeers.value = discovered
    }

    private fun clearDebugSnapshot() {
        publishDebugSnapshot(emptyMap(), emptyMap(), emptySet())
    }

    fun setEnabled(value: Boolean) {
        _enabled.value = value
        if (value) startIfPossible() else stop()
    }

    /**
     * A session-scoped claim on the Wi-Fi radio.
     *
     * Closing the same lease twice is a no-op; raw decrements are intentionally not
     * exposed because lifecycle retries and duplicate teardown calls must not release a
     * different hotspot session's hold.
     */
    class HotspotLease internal constructor(
        private val releaseAction: () -> Unit
    ) : AutoCloseable {
        private val released = AtomicBoolean(false)

        override fun close() {
            if (released.compareAndSet(false, true)) {
                releaseAction()
            }
        }
    }

    /**
     * Releases the Wi-Fi radio so a Wi-Fi Direct hotspot can create its P2P interface,
     * and prevents Aware restarting until the returned lease is closed.
     *
     * Counted because a second share can start while the first is still cleaning up.
     */
    fun acquireHotspotLease(): HotspotLease {
        if (hotspotHolds.getAndIncrement() == 0) {
            Log.i(TAG, "Holding Wi-Fi Aware down so the hotspot can use the radio")
            stop()
        }
        return HotspotLease(::releaseHotspotLease)
    }

    private fun releaseHotspotLease() {
        var remaining: Int
        while (true) {
            val current = hotspotHolds.get()
            if (current == 0) return
            remaining = current - 1
            if (hotspotHolds.compareAndSet(current, remaining)) break
        }

        if (remaining != 0) {
            Log.d(TAG, "Hotspot finished, but $remaining other hold(s) remain")
            return
        }

        Log.i(TAG, "Hotspot finished; restoring Wi-Fi Aware if enabled")
        restartIfStillEnabled()
    }

    @VisibleForTesting
    internal fun resetHotspotLeasesForTest() {
        hotspotHolds.set(0)
    }

    fun startIfPossible() {
        val reusableService = synchronized(lifecycleLock) {
            if (!_enabled.value) return
            if (heldForHotspot()) {
                Log.d(TAG, "Not starting Wi-Fi Aware: held down for the hotspot")
                return
            }
            val existing = service
            if (existing?.isRunning() == true) {
                _running.value = true
                return
            }
            if (starting) return
            starting = true
            existing
        }

        val ctx = appContext ?: run {
            synchronized(lifecycleLock) { starting = false }
            return
        }

        val status = refreshSupportStatus(ctx)
        if (!status.supported) {
            val reason = status.reason ?: "not supported"
            Log.w(TAG, "Wi‑Fi Aware unsupported; not starting ($reason)")
            addBlockedDebugMessage("unsupported:$reason", "Wi-Fi Aware not supported on this device ($reason)")
            synchronized(lifecycleLock) { starting = false }
            return
        }

        val awareManager = WifiAwareSupport.getManager(ctx)
        if (awareManager == null || !status.available) {
            Log.w(TAG, "Wi-Fi Aware is not currently available; not starting")
            addBlockedDebugMessage("unavailable", "Wi-Fi Aware is not available right now")
            synchronized(lifecycleLock) { starting = false }
            return
        }

        // Check system location setting: WifiAwareManager.attach() throws SecurityException if disabled
        val lm = ctx.getSystemService(Context.LOCATION_SERVICE) as? android.location.LocationManager
        val locationEnabled = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            lm?.isLocationEnabled == true
        } else {
            @Suppress("DEPRECATION")
            lm?.isProviderEnabled(android.location.LocationManager.GPS_PROVIDER) == true ||
            lm?.isProviderEnabled(android.location.LocationManager.NETWORK_PROVIDER) == true
        }

        if (!locationEnabled) {
            Log.w(TAG, "Location services are disabled; Wi-Fi Aware cannot start.")
            addBlockedDebugMessage("location-disabled", "Enable Location Services to start Wi-Fi Aware")
            synchronized(lifecycleLock) { starting = false }
            return
        }

        // Android 13+: require NEARBY_WIFI_DEVICES runtime permission
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            val granted = androidx.core.content.ContextCompat.checkSelfPermission(ctx, android.Manifest.permission.NEARBY_WIFI_DEVICES) == android.content.pm.PackageManager.PERMISSION_GRANTED
            if (!granted) {
                Log.w(TAG, "Missing NEARBY_WIFI_DEVICES permission; not starting Wi‑Fi Aware")
                addBlockedDebugMessage("missing-nearby-wifi", "Grant Nearby Wi-Fi Devices to start Wi-Fi Aware")
                synchronized(lifecycleLock) { starting = false }
                return
            }
        }
        if (!_enabled.value || heldForHotspot()) {
            synchronized(lifecycleLock) { starting = false }
            return
        }
        try {
            val startedService = reusableService ?: run {
                Log.i(TAG, "Instantiating WifiAwareMeshService...")
                WifiAwareMeshService(ctx)
            }
            startedService.startServices()

            // Test the hold inside the same lock that publishes the service, and that
            // stop() takes. Testing it outside leaves a window where acquiring a lease
            // sets the flag and stop() finds nothing published yet, and this block then
            // publishes anyway — resurrecting NAN while the hotspot owns the radio.
            // Ordering holds because acquireHotspotLease() increments before calling
            // stop(): either we see the flag here, or stop() sees our published service.
            val published = synchronized(lifecycleLock) {
                val canPublish = !heldForHotspot() && startedService.isRunning()
                if (canPublish) {
                    service = startedService
                    _running.value = true
                } else {
                    if (service === startedService) service = null
                    _running.value = false
                }
                canPublish
            }

            if (published) {
                try { com.bitchat.android.service.MeshServiceHolder.unifiedMeshService?.refreshDelegates() } catch (_: Exception) { }
                clearBlockedDebugMessage()
                try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().addDebugMessage(com.bitchat.android.ui.debug.DebugMessage.SystemMessage("Wi‑Fi Aware started")) } catch (_: Exception) {}
            } else {
                // stopServices() can block, so keep it out of the lock.
                val heldForHotspot = heldForHotspot()
                if (heldForHotspot || reusableService == null) {
                    try { startedService.stopServices() } catch (_: Exception) { }
                }
                if (heldForHotspot) {
                    Log.i(TAG, "Abandoned Wi-Fi Aware start: hotspot claimed the radio")
                }
                val detail = if (heldForHotspot) "held down for the hotspot" else "did not start"
                try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().addDebugMessage(com.bitchat.android.ui.debug.DebugMessage.SystemMessage("Wi‑Fi Aware $detail")) } catch (_: Exception) {}
            }
        } catch (e: Throwable) {
            Log.e(TAG, "Failed to start WifiAwareMeshService", e)
            _running.value = false
            try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().addDebugMessage(com.bitchat.android.ui.debug.DebugMessage.SystemMessage("Wi‑Fi Aware failed to start: ${e.message}")) } catch (_: Exception) {}
        } finally {
            synchronized(lifecycleLock) { starting = false }
        }
    }

    fun stop() {
        val stopped = synchronized(lifecycleLock) {
            val current = service
            service = null
            starting = false
            _running.value = false
            current
        }
        try { stopped?.stopServices() } catch (_: Exception) { }
        try { com.bitchat.android.services.AppStateStore.clearTransportPeers("WIFI") } catch (_: Exception) { }
        clearDebugSnapshot()
        try { com.bitchat.android.ui.debug.DebugSettingsManager.getInstance().addDebugMessage(com.bitchat.android.ui.debug.DebugMessage.SystemMessage("Wi‑Fi Aware stopped")) } catch (_: Exception) {}
    }

    internal fun onServiceStopped(stoppedService: WifiAwareMeshService) {
        synchronized(lifecycleLock) {
            if (service !== stoppedService) return
            service = null
            _running.value = false
            try { com.bitchat.android.services.AppStateStore.clearTransportPeers("WIFI") } catch (_: Exception) { }
            clearDebugSnapshot()
        }
    }

    /**
     * Schedules a restart of the Wi-Fi Aware transport. Concurrent requests are coalesced into
     * a single in-flight loop that retries with backoff. This is important because a single fixed
     * delay can land while the service is still tearing down (recoveryInProgress), in which case
     * startServices() defers and we must try again rather than give up.
     */
    internal fun restartIfStillEnabled(delayMs: Long = 0L) {
        // Record the request before coalescing. A request that arrives while a loop is
        // already running — the final lease closing during a loop that has been
        // burning attempts against the hold — would otherwise be dropped, and the old
        // loop would exhaust MAX_RESTART_ATTEMPTS without ever seeing the cleared hold,
        // leaving Aware down despite the user's setting.
        restartRequested.set(true)

        if (!restartInFlight.compareAndSet(false, true)) {
            Log.d(TAG, "Restart already in flight; coalescing request")
            return
        }
        scope.launch {
            try {
                if (delayMs > 0L) delay(delayMs)
                do {
                    // Consume the request before working, so anything arriving during
                    // the attempts below schedules another pass.
                    restartRequested.set(false)
                    var attempt = 0
                    while (_enabled.value && !_running.value && attempt < MAX_RESTART_ATTEMPTS) {
                        val ctx = appContext
                        if (ctx != null && !refreshSupportStatus(ctx).supported) break
                        startIfPossible()
                        if (_running.value) break
                        attempt++
                        delay(RESTART_RETRY_DELAY_MS)
                    }
                } while (restartRequested.get() && _enabled.value && !_running.value)
            } finally {
                restartInFlight.set(false)
            }

            // A request landing between the loop exiting and the flag clearing finds
            // restartInFlight still set and returns; pick it up here. Terminates because
            // each pass consumes the flag before doing any work.
            if (restartRequested.get() && _enabled.value && !_running.value) {
                restartIfStillEnabled()
            }
        }
    }

    /**
     * Listens for system Wi-Fi Aware availability changes. Aware can flip off/on at runtime
     * (Wi-Fi toggling, hotspot/SoftAP, location changes); without this we would only recover on
     * an unrelated trigger.
     */
    private fun registerAwareStateReceiver(ctx: Context) {
        if (awareReceiverRegistered) return
        if (!refreshSupportStatus(ctx).supported) return
        try {
            val filter = android.content.IntentFilter(
                android.net.wifi.aware.WifiAwareManager.ACTION_WIFI_AWARE_STATE_CHANGED
            )
            ctx.registerReceiver(object : android.content.BroadcastReceiver() {
                override fun onReceive(c: Context?, intent: android.content.Intent?) {
                    val status = refreshSupportStatus(ctx)
                    Log.i(TAG, "Wi-Fi Aware availability changed: supported=${status.supported} available=${status.available} enabled=${_enabled.value} running=${_running.value}")
                    if (status.available) {
                        if (_enabled.value) restartIfStillEnabled(500)
                    } else if (_running.value) {
                        // Aware went away; tear down cleanly so we can re-attach when it returns.
                        // Note: this does not change the enabled preference.
                        stop()
                    }
                }
            }, filter)
            awareReceiverRegistered = true
        } catch (e: Exception) {
            Log.w(TAG, "Failed to register Wi-Fi Aware state receiver: ${e.message}")
        }
    }

    private fun refreshSupportStatus(ctx: Context): WifiAwareSupport.Status {
        val status = WifiAwareSupport.evaluate(ctx)
        _supported.value = status.supported
        _available.value = status.available
        _supportStatus.value = status
        return status
    }

    private fun addBlockedDebugMessage(key: String, message: String) {
        if (lastBlockedReason == key) return
        lastBlockedReason = key
        try {
            com.bitchat.android.ui.debug.DebugSettingsManager.getInstance()
                .addDebugMessage(com.bitchat.android.ui.debug.DebugMessage.SystemMessage(message))
        } catch (_: Exception) { }
    }

    private fun clearBlockedDebugMessage() {
        lastBlockedReason = null
    }

    fun getService(): WifiAwareMeshService? = service
}

