    fun `BLE padding policy matches iOS packet type table`() {
        val expected = mapOf(
            MessageType.ANNOUNCE to false,
            MessageType.MESSAGE to false,
            MessageType.LEAVE to false,
            MessageType.REQUEST_SYNC to false,
            MessageType.FRAGMENT to false,
            MessageType.FILE_TRANSFER to false,
            MessageType.VOICE_FRAME to false,
            MessageType.NOISE_ENCRYPTED to true,
            MessageType.NOISE_HANDSHAKE to true
        )

        expected.forEach { (type, shouldPad) ->
            assertEquals(
                "${type.name} BLE padding policy must match iOS",
                shouldPad,
                BLEPacketPaddingPolicy.shouldPadForBLE(type.value)
            )
        }

        assertFalse(
            "Unknown packet types should be sent unpadded, matching iOS default",
            BLEPacketPaddingPolicy.shouldPadForBLE(0x7Fu)
        )
    }

    @Test
    fun `public BLE packet types are encoded without PKCS7 padding tails`() {
        val publicTypes = listOf(
            MessageType.ANNOUNCE,
            MessageType.MESSAGE,
            MessageType.LEAVE,
            MessageType.REQUEST_SYNC,
            MessageType.FRAGMENT,
            MessageType.FILE_TRANSFER,
            MessageType.VOICE_FRAME
        )

        publicTypes.forEach { type ->
            val packet = packet(type.value, payload = payloadEndingWithoutPaddingShape(type))
            val raw = packet.toBinaryData(padding = false)!!
            val encodedForBLE = packet.toBinaryData(
                padding = BLEPacketPaddingPolicy.shouldPadForBLE(packet.type)
            )!!

            assertArrayEquals(
                "${type.name} BLE encoding should be the unpadded frame",
                raw,
                encodedForBLE
            )
            assertFalse(
                "${type.name} BLE encoding must not leave iOS-visible PKCS#7 tail bytes",
                hasPkcs7PaddingTail(encodedForBLE)
            )
            assertNotNull(
                "${type.name} unpadded BLE frame must remain decodable",
                BinaryProtocol.decode(encodedForBLE)
            )
        }
    }

    @Test
    fun `Noise BLE packet types remain padded and decodable`() {
        val noiseTypes = listOf(MessageType.NOISE_HANDSHAKE, MessageType.NOISE_ENCRYPTED)

        noiseTypes.forEach { type ->
            val packet = packet(type.value, payload = "noise-${type.name}".toByteArray())
            val raw = packet.toBinaryData(padding = false)!!
            val encodedForBLE = packet.toBinaryData(
                padding = BLEPacketPaddingPolicy.shouldPadForBLE(packet.type)
            )!!

            assertTrue("${type.name} BLE frame should be padded", encodedForBLE.size > raw.size)
            assertTrue(
                "${type.name} BLE frame should end with valid PKCS#7 padding",
                hasPkcs7PaddingTail(encodedForBLE)
            )
            assertArrayEquals(
                "${type.name} padding should strip back to the raw frame",
                raw,
                MessagePadding.unpad(encodedForBLE)
            )
            assertNotNull(
                "${type.name} padded BLE frame must remain decodable",
                BinaryProtocol.decode(encodedForBLE)
            )
        }
    }

    private fun packet(type: UByte, payload: ByteArray): BitchatPacket {
        val version = if (type == MessageType.FILE_TRANSFER.value) 2u.toUByte() else 1u.toUByte()
        return BitchatPacket(
            version = version,
            type = type,
            senderID = senderID,
            recipientID = null,
            timestamp = timestamp,
            payload = payload,
            signature = null,
            ttl = 7u,
            route = null
        )
    }

    private fun payloadEndingWithoutPaddingShape(type: MessageType): ByteArray {
        return "ios-ble-policy-${type.name}-z".toByteArray()
    }

    private fun hasPkcs7PaddingTail(data: ByteArray): Boolean {
        if (data.isEmpty()) return false
        val paddingLength = data.last().toInt() and 0xFF
        if (paddingLength <= 0 || paddingLength > data.size) return false
        val start = data.size - paddingLength
        return data.copyOfRange(start, data.size).all { (it.toInt() and 0xFF) == paddingLength }
    }
}

package com.bitchat.android.mesh

import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.model.FragmentPayload
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import java.util.Random

@RunWith(RobolectricTestRunner::class)
class FragmentManagerTest {

    private lateinit var fragmentManager: FragmentManager
    private val senderID = "1122334455667788"
    private val recipientID = "8877665544332211"

    @Before
    fun setup() {
        fragmentManager = FragmentManager()
    }

    @Test
    fun `test fragmentation without route`() {
        // Create a large payload (e.g., 1000 bytes)
        val payload = ByteArray(1000)
        Random().nextBytes(payload)

        val packet = BitchatPacket(
            version = 1u,
            type = MessageType.MESSAGE.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = 7u,
            route = null
        )

        val fragments = fragmentManager.createFragments(packet)

        assertTrue("Should create multiple fragments", fragments.size > 1)

        // Verify each fragment fits in MTU (512)
        for (fragment in fragments) {
            val encodedSize = fragment.toBinaryData()?.size ?: 0
            assertTrue("Fragment encoded size should be <= 512, was $encodedSize", encodedSize <= 512)

            // Inspect the payload data size
            val fragmentPayload = FragmentPayload.decode(fragment.payload)
            assertNotNull(fragmentPayload)
        }
    }

    @Test
    fun `test fragmentation with route`() {
        // Create a large payload
        val payload = ByteArray(1000)
        Random().nextBytes(payload)

        // Create a fake route (3 hops)
        val route = listOf(
            hexStringToByteArray("AABBCCDDEEFF0011"),
            hexStringToByteArray("1100FFEEDDCCBBAA"),
            hexStringToByteArray("1234567890ABCDEF")
        )

        val packet = BitchatPacket(
            version = 2u,
            type = MessageType.MESSAGE.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = 7u,
            route = route
        )

        val fragments = fragmentManager.createFragments(packet)

        assertTrue("Should create multiple fragments", fragments.size > 1)

        // Verify fragments retain the route and version 2
        for (fragment in fragments) {
            assertEquals("Fragment version should be 2", 2u.toUByte(), fragment.version)
            assertEquals("Fragment should have the route", route.size, fragment.route?.size)

            val encodedSize = fragment.toBinaryData()?.size ?: 0
            assertTrue("Fragment encoded size should be <= 512, was $encodedSize", encodedSize <= 512)
        }
    }

    @Test
    fun `test fragmentation size difference with and without route`() {
        // This test specifically checks if the dynamic calculation logic works 
        // by observing that fragments with routes carry less data payload per fragment

        val payload = ByteArray(2000) // Large enough to ensure full fragments
        Random().nextBytes(payload)

        // 1. Without route
        val packetNoRoute = BitchatPacket(
            version = 1u,
            type = MessageType.MESSAGE.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = 7u,
            route = null
        )
        val fragmentsNoRoute = fragmentManager.createFragments(packetNoRoute)
        val firstFragPayloadNoRoute = FragmentPayload.decode(fragmentsNoRoute[0].payload)
        val dataSizeNoRoute = firstFragPayloadNoRoute?.data?.size ?: 0

        // 2. With large route (e.g., 5 hops)
        val route = List(5) { hexStringToByteArray("000000000000000$it") }
        val packetWithRoute = BitchatPacket(
            version = 2u,
            type = MessageType.MESSAGE.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            ttl = 7u,
            route = route
        )
        val fragmentsWithRoute = fragmentManager.createFragments(packetWithRoute)
        val firstFragPayloadWithRoute = FragmentPayload.decode(fragmentsWithRoute[0].payload)
        val dataSizeWithRoute = firstFragPayloadWithRoute?.data?.size ?: 0

        println("Data size without route: $dataSizeNoRoute")
        println("Data size with route: $dataSizeWithRoute")

        assertTrue("Data payload should be smaller with route", dataSizeWithRoute < dataSizeNoRoute)

        // Rough verification of the math:
        // 5 hops * 8 bytes = 40 bytes extra.
        // Plus v2 header overhead differences.
        // The difference should be roughly 40+ bytes.
        assertTrue("Difference should be significant", (dataSizeNoRoute - dataSizeWithRoute) >= 40)
    }

    @Test
    fun `test reassembly`() {
        val originalPayload = ByteArray(1500)
        Random().nextBytes(originalPayload)

        val originalPacket = BitchatPacket(
            version = 1u,
            type = MessageType.FILE_TRANSFER.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = System.currentTimeMillis().toULong(),
            payload = originalPayload,
            ttl = 7u
        )

        val fragments = fragmentManager.createFragments(originalPacket)

        var reassembledPacket: BitchatPacket? = null

        // Feed fragments back into FragmentManager
        // Note: FragmentManager stores state in incomingFragments

        for (fragment in fragments) {
            val result = fragmentManager.handleFragment(fragment)
            if (result != null) {
                reassembledPacket = result
            }
        }

        assertNotNull("Should have reassembled packet", reassembledPacket)
        assertEquals("Type should match", originalPacket.type, reassembledPacket!!.type)
        assertEquals("Payload size should match", originalPacket.payload.size, reassembledPacket.payload.size)
        assertTrue("Payload content should match", originalPacket.payload.contentEquals(reassembledPacket.payload))
    }

    @Test
    fun `inbound fragment set above 256 is rejected`() {
        val payload = FragmentPayload(
            fragmentID = ByteArray(8) { 1 },
            index = 0,
            total = 257,
            originalType = MessageType.NOISE_ENCRYPTED.value,
            data = byteArrayOf(1)
        ).encode()
        val packet = BitchatPacket(
            version = 1u,
            type = MessageType.FRAGMENT.value,
            senderID = hexStringToByteArray(senderID),
            recipientID = hexStringToByteArray(recipientID),
            timestamp = 1u,
            payload = payload,
            ttl = 7u
        )

        assertNull(fragmentManager.handleFragment(packet))
    }

    @Test
    fun `fragment payload refuses UInt16 truncation`() {
        assertThrows(IllegalArgumentException::class.java) {
            FragmentPayload(
                fragmentID = ByteArray(8) { 2 },
                index = 0,
                total = 65_536,
                originalType = MessageType.NOISE_ENCRYPTED.value,
                data = byteArrayOf(1)
            ).encode()
        }
    }

    @Test
    fun `generic public packet retains a 257 fragment outbound plan`() {
        val randomPayload = ByteArray(180 * 1024).also { Random(0xB17C4A7).nextBytes(it) }

        fun plan(contentSize: Int): List<BitchatPacket> = fragmentManager.createFragments(
            BitchatPacket(
                version = 2u,
                type = MessageType.FILE_TRANSFER.value,
                senderID = hexStringToByteArray(senderID),
                recipientID = com.bitchat.android.protocol.SpecialRecipients.BROADCAST,
                timestamp = 1u,
                payload = randomPayload.copyOf(contentSize),
                signature = ByteArray(64) { 7 },
                ttl = 7u
            )
        )

        var low = 1
        var high = randomPayload.size
        while (low < high) {
            val mid = low + (high - low) / 2
            if (plan(mid).size >= 257) high = mid else low = mid + 1
        }

        assertEquals(257, plan(low).size)
    }

    private fun hexStringToByteArray(hexString: String): ByteArray {
        val result = ByteArray(8)
        for (i in 0 until 8) {
            val byteStr = hexString.substring(i * 2, i * 2 + 2)
            result[i] = byteStr.toInt(16).toByte()
        }
        return result
    }
}

package com.bitchat.android.mesh

import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.util.AppConstants
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import java.util.Random

@RunWith(RobolectricTestRunner::class)
class FragmentingPacketSenderTest {

    private val senderID = "1122334455667788"

    private fun packetWithPayload(bytes: Int): BitchatPacket {
        val payload = ByteArray(bytes)
        Random(42).nextBytes(payload)
        return BitchatPacket(
            version = 2u,
            type = MessageType.FILE_TRANSFER.value,
            senderID = MeshPacketUtils.hexStringToByteArray(senderID),
            recipientID = null,
            timestamp = System.currentTimeMillis().toULong(),
            payload = payload,
            signature = null,
            ttl = 7u
        )
    }

    @Test
    fun `oversized packet exceeding receiver fragment cap is rejected with fail event`() = runBlocking {
        val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
        val sender = FragmentingPacketSender(scope, FragmentManager(), "test")
        // ~256 * 469 bytes fit; 1 MiB clearly exceeds MAX_FRAGMENTS_PER_ID
        val packet = packetWithPayload(1024 * 1024)
        var sent = false

        val failed = java.util.concurrent.ConcurrentLinkedQueue<String>()
        val collectJob = launch(Dispatchers.Default) {
            TransferProgressManager.events.collect { event ->
                if (event.failed) failed.add(event.transferId)
            }
        }
        kotlinx.coroutines.delay(100) // activate subscription before emitting

        val accepted = sender.send(RoutedPacket(packet, transferId = "oversize-test"), "test") { sent = true; true }
        assertFalse(accepted)
        assertFalse(sent)
        withTimeout(5_000) {
            while (!failed.contains("oversize-test")) {
                kotlinx.coroutines.delay(10)
            }
        }
        collectJob.cancel()
        Unit
    }

    @Test
    fun `packet within fragment cap is accepted`() = runBlocking {
        val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
        val sender = FragmentingPacketSender(scope, FragmentManager(), "test", interFragmentDelayMs = 0L)
        val packet = packetWithPayload(10_000)
        var writes = 0

        val accepted = sender.send(RoutedPacket(packet, transferId = "fits-test"), "test") { writes += 1; true }
        assertTrue(accepted)
        withTimeout(5_000) {
            while (writes == 0) {
                kotlinx.coroutines.delay(10)
            }
        }
        assertTrue(writes > 0)
    }

    @Test
    fun `fragment count at cap boundary is not rejected`() {
        val manager = FragmentManager()
        val packet = packetWithPayload(AppConstants.Fragmentation.MAX_FRAGMENTS_PER_ID * 400)
        val fragments = manager.createFragments(packet, AppConstants.Fragmentation.MAX_FRAGMENTS_PER_ID)
        assertTrue(fragments.isNotEmpty())
        assertTrue(fragments.size <= AppConstants.Fragmentation.MAX_FRAGMENTS_PER_ID)
    }
}

