            if (peerID == unknownPeer) {
                val unknownRSSIIsAdded = peerManager.getAllPeerRSSI().containsKey(peerID)
                assertEquals(false, unknownRSSIIsAdded)
            }
        }

        val expectedRSSI = testRSSI.filter { it.key != unknownPeer }
