import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.noise.NoisePeerIdentity
import com.bitchat.android.noise.AuthenticatedNoiseSession
import com.bitchat.android.noise.NoiseDecryptionResult
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.protocol.SpecialRecipients
import com.bitchat.android.services.meshgraph.MeshGraphService
import com.bitchat.android.util.AppConstants
import kotlinx.coroutines.runBlocking
import org.junit.After
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.mockito.kotlin.any
import org.mockito.kotlin.anyOrNull
import org.mockito.kotlin.eq
import org.mockito.kotlin.mock
import org.mockito.kotlin.never
import org.mockito.kotlin.verify
import org.mockito.kotlin.whenever
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [Build.VERSION_CODES.P], manifest = Config.NONE)
class MessageHandlerTest {
    private lateinit var handler: MessageHandler
    private lateinit var delegate: MessageHandlerDelegate

    private val myPeerID = "1111222233334444"
    private val noiseKey = ByteArray(32) { 0x0B }
    private val peerID = NoisePeerIdentity.derivePeerID(noiseKey)!!
    private val authenticatedSession = AuthenticatedNoiseSession(
        noiseKey,
        ByteArray(32) { 0x5D }
    )
    private val nickname = "peer"
    private val signingKey = ByteArray(32) { 0x0A }
    private val signature = ByteArray(64) { 1 }
    private val announceClockSkewToleranceMs = 10 * 60 * 1000L

    @Before
    fun setup() {
        MeshGraphService.resetForTesting()
        handler = MessageHandler(myPeerID, RuntimeEnvironment.getApplication())
        delegate = mock()
        handler.delegate = delegate

        whenever(delegate.getPeerInfo(peerID)).thenReturn(null)
        whenever(delegate.verifyEd25519Signature(any(), any(), any())).thenReturn(true)
        whenever(
            delegate.updatePeerInfoFromVerifiedAnnouncement(
                any(), any(), any(), any(), any(), anyOrNull()
            )
        ).thenReturn(true)
    }

    @After
    fun tearDown() {
        MeshGraphService.resetForTesting()
    }

    @Test
    fun `handleAnnounce accepts announce within clock skew tolerance for identity binding`() {
        runBlocking {
            val packet = announcePacket(ageMs = AppConstants.Mesh.STALE_PEER_TIMEOUT_MS + 1_000)

            val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

            assertTrue("Announce within clock skew tolerance should still store peer identity", result)
            verify(delegate).updatePeerInfoFromVerifiedAnnouncement(
                eq(peerID), eq(nickname), any(), any(), eq(true), anyOrNull()
            )
        }
    }

    @Test
    fun `handleAnnounce accepts future announce within clock skew tolerance`() {
        runBlocking {
            val packet = announcePacket(ageMs = -(AppConstants.Mesh.STALE_PEER_TIMEOUT_MS + 1_000))

            val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

            assertTrue("Future announce within clock skew tolerance should still store peer identity", result)
            verify(delegate).updatePeerInfoFromVerifiedAnnouncement(
                eq(peerID), eq(nickname), any(), any(), eq(true), anyOrNull()
            )
        }
    }

    @Test
    fun `handleAnnounce stores advertised capabilities including unknown bits`() {
        runBlocking {
            val capabilities = PeerCapabilities(
                PeerCapabilities.PRIVATE_MEDIA.rawValue or (1L shl 15)
            )
            val packet = announcePacket(ageMs = 0, capabilities = capabilities)

            val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

            assertTrue(result)
            verify(delegate).updatePeerInfoFromVerifiedAnnouncement(
                eq(peerID),
                eq(nickname),
                any(),
                any(),
                eq(true),
                eq(capabilities)
            )
        }
    }

    @Test
    fun `handleAnnounce rejects announce older than clock skew tolerance`() {
        runBlocking {
            val packet = announcePacket(ageMs = announceClockSkewToleranceMs + 1_000)

            val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "relay-link"))

            assertFalse("Announce older than clock skew tolerance should not store peer identity", result)
            verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
                any(), any(), any(), any(), any(), anyOrNull()
            )
        }
    }

    @Test
    fun `handleAnnounce never promotes capability after invalid signature`() {
        runBlocking {
            whenever(delegate.verifyEd25519Signature(any(), any(), any())).thenReturn(false)
            val packet = announcePacket(ageMs = 0, capabilities = PeerCapabilities.PRIVATE_MEDIA)

            val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

            assertFalse(result)
            verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
                any(), any(), any(), any(), any(), anyOrNull()
            )
        }
    }

    @Test
    fun `directed raw private media requires a valid signature`() {
        runBlocking {
            whenever(delegate.getBroadcastRecipient()).thenReturn(SpecialRecipients.BROADCAST)
            whenever(delegate.getPeerNickname(peerID)).thenReturn(nickname)
            whenever(delegate.verifySignature(any(), eq(peerID))).thenReturn(false)
            val file = BitchatFilePacket(
                fileName = "legacy.jpg",
                fileSize = 3,
                mimeType = "image/jpeg",
                content = byteArrayOf(1, 2, 3)
            )
            val unsigned = BitchatPacket(
                version = 2u,
                type = MessageType.FILE_TRANSFER.value,
                senderID = peerID.hexToBytes(),
                recipientID = myPeerID.hexToBytes(),
                timestamp = System.currentTimeMillis().toULong(),
                payload = file.encode()!!,
                signature = null,
                ttl = 7u
            )

            handler.handleMessage(RoutedPacket(unsigned, peerID, "direct-link"))
            handler.handleMessage(
                RoutedPacket(unsigned.copy(signature = ByteArray(64) { 1 }), peerID, "direct-link")
            )

            verify(delegate, never()).onMessageReceived(any())
        }
    }

    @Test
    fun `valid signed directed raw private media remains interoperable`() {
        runBlocking {
            whenever(delegate.getBroadcastRecipient()).thenReturn(SpecialRecipients.BROADCAST)
            whenever(delegate.getPeerNickname(peerID)).thenReturn(nickname)
            whenever(delegate.verifySignature(any(), eq(peerID))).thenReturn(true)
            val file = BitchatFilePacket(
                fileName = "legacy-valid.jpg",
                fileSize = 3,
                mimeType = "image/jpeg",
                content = byteArrayOf(1, 2, 3)
            )
            val packet = BitchatPacket(
                version = 2u,
                type = MessageType.FILE_TRANSFER.value,
                senderID = peerID.hexToBytes(),
                recipientID = myPeerID.hexToBytes(),
                timestamp = System.currentTimeMillis().toULong(),
                payload = file.encode()!!,
                signature = signature,
                ttl = 7u
            )

            handler.handleMessage(RoutedPacket(packet, peerID, "direct-link"))

            verify(delegate).verifySignature(packet, peerID)
            verify(delegate).onMessageReceived(any())
        }
    }

    @Test
    fun `encrypted prerelease iOS Noise 0x09 private media is delivered`() {
        runBlocking {
            val file = BitchatFilePacket(
                fileName = "prerelease-ios.pdf",
                fileSize = 4,
                mimeType = "application/pdf",
                content = byteArrayOf(1, 2, 3, 4)
            )
            val prereleasePlaintext = byteArrayOf(0x09) + file.encode()!!
            val ciphertext = byteArrayOf(0x41, 0x42, 0x43)
            whenever(delegate.decryptFromPeer(any(), eq(peerID))).thenReturn(
                NoiseDecryptionResult(prereleasePlaintext, authenticatedSession)
            )
            whenever(delegate.getPeerNickname(peerID)).thenReturn(nickname)
            whenever(delegate.getMyNickname()).thenReturn("me")
            whenever(delegate.encryptForPeer(any(), eq(peerID))).thenReturn(byteArrayOf(0x55))

            val outerPacket = BitchatPacket(
                version = 2u,
                type = MessageType.NOISE_ENCRYPTED.value,
                senderID = peerID.hexToBytes(),
                recipientID = myPeerID.hexToBytes(),
                timestamp = System.currentTimeMillis().toULong(),
                payload = ciphertext,
                signature = signature,
                ttl = 7u
            )

            handler.handleNoiseEncrypted(RoutedPacket(outerPacket, peerID, "direct-link"))

            verify(delegate).decryptFromPeer(ciphertext, peerID)
            verify(delegate).onMessageReceived(any())
        }
    }

    @Test
    fun `valid encrypted peer state is delivered and malformed state is ignored`() = runBlocking {
        val state = AuthenticatedPeerState(PeerCapabilities.PRIVATE_MEDIA, signingKey)
        val validCiphertext = byteArrayOf(0x31)
        val malformedCiphertext = byteArrayOf(0x32)
        whenever(delegate.decryptFromPeer(validCiphertext, peerID)).thenReturn(
            NoiseDecryptionResult(
                NoisePayload(NoisePayloadType.PEER_STATE, state.encode()).encode(),
                authenticatedSession
            )
        )
        whenever(delegate.decryptFromPeer(malformedCiphertext, peerID)).thenReturn(
            NoiseDecryptionResult(
                NoisePayload(NoisePayloadType.PEER_STATE, byteArrayOf(0x01, 0x01)).encode(),
                authenticatedSession
            )
        )
        val base = BitchatPacket(
            version = 1u,
            type = MessageType.NOISE_ENCRYPTED.value,
            senderID = peerID.hexToBytes(),
            recipientID = myPeerID.hexToBytes(),
            timestamp = System.currentTimeMillis().toULong(),
            payload = validCiphertext,
            ttl = 7u
        )

        handler.handleNoiseEncrypted(RoutedPacket(base, peerID, "direct-link"))
        handler.handleNoiseEncrypted(
            RoutedPacket(base.copy(payload = malformedCiphertext), peerID, "direct-link")
        )

        verify(delegate).onAuthenticatedPeerStateReceived(peerID, state, authenticatedSession)
    }

    @Test
    fun `first self-signed announce cannot claim an ID derived from another Noise key`() = runBlocking {
        val attackerNoiseKey = ByteArray(32) { 0x6B }
        val packet = announcePacket(ageMs = 0, noisePublicKey = attackerNoiseKey)

        val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

        assertFalse("A valid self-signature cannot bind an attacker key to a victim ID", result)
        verify(delegate, never()).verifyEd25519Signature(any(), any(), any())
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `announce requires a 32-byte Noise static key before peer update`() = runBlocking {
        val malformedNoiseKey = ByteArray(31) { 0x0B }
        val packet = announcePacket(ageMs = 0, noisePublicKey = malformedNoiseKey)

        val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

        assertFalse(result)
        verify(delegate, never()).verifyEd25519Signature(any(), any(), any())
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `announce packet sender cannot be processed under a different routed peer ID`() = runBlocking {
        val otherPeerID = NoisePeerIdentity.derivePeerID(ByteArray(32) { 0x21 })!!
        val packet = announcePacket(ageMs = 0)

        val result = handler.handleAnnounce(RoutedPacket(packet, otherPeerID, "relay-link"))

        assertFalse(result)
        verify(delegate, never()).verifyEd25519Signature(any(), any(), any())
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `known peer signing key cannot be replaced without bound Noise session`() = runBlocking {
        whenever(delegate.getPeerInfo(peerID)).thenReturn(peerInfo(signingPublicKey = ByteArray(32) { 0x44 }))
        whenever(delegate.hasNoiseSession(peerID)).thenReturn(false)
        val packet = announcePacket(ageMs = 0)

        val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

        assertFalse(result)
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `ambient bound Noise session does not authorize signing key replacement`() = runBlocking {
        whenever(delegate.getPeerInfo(peerID)).thenReturn(peerInfo(signingPublicKey = ByteArray(32) { 0x44 }))
        whenever(delegate.hasNoiseSession(peerID)).thenReturn(true)
        val packet = announcePacket(ageMs = 0)

        val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

        assertFalse(result)
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `persisted authenticated Ed key rejects copied-static preannounce after restart`() = runBlocking {
        whenever(delegate.getAuthenticatedSigningKey(any())).thenReturn(ByteArray(32) { 0x44 })
        val packet = announcePacket(ageMs = 0)

        val result = handler.handleAnnounce(RoutedPacket(packet, peerID, "direct-link"))

        assertFalse(result)
        verify(delegate, never()).updatePeerInfoFromVerifiedAnnouncement(
            any(), any(), any(), any(), any(), anyOrNull()
        )
        Unit
    }

    @Test
    fun `repeated decrypt failures reset stale session and re-handshake`() = runBlocking {
        whenever(delegate.decryptFromPeer(any(), eq(peerID))).thenReturn(null)
        whenever(delegate.hasNoiseSession(peerID)).thenReturn(true)
        val packet = encryptedPacket()

        repeat(2) {
            assertFalse(handler.handleNoiseEncrypted(RoutedPacket(packet, peerID, "direct-link")))
        }
        verify(delegate, never()).removeNoiseSession(any())
        verify(delegate, never()).initiateNoiseHandshake(any())

        assertFalse(handler.handleNoiseEncrypted(RoutedPacket(packet, peerID, "direct-link")))
        verify(delegate).removeNoiseSession(peerID)
        verify(delegate).initiateNoiseHandshake(peerID)
    }

    @Test
    fun `successful decrypt resets the failure counter`() = runBlocking {
        whenever(delegate.hasNoiseSession(peerID)).thenReturn(true)
        val plaintext = NoisePayload(NoisePayloadType.DELIVERED, "id-1".toByteArray()).encode()
        whenever(delegate.decryptFromPeer(any(), eq(peerID)))
            .thenReturn(null)
            .thenReturn(null)
            .thenReturn(NoiseDecryptionResult(plaintext, authenticatedSession))
            .thenReturn(null)
            .thenReturn(null)
        val packet = encryptedPacket()

        repeat(5) {
            handler.handleNoiseEncrypted(RoutedPacket(packet, peerID, "direct-link"))
        }

        verify(delegate, never()).removeNoiseSession(any())
        verify(delegate, never()).initiateNoiseHandshake(any())
    }

    @Test
    fun `decrypt failures without an established session never reset`() = runBlocking {
        whenever(delegate.decryptFromPeer(any(), eq(peerID))).thenReturn(null)
        whenever(delegate.hasNoiseSession(peerID)).thenReturn(false)
        val packet = encryptedPacket()

        repeat(4) {
            assertFalse(handler.handleNoiseEncrypted(RoutedPacket(packet, peerID, "direct-link")))
        }

        verify(delegate, never()).removeNoiseSession(any())
        verify(delegate, never()).initiateNoiseHandshake(any())
    }

    @Test
    fun `successful decrypt reports the packet as valid`() = runBlocking {
        val plaintext = NoisePayload(NoisePayloadType.DELIVERED, "id-2".toByteArray()).encode()
        whenever(delegate.decryptFromPeer(any(), eq(peerID))).thenReturn(
            NoiseDecryptionResult(plaintext, authenticatedSession)
        )

        assertTrue(handler.handleNoiseEncrypted(RoutedPacket(encryptedPacket(), peerID, "direct-link")))
    }

    private fun encryptedPacket(): BitchatPacket = BitchatPacket(
        version = 1u,
        type = MessageType.NOISE_ENCRYPTED.value,
        senderID = peerID.hexToBytes(),
        recipientID = myPeerID.hexToBytes(),
        timestamp = System.currentTimeMillis().toULong(),
        payload = byteArrayOf(0x41, 0x42, 0x43),
        ttl = 7u
    )

    private fun announcePacket(
        ageMs: Long,
        ttl: UByte = (AppConstants.MESSAGE_TTL_HOPS.toInt() - 1).toUByte(),
        capabilities: PeerCapabilities? = null,
        noisePublicKey: ByteArray = noiseKey
    ): BitchatPacket {
        val announcement = IdentityAnnouncement(
            nickname = nickname,
            noisePublicKey = noisePublicKey,
            signingPublicKey = signingKey,
            capabilities = capabilities
        )
        return BitchatPacket(
            version = 1u,
            type = MessageType.ANNOUNCE.value,
            senderID = peerID.hexToBytes(),
            recipientID = SpecialRecipients.BROADCAST,
            timestamp = (System.currentTimeMillis() - ageMs).toULong(),
            payload = announcement.encode()!!,
            signature = signature,
            ttl = ttl
        )
    }

    private fun String.hexToBytes(): ByteArray {
        return chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    }

    private fun peerInfo(signingPublicKey: ByteArray) = PeerInfo(
        id = peerID,
        nickname = nickname,
        isConnected = true,
        isDirectConnection = true,
        noisePublicKey = noiseKey,
        signingPublicKey = signingPublicKey,
        isVerifiedNickname = true,
        lastSeen = System.currentTimeMillis()
    )
}

package com.bitchat.android.mesh

import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.protocol.SpecialRecipients
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import kotlinx.coroutines.withTimeoutOrNull
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class PacketProcessorAnnounceSideEffectTest {
    private val processors = mutableListOf<PacketProcessor>()

    @After
    fun tearDown() {
        processors.forEach(PacketProcessor::shutdown)
    }

    @Test
    fun `rejected announce does not update last seen or relay`() = runBlocking {
        val delegate = RecordingDelegate(acceptAnnounce = false)
        val processor = processor(delegate)

        processor.processPacket(announce())
        withTimeout(1_000) { delegate.handled.await() }

        assertNull(withTimeoutOrNull(250) { delegate.lastSeen.await() })
        assertEquals(0, delegate.relayCount)
    }

    @Test
    fun `accepted announce unlocks post-handler side effects`() = runBlocking {
        val delegate = RecordingDelegate(acceptAnnounce = true)
        val processor = processor(delegate)

        processor.processPacket(announce())

        assertEquals(PEER_ID, withTimeout(1_000) { delegate.lastSeen.await() })
    }

    @Test
    fun `rejected handshake does not update last seen`() = runBlocking {
        val delegate = RecordingDelegate(acceptAnnounce = true, acceptHandshake = false)
        val processor = processor(delegate)

        processor.processPacket(handshake())
        withTimeout(1_000) { delegate.handshakeHandled.await() }

        assertNull(withTimeoutOrNull(250) { delegate.lastSeen.await() })
    }

    @Test
    fun `accepted handshake updates last seen`() = runBlocking {
        val delegate = RecordingDelegate(acceptAnnounce = true, acceptHandshake = true)
        val processor = processor(delegate)

        processor.processPacket(handshake())

        assertEquals(PEER_ID, withTimeout(1_000) { delegate.lastSeen.await() })
    }

    private fun processor(delegate: RecordingDelegate): PacketProcessor =
        PacketProcessor(MY_PEER_ID).also {
            it.delegate = delegate
            processors += it
        }

    private fun announce(): RoutedPacket {
        val packet = BitchatPacket(
            version = 1u,
            type = MessageType.ANNOUNCE.value,
            senderID = PEER_ID.hexToBytes(),
            recipientID = SpecialRecipients.BROADCAST,
            timestamp = System.currentTimeMillis().toULong(),
            payload = byteArrayOf(0x01),
            ttl = 7u
        )
        return RoutedPacket(packet, PEER_ID, "direct-link")
    }

    private fun handshake(): RoutedPacket {
        val packet = BitchatPacket(
            version = 1u,
            type = MessageType.NOISE_HANDSHAKE.value,
            senderID = PEER_ID.hexToBytes(),
            recipientID = MY_PEER_ID.hexToBytes(),
            timestamp = System.currentTimeMillis().toULong(),
            payload = byteArrayOf(0x01),
            ttl = 7u
        )
        return RoutedPacket(packet, PEER_ID, "direct-link")
    }

    private class RecordingDelegate(
        private val acceptAnnounce: Boolean,
        private val acceptHandshake: Boolean = false
    ) : PacketProcessorDelegate {
        val handled = CompletableDeferred<Unit>()
        val handshakeHandled = CompletableDeferred<Unit>()
        val lastSeen = CompletableDeferred<String>()
        @Volatile var relayCount = 0

        override fun validatePacketSecurity(packet: BitchatPacket, peerID: String) = true
        override fun updatePeerLastSeen(peerID: String) {
            lastSeen.complete(peerID)
        }
        override fun getPeerNickname(peerID: String): String? = null
        override fun getNetworkSize() = 1
        override fun getBroadcastRecipient(): ByteArray = SpecialRecipients.BROADCAST
        override fun handleNoiseHandshake(routed: RoutedPacket): Boolean {
            handshakeHandled.complete(Unit)
            return acceptHandshake
        }
        override fun handleNoiseEncrypted(routed: RoutedPacket) = true
        override suspend fun handleAnnounce(routed: RoutedPacket): Boolean {
            handled.complete(Unit)
            return acceptAnnounce
        }
        override fun handleMessage(routed: RoutedPacket) = Unit
        override fun handleLeave(routed: RoutedPacket) = Unit
        override fun handleFragment(packet: BitchatPacket): BitchatPacket? = null
        override fun handleRequestSync(routed: RoutedPacket) = Unit
        override fun sendAnnouncementToPeer(peerID: String) = Unit
        override fun sendCachedMessages(peerID: String) = Unit
        override fun relayPacket(routed: RoutedPacket) {
            relayCount += 1
        }
        override fun sendToPeer(peerID: String, routed: RoutedPacket) = false
    }

    private fun String.hexToBytes(): ByteArray =
        chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private companion object {
        const val MY_PEER_ID = "1111222233334444"
        const val PEER_ID = "aaaabbbbccccdddd"
    }
}

package com.bitchat.android.mesh

import com.bitchat.android.model.RoutedPacket
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.util.toHexString
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.runTest
import org.junit.Before
import org.junit.Test
import org.mockito.kotlin.any
import org.mockito.kotlin.mock
import org.mockito.kotlin.never
import org.mockito.kotlin.verify
import org.mockito.kotlin.whenever

@ExperimentalCoroutinesApi
class PacketRelayManagerTest {

    private lateinit var packetRelayManager: PacketRelayManager
    private val delegate: PacketRelayManagerDelegate = mock()

    private val myPeerID = "1111111111111111"
    private val otherPeerID = "2222222222222222"
    private val nextHopPeerID = "3333333333333333"
    private val finalRecipientID = "4444444444444444"

    @Before
    fun setUp() {
        packetRelayManager = PacketRelayManager(myPeerID)
        packetRelayManager.delegate = delegate
        whenever(delegate.getNetworkSize()).thenReturn(10)
        whenever(delegate.getBroadcastRecipient()).thenReturn(byteArrayOf(0,0,0,0,0,0,0,0))
    }

    private fun createPacket(route: List<ByteArray>?, recipient: String? = null): BitchatPacket {
        return BitchatPacket(
            type = MessageType.MESSAGE.value,
            senderID = hexStringToPeerBytes(otherPeerID),
            recipientID = recipient?.let { hexStringToPeerBytes(it) },
            timestamp = System.currentTimeMillis().toULong(),
            payload = "hello".toByteArray(),
            ttl = 5u,
            route = route
        )
    }

    @Test
    fun `packet with duplicate hops is dropped`() = runTest {
        val route = listOf(
            hexStringToPeerBytes(nextHopPeerID),
            hexStringToPeerBytes(nextHopPeerID)
        )
        val packet = createPacket(route)
        val routedPacket = RoutedPacket(packet, otherPeerID)

        packetRelayManager.handlePacketRelay(routedPacket)

        verify(delegate, never()).sendToPeer(any(), any())
        verify(delegate, never()).broadcastPacket(any())
    }

    @Test
    fun `valid source-routed packet is relayed to next hop`() = runTest {
        val route = listOf(
            hexStringToPeerBytes(myPeerID),
            hexStringToPeerBytes(nextHopPeerID)
        )
        val packet = createPacket(route, finalRecipientID)
        val routedPacket = RoutedPacket(packet, otherPeerID)
        whenever(delegate.sendToPeer(any(), any())).thenReturn(true)

        packetRelayManager.handlePacketRelay(routedPacket)

        verify(delegate).sendToPeer(org.mockito.kotlin.eq(nextHopPeerID), any())
        verify(delegate, never()).broadcastPacket(any())
    }

    @Test
    fun `last hop does not relay further`() = runTest {
        val route = listOf(
            hexStringToPeerBytes(myPeerID)
        )
        val packet = createPacket(route, finalRecipientID)
        val routedPacket = RoutedPacket(packet, otherPeerID)
        whenever(delegate.sendToPeer(any(), any())).thenReturn(true)

        packetRelayManager.handlePacketRelay(routedPacket)

        verify(delegate).sendToPeer(org.mockito.kotlin.eq(finalRecipientID), any())
        verify(delegate, never()).broadcastPacket(any())
    }

    @Test
    fun `packet with empty route is broadcast`() = runTest {
        val packet = createPacket(null)
        val routedPacket = RoutedPacket(packet, otherPeerID)

        packetRelayManager.handlePacketRelay(routedPacket)

        verify(delegate, never()).sendToPeer(any(), any())
        verify(delegate).broadcastPacket(any())
    }

    private fun hexStringToPeerBytes(hex: String): ByteArray {
        val result = ByteArray(8)
        var idx = 0
        var out = 0
        while (idx + 1 < hex.length && out < 8) {
            val b = hex.substring(idx, idx + 2).toIntOrNull(16)?.toByte() ?: 0
            result[out++] = b
            idx += 2
        }
        return result
    }
}

package com.bitchat.android.mesh

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class PowerProfileResolverTest {

    @Test
    fun `background normal without peers scans one second per minute`() {
        val profile = resolve(battery = 80, background = true, peers = false)

        assertEquals(PowerManager.BatteryBand.NORMAL, profile.batteryBand)
        assertEquals(1_000L, profile.ble.scanOnMs)
        assertEquals(59_000L, profile.ble.scanOffMs)
        assertFalse(profile.ble.continuousScan)
        assertEquals(8, profile.ble.maxConnections)
        assertEquals(60_000L, profile.meshAnnouncementIntervalMs)
    }

    @Test
    fun `any direct transport peer accelerates background BLE discovery to thirty seconds`() {
        val profile = resolve(battery = 80, background = true, peers = true)

        assertEquals(1_000L, profile.ble.scanOnMs)
        assertEquals(29_000L, profile.ble.scanOffMs)
    }

    @Test
    fun `background low profile uses selected wifi and nostr cadence`() {
        val profile = resolve(battery = 20, background = true)

        assertEquals(PowerManager.BatteryBand.LOW, profile.batteryBand)
        assertEquals(20_000L, profile.wifiAware.tcpKeepAliveMs)
        assertEquals(120_000L, profile.wifiAware.discoveryKeepAliveMs)
        assertEquals(120_000L, profile.wifiAware.connectionMaintenanceMs)
        assertEquals(600_000L, profile.wifiAware.discoveryIdleRefreshMs)
        assertEquals(900_000L, profile.wifiAware.discoveryStaleMs)
        assertEquals(600_000L, profile.nostr.presenceHeartbeatMinMs)
        assertEquals(600_000L, profile.nostr.subscriptionValidationMs)
        assertEquals(120_000L, profile.meshAnnouncementIntervalMs)
    }

    @Test
    fun `background critical profile uses slowest wifi and nostr cadence without reducing connections`() {
        val profile = resolve(battery = 10, background = true, peers = true)

        assertEquals(PowerManager.BatteryBand.CRITICAL, profile.batteryBand)
        assertEquals(30_000L, profile.wifiAware.tcpKeepAliveMs)
        assertEquals(180_000L, profile.wifiAware.discoveryKeepAliveMs)
        assertEquals(180_000L, profile.wifiAware.connectionMaintenanceMs)
        assertEquals(900_000L, profile.wifiAware.discoveryIdleRefreshMs)
        assertEquals(1_200_000L, profile.wifiAware.discoveryStaleMs)
        assertEquals(900_000L, profile.nostr.presenceHeartbeatMinMs)
        assertEquals(900_000L, profile.nostr.subscriptionValidationMs)
        assertEquals(300_000L, profile.meshAnnouncementIntervalMs)
        assertEquals(8, profile.ble.maxConnections)
    }

    @Test
    fun `foreground normal preserves balanced BLE cadence`() {
        val profile = resolve(battery = 80, background = false)

        assertEquals(PowerManager.PowerMode.BALANCED, profile.mode)
        assertEquals(8_000L, profile.ble.scanOnMs)
        assertEquals(2_000L, profile.ble.scanOffMs)
        assertEquals(5_000L, profile.wifiAware.tcpKeepAliveMs)
        assertEquals(30_000L, profile.meshAnnouncementIntervalMs)
    }

    @Test
    fun `foreground charging is performance but background charging stays power limited`() {
        val foreground = PowerProfileResolver.resolve(80, true, false, false)
        val background = PowerProfileResolver.resolve(80, true, true, false)

        assertEquals(PowerManager.PowerMode.PERFORMANCE, foreground.mode)
        assertTrue(foreground.ble.continuousScan)
        assertEquals(PowerManager.PowerMode.POWER_SAVER, background.mode)
        assertFalse(background.ble.continuousScan)
        assertEquals(59_000L, background.ble.scanOffMs)
    }

    @Test
    fun `battery thresholds are inclusive`() {
        assertEquals(PowerManager.BatteryBand.NORMAL, resolve(21, true).batteryBand)
        assertEquals(PowerManager.BatteryBand.LOW, resolve(20, true).batteryBand)
        assertEquals(PowerManager.BatteryBand.LOW, resolve(11, true).batteryBand)
        assertEquals(PowerManager.BatteryBand.CRITICAL, resolve(10, true).batteryBand)
    }

    private fun resolve(
        battery: Int,
        background: Boolean,
        peers: Boolean = false
    ) = PowerProfileResolver.resolve(
        batteryLevel = battery,
        isCharging = false,
        isBackground = background,
        hasDirectPeers = peers
    )
}

package com.bitchat.android.mesh

import com.bitchat.android.model.AuthenticatedPeerState
import com.bitchat.android.model.PeerCapabilities
import com.bitchat.android.noise.AuthenticatedNoiseSession
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class PrivateMediaSecurityTest {
    private val peerID = "0011223344556677"
    private var authenticatedSession: AuthenticatedNoiseSession? = AuthenticatedNoiseSession(
        ByteArray(32) { (it + 1).toByte() },
        ByteArray(32) { 0x51 }
    )
    private var status: AuthenticatedPeerStateStatus = AuthenticatedPeerStateStatus.Awaiting
    private var pinned = false
    private val controller = PrivateMediaSecurityController(
        authenticatedSessionProvider = { authenticatedSession },
        peerStateStatusProvider = { _, _ -> status },
        isPrivateMediaPinned = { pinned }
    )

    @Test
    fun `live session waits for fresh generation proof`() {
        assertEquals(PrivateMediaPolicyDecision.AwaitingPeerState, controller.sendPolicy(peerID))
    }

    @Test
    fun `valid private-media proof enables encrypted wire`() {
        status = AuthenticatedPeerStateStatus.Proven(
            AuthenticatedPeerState(PeerCapabilities.PRIVATE_MEDIA, ByteArray(32) { 1 })
        )
        assertTrue(controller.sendPolicy(peerID) is PrivateMediaPolicyDecision.Encrypted)
    }

    @Test
    fun `no-bit proof permits consent only when capability was never pinned`() {
        status = AuthenticatedPeerStateStatus.Proven(
            AuthenticatedPeerState(PeerCapabilities.NONE, ByteArray(32) { 1 })
        )
        assertEquals(PrivateMediaPolicyDecision.RequiresLegacyConsent, controller.sendPolicy(peerID))

        pinned = true
        assertTrue(controller.sendPolicy(peerID) is PrivateMediaPolicyDecision.Blocked)
    }

    @Test
    fun `no-proof timeout permits old-client consent but blocks pinned downgrade`() {
        status = AuthenticatedPeerStateStatus.TimedOut
        assertEquals(PrivateMediaPolicyDecision.RequiresLegacyConsent, controller.sendPolicy(peerID))

        pinned = true
        assertTrue(controller.sendPolicy(peerID) is PrivateMediaPolicyDecision.Blocked)
    }

    @Test
    fun `live session missing coordinator generation waits and never unlocks legacy`() {
        status = AuthenticatedPeerStateStatus.Missing
        assertEquals(PrivateMediaPolicyDecision.AwaitingPeerState, controller.sendPolicy(peerID))
    }

    @Test
    fun `pin never bypasses requirement for live authenticated session`() {
        pinned = true
        authenticatedSession = null
        assertEquals(PrivateMediaPolicyDecision.NeedsHandshake, controller.sendPolicy(peerID))
    }
}

package com.bitchat.android.mesh

import com.bitchat.android.model.BitchatFilePacket
import com.bitchat.android.model.NoisePayload
import com.bitchat.android.model.NoisePayloadType
import com.bitchat.android.protocol.BitchatPacket
import com.bitchat.android.protocol.MessageType
import com.bitchat.android.noise.AuthenticatedNoiseSession
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import java.util.Random

@RunWith(RobolectricTestRunner::class)
class PrivateMediaTransferPreparerTest {
    private val senderID = hex("0011223344556677")
    private val recipientID = hex("8877665544332211")
    private val authenticatedSession = AuthenticatedNoiseSession(
        ByteArray(32) { 0x21 },
        ByteArray(32) { 0x22 }
    )
    private val fragmentManagers = mutableListOf<FragmentManager>()

    @After
    fun tearDown() {
        fragmentManagers.forEach(FragmentManager::shutdown)
    }

    @Test
    fun `encrypted mode emits deployed Noise 0x20 and signs before fragmentation`() {
        var encryptedPlaintext: ByteArray? = null
        val preparer = preparer(
            policy = PrivateMediaPolicyDecision.Encrypted(authenticatedSession),
            encrypt = { bytes, _, _ ->
                encryptedPlaintext = bytes
                PrivateMediaEncryptionResult.Success(byteArrayOf(0x41) + bytes)
            }
        )

        val outcome = preparer.prepare("peer", recipientID, file(64), false)

        val ready = outcome as PrivateMediaBuildOutcome.Ready
        assertEquals(MessageType.NOISE_ENCRYPTED.value, ready.built.packet.type)
        assertNotNull(ready.built.packet.signature)
        assertEquals(PrivateMediaWireMode.ENCRYPTED_NOISE_0X20, ready.built.wireMode)
        val decoded = NoisePayload.decode(encryptedPlaintext!!)
        assertEquals(NoisePayloadType.FILE_TRANSFER, decoded?.type)
        assertEquals(0x20u.toUByte(), encryptedPlaintext!![0].toUByte())
    }

    @Test
    fun `prerelease iOS Noise 0x09 decodes as file transfer but re-encodes canonical 0x20`() {
        val filePayload = file(3).encode()!!
        val prereleasePayload = byteArrayOf(0x09) + filePayload

        val decoded = NoisePayload.decode(prereleasePayload)

        assertEquals(NoisePayloadType.FILE_TRANSFER, decoded?.type)
        assertTrue(filePayload.contentEquals(decoded?.data))
        assertEquals(0x20u.toUByte(), decoded!!.encode()[0].toUByte())
    }

    @Test
    fun `legacy mode requires consent and signing failure aborts`() {
        val noConsent = preparer(policy = PrivateMediaPolicyDecision.RequiresLegacyConsent)
            .prepare("peer", recipientID, file(64), false)
        assertTrue(noConsent is PrivateMediaBuildOutcome.RequiresLegacyConsent)

        val signingFailure = preparer(
            policy = PrivateMediaPolicyDecision.RequiresLegacyConsent,
            finalizer = { null }
        ).prepare("peer", recipientID, file(64), true)
        assertTrue(signingFailure is PrivateMediaBuildOutcome.Rejected)
        assertTrue((signingFailure as PrivateMediaBuildOutcome.Rejected).reason.contains("nothing was sent"))

        val malformedSignature = preparer(
            policy = PrivateMediaPolicyDecision.RequiresLegacyConsent,
            finalizer = { packet -> packet.copy(signature = ByteArray(0)) }
        ).prepare("peer", recipientID, file(64), true)
        assertTrue(malformedSignature is PrivateMediaBuildOutcome.Rejected)
    }

    @Test
    fun `consented legacy mode is signed directed raw 0x22`() {
        val outcome = preparer(policy = PrivateMediaPolicyDecision.RequiresLegacyConsent)
            .prepare("peer", recipientID, file(64), true)

        val ready = outcome as PrivateMediaBuildOutcome.Ready
        assertEquals(MessageType.FILE_TRANSFER.value, ready.built.packet.type)
        assertTrue(ready.built.packet.recipientID!!.contentEquals(recipientID))
        assertNotNull(ready.built.packet.signature)
        assertEquals(PrivateMediaWireMode.SIGNED_DIRECTED_RAW_0X22, ready.built.wireMode)
    }

    @Test
    fun `handshake requirement returns before encoding signing encryption or fragmentation`() {
        var encrypted = false
        var finalized = false
        var fragmented = false
        val fragmentManager = FragmentManager().also { fragmentManagers += it }
        val preparer = PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = { PrivateMediaPolicyDecision.NeedsHandshake },
            encrypt = { _, _, _ ->
                encrypted = true
                PrivateMediaEncryptionResult.Success(byteArrayOf(1))
            },
            finalizeRoutedAndSigned = {
                finalized = true
                it
            },
            fragment = { packet, maxFragments ->
                fragmented = true
                fragmentManager.createFragments(packet, maxFragments)
            }
        )

        val outcome = preparer.prepare("peer", recipientID, file(64), false)

        assertEquals(PrivateMediaBuildOutcome.NeedsHandshake, outcome)
        assertTrue(!encrypted)
        assertTrue(!finalized)
        assertTrue(!fragmented)
    }

    @Test
    fun `peer-state wait returns before encoding signing encryption or fragmentation`() {
        var encrypted = false
        var finalized = false
        var fragmented = false
        val fragmentManager = FragmentManager().also { fragmentManagers += it }
        val preparer = PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = { PrivateMediaPolicyDecision.AwaitingPeerState },
            encrypt = { _, _, _ ->
                encrypted = true
                PrivateMediaEncryptionResult.Success(byteArrayOf(1))
            },
            finalizeRoutedAndSigned = {
                finalized = true
                it
            },
            fragment = { packet, maxFragments ->
                fragmented = true
                fragmentManager.createFragments(packet, maxFragments)
            }
        )

        val outcome = preparer.prepare("peer", recipientID, file(64), false)

        assertEquals(PrivateMediaBuildOutcome.AwaitingPeerState, outcome)
        assertTrue(!encrypted)
        assertTrue(!finalized)
        assertTrue(!fragmented)
    }

    @Test
    fun `impossible content size rejects before policy encryption signing or fragmentation`() {
        var policyChecked = false
        var encrypted = false
        var finalized = false
        var fragmented = false
        val absolutePayloadUpperBound =
            com.bitchat.android.util.AppConstants.Fragmentation.MAX_FRAGMENTS_PER_ID *
                com.bitchat.android.util.AppConstants.Fragmentation.MAX_FRAGMENT_SIZE
        val preparer = PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = {
                policyChecked = true
                PrivateMediaPolicyDecision.Encrypted(authenticatedSession)
            },
            encrypt = { _, _, _ ->
                encrypted = true
                PrivateMediaEncryptionResult.Success(byteArrayOf(1))
            },
            finalizeRoutedAndSigned = {
                finalized = true
                it
            },
            fragment = { _, _ ->
                fragmented = true
                emptyList()
            }
        )

        val outcome = preparer.prepare(
            "peer",
            recipientID,
            file(absolutePayloadUpperBound + 1),
            false
        )

        assertTrue(outcome is PrivateMediaBuildOutcome.Rejected)
        assertTrue((outcome as PrivateMediaBuildOutcome.Rejected).reason.contains("256"))
        assertTrue(!policyChecked)
        assertTrue(!encrypted)
        assertTrue(!finalized)
        assertTrue(!fragmented)
    }

    @Test
    fun `no route accepts 256 final fragments and rejects 257`() {
        assertExactBoundary(route = null)
    }

    @Test
    fun `source route accepts 256 final fragments and rejects 257`() {
        assertExactBoundary(
            route = listOf(
                hex("1021324354657687"),
                hex("2031425364758697"),
                hex("30415263748596a7")
            )
        )
    }

    @Test
    fun `generation churn re-runs policy once instead of losing the send intent`() {
        val replacementSession = AuthenticatedNoiseSession(
            authenticatedSession.remoteStaticKey,
            ByteArray(32) { 0x23 }
        )
        var policyCalls = 0
        val fragmentManager = FragmentManager().also { fragmentManagers += it }
        val preparer = PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = {
                policyCalls += 1
                PrivateMediaPolicyDecision.Encrypted(
                    if (policyCalls == 1) authenticatedSession else replacementSession
                )
            },
            encrypt = { bytes, _, session ->
                if (session == authenticatedSession) {
                    PrivateMediaEncryptionResult.GenerationChanged
                } else {
                    PrivateMediaEncryptionResult.Success(byteArrayOf(0x41) + bytes)
                }
            },
            finalizeRoutedAndSigned = { it.copy(signature = ByteArray(64) { 0x33 }) },
            fragment = fragmentManager::createFragments
        )

        val outcome = preparer.prepare("peer", recipientID, file(64), false)

        assertTrue(outcome is PrivateMediaBuildOutcome.Ready)
        assertEquals(2, policyCalls)
    }

    @Test
    fun `repeated generation churn remains retryable`() {
        val fragmentManager = FragmentManager().also { fragmentManagers += it }
        val preparer = PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = { PrivateMediaPolicyDecision.Encrypted(authenticatedSession) },
            encrypt = { _, _, _ -> PrivateMediaEncryptionResult.GenerationChanged },
            finalizeRoutedAndSigned = { it.copy(signature = ByteArray(64) { 0x33 }) },
            fragment = fragmentManager::createFragments
        )

        assertEquals(
            PrivateMediaBuildOutcome.AwaitingPeerState,
            preparer.prepare("peer", recipientID, file(64), false)
        )
    }

    private fun assertExactBoundary(route: List<ByteArray>?) {
        val randomContent = ByteArray(180 * 1024).also { Random(0xB17C4A7).nextBytes(it) }
        val preparer = preparer(
            policy = PrivateMediaPolicyDecision.Encrypted(authenticatedSession),
            finalizer = { packet ->
                packet.copy(
                    version = if (route == null) packet.version else 2u,
                    route = route,
                    signature = ByteArray(64) { 0x5A }
                )
            }
        )

        fun outcome(contentSize: Int): PrivateMediaBuildOutcome = preparer.prepare(
            "peer",
            recipientID,
            BitchatFilePacket(
                fileName = "boundary.bin",
                fileSize = contentSize.toLong(),
                mimeType = "application/octet-stream",
                content = randomContent.copyOf(contentSize)
            ),
            false
        )

        var low = 1
        var high = randomContent.size
        while (low < high) {
            val mid = low + (high - low) / 2
            if (outcome(mid) is PrivateMediaBuildOutcome.Rejected) high = mid else low = mid + 1
        }

        val accepted = outcome(low - 1) as PrivateMediaBuildOutcome.Ready
        val rejected = outcome(low)
        assertEquals(256, accepted.built.fragments.size)
        assertTrue(rejected is PrivateMediaBuildOutcome.Rejected)
        assertTrue((rejected as PrivateMediaBuildOutcome.Rejected).reason.contains("256"))
    }

    private fun preparer(
        policy: PrivateMediaPolicyDecision,
        encrypt: (
            ByteArray,
            String,
            AuthenticatedNoiseSession
        ) -> PrivateMediaEncryptionResult = { bytes, _, _ ->
            PrivateMediaEncryptionResult.Success(byteArrayOf(0x01) + bytes)
        },
        finalizer: (BitchatPacket) -> BitchatPacket? = { packet ->
            packet.copy(signature = ByteArray(64) { 0x33 })
        }
    ): PrivateMediaTransferPreparer {
        val fragmentManager = FragmentManager().also { fragmentManagers += it }
        return PrivateMediaTransferPreparer(
            senderID = senderID,
            ttl = 7u,
            policyProvider = { policy },
            encrypt = encrypt,
            finalizeRoutedAndSigned = finalizer,
            fragment = fragmentManager::createFragments,
            now = { 1_700_000_000_000uL }
        )
    }

    private fun file(size: Int) = BitchatFilePacket(
        fileName = "test.bin",
        fileSize = size.toLong(),
        mimeType = "application/octet-stream",
        content = ByteArray(size) { it.toByte() }
    )

    private fun hex(value: String): ByteArray =
        value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
}

package com.bitchat.android.mesh

import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.delay
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class RetryingControlPacketSenderTest {
    @Test
    fun `control packet is sent for the full redundant retry window`() = runTest {
        val attempts = mutableListOf<Int>()
        val sender = RetryingControlPacketSender(
            scope = this,
            maxAttempts = 3,
            retryDelayMs = 10,
            interSendDelayMs = 1
        )

        sender.enqueue(
            key = "peer:message",
            sendAttempt = { attempt ->
                attempts += attempt
                true
            }
        )
        advanceUntilIdle()

        assertEquals(listOf(1, 2, 3), attempts)
    }

    @Test
    fun `duplicate enqueue is coalesced while receipt retry is active`() = runTest {
        var firstRequestAttempts = 0
        var duplicateRequestAttempts = 0
        val sender = RetryingControlPacketSender(
            scope = this,
            maxAttempts = 3,
            retryDelayMs = 10,
            interSendDelayMs = 1
        )

        sender.enqueue(
            key = "peer:message",
            sendAttempt = {
                firstRequestAttempts += 1
                true
            }
        )
        sender.enqueue(
            key = "peer:message",
            sendAttempt = {
                duplicateRequestAttempts += 1
                true
            }
        )
        advanceUntilIdle()

        assertEquals(3, firstRequestAttempts)
        assertEquals(0, duplicateRequestAttempts)
    }

    @Test
    fun `transport writes for different receipts are serialized`() = runTest {
        var activeWrites = 0
        var maximumActiveWrites = 0
        val sender = RetryingControlPacketSender(
            scope = this,
            maxAttempts = 1,
            retryDelayMs = 0,
            interSendDelayMs = 0
        )

        fun enqueue(key: String) {
            sender.enqueue(
                key = key,
                sendAttempt = {
                    activeWrites += 1
                    maximumActiveWrites = maxOf(maximumActiveWrites, activeWrites)
                    delay(10)
                    activeWrites -= 1
                    true
                }
            )
        }

        enqueue("peer:first")
        enqueue("peer:second")
        advanceUntilIdle()

        assertEquals(1, maximumActiveWrites)
    }

    @Test
    fun `completion reports whether transport accepted any attempt`() = runTest {
        val completions = mutableListOf<Boolean>()
        val sender = RetryingControlPacketSender(
            scope = this,
            maxAttempts = 3,
            retryDelayMs = 1,
            interSendDelayMs = 0
        )

        sender.enqueue(
            key = "peer:rejected",
            sendAttempt = { false },
            onComplete = completions::add
        )
        sender.enqueue(
            key = "peer:eventually-accepted",
            sendAttempt = { attempt -> attempt == 2 },
            onComplete = completions::add
        )
        advanceUntilIdle()

        assertEquals(2, completions.size)
        assertEquals(setOf(false, true), completions.toSet())
    }
}

