@RunWith(RobolectricTestRunner::class)
class IncomingMessageAdmissionTest {
    private lateinit var context: Context
    private lateinit var databaseName: String
    private lateinit var repository: ConversationRepository
    private val repositoriesToClose = mutableListOf<ConversationRepository>()

    @Before
    fun setUp() {
        context = ApplicationProvider.getApplicationContext()
        databaseName = "admission-test-${UUID.randomUUID()}.db"
        repository = ConversationRepository(
            context = context,
            dispatcher = Dispatchers.Unconfined,
            databaseName = databaseName,
            storageCipher = InMemoryConversationStorageCipher()
        )
        repositoriesToClose += repository
        AppStateStore.setConversationRepositoryForTest(repository)
        AppStateStore.resumePrivateConversationsAfterPanic()
        AppStateStore.clear()
    }

    @After
    fun tearDown() {
        AppStateStore.resumePrivateConversationsAfterPanic()
        AppStateStore.clear()
        AppStateStore.setConversationRepositoryForTest(null)
        repositoriesToClose.forEach(ConversationRepository::closeForTest)
        context.deleteDatabase(databaseName)
        context.deleteDatabase("failing-$databaseName")
    }

    @Test
    fun `private message rejected during panic cannot continue transport dispatch`() {
        assertTrue(runBlocking { AppStateStore.panicClearPrivateConversations() })

        assertFalse(
            IncomingMessageAdmission.admitToAppState(
                privateMessage(id = "during-panic")
            )
        )
        assertTrue(AppStateStore.privateMessages.value.isEmpty())
    }

    @Test
    fun `duplicate private transport delivery is rejected before downstream effects`() {
        val message = privateMessage(id = "same-message-over-two-transports")

        assertTrue(IncomingMessageAdmission.admitToAppState(message))
        assertFalse(IncomingMessageAdmission.admitToAppState(message))
    }

    @Test
    fun `older retained replay is rejected after summary-only restart`() {
        val older = privateMessage(id = "older-retained")
        val latest = privateMessage(id = "latest-summary").copy(timestamp = Date(2L))
        assertTrue(IncomingMessageAdmission.admitToAppState(older))
        assertTrue(IncomingMessageAdmission.admitToAppState(latest))

        AppStateStore.clear()
        repository.reload { snapshot ->
            AppStateStore.restorePrivateConversations(snapshot)
        }
        runBlocking { repository.awaitPendingWrites() }
        assertEquals(
            listOf(latest.id),
            AppStateStore.privateMessages.value.getValue("peer-a").map { it.id }
        )

        assertFalse(IncomingMessageAdmission.admitToAppState(older))
        assertEquals(
            listOf(latest.id),
            AppStateStore.privateMessages.value.getValue("peer-a").map { it.id }
        )
    }

    @Test
    fun `delivery receipt persists after older message is unloaded from memory`() {
        val older = privateMessage(id = "older-outgoing").copy(
            sender = "me",
            senderPeerID = "self",
            recipientNickname = "alice",
            deliveryStatus = DeliveryStatus.Sent
        )
        val latest = privateMessage(id = "latest-summary").copy(timestamp = Date(2L))
        assertTrue(AppStateStore.addPrivateMessage("peer-a", older, forceRead = true))
        assertTrue(IncomingMessageAdmission.admitToAppState(latest))
        runBlocking { repository.awaitPendingWrites() }

        AppStateStore.releasePrivateConversationHistory("peer-a")
        assertEquals(
            listOf(latest.id),
            AppStateStore.privateMessages.value.getValue("peer-a").map { it.id }
        )

        val delivered = DeliveryStatus.Delivered(to = "alice", at = Date(3L))
        AppStateStore.updatePrivateMessageStatus(older.id, delivered)
        runBlocking { repository.awaitPendingWrites() }

        val snapshot = runBlocking {
            repository.loadConversationAndWait("peer-a")
        }
        assertEquals(
            delivered,
            snapshot?.chats?.getValue("peer-a")
                ?.single { it.id == older.id }
                ?.deliveryStatus
        )
    }

    @Test
    fun `public and channel messages preserve best effort admission`() {
        val public = BitchatMessage(
            id = "public",
            sender = "alice",
            content = "hello",
            timestamp = Date(1L)
        )
        val channel = public.copy(id = "channel", channel = "#mesh")

        assertTrue(IncomingMessageAdmission.admitToAppState(public))
        assertTrue(IncomingMessageAdmission.admitToAppState(channel))
        assertTrue(AppStateStore.publicMessages.value.contains(public))
    }

    @Test
    fun `outgoing callback runs only after local echo survives process state clear`() {
        val state = ChatState(TestScope())
        state.setNickname("me")
        val manager = PrivateChatManager(
            state = state,
            messageManager = MessageManager(state),
            dataManager = DataManager(context),
            noiseSessionDelegate = testNoiseDelegate()
        )
        var callbackInvoked = false

        val sent = runBlocking {
            manager.sendPrivateMessageDurably(
                content = "durable outgoing",
                peerID = "peer-a",
                recipientNickname = "alice",
                senderNickname = "me",
                myPeerID = "self"
            ) { _, _, _, _ ->
                callbackInvoked = true
            }
        }

        assertTrue(sent)
        assertTrue(callbackInvoked)
        AppStateStore.clear()
        repository.reload { snapshot ->
            assertEquals(
                "durable outgoing",
                snapshot.chats.getValue("peer-a").single().content
            )
        }
        runBlocking { repository.awaitPendingWrites() }
    }

    @Test
    fun `outgoing messages to different peers keep separate persisted conversations`() {
        val state = ChatState(TestScope())
        state.setNickname("me")
        val manager = PrivateChatManager(
            state = state,
            messageManager = MessageManager(state),
            dataManager = DataManager(context),
            noiseSessionDelegate = testNoiseDelegate()
        )

        runBlocking {
            assertTrue(
                manager.sendPrivateMessageDurably(
                    content = "only for alice",
                    peerID = "peer-a",
                    recipientNickname = "alice",
                    senderNickname = "me",
                    myPeerID = "self"
                ) { _, _, _, _ -> }
            )
            assertTrue(
                manager.sendPrivateMessageDurably(
                    content = "only for bob",
                    peerID = "peer-b",
                    recipientNickname = "bob",
                    senderNickname = "me",
                    myPeerID = "self"
                ) { _, _, _, _ -> }
            )

            val alice = repository.loadConversationAndWait("peer-a")
            val bob = repository.loadConversationAndWait("peer-b")

            assertEquals(
                listOf("only for alice"),
                alice?.chats?.getValue("peer-a")?.map { it.content }
            )
            assertEquals(
                listOf("only for bob"),
                bob?.chats?.getValue("peer-b")?.map { it.content }
            )
        }
    }

    @Test
    fun `outgoing callback is suppressed when durable storage fails`() {
        val failingRepository = ConversationRepository(
            context = context,
            dispatcher = Dispatchers.Unconfined,
            databaseName = "failing-$databaseName",
            storageCipher = object : ConversationStorageCipher {
                override fun encrypt(
                    plaintext: ByteArray,
                    associatedData: ByteArray
                ): ByteArray = error("storage unavailable")

                override fun decrypt(
                    envelope: ByteArray,
                    associatedData: ByteArray
                ): ByteArray = error("storage unavailable")

                override fun destroyKey() = Unit
            }
        )
        repositoriesToClose += failingRepository
        AppStateStore.setConversationRepositoryForTest(failingRepository)
        val state = ChatState(TestScope())
        val manager = PrivateChatManager(
            state = state,
            messageManager = MessageManager(state),
            dataManager = DataManager(context),
            noiseSessionDelegate = testNoiseDelegate()
        )
        var callbackInvoked = false

        val sent = runBlocking {
            manager.sendPrivateMessageDurably(
                "lost",
                "peer-a",
                "alice",
                "me",
                "self"
            ) { _, _, _, _ -> callbackInvoked = true }
        }

        assertFalse(sent)
        assertFalse(callbackInvoked)
        assertTrue(state.getPrivateChatsValue().isEmpty())
    }

    private fun privateMessage(id: String) = BitchatMessage(
        id = id,
        sender = "alice",
        content = "secret",
        timestamp = Date(1L),
        isPrivate = true,
        senderPeerID = "peer-a"
    )

    private fun testNoiseDelegate() = object : NoiseSessionDelegate {
        override fun hasEstablishedSession(peerID: String) = false
        override fun initiateHandshake(peerID: String) = Unit
        override fun getMyPeerID() = "self"
    }
}

package com.bitchat.android.services.meshgraph

import org.junit.Assert.*
import org.junit.Test
import org.junit.Before

class MeshGraphServiceTest {

    private lateinit var service: MeshGraphService

    @Before
    fun setUp() {
        // Use the test-only API to reset the singleton state safely
        MeshGraphService.resetForTesting()
        service = MeshGraphService.getInstance()
    }

    @Test
    fun testUpdateFromAnnouncement_AddsNeighbors() {
        val origin = "PeerA"
        val neighbors = listOf("PeerB", "PeerC")
        val timestamp = 100UL

        service.updateFromAnnouncement(origin, "Alice", neighbors, timestamp)

        val snapshot = service.graphState.value
        // Verify nodes
        assertTrue(snapshot.nodes.any { it.peerID == "PeerA" })
        assertTrue(snapshot.nodes.any { it.peerID == "PeerB" })
        assertTrue(snapshot.nodes.any { it.peerID == "PeerC" })

        // Verify edges (unconfirmed because B and C haven't announced A)
        // A -> B
        val edgeAB = snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerB") || (it.a == "PeerB" && it.b == "PeerA") }
        assertNotNull(edgeAB)
        assertFalse(edgeAB!!.isConfirmed)
        assertEquals("PeerA", edgeAB.confirmedBy)

        // A -> C
        val edgeAC = snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerC") || (it.a == "PeerC" && it.b == "PeerA") }
        assertNotNull(edgeAC)
        assertFalse(edgeAC!!.isConfirmed)
        assertEquals("PeerA", edgeAC.confirmedBy)
    }

    @Test
    fun testUpdateFromAnnouncement_NewerTimestampReplacesNeighbors() {
        val origin = "PeerA"

        // Initial state: A -> {B, C}
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerB", "PeerC"), 100UL)

        // Update: A -> {B, D} (newer timestamp)
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerB", "PeerD"), 200UL)

        val snapshot = service.graphState.value

        // Verify Edge A-B exists
        assertNotNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerB") || (it.a == "PeerB" && it.b == "PeerA") })

        // Verify Edge A-D exists
        assertNotNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerD") || (it.a == "PeerD" && it.b == "PeerA") })

        // Verify Edge A-C does NOT exist
        assertNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerC") || (it.a == "PeerC" && it.b == "PeerA") })
    }

    @Test
    fun testUpdateFromAnnouncement_OlderTimestampIsIgnored() {
        val origin = "PeerA"

        // Initial state: A -> {B, C} at ts=200
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerB", "PeerC"), 200UL)

        // Old Update: A -> {D} at ts=100
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerD"), 100UL)

        val snapshot = service.graphState.value

        // Should still be {B, C}
        assertNotNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerB") || (it.a == "PeerB" && it.b == "PeerA") })
        assertNotNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerC") || (it.a == "PeerC" && it.b == "PeerA") })
        assertNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerD") || (it.a == "PeerD" && it.b == "PeerA") })
    }

    @Test
    fun testUpdateFromAnnouncement_NullNeighborsClearsList_TheFix() {
        val origin = "PeerA"

        // Initial state: A -> {B, C} at ts=100
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerB", "PeerC"), 100UL)

        // Update with NULL neighbors (omitted TLV) at ts=200
        service.updateFromAnnouncement(origin, "Alice", null, 200UL)

        val snapshot = service.graphState.value

        // All edges from A should be gone
        val edgesFromA = snapshot.edges.filter { it.a == "PeerA" || it.b == "PeerA" }
        assertTrue("Edges from PeerA should be empty after null update", edgesFromA.isEmpty())

        // Nodes B and C might still exist if they were added to the node list, but connected edges are gone.
        // Actually, publishSnapshot collects nodes from nicknames and announcements.
        // Since we provided nicknames for PeerA, it should be there.
        // PeerB and PeerC were only in announcements. Since A's announcement is cleared, and B/C never announced, 
        // they might disappear from the node list if 'nicknames' doesn't contain them.
        // Let's check edges primarily as that's what routing cares about.
    }

    @Test
    fun testUpdateFromAnnouncement_NullNeighborsWithOlderTimestampIsIgnored() {
        val origin = "PeerA"

        // Initial state: A -> {B, C} at ts=200
        service.updateFromAnnouncement(origin, "Alice", listOf("PeerB", "PeerC"), 200UL)

        // Old Update with NULL neighbors at ts=100
        service.updateFromAnnouncement(origin, "Alice", null, 100UL)

        val snapshot = service.graphState.value

        // Should still be {B, C} because the null update was older
        assertFalse(snapshot.edges.isEmpty())
        assertNotNull(snapshot.edges.find { (it.a == "PeerA" && it.b == "PeerB") || (it.a == "PeerB" && it.b == "PeerA") })
    }

    @Test
    fun removePeer_RemovesInboundAndOutboundGraphReferences() {
        service.updateFromAnnouncement("PeerA", "Alice", listOf("PeerB"), 100UL)
        service.updateFromAnnouncement("PeerB", "Bob", listOf("PeerA", "PeerC"), 100UL)
        service.updateFromAnnouncement("PeerC", "Carol", listOf("PeerB"), 100UL)

        service.removePeer("PeerB")

        val snapshot = service.graphState.value
        assertFalse(snapshot.nodes.any { it.peerID == "PeerB" })
        assertFalse(snapshot.edges.any { it.a == "PeerB" || it.b == "PeerB" })
        assertTrue(snapshot.nodes.any { it.peerID == "PeerA" })
        assertTrue(snapshot.nodes.any { it.peerID == "PeerC" })
    }
}

package com.bitchat.android.sync

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Random

class GCSFilterTest {

    @Test
    fun testGCSFilterBasic() {
        val random = Random(42)
        val ids = List(20) {
            val bytes = ByteArray(16)
            random.nextBytes(bytes)
            bytes
        }

        // Build filter with plenty of bytes (no trimming)
        val params = GCSFilter.buildFilter(ids, maxBytes = 400, targetFpr = 0.01)
        val sorted = GCSFilter.decodeToSortedSet(params.p, params.m, params.data)

        for (id in ids) {
            val v = GCSFilter.h64(id) % params.m
            val nonZeroV = if (v == 0L) 1L else v
            assertTrue("Filter should contain all encoded IDs", GCSFilter.contains(sorted, nonZeroV))
        }
    }

    @Test
    fun testGCSFilterWithTrimming() {
        val random = Random(42)
        // 50 IDs
        val ids = List(50) {
            val bytes = ByteArray(16)
            random.nextBytes(bytes)
            bytes
        }

        // Force trimming by setting maxBytes to a very small value (e.g., 20 bytes)
        val maxBytes = 20
        val params = GCSFilter.buildFilter(ids, maxBytes = maxBytes, targetFpr = 0.01)

        // Ensure some trimming actually happened
        assertTrue("Params data size should be <= maxBytes", params.data.size <= maxBytes)

        val sorted = GCSFilter.decodeToSortedSet(params.p, params.m, params.data)

        // Let's verify that the first trimmedN elements in ids are all matched
        val trimmedN = (params.m ushr params.p).toInt()
        assertTrue("At least some elements should have been encoded", trimmedN > 0)

        val retainedIds = ids.take(trimmedN)
        for (id in retainedIds) {
            val v = GCSFilter.h64(id) % params.m
            val nonZeroV = if (v == 0L) 1L else v
            assertTrue("Retained ID should be found in filter", GCSFilter.contains(sorted, nonZeroV))
        }
    }

    @Test
    fun testGCSFilterHandlesCollisionsAndZeroBucket() {
        val random = Random(42)
        // Generate a large number of IDs to guarantee collisions (mapping to the same bucket) and some zero-bucket mapping
        val ids = List(200) {
            val bytes = ByteArray(16)
            random.nextBytes(bytes)
            bytes
        }

        // Build GCS filter - this should complete successfully without throwing repeat count exceptions or negative-count crashes
        val params = GCSFilter.buildFilter(ids, maxBytes = 100, targetFpr = 0.05)
        val sorted = GCSFilter.decodeToSortedSet(params.p, params.m, params.data)

        // Verify elements are successfully stored and found (including those mapping to 0)
        var foundCount = 0
        for (id in ids) {
            val v = GCSFilter.h64(id) % params.m
            val nonZeroV = if (v == 0L) 1L else v
            if (GCSFilter.contains(sorted, nonZeroV)) {
                foundCount++
            }
        }
        assertTrue("Should successfully decode and find elements after deduplication", foundCount > 0)
    }
}

package com.bitchat.android.ui

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

class LanguageCatalogContractTest {
    private val resourcesDirectory = File("src/main/res")

    @Test
    fun `locale config contains every shipped locale exactly once`() {
        val shippedLanguageTags = resourcesDirectory
            .listFiles()
            .orEmpty()
            .filter { it.isDirectory && it.name.startsWith("values-") }
            .mapNotNull { directory -> directory.name.toLanguageTagOrNull() }
            .toSet()

        val configuredLanguageTags = Regex("""android:name="([^"]+)"""")
            .findAll(File(resourcesDirectory, "xml/locales_config.xml").readText())
            .map { match -> match.groupValues[1] }
            .toList()

        assertEquals(
            "Locale configuration must not contain duplicate entries",
            configuredLanguageTags.toSet().size,
            configuredLanguageTags.size,
        )
        assertEquals(shippedLanguageTags, configuredLanguageTags.toSet())
    }

    @Test
    fun `language picker strings exist in every locale pack`() {
        val requiredKeys = setOf(
            "about_language",
            "about_app_language",
            "about_system_default",
            "about_select_language",
        )

        resourcesDirectory
            .listFiles()
            .orEmpty()
            .filter { directory ->
                directory.isDirectory &&
                    (directory.name == "values" || directory.name.toLanguageTagOrNull() != null)
            }
            .forEach { directory ->
                val strings = File(directory, "strings.xml").readText()
                requiredKeys.forEach { key ->
                    assertTrue(
                        "$key is missing from ${directory.name}/strings.xml",
                        """name="$key""" in strings,
                    )
                }
            }
    }

    private fun String.toLanguageTagOrNull(): String? {
        if (!startsWith("values-") || this == "values-night") return null
        return removePrefix("values-")
            .split("-")
            .joinToString("-") { qualifier ->
                if (qualifier.startsWith("r") && qualifier.length == 3) {
                    qualifier.drop(1)
                } else {
                    qualifier
                }
            }
    }
}

