@RunWith(RobolectricTestRunner::class)
class GitHubReleaseClientTest {

    @Test
    fun `parses universal apk and GitHub asset digest`() {
        val digest = "a".repeat(64)
        val release = GitHubReleaseClient.parseRelease(
            """
            {
              "tag_name": "v1.7.6",
              "body": "",
              "assets": [
                {
                  "name": "bitchat-android-universal.apk",
                  "browser_download_url": "https://example.test/bitchat.apk",
                  "size": 49283072,
                  "digest": "sha256:$digest"
                }
              ]
            }
            """.trimIndent()
        )

        requireNotNull(release)
        assertEquals("1.7.6", release.versionName)
        assertEquals(49_283_072L, release.universalApkSize)
        assertEquals(digest, release.universalApkSha256)
    }

    @Test
    fun `falls back to checksum in release notes`() {
        val digest = "b".repeat(64)
        val release = GitHubReleaseClient.parseRelease(
            """
            {
              "tag_name": "1.7.6",
              "body": "bitchat-android-universal.apk: $digest",
              "assets": [
                {
                  "name": "bitchat-android-universal.apk",
                  "browser_download_url": "https://example.test/bitchat.apk",
                  "size": 10
                }
              ]
            }
            """.trimIndent()
        )

        assertEquals(digest, requireNotNull(release).universalApkSha256)
    }

    @Test
    fun `rejects releases without a universal apk`() {
        val release = GitHubReleaseClient.parseRelease(
            """
            {
              "tag_name": "v1.7.6",
              "assets": [
                {
                  "name": "bitchat-android-arm64.apk",
                  "browser_download_url": "https://example.test/arm64.apk",
                  "size": 10
                }
              ]
            }
            """.trimIndent()
        )

        assertNull(release)
    }

    @Test
    fun `compares release versions`() {
        val release = GitHubReleaseClient.Release(
            tagName = "v1.7.6",
            versionName = "1.7.6",
            universalApkUrl = "https://example.test/bitchat.apk",
            universalApkSha256 = null,
            universalApkSize = 10,
            universalApkName = "bitchat-android-universal.apk"
        )

        assertTrue(GitHubReleaseClient.isNewerVersion("1.7.5", release))
        assertFalse(GitHubReleaseClient.isNewerVersion("1.7.6", release))
        assertFalse(GitHubReleaseClient.isNewerVersion("1.8.0", release))
        assertTrue(GitHubReleaseClient.isNewerVersion("1.7.4", "1.7.5"))
        assertFalse(GitHubReleaseClient.isNewerVersion("1.7.5", "1.7.4"))
    }
}

package com.bitchat.android.wifiaware

import org.junit.Assert.assertNull
import org.junit.Assert.assertSame
import org.junit.Test

class IngressLinkPolicyTest {
    @Test
    fun `observation resolves only the exact ingress link`() {
        val attackerSocket = Any()
        val victimSocket = Any()
        val links = mapOf(
            "attacker-link" to IngressLinkPolicy.Link("provisional-attacker", attackerSocket),
            "victim-link" to IngressLinkPolicy.Link("provisional-victim", victimSocket)
        )
        val current = mapOf(
            "provisional-attacker" to attackerSocket,
            "provisional-victim" to victimSocket
        )

        val resolved = IngressLinkPolicy.resolve(
            ingressLinkID = "victim-link",
            relayAddress = "provisional-victim",
            links = links,
            currentTransportForRelay = current::get
        )

        assertSame(victimSocket, resolved?.transport)
    }

    @Test
    fun `stale replaced or mismatched ingress links cannot be observed`() {
        val completedSocket = Any()
        val replacementSocket = Any()
        val links = mapOf(
            "completed-link" to IngressLinkPolicy.Link("provisional", completedSocket)
        )

        assertNull(
            IngressLinkPolicy.resolve(
                ingressLinkID = "missing-link",
                relayAddress = "provisional",
                links = links,
                currentTransportForRelay = { completedSocket }
            )
        )
        assertNull(
            IngressLinkPolicy.resolve(
                ingressLinkID = "completed-link",
                relayAddress = "different-provisional",
                links = links,
                currentTransportForRelay = { completedSocket }
            )
        )
        assertNull(
            IngressLinkPolicy.resolve(
                ingressLinkID = "completed-link",
                relayAddress = "provisional",
                links = links,
                currentTransportForRelay = { replacementSocket }
            )
        )
    }
}

