fun formatVerificationCode(fingerprint: String): String {
    return fingerprint
        .uppercase()
        .chunked(4)
        .chunked(4)
        .joinToString("\n") { line -> line.joinToString(" ") }
}

package com.bitchat.watch.ui

import android.content.Context
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableLongStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import androidx.compose.ui.platform.LocalContext
import com.bitchat.android.features.voice.VoiceRecorder
import com.bitchat.android.features.voice.normalizeAmplitudeSample
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

private const val MAX_RECORDING_MS = 10_000L
private const val MIN_RECORDING_MS = 600L
private const val AMPLITUDE_POLL_MS = 80L
private const val LIVE_BARS = 32

/**
 * Push-to-talk recording controller: start on press, stop on release, 10 s cap, ~80 ms
 * amplitude polls into a rolling live-waveform buffer. Hoisted to screen level so the
 * full-screen overlay can render outside the edge-button slot.
 */
class VoiceNoteController(
    private val context: Context,
    private val scope: CoroutineScope,
    private val recorderFactory: () -> VoiceRecorder,
    private val onSendVoice: (String) -> Unit
) {
    private var recorder: VoiceRecorder? = null

    var recording by mutableStateOf(false)
        private set
    var isLive by mutableStateOf(false)
        private set
    var elapsedMs by mutableLongStateOf(0L)
        private set
    var liveSamples by mutableStateOf(FloatArray(LIVE_BARS))
        private set

    private var pollJob: Job? = null
    private var startedAt = 0L

    fun start() {
        if (recording) return
        val activeRecorder = recorderFactory()
        activeRecorder.start() ?: return
        recorder = activeRecorder
        isLive = activeRecorder.isLive
        startedAt = System.currentTimeMillis()
        elapsedMs = 0L
        liveSamples = FloatArray(LIVE_BARS)
        recording = true
        WearHaptics.knock(context)
        pollJob = scope.launch {
            while (true) {
                delay(AMPLITUDE_POLL_MS)
                val amp = normalizeAmplitudeSample(recorder?.pollAmplitude() ?: 0)
                liveSamples = liveSamples.copyOfRange(1, LIVE_BARS) + amp
                val elapsed = System.currentTimeMillis() - startedAt
                elapsedMs = elapsed
                if (elapsed >= MAX_RECORDING_MS) {
                    stop(send = true)
                    break
                }
            }
        }
    }

    fun stop(send: Boolean) {
        if (!recording) return
        recording = false
        // The send path clicks; the cancel path stays silent here because the caller
        // plays its own reject haptic.
        if (send) WearHaptics.click(context)
        pollJob?.cancel()
        pollJob = null
        val file = recorder?.stop(canceled = !send)
        recorder = null
        isLive = false
        val elapsed = System.currentTimeMillis() - startedAt
        if (send && file != null && elapsed >= MIN_RECORDING_MS) {
            onSendVoice(file.absolutePath)
        } else {
            file?.delete()
        }
    }
}

@Composable
fun rememberVoiceNoteController(
    recorderFactory: () -> VoiceRecorder,
    onSendVoice: (String) -> Unit
): VoiceNoteController {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    return remember { VoiceNoteController(context, scope, recorderFactory, onSendVoice) }
}

package com.bitchat.watch.ui

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Process-wide UI state for the watch app: unread DM counters and the currently open DM thread.
 */
object WearChatState {
    private val _unreadDms = MutableStateFlow<Map<String, Int>>(emptyMap())
    val unreadDms: StateFlow<Map<String, Int>> = _unreadDms.asStateFlow()

    @Volatile
    var appInForeground: Boolean = false
        private set

    @Volatile
    var openDmPeer: String? = null

    @Synchronized
    fun onPrivateMessageArrived(peerID: String) {
        if (appInForeground && openDmPeer == peerID) return
        _unreadDms.value = _unreadDms.value + (peerID to ((_unreadDms.value[peerID] ?: 0) + 1))
    }

    fun setAppInForeground(inForeground: Boolean) {
        appInForeground = inForeground
    }

    @Synchronized
    fun openDm(peerID: String) {
        openDmPeer = peerID
        _unreadDms.value = _unreadDms.value - peerID
    }

    @Synchronized
    fun closeDm() {
        openDmPeer = null
    }

    fun unreadCount(peerID: String): Int = _unreadDms.value[peerID] ?: 0
}

package com.bitchat.watch.ui

import android.content.Context
import android.os.Build
import android.os.VibrationEffect
import android.os.Vibrator
import android.os.VibratorManager

/**
 * Tactile accents for the watch's important moments. Uses predefined vibration effects so
 * the feel stays consistent with the rest of Wear OS.
 */
object WearHaptics {
    /** Firm knock: recording started, message received. */
    fun knock(context: Context) = vibrate(context, VibrationEffect.EFFECT_HEAVY_CLICK)

    /** Crisp click: recording stopped, message sent. */
    fun click(context: Context) = vibrate(context, VibrationEffect.EFFECT_CLICK)

    /** Double tap: destructive/cancel confirmation. */
    fun reject(context: Context) = vibrate(context, VibrationEffect.EFFECT_DOUBLE_CLICK)

    /** Light tick: small confirmations. */
    fun tick(context: Context) = vibrate(context, VibrationEffect.EFFECT_TICK)

    private fun vibrate(context: Context, effect: Int) {
        val vibrator = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            context.getSystemService(VibratorManager::class.java)?.defaultVibrator
        } else {
            @Suppress("DEPRECATION")
            context.getSystemService(Vibrator::class.java)
        } ?: return
        vibrator.vibrate(VibrationEffect.createPredefined(effect))
    }
}

package com.bitchat.watch.ui

import android.content.Context
import com.bitchat.android.favorites.FavoriteRelationship
import com.bitchat.android.favorites.FavoritesChangeListener
import com.bitchat.android.favorites.FavoritesPersistenceService
import com.bitchat.android.identity.SecureIdentityStateManager
import com.bitchat.watch.mesh.WearMeshService
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

enum class FavoriteIndicator {
    None,
    FavoritedUs,
    Favorite
}

data class WearPeerIdentitySnapshot(
    val isFavorite: Boolean,
    val theyFavoritedUs: Boolean,
    val favoriteIndicator: FavoriteIndicator,
    val fingerprint: String?,
    val isVerified: Boolean
)

fun favoriteIndicator(
    isFavorite: Boolean,
    theyFavoritedUs: Boolean
): FavoriteIndicator = when {
    isFavorite -> FavoriteIndicator.Favorite
    theyFavoritedUs -> FavoriteIndicator.FavoritedUs
    else -> FavoriteIndicator.None
}

/**
 * Process-wide bridge between the shared identity stores and the Watch Compose UI.
 *
 * Favorites are keyed by the authenticated Noise public key, while screens navigate with the
 * short mesh peer ID. The shared persistence service resolves that mapping and notifies this
 * object whenever either side changes the relationship.
 */
object WearPeerIdentityState : FavoritesChangeListener {
    private val _revision = MutableStateFlow(0L)
    val revision: StateFlow<Long> = _revision.asStateFlow()

    @Volatile
    private var initialized = false

    private lateinit var identityManager: SecureIdentityStateManager

    fun initialize(context: Context) {
        if (initialized) return
        synchronized(this) {
            if (initialized) return
            FavoritesPersistenceService.initialize(context.applicationContext)
            identityManager = SecureIdentityStateManager(context.applicationContext)
            FavoritesPersistenceService.shared.addListener(this)
            initialized = true
        }
        publishChange()
    }

    fun snapshot(peerID: String, mesh: WearMeshService?): WearPeerIdentitySnapshot {
        check(initialized) { "WearPeerIdentityState must be initialized by the application" }
        val relationship = relationship(peerID, mesh)
        val fingerprint = mesh?.getPeerFingerprint(peerID)
            ?: relationship?.peerNoisePublicKey?.let(identityManager::generateFingerprint)
        val isVerified = fingerprint != null &&
            identityManager.getVerifiedFingerprints().any {
                it.equals(fingerprint, ignoreCase = true)
            }
        val isFavorite = relationship?.isFavorite == true
        val theyFavoritedUs = relationship?.theyFavoritedUs == true
        return WearPeerIdentitySnapshot(
            isFavorite = isFavorite,
            theyFavoritedUs = theyFavoritedUs,
            favoriteIndicator = favoriteIndicator(isFavorite, theyFavoritedUs),
            fingerprint = fingerprint,
            isVerified = isVerified
        )
    }

    fun setFavorite(
        peerID: String,
        isFavorite: Boolean,
        mesh: WearMeshService
    ): Boolean {
        check(initialized) { "WearPeerIdentityState must be initialized by the application" }
        val peerInfo = mesh.getPeerInfo(peerID) ?: return false
        val noisePublicKey = peerInfo.noisePublicKey ?: return false
        val nickname = mesh.getPeerNickname(peerID)
            ?: peerInfo.nickname.takeIf(String::isNotBlank)
            ?: peerID.take(8)

        FavoritesPersistenceService.shared.updateFavoriteStatus(
            noisePublicKey = noisePublicKey,
            nickname = nickname,
            isFavorite = isFavorite
        )
        mesh.sendFavoriteNotification(peerID, isFavorite)
        return true
    }

    fun setVerified(
        peerID: String,
        verified: Boolean,
        mesh: WearMeshService?
    ): Boolean {
        check(initialized) { "WearPeerIdentityState must be initialized by the application" }
        val fingerprint = snapshot(peerID, mesh).fingerprint ?: return false
        identityManager.setVerifiedFingerprint(fingerprint.lowercase(), verified)
        publishChange()
        return true
    }

    fun myFingerprint(mesh: WearMeshService?): String? = mesh?.getIdentityFingerprint()

    override fun onFavoriteChanged(noiseKeyHex: String) {
        publishChange()
    }

    override fun onAllCleared() {
        publishChange()
    }

    private fun relationship(
        peerID: String,
        mesh: WearMeshService?
    ): FavoriteRelationship? {
        FavoritesPersistenceService.shared.getFavoriteStatus(peerID)?.let { return it }
        val noisePublicKey = mesh?.getPeerInfo(peerID)?.noisePublicKey ?: return null
        return FavoritesPersistenceService.shared.getFavoriteStatus(noisePublicKey)
    }

    private fun publishChange() {
        _revision.update { it + 1L }
    }
}

