/**
 * Compact inline image thumbnail; tap opens the full-screen viewer.
 */
@Composable
fun ImageMessageItem(path: String, onOpen: (String) -> Unit) {
    val bitmap = remember(path) { BitmapFactory.decodeFile(path) }
    if (bitmap == null) {
        FileMessageChip(name = File(path).name, sizeBytes = File(path).length())
        return
    }
    Image(
        painter = BitmapPainter(bitmap.asImageBitmap()),
        contentDescription = "image",
        contentScale = ContentScale.Crop,
        modifier = Modifier
            .padding(top = 2.dp)
            .widthIn(max = 120.dp)
            .aspectRatio(
                (bitmap.width.toFloat() / bitmap.height.toFloat()).coerceIn(0.6f, 1.8f)
            )
            .clip(RoundedCornerShape(10.dp))
            .clickable { onOpen(path) }
    )
}

/**
 * Full-screen image viewer (mirrors the phone's FullScreenImageViewer): black surface,
 * fit-to-screen, tap or swipe-back to dismiss.
 */
@Composable
fun FullScreenImageViewer(path: String, onClose: () -> Unit) {
    Dialog(
        onDismissRequest = onClose,
        properties = DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black)
                .clickable { onClose() },
            contentAlignment = Alignment.Center
        ) {
            val bitmap = remember(path) { BitmapFactory.decodeFile(path) }
            if (bitmap != null) {
                Image(
                    painter = BitmapPainter(bitmap.asImageBitmap()),
                    contentDescription = "image fullscreen",
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.fillMaxSize()
                )
            }
            Icon(
                imageVector = Icons.Filled.Close,
                contentDescription = "close",
                tint = Color.White.copy(alpha = 0.7f),
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = 24.dp)
                    .size(20.dp)
            )
        }
    }
}

/**
 * Voice-note bubble: play/pause + waveform (120 bins, extracted locally like the phone) +
 * duration/progress. Playback via MediaPlayer.
 */
@Composable
fun VoiceNoteItem(path: String, messageID: String? = null) {
    val palette = LocalBitchatPalette.current
    val context = LocalContext.current
    val liveIDs by com.bitchat.android.features.voice.LiveVoiceManager
        .getInstance(context).liveMessageIDs.collectAsState()
    val isLive = messageID != null && messageID in liveIDs
    var samples by remember { mutableStateOf(VoiceWaveformCache.get(path)) }
    var playing by remember { mutableStateOf(false) }
    var progress by remember { mutableFloatStateOf(0f) }
    var durationMs by remember { mutableIntStateOf(0) }
    val player = remember { MediaPlayer() }

    LaunchedEffect(path) {
        if (samples == null) {
            AudioWaveformExtractor.extractAsync(path) { extracted ->
                if (extracted != null) {
                    VoiceWaveformCache.put(path, extracted)
                    samples = extracted
                }
            }
        }
    }

    DisposableEffect(path) {
        runCatching {
            player.reset()
            player.setDataSource(path)
            player.setOnCompletionListener {
                playing = false
                progress = 0f
            }
            player.prepare()
            durationMs = player.duration
        }
        onDispose {
            runCatching { if (player.isPlaying) player.stop() }
            runCatching { player.release() }
        }
    }

    LaunchedEffect(playing) {
        while (playing) {
            progress = if (durationMs > 0) player.currentPosition.toFloat() / durationMs else 0f
            delay(100)
        }
    }

    Row(
        modifier = Modifier
            .padding(top = 2.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(palette.inputSurface)
            .padding(horizontal = 8.dp, vertical = 6.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (isLive) {
            Text(
                text = "LIVE",
                color = Color(0xFFFFB300),
                style = ChatVisualTokens.SystemActionStyle,
                modifier = Modifier.padding(end = 4.dp)
            )
        }
        Box(
            modifier = Modifier
                .size(26.dp)
                .clip(CircleShape)
                .background(MaterialTheme.colorScheme.primary)
                .clickable {
                    if (playing) {
                        player.pause()
                        playing = false
                    } else {
                        runCatching { player.start() }
                        playing = true
                    }
                },
            contentAlignment = Alignment.Center
        ) {
            if (playing) {
                Canvas(modifier = Modifier.size(10.dp)) {
                    val w = size.width
                    val h = size.height
                    drawRoundRect(
                        color = Color.Black,
                        topLeft = Offset(0f, 0f),
                        size = Size(w * 0.35f, h),
                        cornerRadius = CornerRadius(1.dp.toPx())
                    )
                    drawRoundRect(
                        color = Color.Black,
                        topLeft = Offset(w * 0.65f, 0f),
                        size = Size(w * 0.35f, h),
                        cornerRadius = CornerRadius(1.dp.toPx())
                    )
                }
            } else {
                Icon(
                    imageVector = Icons.Filled.PlayArrow,
                    contentDescription = "play",
                    tint = Color.Black,
                    modifier = Modifier.size(16.dp)
                )
            }
        }
        WaveformBars(
            samples = samples,
            progress = progress,
            modifier = Modifier
                .padding(start = 6.dp)
                .weight(1f)
                .height(22.dp),
            activeColor = MaterialTheme.colorScheme.primary,
            inactiveColor = palette.textTertiary.copy(alpha = 0.5f)
        )
        Text(
            text = formatDuration(if (playing) (durationMs * progress).toInt() else durationMs),
            style = ChatVisualTokens.SystemActionStyle,
            color = palette.textTertiary,
            modifier = Modifier.padding(start = 6.dp)
        )
    }
}

@Composable
fun WaveformBars(
    samples: FloatArray?,
    progress: Float,
    modifier: Modifier = Modifier,
    activeColor: Color,
    inactiveColor: Color
) {
    Canvas(modifier = modifier) {
        val bars = 32
        val values = samples?.let { com.bitchat.android.features.voice.resampleWave(it, bars) }
            ?: FloatArray(bars) { 0.3f }
        val barWidth = size.width / (bars * 2 - 1)
        for (i in 0 until bars) {
            val v = values.getOrElse(i) { 0f }.coerceIn(0.08f, 1f)
            val barHeight = size.height * v
            val x = i * barWidth * 2
            drawRoundRect(
                color = if (i.toFloat() / bars <= progress) activeColor else inactiveColor,
                topLeft = Offset(x, (size.height - barHeight) / 2f),
                size = Size(barWidth, barHeight),
                cornerRadius = CornerRadius(barWidth / 2f)
            )
        }
    }
}

/**
 * Compact chip for non-media files.
 */
@Composable
fun FileMessageChip(name: String, sizeBytes: Long) {
    val palette = LocalBitchatPalette.current
    Row(
        modifier = Modifier
            .padding(top = 2.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(palette.inputSurface)
            .padding(horizontal = 10.dp, vertical = 6.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column {
            Text(
                text = name,
                style = ChatVisualTokens.SystemActionStyle,
                color = MaterialTheme.colorScheme.onSurface,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                text = formatSize(sizeBytes),
                style = ChatVisualTokens.SystemActionStyle,
                color = palette.textTertiary
            )
        }
    }
}

private fun formatDuration(ms: Int): String {
    val totalSeconds = (ms / 1000).coerceAtLeast(0)
    return "%d:%02d".format(totalSeconds / 60, totalSeconds % 60)
}

private fun formatSize(bytes: Long): String = when {
    bytes >= 1_048_576 -> "%.1f MB".format(bytes / 1_048_576f)
    bytes >= 1024 -> "%.1f KB".format(bytes / 1024f)
    else -> "$bytes B"
}

package com.bitchat.watch.ui.theme

import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color
import kotlin.math.abs

@Immutable
data class PeerColorStyle(
    val saturation: Float,
    val value: Float,
) {
    companion object {
        val Dark = PeerColorStyle(saturation = 0.55f, value = 0.82f)
    }
}

fun colorForPeer(stableKey: String, palette: BitchatPalette): Color {
    var hash = 5381UL
    for (byte in stableKey.toByteArray()) {
        hash = ((hash shl 5) + hash) + byte.toUByte().toULong()
    }

    var hue = (hash % 360UL).toDouble() / 360.0
    val orange = 30.0 / 360.0
    if (abs(hue - orange) < 0.05) {
        hue = (hue + 0.12) % 1.0
    }

    val style = palette.peerColors
    return Color.hsv(
        hue = (hue * 360).toFloat(),
        saturation = style.saturation,
        value = style.value
    )
}

package com.bitchat.watch.notification

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class WearNotificationPolicyTest {

    @Test
    fun `system private messages never notify`() {
        assertFalse(
            WearNotificationPolicy.shouldNotifyPrivateMessage(
                senderPeerID = "peer-a",
                senderIsSystem = true,
                appInForeground = false,
                openDmPeer = null
            )
        )
    }

    @Test
    fun `visible matching dm suppresses notification`() {
        assertFalse(
            WearNotificationPolicy.shouldNotifyPrivateMessage(
                senderPeerID = "peer-a",
                senderIsSystem = false,
                appInForeground = true,
                openDmPeer = "peer-a"
            )
        )
    }

    @Test
    fun `backgrounded matching dm still notifies`() {
        assertTrue(
            WearNotificationPolicy.shouldNotifyPrivateMessage(
                senderPeerID = "peer-a",
                senderIsSystem = false,
                appInForeground = false,
                openDmPeer = "peer-a"
            )
        )
    }

    @Test
    fun `different visible dm still notifies`() {
        assertTrue(
            WearNotificationPolicy.shouldNotifyPrivateMessage(
                senderPeerID = "peer-a",
                senderIsSystem = false,
                appInForeground = true,
                openDmPeer = "peer-b"
            )
        )
    }

    @Test
    fun `peer count is distinct`() {
        assertEquals(2, WearNotificationPolicy.activePeerCount(listOf("peer-a", "peer-a", "peer-b")))
    }
}

package com.bitchat.watch.ui

import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Test

class ChatAutoScrollTest {

    @Test
    fun `newest scroll waits until appended message is measured`() = runTest {
        val measuredLayouts = MutableStateFlow(MeasuredChatLayout(3, null))
        var scrollCount = 0

        val scrollJob = launch(start = CoroutineStart.UNDISPATCHED) {
            scrollToNewestAfterItemsMeasured(
                expectedItemCount = 4,
                expectedSingleMessageKey = null,
                measuredLayouts = measuredLayouts
            ) {
                scrollCount += 1
            }
        }

        assertFalse(scrollJob.isCompleted)
        assertEquals(0, scrollCount)

        measuredLayouts.value = MeasuredChatLayout(4, null)
        scrollJob.join()

        assertEquals(1, scrollCount)
    }

    @Test
    fun `newest scroll runs immediately when messages are already measured`() = runTest {
        val measuredLayouts = MutableStateFlow(MeasuredChatLayout(4, null))
        var scrollCount = 0

        scrollToNewestAfterItemsMeasured(
            expectedItemCount = 4,
            expectedSingleMessageKey = null,
            measuredLayouts = measuredLayouts
        ) {
            scrollCount += 1
        }

        assertEquals(1, scrollCount)
    }

    @Test
    fun `first message waits past stale empty placeholder layout`() = runTest {
        val messageKey = "first-message"
        val measuredLayouts = MutableStateFlow(
            MeasuredChatLayout(itemCount = 1, singleVisibleItemKey = "empty-placeholder")
        )
        var scrollCount = 0

        val scrollJob = launch(start = CoroutineStart.UNDISPATCHED) {
            scrollToNewestAfterItemsMeasured(
                expectedItemCount = 1,
                expectedSingleMessageKey = messageKey,
                measuredLayouts = measuredLayouts
            ) {
                scrollCount += 1
            }
        }

        assertFalse(scrollJob.isCompleted)
        assertEquals(0, scrollCount)

        measuredLayouts.value = MeasuredChatLayout(
            itemCount = 1,
            singleVisibleItemKey = messageKey
        )
        scrollJob.join()

        assertEquals(1, scrollCount)
    }
}

package com.bitchat.watch.ui

import org.junit.Assert.assertEquals
import org.junit.Test

class WearPeerIdentityStateTest {

    @Test
    fun `favorite indicator matches Android three-state star`() {
        assertEquals(
            FavoriteIndicator.None,
            favoriteIndicator(isFavorite = false, theyFavoritedUs = false)
        )
        assertEquals(
            FavoriteIndicator.FavoritedUs,
            favoriteIndicator(isFavorite = false, theyFavoritedUs = true)
        )
        assertEquals(
            FavoriteIndicator.Favorite,
            favoriteIndicator(isFavorite = true, theyFavoritedUs = false)
        )
        assertEquals(
            FavoriteIndicator.Favorite,
            favoriteIndicator(isFavorite = true, theyFavoritedUs = true)
        )
    }

    @Test
    fun `verification code keeps every fingerprint character`() {
        val fingerprint = (0 until 64).joinToString("") { (it % 16).toString(16) }

        val formatted = formatVerificationCode(fingerprint)

        assertEquals(fingerprint.uppercase(), formatted.filterNot(Char::isWhitespace))
        assertEquals(4, formatted.lines().size)
        assertEquals(listOf(4, 4, 4, 4), formatted.lines().map { it.split(" ").size })
    }
}
